:is(#vv-agentes,#automacoes-root) button.v2g-pill:focus-visible{outline:2px solid #C2490C;outline-offset:2px}
:is(#vv-agentes,#automacoes-root) .v2g-pill.r{background:#FDECEE;color:#B42318}
:is(#vv-agentes,#automacoes-root) .v2g-pill.a{background:#FFF4D6;color:#7A4A00}
:is(#vv-agentes,#automacoes-root) .v2g-pill.g{background:#E8F5EC;color:#11613A}
:is(#vv-agentes,#automacoes-root) .v2g-pill.b{background:#E7EEFB;color:#1E4A9A}
:is(#vv-agentes,#automacoes-root) .v2g-pill.v{background:#EEEAFB;color:#4B36A8}
:is(#vv-agentes,#automacoes-root) .v2g-pill.n{background:#EFEBE4;color:#4A463F}
:is(#vv-agentes,#automacoes-root) .v2g-fala{display:flex;align-items:center;gap:14px}
:is(#vv-agentes,#automacoes-root) .v2g-fala > p{flex:1;min-width:0;margin:0;font:400 var(--d3-fs-destaque)/1.45 var(--vv-texto,Inter),sans-serif;color:#1F1D1A}
:is(#vv-agentes,#automacoes-root) .v2g-fala b{font-weight:700}
:is(#vv-agentes,#automacoes-root) .v2g-quem{display:block;margin-bottom:2px;font:600 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;color:#4B36A8}
:is(#vv-agentes,#automacoes-root) .v2g-ag{flex:none;position:relative;display:grid;place-items:center;width:40px;height:40px;border-radius:50%;background:#6E56CF;color:#FFFFFF;font:700 var(--d3-fs-destaque) var(--vv-texto,Inter),sans-serif}
:is(#vv-agentes,#automacoes-root) .v2g-ag::after{content:"";position:absolute;inset:-5px;border-radius:50%;border:2px solid #6E56CF;opacity:0;animation:v2g-pulso 3.6s ease-out infinite}
@keyframes v2g-pulso{0%{opacity:.5;transform:scale(.85)}70%,100%{opacity:0;transform:scale(1.25)}}
:is(#vv-agentes,#automacoes-root) .v2g-av{flex:none;display:inline-grid;place-items:center;width:28px;height:28px;border-radius:50%;background:#EFEBE4;color:#4A463F;font:700 var(--d3-fs-mini) var(--vv-texto,Inter),sans-serif;box-shadow:0 0 0 2px #FFFFFF}
:is(#vv-agentes,#automacoes-root) .v2g-av.lil{background:#EEEAFB;color:#4B36A8}
:is(#vv-agentes,#automacoes-root) .v2g-kpi > small{display:block;font:400 var(--d3-fs-texto)/1.35 var(--vv-texto,Inter),sans-serif;color:#6B665E}
:is(#vv-agentes,#automacoes-root) .v2g-kpi b{display:block;margin:6px 0;font:700 34px/1.05 var(--vv-titulo,"Inter Tight"),Inter,sans-serif;letter-spacing:-.02em;color:#1F1D1A;font-variant-numeric:tabular-nums}
:is(#vv-agentes,#automacoes-root) .v2g-kpi b > i{font:600 var(--d3-fs-destaque) var(--vv-texto,Inter),sans-serif;font-style:normal;letter-spacing:0;color:#6B665E}
:is(#vv-agentes,#automacoes-root) .v2g-kpi.ruim b{color:#B42318}
:is(#vv-agentes,#automacoes-root) .v2g-lin{display:flex;align-items:center;gap:12px;min-width:0;padding:12px 0;border-top:1px solid #F1EDE6;font:400 var(--d3-fs-texto)/1.4 var(--vv-texto,Inter),sans-serif;color:#1F1D1A}
:is(#vv-agentes,#automacoes-root) .v2g-cab + .v2g-lin{border-top:0}
