  body.mundo #workspace-drawer.gv2-gaveta.gv2-folha:not(.gv2-folha-inteira){top:auto;right:0;bottom:0;left:0;width:100%;height:auto;max-height:calc(100dvh - 32px);padding:0;border-radius:28px 28px 0 0;box-shadow:0 -12px 30px -12px rgba(31,29,26,.4);animation:gv2-folha-sobe .36s cubic-bezier(.2,.8,.2,1) both}
