/* ===== 2. AS TELAS DA RODADA 1 NO CELULAR ===== */
@media (max-width:600px){
  /* toque de 44 px (quadro: busca, botões e fichas com 44 de altura no celular). Só a altura e a largura mínimas mudam;
     o desenho de cada grupo continua o do fragmento dele. As abas em segmento ficam em 36, como no quadro. */
  body.mundo :is(#mundo-hud,#vv-conteudo,#vv-comercial,#vv-pessoas,#vv-carteira,#office-catalogo,#workflow-modal,#automacoes-root,#vv-planejamentos,#vv-whatsapp,#vv-reunioes,#vv-ferramentas,.pv2-casa) :is(button,summary,a)[class*="-chip"][class*="-chip"],
  body.mundo :is(#mundo-hud,#vv-conteudo,#vv-comercial,#vv-pessoas,#vv-carteira,#office-catalogo,#workflow-modal,#automacoes-root,#vv-planejamentos,#vv-whatsapp,#vv-reunioes,#vv-ferramentas,.pv2-casa) :is(button,summary,a)[class*="-btn"][class*="-btn"]:not(.vv-trilho-btn){min-height:44px;min-width:44px;box-sizing:border-box}
  body.mundo :is(#mundo-hud,#vv-conteudo,#vv-comercial,#vv-pessoas,#vv-carteira,#office-catalogo,#workflow-modal,#automacoes-root,#vv-planejamentos,#vv-whatsapp,#vv-reunioes,#vv-ferramentas,.pv2-casa) input[class*="busca"][class*="busca"]{min-height:44px;box-sizing:border-box}
  /* fechar e ícones soltos: 44 × 44 */
  body.mundo :is(#mundo-hud,#vv-conteudo,#vv-comercial,#vv-pessoas,#vv-carteira,#office-catalogo,#workflow-modal,#vv-wa-avisos,#vv-ferramentas,#vv-impressoes,#vv-reunioes) :is(.v2c-x,.v2l-x,.v2r-x,.vp-x,.vb-janela-x,.v2c-fechar,.vv-aviso-curto-x):is(button,a,summary){width:44px;height:44px;min-width:44px;min-height:44px;box-sizing:border-box}
  /* o topo do celular (busca, avisos, mais, conta): 44 de altura como no quadro; a busca encolhe para caber */
  body.mundo #mundo-hud :is(button,summary).vv-botao.vv-botao{min-height:44px;min-width:44px;height:44px;box-sizing:border-box}
  body.mundo #mundo-hud :is(button,summary).vv-botao.vv-busca-larga{min-width:0}
  body.mundo #mundo-hud .vv-barra-topo .vv-ferramentas > .vv-botao.vv-botao:not(.vv-busca-larga){width:44px;min-width:44px;height:44px}
  /* os dois botões do canto da janela (tela cheia e fechar) e o fechar da janela de Pessoas */
  body.mundo .vv-canto-modulo .vv-botao.vv-botao{width:44px;height:44px;min-width:44px;min-height:44px}
  body.mundo #vv-pessoas.v2p-janela .vp-topo-botoes > .vp-x.vb-janela-x{width:44px;min-width:44px;height:44px;min-height:44px}
  /* abas em segmento: 36 de altura, como no quadro do celular (a família das abas desenha em 30) */
  body.mundo :is(#mundo-hud,#vv-conteudo,#vv-comercial,#vv-pessoas,#vv-carteira,#office-catalogo,#workflow-modal,.pv2-casa) .vb-abas:not(#vb-a):not(#vb-b) [role="tab"]{height:36px}
  /* VYBES no Hoje: as abas e as tarefas do painel */
  body.mundo #vv-hoje :is(.v2vb-aba,.v2vb-tar){min-height:44px;box-sizing:border-box}

  /* janelas que passavam por cima da barra de baixo: terminam acima dela */
  /* a barra ocupa 56 px + 8 de margem embaixo; a janela começa a 12 do topo e para 8 acima da barra (12 + 64 + 8 = 84) */
  body.mundo #office-catalogo.v2l-janela[open]{height:calc(100dvh - 84px - env(safe-area-inset-bottom));max-height:calc(100dvh - 84px - env(safe-area-inset-bottom));margin:12px auto auto}
  body.mundo #workflow-modal.rk2-janela{top:calc(12px + (100dvh - 84px - env(safe-area-inset-bottom)) / 2);height:calc(100dvh - 84px - env(safe-area-inset-bottom));max-height:calc(100dvh - 84px - env(safe-area-inset-bottom))}
}
