#vv-carteira .v2c-etapa select{border-radius:999px;padding-left:14px}
#vv-carteira .v2c-atalhos{display:flex;flex-wrap:wrap;align-items:center;gap:8px}
#vv-carteira .v2c-rodape{display:flex;flex-wrap:wrap;align-items:center;gap:12px}
#vv-carteira .v2c-rodape > p{flex:1 1 320px}
#vv-carteira .v2c-rodape b{color:#1F1D1A}
#vv-carteira .v2c-rodape .vc-ativacao-tec{display:block;margin-top:4px}
@media (prefers-reduced-motion:reduce){
  #vv-carteira .v2c-ag::after,#vv-carteira .v2c-perde > i{animation:none}
