#vv-comercial.v2c .v2c-btn.k[data-estado="indo"]::after{border-color:rgba(255,255,255,.4);border-top-color:#FFFFFF}
#vv-comercial.v2c .v2c-btn[data-estado="feito"]{pointer-events:none;background:#11613A;color:#FFFFFF;box-shadow:none}
#vv-comercial.v2c .v2c-seg{flex:none;display:inline-flex;padding:4px;border-radius:999px;background:#EAE6DE}
#vv-comercial.v2c .v2c-seg button{appearance:none;height:30px;padding:0 14px;border:0;border-radius:999px;background:none;color:#6B665E;font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);cursor:pointer}
#vv-comercial.v2c .v2c-seg button[aria-pressed="true"]{background:#FFFFFF;color:#1F1D1A;box-shadow:0 1px 3px rgba(31,29,26,.18)}
#vv-comercial.v2c .v2c-chips{display:flex;flex-wrap:wrap;gap:8px}
#vv-comercial.v2c .v2c-chip{appearance:none;flex:none;display:inline-flex;align-items:center;gap:6px;height:30px;padding:0 12px;border:0;border-radius:999px;background:#FFFFFF;box-shadow:inset 0 0 0 1px #E6E0D6;color:#1F1D1A;font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);white-space:nowrap;cursor:pointer}
#vv-comercial.v2c .v2c-chip[aria-pressed="true"]{background:#1F1D1A;color:#FFFFFF;box-shadow:none}
#vv-comercial.v2c .v2c-pill{flex:none;display:inline-flex;align-items:center;height:22px;padding:0 9px;border-radius:999px;font:600 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);white-space:nowrap}
#vv-comercial.v2c .v2c-pill.r{background:#FDECEE;color:#B42318}
#vv-comercial.v2c .v2c-pill.a{background:#FFF4D6;color:#7A4A00}
#vv-comercial.v2c .v2c-pill.g{background:#E8F5EC;color:#11613A}
#vv-comercial.v2c .v2c-pill.b{background:#E7EEFB;color:#1E4A9A}
#vv-comercial.v2c .v2c-pill.n{background:#EFEBE4;color:#4A463F}
#vv-comercial.v2c .v2c-sub{font:400 var(--d3-fs-texto)/1.35 var(--vv-texto,Inter,sans-serif);color:#6B665E}
#vv-comercial.v2c .v2c-link{appearance:none;display:inline;padding:0;border:0;background:none;color:#C2490C;font:inherit;text-decoration:underline;cursor:pointer}
#vv-comercial.v2c .v2c-link:hover{color:#8A3207}
#vv-comercial.v2c .v2c-bom{color:#11613A;font-weight:600}
#vv-comercial.v2c .v2c-cli{display:inline-flex;align-items:center;gap:6px;font-weight:600}
#vv-comercial.v2c .v2c-cli .cliente-carteira{display:inline-flex;align-items:center;gap:6px;padding:0;border:0;border-radius:0;background:none;color:inherit;font:inherit;font-weight:600}
#vv-comercial.v2c .v2c-cli .cliente-carteira::before{content:"";flex:none;width:8px;height:8px;border-radius:50%;background:var(--carteira-texto,#C2490C)}

/* cartão, fala, três números */
#vv-comercial.v2c .v2c-card{box-sizing:border-box;min-width:0;padding:18px;border-radius:20px;background:#FFFFFF;box-shadow:0 1px 2px rgba(31,29,26,.05),0 12px 24px -18px rgba(31,29,26,.22)}
#vv-comercial.v2c .v2c-fala{display:flex;align-items:center;gap:14px}
#vv-comercial.v2c .v2c-fala > p{flex:1;min-width:0;font-size:var(--d3-fs-destaque);line-height:1.45}
#vv-comercial.v2c .v2c-fala b{font-weight:700}
#vv-comercial.v2c .v2c-ag{flex:none;position:relative;display:grid;place-items:center;width:40px;height:40px;border-radius:50%;background:#6E56CF;color:#FFFFFF;font:700 var(--d3-fs-destaque) var(--vv-texto,Inter,sans-serif)}
#vv-comercial.v2c .v2c-ag::after{content:"";position:absolute;inset:-5px;border-radius:50%;border:2px solid #6E56CF;opacity:0;animation:v2c-pulso 3.6s ease-out infinite}
@keyframes v2c-pulso{0%{opacity:.5;transform:scale(.85)}70%,100%{opacity:0;transform:scale(1.25)}}
#vv-comercial.v2c .v2c-quem{display:block;margin-bottom:2px;font:600 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:#4B36A8}
#vv-comercial.v2c .v2c-tres{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}
#vv-comercial.v2c .v2c-kpi > small{display:block;font-size:var(--d3-fs-texto);color:#6B665E}
#vv-comercial.v2c .v2c-kpi > b{display:block;margin:6px 0;font:700 34px/1.05 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.02em;font-variant-numeric:tabular-nums;overflow-wrap:break-word}
#vv-comercial.v2c .v2c-kpi.longo > b{font-size:26px;line-height:1.15}
#vv-comercial.v2c .v2c-kpi.ruim > b{color:#B42318}
#vv-comercial.v2c .v2c-kpi.quieto > b{color:#B5AFA5}
#vv-comercial.v2c .v2c-kpi .v2-barra{background:#EAE6DE}
#vv-comercial.v2c .v2-barra.ja > i{animation:none}

/* funil: faixa das etapas, colunas e o cartão que abre */
#vv-comercial.v2c .v2c-etapas{display:flex;gap:8px;align-items:stretch}
#vv-comercial.v2c .v2c-et{appearance:none;flex:1 1 0;min-width:0;box-sizing:border-box;margin:0;padding:9px 12px;border:1.5px solid transparent;border-radius:16px;background:#FFFFFF;box-shadow:0 1px 2px rgba(31,29,26,.05),0 10px 20px -18px rgba(31,29,26,.22);color:#1F1D1A;font:inherit;text-align:left;cursor:pointer}
#vv-comercial.v2c .v2c-et > b{display:block;font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#vv-comercial.v2c .v2c-et > span{font:700 20px/1.2 var(--vv-titulo,"Inter Tight",Inter,sans-serif)}
#vv-comercial.v2c .v2c-et > em{margin-left:6px;font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);font-style:normal;color:#4A463F;white-space:nowrap}
#vv-comercial.v2c .v2c-et > small{display:block;font-size:var(--d3-fs-apoio);color:#6B665E;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#vv-comercial.v2c .v2c-et.z{background:transparent;border-color:#D9D1C3;border-style:dashed;box-shadow:none}
#vv-comercial.v2c .v2c-et.z > span{color:#6B665E}
#vv-comercial.v2c .v2c-et.at{background:#FFF1E6}
#vv-comercial.v2c .v2c-et.at > b{color:#8A3207}
#vv-comercial.v2c .v2c-et.ganho > b{color:#11613A}
#vv-comercial.v2c .v2c-et[aria-pressed="true"]{border-color:#1F1D1A;border-style:solid}
#vv-comercial.v2c .v2c-quadro{display:grid;grid-template-columns:repeat(var(--n,4),minmax(0,1fr));gap:14px;align-items:start}
#vv-comercial.v2c .v2c-colu{display:flex;flex-direction:column;gap:8px;min-width:0}
#vv-comercial.v2c .v2c-colu > h3,#vv-comercial.v2c .v2c-card-topo h3{font:600 var(--d3-fs-destaque)/1.2 var(--vv-titulo,"Inter Tight",Inter,sans-serif);color:#1F1D1A}
#vv-comercial.v2c .v2c-colu-ops{display:flex;flex-direction:column;gap:8px;min-width:0}
#vv-comercial.v2c .v2c-quadro.foco{grid-template-columns:minmax(0,1fr)}
#vv-comercial.v2c .v2c-quadro.foco .v2c-colu-ops{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px 14px;align-items:start}
#vv-comercial.v2c .v2c-op{min-width:0;padding:0 14px;border-radius:16px;background:#FFFFFF;box-shadow:0 1px 2px rgba(31,29,26,.05),0 10px 20px -18px rgba(31,29,26,.22)}
#vv-comercial.v2c .v2c-op[draggable="true"]{cursor:grab}
#vv-comercial.v2c .v2c-op-lin{appearance:none;display:block;width:100%;margin:0;padding:12px 0;border:0;background:none;color:inherit;font:400 var(--d3-fs-texto)/1.35 var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
#vv-comercial.v2c .v2c-t{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:4px 8px;font-weight:600}
#vv-comercial.v2c .v2c-t > span:first-child{flex:0 1 auto;max-width:100%;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#vv-comercial.v2c .v2c-op-lin > .v2c-sub{display:block}
#vv-comercial.v2c .v2c-pas{padding:0 0 6px;font-size:var(--d3-fs-texto);color:#4A463F;overflow-wrap:anywhere}
#vv-comercial.v2c .v2c-acoes{display:flex;flex-wrap:wrap;gap:8px;padding:0 0 12px}
#vv-comercial.v2c .v2c-acoes.recuo{padding-left:14px}
#vv-comercial.v2c .v2-abre[aria-expanded="false"] > .v2-mais{visibility:hidden;transition:grid-template-rows .28s var(--vv-suave,cubic-bezier(.22,1,.36,1)),visibility 0s .28s}
#vv-comercial.v2c .v2c-lista > .v2c-op{padding:0;border-radius:0;box-shadow:none;border-top:1px solid #F1EDE6}
#vv-comercial.v2c .v2c-lista > .v2c-card-topo + .v2c-op{border-top:0}

/* barra de filtro, "Pede ação" e a lista */
#vv-comercial.v2c .v2c-filtro{display:flex;flex-wrap:wrap;align-items:center;gap:8px}
#vv-comercial.v2c .v2c-busca{flex:1 1 160px;min-width:140px;height:36px;box-sizing:border-box;margin:0;padding:0 16px;border:0;border-radius:999px;background:#FFFFFF;box-shadow:inset 0 0 0 1px #E6E0D6;color:#1F1D1A;font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif)}
#vv-comercial.v2c .v2c-extras{flex:1 1 100%;justify-content:flex-end}
#vv-comercial.v2c .v2c-grade{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.3fr);gap:14px}
#vv-comercial.v2c .v2c-grade.pacotes{grid-template-columns:minmax(0,1fr) minmax(0,1.4fr)}
#vv-comercial.v2c .v2c-grade > .v2c-card{display:flex;flex-direction:column;min-height:300px}
#vv-comercial.v2c .v2c-card-topo{display:flex;flex-wrap:wrap;align-items:baseline;gap:2px 8px;margin-bottom:2px}
#vv-comercial.v2c .v2c-card-topo h3{flex:1 0 auto;min-width:0}
#vv-comercial.v2c .v2c-card-topo small{font-size:var(--d3-fs-texto);color:#6B665E}
#vv-comercial.v2c .v2c-card-pe{margin-top:auto;padding-top:8px}
#vv-comercial.v2c .v2c-nada{padding:12px 0}
#vv-comercial.v2c .v2c-lin{display:flex;align-items:center;gap:12px;padding:12px 0;border-top:1px solid #F1EDE6;font-size:var(--d3-fs-texto)}
#vv-comercial.v2c .v2c-card-topo + .v2c-lin,#vv-comercial.v2c .v2c-card-topo + .v2c-abre > .v2c-lin{border-top:0}
#vv-comercial.v2c .v2c-lin-txt{flex:1;min-width:0;overflow-wrap:anywhere}
#vv-comercial.v2c .v2c-lin-txt > p{margin-top:4px;overflow-wrap:anywhere}
#vv-comercial.v2c button.v2c-lin{appearance:none;width:100%;margin:0;border-width:1px 0 0;border-style:solid;border-color:#F1EDE6;border-radius:0;background:none;color:inherit;font:400 var(--d3-fs-texto)/1.35 var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
#vv-comercial.v2c .v2c-card-topo + .v2c-abre > button.v2c-lin{border-top-color:transparent}
#vv-comercial.v2c .v2c-abre.apagado > .v2c-lin{color:#6B665E}
#vv-comercial.v2c .v2c-pk{display:grid;grid-template-columns:minmax(0,1fr) 124px 190px;gap:0 12px}
#vv-comercial.v2c .v2c-pk.sem-margem{grid-template-columns:minmax(0,1fr) 124px}
#vv-comercial.v2c :is(.v2c-pk-n,.v2c-orc-n){display:flex;flex-direction:column;align-items:flex-start;min-width:0}
#vv-comercial.v2c :is(.v2c-pk-n,.v2c-orc-n) > .v2c-sub{max-width:100%;overflow-wrap:anywhere}
#vv-comercial.v2c .v2c-pk-n > b{font-weight:700}
#vv-comercial.v2c .v2c-pk-p{display:flex;flex-direction:column;align-items:flex-end;font-weight:600;white-space:nowrap}
#vv-comercial.v2c .v2c-pk-m{display:flex;flex-direction:column;gap:6px;min-width:0}
#vv-comercial.v2c .v2c-pk-m .v2-barra{display:block;background:#EAE6DE}
#vv-comercial.v2c .v2c-orc-n{flex:1}
#vv-comercial.v2c .v2c-orc > b{flex:none;font-weight:700;white-space:nowrap}
#vv-comercial.v2c .v2c-hist{display:flex;align-items:center;gap:8px;padding:0 0 10px 14px;font-size:var(--d3-fs-texto);color:#4A463F;overflow-wrap:anywhere}
#vv-comercial.v2c .v2c-hist::before{content:"";flex:none;width:6px;height:6px;border-radius:50%;background:#C9C2B6}

/* vazio numa linha, rodapé e o que fica a um clique */
#vv-comercial.v2c .v2c-vz{display:flex;flex-wrap:wrap;align-items:center;gap:10px;padding:7px 8px 7px 18px;border:1.5px dashed #D9D1C3;border-radius:999px;font-size:var(--d3-fs-texto);color:#4A463F}
#vv-comercial.v2c .v2c-vz > p{flex:1 1 240px;min-width:0}
#vv-comercial.v2c .v2c-vz b{color:#1F1D1A}
#vv-comercial.v2c .v2c-tec{padding:0 18px}
#vv-comercial.v2c .v2c-resto{padding:18px;border-radius:20px;background:#FFFFFF;box-shadow:0 1px 2px rgba(31,29,26,.05),0 12px 24px -18px rgba(31,29,26,.22)}
#vv-comercial.v2c :is(.v2c-btn,.v2c-chip,.v2c-et,.v2c-link,.v2c-fechar,.v2c-op-lin,.v2c-lin,.v2c-busca,.v2c-seg button):focus-visible{outline:2px solid var(--ds-acao,#C2490C);outline-offset:2px}
@media (prefers-reduced-motion:reduce){
  #vv-comercial.v2c .v2c-ag::after{animation:none}
  #vv-comercial.v2c .v2c-btn,#vv-comercial.v2c .v2-abre[aria-expanded="false"] > .v2-mais{transition:none}
}
@container v2c (max-width:900px){
  #vv-comercial.v2c .v2c-grade,#vv-comercial.v2c .v2c-grade.pacotes{grid-template-columns:minmax(0,1fr)}
  #vv-comercial.v2c .v2c-grade > .v2c-card{min-height:0}
  #vv-comercial.v2c .v2c-etapas{flex-wrap:wrap}
  #vv-comercial.v2c .v2c-et{flex:1 1 120px}
  #vv-comercial.v2c .v2c-quadro,#vv-comercial.v2c .v2c-quadro.foco .v2c-colu-ops{grid-template-columns:repeat(2,minmax(0,1fr))}
}
@container v2c (max-width:560px){
  #vv-comercial.v2c .v2c-tres{grid-template-columns:minmax(0,1fr);gap:8px}
  #vv-comercial.v2c .v2c-card{padding:14px}
  #vv-comercial.v2c .v2c-kpi > b,#vv-comercial.v2c .v2c-kpi.longo > b{margin:4px 0;font-size:26px}
  #vv-comercial.v2c .v2c-fala{flex-wrap:wrap}
  #vv-comercial.v2c .v2c-fala > p{flex:1 1 200px}
  #vv-comercial.v2c .v2c-quadro,#vv-comercial.v2c .v2c-quadro.foco .v2c-colu-ops{grid-template-columns:minmax(0,1fr)}
  #vv-comercial.v2c .v2c-pk,#vv-comercial.v2c .v2c-pk.sem-margem{grid-template-columns:minmax(0,1fr) auto}
  #vv-comercial.v2c .v2c-pk-m{grid-column:1 / -1;margin-top:8px}
  #vv-comercial.v2c .v2c-orc{flex-wrap:wrap;gap:6px 12px}
  #vv-comercial.v2c .v2c-orc-n{flex:1 1 100%}
  #vv-comercial.v2c .v2c-lin:not(button){flex-wrap:wrap}
  #vv-comercial.v2c .v2c-vz{border-radius:20px;padding:12px 14px}
}
@media (max-width:640px){
  #vv-comercial.v2c .v2c-topo{padding:calc(16px + env(safe-area-inset-top)) 16px 0;gap:8px}
  #vv-comercial.v2c .v2c-topo h2{flex-basis:100%;font-size:24px}
  #vv-comercial.v2c .v2c-topo .v2c-fechar{margin-left:auto}
  #vv-comercial.v2c .v2c-corpo{padding:14px 16px 24px}
  #vv-comercial.v2c :is(.vc-ajuda,.vc-msg-geral){margin:14px 16px 0}
  #vv-comercial.v2c .vc-abas{padding:10px 16px 0}
}
/* Finanças por cliente, Fornecedores e Creators (quadros DEPOIS PorCliente, Fornecedores e Creators) */
#vv-comercial.v2c .v2c-titulo{flex:1 1 200px;min-width:0}
#vv-comercial.v2c .v2c-titulo > h2{flex:none}
#vv-comercial.v2c .v2c-mes{flex:none;display:inline-flex;align-items:center}
#vv-comercial.v2c .v2c-kpi.bom > b{color:#11613A}
#vv-comercial.v2c .v2c-kpi.atencao > b{color:#7A4A00}
#vv-comercial.v2c .v2c-kpi .v2-barra + small{margin-top:8px}
#vv-comercial.v2c .v2c-ruim{color:#B42318;font-weight:700}
#vv-comercial.v2c .v2c-atencao{color:#7A4A00;font-weight:600}
#vv-comercial.v2c .v2c-tb{display:grid;grid-template-columns:minmax(0,1fr) 76px 112px 150px 98px;align-items:center;gap:10px}
#vv-comercial.v2c .v2c-tb.com-custo{grid-template-columns:minmax(0,1fr) 76px 76px 112px 150px 98px}
#vv-comercial.v2c .v2c-tb-cab{padding:6px 0 2px;font:600 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:#6B665E}
#vv-comercial.v2c .v2c-tb-cab + .v2c-abre > .v2c-lin{border-top:0}
#vv-comercial.v2c .v2c-num{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}
#vv-comercial.v2c .v2c-mg{display:flex;align-items:center;gap:8px}
#vv-comercial.v2c .v2c-mg .v2-barra{flex:1;background:#EAE6DE}
#vv-comercial.v2c .v2c-nome{appearance:none;display:flex;min-width:0;margin:0;padding:0;border:0;background:none;color:inherit;font:inherit;text-align:left;cursor:pointer}
#vv-comercial.v2c .v2c-nome .v2c-cli,#vv-comercial.v2c .v2c-nome .cliente-carteira{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#vv-comercial.v2c .v2c-tb > .v2c-btn{justify-self:end}
#vv-comercial.v2c .v2c-det{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;padding:0 0 12px;font-size:var(--d3-fs-texto);color:#4A463F}
#vv-comercial.v2c .v2c-det b{display:block;font-size:var(--d3-fs-apoio);font-weight:600;color:#6B665E}
#vv-comercial.v2c .v2c-pede .v2c-lin{align-items:flex-start}
#vv-comercial.v2c .v2c-fr{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(0,1.1fr) 96px 132px 156px;align-items:center;gap:14px;padding:10px 0}
#vv-comercial.v2c .v2c-fr > *{min-width:0;overflow-wrap:anywhere}
#vv-comercial.v2c .v2c-seg2{font-size:var(--d3-fs-apoio);font-weight:400;color:#6B665E}
#vv-comercial.v2c .v2c-fr-acao{text-align:right}
#vv-comercial.v2c .v2c-dt{display:flex;flex-direction:column;gap:6px;margin:0 0 12px 3px;padding:2px 0 2px 14px;border-left:2px solid #EAE6DE;font-size:var(--d3-fs-texto);color:#4A463F}
#vv-comercial.v2c .v2c-dt b{color:#1F1D1A}
#vv-comercial.v2c .v2c-dt .v2c-acoes{padding:2px 0 0}
#vv-comercial.v2c .v2c-campo{display:flex;flex-wrap:wrap;align-items:center;gap:8px;font-size:var(--d3-fs-texto);color:#4A463F}
#vv-comercial.v2c .v2c-campo.solto{padding:0 0 12px}
#vv-comercial.v2c .v2c-campo .v2c-busca{flex:none;min-width:0;height:30px}
#vv-comercial.v2c .v2c-busca.curto{width:84px}
#vv-comercial.v2c .v2c-busca.medio{width:220px}
#vv-comercial.v2c .v2c-busca.largo{width:260px}
#vv-comercial.v2c .v2c-forn > .v2c-filtro{margin-top:12px}
#vv-comercial.v2c .v2c-forn > .v2c-filtro:first-child{margin-top:0}
#vv-comercial.v2c .v2c-forn > .v2c-filtro + .v2c-abre > .v2c-lin{border-top:0}
#vv-comercial.v2c .v2c-forn > .v2c-card-pe{margin-top:0;border-top:1px solid #F1EDE6}
#vv-comercial.v2c .v2c-pessoas{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;align-items:start}
#vv-comercial.v2c .v2c-pes{display:flex;flex-direction:column;gap:6px;padding:14px 16px}
#vv-comercial.v2c .v2c-pes > p{font-size:var(--d3-fs-texto);overflow-wrap:anywhere}
#vv-comercial.v2c .v2c-pes-topo{appearance:none;display:flex;align-items:center;gap:10px;width:100%;min-width:0;margin:0;padding:0;border:0;background:none;color:inherit;font:inherit;text-align:left;cursor:pointer}
#vv-comercial.v2c .v2c-pes-topo > span:last-child{min-width:0}
#vv-comercial.v2c .v2c-pes-topo b{display:block;font-size:var(--d3-fs-texto);font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#vv-comercial.v2c .v2c-pes-topo small{display:block;font-size:var(--d3-fs-apoio);color:#6B665E;overflow-wrap:anywhere}
#vv-comercial.v2c .v2c-av{flex:none;display:inline-grid;place-items:center;width:40px;height:40px;border-radius:50%;background:#EFEBE4;color:#4A463F;font:700 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);box-shadow:0 0 0 2px #FFFFFF}
#vv-comercial.v2c .v2c-pes .v2c-acoes{padding:6px 0 0}
#vv-comercial.v2c .v2c-ag{font-size:var(--d3-fs-texto)}
#vv-comercial.v2c :is(.v2c-nome,.v2c-pes-topo):focus-visible{outline:2px solid var(--ds-acao,#C2490C);outline-offset:2px}
@container v2c (max-width:900px){
  #vv-comercial.v2c .v2c-pessoas{grid-template-columns:repeat(2,minmax(0,1fr))}
  #vv-comercial.v2c .v2c-fr{grid-template-columns:minmax(0,1fr) minmax(0,1fr) auto}
  #vv-comercial.v2c .v2c-fr-acao{grid-column:1 / -1;text-align:left}
}
@container v2c (max-width:560px){
  #vv-comercial.v2c .v2c-pessoas{grid-template-columns:minmax(0,1fr)}
  #vv-comercial.v2c .v2c-fr{grid-template-columns:minmax(0,1fr);gap:6px}
  #vv-comercial.v2c .v2c-tb,#vv-comercial.v2c .v2c-tb.com-custo{grid-template-columns:minmax(0,1fr) auto;gap:6px 10px}
  #vv-comercial.v2c .v2c-tb-cab{display:none}
  #vv-comercial.v2c .v2c-det{grid-template-columns:minmax(0,1fr)}
  #vv-comercial.v2c .v2c-campo .v2c-busca{flex:1 1 140px;width:auto}
}

/* ===== padrao-v2/conteudo.css ===== */
/* PADRÃO V2 · CONTEÚDO (quadro "Aprovação de conteúdo" do moodboard, 12/11/2026). As medidas são as do quadro:
   janela #F9F8F5 com 26/30 de respiro, título 30, abas em pílula sobre #EAE6DE, cartão branco de raio 20, botão em
   pílula de 30 e 38, baralho de 350 por 452 com carta de raio 24, linha de 13,5 e pílula de 22. A tela é .v2c;
   as peças do baralho (.v2-baralho, .v2-carta, .v2-pontos, .v2-num) vêm do bloco PADRÃO V2 · BASE. */
#vv-conteudo.vc.vc{padding:26px 30px;gap:16px;border:0;background:#F9F8F5;color:#1F1D1A;font:400 var(--d3-fs-texto)/1.4 var(--vv-texto,"Inter",system-ui,sans-serif)}
#vv-conteudo.vc .vc-corpo{margin:0 -30px -26px;padding:0 30px 26px}
#vv-conteudo.vc :is(.vc-ajuda,.vc-aviso){margin:0}
#vv-conteudo.vc :is(.v2c-btn,.v2c-link,.v2c-seg button,.v2c-mes button,.v2c-lin,.v2c-eq-lin,.v2c-arte):focus-visible{outline:2px solid var(--ds-acao,#C2490C);outline-offset:2px;box-shadow:none}

/* topo: título, abas, mês, ajuda */
#vv-conteudo.vc .v2c-topo{flex:none;display:flex;flex-wrap:wrap;align-items:center;gap:12px}
#vv-conteudo.vc .v2c-topo h2{flex:1 1 auto;min-width:0;margin:0;font:700 var(--d3-fs-numero)/1.1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.01em;color:#1F1D1A}
#vv-conteudo.vc .v2c-seg{display:inline-flex;padding:4px;border-radius:999px;background:#EAE6DE}
#vv-conteudo.vc .v2c-seg button{appearance:none;display:inline-flex;align-items:center;justify-content:center;height:30px;padding:0 14px;border:0;border-radius:999px;background:none;color:#6B665E;font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);white-space:nowrap;cursor:pointer}
#vv-conteudo.vc .v2c-seg button:hover{color:#1F1D1A}
#vv-conteudo.vc .v2c-seg button[aria-selected="true"]{background:#FFFFFF;color:#1F1D1A;box-shadow:0 1px 3px rgba(31,29,26,.18)}
#vv-conteudo.vc .v2c-mes{display:inline-flex;align-items:center;height:30px;padding:0 4px;border-radius:999px;background:#FFFFFF;box-shadow:inset 0 0 0 1px #E6E0D6}
#vv-conteudo.vc .v2c-mes button{appearance:none;height:26px;min-width:24px;padding:0 6px;border:0;border-radius:999px;background:none;color:#1F1D1A;font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);white-space:nowrap;cursor:pointer}
#vv-conteudo.vc .v2c-mes button:hover{background:#F3F1EC}
#vv-conteudo.vc .v2c-btn{appearance:none;flex:none;display:inline-flex;align-items:center;justify-content:center;gap:6px;height:30px;min-height:0;padding:0 12px;border:0;border-radius:999px;background:#FFFFFF;box-shadow:inset 0 0 0 1px #E6E0D6;color:#1F1D1A;font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);white-space:nowrap;cursor:pointer;transition:transform .14s cubic-bezier(.34,1.56,.64,1)}
#vv-conteudo.vc .v2c-btn:hover{box-shadow:inset 0 0 0 1px #1F1D1A}
#vv-conteudo.vc .v2c-btn:active{transform:scale(.96)}
#vv-conteudo.vc .v2c-btn.g{height:38px;padding:0 16px;font-size:var(--d3-fs-texto)}
#vv-conteudo.vc .v2c-btn.k{background:#1F1D1A;color:#FFFFFF;box-shadow:none}
#vv-conteudo.vc .v2c-btn.k:hover{background:#000000}
#vv-conteudo.vc .v2c-btn[aria-expanded="true"]{background:#1F1D1A;color:#FFFFFF;box-shadow:none}
#vv-conteudo.vc .v2c-x{width:30px;padding:0}
#vv-conteudo.vc .v2c-x svg{width:14px;height:14px}

/* peças comuns: cartão, texto de apoio, cliente com o ponto da carteira, avatar, pílula, link */
#vv-conteudo.vc .v2c-card{box-sizing:border-box;border-radius:20px;padding:18px;background:#FFFFFF;box-shadow:0 1px 2px rgba(31,29,26,.05),0 12px 24px -18px rgba(31,29,26,.22)}
#vv-conteudo.vc .v2c-card-topo{display:flex;align-items:baseline;gap:8px;margin-bottom:2px}
#vv-conteudo.vc .v2c-card-topo h3{flex:1;min-width:0;margin:0;font:600 var(--d3-fs-destaque)/1.2 var(--vv-titulo,"Inter Tight",Inter,sans-serif);color:#1F1D1A}
#vv-conteudo.vc .v2c-sub{margin:0;font:400 var(--d3-fs-texto)/1.4 var(--vv-texto,Inter,sans-serif);color:#6B665E}
#vv-conteudo.vc .v2c-sub.ok{color:#11613A;font-weight:600}
#vv-conteudo.vc .v2c-cli{display:inline-flex;align-items:center;gap:6px;min-width:0;font-weight:600;color:#1F1D1A}
#vv-conteudo.vc .v2c-cli::before{content:"";flex:none;width:8px;height:8px;border-radius:50%;background:#8A847A}
#vv-conteudo.vc .v2c-cli[data-carteira="vinicius"]::before{background:#C2490C}
#vv-conteudo.vc .v2c-cli[data-carteira="ewerton"]::before{background:#3B5BA9}
#vv-conteudo.vc .v2c-av{display:inline-grid;place-items:center;flex:none;width:28px;height:28px;border-radius:50%;background:#EFEBE4;color:#4A463F;font:700 var(--d3-fs-mini) var(--vv-texto,Inter,sans-serif);box-shadow:0 0 0 2px #FFFFFF}
#vv-conteudo.vc .v2c-avs{display:inline-flex;flex:none;padding-left:8px}
#vv-conteudo.vc .v2c-avs .v2c-av{margin-left:-8px}
#vv-conteudo.vc .v2c-pill{display:inline-flex;align-items:center;flex:none;height:22px;padding:0 9px;border-radius:999px;background:#EFEBE4;color:#4A463F;font:600 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);white-space:nowrap}
#vv-conteudo.vc .v2c-pill.r{background:#FDECEE;color:#B42318}
#vv-conteudo.vc .v2c-pill.a{background:#FFF4D6;color:#7A4A00}
#vv-conteudo.vc .v2c-pill.g{background:#E8F5EC;color:#11613A}
#vv-conteudo.vc .v2c-pill.b{background:#E7EEFB;color:#1E4A9A}
#vv-conteudo.vc .v2c-link{appearance:none;display:inline;padding:0;border:0;background:none;color:#C2490C;font:inherit;font-weight:700;cursor:pointer}
#vv-conteudo.vc .v2c-link:hover{text-decoration:underline}

/* a fala do Augusto */
#vv-conteudo.vc .v2c-apr{display:flex;flex-direction:column;gap:16px;min-height:100%}
#vv-conteudo.vc .v2c-fala{flex:none;display:flex;align-items:center;gap:14px}
#vv-conteudo.vc .v2c-fala > p{flex:1;min-width:0;margin:0;font:400 var(--d3-fs-destaque)/1.45 var(--vv-texto,Inter,sans-serif);color:#1F1D1A}
#vv-conteudo.vc .v2c-fala b{font-weight:700}
#vv-conteudo.vc .v2c-quem{display:block;margin-bottom:2px;font:600 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:#4B36A8}
#vv-conteudo.vc .v2c-ag{position:relative;flex:none;display:grid;place-items:center;width:40px;height:40px;border-radius:50%;background:#6E56CF;color:#FFFFFF;font:700 var(--d3-fs-destaque) var(--vv-texto,Inter,sans-serif)}
#vv-conteudo.vc .v2c-ag::after{content:"";position:absolute;inset:-5px;border-radius:50%;border:2px solid #6E56CF;opacity:0;animation:v2c-pulso 3.6s ease-out infinite}
@keyframes v2c-pulso{0%{opacity:.5;transform:scale(.85)}70%,100%{opacity:0;transform:scale(1.25)}}

/* duas colunas: o baralho à esquerda; a fila e o equilíbrio à direita */
#vv-conteudo.vc .v2c-cols{flex:1;min-height:0;display:flex;gap:26px}
#vv-conteudo.vc .v2c-mesa{flex:none;width:410px;display:flex;flex-direction:column;align-items:flex-start;gap:14px}
#vv-conteudo.vc .v2c-mesa .v2-baralho{flex:none;width:350px;height:452px;touch-action:pan-y}
#vv-conteudo.vc .v2c-carta{box-sizing:border-box;display:flex;flex-direction:column;gap:10px;padding:14px}
#vv-conteudo.vc .v2c-arte{appearance:none;position:relative;flex:1;min-height:0;display:grid;place-items:center;overflow:hidden;width:100%;padding:0;border:0;border-radius:16px;background:#EDE8DF;color:rgba(31,29,26,.6);font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);cursor:pointer}
#vv-conteudo.vc .v2c-carta[data-carteira="vinicius"] .v2c-arte{background:#FBE3D2}
#vv-conteudo.vc .v2c-carta[data-carteira="ewerton"] .v2c-arte{background:#DCE7FA}
#vv-conteudo.vc .v2c-arte.vazia::before{content:"";position:absolute;left:-30px;bottom:-40px;width:150px;height:150px;border-radius:50%;background:rgba(255,255,255,.55)}
#vv-conteudo.vc .v2c-arte.vazia::after{content:"";position:absolute;right:22px;top:22px;width:90px;height:90px;border-radius:24px;background:rgba(255,255,255,.4);transform:rotate(12deg)}
#vv-conteudo.vc .v2c-arte > span{position:relative}
#vv-conteudo.vc .v2c-arte > img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;display:block}
#vv-conteudo.vc .v2c-nome{margin:0;font:400 var(--d3-fs-destaque)/1.3 var(--vv-texto,Inter,sans-serif);color:#1F1D1A;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
#vv-conteudo.vc .v2c-nome b{font-weight:700}
#vv-conteudo.vc .v2c-meta{display:flex;align-items:center;gap:8px;min-height:28px;margin:0;font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);color:#6B665E}
#vv-conteudo.vc .v2c-meta > span{flex:none;white-space:nowrap}
#vv-conteudo.vc .v2c-meta > .v2c-cli{flex:0 1 auto;display:block;overflow:hidden;text-overflow:ellipsis}
#vv-conteudo.vc .v2c-meta > .v2c-cli::before{display:inline-block;margin-right:6px}
#vv-conteudo.vc .v2c-meta .ruim{color:#B42318;font-weight:600}
#vv-conteudo.vc .v2c-meta .v2c-avs{margin-left:auto}
#vv-conteudo.vc .v2c-leg{margin:0;font:400 var(--d3-fs-texto)/1.45 var(--vv-texto,Inter,sans-serif);color:#4A463F;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
#vv-conteudo.vc .v2c-acoes{display:flex;align-items:center;gap:8px;width:350px;max-width:100%}
#vv-conteudo.vc .v2c-acoes .v2c-btn.k{flex:1}
#vv-conteudo.vc .v2c-conta{display:flex;flex-wrap:wrap;align-items:center;gap:10px;margin:0;font:400 var(--d3-fs-texto)/1.4 var(--vv-texto,Inter,sans-serif);color:#6B665E}
#vv-conteudo.vc .v2c-nada{display:flex;flex-direction:column;align-items:flex-start;justify-content:center;gap:8px;width:350px;max-width:100%;min-height:200px;font:400 var(--d3-fs-texto)/1.45 var(--vv-texto,Inter,sans-serif);color:#6B665E}
#vv-conteudo.vc .v2c-nada b{font:600 var(--d3-fs-destaque)/1.25 var(--vv-titulo,"Inter Tight",Inter,sans-serif);color:#1F1D1A}
#vv-conteudo.vc .v2c-lista{align-self:stretch;max-height:452px;overflow:auto;padding:6px 18px;scrollbar-width:thin}
#vv-conteudo.vc .v2c-lista .v2c-lin:first-child{border-top:0}
#vv-conteudo.vc .v2c-lista .v2c-lin[aria-current="true"] .v2c-lin-txt > span:last-child{font-weight:600;color:#1F1D1A}

#vv-conteudo.vc .v2c-lado{flex:1;min-width:0;display:flex;flex-direction:column;gap:14px}
#vv-conteudo.vc .v2c-lin{appearance:none;display:flex;align-items:center;gap:12px;width:100%;margin:0;padding:12px 0;border:0;border-top:1px solid #F1EDE6;border-radius:0;background:none;color:#1F1D1A;font:400 var(--d3-fs-texto)/1.35 var(--vv-texto,Inter,sans-serif);text-align:left}
#vv-conteudo.vc button.v2c-lin{cursor:pointer}
#vv-conteudo.vc button.v2c-lin:hover .v2c-cli{text-decoration:underline}
#vv-conteudo.vc .v2c-lin-txt{flex:1;min-width:0;display:flex;flex-wrap:wrap;align-items:center;gap:2px 6px;margin:0}
#vv-conteudo.vc .v2c-lin-txt b{font-weight:700}
#vv-conteudo.vc .v2c-fila{flex:none;padding-bottom:6px}
#vv-conteudo.vc p.v2c-lin.v2c-sub{font-size:var(--d3-fs-texto);color:#6B665E}
#vv-conteudo.vc .v2c-eq{flex:1 0 auto;display:flex;flex-direction:column;gap:12px}
#vv-conteudo.vc .v2c-eq .v2c-card-topo{margin:0}
#vv-conteudo.vc .v2c-pts{display:flex;flex-wrap:wrap;gap:6px 16px;margin:0}
#vv-conteudo.vc .v2c-pts span{display:inline-flex;align-items:center;gap:6px;font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:#4A463F}
#vv-conteudo.vc .v2c-pts span::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--c)}
#vv-conteudo.vc .v2c-pts b{font-weight:700;color:#1F1D1A}
#vv-conteudo.vc .v2c-eq-grade{display:grid;grid-template-columns:minmax(110px,auto) minmax(0,1fr) minmax(0,170px);gap:10px 12px;align-items:center}
#vv-conteudo.vc .v2c-eq-lin{appearance:none;grid-column:1/-1;display:grid;grid-template-columns:subgrid;align-items:center;padding:0;border:0;background:none;color:#1F1D1A;font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
#vv-conteudo.vc .v2c-eq-lin .v2c-cli{max-width:200px;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;display:block}
#vv-conteudo.vc .v2c-eq-lin .v2c-cli::before{display:inline-block;margin-right:6px}
#vv-conteudo.vc .v2c-eq-lin:hover .v2c-cli{text-decoration:underline}
#vv-conteudo.vc .v2c-emp{display:flex;height:10px;border-radius:5px;overflow:hidden;background:#EAE6DE}
#vv-conteudo.vc .v2c-emp i{display:block;height:100%}
#vv-conteudo.vc .v2c-pe{margin-top:auto}

/* estreito: uma coluna; o baralho ocupa a largura e as abas descem para a linha de baixo */
@container vc (max-width: 900px){
  #vv-conteudo.vc .v2c-cols{flex-direction:column;gap:16px}
  #vv-conteudo.vc .v2c-mesa{width:100%}
  #vv-conteudo.vc .v2c-mesa .v2-baralho{width:min(350px,calc(100% - 56px))}
  #vv-conteudo.vc .v2c-acoes{width:min(350px,100%)}
  #vv-conteudo.vc .v2c-eq{flex:none}
}
@container vc (max-width: 620px){
  #vv-conteudo.vc .v2c-topo{gap:10px}
  #vv-conteudo.vc .v2c-topo h2{font-size:26px}
  #vv-conteudo.vc .v2c-seg{order:5;display:flex;width:100%;box-sizing:border-box}
  #vv-conteudo.vc .v2c-seg button{flex:1 1 auto;padding:0 6px;font-size:var(--d3-fs-apoio)}
  #vv-conteudo.vc .v2c-mes{order:6}
  #vv-conteudo.vc .v2c-fala{flex-wrap:wrap}
  #vv-conteudo.vc .v2c-fala > p{flex:1 1 200px}
  #vv-conteudo.vc .v2c-eq-grade{grid-template-columns:minmax(0,auto) minmax(0,1fr)}
  #vv-conteudo.vc .v2c-eq-lin > .v2c-sub{grid-column:1/-1;margin-top:-6px}
}
@media (max-width:760px){
  #vv-conteudo.vc.vc{padding:16px}
  #vv-conteudo.vc .vc-corpo{margin:0 -16px -16px;padding:0 16px 16px}
}
@media (prefers-reduced-motion:reduce){
  #vv-conteudo.vc .v2c-ag::after{animation:none}
  #vv-conteudo.vc .v2c-btn{transition:none}
}

/* ===== padrao-v2/contratos.css ===== */
/* PADRÃO V2 · CONTRATOS E CHURN (12/11/2026): as duas telas do menu Comercial iguais aos quadros DEPOIS do moodboard.
   As peças da janela (cartão, fala, três números, fichas, botões, linha que abre no lugar) são as de padrao-v2/clientes.css
   (#vv-carteira .v2c-*); aqui só o que estes quadros têm de próprio, com o prefixo v2k. Tudo ganha pelo id da janela. */

/* as duas colunas: Contratos (Pede ação e mês a mês | clientes ativos) e Churn (Pede ação e quem saiu | saídas e retenção) */
#vv-carteira .v2k-grade2{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.3fr);gap:14px;align-items:stretch}
#vv-carteira .v2k-grade2.v2k-churn{grid-template-columns:minmax(0,1.4fr) minmax(0,1fr)}
#vv-carteira .v2k-col-esq{min-width:0;display:flex;flex-direction:column;gap:14px}
#vv-carteira .v2k-col-esq > .v2k-meses{flex:1 1 auto}
#vv-carteira .v2k-grade2 > .v2c-card{display:flex;flex-direction:column;min-width:0}

/* número em âmbar (renovam em 30 dias) e o vermelho do que venceu */
#vv-carteira .v2c-kpi.amarelo > b{color:#7A4A00}
#vv-carteira .v2k-ruim{color:#B42318;font-weight:600}
#vv-carteira .v2k-espia{color:inherit;cursor:pointer;border-radius:4px}
#vv-carteira .v2k-espia:hover{color:#1F1D1A;text-decoration:underline;text-underline-offset:2px}
#vv-carteira .v2k-espia:focus-visible{outline:2px solid var(--ds-acao,#C2490C);outline-offset:2px}

/* Pede ação */
#vv-carteira .v2k-acoes{list-style:none;margin:0;padding:0}
#vv-carteira .v2k-acao{display:flex;flex-wrap:wrap;align-items:center;gap:8px 12px;padding:12px 0;border-top:1px solid #F1EDE6;font:400 var(--d3-fs-texto)/1.4 var(--vv-texto,Inter),sans-serif;color:#1F1D1A}
#vv-carteira .v2k-acao:first-child{border-top:0}
#vv-carteira .v2k-acao > p{flex:1 1 200px;min-width:0;margin:0}
#vv-carteira .v2k-acao-tx{flex:1 1 200px;min-width:0}
#vv-carteira .v2k-acao .v2k-acao-tx > p{margin:4px 0 0}
#vv-carteira .v2k-acao b{font-weight:600}
#vv-carteira .v2k-acao-form{flex:1 1 100%;min-width:0}
#vv-carteira .v2k-cli{display:inline-flex;align-items:center;gap:6px;font-weight:600}
#vv-carteira .v2k-porque{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin:0;padding:0 0 12px}
#vv-carteira .v2k-quem-saiu{margin-top:2px;padding-top:12px;border-top:1px solid #F1EDE6}
#vv-carteira .v2k-acoes + .v2k-quem-saiu,#vv-carteira .v2k-acoes + .v2c-pe + .v2k-quem-saiu{margin-top:0}
#vv-carteira .v2k-quem-saiu > small{font-size:var(--d3-fs-texto)}

/* os formulários de sempre (mesmos campos), em duas colunas dentro dos cartões */
#vv-carteira .v2k-grade2 .vc-form,#vv-carteira .v2k-registrar .vc-form{grid-template-columns:repeat(2,minmax(0,1fr));padding:4px 0 12px}
#vv-carteira .v2k-grade2 .vc-form .vc-campo.largo,#vv-carteira .v2k-registrar .vc-form .vc-campo.largo{grid-column:1/-1}
#vv-carteira .v2k-registrar{align-items:flex-end}
#vv-carteira .v2k-registrar > .vc-campo{flex:1 1 260px;margin:0}
#vv-carteira .v2k-registrar > .vc-form,#vv-carteira .v2k-registrar > .v2k-porque,#vv-carteira .v2k-registrar > .v2k-registrar-quem{flex:1 1 100%}
#vv-carteira .v2k-registrar-quem{margin:0;font:400 var(--d3-fs-texto)/1.4 var(--vv-texto,Inter),sans-serif;color:#4A463F}
#vv-carteira .v2k-painel > .vb-mes{margin:0}
#vv-carteira .v2c-painel.v2k-painel > .vc-ordem{flex:0 1 280px;margin-left:auto}

/* Mês a mês (Contratos): uma série por vez, colunas com o mês de agora em laranja */
#vv-carteira .v2k-meses{display:flex;flex-direction:column;padding:14px 18px}
#vv-carteira .v2k-meses-topo{display:flex;flex-wrap:wrap;align-items:center;gap:6px}
#vv-carteira .v2k-meses-topo > h2{flex:1 1 auto;font:600 var(--d3-fs-destaque)/1.2 var(--vv-titulo,"Inter Tight"),Inter,sans-serif;color:#1F1D1A}
#vv-carteira .v2k-meses-topo > .v2c-chips{gap:6px}
#vv-carteira .v2k-cols{flex:1 1 auto;min-height:110px;display:flex;align-items:flex-end;gap:4px;padding-top:8px}
#vv-carteira .v2k-col{flex:1;min-width:0;height:100%;min-height:110px;display:flex;flex-direction:column;justify-content:flex-end;align-items:center;gap:4px}
#vv-carteira .v2k-col > i{display:block;width:24px;max-width:100%;height:var(--h);border-radius:7px 7px 3px 3px;background:#D9D3C8;transform-origin:bottom;animation:v2k-sobe .7s var(--vv-suave,cubic-bezier(.22,1,.36,1)) both}
#vv-carteira .v2k-col.agora > i{background:#1F1D1A}
#vv-carteira .v2k-col > span{font:400 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;color:#6B665E}
#vv-carteira .v2k-col.agora > span{color:#1F1D1A;font-weight:600}
#vv-carteira .v2k-col[data-espiar]{cursor:pointer}
@keyframes v2k-sobe{from{transform:scaleY(0)}to{transform:none}}

/* Clientes ativos (Contratos): nome e desde quando | trilha até a renovação | valor | data */
#vv-carteira .v2k-linha-ct{display:grid;grid-template-columns:minmax(0,1fr) 150px 76px 122px;align-items:center;gap:12px}
#vv-carteira .v2k-nome{min-width:0;display:flex;flex-direction:column;gap:1px}
#vv-carteira .v2k-nome > b{font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#vv-carteira .v2k-nome > small,#vv-carteira .v2k-dir > small,#vv-carteira .v2k-trilha > small{font:400 var(--d3-fs-texto)/1.35 var(--vv-texto,Inter),sans-serif;color:#6B665E;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#vv-carteira .v2k-trilha{min-width:0;display:flex;flex-direction:column;gap:6px}
#vv-carteira .v2k-trilha > .v2-barra{background:#EAE6DE}
#vv-carteira .v2k-valor{font-weight:700;font-variant-numeric:tabular-nums;white-space:nowrap}
#vv-carteira .v2k-linha-ct > .v2c-pill{justify-content:flex-start;min-width:0;overflow:hidden;text-overflow:ellipsis}
#vv-carteira .v2k-det{padding:0 0 4px}
#vv-carteira .v2k-hist{display:flex;align-items:center;gap:8px;margin:0;padding:0 0 10px 14px;font:400 var(--d3-fs-texto)/1.4 var(--vv-texto,Inter),sans-serif;color:#4A463F}
#vv-carteira .v2k-hist::before{content:"";flex:none;width:6px;height:6px;border-radius:50%;background:#C9C2B6}
#vv-carteira .v2k-det-acoes{display:flex;flex-wrap:wrap;gap:8px;margin:0;padding:0 0 12px 14px}
#vv-carteira .v2k-det > .vc-form{padding-left:14px}

/* Quem saiu (Churn): o porquê à esquerda, quanto levou à direita */
#vv-carteira .v2k-saiu .v2c-abrir{justify-content:space-between}
#vv-carteira .v2k-saiu .v2k-nome{flex:1}
#vv-carteira .v2k-dir{flex:none;display:flex;flex-direction:column;align-items:flex-end;gap:1px;text-align:right}
#vv-carteira .v2k-dir > b{font-weight:700;font-variant-numeric:tabular-nums;white-space:nowrap}

/* Saídas e retenção (Churn) */
#vv-carteira .v2k-lado > h2{font:600 var(--d3-fs-destaque)/1.2 var(--vv-titulo,"Inter Tight"),Inter,sans-serif;color:#1F1D1A}
#vv-carteira .v2k-lado > .v2k-seg{margin:10px 0 0}
#vv-carteira .v2k-vista{min-width:0}
#vv-carteira .v2k-motivos > .v2k-mot{display:flex;align-items:baseline;gap:8px;margin:12px 0 6px;font:500 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter),sans-serif;color:#1F1D1A}
#vv-carteira .v2k-motivos > .v2k-mot > span:first-child{flex:1;min-width:0}
#vv-carteira .v2k-motivos > .v2-barra{background:#EAE6DE}
#vv-carteira .v2k-grafs{grid-template-columns:minmax(0,1fr);margin-top:12px}
#vv-carteira .v2k-vista > .vc-tabela-rola,#vv-carteira .v2k-vista > .vb-estado{margin-top:12px}
#vv-carteira .v2k-lado > .v2c-pe{border-top:0}

/* o rodapé tracejado (parte ainda não ligada) e a nota final */
#vv-carteira .v2k-vz{display:flex;flex-wrap:wrap;align-items:center;gap:10px;padding:7px 8px 7px 18px;border:1.5px dashed #D9D1C3;border-radius:999px;font:400 var(--d3-fs-texto)/1.4 var(--vv-texto,Inter),sans-serif;color:#4A463F}
#vv-carteira .v2k-vz > p{flex:1 1 300px;margin:0}
#vv-carteira .v2k-vz b{color:#1F1D1A}
#vv-carteira .v2k-vz .vc-ativacao-tec{display:block;margin-top:4px}
#vv-carteira .v2k-nota{margin:0}
#vv-carteira .v2k-fin > .vc-secao{margin:0}
#vv-carteira .v2c:is([data-tela="contratos"],[data-tela="churn"]) .v2c-ajuda .vc-ajuda > p{margin-top:6px}

@media (prefers-reduced-motion:reduce){#vv-carteira .v2k-col > i{animation:none}}
@container v2c (max-width:980px){
  #vv-carteira .v2k-grade2,#vv-carteira .v2k-grade2.v2k-churn{grid-template-columns:minmax(0,1fr)}
  #vv-carteira .v2k-cols,#vv-carteira .v2k-col{min-height:96px}
}
@container v2c (max-width:680px){
  #vv-carteira .v2k-linha-ct{grid-template-columns:minmax(0,1fr) auto auto;gap:6px 10px}
  #vv-carteira .v2c:is([data-tela="contratos"],[data-tela="churn"]) .v2c-tres{grid-template-columns:repeat(2,minmax(0,1fr))}
  #vv-carteira .v2c:is([data-tela="contratos"],[data-tela="churn"]) .v2c-tres > .v2c-kpi:first-child{grid-column:1/-1}
  #vv-carteira .v2c:is([data-tela="contratos"],[data-tela="churn"]) .v2c-kpi > b{white-space:nowrap}
  #vv-carteira .v2c:is([data-tela="contratos"],[data-tela="churn"]) .v2c-kpi > b > .v2c-pill{font-size:var(--d3-fs-mini);vertical-align:middle}
  #vv-carteira .v2c:is([data-tela="contratos"],[data-tela="churn"]) .v2c-topo > .v2c-sub{order:3;flex:1 1 100%}
  #vv-carteira .v2k-trilha{grid-column:1/-1;order:5}
  #vv-carteira .v2k-grade2 .vc-form,#vv-carteira .v2k-registrar .vc-form{grid-template-columns:minmax(0,1fr)}
  #vv-carteira .v2k-vz{border-radius:20px;padding:10px 12px}
  #vv-carteira .v2k-det-acoes,#vv-carteira .v2k-hist{padding-left:0}
  #vv-carteira .v2k-det > .vc-form{padding-left:0}
}

/* ===== padrao-v2/coordenacao.css ===== */
/* PADRÃO V2 · HOJE · COORDENAÇÃO: a aba do Heitor e da Beatriz agora segue a Direção 3 (padrao-v2/d3-hoje.css, quadro
   D3-Coordenacao). Fica só a grade das quatro abas do Hoje. */
.vv-seg-4{grid-template-columns:repeat(4,minmax(0,1fr))}

/* ===== padrao-v2/cores.css ===== */
/* PADRÃO V2 · CORES ENXUTAS (confere de cor, 13/11/2026; Paulo: "pra não olhar muita informação e tudo parecer a mesma
   coisa"). Regras: pílula cheia só no que pede atenção (vermelho venceu, âmbar voltou para ajuste, verde pronto); o resto
   do status é uma pílula clara com a bolinha na cor do catálogo (Paulo, 08/11: o status tem de mostrar a cor dele);
   vermelho só no que venceu; lilás só no agente; laranja só na ação. */

/* A pílula de status nas listas e cartões do mundo (pillHtml em vybe-gestor.js). */
body.mundo .pill.vv-st-ponto{display:inline-flex;align-items:center;gap:6px;height:22px;max-width:100%;box-sizing:border-box;padding:0 9px;border:0;border-radius:999px;
  background:#F3F1EC;color:#4A463F;font:600 var(--d3-fs-apoio)/1 var(--vv-texto,Inter,sans-serif);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;box-shadow:none}
body.mundo .pill.vv-st-ponto > i{flex:none;width:7px;height:7px;border-radius:50%;background:var(--st,#B5AFA5)}
body.mundo .pill.vv-st-ponto.r{background:#FDECEE;color:#B42318}
body.mundo .pill.vv-st-ponto.a{background:#FFF4D6;color:#7A4A00}
body.mundo .pill.vv-st-ponto.g{background:#E8F5EC;color:#11613A}

/* O botão de status das listas (pv2StatusBotao): neutro com a bolinha; azul e lilás (antigos "a fazer" e "aprovação")
   viram neutros — o lilás é do agente. */
:is(#grupos-board,#grupos-board-demandas,#cartao-rapido,#pv2-painel,#pv2-semana,#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6,#pv2-demandas,#pv2-agenda,#pv2-ia,#vv-hoje,#workspace-drawer) .pv2-st.pv2-st:is(.n,.b,.v){background:#F3F1EC;color:#4A463F}
:is(#grupos-board,#grupos-board-demandas,#cartao-rapido,#pv2-painel,#pv2-semana,#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6,#pv2-demandas,#pv2-agenda,#pv2-ia,#vv-hoje,#workspace-drawer) .pv2-st.pv2-st:is(.n,.b,.v)::before{content:"";flex:none;width:7px;height:7px;border-radius:50%;background:var(--st,#B5AFA5)}
:is(#pv2-painel,#pv2-semana,#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6,#pv2-demandas,#pv2-agenda,#pv2-agenda-topo,#pv2-ia) .pv2-pill.pv2-pill:is(.b,.v){background:#F3F1EC;color:#4A463F}

/* Peça sem responsável: neutro tracejado, não vermelho (vermelho é do que venceu). */
:is(#pv2-painel,#pv2-semana,#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6,#pv2-demandas,#pv2-agenda,#pv2-agenda-topo,#pv2-ia) .pv2-av.sd.sd{background:#FFFFFF;color:#6B665E;box-shadow:inset 0 0 0 1.5px #C9C2B6}

/* Links do mundo em tinta sublinhada (o laranja fica só no botão de ação). */
body.mundo :is(#vv-hoje,#mundo-hud,.vv-setor-visao,#vv-carteira,#vv-comercial) .vg-link{color:#1F1D1A;text-decoration:underline;text-decoration-color:#C9C2B6;text-underline-offset:3px}
body.mundo :is(#vv-hoje,#mundo-hud,.vv-setor-visao,#vv-carteira,#vv-comercial) .vg-link:hover{text-decoration-color:#1F1D1A}

/* Acabamento premium (15/11/2026, item 10): a peça sem dono aparecia como uma bolinha com "?" (Hoje, Painel, Produção),
   que parece dúvida, não falta de responsável. A bolinha tracejada fica e o "?" vira um traço; o nome acessível
   ("Sem dono", "Sem responsável") continua no title e no aria-label de cada uma. */
:is(.pv2-av.sd,.d3h-av.sd,.d3s-pes.sd .d3s-av,#vv-carteira .v2c-av.vago):not(#v2-sd-a):not(#v2-sd-b){font-size:0;line-height:0}
:is(.pv2-av.sd,.d3h-av.sd,.d3s-pes.sd .d3s-av,#vv-carteira .v2c-av.vago):not(#v2-sd-a):not(#v2-sd-b)::before{content:"";display:block;width:10px;height:2px;border-radius:1px;background:var(--d3-apagado)}

/* ===== padrao-v2/d3-agenda.css ===== */
/* DIREÇÃO 3 · AGENDA E CAPTAÇÕES, PLANEJAMENTOS, IMPRESSÕES, PROJETOS, CREATORS, FORNECEDORES E TOOLKIT (quadros D3-*,
   aprovados pelo Paulo em 13/11/2026). Usa os tokens e as peças de 0-d3-base.css (.d3-acao, .d3-num, .d3-graf, .d3-barra)
   e os movimentos .v2-* do bloco PADRÃO V2 · BASE de vybe-mundo.css. Cada regra presa ao id da janela. */

/* ===================== Agenda e captações (#pv2-agenda) ===================== */
#pv2-agenda .d3ag-nums{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;min-width:0}
#pv2-agenda .d3ag-nums > .d3-num{appearance:none;border:0;margin:0;text-align:left;color:var(--d3-tinta);font-family:inherit;cursor:default}
#pv2-agenda .d3ag-nums > button.d3-num{cursor:pointer;transition:box-shadow .2s}
#pv2-agenda .d3ag-nums > button.d3-num:hover{box-shadow:0 0 0 1px var(--d3-borda)}
#pv2-agenda .d3ag-nums > button.d3-num:focus-visible{outline:2px solid var(--d3-acao);outline-offset:2px}
#pv2-agenda .d3-num > .d3-num-v small{font-size:var(--d3-fs-titulo);font-weight:600;color:var(--d3-apagado);letter-spacing:0}
#pv2-agenda .d3ag-pe{font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter),sans-serif;color:var(--d3-apagado);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#pv2-agenda .d3ag-pe .r{color:var(--d3-perigo)}

/* a faixa da semana */
#pv2-agenda .d3ag-faixa{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:6px;align-items:stretch;padding:8px}
#pv2-agenda .d3ag-nav{flex:none;display:inline-flex;align-items:center;gap:2px}
#pv2-agenda .d3ag-seta{appearance:none;display:grid;place-items:center;width:28px;height:28px;padding:0;border:0;border-radius:50%;background:transparent;color:var(--d3-texto2);cursor:pointer}
#pv2-agenda .d3ag-seta:hover{background:var(--d3-trilho)}
#pv2-agenda .d3ag-seta svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
#pv2-agenda .d3ag-dia{appearance:none;display:flex;align-items:center;justify-content:space-between;gap:6px;min-width:0;padding:8px 12px;border:0;border-radius:14px;background:transparent;color:var(--d3-apagado);font:400 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;cursor:pointer;transition:background .2s}
#pv2-agenda .d3ag-dia:hover{background:var(--d3-trilho)}
#pv2-agenda .d3ag-dia > span{display:inline-flex;align-items:center;gap:5px;min-width:0;white-space:nowrap}
#pv2-agenda .d3ag-dia b{color:var(--d3-tinta);font-weight:700}
#pv2-agenda .d3ag-dia .d3ag-dia-n > b{font-size:var(--d3-fs-destaque)}
#pv2-agenda .d3ag-dia .d3ag-dia-n > b.zero{color:var(--d3-meta)}
#pv2-agenda .d3ag-dia.hj{background:var(--d3-tinta);color:#FFFFFF}
#pv2-agenda .d3ag-dia.hj b{color:#FFFFFF}
#pv2-agenda .d3ag-selo{display:inline-flex;align-items:center;flex:none;height:18px;padding:0 6px;border-radius:999px;font:700 var(--d3-fs-mini) var(--vv-texto,Inter),sans-serif}
#pv2-agenda .d3ag-selo.a{background:var(--d3-ajuste-veu);color:var(--d3-ajuste)}
#pv2-agenda .d3ag-selo.b{background:var(--d3-info-veu);color:var(--d3-info)}
/* Confere responsivo (14/11/2026): com a faixa abaixo de ~1.000 px (1366, 1280 e o app do Mac) o selo "fechar" e
   "Feriado" passavam por cima de "hoje 14" e "dom 15". O dia fica em cima e o selo com o número embaixo. */
#pv2-agenda .d3ag-faixa{container:d3agfaixa / inline-size;width:100%;box-sizing:border-box}
@container d3agfaixa (max-width:1000px){
  #pv2-agenda .d3ag-dia{flex-direction:column;align-items:flex-start;gap:4px;padding:8px 10px}
  #pv2-agenda .d3ag-dia > .d3ag-dia-n{align-self:stretch;justify-content:space-between}
}

/* cartões */
#pv2-agenda .pv2a-duas.d3ag-corpo{display:flex;flex-direction:column;gap:14px}
#pv2-agenda .d3ag-card{min-width:0;box-sizing:border-box;border-radius:var(--d3-r-cartao);background:var(--d3-cartao);color:var(--d3-tinta)}
#pv2-agenda .d3ag-duas{display:grid;grid-template-columns:minmax(0,2.2fr) minmax(0,.85fr);gap:14px;align-items:start;min-width:0}
#pv2-agenda .pv2a-duas.larga + .d3ag-ordem,#pv2-agenda .pv2a-duas.larga > .d3ag-ordem{margin-top:0}
#pv2-agenda .d3ag-col{display:flex;flex-direction:column;gap:14px;min-width:0}
#pv2-agenda .d3ag-cab{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:0 18px 8px}
#pv2-agenda .d3ag-cab > h3{margin:0;font:700 var(--d3-fs-destaque) var(--vv-texto,Inter),sans-serif;color:var(--d3-tinta)}
#pv2-agenda .d3ag-cab > span{font:400 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;color:var(--d3-apagado)}
#pv2-agenda .d3ag-n{font:400 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;color:var(--d3-apagado)}
#pv2-agenda .d3ag-vazio{margin:0;padding:12px 18px;border-top:1px solid var(--d3-linha)}

/* Na ordem de fazer */
#pv2-agenda .d3ag-ordem{padding:14px 0 8px}
#pv2-agenda .d3ag-lin{display:grid;grid-template-columns:56px 44px 80px minmax(0,1fr) auto 104px;align-items:center;gap:10px;padding:9px 18px;border-top:1px solid var(--d3-linha);font:400 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;color:var(--d3-tinta);cursor:pointer;transition:background .2s}
#pv2-agenda .d3ag-lin:hover,#pv2-agenda .d3ag-lin.sel,#pv2-agenda .d3ag-lin.fechar{background:#F9F8F5}
#pv2-agenda .d3ag-lin:focus-visible{outline:2px solid var(--d3-acao);outline-offset:-2px}
#pv2-agenda .d3ag-lin.passou{color:var(--d3-apagado)}
#pv2-agenda .d3ag-lin.passou .pv2-cli{opacity:.7}
#pv2-agenda .d3ag-q{font:700 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;color:var(--d3-apagado);text-transform:uppercase}
#pv2-agenda .d3ag-q.hj{color:var(--d3-tinta)}
#pv2-agenda .d3ag-q.r{color:var(--d3-perigo)}
#pv2-agenda .d3ag-h{font-size:var(--d3-fs-texto)}
#pv2-agenda .d3ag-t{color:var(--d3-texto2)}
#pv2-agenda .d3ag-c{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#pv2-agenda .d3ag-c .pv2-cli{font-weight:700}
#pv2-agenda .d3ag-c .pv2-cli[data-carteira="vinicius"]{color:var(--d3-cart-vinicius)}
#pv2-agenda .d3ag-c .pv2-cli[data-carteira="ewerton"]{color:var(--d3-cart-ewerton)}
#pv2-agenda .d3ag-sem{font-weight:600}
#pv2-agenda .d3ag-pill{justify-self:start;display:inline-flex;align-items:center;gap:5px;height:22px;padding:0 9px;border-radius:999px;background:var(--d3-trilho);color:var(--d3-texto2);font:600 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;white-space:nowrap}
#pv2-agenda .d3ag-pill > i{flex:none;width:7px;height:7px;border-radius:50%;background:var(--c,var(--d3-meta))}
#pv2-agenda .d3ag-pill.a{background:var(--d3-ajuste-veu);color:var(--d3-ajuste)}
#pv2-agenda .d3ag-fim{justify-self:end;font:400 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;color:var(--d3-apagado);text-align:right;white-space:nowrap}
#pv2-agenda .d3ag-fim.r{color:var(--d3-perigo);font-weight:600}
#pv2-agenda .d3ag-mini{appearance:none;justify-self:end;height:28px;padding:0 12px;border:0;border-radius:999px;background:var(--d3-trilho);color:var(--d3-tinta);font:600 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;white-space:nowrap;cursor:pointer;transition:background .2s,transform .14s}
#pv2-agenda .d3ag-mini:hover{background:var(--d3-borda)}
#pv2-agenda .d3ag-mini:active{transform:scale(.96)}
#pv2-agenda .d3ag-mini[aria-current]{background:var(--d3-tinta);color:#FFFFFF}
#pv2-agenda .d3ag-mini.b{background:#FFFFFF}
#pv2-agenda .d3ag-mini.k{background:var(--d3-tinta);color:#FFFFFF}
#pv2-agenda .d3ag-mais{appearance:none;display:block;margin:4px 18px 0;padding:6px 0;border:0;background:transparent;color:var(--d3-apagado);font:600 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;cursor:pointer}
#pv2-agenda .d3ag-abre > .v2-mais > div{min-height:0;overflow:hidden}
#pv2-agenda .d3ag-det{display:flex;flex-direction:column;gap:8px;margin:0 18px 8px 128px;padding:10px 12px;border-radius:14px;background:var(--d3-trilho)}
#pv2-agenda .d3ag-etapas{display:flex;flex-wrap:wrap;gap:6px 16px}
#pv2-agenda .d3ag-etp{display:inline-flex;align-items:center;gap:6px;font:500 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;color:var(--d3-apagado)}
#pv2-agenda .d3ag-etp > i{display:grid;place-items:center;width:16px;height:16px;border-radius:50%;background:#FFFFFF;box-shadow:inset 0 0 0 1.5px #C9C2B6}
#pv2-agenda .d3ag-etp.ok{color:var(--d3-tinta)}
#pv2-agenda .d3ag-etp.ok > i{background:var(--d3-pronto);box-shadow:none}
#pv2-agenda .d3ag-etp.ok > i svg{width:10px;height:10px;fill:none;stroke:#FFFFFF;stroke-width:3.5;stroke-linecap:round;stroke-linejoin:round}
#pv2-agenda .d3ag-etp.vez{color:var(--d3-tinta);font-weight:700}
#pv2-agenda .d3ag-chips{display:flex;flex-wrap:wrap;gap:6px}
#pv2-agenda .d3ag-chip{display:inline-flex;align-items:center;height:24px;max-width:220px;padding:0 9px;border-radius:999px;background:#FFFFFF;font:600 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#pv2-agenda .d3ag-chip.ok{text-decoration:line-through;color:var(--d3-apagado)}
#pv2-agenda .d3ag-acoes{display:flex;justify-content:flex-end;gap:8px}

/* lado: esperando captação e roteiros */
#pv2-agenda .d3ag-lado{padding:14px 16px 6px}
#pv2-agenda .d3ag-lado > .d3ag-cab{padding:0 0 6px}
#pv2-agenda .d3ag-lado-lin{appearance:none;display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:10px;align-items:center;width:100%;margin:0;padding:8px 0;border:0;border-top:1px solid var(--d3-linha);background:transparent;color:var(--d3-tinta);font:400 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;text-align:left;cursor:pointer}
#pv2-agenda .d3ag-lado-lin.fixo{grid-template-columns:minmax(0,1fr) auto;cursor:default}
#pv2-agenda button.d3ag-lado-lin:hover{color:var(--d3-acao-texto)}
#pv2-agenda .d3ag-lado-lin .pv2-cli{font-weight:700;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#pv2-agenda .d3ag-lado-lin .pv2-cli[data-carteira="vinicius"]{color:var(--d3-cart-vinicius)}
#pv2-agenda .d3ag-lado-lin .pv2-cli[data-carteira="ewerton"]{color:var(--d3-cart-ewerton)}
#pv2-agenda .d3ag-lado-lin > b.a{color:var(--d3-ajuste)}
#pv2-agenda .d3ag-lado-lin.mais{grid-template-columns:1fr;color:var(--d3-apagado);font-weight:600}
/* Agentes viram: a bolinha lilás do agente, o que ele notou e o dia */
#pv2-agenda .d3ag-lado-lin.d3ag-viu{grid-template-columns:24px minmax(0,1fr) auto}
#pv2-agenda .d3ag-viu-av{display:grid;place-items:center;width:24px;height:24px;border-radius:50%;background:var(--d3-agente);color:#FFFFFF;font:700 var(--d3-fs-mini) var(--vv-texto,Inter),sans-serif}
#pv2-agenda .d3ag-viu-txt{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#pv2-agenda .d3ag-viu-txt .pv2-cli{display:inline;font-weight:700}
/* O ⋯ de "Na ordem de fazer": busca, Dia, Anterior, Hoje, Próxima e os filtros (o quadro não tem a linha de busca) */
#pv2-agenda .d3ag-cab > .d3ag-cab-dir{display:inline-flex;align-items:center;gap:8px}
#pv2-agenda .d3ag-ferr{position:relative}
#pv2-agenda .d3ag-ferr > .d3ag-ferr-btn{display:grid;place-items:center;width:28px;height:28px;border-radius:50%;background:var(--d3-trilho);color:var(--d3-tinta);font:700 var(--d3-fs-destaque)/1 var(--vv-texto,Inter),sans-serif;list-style:none;cursor:pointer}
#pv2-agenda .d3ag-ferr > .d3ag-ferr-btn::-webkit-details-marker{display:none}
#pv2-agenda .d3ag-ferr > .d3ag-ferr-btn.tem{background:var(--d3-tinta);color:#FFFFFF}
#pv2-agenda .d3ag-ferr > .pv2-pop{right:0;left:auto;width:min(320px,86vw);gap:8px}
#pv2-agenda .d3ag-ferr .pv2-pop-linha{display:flex;flex-wrap:wrap;align-items:center;gap:8px}
#pv2-agenda .d3ag-ferr .pv2-busca{flex:none;width:100%;height:38px;box-sizing:border-box}

/* Agenda no celular: dois números por linha, a semana em sete colunas curtas e a linha em duas */
@media (max-width:900px){
  #pv2-agenda .d3ag-duas{grid-template-columns:minmax(0,1fr)}
}
@media (max-width:700px){
  #pv2-agenda .d3ag-nums{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
  #pv2-agenda .d3ag-faixa{grid-template-columns:repeat(7,minmax(0,1fr));gap:2px;padding:6px}
  #pv2-agenda .d3ag-dia{flex-direction:column;gap:2px;padding:6px 2px;font-size:var(--d3-fs-mini)}
  #pv2-agenda .d3ag-dia > span{flex-direction:column;gap:0}
  #pv2-agenda .d3ag-dia .d3ag-selo{display:none}
  #pv2-agenda .d3ag-lin{grid-template-columns:44px minmax(0,1fr) auto;grid-template-areas:"q c f" "h p f";row-gap:4px;padding:10px 14px}
  #pv2-agenda .d3ag-lin > .d3ag-q{grid-area:q}
  #pv2-agenda .d3ag-lin > .d3ag-h{grid-area:h}
  #pv2-agenda .d3ag-lin > .d3ag-t{display:none}
  #pv2-agenda .d3ag-lin > .d3ag-c{grid-area:c}
  #pv2-agenda .d3ag-lin > .d3ag-pill{grid-area:p}
  #pv2-agenda .d3ag-lin > .d3ag-fim,#pv2-agenda .d3ag-lin > .d3ag-mini{grid-area:f}
  #pv2-agenda .d3ag-det{margin:0 14px 8px}
  #pv2-agenda .d3ag-acoes{flex-wrap:wrap}
}

/* ===================== Planejamentos (#vv-planejamentos) ===================== */
#vv-planejamentos.vv-plj.vv-plj{background:var(--d3-areia)}
#vv-planejamentos .d3-acao .d3-acao-frase{display:flex;flex-direction:column;gap:1px;white-space:nowrap}
#vv-planejamentos .d3-acao .d3pl-quem{overflow:hidden;text-overflow:ellipsis;font:600 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;opacity:.85}
#vv-planejamentos .d3-acao .d3-acao-frase > span{overflow:hidden;text-overflow:ellipsis;font-size:var(--d3-fs-titulo)}
#vv-planejamentos .p2-menu > .p2-btn.d3pl-novo{background:var(--d3-cartao);color:var(--d3-tinta);box-shadow:none}
#vv-planejamentos .p2-menu > .p2-btn.d3pl-novo:hover{background:var(--d3-trilho)}
/* o mês é um segmento com os meses (Direção 3): o escolhido fica escuro, como no quadro */
#vv-planejamentos .p2-seg[aria-label="Mês"]{background:var(--d3-cartao)}
#vv-planejamentos .p2-seg[aria-label="Mês"] > button[aria-pressed="true"]{background:var(--d3-tinta);color:#FFFFFF;box-shadow:none}
#vv-planejamentos .d3pl-nums{flex:none;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;min-width:0}
#vv-planejamentos .d3pl-nums > .d3-num{appearance:none;border:0;margin:0;text-align:left;color:var(--d3-tinta);font-family:inherit}
#vv-planejamentos .d3pl-nums > button.d3-num{cursor:pointer}
#vv-planejamentos .d3pl-nums > button.d3-num:hover{box-shadow:0 0 0 1px var(--d3-borda)}
#vv-planejamentos .d3-num > .d3-num-v small{font-size:var(--d3-fs-titulo);font-weight:600;color:var(--d3-apagado);letter-spacing:0}
#vv-planejamentos .d3pl-pe{font:400 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;color:var(--d3-apagado);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#vv-planejamentos .d3-num.a > .d3pl-pe{color:var(--d3-ajuste)}
#vv-planejamentos .d3-num.r > .d3pl-pe{color:var(--d3-perigo)}

/* a tabela */
#vv-planejamentos .p2-card.p2-lista{padding:6px 0 10px;border-radius:var(--d3-r-cartao);box-shadow:none}
#vv-planejamentos .d3pl-cab,#vv-planejamentos .p2-lin.d3pl-lin{display:grid;grid-template-columns:minmax(0,250px) 76px 136px minmax(0,1fr) 120px auto;align-items:center;gap:12px;padding:10px 18px}
#vv-planejamentos .d3pl-cab{padding-top:8px;padding-bottom:8px;font:500 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;color:var(--d3-apagado)}
#vv-planejamentos .p2-lin.d3pl-lin > :is(.p2-c1,.p2-c2,.p2-c3,.p2-c5){width:auto}
#vv-planejamentos .p2-lin.d3pl-lin > p{margin:0;min-width:0}
#vv-planejamentos .d3pl-sec{display:flex;align-items:baseline;gap:8px;padding:9px 18px;border-top:1px solid var(--d3-linha);background:#F9F8F5}
#vv-planejamentos .d3pl-sec > h3{margin:0;padding-left:10px;border-left:3px solid var(--d3-pronto);font:700 var(--d3-fs-destaque) var(--vv-texto,Inter),sans-serif;color:var(--d3-tinta)}
#vv-planejamentos .d3pl-sec.a > h3{border-left-color:var(--d3-ajuste)}
#vv-planejamentos .d3pl-sec > span{font:400 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;color:var(--d3-apagado)}
#vv-planejamentos .d3pl-abre[data-plj-linha] > .d3pl-lin{background:#F9F8F5}
#vv-planejamentos .d3pl-abre[data-plj-linha][aria-expanded="true"]{box-shadow:inset 3px 0 0 var(--d3-tinta)}
#vv-planejamentos .d3pl-abre .p2-det{margin:0 18px 12px;background:var(--d3-cartao);box-shadow:0 0 0 1px var(--d3-linha)}
#vv-planejamentos .d3pl-abre .p2-cx.ok{background:var(--d3-pronto)}
#vv-planejamentos .d3pl-pecas{display:flex;flex-wrap:wrap;align-items:center;gap:6px;overflow:hidden}
#vv-planejamentos .d3pl-n{font:400 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;color:var(--d3-texto2)}
#vv-planejamentos .d3pl-av{display:inline-flex;align-items:center;height:22px;padding:0 8px;border-radius:999px;background:var(--d3-trilho);font:600 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;color:var(--d3-tinta);white-space:nowrap}
#vv-planejamentos .d3pl-av.r{background:var(--d3-perigo-veu);color:var(--d3-perigo)}
#vv-planejamentos .d3pl-pill{display:inline-flex;align-items:center;gap:5px;height:22px;padding:0 9px;border-radius:999px;background:var(--d3-trilho);color:var(--d3-texto2);font:600 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;white-space:nowrap}
#vv-planejamentos .d3pl-pill > i{flex:none;width:7px;height:7px;border-radius:50%;background:var(--c)}
#vv-planejamentos .d3pl-pill.a{background:var(--d3-ajuste-veu);color:var(--d3-ajuste)}
#vv-planejamentos .d3pl-pill.g{background:var(--d3-pronto-veu);color:var(--d3-pronto)}
#vv-planejamentos .d3pl-pill.r{background:var(--d3-perigo-veu);color:var(--d3-perigo)}
#vv-planejamentos .d3pl-ok{display:flex;align-items:center;gap:8px}
#vv-planejamentos .d3pl-ok > .d3-barra{flex:1;min-width:30px}
#vv-planejamentos .d3pl-ok > .d3-barra > i.g{background:var(--d3-pronto)}
#vv-planejamentos .d3pl-ok > small{font:500 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;color:var(--d3-apagado);font-variant-numeric:tabular-nums}
#vv-planejamentos .d3pl-bts{display:flex;justify-content:flex-end;gap:6px}
#vv-planejamentos .d3pl-nomes{display:flex;flex-wrap:nowrap;gap:10px;overflow:hidden;white-space:nowrap}
#vv-planejamentos .d3pl-nomes > *{flex:none}
/* Acabamento premium (15/11/2026, item 11): o último nome da fila ("Cliente ⊦") era cortado no meio da letra. A fila vira
   uma linha de texto: cada cliente é um trecho na linha (a bolinha num bloquinho antes do nome) e a linha termina em "…". */
#vv-planejamentos .d3pl-nomes.d3pl-nomes{display:block;text-overflow:ellipsis}
#vv-planejamentos .d3pl-nomes > .cliente-carteira{display:inline;margin-right:10px}
#vv-planejamentos .d3pl-nomes > .cliente-carteira::before{display:inline-block;margin-right:6px;vertical-align:1px}
#vv-planejamentos .d3pl-nomes > .cliente-carteira > .p2-nome{display:inline;overflow:visible}
/* Confere responsivo (14/11/2026): com o menu aberto em 1024 a lista mede ~680 px; as cinco colunas fixas comiam tudo,
   o nome do cliente virava "Clie..." e "Peças" encostava em "Com OK". Abaixo de 820 px de lista, a linha empilha. */
#vv-planejamentos .p2-card.p2-lista{container:d3pl / inline-size}
@container d3pl (max-width:820px){
  #vv-planejamentos .d3pl-cab{display:none}
  #vv-planejamentos .p2-lin.d3pl-lin{grid-template-columns:minmax(0,1fr) auto auto;gap:6px 10px}
  #vv-planejamentos .p2-lin.d3pl-lin > p{grid-column:1 / 2}
  #vv-planejamentos .p2-lin.d3pl-lin > .d3pl-bts{grid-column:2 / -1}
  #vv-planejamentos .p2-lin.d3pl-lin > .d3pl-ok{grid-column:1 / -1}
  #vv-planejamentos .d3pl-ok:empty{display:none}
}
@media (max-width:900px){
  #vv-planejamentos .d3pl-nums{grid-template-columns:repeat(2,minmax(0,1fr))}
  #vv-planejamentos .d3pl-cab{display:none}
  #vv-planejamentos .p2-lin.d3pl-lin{grid-template-columns:minmax(0,1fr) auto;gap:6px 10px}
  #vv-planejamentos .p2-lin.d3pl-lin > :is(.p2-c1,p,.d3pl-ok){grid-column:1 / -1}
  #vv-planejamentos .p2-lin.d3pl-lin > .p2-c2{display:none}
  #vv-planejamentos .p2-lin.d3pl-lin > .d3pl-bts{grid-column:1 / -1;justify-content:flex-start}
  #vv-planejamentos .d3pl-ok:empty{display:none}
}

/* ===================== Impressões (#vv-impressoes) ===================== */
#vv-impressoes.vc-janela.vc-janela{background:var(--d3-areia)}
#vv-impressoes .d3-acao .d3-acao-frase{display:flex;flex-direction:column;gap:1px;white-space:nowrap}
#vv-impressoes .d3-acao .d3im-quem{overflow:hidden;text-overflow:ellipsis;font:600 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;opacity:.85}
#vv-impressoes .d3-acao .d3-acao-frase > span{overflow:hidden;text-overflow:ellipsis;font-size:var(--d3-fs-titulo)}
#vv-impressoes .p2-btn.d3im-nova{background:var(--d3-cartao);color:var(--d3-tinta);box-shadow:none}
#vv-impressoes .p2-btn.d3im-nova:hover{background:var(--d3-trilho)}
#vv-impressoes .d3im-nums{flex:none;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;min-width:0}
#vv-impressoes .d3im-nums > .d3-num{appearance:none;border:0;margin:0;text-align:left;color:var(--d3-tinta);font-family:inherit;position:relative}
#vv-impressoes .d3im-nums > button.d3-num{cursor:pointer}
#vv-impressoes .d3im-nums > button.d3-num:hover{box-shadow:0 0 0 1px var(--d3-borda)}
#vv-impressoes .d3im-nums > .d3-num > .d3-graf{position:absolute;right:16px;top:26px;width:96px}
#vv-impressoes .d3im-pe{font:400 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;color:var(--d3-apagado);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#vv-impressoes .d3-num.r > .d3im-pe{color:var(--d3-perigo)}
#vv-impressoes .d3-num.a > .d3im-pe{color:var(--d3-ajuste)}

/* a lista em tabela */
#vv-impressoes .p2-card.vi2-lista{padding:16px 0 10px;border-radius:var(--d3-r-cartao);box-shadow:none}
#vv-impressoes .vi2-lista > .p2-filtros{padding:0 18px}
#vv-impressoes .vi2-cab,#vv-impressoes .p2-lin.vi2-tab{display:grid;grid-template-columns:minmax(0,1fr) 130px 130px 92px 150px;align-items:center;gap:12px;padding:10px 18px}
#vv-impressoes .vi2-cab{padding-top:6px;padding-bottom:6px;font:500 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;color:var(--d3-apagado)}
#vv-impressoes .vi2-cab + .vi2-item > .p2-lin{border-top:1px solid var(--d3-linha)}
#vv-impressoes .p2-lin.vi2-tab > .vi2-meio{display:flex;flex-direction:column;gap:6px}
#vv-impressoes .p2-lin.vi2-tab .vi2-tri{gap:3px}
#vv-impressoes .p2-lin.vi2-tab .vi2-tri > .p2-cx{width:14px;height:4px;border-radius:2px;background:var(--d3-linha);box-shadow:none}
#vv-impressoes .p2-lin.vi2-tab .vi2-tri > .p2-cx.ok{background:var(--d3-pronto)}
#vv-impressoes .p2-lin.vi2-tab .vi2-tri > .p2-cx.at{background:var(--d3-tinta)}
#vv-impressoes .p2-lin.vi2-tab .vi2-tri > .p2-cx svg,#vv-impressoes .p2-lin.vi2-tab .vi2-tri > .p2-cx + .p2-cx::before{display:none}
#vv-impressoes .p2-lin.vi2-tab > :is(.vi2-onde,.vi2-forn){min-width:0;font:400 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;color:var(--d3-texto2);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
