#vv-pessoas .v2p-proj .d3pj-trilho{position:relative;height:22px}
#vv-pessoas .v2p-proj .d3pj-trilho::before{content:"";position:absolute;left:0;right:0;top:10px;height:2px;border-radius:1px;background:var(--d3-linha)}
