#vv-pessoas .v2p-proj .d3pj-ponto.at{width:18px;height:18px;border:3px solid var(--d3-tinta);background:var(--d3-cartao)}
#vv-pessoas .v2p-proj .d3pj-ponto.venc{border-color:var(--d3-perigo);background:var(--d3-perigo)}
#vv-pessoas .v2p-proj .d3pj-hoje{position:absolute;left:var(--x);top:0;bottom:0;border-left:2px dotted var(--d3-ajuste)}
