#vv-pessoas .v2p-proj .d3pj-datas > span.hoje{color:var(--d3-ajuste);font-weight:600}
@media (prefers-reduced-motion:reduce){#vv-pessoas .v2p-proj .d3pj-feito{animation:none}}
@media (max-width:900px){
  #vv-pessoas .v2p-proj .d3pj-nums{grid-template-columns:repeat(2,minmax(0,1fr))}
