/* ===== padrao-v2/d3-auditoria-janelas.css ===== */
/* Direção 3 · janelas da auditoria (14/11/2026): o planejamento aberto e o construtor de regra das Automações.
   Fundo areia, cartão branco canto 20, botão principal preto liso; o laranja cheio fica só no bloco de ação. */

/* ── Planejamento aberto (#workflow-modal.plj-janela, vybe-planejamentos.js) ─────────────────────────────────────
   O documento vem na moldura com a escolha clara (pljPreparaDocumento); em volta dele, areia e barras brancas. */
#workflow-modal.plj-janela.plj-modo-doc,#workflow-modal.plj-janela.plj-modo-editar{background:var(--d3-areia)}
#workflow-modal.plj-janela .plj-flut{border-radius:var(--d3-r-cartao);border:1px solid var(--d3-borda);background:var(--d3-cartao);box-shadow:0 12px 28px -20px rgba(31,29,26,.45);backdrop-filter:none}
#workflow-modal.plj-janela .plj-flut-x{width:36px;height:36px;background:var(--d3-trilho);color:var(--d3-tinta)}
#workflow-modal.plj-janela .plj-flut-x:hover{background:var(--d3-borda)}
#workflow-modal.plj-janela .plj-flut-links .cli-porta{height:36px;border-radius:999px;border-color:var(--d3-borda);background:var(--d3-cartao);color:var(--d3-tinta)}
#workflow-modal.plj-janela .plj-flut-links .cli-porta:hover{border-color:var(--d3-tinta);background:var(--d3-cartao)}
#workflow-modal.plj-janela .plj-flut-links .plj-flut-editar{border-color:var(--d3-borda);background:var(--d3-trilho)}
#workflow-modal.plj-janela .plj-flut-links .cli-porta:focus-visible,#workflow-modal.plj-janela .plj-flut-x:focus-visible{outline:2px solid var(--d3-tinta);outline-offset:2px}
/* A barra de baixo cabe na tela: a dica quebra linha em vez de passar por baixo dos botões. */
#workflow-modal.plj-janela .plj-flut-base{left:12px;max-width:none;box-sizing:border-box;flex-wrap:wrap;justify-content:flex-end}
#workflow-modal.plj-janela .plj-flut-base .plj-flut-dica{flex:1 1 220px;min-width:0;white-space:normal}
#workflow-modal.plj-janela .plj-flut-base > .plj-acoes-flut{display:flex;flex-wrap:wrap;align-items:center;justify-content:flex-end;gap:8px;min-width:0}
#workflow-modal.plj-janela .plj-flut-base > .plj-acoes-flut > :is(.workflow-primary,.workflow-secondary){height:40px;margin:0;padding:0 18px;border-radius:999px}
#workflow-modal.plj-janela .plj-flut-dica b{color:var(--d3-tinta)}
#workflow-modal.plj-janela:focus{outline:none}
/* Histórico: a linha do tempo era texto claro do tema escuro, sumia no fundo claro. */
#workflow-modal.plj-janela .plj-tempo b{color:var(--d3-tinta)}
#workflow-modal.plj-janela .plj-tempo small{color:var(--d3-apagado)}
#workflow-modal.plj-janela .plj-tempo p{color:var(--d3-texto2)}
#workflow-modal.plj-janela .plj-tempo li::before{background:var(--d3-borda)}
#workflow-modal.plj-janela .plj-tempo li.com-fala p{background:var(--d3-trilho);border-color:var(--d3-borda)}
#workflow-modal.plj-janela .plj-tempo li.ruim.com-fala p{background:var(--d3-perigo-veu);border-color:#F5C2C7}
@media (min-width:1000px){#workflow-modal.plj-janela .plj-flut-base{left:auto;max-width:calc(100% - 24px)}}

/* ── Automações › Nova regra (#auto-editor .auto-construtor, vybe-automacoes-ui.js) ────────────────────────────────
   Blocos à esquerda; à direita, a prévia em cartão claro e os botões juntos, presos ao rolar. O cabeçalho deixa
   livre o canto onde ficam o ⛶ e o ✕ da janela. */
#automacoes-root .auto-construtor{margin:0 0 20px;border:0;border-radius:var(--d3-r-cartao);background:var(--d3-cartao);box-shadow:0 1px 2px rgba(31,29,26,.05),0 12px 24px -18px rgba(31,29,26,.22);backdrop-filter:none;overflow:visible;grid-template-columns:minmax(0,1fr) 300px;column-gap:20px}
#automacoes-root .auto-construtor:focus{outline:none}
#automacoes-root .auto-construtor > .auto-construtor-topo{grid-column:1/-1;padding:20px 104px 16px 22px;border-bottom:1px solid var(--d3-linha)}
#automacoes-root .auto-construtor > .auto-bloco{grid-column:1;border-bottom:1px solid var(--d3-linha)}
#automacoes-root .auto-construtor > .auto-bloco:last-of-type{border-bottom:0}
#automacoes-root .auto-construtor-fechar{display:grid;place-items:center;width:34px;height:34px;padding:0;border-radius:50%;background:var(--d3-trilho);font-size:20px}
#automacoes-root .auto-construtor-fechar:hover{background:var(--d3-borda)}
#automacoes-root .auto-bloco-numero{border:1px solid var(--d3-borda);background:var(--d3-trilho)}
#automacoes-root .auto-bloco-numero > i{font-style:normal;color:var(--d3-tinta)}
#automacoes-root .auto-construtor > .auto-lado{grid-column:2;grid-row:2 / span 4;align-self:start;position:sticky;top:90px;display:grid;gap:12px;margin:20px 22px 20px 0}
#automacoes-root .auto-previa{display:grid;gap:8px;padding:16px 18px;border-radius:var(--d3-r-cartao);border:1px solid var(--d3-borda);background:var(--d3-trilho)}
#automacoes-root .auto-previa > span{color:var(--d3-apagado);font:600 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif}
#automacoes-root .auto-previa > b{color:var(--d3-tinta);font:600 var(--d3-fs-destaque)/1.45 var(--vv-texto,Inter),sans-serif}
#automacoes-root .auto-previa.incompleta > b{color:var(--d3-apagado);font-weight:500;font-size:var(--d3-fs-destaque)}
#automacoes-root .auto-previa > .auto-problema{margin:0;font:500 var(--d3-fs-texto)/1.5 var(--vv-texto,Inter),sans-serif;font-style:normal}
#automacoes-root .auto-c-botoes{display:flex;justify-content:flex-end;gap:8px}
#automacoes-root .auto-c-botoes > .v2g-btn{height:40px;padding:0 18px;border-radius:999px}
#automacoes-root .auto-c-botoes > .v2g-btn.k:disabled{opacity:1;background:var(--d3-linha);color:var(--d3-apagado);box-shadow:none;cursor:not-allowed}
@media (max-width:900px){
  #automacoes-root .auto-construtor{grid-template-columns:minmax(0,1fr)}
  #automacoes-root .auto-construtor > .auto-lado{grid-column:1;grid-row:auto;position:static;margin:0 16px 18px}
  #automacoes-root .auto-construtor > .auto-bloco:last-of-type{border-bottom:1px solid var(--d3-linha)}
}
@media (max-width:600px){
  #automacoes-root .auto-construtor > .auto-construtor-topo{padding:16px 104px 14px 16px}
  #automacoes-root .auto-construtor > .auto-bloco{padding:16px}
  #automacoes-root .auto-c-botoes > .v2g-btn{flex:1 1 0;height:44px}
}

/* ===== padrao-v2/d3-auditoria.css ===== */
/* Auditoria front x back (14/11/2026): acertos pequenos de várias telas, no padrão Direção 3.
   Ganha por especificidade (id da janela ou classe repetida), sem prioridade forçada. */

/* Sistema irmão no menu lateral (VybeHub ↗): agora é link de verdade; fica com a cara do item ao lado. */
#mundo-hud .vv-trilho a:is(.vv-trilho-btn,.vv-trilho-fav-item,[data-submodulo]),#mundo-hud .vv-setor > a[role="menuitem"]{text-decoration:none;cursor:pointer}

/* Saúde da carteira: "Filtros" aberto fica preto com texto branco (antes, branco sobre branco). */
#vv-carteira .v2c:is([data-tela="saude"],[data-tela="onboarding"]) .v2c-filtros > .v2c-btn:is(.k,[aria-expanded="true"]),
#vv-carteira .v2c:is([data-tela="saude"],[data-tela="onboarding"]) .v2c-filtros > .v2c-btn:is(.k,[aria-expanded="true"]):hover{background:var(--d3-tinta);color:#FFFFFF}

/* Contraste mínimo 4.5:1 (texto) e 3:1 (número grande). */
:is(#vv-comercial,.vv-setor-visao) .fv2.d3f .d3-num.q.q > .d3-num-v,#pv2-ia.d3f .d3-num.q.q > .d3-num-v{color:var(--vv-apagado,#6B675F)}
#vv-carteira .v2c-kpi.quieto.quieto > b,#vv-comercial.v2c .v2c-kpi.quieto.quieto > b,:is(#vv-comercial,.vv-setor-visao) .fv2-kpi.quieto.quieto > b,
:is(#pv2-painel,#pv2-semana,#pv2-demandas,#pv2-agenda,#pv2-ia) .pv2-kpi.quieto.quieto > b{color:var(--vv-apagado,#6B675F)}
body.mundo .vb-resumo-item.zero.zero,:is(#vv-carteira,#vv-comercial,#mundo-hud) .vb-resumo-item.zero.zero,.vs-resumo .vb-resumo-item.zero.zero{color:var(--vv-apagado,#6B675F)}
#vv-ferramentas.vc-janela :is(.vf-dica,.vf-cor small,.vf-qr.vazio p,.vf-link.vazio p){color:var(--vv-apagado,#6B675F)}
.vv-gestao.vv-gestao .g2-mais > summary > u{color:#A83D08}

/* Fala de agente sem ação: cartão claro (laranja cheio só no bloco com botão). O submódulo do trilho não muda. */
.vv-gestao.vv-gestao .g2-fala.g2-fala-quieta{background:var(--d3-cartao,#FFFFFF);color:var(--d3-tinta)}
.vv-gestao.vv-gestao .g2-fala.g2-fala-quieta .g2-fala-lin > p{color:var(--d3-tinta)}
.vv-gestao.vv-gestao .g2-fala.g2-fala-quieta .g2-quem{color:var(--d3-agente-texto,#4B36A8);opacity:1}
.vv-gestao.vv-gestao .g2-fala.g2-fala-quieta .g2-ag{background:var(--d3-agente,#6E56CF);color:#FFFFFF}
#vv-placa .v2e .v2n-fala.v2n-fala-quieta{background:var(--d3-cartao,#FFFFFF)}
#vv-placa .v2e .v2n-fala.v2n-fala-quieta > p,#vv-placa .v2e .v2n-fala.v2n-fala-quieta > p b{color:var(--d3-tinta)}
#vv-placa .v2e .v2n-fala.v2n-fala-quieta .v2n-quem{color:var(--d3-agente-texto,#4B36A8);opacity:1}
#vv-placa .v2e .v2n-fala.v2n-fala-quieta > .v2n-ag{background:var(--d3-agente,#6E56CF);color:#FFFFFF}

/* Anel de foco: baralho de aprovação e chips de filtro (o foco dos botões vem de --ds-foco, que vybe-mundo.css aplica). */
body.mundo .v2-baralho.v2-baralho:not(.d3h-baralho):focus-visible{outline:2px solid var(--d3-tinta);outline-offset:4px;border-radius:var(--d3-r-cartao,20px)}
#vv-hoje .d3h-baralho.d3h-baralho:focus-visible{box-shadow:0 0 0 2px #FFFFFF,0 0 0 4px var(--d3-tinta);border-radius:var(--d3-r-cartao,20px)}
body.mundo :is(.v2f-chip,.v2c-chip,.v2r-chip,.pv2-chip,.acao-chip,.vd-chip,.v2w-chip,.vb-chip,.d3h-chip,.v2p-chip){--ds-foco:0 0 0 2px #FFFFFF,0 0 0 4px #1F1D1A}

/* Camadas antigas por baixo do mundo: fora de uma tela antiga (mundo-modulo) ou da Gestão, o cabeçalho e o painel
   antigos não aparecem nem recebem foco. O modo clássico (?legado=1) não tem body.mundo e fica igual. */
body.mundo:not(.mundo-modulo):not(.mundo-gestao) > :is(header.app-header,.container,[id^="painel-"]:not(#painel-escritorio)){visibility:hidden}

/* Agenda no celular: um "+" só. O da barra de baixo (Criar) fica; marcar na agenda segue no "Marcar captação" do topo e
   no toque no dia ou na hora. A barrinha do cliente no mês termina em reticências. */
@media (max-width:600px){
  body.mundo #pv2-agenda .capt-fab.capt-fab{display:none}
  body.mundo #pv2-agenda .pv2a-mes-cartao .capt-cal.vista-mes .capt-mes .ag-chip.ag-chip span{text-overflow:ellipsis}
}

/* Loja: o cartão do item com "Comprar" inteiro (duas colunas quando a coluna estreita) e, em tela baixa, o corpo rola
   inteiro em vez de espremer a lista de conquistas atrás do "Seu título no mapa". */
#office-catalogo .v2l-grade.v2l-grade{grid-template-columns:repeat(auto-fill,minmax(180px,1fr))}
#office-catalogo .v2l-pe.v2l-pe > .v2l-btn{flex:none}
#office-catalogo .v2l-pe.v2l-pe{flex-wrap:wrap}
@media (min-width:861px) and (max-height:760px){
  #office-catalogo:not([data-aba="conquistas"]) .v2l-corpo.v2l-corpo{overflow-y:auto;scrollbar-width:thin}
  #office-catalogo:not([data-aba="conquistas"]) .v2l-corpo.v2l-corpo > :is(.v2l-esq,.v2l-conq){min-height:auto}
  #office-catalogo:not([data-aba="conquistas"]) .v2l-corpo .v2l-grade.v2l-grade,#office-catalogo:not([data-aba="conquistas"]) .v2l-corpo .v2l-escadas.v2l-escadas{flex:none;overflow:visible}
}

/* "Sem filtros" do painel antigo no mundo: pílula clara lisa, sem o degradê escuro do tema antigo (que agora vale só fora
   do mundo, em vybe-padrao.css). */
body.mundo #ops-clear-btn.ops-clear-btn{height:32px;padding:0 12px;border:0;border-radius:999px;background:var(--d3-cartao,#FFFFFF);box-shadow:inset 0 0 0 1px var(--d3-linha,#E6E0D6);font:600 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif}

/* ===== padrao-v2/d3-clientes.css ===== */
/* DIREÇÃO 3 · CLIENTES (moodboard 3 aprovado em 13/11/2026): Saúde da carteira, Onboarding, Gestão de clientes, ficha,
   Reuniões e as placas do centro comercial iguais aos quadros D3. Fundo areia, cartão branco de canto 20 só com título e
   conteúdo, o bloco de ação laranja como único laranja cheio, gráfico em linha e status em pílula clara com bolinha.
   Tudo ganha pelo id da janela e usa os tokens --d3-* de 0-d3-base.css. */

/* ===== Saúde da carteira e Onboarding (#vv-carteira, vybe-mundo-carteira.js) ===== */
#vv-carteira .v2c:is([data-tela="saude"],[data-tela="onboarding"]){gap:18px;padding:28px 36px 0;border-radius:inherit;background:var(--d3-areia)}
#vv-carteira .v2c:is([data-tela="saude"],[data-tela="onboarding"]) .v2c-corpo.vc-corpo{gap:14px;margin:0 -36px;padding:0 36px 28px}
#vv-carteira .v2c:is([data-tela="saude"],[data-tela="onboarding"]) .v2c-topo > h2{flex:none;font-size:var(--d3-fs-numero);letter-spacing:-.02em}
#vv-carteira .v2c:is([data-tela="saude"],[data-tela="onboarding"]) .d3c-meta{flex:1 1 120px;min-width:0;font:400 var(--d3-fs-destaque) var(--vv-texto,Inter),sans-serif;color:var(--d3-apagado);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#vv-carteira .v2c:is([data-tela="saude"],[data-tela="onboarding"]) .v2c-seg{background:var(--d3-trilho)}
#vv-carteira .v2c:is([data-tela="saude"],[data-tela="onboarding"]) .v2c-seg > button{height:32px;color:var(--d3-texto2);font-size:var(--d3-fs-texto)}
#vv-carteira .v2c:is([data-tela="saude"],[data-tela="onboarding"]) .v2c-seg > button[aria-pressed="true"]{background:var(--d3-tinta);color:#FFFFFF;box-shadow:none}
#vv-carteira .v2c:is([data-tela="saude"],[data-tela="onboarding"]) .v2c-btn{height:30px;background:var(--d3-trilho);box-shadow:none;color:var(--d3-tinta)}
#vv-carteira .v2c:is([data-tela="saude"],[data-tela="onboarding"]) .v2c-btn:hover{background:#E9E5DD;box-shadow:none}
#vv-carteira .v2c:is([data-tela="saude"],[data-tela="onboarding"]) .v2c-btn.g{height:40px;padding:0 16px;font-size:var(--d3-fs-texto)}
#vv-carteira .v2c:is([data-tela="saude"],[data-tela="onboarding"]) .v2c-topo .v2c-btn.g{background:var(--d3-cartao)}
#vv-carteira .v2c:is([data-tela="saude"],[data-tela="onboarding"]) .v2c-btn.d3c-novo::before{content:"+";margin-right:2px;font-size:var(--d3-fs-destaque);font-weight:500}
#vv-carteira .v2c:is([data-tela="saude"],[data-tela="onboarding"]) .v2c-btn:is(.k,[aria-expanded="true"]){background:var(--d3-tinta);color:#FFFFFF}
#vv-carteira .v2c:is([data-tela="saude"],[data-tela="onboarding"]) .v2c-x{width:40px;height:40px;background:var(--d3-cartao);box-shadow:none}
#vv-carteira .v2c:is([data-tela="saude"],[data-tela="onboarding"]) .v2c-card{padding:16px 18px;border-radius:var(--d3-r-cartao);background:var(--d3-cartao);box-shadow:none}
#vv-carteira .v2c:is([data-tela="saude"],[data-tela="onboarding"]) .v2c-card-topo > h2{font-size:var(--d3-fs-destaque);font-weight:700}
/* bloco de ação (o único laranja cheio) */
#vv-carteira .v2c:is([data-tela="saude"],[data-tela="onboarding"]) .d3-acao{padding:16px 20px;border-radius:22px;gap:14px}
#vv-carteira .v2c:is([data-tela="saude"],[data-tela="onboarding"]) .d3-acao > .d3-acao-av{width:36px;height:36px;font-size:var(--d3-fs-destaque)}
#vv-carteira .v2c:is([data-tela="saude"],[data-tela="onboarding"]) .d3-acao > .d3-acao-frase{font:600 var(--d3-fs-titulo)/1.25 var(--vv-titulo,"Inter Tight"),Inter,sans-serif;letter-spacing:-.01em}
#vv-carteira .v2c:is([data-tela="saude"],[data-tela="onboarding"]) .d3-acao > .d3-acao-btn{height:40px;padding:0 20px;font-size:var(--d3-fs-destaque)}
#vv-carteira .v2c .d3c-quem{display:block;margin-bottom:2px;font:600 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;opacity:.86;letter-spacing:0}
/* quatro números: rótulo, número que chega, mini linha ao lado e uma linha curta embaixo */
#vv-carteira .v2c .d3c-quatro{grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}
#vv-carteira .v2c .d3c-num{appearance:none;display:grid;grid-template-columns:max-content minmax(0,90px);justify-content:space-between;align-items:end;gap:6px 10px;margin:0;padding:14px 16px;border:0;border-radius:18px;background:var(--d3-cartao);color:var(--d3-tinta);font:400 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;text-align:left}
#vv-carteira .v2c button.d3c-num{cursor:pointer;transition:box-shadow .15s,transform .14s var(--vv-mola,cubic-bezier(.34,1.56,.64,1))}
#vv-carteira .v2c button.d3c-num:hover{box-shadow:inset 0 0 0 1px var(--d3-borda)}
#vv-carteira .v2c button.d3c-num:active{transform:scale(.98)}
#vv-carteira .v2c button.d3c-num:focus-visible{outline:2px solid var(--d3-acao);outline-offset:2px}
#vv-carteira .v2c .d3c-num > .d3-num-rot{grid-column:1 / -1;font-size:var(--d3-fs-texto);font-weight:400}
#vv-carteira .v2c .d3c-num > .d3-num-v{grid-column:1;font-size:36px;white-space:nowrap}
#vv-carteira .v2c .d3c-num > .d3-num-v > small{font-size:var(--d3-fs-titulo);color:var(--d3-apagado)}
#vv-carteira .v2c .d3c-num > .d3-graf{grid-column:2;grid-row:2;width:100%;max-width:90px;margin-bottom:4px}
#vv-carteira .v2c .d3c-num.r > .d3-graf polyline:not(.meta){stroke:var(--d3-perigo)}
#vv-carteira .v2c .d3c-num.r > .d3-graf circle{fill:var(--d3-perigo)}
#vv-carteira .v2c .d3c-num > .d3c-sub{grid-column:1 / -1;display:flex;flex-wrap:wrap;align-items:center;gap:5px;min-width:0;font-size:var(--d3-fs-texto);color:var(--d3-apagado)}
#vv-carteira .v2c .d3c-r{color:var(--d3-perigo)}
#vv-carteira .v2c .d3c-mini{display:inline-flex;align-items:center;height:20px;padding:0 7px;border-radius:999px;background:var(--d3-ajuste-veu);color:var(--d3-ajuste);font-size:var(--d3-fs-apoio);font-weight:700}
#vv-carteira .v2c .d3c-mini.g{background:var(--d3-pronto-veu);color:var(--d3-pronto)}
#vv-carteira .v2c .d3c-mini.r{background:var(--d3-perigo-veu);color:var(--d3-perigo)}
/* barra de filtro */
#vv-carteira .v2c:is([data-tela="saude"],[data-tela="onboarding"]) .v2c-filtros{gap:6px}
#vv-carteira .v2c:is([data-tela="saude"],[data-tela="onboarding"]) .v2c-chips{gap:6px}
#vv-carteira .v2c:is([data-tela="saude"],[data-tela="onboarding"]) .v2c-chip{height:32px;background:var(--d3-trilho);box-shadow:none;font-size:var(--d3-fs-texto)}
#vv-carteira .v2c:is([data-tela="saude"],[data-tela="onboarding"]) .v2c-chip:hover{background:#E9E5DD;box-shadow:none}
#vv-carteira .v2c:is([data-tela="saude"],[data-tela="onboarding"]) .v2c-chip[aria-pressed="true"]{background:var(--d3-tinta);color:#FFFFFF;font-weight:600}
#vv-carteira .v2c:is([data-tela="saude"],[data-tela="onboarding"]) .v2c-filtros > .v2c-btn{height:32px;background:var(--d3-cartao)}
#vv-carteira .v2c:is([data-tela="saude"],[data-tela="onboarding"]) .v2c-busca{height:38px;background:var(--d3-cartao);box-shadow:none}
#vv-carteira .v2c .d3c-ponto{flex:none;display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--d3-apagado)}
#vv-carteira .v2c .d3c-ponto.r{background:var(--d3-perigo)}
#vv-carteira .v2c .d3c-ponto.a{background:var(--d3-ajuste)}
#vv-carteira .v2c .d3c-ponto.g{background:var(--d3-pronto)}
#vv-carteira .v2c .d3c-sel{display:inline-flex;align-items:center;gap:4px;height:32px;padding:0 6px 0 12px;border-radius:999px;background:var(--d3-cartao);font:500 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;color:var(--d3-tinta)}
#vv-carteira .v2c .d3c-sel > select{appearance:auto;field-sizing:content;max-width:150px;height:28px;margin:0;padding:0 2px;border:0;background:transparent;color:inherit;font:inherit;cursor:pointer}
#vv-carteira .v2c .d3c-sel:focus-within{outline:2px solid var(--d3-acao);outline-offset:2px}
/* a lista da Saúde: cabeçalho, faixa do risco, nota, cliente, head, risco, o que tirou ponto e a ação */
#vv-carteira .v2c:is([data-tela="saude"],[data-tela="onboarding"]) .v2c-corpo > .v2c-quadro{flex:1 0 auto;position:relative;padding:14px 0 8px}
#vv-carteira .v2c .d3c-ordem{appearance:none;position:absolute;top:12px;right:18px;margin:0;padding:2px 4px;border:0;border-radius:6px;background:none;color:var(--d3-apagado);font:400 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;cursor:pointer}
#vv-carteira .v2c .d3c-ordem:hover{color:var(--d3-tinta);text-decoration:underline}
#vv-carteira .v2c[data-tela="saude"] .d3c-cab{display:grid;grid-template-columns:44px 230px 150px 100px minmax(0,1fr) 112px;gap:12px;padding:0 18px 8px 22px;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;color:var(--d3-apagado)}
#vv-carteira .v2c[data-tela="saude"] .v2c-linha{position:relative;border-top:1px solid var(--d3-linha)}
#vv-carteira .v2c .d3c-faixa{position:absolute;left:0;top:8px;width:4px;height:40px;border-radius:0 4px 4px 0;background:var(--d3-ajuste)}
#vv-carteira .v2c .d3c-faixa.r{background:var(--d3-perigo)}
#vv-carteira .v2c .d3c-faixa.g{background:var(--d3-pronto)}
#vv-carteira .v2c[data-tela="saude"] .v2c-lin{display:grid;grid-template-columns:minmax(0,1fr) 112px;gap:12px;padding:12px 18px 12px 22px}
#vv-carteira .v2c[data-tela="saude"] .v2c-abrir{display:grid;grid-template-columns:44px 230px 150px 100px minmax(0,1fr);gap:12px;align-items:center;font-size:var(--d3-fs-texto)}
#vv-carteira .v2c[data-tela="saude"] .v2c-nota{justify-self:start;width:auto;height:auto;border-radius:0;background:none;font:700 22px/1 var(--vv-titulo,"Inter Tight"),Inter,sans-serif;color:var(--d3-ajuste)}
#vv-carteira .v2c[data-tela="saude"] .v2c-nota.r{color:var(--d3-perigo)}
#vv-carteira .v2c[data-tela="saude"] .v2c-nota.g{color:var(--d3-pronto)}
#vv-carteira .v2c[data-tela="saude"] .v2c-quemc{width:auto}
#vv-carteira .v2c[data-tela="saude"] .v2c-quemc .cliente-carteira,#vv-carteira .v2c[data-tela="onboarding"] .v2c-nm .cliente-carteira{color:var(--carteira-texto,var(--d3-tinta));font-weight:700}
#vv-carteira .v2c .d3c-head{display:inline-flex;align-items:center;gap:7px;min-width:0;white-space:nowrap;overflow:hidden}
#vv-carteira .v2c .d3c-head > .v2c-av,#vv-carteira .v2c[data-tela="onboarding"] .v2c-abrir > .v2c-av{width:26px;height:26px;background:#EFEBE4;box-shadow:none;font-size:var(--d3-fs-mini);color:var(--d3-tinta)}
#vv-carteira .v2c .d3c-vago{color:var(--d3-apagado)}
#vv-carteira .v2c .d3c-pill{justify-self:start;display:inline-flex;align-items:center;gap:5px;height:22px;padding:0 9px;border-radius:999px;background:var(--d3-trilho);color:var(--d3-texto2);font:600 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;white-space:nowrap}
#vv-carteira .v2c .d3c-perdas{display:flex;gap:14px;min-width:0;overflow:hidden;font-size:var(--d3-fs-texto);white-space:nowrap;color:var(--d3-texto2)}
#vv-carteira .v2c .d3c-perdas > span > b{color:var(--d3-tinta)}
#vv-carteira .v2c .d3c-perdas > span.r,#vv-carteira .v2c .d3c-perdas > span.r > b{color:var(--d3-perigo)}
#vv-carteira .v2c .d3c-perdas > span.g{color:var(--d3-pronto)}
#vv-carteira .v2c[data-tela="saude"] .v2c-ac{width:auto}
#vv-carteira .v2c[data-tela="saude"] .v2c-det{padding:0 18px 12px 78px}
/* rodapé: quanto cada sinal tira e o que ficou recolhido */
#vv-carteira .v2c .d3c-pe{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin-top:auto;padding:10px 18px 4px 22px;border-top:1px solid var(--d3-linha)}
#vv-carteira .v2c .d3c-pe-rot{margin-right:4px;font-size:var(--d3-fs-texto);color:var(--d3-apagado)}
#vv-carteira .v2c .d3c-tira{display:inline-flex;align-items:center;height:26px;padding:0 10px;border-radius:999px;background:var(--d3-trilho);color:var(--d3-tinta);font:600 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif}
#vv-carteira .v2c .d3c-tira.r{background:var(--d3-perigo-veu);color:var(--d3-perigo)}
#vv-carteira .v2c .d3c-pe > .v2c-btn{height:28px}
#vv-carteira .v2c:is([data-tela="saude"],[data-tela="onboarding"]) .v2c-vazio{padding:14px 22px 4px}
/* Mês a mês em linha */
#vv-carteira .v2c .d3c-serie{margin-top:12px}
#vv-carteira .v2c .d3c-serie > .d3-graf{max-height:140px}
#vv-carteira .v2c .d3c-meses{display:flex;justify-content:space-between;gap:6px;margin-top:8px;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;color:var(--d3-apagado)}
#vv-carteira .v2c .d3c-meses > span{display:flex;flex-direction:column;align-items:center}
#vv-carteira .v2c .d3c-meses > span > b{font-weight:600;color:var(--d3-texto2)}
#vv-carteira .v2c .d3c-meses > .agora{font-weight:700;color:var(--d3-tinta)}
