#vv-comercial.v2c.d3c .d3-num > .d3-num-rot{font-size:var(--d3-fs-texto);font-weight:400}
#vv-comercial.v2c.d3c .d3-num > .d3-num-v{font-size:36px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#vv-comercial.v2c.d3c .d3-num.d3c-longo > .d3-num-v{font-size:26px;line-height:36px}
/* Cartão estreito (celular, dois por linha): "Sem campeão" virava "Sem cam...". O número diminui com o cartão. */
#vv-comercial.v2c.d3c .d3c-nums > .d3-num{container-type:inline-size}
@container (max-width:200px){
  #vv-comercial.v2c.d3c .d3c-nums > .d3-num > .d3-num-v{font-size:clamp(18px,15cqi,26px);line-height:1.15}
