/* Filtros: chips com menu e a busca. */
#vv-hoje .d3h-co .v2o-sem-filtros{display:flex;flex-wrap:wrap;align-items:center;gap:6px;padding:0 18px}
#vv-hoje .d3h-co .v2o-sem-busca{flex:0 1 220px;min-width:120px;height:32px;box-sizing:border-box;padding:0 12px;border:0;border-radius:999px;background:var(--d3-trilho);color:var(--d3-tinta);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif)}
