#vv-hoje .d3h-co .v2o-sem-quem > small{font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#vv-hoje .d3h-co .v2o-sem-ab.a{color:var(--d3-ajuste);font-weight:600}
