#vv-hoje .d3h-co .v2o-sem-dia > small{font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado)}
#vv-hoje .d3h-co .v2o-sem-dia.hoje{background:var(--d3-trilho)}
#vv-hoje .d3h-co .v2o-sem-avisos{display:flex;flex-wrap:wrap;gap:4px;min-width:0}
#vv-hoje .d3h-co .v2o-sem-cel{display:flex;flex-direction:column;gap:6px;min-width:0;min-height:44px;padding:6px;border-radius:14px;background:var(--d3-trilho);transition:box-shadow .15s ease,background .15s ease}
#vv-hoje .d3h-co .v2o-sem-cel.antes{background:transparent;box-shadow:inset 0 0 0 1px var(--d3-borda)}
#vv-hoje .d3h-co .v2o-sem-cel.passou{box-shadow:inset 0 0 0 1.5px var(--d3-perigo)}
#vv-hoje .d3h-co .v2o-sem-cel.solta-aqui,#vv-hoje .d3h-co .v2o-sem-cel.alvo{background:var(--d3-cartao);box-shadow:inset 0 0 0 2px var(--d3-tinta)}
#vv-hoje .d3h-co .v2o-sem-linha.ninguem .v2o-sem-cel{background:transparent;outline:1px dashed var(--d3-borda);outline-offset:-1px}
#vv-hoje .d3h-co .v2o-sem-cel-top{display:flex;flex-wrap:wrap;align-items:center;gap:4px;min-width:0}
#vv-hoje .d3h-co .v2o-conta{display:inline-flex;align-items:baseline;height:22px;padding:0 8px;border-radius:999px;background:var(--d3-cartao);color:var(--d3-tinta);font:700 var(--d3-fs-texto)/22px var(--vv-texto,Inter,sans-serif);font-variant-numeric:tabular-nums}
#vv-hoje .d3h-co .v2o-conta > small{font-weight:500;color:var(--d3-apagado)}
#vv-hoje .d3h-co .v2o-conta.cheia{box-shadow:inset 0 0 0 1px var(--d3-tinta)}
#vv-hoje .d3h-co .v2o-conta.r{background:var(--d3-perigo);color:#FFFFFF}
#vv-hoje .d3h-co .v2o-conta.r > small{color:#FFFFFF}
#vv-hoje .d3h-co .v2o-sem-filtradas{font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado)}

/* A peça: cliente com a cor da carteira e o ⋯; formato e status; prazo e no ar (cada data muda no lugar). */
#vv-hoje .d3h-co .v2o-gp{display:flex;flex-direction:column;gap:4px;min-width:0;padding:7px 8px;border-radius:12px;background:var(--d3-cartao);box-shadow:0 1px 0 var(--d3-borda);cursor:grab;animation:d3NumChega .4s cubic-bezier(.22,1,.36,1) both}
#vv-hoje .d3h-co .v2o-gp.arrastando{opacity:.45}
#vv-hoje .d3h-co .v2o-gp.movendo{box-shadow:inset 0 0 0 1.5px var(--d3-tinta)}
#vv-hoje .d3h-co .v2o-gp-top{display:flex;align-items:center;gap:4px;min-width:0}
#vv-hoje .d3h-co .v2o-gp-cli{flex:1 1 auto;min-width:0;font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#vv-hoje .d3h-co .v2o-gp-cli .cliente-carteira.cliente-carteira{padding:0;border:0;background:none;box-shadow:none;font-weight:600;color:var(--d3-tinta)}
#vv-hoje .d3h-co .v2o-gp-cli .cliente-carteira.cliente-carteira[data-carteira="vinicius"]{color:var(--d3-cart-vinicius)}
#vv-hoje .d3h-co .v2o-gp-cli .cliente-carteira.cliente-carteira[data-carteira="ewerton"]{color:var(--d3-cart-ewerton)}
#vv-hoje .d3h-co .v2o-gp-sem{font-weight:400;color:var(--d3-apagado)}
#vv-hoje .d3h-co .v2o-gp-top .vb-menu-linha{flex:none}
#vv-hoje .d3h-co .v2o-gp-top .vb-pt3{width:24px;height:24px}
#vv-hoje .d3h-co .v2o-gp-meio{display:flex;flex-wrap:wrap;align-items:center;gap:4px;min-width:0}
#vv-hoje .d3h-co .v2o-gp-f{font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-texto2);white-space:nowrap}
#vv-hoje .d3h-co .v2o-st{display:inline-flex;align-items:center;gap:4px;max-width:100%;height:20px;padding:0 7px;border-radius:999px;background:var(--d3-trilho);color:var(--d3-texto2);font:600 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#vv-hoje .d3h-co .v2o-st > i{flex:none;width:6px;height:6px;border-radius:50%;background:var(--d3-st,var(--d3-meta))}
#vv-hoje .d3h-co .v2o-st.a{background:var(--d3-ajuste);color:#FFFFFF}
#vv-hoje .d3h-co .v2o-st.r{background:var(--d3-perigo);color:#FFFFFF}
#vv-hoje .d3h-co .v2o-st.g{background:var(--d3-pronto);color:#FFFFFF}
#vv-hoje .d3h-co .v2o-gp-datas{display:flex;flex-wrap:wrap;gap:2px 8px;min-width:0}
#vv-hoje .d3h-co .v2o-gp-d{appearance:none;margin:0;padding:0;border:0;background:none;color:var(--d3-tinta);font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);white-space:nowrap;cursor:pointer;border-radius:6px}
#vv-hoje .d3h-co .v2o-gp-d > i{font-style:normal;font-weight:400;color:var(--d3-apagado)}
#vv-hoje .d3h-co .v2o-gp-d.ruim{color:var(--d3-perigo);font-weight:600}
#vv-hoje .d3h-co .v2o-gp-d:hover{text-decoration:underline}
#vv-hoje .d3h-co .v2o-gp-d input.vb-no-lugar{width:100%;max-width:140px;font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif)}
#vv-hoje .d3h-co .v2o-gp-para{display:flex;flex-wrap:wrap;gap:4px;padding-top:4px;border-top:1px solid var(--d3-linha)}
#vv-hoje .d3h-co .v2o-gp-para > .v2o-chip{height:26px;padding:0 8px}
#vv-hoje .d3h-co .v2o-gp-para > .v2o-chip.fora{opacity:.7}
#vv-hoje .d3h-co .v2o-gp-para > .v2o-btn{height:26px;padding:0 10px}

/* O OK do mover: na célula de destino, a linha que abre no lugar. */
#vv-hoje .d3h-co .v2o-sem-conf{display:flex;flex-direction:column;gap:6px;min-width:0;padding:8px;border-radius:12px;background:var(--d3-cartao);box-shadow:0 6px 18px rgba(31,29,26,.12);animation:d3NumChega .35s cubic-bezier(.22,1,.36,1) both}
#vv-hoje .d3h-co .v2o-sem-conf > b{font:600 var(--d3-fs-texto)/1.35 var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);overflow-wrap:anywhere}
#vv-hoje .d3h-co .v2o-avisos{display:flex;flex-wrap:wrap;gap:4px}
#vv-hoje .d3h-co .v2o-sem-conf-bt{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:6px}
#vv-hoje .d3h-co .v2o-sem-conf-bt > .v2o-btn{height:28px;padding:0 12px}

/* Celular: a lista por dia (a grade some). */
#vv-hoje .d3h-co .v2o-sem-lista{display:none;flex-direction:column;gap:10px;padding:0 12px}
#vv-hoje .d3h-co .v2o-sem-ldia{display:flex;flex-direction:column;gap:8px;padding:8px;border-radius:16px;background:var(--d3-trilho)}
#vv-hoje .d3h-co .v2o-sem-ldia.hoje{box-shadow:inset 0 0 0 1.5px var(--d3-tinta)}
#vv-hoje .d3h-co .v2o-sem-ldia > .v2o-sem-dia{padding:2px 4px}
#vv-hoje .d3h-co .v2o-sem-ldia > .v2o-nota{padding:0 4px 4px}
#vv-hoje .d3h-co .v2o-sem-lpes{display:flex;flex-direction:column;gap:6px;min-width:0}
#vv-hoje .d3h-co .v2o-sem-lquem{display:flex;flex-wrap:wrap;align-items:center;gap:6px;padding:0 4px;font:700 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}
/* O controle manual vem primeiro: indicadores (o número abre a lista no lugar), fichas por pessoa e a grade. */
#vv-hoje .d3h-co .v2o-man{display:flex;flex-direction:column;gap:14px;min-width:0}
#vv-hoje .d3h-co .v2o-inds{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px}
#vv-hoje .d3h-co .v2o-ind{appearance:none;border:0;text-align:left;cursor:pointer;font:inherit}
#vv-hoje .d3h-co .v2o-ind[aria-expanded="true"]{box-shadow:inset 0 0 0 2px var(--d3-tinta)}
#vv-hoje .d3h-co .v2o-ind.k > .d3-num-v{color:var(--d3-acao-texto)}
#vv-hoje .d3h-co .v2o-ind.k{box-shadow:inset 0 0 0 1.5px var(--d3-acao)}
#vv-hoje .d3h-co .v2o-ind.k[aria-expanded="true"]{box-shadow:inset 0 0 0 2px var(--d3-acao)}
#vv-hoje .d3h-co .v2o-ind-lista{padding-bottom:8px}
#vv-hoje .d3h-co .v2o-ind-lista > .d3h-cab{display:flex;align-items:center;justify-content:space-between}
#vv-hoje .d3h-co .v2o-il-ul{margin:0;padding:0;list-style:none}
#vv-hoje .d3h-co .v2o-il{display:flex;flex-wrap:wrap;align-items:center;gap:6px 10px;padding:9px 18px;border-top:1px solid var(--d3-linha);animation:d3NumChega .35s cubic-bezier(.22,1,.36,1) both}
#vv-hoje .d3h-co .v2o-il-cli{flex:none;font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif)}
#vv-hoje .d3h-co .v2o-il-cli .cliente-carteira.cliente-carteira{padding:0;border:0;background:none;box-shadow:none;font-weight:600;color:var(--d3-tinta)}
#vv-hoje .d3h-co .v2o-il-cli .cliente-carteira.cliente-carteira[data-carteira="vinicius"]{color:var(--d3-cart-vinicius)}
#vv-hoje .d3h-co .v2o-il-cli .cliente-carteira.cliente-carteira[data-carteira="ewerton"]{color:var(--d3-cart-ewerton)}
#vv-hoje .d3h-co .v2o-il-nome{flex:1 1 160px;min-width:0;font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#vv-hoje .d3h-co .v2o-il-q{font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-texto2)}
#vv-hoje .d3h-co .v2o-il-q > em{font-style:normal;color:var(--d3-ajuste)}
#vv-hoje .d3h-co .v2o-il-ac{display:inline-flex;gap:6px;margin-left:auto}
#vv-hoje .d3h-co .v2o-il > .v2o-gp-para,#vv-hoje .d3h-co .v2o-il > .v2o-sem-conf{flex:1 1 100%}
#vv-hoje .d3h-co .v2o-fichas{display:flex;flex-wrap:wrap;gap:4px;margin:0 18px;padding:4px;border-radius:999px;background:var(--d3-trilho);align-self:flex-start;max-width:calc(100% - 36px);box-sizing:border-box}
#vv-hoje .d3h-co .v2o-fichas > button{appearance:none;display:inline-flex;align-items:center;gap:6px;height:32px;padding:0 14px;border:0;border-radius:999px;background:transparent;color:var(--d3-texto2);font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);cursor:pointer;transition:background .2s ease,color .2s ease}
#vv-hoje .d3h-co .v2o-fichas > button > small{font:600 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado)}
#vv-hoje .d3h-co .v2o-fichas > button > small.a{color:var(--d3-ajuste)}
#vv-hoje .d3h-co .v2o-fichas > button[aria-pressed="true"]{background:var(--d3-tinta);color:var(--d3-cartao);font-weight:600}
#vv-hoje .d3h-co .v2o-fichas > button[aria-pressed="true"] > small{color:var(--d3-meta)}
#vv-hoje .d3h-co .v2o-gp-q{font:700 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}

/* Mês: o calendário (segunda a domingo), cada dia uma célula que recebe a peça arrastada. */
#vv-hoje .d3h-co .v2o-cal{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:6px;padding:0 12px}
#vv-hoje .d3h-co .v2o-cal-dow{padding:0 6px;font:600 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado)}
#vv-hoje .d3h-co .v2o-cal-dia{display:flex;flex-direction:column;gap:6px;min-width:0;min-height:72px;padding:6px;border-radius:14px;background:var(--d3-trilho);transition:box-shadow .15s ease,background .15s ease}
#vv-hoje .d3h-co .v2o-cal-dia.fora{opacity:.55}
#vv-hoje .d3h-co .v2o-cal-dia.hoje{box-shadow:inset 0 0 0 1.5px var(--d3-tinta)}
#vv-hoje .d3h-co .v2o-cal-dia.passou{box-shadow:inset 0 0 0 1.5px var(--d3-perigo)}
#vv-hoje .d3h-co .v2o-cal-dia.solta-aqui,#vv-hoje .d3h-co .v2o-cal-dia.alvo{background:var(--d3-cartao);box-shadow:inset 0 0 0 2px var(--d3-tinta)}
#vv-hoje .d3h-co .v2o-cal-top{display:flex;flex-wrap:wrap;align-items:center;gap:4px;min-width:0}
#vv-hoje .d3h-co .v2o-cal-top > b{margin-right:2px;font:700 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}

/* As sugestões do Heitor: recolhidas, com tudo o que tinham; abrem no lugar. */
#vv-hoje .d3h-co .v2o-heitor{padding:0}
#vv-hoje .d3h-co .v2o-heitor-cab{appearance:none;display:flex;align-items:center;gap:10px;width:100%;margin:0;padding:14px 18px;border:0;background:none;color:var(--d3-tinta);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
#vv-hoje .d3h-co .v2o-heitor-cab > b{font:700 var(--d3-fs-destaque) var(--vv-texto,Inter,sans-serif)}
#vv-hoje .d3h-co .v2o-heitor-cab > small{flex:1;min-width:0;color:var(--d3-apagado);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#vv-hoje .d3h-co .v2o-heitor-cab > svg{flex:none;transition:transform .25s ease}
#vv-hoje .d3h-co .v2o-heitor-cab[aria-expanded="true"] > svg{transform:rotate(180deg)}
#vv-hoje .d3h-co .v2o-heitor-av{flex:none;display:grid;place-items:center;width:28px;height:28px;border-radius:50%;background:var(--d3-agente);color:var(--d3-cartao);font:800 var(--d3-fs-apoio) var(--vv-titulo,Inter,sans-serif)}
#vv-hoje .d3h-co .v2o-heitor > .v2-mais > div{display:flex;flex-direction:column;gap:14px}
#vv-hoje .d3h-co .v2o-heitor[aria-expanded="true"] > .v2-mais > div{padding:0 14px 14px}
#vv-hoje .d3h-co .v2o-heitor[aria-expanded="false"] > .v2-mais{visibility:hidden;transition:grid-template-rows .28s var(--vv-suave,cubic-bezier(.22,1,.36,1)),visibility 0s .28s}
#vv-hoje .d3h-co .v2o-heitor .d3h-cartao{background:var(--d3-trilho)}

@container hoje (max-width:1100px){
  #vv-hoje .d3h-co .v2o-inds{grid-template-columns:repeat(3,minmax(0,1fr))}
}
@container hoje (max-width:760px){
  #vv-hoje .d3h-co .v2o-sem-grade{display:none}
  #vv-hoje .d3h-co .v2o-sem-lista{display:flex}
  #vv-hoje .d3h-co .v2o-sem-faixa{margin-right:0;flex:1 1 auto}
  #vv-hoje .d3h-co .v2o-sem-busca{flex:1 1 100%}
  #vv-hoje .d3h-co .v2o-cal{display:none}
  #vv-hoje .d3h-co .v2o-inds{grid-template-columns:repeat(2,minmax(0,1fr))}
  #vv-hoje .d3h-co .v2o-fichas{border-radius:18px}
  #vv-hoje .d3h-co .v2o-il-ac{margin-left:0}
}
@media (prefers-reduced-motion:reduce){
  #vv-hoje .d3h-co .v2o-gp,#vv-hoje .d3h-co .v2o-sem-conf,#vv-hoje .d3h-co .v2o-il{animation:none}
  #vv-hoje .d3h-co .v2o-heitor-cab > svg{transition:none}
}

/* ===== padrao-v2/d3-faltas.css ===== */
/* DIREÇÃO 3 · O QUE FALTOU DOS QUADROS (14/11/2026, aprovado pelo Paulo). Cinco peças:
   1 confirmação perigosa (#vb-apagar, vbConfirmarApagar em vybe-core.js; quadro D3-Fam-Confirmacoes),
   2 "Semana de dd/mm" na Nova demanda (#fc-overlay .nd-semana; quadro D3-NovaDemanda),
   3 topo da Agenda com Semana, Mês, Roteiros e Mais (#pv2-agenda-topo .d3ag-vistas; quadro D3-Agenda),
   4 "Editar" e "Confirmar N" em lote na Fila do Danilo e na Coordenação (quadros D3-Criacao e D3-Coordenacao),
   5 rótulo "Gestão" ao lado do título de Clientes (quadro D3-GestaoClientes).
   Sem regra com importância: a força vem do id da janela. */

/* ===== 1. CONFIRMAÇÃO PERIGOSA ===== */
#vb-apagar .vb-apagar-caixa.vb-apagar-caixa{display:flex;flex-direction:column;gap:12px;width:min(340px,100%)}
#vb-apagar .vb-apagar-caixa .vb-apagar-ic{flex:none;display:inline-grid;place-items:center;width:40px;height:40px;border-radius:999px;background:var(--d3-perigo-veu);color:var(--d3-perigo)}
#vb-apagar .vb-apagar-caixa .vb-apagar-t{font-size:var(--d3-fs-destaque)}
#vb-apagar .vb-apagar-caixa .vb-apagar-x{margin:0;font-size:var(--d3-fs-texto);color:var(--d3-texto2)}
#vb-apagar .vb-apagar-caixa .vb-apagar-rot{margin-bottom:-6px;font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}
#vb-apagar .vb-apagar-caixa .vb-apagar-c{appearance:none;width:100%;height:40px;box-sizing:border-box;margin:0;padding:0 14px;border:0;border-radius:12px;background:var(--d3-cartao);box-shadow:inset 0 0 0 1.5px var(--d3-borda);color:var(--d3-tinta);font:500 var(--d3-fs-destaque) var(--vv-texto,Inter,sans-serif);letter-spacing:.04em;outline:0;transition:box-shadow .15s}
