#vv-hoje .d3h :is(h2,h3,p,ul,ol){margin:0}
#vv-hoje .d3h :is(ul,ol){padding:0;list-style:none}

/* Topo: "Hoje" e a data à esquerda; as abas (preto na escolhida) e os atalhos à direita. */
#vv-hoje .d3h-topo{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px 14px;min-width:0}
#vv-hoje .d3h-ola{display:flex;align-items:center;flex-wrap:wrap;gap:6px 14px;min-width:0}
#vv-hoje .d3h-ola > h2{margin:0;font:700 var(--d3-fs-numero)/1.1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.02em;color:var(--d3-tinta)}
#vv-hoje .d3h-ola > small{font:400 var(--d3-fs-destaque)/1.2 var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado);white-space:nowrap}
#vv-hoje .d3h-topo-dir{display:flex;align-items:center;flex-wrap:wrap;justify-content:flex-end;gap:8px;margin-left:auto;min-width:0}
#vv-hoje .d3h-topo .vv-seg{display:inline-flex;width:auto;gap:0;padding:4px;border:0;border-radius:999px;background:var(--d3-trilho);box-shadow:none}
#vv-hoje .d3h-topo .vv-seg > button{flex:none;height:32px;padding:0 14px;border:0;border-radius:999px;background:transparent;color:var(--d3-texto2);font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);box-shadow:none;cursor:pointer;white-space:nowrap}
#vv-hoje .d3h-topo .vv-seg > button[aria-selected="true"]{background:var(--d3-tinta);color:#FFFFFF;font-weight:600;animation:d3hAbaEstica .35s cubic-bezier(.22,1,.36,1) both}
