#vv-hoje .d3h-topo .vv-hoje-criar > svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:2.2;stroke-linecap:round}
#vv-hoje .d3h-online{display:inline-flex;align-items:center;gap:8px;min-width:0}
#vv-hoje .d3h-avs{display:inline-flex}
#vv-hoje .d3h-avs > i{display:grid;place-items:center;width:26px;height:26px;margin-left:-6px;border-radius:50%;background:var(--d3-trilho);box-shadow:0 0 0 2px var(--d3-areia);color:var(--d3-tinta);font:700 10px var(--vv-texto,Inter,sans-serif);font-style:normal}
#vv-hoje .d3h-avs > i:first-child{margin-left:0}
#vv-hoje .d3h-online > small{font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
@keyframes d3hAbaEstica{from{transform:scaleX(.7);opacity:.4}to{transform:none;opacity:1}}

/* A faixa laranja: frase grande, o rosto do agente pulsando, os passos numerados e um botão branco. */
#vv-hoje .d3h-acao{padding:16px 20px;border-radius:22px;gap:14px;font:600 var(--d3-fs-titulo)/1.25 var(--vv-titulo,"Inter Tight",Inter,sans-serif)}
#vv-hoje .d3h-acao > .d3-acao-av{width:36px;height:36px;font-size:var(--d3-fs-destaque)}
#vv-hoje .d3h-acao > .d3-acao-frase{display:flex;flex-direction:column;gap:1px;white-space:nowrap}
#vv-hoje .d3h-acao > .d3-acao-frase > small{font:700 var(--d3-fs-apoio)/1.2 var(--vv-texto,Inter,sans-serif);opacity:.85;overflow:hidden;text-overflow:ellipsis}
#vv-hoje .d3h-acao > .d3-acao-btn{height:40px;padding:0 20px;font-size:var(--d3-fs-destaque);transition:transform .15s}
#vv-hoje .d3h-acao > .d3-acao-btn:active{transform:scale(.96)}
#vv-hoje .d3h-acao-passos{flex:0 1 auto;display:flex;gap:6px;min-width:0;overflow:hidden}
#vv-hoje .d3h-acao-passos > li{min-width:0;max-width:220px;flex:0 1 auto;display:flex}
#vv-hoje .d3h-acao-passos button{appearance:none;display:inline-flex;align-items:center;gap:6px;max-width:100%;min-width:0;height:30px;padding:0 12px 0 4px;border:0;border-radius:999px;background:rgba(255,255,255,.16);color:#FFFFFF;font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);cursor:pointer}
#vv-hoje .d3h-acao-passos button:hover{background:rgba(255,255,255,.26)}
#vv-hoje .d3h-acao-passos i{flex:none;display:grid;place-items:center;width:22px;height:22px;border-radius:50%;background:#FFFFFF;color:var(--d3-acao-texto);font:700 var(--d3-fs-mini) var(--vv-texto,Inter,sans-serif);font-style:normal}
#vv-hoje .d3h-acao-passos span{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

/* Números: rótulo, número que chega (o "/ total" menor), linha ao lado ou barra embaixo, nota curta. */
#vv-hoje .d3h-nums{display:grid;grid-auto-flow:column;grid-auto-columns:minmax(0,1fr);gap:12px}
#vv-hoje .d3h-num{appearance:none;box-sizing:border-box;min-height:104px;margin:0;padding:14px 16px;border:0;border-radius:18px;background:var(--d3-cartao);color:var(--d3-tinta);font:inherit;text-align:left}
#vv-hoje button.d3h-num{cursor:pointer;transition:box-shadow .2s}
#vv-hoje button.d3h-num:hover{box-shadow:0 10px 24px -18px rgba(31,29,26,.45)}
#vv-hoje .d3h-num > .d3-num-rot{font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado)}
#vv-hoje .d3h-num-linha{display:flex;align-items:flex-end;justify-content:space-between;gap:10px;min-width:0}
#vv-hoje .d3h-num-linha > .d3-num-v{min-width:0;font:700 36px/1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.02em;color:var(--d3-tinta);white-space:nowrap;font-variant-numeric:tabular-nums;animation:d3NumChega .55s cubic-bezier(.22,1,.36,1) both}
#vv-hoje .d3h-num-linha > .d3-num-v > small{font:600 var(--d3-fs-titulo) var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:0;color:var(--d3-apagado)}
#vv-hoje .d3h-num-linha > .d3-graf{flex:none;width:90px}
#vv-hoje .d3h-num.r .d3-num-v{color:var(--d3-perigo)}
#vv-hoje .d3h-num.r .d3-graf polyline:not(.meta){stroke:var(--d3-perigo)}
#vv-hoje .d3h-num.r .d3-graf circle{fill:var(--d3-perigo)}
#vv-hoje .d3h-num.a .d3-num-v{color:var(--d3-ajuste)}
#vv-hoje .d3h-num.g .d3-num-v{color:var(--d3-pronto)}
#vv-hoje .d3h-num > .d3-barra{margin-top:4px}
#vv-hoje .d3h-num-sub{font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#vv-hoje .d3h-num-sub.r{color:var(--d3-perigo)}
#vv-hoje .d3h-num-sub.a{color:var(--d3-ajuste)}
#vv-hoje .d3h-num-sub.g{color:var(--d3-pronto)}
#vv-hoje .d3h-nums > :nth-child(2) .d3-num-v{animation-delay:.15s}
#vv-hoje .d3h-nums > :nth-child(3) .d3-num-v{animation-delay:.3s}
#vv-hoje .d3h-nums > :nth-child(4) .d3-num-v{animation-delay:.45s}
#vv-hoje .d3h-nums > :nth-child(2) .d3-barra > i{animation-delay:.25s}
#vv-hoje .d3h-nums > :nth-child(3) .d3-barra > i{animation-delay:.4s}

/* Três colunas de cartões; a primeira coluna com um cartão só vai até o fim (Pede ação, Minhas tarefas). */
#vv-hoje .d3h-grade{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(0,1fr) minmax(0,.85fr);gap:14px;align-items:stretch}
#vv-hoje .d3h-tf .d3h-grade{grid-template-columns:minmax(0,1.9fr) minmax(0,1fr) minmax(0,.9fr)}
#vv-hoje .d3h-col{display:flex;flex-direction:column;gap:14px;min-width:0}
#vv-hoje .d3h-col > .d3h-cartao:only-child{flex:1 1 auto}
#vv-hoje .d3h-cartao{display:flex;flex-direction:column;min-width:0;box-sizing:border-box;padding:14px 0 8px;border-radius:var(--d3-r-cartao);background:var(--d3-cartao)}
#vv-hoje .d3h-cab{display:flex;align-items:center;justify-content:space-between;gap:10px;min-width:0;padding:0 18px 8px}
#vv-hoje .d3h-cab > h3{flex:none;margin:0;font:700 var(--d3-fs-destaque)/1.25 var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);white-space:nowrap}
#vv-hoje .d3h-aux{display:inline-flex;align-items:center;gap:8px;min-width:0;font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#vv-hoje .d3h-corpo{display:flex;flex-direction:column;min-width:0}
#vv-hoje .d3h-pe{display:flex;flex-wrap:wrap;align-items:center;gap:6px 10px;margin-top:auto;padding:10px 18px 4px;border-top:1px solid var(--d3-linha);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado)}
#vv-hoje .d3h-vazio{margin:0;padding:10px 18px;border-top:1px solid var(--d3-linha);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado)}
#vv-hoje .d3h-link{appearance:none;margin:0;padding:0;border:0;background:none;color:var(--d3-tinta);font:inherit;text-decoration:underline;text-decoration-color:#C9C2B6;text-underline-offset:3px;cursor:pointer}
#vv-hoje .d3h-link:hover{text-decoration-color:var(--d3-tinta)}
#vv-hoje .d3h-mais{align-self:flex-start;margin:8px 18px 2px;font-size:var(--d3-fs-texto)}
#vv-hoje .d3h-btn{appearance:none;display:inline-flex;align-items:center;justify-content:center;gap:6px;height:36px;padding:0 16px;border:0;border-radius:999px;background:var(--d3-trilho);color:var(--d3-tinta);font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);white-space:nowrap;cursor:pointer;transition:transform .15s,background-color .2s}
#vv-hoje .d3h-btn:hover{background:var(--d3-linha)}
#vv-hoje .d3h-btn:active{transform:scale(.96)}
#vv-hoje .d3h-btn.k{background:var(--d3-tinta);color:#FFFFFF;font-weight:600}
#vv-hoje .d3h-btn.s{height:30px;padding:0 12px;font-size:var(--d3-fs-texto)}
#vv-hoje .d3h-btn:disabled{color:var(--d3-meta);cursor:default}
#vv-hoje .d3h-topo .d3h-btn{background:var(--d3-cartao)}
#vv-hoje .d3h-leg{display:inline-flex;align-items:center;gap:5px;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado)}
#vv-hoje .d3h-leg > i{width:14px;height:2.5px;border-radius:2px;background:var(--d3-tinta)}
#vv-hoje .d3h-leg.m > i{height:0;border-top:1.5px dashed var(--d3-meta);background:none}
#vv-hoje .d3h-leg.t > i{width:2px;height:10px}

/* Pílula clara com bolinha; cheia só no que venceu (vermelho) e no pronto (verde). */
#vv-hoje .d3h-pill{display:inline-flex;align-items:center;gap:5px;height:22px;padding:0 9px;border-radius:999px;background:var(--d3-trilho);color:var(--d3-texto2);font:600 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);white-space:nowrap}
#vv-hoje .d3h-pill > i{width:7px;height:7px;border-radius:50%;background:var(--d3-meta)}
#vv-hoje .d3h-pill.r{background:var(--d3-perigo-veu);color:var(--d3-perigo)}
#vv-hoje .d3h-pill.r > i{background:var(--d3-perigo)}
#vv-hoje .d3h-pill.g{background:var(--d3-pronto-veu);color:var(--d3-pronto)}
#vv-hoje .d3h-pill.g > i{background:var(--d3-pronto)}
#vv-hoje .d3h-pill.so{font-weight:500}
#vv-hoje .d3h-pct{display:inline-flex;align-items:center;height:20px;padding:0 7px;border-radius:999px;background:var(--d3-trilho);color:var(--d3-texto2);font:600 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif)}
#vv-hoje .d3h-pct.a{background:var(--d3-ajuste-veu);color:var(--d3-ajuste)}
#vv-hoje .d3h-pct.g{color:var(--d3-pronto)}

/* Linha de peça (Pede ação, Pediram ajuste): quando, cliente · peça, status, data e quem faz. */
#vv-hoje .d3h-lin{appearance:none;display:flex;align-items:center;gap:10px;width:100%;min-width:0;box-sizing:border-box;margin:0;padding:10px 18px;border:0;border-top:1px solid var(--d3-linha);background:none;color:var(--d3-tinta);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
#vv-hoje .d3h-lin:hover{background:#FBFAF7}
#vv-hoje .d3h-q{flex:none;width:72px;font:700 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);letter-spacing:.02em;text-transform:uppercase;color:var(--d3-apagado);white-space:nowrap}
#vv-hoje .d3h-q.r{color:var(--d3-perigo)}
#vv-hoje .d3h-q.a{color:var(--d3-ajuste)}
#vv-hoje .d3h-q.ok{color:var(--d3-pronto)}
#vv-hoje .d3h-nome{flex:1 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#vv-hoje .d3h-st{flex:none;max-width:150px;display:inline-flex;min-width:0}
#vv-hoje .d3h-qd{flex:none;font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado);white-space:nowrap}
#vv-hoje .d3h-qd.r{color:var(--d3-perigo)}
#vv-hoje .d3h-qd.a{color:var(--d3-ajuste)}
#vv-hoje .d3h-av{flex:none;display:grid;place-items:center;width:26px;height:26px;border-radius:50%;background:#EFEBE4;color:var(--d3-tinta);font:700 10px var(--vv-texto,Inter,sans-serif);font-style:normal}
#vv-hoje .d3h-av.sd{background:#FFFFFF;box-shadow:inset 0 0 0 1.5px #C9C2B6;color:var(--d3-apagado)}
#vv-hoje .d3h-av.ag{width:24px;height:24px;background:var(--d3-agente);color:#FFFFFF;font-size:var(--d3-fs-mini)}
#vv-hoje .d3h .cliente-carteira{display:inline-flex;align-items:center;gap:5px;max-width:100%;margin:0;padding:0;border:0;border-radius:0;background:none;box-shadow:none;color:var(--carteira-texto,var(--d3-tinta));font:inherit;font-weight:700;vertical-align:baseline}
#vv-hoje .d3h .cliente-carteira::before{content:"";flex:none;width:6px;height:6px;border-radius:50%;background:currentColor}
#vv-hoje .d3h-olho > .d3h-ficha{max-width:240px}

/* "De olho": fichas no pé do cartão; vermelha só a do que venceu. */
#vv-hoje .d3h-olho{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin-top:auto;padding:10px 18px 4px;border-top:1px solid var(--d3-linha)}
#vv-hoje .d3h-olho > span{margin-right:4px;font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado)}
#vv-hoje .d3h-ficha{appearance:none;max-width:100%;height:28px;padding:0 10px;border:0;border-radius:999px;background:var(--d3-trilho);color:var(--d3-tinta);font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;cursor:pointer}
#vv-hoje .d3h-ficha:hover{background:var(--d3-linha)}
#vv-hoje .d3h-ficha{display:inline-flex;align-items:center;gap:6px}
#vv-hoje .d3h-ficha > i{flex:none;width:7px;height:7px;border-radius:50%;background:var(--d3-meta)}
#vv-hoje .d3h-ficha.r > i{background:var(--d3-perigo)}
#vv-hoje .d3h-ficha.a > i{background:#E8A33D}

/* Baralho "Para você decidir": a prévia à esquerda, a peça à direita, ‹ Pedir alteração · Aprovar ›. */
#vv-hoje .d3h-decidir{padding:14px 16px;gap:10px}
#vv-hoje .d3h-decidir > .d3h-cab{padding:0}
#vv-hoje .d3h-decidir > .d3h-vazio{padding:8px 0 0}
#vv-hoje .d3h-baralho{height:150px;outline:none;overflow:clip;overflow-clip-margin:6px}
#vv-hoje .d3h-baralho > .d3h-carta{display:flex;gap:12px;border-radius:16px;box-shadow:none;cursor:pointer}
#vv-hoje .d3h-baralho > .d3h-carta[data-pos="0"]{cursor:default}
#vv-hoje .d3h-baralho > .d3h-carta[data-pos="1"],#vv-hoje .d3h-baralho > .d3h-carta[data-pos="2"]{transform:translateX(20px) scale(.93);opacity:0}
#vv-hoje .d3h-baralho:focus-visible > .d3h-carta[data-pos="0"]{outline:2px solid var(--d3-acao);outline-offset:3px}
#vv-hoje .d3h-arte{position:relative;flex:0 0 120px;height:150px;overflow:hidden;border-radius:14px;background:var(--d3-info-veu)}
#vv-hoje .d3h-arte > img{width:100%;height:100%;object-fit:cover;display:block}
#vv-hoje .d3h-arte > span{position:absolute;left:8px;bottom:8px;max-width:calc(100% - 16px);box-sizing:border-box;padding:2px 7px;border-radius:999px;background:#FFFFFF;color:var(--d3-info);font:600 var(--d3-fs-mini) var(--vv-texto,Inter,sans-serif);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#vv-hoje .d3h-carta-txt{flex:1;min-width:0;display:flex;flex-direction:column;align-items:flex-start;gap:6px}
#vv-hoje .d3h-carta-txt > b{max-width:100%;font:700 var(--d3-fs-destaque)/1.3 var(--vv-texto,Inter,sans-serif);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
#vv-hoje .d3h-carta-cli{max-width:100%;font-size:var(--d3-fs-texto);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#vv-hoje .d3h-pills{display:flex;flex-wrap:wrap;gap:5px}
#vv-hoje .d3h-carta-txt > small{font:400 var(--d3-fs-texto)/1.35 var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado)}
#vv-hoje .d3h-decidir-acoes{display:flex;align-items:center;gap:8px}
#vv-hoje .d3h-decidir-acoes > .d3h-btn{flex:1 1 auto;padding:0 10px;white-space:nowrap}
#vv-hoje .d3h-decidir-acoes > .d3h-passo{flex:none;width:36px;padding:0;font:600 var(--d3-fs-destaque) var(--vv-texto,Inter,sans-serif)}
#vv-hoje .d3h-fila{display:flex;flex-wrap:wrap;gap:4px 12px;font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado)}
#vv-hoje .d3h-fila b{color:var(--d3-tinta)}

/* Semana em linha: prontas contra previstas, os dias embaixo (o escolhido em preto) e o pé com o que o dia tem. */
#vv-hoje .d3h-semana > .d3h-corpo{padding:0 16px}
#vv-hoje .d3h-sem-graf{width:100%;height:auto;max-height:110px}
#vv-hoje .d3h-sem-graf polyline.meta{stroke-dasharray:5 5}
#vv-hoje .d3h-sem-dias{display:flex;justify-content:space-between;gap:2px;padding:4px 0 2px}
#vv-hoje .d3h-sem-dias > *{appearance:none;min-width:0;padding:2px 4px;border:0;border-radius:8px;background:none;color:var(--d3-apagado);font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);cursor:pointer}
#vv-hoje .d3h-sem-dias > span{cursor:default}
#vv-hoje .d3h-sem-dias > .hoje{color:var(--d3-tinta);font-weight:700}
#vv-hoje .d3h-sem-dias > [aria-pressed="true"]{background:var(--d3-tinta);color:#FFFFFF}
#vv-hoje .d3h-sem-qual{color:var(--d3-tinta);font-weight:600}

/* Agenda, agentes e WhatsApp: linhas de uma linha só. */
#vv-hoje .d3h-agenda,#vv-hoje .d3h-agentes{padding-bottom:6px}
#vv-hoje :is(.d3h-ag,.d3h-agl,.d3h-zap){appearance:none;display:flex;align-items:center;gap:10px;width:auto;min-width:0;margin:0 16px;padding:8px 0;border:0;border-top:1px solid var(--d3-linha);background:none;color:var(--d3-tinta);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
#vv-hoje .d3h-ag > b{flex:0 0 46px;font-weight:700;font-variant-numeric:tabular-nums}
#vv-hoje :is(.d3h-ag,.d3h-agl) > span{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#vv-hoje .d3h-agl > small{flex:none;font:600 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado);max-width:40%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#vv-hoje .d3h-zapc.so-cab{padding-bottom:14px}
#vv-hoje .d3h-zapc.so-cab > .d3h-cab{padding-bottom:0}
#vv-hoje .d3h-zap-n{font:700 var(--d3-fs-titulo) var(--vv-titulo,"Inter Tight",Inter,sans-serif);color:var(--d3-tinta)}
#vv-hoje .d3h-zap > span{flex:1;min-width:0;display:flex;flex-direction:column;overflow:hidden}
#vv-hoje .d3h-zap > span > small{font-size:var(--d3-fs-apoio);color:var(--d3-apagado);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#vv-hoje .d3h-zap > b{flex:none;font:700 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado)}
#vv-hoje .d3h-zap > b.r{color:var(--d3-perigo)}

/* Aprovações: a linha conta (quantas e há quanto tempo) e abre no lugar com cada item. */
#vv-hoje .d3h-apr{margin:0 16px;border-top:1px solid var(--d3-linha)}
#vv-hoje .d3h-apr-lin{appearance:none;display:flex;align-items:center;gap:10px;width:100%;margin:0;padding:8px 0;border:0;background:none;color:var(--d3-tinta);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
#vv-hoje .d3h-apr-lin > span{flex:1;min-width:0}
#vv-hoje .d3h-apr-lin > b{font-weight:700}
#vv-hoje .d3h-apr-lin > small,#vv-hoje .d3h-apr-item > small{flex:none;min-width:30px;text-align:right;font:600 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado)}
#vv-hoje :is(.d3h-apr-lin,.d3h-apr-item) > small.r{color:var(--d3-perigo)}
#vv-hoje .d3h-apr[aria-expanded="false"] > .v2-mais{visibility:hidden;transition:grid-template-rows .28s cubic-bezier(.22,1,.36,1),visibility 0s .28s}
#vv-hoje .d3h-apr-item{appearance:none;display:flex;align-items:center;gap:8px;width:100%;margin:0;padding:6px 0 6px 12px;border:0;background:none;color:var(--d3-texto2);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
#vv-hoje .d3h-apr-item > span{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

/* Minhas tarefas: fichas, busca e Filtros no alto do cartão; a linha com Agora/Depois/Em seguida, a bolinha que risca,
   o status que troca, a data, o olho, quem faz e a seta; aberta, as etapas em barras e os botões da peça. */
#vv-hoje .d3h-filtros{display:flex;align-items:center;flex-wrap:wrap;gap:6px;margin:0;padding:0 18px 10px}
#vv-hoje .d3h-filtros > .v2t-fichas{display:flex;flex-wrap:wrap;gap:6px}
#vv-hoje .d3h-filtros .v2t-ficha{appearance:none;height:30px;padding:0 12px;border:0;border-radius:999px;background:var(--d3-trilho);color:var(--d3-tinta);font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);box-shadow:none;cursor:pointer;transition:background-color .2s,color .2s}
#vv-hoje .d3h-filtros .v2t-ficha > b{font-weight:600}
#vv-hoje .d3h-filtros .v2t-ficha.r{background:var(--d3-perigo-veu);color:var(--d3-perigo)}
#vv-hoje .d3h-filtros .v2t-ficha[aria-selected="true"]{background:var(--d3-tinta);color:#FFFFFF}
#vv-hoje .d3h-filtros .v2t-busca{flex:1 1 90px;min-width:70px;max-width:180px;height:30px;box-sizing:border-box;padding:0 12px;border:0;border-radius:999px;background:var(--d3-trilho);color:var(--d3-tinta);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);box-shadow:none}
#vv-hoje .d3h-filtros > .d3h-btn{margin-left:auto}
#vv-hoje .d3h-lista{display:flex;flex-direction:column;min-width:0}
#vv-hoje .d3h-tarefas .v2-linha{border-top:1px solid var(--d3-linha);background:none}
#vv-hoje .d3h-tarefas .v2-linha[aria-expanded="true"]{background:#FBFAF7}
#vv-hoje .d3h-tarefas .v2t-lin{display:flex;align-items:center;gap:8px;min-width:0;padding:9px 18px;border:0;background:none}
#vv-hoje .d3h-tarefas .v2t-cx{flex:none;display:grid;place-items:center;width:22px;height:22px;margin:0;padding:0;border:0;border-radius:50%;background:#FFFFFF;box-shadow:inset 0 0 0 1.5px #C9C2B6;cursor:pointer;transition:background-color .25s,box-shadow .25s}
#vv-hoje .d3h-tarefas .v2t-cx > svg{width:12px;height:12px;fill:none;stroke:#FFFFFF;stroke-width:3;stroke-linecap:round;stroke-linejoin:round}
#vv-hoje .d3h-tarefas .v2t-cx.ok{background:var(--d3-pronto);box-shadow:none}
#vv-hoje .d3h-tarefas .d3h-q{width:62px}
#vv-hoje .d3h-tarefas .v2-linha-seta{display:none}
#vv-hoje .d3h-tarefas .v2t-nome{flex:1 1 140px;min-width:0;margin:0;padding:0;border:0;background:none;color:var(--d3-tinta);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);text-align:left;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;cursor:pointer}
#vv-hoje .d3h-tarefas .v2t-st{flex:0 1 auto;width:auto;max-width:130px;min-width:0;overflow:hidden}
#vv-hoje .d3h-tarefas .v2t-st .vv-demanda-status{display:inline-flex;align-items:center;gap:2px;max-width:100%;padding:0;border:0;background:none;cursor:pointer}
#vv-hoje .d3h-tarefas .v2t-st .vv-demanda-status > svg{flex:none;width:12px;height:12px;fill:none;stroke:var(--d3-apagado);stroke-width:2}
#vv-hoje .d3h-tarefas .v2t-quando{flex:none;display:inline-flex;align-items:center;gap:6px}
#vv-hoje .d3h-tarefas .v2t-q{padding:0;background:none;font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado);text-decoration:underline dotted #C9C2B6;text-underline-offset:3px}
#vv-hoje .d3h-tarefas .v2t-q.ruim{color:var(--d3-perigo)}
#vv-hoje .d3h-tarefas .v2t-q.atencao{color:var(--d3-ajuste)}
#vv-hoje .d3h-tarefas .v2t-q.ok{color:var(--d3-apagado);text-decoration:none}
#vv-hoje .d3h-tarefas .v2-linha-seta{flex:none;display:none;place-items:center;width:24px;height:24px;margin:0;padding:0;border:0;border-radius:50%;background:none;cursor:pointer}
#vv-hoje .d3h-tarefas .v2-linha-seta > svg{width:14px;height:14px;fill:none;stroke:var(--d3-apagado);stroke-width:2;transition:transform .25s}
#vv-hoje .d3h-tarefas .v2-linha[aria-expanded="true"] .v2-linha-seta > svg{transform:rotate(90deg)}
#vv-hoje .d3h-tarefas .v2t-det{margin:0 18px 12px 114px;padding:0;background:none}
#vv-hoje .d3h-tarefas .v2t-etapas{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:6px;margin:0 0 10px}
#vv-hoje .d3h-tarefas .v2t-etapa{display:flex;flex-direction:column;gap:5px;min-width:0;padding:0;background:none;color:var(--d3-apagado);font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#vv-hoje .d3h-tarefas .v2t-etapa > i{display:block;width:100%;height:4px;border-radius:2px;background:var(--d3-linha)}
#vv-hoje .d3h-tarefas .v2t-etapa.ok{color:var(--d3-pronto)}
#vv-hoje .d3h-tarefas .v2t-etapa.ok > i{background:var(--d3-pronto)}
#vv-hoje .d3h-tarefas .v2t-etapa.agora{color:var(--d3-tinta);font-weight:700}
#vv-hoje .d3h-tarefas .v2t-etapa.agora > i{background:var(--d3-tinta)}
#vv-hoje .d3h-tarefas .v2t-det-linha{display:flex;flex-wrap:wrap;align-items:center;gap:8px}
#vv-hoje .d3h-tarefas .v2t-det-linha > p{flex:1 1 160px;min-width:0;font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado)}
#vv-hoje .d3h-tarefas .v2-linha[aria-expanded="false"] > .v2-mais{visibility:hidden;transition:grid-template-rows .28s cubic-bezier(.22,1,.36,1),visibility 0s .28s}
#vv-hoje .d3h-tarefas .v2t-grupo{display:flex;justify-content:space-between;padding:10px 18px 4px;border-top:1px solid var(--d3-linha);font:700 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);letter-spacing:.02em;text-transform:uppercase;color:var(--d3-apagado)}
#vv-hoje .d3h-lista-pe{margin:0;padding:10px 18px 0;border-top:1px solid var(--d3-linha);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado)}
#vv-hoje .d3h-dia > summary,#vv-hoje button.d3h-dia{display:inline-flex;align-items:center;gap:8px;height:40px;padding:0 14px 0 4px;border:0;border-radius:999px;background:var(--d3-cartao);color:var(--d3-texto2);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);list-style:none;cursor:pointer;box-shadow:none}
#vv-hoje .d3h-dia > summary::-webkit-details-marker{display:none}
#vv-hoje .d3h-dia > summary > i,#vv-hoje button.d3h-dia > i{display:grid;place-items:center;width:32px;height:32px;border-radius:50%;background:var(--d3-trilho);color:var(--d3-tinta);font:700 var(--d3-fs-mini) var(--vv-texto,Inter,sans-serif);font-style:normal}
#vv-hoje .d3h-dia > summary > b{color:var(--d3-tinta)}
#vv-hoje .d3h-dia > summary > svg{width:12px;height:12px;fill:none;stroke:currentColor;stroke-width:2}

/* Criação: a Fila do Danilo (vybe-mundo-criacao.js) dentro do cartão branco; o time com a carga e o risco do limite. */
#vv-hoje .d3h-danilo{padding:14px 18px 10px}
#vv-hoje .d3h-danilo .vs-bloco,#vv-hoje .d3h-danilo .vcr-bloco{margin:0;padding:0;border:0;border-radius:0;background:none;box-shadow:none}
#vv-hoje .d3h-danilo .vs-bloco-cabeca b{font:700 var(--d3-fs-destaque) var(--vv-texto,Inter,sans-serif)}
#vv-hoje .v2c-conversa{padding:14px 18px}
#vv-hoje .d3h-pes{appearance:none;display:flex;flex-direction:column;gap:6px;width:auto;margin:0 16px;padding:10px 0;border:0;border-top:1px solid var(--d3-linha);background:none;color:var(--d3-tinta);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
#vv-hoje .d3h-pes-top{display:flex;align-items:baseline;gap:6px;min-width:0}
#vv-hoje .d3h-pes-top > b{font-weight:700}
#vv-hoje .d3h-pes-top > small{flex:1;min-width:0;font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#vv-hoje .d3h-pes-n{flex:none;font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado)}
#vv-hoje .d3h-pes-n > b{font-weight:700;color:var(--d3-tinta)}
#vv-hoje .d3h-pes-n > b.a{color:var(--d3-ajuste)}
#vv-hoje .d3h-pes-n > b.g{color:var(--d3-pronto)}
#vv-hoje .d3h-carga{position:relative;display:block;height:6px;border-radius:999px;background:var(--d3-linha)}
#vv-hoje .d3h-carga > i{position:absolute;inset:0 auto 0 0;width:var(--v,0%);border-radius:inherit;background:#6B665E;animation:d3BarraCresce .9s cubic-bezier(.22,1,.36,1) .1s both}
#vv-hoje .d3h-pes.passou .d3h-carga > i,#vv-hoje .d3h-carga.passou > i{background:var(--d3-ajuste)}
#vv-hoje .d3h-carga > u{position:absolute;top:-4px;bottom:-4px;left:var(--lim,100%);width:2px;border-radius:1px;background:var(--d3-tinta)}
#vv-hoje .d3h-pes-pe{display:flex;flex-wrap:wrap;align-items:center;gap:6px;min-width:0}
#vv-hoje .d3h-pes-pe > small{font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0}
#vv-hoje .d3h-ideias .v2c-sugestoes{padding:0 16px}

/* Coordenação: período ao lado do título; listas com as fichas de quem recebe (contorno = sugerido); a carga do time em
   linha contra o limite e os limites em ladrilhos; por pessoa, agora → depois. */
#vv-hoje .d3h-co .v2o-periodo{display:inline-flex;padding:3px;border-radius:999px;background:var(--d3-cartao);box-shadow:inset 0 0 0 1px var(--d3-borda)}
#vv-hoje .d3h-co .v2o-periodo > button{appearance:none;height:28px;padding:0 12px;border:0;border-radius:999px;background:transparent;color:var(--d3-texto2);font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);cursor:pointer}
#vv-hoje .d3h-co .v2o-periodo > button[aria-selected="true"]{background:var(--d3-trilho);color:var(--d3-tinta);font-weight:600}
#vv-hoje .d3h-co .d3h-corpo > li{display:flex;flex-wrap:wrap;align-items:center;gap:6px 10px;padding:10px 18px;border-top:1px solid var(--d3-linha)}
#vv-hoje .d3h-co .d3h-corpo > li.d3h-vazio{display:block}
#vv-hoje .d3h-co .v2o-peca{flex:1 1 200px;min-width:0;display:flex;flex-direction:column;gap:2px}
#vv-hoje .d3h-co .v2o-peca > b{font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}

#vv-hoje .d3h-co .v2o-peca > small{font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado)}
#vv-hoje .d3h-co .ruim{font-style:normal;font-weight:600;color:var(--d3-perigo)}
#vv-hoje .d3h-co .v2o-quem{display:flex;flex-wrap:wrap;gap:6px}
#vv-hoje .d3h-co .v2o-chip{appearance:none;display:inline-flex;align-items:center;gap:5px;height:28px;padding:0 10px;border:0;border-radius:999px;background:var(--d3-trilho);color:var(--d3-texto2);font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);cursor:pointer}
#vv-hoje .d3h-co .v2o-chip > small{font:600 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado)}
#vv-hoje .d3h-co .v2o-chip.a > small{color:var(--d3-ajuste)}
#vv-hoje .d3h-co .v2o-chip.sugerido{background:#FFFFFF;box-shadow:inset 0 0 0 1.5px var(--d3-tinta);color:var(--d3-tinta);font-weight:600}
#vv-hoje .d3h-co .v2o-porque{display:inline-flex;align-items:center;gap:8px;font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-texto2)}
#vv-hoje .d3h-co .v2o-de{display:inline-flex;align-items:center;gap:5px;height:28px;padding:0 4px 0 10px;border-radius:999px;background:var(--d3-trilho)}
#vv-hoje .d3h-co .v2o-conf{flex:1 1 100%;display:flex;flex-wrap:wrap;align-items:center;gap:6px;font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}
#vv-hoje .d3h-co .v2o-btn{appearance:none;height:30px;padding:0 14px;border:0;border-radius:999px;background:var(--d3-trilho);color:var(--d3-tinta);font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);cursor:pointer}
#vv-hoje .d3h-co .v2o-btn.k{background:var(--d3-tinta);color:#FFFFFF;font-weight:600}
#vv-hoje .d3h-co .v2o-grava{font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado)}
#vv-hoje .d3h-co .v2o-nota{margin:0;padding:8px 18px 0;font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado)}
#vv-hoje .d3h-co .v2o-msg{margin:0;padding:10px 14px;border-radius:14px;background:var(--d3-perigo-veu);color:var(--d3-perigo);font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif)}
#vv-hoje .d3h-co-carga > .d3h-corpo{flex:1;padding:0 16px}
#vv-hoje .d3h-co-total{font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado)}
#vv-hoje .d3h-co-total > b{margin-right:4px;font:700 var(--d3-fs-numero)/1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);color:var(--d3-tinta);animation:d3NumChega .55s cubic-bezier(.22,1,.36,1) both}
#vv-hoje .d3h-co-graf{width:100%;height:auto;max-height:170px;margin-top:10px}
#vv-hoje .d3h-co-graf polyline.previsto{stroke:var(--d3-meta);stroke-width:1.5;stroke-dasharray:3 4;animation:none}
#vv-hoje .d3h-co-tiles{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-top:auto;padding:12px 0 6px}
#vv-hoje .d3h-co-tiles > span{display:flex;flex-direction:column;gap:2px;padding:10px 12px;border-radius:14px;background:var(--d3-trilho);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-texto2)}
#vv-hoje .d3h-co-tiles > span > small{font-size:var(--d3-fs-texto);color:var(--d3-apagado)}
#vv-hoje .d3h-co-tiles > span > b{font:700 var(--d3-fs-titulo) var(--vv-titulo,"Inter Tight",Inter,sans-serif);color:var(--d3-tinta)}
#vv-hoje .d3h-co .v2o-pes{margin:0 16px;border-top:1px solid var(--d3-linha)}
#vv-hoje .d3h-co .v2o-pes-linha{appearance:none;display:flex;flex-direction:column;gap:6px;width:100%;margin:0;padding:10px 0;border:0;background:none;color:var(--d3-tinta);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
#vv-hoje .d3h-co .v2o-nivel{font-weight:600}
#vv-hoje .d3h-co .v2o-lista{margin:0 0 8px}
#vv-hoje .d3h-co .v2o-lista > li{display:flex;flex-wrap:wrap;align-items:center;gap:6px 10px;padding:8px 0;border-top:1px solid var(--d3-linha)}

/* O cartão de tarefas estreito (Minhas tarefas no app do Mac, 1135: a coluna fica com ~380 px): o nome da peça virava
   "Academia L" e o status "Em pro". Abaixo de 480 px de cartão, a linha quebra como no celular. */
#vv-hoje .d3h-tarefas{container:d3htf / inline-size}
@container d3htf (max-width:480px){
  #vv-hoje .d3h-tarefas .v2t-lin{flex-wrap:wrap;row-gap:4px;padding:9px 14px}
  #vv-hoje .d3h-tarefas .v2t-nome{flex:1 1 calc(100% - 120px)}
  #vv-hoje .d3h-tarefas .v2t-st{max-width:none}
  #vv-hoje .d3h-tarefas .d3h-q{width:auto;min-width:0}
}
/* A coluna do Hoje estreita (Minha sala) e o celular: duas colunas, depois uma; números em duas por linha. */
@container hoje (max-width:1100px){
  #vv-hoje .d3h-grade,#vv-hoje .d3h-tf .d3h-grade{grid-template-columns:minmax(0,1.3fr) minmax(0,1fr)}
  #vv-hoje .d3h-grade > .d3h-col:nth-child(3){grid-column:1 / -1;display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));align-items:start}
  /* O guia do dia com os três passos: em 1366 e 1135 a frase virava "2 peças suas vã..." espremida pelos passos. Os
     passos descem para a linha de baixo e a frase fica inteira. */
  #vv-hoje .d3h-acao:has(> .d3h-acao-passos){flex-wrap:wrap}
  #vv-hoje .d3h-acao:has(> .d3h-acao-passos) > .d3-acao-frase{flex:1 1 calc(100% - 200px);white-space:normal}
  #vv-hoje .d3h-acao:has(> .d3h-acao-passos) > .d3h-acao-passos{order:3;flex:1 1 100%;flex-wrap:wrap}
}
@container hoje (max-width:760px){
  #vv-hoje .d3h-grade,#vv-hoje .d3h-tf .d3h-grade{grid-template-columns:minmax(0,1fr)}
  #vv-hoje .d3h-grade > .d3h-col:nth-child(3){display:flex;align-items:stretch}
  #vv-hoje .d3h-nums{grid-auto-flow:row;grid-template-columns:repeat(2,minmax(0,1fr))}
  #vv-hoje .d3h-acao{flex-wrap:wrap;font-size:var(--d3-fs-titulo)}
  #vv-hoje .d3h-acao > .d3-acao-frase{flex:1 1 calc(100% - 52px);white-space:normal}
  #vv-hoje .d3h-acao-passos{order:3;flex:1 1 100%;flex-wrap:wrap}
  #vv-hoje .d3h-acao > .d3-acao-btn{order:4;margin-left:auto}
  #vv-hoje .d3h-tarefas .v2t-det{margin-left:18px}
  #vv-hoje .d3h-topo-dir{margin-left:0;justify-content:flex-start}
}
@container hoje (max-width:480px){
  #vv-hoje .d3h-ola > h2{font-size:26px}
  #vv-hoje .d3h-num{min-height:0;padding:12px}
  #vv-hoje .d3h-num-linha > .d3-num-v{font-size:var(--d3-fs-numero)}
  #vv-hoje .d3h-num-linha > .d3-num-v > small{font-size:var(--d3-fs-destaque)}
  #vv-hoje .d3h-num-linha > .d3-graf{display:none}
  #vv-hoje .d3h-q{width:auto;min-width:0}
  #vv-hoje .d3h-lin{flex-wrap:wrap;row-gap:4px}
  #vv-hoje .d3h-lin > .d3h-nome{flex:1 1 calc(100% - 90px)}
  #vv-hoje .d3h-tarefas .v2t-lin{flex-wrap:wrap;row-gap:4px;padding:9px 14px}
  #vv-hoje .d3h-tarefas .v2t-nome{flex:1 1 calc(100% - 120px)}
  #vv-hoje .d3h-tarefas .v2t-st{max-width:none}
  #vv-hoje .d3h-filtros .v2t-busca{max-width:none}
