#vv-hoje .d3h-danilo .vcr-fila .vcr-q{flex:0 0 64px;font:700 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);letter-spacing:.02em;text-transform:uppercase;color:var(--d3-texto2)}
