  #vv-placa .v2e .v2e-predio > .v2n-cab > h2{white-space:nowrap}
  #vv-placa .v2e .v2n-cab > .v2e-busca{order:3;flex:1 1 100%;max-width:none;margin-left:0}
}
#vv-hoje .d3h-danilo .vcr-fila .vcr-sug.vcr-lin{flex-direction:row;flex-wrap:nowrap}
#vv-hoje .d3h-danilo .vcr-fila .vcr-lote{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-top:auto;padding:10px 0 0;border-top:1px solid var(--d3-linha)}
#vv-hoje .d3h-danilo .vcr-fila .vcr-lote > .vcr-pe-conta,#vv-hoje .d3h-danilo .vcr-fila .vcr-lote > .vcr-conf{flex:1 1 200px;min-width:0;font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado)}
#vv-hoje .d3h-danilo .vcr-fila .vcr-lote > button{height:36px;padding:0 16px;border:0;border-radius:999px;background:var(--d3-trilho);color:var(--d3-tinta);font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);cursor:pointer}
#vv-hoje .d3h-danilo .vcr-fila .vcr-lote > button.vc-acao{background:var(--d3-tinta);color:#FFFFFF}
#vv-hoje .d3h-danilo .vcr-fila{display:flex;flex-direction:column}
/* A faixa do Ranking dentro da janela do Escritório: as cores da faixa valem por cima das regras da janela. */
#ofc-ranking .d3r-acao.d3-acao{background:var(--d3-acao);color:#FFFFFF}
#ofc-ranking .d3r-acao > .d3-acao-av{background:#FFFFFF;color:var(--d3-agente)}
#ofc-ranking .d3r-acao > .d3-acao-frase,#ofc-ranking .d3r-acao > .d3-acao-frase > small{color:#FFFFFF}
#ofc-ranking .d3r-acao > .d3-acao-btn{border:0;background:#FFFFFF;color:var(--d3-acao-texto);font:700 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif)}
/* Centro no celular: a faixa laranja continua à vista, logo abaixo da barra (antes a fala sumia abaixo de 900 px). */
@media (max-width:900px){
  body.mundo.mundo-centro:not(.mundo-modulo):not(.v2m-dia) #mundo-hud > .v2m-fala.d3h-acao{display:flex;top:calc(var(--vv-m,8px) + 168px);left:var(--vv-m,8px);right:var(--vv-m,8px);padding:10px 12px;gap:10px;font-size:var(--d3-fs-destaque)}
  body.mundo.mundo-centro #mundo-hud > .v2m-fala.d3h-acao > .d3-acao-frase{white-space:normal}
  body.mundo.mundo-centro #mundo-hud > .v2m-fala.d3h-acao > .d3-acao-frase > span{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
  body.mundo.mundo-centro #mundo-hud > .v2m-fala.d3h-acao > .d3-acao-btn{height:34px;padding:0 12px;font-size:var(--d3-fs-texto)}
}

/* CENTRO PELO QUADRO (D3-Centro e D3-Loja; Paulo, 14/11/2026: "o 3D não ocupa a tela toda: ele fica DENTRO de um
   cartão, numa grade igual à do quadro"). Com o painel (body.d3c-painel), o canvas e os rótulos do mapa vão para o
   retângulo do cartão (--d3c-m*, medido em pintarCentroD3) e o resto da tela é areia com cartões brancos. "Entrar no
   mapa" (body.d3c-cheio) volta tudo ao mapa em tela cheia de antes. */
body.mundo.d3c-painel #mundo{background:var(--d3-areia)}
body.mundo.d3c-painel #mundo > :is(canvas,.mundo-rotulos,.mundo-vinheta){inset:auto;left:var(--d3c-mx,0px);top:var(--d3c-my,0px);width:var(--d3c-mw,100%);height:var(--d3c-mh,100%);border-radius:var(--d3-r-cartao)}
body.mundo.d3c-painel #mundo > .mundo-vinheta{display:none}
body.mundo.d3c-painel #mundo > .mundo-fonte{display:none}
body.mundo.d3c-painel #mundo > .mundo-carregando{left:calc(var(--d3c-mx,0px) + var(--d3c-mw,100vw) / 2);top:calc(var(--d3c-my,0px) + var(--d3c-mh,100vh) / 2)}
#mundo-hud > #d3-centro{display:none}
body.mundo.mundo-centro.d3c-painel #mundo-hud > #d3-centro{position:absolute;z-index:3;top:var(--vv-palco-topo,74px);left:var(--vv-livre-esq,250px);right:var(--vv-m,14px);bottom:calc(var(--vv-dock-alto,74px) + 12px);display:grid;grid-template-columns:minmax(0,1fr);grid-template-rows:auto auto auto minmax(0,1fr);gap:12px;pointer-events:none;color:var(--d3-tinta);font:400 var(--d3-fs-texto)/1.35 var(--vv-texto,Inter,sans-serif)}
#d3-centro > *,#d3-centro .d3c-grade > *,#d3-centro .d3c-col1 > *{pointer-events:auto}
#d3-centro :is(h3,p){margin:0}
/* Título: Vybelândia e a data à esquerda; a busca e Centro/Prédio à direita. */
body.mundo.mundo-centro.d3c-painel #mundo-hud #d3-centro .vv-legenda-cidade.v2m-barra{position:static;inset:auto;display:flex;align-items:center;gap:12px;margin:0;padding:0;background:none;box-shadow:none}
body.mundo.mundo-centro.d3c-painel #mundo-hud #d3-centro .v2m-barra > .v2m-nome{display:contents}
body.mundo.mundo-centro.d3c-painel #mundo-hud #d3-centro .v2m-barra h1{order:0;margin:0;font:700 var(--d3-fs-numero)/1.1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.02em;color:var(--d3-tinta)}
body.mundo.mundo-centro.d3c-painel #mundo-hud #d3-centro .v2m-barra .d3c-data{order:1;font:400 var(--d3-fs-destaque) var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado);white-space:nowrap}
body.mundo.mundo-centro.d3c-painel #mundo-hud #d3-centro .v2m-barra > .v2n-busca{order:2;flex:0 1 260px;min-width:0;max-width:none;height:40px;margin-left:auto;padding:0 16px;border:0;border-radius:999px;background:var(--d3-cartao);box-shadow:none}
body.mundo.mundo-centro.d3c-painel #mundo-hud #d3-centro .v2m-barra .v2n-seg{order:3;display:inline-flex;padding:4px;border-radius:999px;background:var(--d3-trilho)}
body.mundo.mundo-centro.d3c-painel #mundo-hud #d3-centro .v2m-barra .v2n-seg > button{height:32px;padding:0 14px;border:0;border-radius:999px;background:transparent;color:var(--d3-texto2);font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);box-shadow:none}
body.mundo.mundo-centro.d3c-painel #mundo-hud #d3-centro .v2m-barra .v2n-seg > button[aria-pressed="true"]{background:var(--d3-tinta);color:#FFFFFF;font-weight:600}
body.mundo.mundo-centro.d3c-painel #mundo-hud #d3-centro .v2m-barra :is(.v2m-conta,[data-seu-dia],.d3c-voltar){display:none}
#mundo-hud .v2m-barra .d3c-data{display:none}
body.mundo.mundo-centro.d3c-painel #mundo-hud #d3-centro .v2m-barra .d3c-data{display:inline}
#mundo-hud .v2m-barra .d3c-voltar{display:none}
body.mundo.mundo-centro.d3c-cheio #mundo-hud > .v2m-barra .d3c-voltar{display:inline-flex}
/* A faixa laranja do VYBES no lugar da faixa do quadro. */
body.mundo.mundo-centro.d3c-painel #mundo-hud #d3-centro .d3c-faixa > .v2m-fala.d3h-acao{position:static;display:flex;margin:0;padding:14px 18px;border:0;border-radius:22px;background:var(--d3-acao);color:#FFFFFF;box-shadow:none;font:600 var(--d3-fs-titulo)/1.25 var(--vv-titulo,"Inter Tight",Inter,sans-serif)}
body.mundo.mundo-centro.d3c-painel #mundo-hud #d3-centro .v2m-fala.d3h-acao > .d3-acao-frase{display:flex;flex-direction:column;gap:1px;min-width:0}
body.mundo.mundo-centro.d3c-painel #mundo-hud #d3-centro .v2m-fala.d3h-acao > .d3-acao-frase > small{font:700 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);opacity:.85}
body.mundo.mundo-centro.d3c-painel #mundo-hud #d3-centro .v2m-fala.d3h-acao > .d3-acao-frase > span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
body.mundo.mundo-centro.d3c-painel #mundo-hud #d3-centro .v2m-fala.d3h-acao b{color:#FFFFFF}
body.mundo.mundo-centro.d3c-painel #mundo-hud #d3-centro .v2m-fala.d3h-acao > .d3-acao-btn{height:40px;padding:0 18px}
/* Números. */
#d3-centro .d3c-nums{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}
#d3-centro .d3c-num{min-height:0;padding:12px 16px;gap:4px;border-radius:18px}
#d3-centro .d3c-num-linha{display:flex;align-items:center;justify-content:space-between;gap:8px;min-width:0}
#d3-centro .d3c-num .d3-num-v{font-size:var(--d3-fs-numero);animation:d3NumChega .55s cubic-bezier(.22,1,.36,1) both}
#d3-centro .d3c-num .d3-num-v > small{font:600 var(--d3-fs-destaque) var(--vv-titulo,"Inter Tight",Inter,sans-serif);color:var(--d3-apagado)}
#d3-centro .d3c-num.r .d3-num-v{color:var(--d3-perigo)}
#d3-centro .d3c-sub{font-size:var(--d3-fs-texto);color:var(--d3-apagado);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#d3-centro .d3c-avs,#d3-centro .d3c-pes > i:first-child{display:inline-flex}
#d3-centro .d3c-avs > i,#d3-centro .d3c-pes > i{display:grid;place-items:center;width:28px;height:28px;margin-left:-6px;border-radius:50%;background:var(--d3-trilho);box-shadow:0 0 0 2px var(--d3-cartao);font:700 10px var(--vv-texto,Inter,sans-serif);font-style:normal;color:var(--d3-tinta)}
#d3-centro .d3c-avs > i:first-child{margin-left:0}
/* A grade: mapa e módulos | prédio | online e salas. */
#d3-centro .d3c-grade{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(0,1fr) minmax(0,.85fr);gap:14px;min-height:0}
#d3-centro .d3c-col1,#d3-centro .d3c-col2,#d3-centro .d3c-col3{display:flex;flex-direction:column;gap:14px;min-height:0;min-width:0}
#d3-centro .d3c-mapa{position:relative;flex:1 1 auto;min-height:220px;border-radius:var(--d3-r-cartao);background:transparent;box-shadow:inset 0 0 0 1px rgba(31,29,26,.06);pointer-events:none}
#d3-centro .d3c-mapa > *{pointer-events:auto}
#d3-centro .d3c-cartao.d3c-mapa{padding:0;background:transparent}
#d3-centro > .d3c-grade,#d3-centro .d3c-grade > .d3c-col1{pointer-events:none}
#d3-centro .d3c-chips{position:absolute;top:12px;left:12px;display:flex;flex-wrap:wrap;gap:6px}
#d3-centro .d3c-chip{appearance:none;display:inline-flex;align-items:center;height:28px;padding:0 10px;border:0;border-radius:999px;background:var(--d3-cartao);color:var(--d3-tinta);font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);box-shadow:0 6px 14px -10px rgba(31,29,26,.5)}
#d3-centro button.d3c-chip{cursor:pointer}
#d3-centro .d3c-chip.r{background:var(--d3-perigo-veu);color:var(--d3-perigo)}
#d3-centro .d3c-chip[aria-pressed="true"]{box-shadow:inset 0 0 0 1.5px var(--d3-tinta)}
#d3-centro .d3c-entrar{appearance:none;position:absolute;left:12px;bottom:12px;height:40px;padding:0 18px;border:0;border-radius:999px;background:var(--d3-tinta);color:#FFFFFF;font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);cursor:pointer}
#d3-centro .d3c-cartao{box-sizing:border-box;min-height:0;padding:14px 16px;border-radius:var(--d3-r-cartao);background:var(--d3-cartao)}
#d3-centro .d3c-cab{display:flex;align-items:center;justify-content:space-between;gap:8px;padding-bottom:8px}
#d3-centro .d3c-cab > h3{font:700 var(--d3-fs-destaque) var(--vv-texto,Inter,sans-serif)}
#d3-centro .d3c-cab > small{font-size:var(--d3-fs-texto);color:var(--d3-apagado)}
#d3-centro .d3c-mods{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px}
#d3-centro .d3c-mod{appearance:none;display:flex;flex-direction:column;align-items:flex-start;gap:2px;min-width:0;margin:0;padding:8px 10px;border:0;border-radius:14px;background:var(--d3-trilho);color:var(--d3-tinta);font:inherit;text-align:left;cursor:pointer}
#d3-centro .d3c-mod > b{font:600 var(--d3-fs-texto)/1.25 var(--vv-texto,Inter,sans-serif)}
#d3-centro .d3c-mod > small{max-width:100%;font-size:var(--d3-fs-apoio);color:var(--d3-apagado);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#d3-centro .d3c-mod > small.r{color:var(--d3-perigo)}
#d3-centro .d3c-mod > small.g{color:var(--d3-pronto)}
#d3-centro .d3c-predio{flex:1 1 auto;display:flex;flex-direction:column;overflow:hidden;padding-bottom:10px}
#d3-centro .d3c-andar{appearance:none;display:grid;grid-template-columns:24px minmax(0,1fr) auto 8px;align-items:center;gap:10px;width:100%;margin:0;padding:8px 0;border:0;border-top:1px solid var(--d3-linha);background:none;color:var(--d3-tinta);font:inherit;text-align:left;cursor:pointer}
#d3-centro .d3c-andar-n{display:grid;place-items:center;width:24px;height:24px;border-radius:8px;background:var(--d3-trilho);font:700 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif)}
#d3-centro .d3c-andar > b{font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#d3-centro .d3c-andar > small{font-size:var(--d3-fs-texto);color:var(--d3-apagado);white-space:nowrap}
#d3-centro .d3c-andar > i{width:7px;height:7px;border-radius:50%;background:var(--s)}
#d3-centro .d3c-pe{margin-top:auto;padding-top:8px;border-top:1px solid var(--d3-linha);font-size:var(--d3-fs-texto);color:var(--d3-apagado)}
#d3-centro .d3c-pill{display:inline-flex;align-items:center;height:22px;padding:0 9px;border-radius:999px;background:var(--d3-trilho);color:var(--d3-texto2);font:600 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif)}
#d3-centro .d3c-pill.g{background:var(--d3-pronto-veu);color:var(--d3-pronto)}
#d3-centro .d3c-pill.a{background:var(--d3-ajuste-veu);color:var(--d3-ajuste)}
#d3-centro .d3c-pes{display:flex;align-items:center;gap:8px;padding:6px 0;border-top:1px solid var(--d3-linha)}
#d3-centro .d3c-pes > i{margin-left:0;box-shadow:none}
#d3-centro .d3c-pes > b{flex:1;min-width:0;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#d3-centro .d3c-pes > em{font-style:normal;font-weight:600;color:var(--d3-pronto)}
#d3-centro .d3c-pes > small{font-size:var(--d3-fs-texto);color:var(--d3-apagado);white-space:nowrap}
#d3-centro .d3c-fora{display:flex;flex-wrap:wrap;align-items:center;gap:5px;padding-top:8px;font-size:var(--d3-fs-texto);color:var(--d3-apagado)}
#d3-centro .d3c-sala{display:flex;align-items:center;gap:6px;padding:6px 0;border-top:1px solid var(--d3-linha)}
#d3-centro .d3c-sala > b{min-width:0;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#d3-centro .d3c-sala > small{flex:1;font-size:var(--d3-fs-texto);color:var(--d3-apagado);white-space:nowrap}
#d3-centro .d3c-btn{appearance:none;height:30px;padding:0 12px;border:0;border-radius:999px;background:var(--d3-trilho);color:var(--d3-tinta);font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);cursor:pointer}
#d3-centro .d3c-link{appearance:none;margin-top:6px;padding:0;border:0;background:none;color:var(--d3-tinta);font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);text-decoration:underline;text-decoration-color:var(--d3-borda);text-underline-offset:3px;cursor:pointer}
#d3-centro .d3c-vazio{padding:8px 0;border-top:1px solid var(--d3-linha);font-size:var(--d3-fs-texto);color:var(--d3-apagado)}
#d3-centro .d3c-col3{overflow:hidden}
#d3-centro .d3c-lojas{display:none;flex:1 1 auto;overflow:hidden}
#d3-centro .d3c-loja{appearance:none;display:grid;grid-template-columns:minmax(0,1fr) 70px 24px;align-items:center;gap:10px;width:100%;margin:0;padding:7px 0;border:0;border-top:1px solid var(--d3-linha);background:none;color:var(--d3-tinta);font:inherit;text-align:left;cursor:pointer}
#d3-centro .d3c-loja-nome{min-width:0;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
#d3-centro .d3c-loja .d3-barra.r > i{background:var(--d3-perigo)}
#d3-centro .d3c-loja > b{text-align:right}
#d3-centro .d3c-loja > b.r{color:var(--d3-perigo)}
#d3-centro .cliente-carteira{display:inline-flex;align-items:center;gap:5px;max-width:100%;padding:0;border:0;background:none;box-shadow:none;color:var(--carteira-texto,var(--d3-tinta));font:inherit;font-weight:600}
#d3-centro .cliente-carteira::before{content:"";flex:none;width:6px;height:6px;border-radius:50%;background:currentColor}
/* Controles do mapa dentro do cartão (canto de baixo à direita). */
body.mundo.mundo-centro.d3c-painel:not(.mundo-andar) #mundo-hud > .vv-controles.vv-ilha{top:auto;left:auto;right:var(--d3c-cr,26px);bottom:var(--d3c-cb,100px)}
body.mundo.mundo-centro.d3c-painel #mundo-hud > .vv-controles > .v2m-dica{display:none}
/* D3-Loja: a loja aberta ocupa o meio (no lugar do prédio) e a direita vira a lista de lojas por atraso. */
body.mundo.mundo-centro.d3c-painel:not(.mundo-modulo) #mundo-hud > #vv-placa:has(> .d3m-loja){left:var(--d3c-px,0px);top:var(--d3c-py,0px);right:auto;bottom:auto;width:var(--d3c-pw,360px);max-height:var(--d3c-ph,60vh);box-sizing:border-box;overflow:auto;border-radius:var(--d3-r-cartao)}
body.mundo.mundo-centro.d3c-painel #mundo-hud:has(> #vv-placa:not([hidden]) > .d3m-loja) > #d3-centro :is(.d3c-predio,.d3c-online,.d3c-salas,.d3c-mods-slot){display:none}
body.mundo.mundo-centro.d3c-painel #mundo-hud:has(> #vv-placa:not([hidden]) > .d3m-loja) > #d3-centro .d3c-lojas{display:block}
/* No cartão do meio fica o que o quadro D3-Loja mostra (números, em aberto, semana, quem está, botões), para caber sem
   rolar; a saúde, o mês e o resto do cliente seguem em "Ficha" e no celular, onde a ficha é a própria página. */
@media (min-width:901px){
  body.mundo.mundo-centro.d3c-painel #mundo-hud > #vv-placa > .d3m-loja :is(.d3m-end,.vv-cli){display:none}
  body.mundo.mundo-centro.d3c-painel #mundo-hud > #vv-placa > .d3m-loja{gap:8px}
  body.mundo.mundo-centro.d3c-painel:not(.mundo-modulo) #mundo-hud > #vv-placa:has(> .d3m-loja){padding-top:14px;padding-bottom:12px}
}
@media (max-width:900px){
  body.mundo.mundo-centro.d3c-painel #mundo-hud > #d3-centro{top:calc(var(--vv-m,8px) + 488px);left:var(--vv-m,8px);right:var(--vv-m,8px);bottom:76px;display:flex;flex-direction:column;overflow:auto;overscroll-behavior:contain;pointer-events:auto}
  #d3-centro .d3c-tit{position:fixed;top:calc(var(--vv-m,8px) + 56px);left:var(--vv-m,8px);right:var(--vv-m,8px)}
  #d3-centro .d3c-faixa{position:fixed;top:calc(var(--vv-m,8px) + 198px);left:var(--vv-m,8px);right:var(--vv-m,8px)}
  #d3-centro .d3c-mapa{position:fixed;top:calc(var(--vv-m,8px) + 276px);left:var(--vv-m,8px);right:var(--vv-m,8px);height:202px;min-height:0}
  body.mundo.mundo-centro.d3c-painel:not(.mundo-andar) #mundo-hud > .vv-controles.vv-ilha{display:none}
  #d3-centro .d3c-grade,#d3-centro .d3c-col1{display:contents}
  #d3-centro .d3c-nums{grid-template-columns:repeat(2,minmax(0,1fr));flex:none}
  #d3-centro :is(.d3c-mods-slot,.d3c-col2,.d3c-col3){flex:none}
  #d3-centro .d3c-mods{grid-template-columns:repeat(2,minmax(0,1fr))}
  body.mundo.mundo-centro.d3c-painel #mundo-hud #d3-centro .vv-legenda-cidade.v2m-barra{flex-wrap:wrap;row-gap:8px}
  #d3-centro .v2m-barra h1{font-size:24px}
  #d3-centro .v2m-barra > .v2n-busca{order:4;flex:1 1 100%;margin-left:0}
  #d3-centro .d3c-faixa > .v2m-fala.d3h-acao{padding:10px 12px;font-size:var(--d3-fs-destaque)}
  #d3-centro .v2m-fala.d3h-acao > .d3-acao-frase > span{white-space:normal;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
  #d3-centro .v2m-fala.d3h-acao > .d3-acao-btn{height:34px;padding:0 12px;font-size:var(--d3-fs-texto)}
  #d3-centro .d3c-col3{overflow:visible}
  body.mundo.mundo-centro.d3c-painel:not(.mundo-modulo) #mundo-hud > #vv-placa:has(> .d3m-loja){left:var(--vv-m,8px);right:var(--vv-m,8px);top:calc(var(--vv-m,8px) + 488px);bottom:76px;width:auto;max-height:none}
}

/* MINHA SALA PELO QUADRO (D3-MinhaSala): o quarto 3D vai para o cartão da esquerda (--d3s-q*, medido em pintarSalaD3);
   a faixa da sala vira o título; sem o Hoje estreito; Decorar abre a barra de itens dentro do cartão do quarto. */
body.mundo.mundo-quarto.d3s-painel #mundo-hud > #vv-hoje.vv-hoje{display:none}
body.mundo.d3s-painel #mundo-andar.quarto{background:var(--d3-areia)}
body.mundo.mundo-quarto.d3s-painel #mundo-andar.quarto > .andar-palco{inset:auto;left:var(--d3s-qx,0px);top:var(--d3s-qy,0px);width:var(--d3s-qw,100%);height:var(--d3s-qh,100%);border-radius:var(--d3-r-cartao);overflow:hidden}
body.mundo.mundo-quarto.d3s-painel #mundo-andar.quarto > .quarto-estado{position:absolute;left:var(--d3s-qx,0px);top:var(--d3s-qy,0px);width:var(--d3s-qw,100%);height:var(--d3s-qh,100%)}
#mundo-andar > #d3-sala{position:absolute;z-index:3;top:var(--vv-palco-topo,74px);left:calc(var(--vv-palco-esq,244px) + 8px);right:var(--vv-m,14px);bottom:calc(var(--vv-dock-alto,74px) + 12px);display:grid;grid-template-columns:minmax(0,1fr);grid-template-rows:auto auto auto minmax(0,1fr);gap:12px;pointer-events:none;color:var(--d3-tinta);font:400 var(--d3-fs-texto)/1.35 var(--vv-texto,Inter,sans-serif)}
#d3-sala > *,#d3-sala .d3s-grade > *{pointer-events:auto}
/* A grade em si deixa passar o toque: o cartão do quarto é um buraco, e arrastar, girar e dar zoom chegam ao 3D por
   baixo, como antes (Paulo, 14/11/2026: "deixa mexer a tela do 3D no lugar de fixa"). */
#d3-sala > .d3s-grade{pointer-events:none}
#d3-sala :is(h3,p){margin:0}
body.mundo.mundo-quarto.d3s-painel #mundo-andar.quarto #d3-sala .quarto-cab{position:static;inset:auto;display:flex;align-items:center;gap:12px;min-height:0;margin:0;padding:0;border:0;background:none;box-shadow:none}
#d3-sala .quarto-cab .quarto-cab-nome{display:flex;align-items:baseline;gap:10px;flex-direction:row-reverse;justify-content:flex-end}
#d3-sala .quarto-cab .quarto-cab-nome > b{font:700 var(--d3-fs-numero)/1.1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.02em;color:var(--d3-tinta)}
#d3-sala .quarto-cab .quarto-cab-nome > small{font:400 var(--d3-fs-destaque) var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado)}
#d3-sala .quarto-cab .quarto-quem{min-width:0}
#d3-sala .quarto-cab .quarto-acoes{margin-left:auto}
#d3-sala .d3s-acao{padding:14px 18px;border-radius:22px;font:600 var(--d3-fs-titulo)/1.25 var(--vv-titulo,"Inter Tight",Inter,sans-serif)}
#d3-sala .d3s-acao > .d3-acao-frase{display:flex;flex-direction:column;gap:1px;min-width:0}
#d3-sala .d3s-acao > .d3-acao-frase > small{font:700 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);opacity:.85}
#d3-sala .d3s-acao > .d3-acao-frase > span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#d3-sala .d3s-acao > .d3-acao-btn{height:40px;padding:0 20px}
#d3-sala .d3s-nums{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}
#d3-sala .d3s-num{min-height:0;padding:12px 16px;gap:4px;border-radius:18px}
#d3-sala .d3s-num-linha{display:flex;align-items:flex-end;justify-content:space-between;gap:8px;min-width:0}
#d3-sala .d3s-num-linha > .d3-graf{flex:none;width:80px}
#d3-sala .d3s-num .d3-num-v{font-size:var(--d3-fs-numero);animation:d3NumChega .55s cubic-bezier(.22,1,.36,1) both}
#d3-sala .d3s-num .d3-num-v > small{font:600 var(--d3-fs-destaque) var(--vv-titulo,"Inter Tight",Inter,sans-serif);color:var(--d3-apagado)}
#d3-sala .d3s-sub{font-size:var(--d3-fs-texto);color:var(--d3-apagado);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#d3-sala .d3s-grade{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr) minmax(0,.85fr);gap:14px;min-height:0}
#d3-sala .d3s-col2,#d3-sala .d3s-col3{display:flex;flex-direction:column;gap:14px;min-height:0;min-width:0;overflow:hidden}
/* Janela baixa (app do Mac com 650 de altura): o cartão não encolhe abaixo do conteúdo, a coluna rola por dentro.
   Antes o Humor do cartão Agora passava por cima do Seu dia (regra "nada cobre"). */
#d3-sala .d3s-grade > :is(.d3s-col2,.d3s-col3){overflow-y:auto;scrollbar-width:thin}
#d3-sala .d3s-grade > :is(.d3s-col2,.d3s-col3) > .d3s-cartao{flex-shrink:0}
#d3-sala .d3s-quarto{min-height:220px;border-radius:var(--d3-r-cartao);box-shadow:inset 0 0 0 1px rgba(31,29,26,.06);pointer-events:none}
#d3-sala .d3s-cartao{box-sizing:border-box;min-height:0;padding:14px 16px;border-radius:var(--d3-r-cartao);background:var(--d3-cartao)}
#d3-sala .d3s-quarto.d3s-cartao{background:transparent;padding:0}
#d3-sala .d3s-cab{display:flex;align-items:baseline;justify-content:space-between;gap:8px;padding-bottom:8px}
#d3-sala .d3s-cab > h3{font:700 var(--d3-fs-destaque) var(--vv-texto,Inter,sans-serif)}
#d3-sala .d3s-cab > small{font-size:var(--d3-fs-texto);color:var(--d3-apagado)}
#d3-sala .d3s-peca{appearance:none;display:flex;align-items:center;gap:12px;width:100%;margin:0;padding:0;border:0;background:none;color:var(--d3-tinta);font:inherit;text-align:left;cursor:pointer}
#d3-sala .d3s-thumb{flex:none;width:56px;height:56px;border-radius:12px;background:var(--d3-ajuste-veu)}
#d3-sala .d3s-peca-txt{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px}
#d3-sala .d3s-peca-txt > b{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#d3-sala .d3s-rot{margin-top:10px;font-size:var(--d3-fs-texto);color:var(--d3-apagado)}
#d3-sala .d3s-humor{display:flex;flex-wrap:wrap;gap:6px;margin-top:6px}
#d3-sala .d3s-humor > button{appearance:none;display:inline-flex;align-items:center;gap:6px;height:30px;padding:0 12px;border:0;border-radius:999px;background:var(--d3-trilho);color:var(--d3-tinta);font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);cursor:pointer}
#d3-sala .d3s-humor > button[aria-pressed="true"]{background:var(--d3-tinta);color:#FFFFFF}
#d3-sala .d3s-humor > button:disabled{cursor:default;opacity:.6}
#d3-sala .d3s-humor i{width:7px;height:7px;border-radius:50%;background:var(--d3-meta)}
#d3-sala .d3s-humor i.disponivel{background:var(--d3-pronto)}
#d3-sala .d3s-humor i.foco{background:#FFFFFF;box-shadow:inset 0 0 0 2px var(--d3-tinta)}
#d3-sala .d3s-humor i.reuniao{background:var(--d3-ajuste)}
#d3-sala .d3s-dia{flex:1 1 auto;display:flex;flex-direction:column;overflow:hidden}
#d3-sala .d3s-lista{display:flex;flex-direction:column;min-height:0;overflow:hidden}
#d3-sala .d3s-lin{appearance:none;display:flex;align-items:center;gap:10px;width:100%;margin:0;padding:8px 0;border:0;border-top:1px solid var(--d3-linha);background:none;color:var(--d3-tinta);font:inherit;text-align:left;cursor:pointer}
#d3-sala .d3s-lin > i{flex:none;width:18px;height:18px;border-radius:50%;box-shadow:inset 0 0 0 1.5px var(--d3-borda)}
#d3-sala .d3s-lin.feita > i{background:var(--d3-pronto);box-shadow:none}
#d3-sala .d3s-lin > .v2-risca{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
/* Coluna do meio estreita (1024 com o menu aberto, ~230 px): "Agora" mostrava "Ca..." e o cliente sumia, e no "Seu dia"
   o nome da peça virava "Car...". Abaixo de 300 px o nome ganha duas linhas e a data e o cliente descem. */
#d3-sala .d3s-col2{container:d3sc2 / inline-size}
@container d3sc2 (max-width:300px){
  #d3-sala .d3s-peca{flex-wrap:wrap;row-gap:6px}
  #d3-sala .d3s-thumb{width:40px;height:40px}
  #d3-sala .d3s-peca-txt{flex:1 1 calc(100% - 52px)}
  #d3-sala .d3s-peca-txt > b{white-space:normal;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}
  #d3-sala .d3s-peca > :last-child:not(.d3s-peca-txt){margin-left:52px}
  #d3-sala .d3s-lin{flex-wrap:wrap;row-gap:2px}
  #d3-sala .d3s-lin > .v2-risca{flex:1 1 calc(100% - 28px)}
  #d3-sala .d3s-lin > .cliente-carteira{max-width:calc(100% - 28px);margin-left:28px}
  #d3-sala .d3s-peca-txt > span > .cliente-carteira{max-width:100%}
}
#d3-sala .d3s-venc{flex:none;font-style:normal;font:600 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-perigo)}
#d3-sala .cliente-carteira{display:inline-flex;align-items:center;gap:5px;max-width:40%;padding:0;border:0;background:none;box-shadow:none;color:var(--carteira-texto,var(--d3-tinta));font:inherit;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#d3-sala .cliente-carteira::before{content:"";flex:none;width:6px;height:6px;border-radius:50%;background:currentColor}
#d3-sala .d3s-pe{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:auto;padding-top:10px;border-top:1px solid var(--d3-linha)}
#d3-sala .d3s-btn{appearance:none;height:34px;padding:0 16px;border:0;border-radius:999px;background:var(--d3-trilho);color:var(--d3-tinta);font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);cursor:pointer}
#d3-sala .d3s-btn.k{background:var(--d3-tinta);color:#FFFFFF}
#d3-sala .d3s-niveis{display:flex;gap:10px;padding-bottom:8px;font-size:var(--d3-fs-texto);color:var(--d3-texto2)}
#d3-sala .d3s-niveis > span{display:inline-flex;align-items:center;gap:5px}
#d3-sala .d3s-niveis i{width:9px;height:9px;border-radius:50%;background:var(--d3-cart-vinicius)}
#d3-sala .d3s-niveis i.n2{background:var(--d3-meta)}
#d3-sala .d3s-niveis i.n3{background:var(--d3-ajuste)}
#d3-sala .d3s-niveis i.n4{background:var(--d3-info)}
#d3-sala .d3s-marco{display:flex;flex-direction:column;gap:5px;padding:8px 0;border-top:1px solid var(--d3-linha)}
#d3-sala .d3s-marco > p{display:flex;justify-content:space-between;gap:8px}
#d3-sala .d3s-marco small{font-size:var(--d3-fs-apoio);color:var(--d3-apagado)}
#d3-sala .d3s-conq{flex:1 1 auto;display:flex;flex-direction:column;overflow:hidden}
#d3-sala .d3s-data{display:grid;grid-template-columns:48px minmax(0,1fr);gap:8px;padding:7px 0;border-top:1px solid var(--d3-linha)}
#d3-sala .d3s-data > span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
/* Datas: "N sem peça" à direita, em âmbar (quadro D3-MinhaSala). */
#d3-sala .d3s-data.falta{grid-template-columns:48px minmax(0,1fr) auto}
#d3-sala .d3s-data.falta > b{color:var(--d3-ajuste)}
#d3-sala .d3s-data > em{font:600 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);font-style:normal;color:var(--d3-ajuste);white-space:nowrap}
/* Agora: o foco no cabeçalho ("foco · mm:ss" com Parar, ou Iniciar foco) e a cor da sala em bolinhas. */
#d3-sala .d3s-cab > .d3s-foco{display:inline-flex;align-items:center;gap:8px;font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-apagado);white-space:nowrap}
#d3-sala .d3s-foco > b{font-weight:600;font-variant-numeric:tabular-nums;color:var(--d3-tinta)}
#d3-sala .d3s-foco .d3s-btn{height:28px;padding:0 12px;font-size:var(--d3-fs-texto)}
#d3-sala .d3s-foco.on .d3s-btn{background:var(--d3-tinta);color:var(--d3-cartao)}
#d3-sala .d3s-cor{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:12px}
#d3-sala .d3s-cor > .d3s-rot{margin:0}
#d3-sala .d3s-cores{display:flex;gap:8px}
#d3-sala .d3s-cores > button{appearance:none;width:24px;height:24px;margin:0;padding:0;border:0;border-radius:50%;background:var(--c);box-shadow:inset 0 0 0 1px var(--d3-linha);cursor:pointer}
#d3-sala .d3s-cores > button[aria-pressed="true"]{box-shadow:0 0 0 2px var(--d3-cartao),0 0 0 4px var(--d3-tinta)}
#d3-sala .d3s-cores > button:focus-visible{outline:2px solid var(--d3-acao);outline-offset:3px}
#d3-sala .d3s-cores > button:disabled{cursor:default;opacity:.6}
