.vv-personagem .vv-personagem-amostra[aria-pressed="true"],.vv-personagem .vv-personagem-amostra[aria-pressed="true"]:hover,.vv-personagem .vv-personagem-peca[aria-pressed="true"]{border-color:var(--d3-tinta);box-shadow:0 0 0 1px var(--d3-tinta)}
.vv-personagem .vv-personagem-giro button:hover{color:var(--d3-tinta)}

