#ofc-aviso-novo .aviso-form :is(input,textarea,select):focus-visible{outline:0;background:var(--d3-cartao);box-shadow:inset 0 0 0 1.5px var(--d3-tinta)}
#ofc-aviso-novo .aviso-form-nota{color:var(--d3-apagado);font:500 var(--d3-fs-apoio)/1.4 var(--vv-texto,Inter,sans-serif)}
