@media (max-width:720px){
  .vv-gestao .d3g-nums{grid-template-columns:repeat(2,minmax(0,1fr))}
  .vv-gestao .d3g-nums > .d3-num > .d3-num-v{font-size:var(--d3-fs-numero)}
  .vv-gestao .d3g-nums > .d3-num > .d3-graf{display:none}
  .vv-gestao .d3g > .d3-acao{flex-wrap:wrap}
  .vv-gestao .d3g > .d3-acao > .d3-acao-frase{flex:1 1 calc(100% - 52px);font-size:var(--d3-fs-destaque)}
  .vv-gestao .d3g > .d3-acao > .d3-acao-btn{margin-left:50px}
  .vv-gestao .d3g-set{grid-template-columns:minmax(0,1fr) auto}
  .vv-gestao .d3g-set-nome{grid-column:1/-1}
}
/* O leque da aprovação (Paulo, 15/11/2026, "card fan" de referência): as artes da fila abertas como cartas na mão, a
   da vez de pé no meio, as vizinhas giradas para os lados; passar de peça gira o leque com mola. A carta de informações
   fica ao lado, sem a arte repetida. */
#vv-conteudo.vc.vc .d3a-palco{display:grid;grid-template-columns:minmax(240px,46%) minmax(0,1fr);gap:20px;margin:0 18px;height:420px}
#vv-conteudo.vc.vc .d3a-palco .v2-baralho{margin:0;height:100%}
#vv-conteudo.vc.vc .d3a-palco .v2c-carta{grid-template-columns:minmax(0,1fr)}
#vv-conteudo.vc.vc .d3a-palco .d3a-arte-caixa{display:none}
#vv-conteudo.vc.vc .d3a-leque{position:relative;min-width:0;height:100%;perspective:1200px}
#vv-conteudo.vc.vc .d3a-leque-c{position:absolute;left:50%;top:52%;width:min(74%,250px);aspect-ratio:4/5;margin:0;padding:0;border:0;border-radius:18px;overflow:hidden;background:var(--d3-trilho);cursor:pointer;
  z-index:calc(10 - var(--alp));transform-origin:50% 120%;
  transform:translate(-50%,-50%) translateX(calc(var(--lp) * 40%)) rotate(calc(var(--lp) * 9deg)) translateY(calc(var(--alp) * 5%)) scale(calc(1 - var(--alp) * .07));
  box-shadow:0 18px 36px -18px color-mix(in srgb,var(--d3-tinta) 45%,transparent),0 0 0 1px var(--d3-borda);
  filter:saturate(calc(1 - var(--alp) * .22)) brightness(calc(1 - var(--alp) * .04));
  transition:transform .6s cubic-bezier(.34,1.45,.64,1),filter .4s ease,box-shadow .4s ease}
#vv-conteudo.vc.vc .d3a-leque-c.vez{cursor:default;box-shadow:0 28px 56px -22px color-mix(in srgb,var(--d3-tinta) 55%,transparent),0 0 0 2px var(--d3-tinta)}
#vv-conteudo.vc.vc .d3a-leque-c:not(.vez):hover{transform:translate(-50%,-54%) translateX(calc(var(--lp) * 40%)) rotate(calc(var(--lp) * 7deg)) translateY(calc(var(--alp) * 5%)) scale(calc(1.02 - var(--alp) * .07))}
#vv-conteudo.vc.vc .d3a-leque-c > img{display:block;width:100%;height:100%;object-fit:cover}
#vv-conteudo.vc.vc .d3a-leque-c > .d3a-selo{position:absolute;left:8px;top:8px;z-index:1}
#vv-conteudo.vc.vc .d3a-leque-c .vc-previa-msg,#vv-conteudo.vc.vc .d3a-leque-c .vc-previa-quadro{display:grid;place-items:center;width:100%;height:100%;padding:12px;box-sizing:border-box;text-align:center;font-size:var(--d3-fs-apoio);color:var(--d3-apagado)}
@media (prefers-reduced-motion:reduce){#vv-conteudo.vc.vc .d3a-leque-c{transition:none}}
@media (max-width:700px){
  #vv-conteudo.vc.vc .d3a-palco{grid-template-columns:minmax(0,1fr);grid-template-rows:280px auto;height:auto}
  #vv-conteudo.vc.vc .d3a-palco .v2-baralho{height:300px}
  #vv-conteudo.vc.vc .d3a-leque-c{width:min(52%,190px)}
}
/* A mesa da aprovação no padrão novo (Paulo, 15/11/2026: "do lado ali com a copy certinha como ia ficar no Insta, quem
   fez, as infos... princípios de modernidade", e "o nosso muito tudo branco; olha como esse usou bem as cores"): a mesa
   ocupa a largura toda (fila e equilíbrio embaixo, lado a lado), a arte grande no leque à esquerda e, à direita, o painel
   escuro com o post como sai no Instagram, quem fez e as informações, cada uma na sua cor. Aprovar é a ação: laranja. */
#vv-conteudo.vc.vc .v2c-cols{grid-template-columns:minmax(0,1fr)}
#vv-conteudo.vc.vc .v2c-lado{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));align-items:start}
#vv-conteudo.vc.vc .d3a-palco{grid-template-columns:minmax(0,1fr) minmax(320px,420px);gap:24px;height:560px}
#vv-conteudo.vc.vc .d3a-leque-c{width:min(56%,320px)}
#vv-conteudo.vc.vc .d3a-palco .v2-baralho > .d3a-ig{display:block;padding:0;border-radius:24px;background:var(--d3-tinta);color:var(--d3-cartao);box-shadow:0 30px 60px -30px color-mix(in srgb,var(--d3-tinta) 70%,transparent)}
#vv-conteudo.vc.vc .d3a-ig .d3a-info{height:100%;box-sizing:border-box;gap:14px;padding:18px 18px 16px;overflow-y:auto;scrollbar-width:thin}
#vv-conteudo.vc.vc .d3a-ig-tit{display:flex;flex-direction:column;gap:4px;margin:0}
#vv-conteudo.vc.vc .d3a-ig-tit b{font:700 var(--d3-fs-titulo)/1.2 var(--vv-titulo,Inter),sans-serif;color:var(--d3-cartao)}
#vv-conteudo.vc.vc .d3a-ig-tit .v2c-cli{color:color-mix(in srgb,var(--d3-cartao) 72%,transparent)}
/* O post como sai no Instagram: cartão claro dentro do painel escuro. */
#vv-conteudo.vc.vc .d3a-ig-post{display:flex;flex-direction:column;gap:8px;padding:12px 14px;border-radius:16px;background:var(--d3-cartao);color:var(--d3-tinta)}
#vv-conteudo.vc.vc .d3a-ig-cab{margin:0;padding:0;display:grid;grid-template-columns:auto minmax(0,1fr);grid-template-rows:auto auto;column-gap:10px;align-items:center}
#vv-conteudo.vc.vc .d3a-ig-av{grid-row:1 / 3;display:grid;place-items:center;width:34px;height:34px;border-radius:50%;overflow:hidden;background:var(--d3-trilho);box-shadow:0 0 0 2px var(--d3-cartao),0 0 0 4px var(--d3-acao);font:700 var(--d3-fs-mini) var(--vv-texto,Inter),sans-serif;color:var(--d3-texto2)}
#vv-conteudo.vc.vc .d3a-ig-av img{width:100%;height:100%;object-fit:cover}
#vv-conteudo.vc.vc .d3a-ig-cab b{font:700 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#vv-conteudo.vc.vc .d3a-ig-cab small{font-size:var(--d3-fs-mini);color:var(--d3-apagado)}
#vv-conteudo.vc.vc .d3a-ig-leg{margin:0;white-space:pre-line;font-size:var(--d3-fs-texto);line-height:1.45;overflow-wrap:anywhere}
#vv-conteudo.vc.vc .d3a-ig-leg b{font-weight:700}
#vv-conteudo.vc.vc .d3a-ig-sem{color:var(--d3-apagado);font-size:var(--d3-fs-apoio)}
/* Quem fez: rosto, nome e papel. */
#vv-conteudo.vc.vc .d3a-ig-quem{display:flex;flex-wrap:wrap;gap:8px 16px}
#vv-conteudo.vc.vc .d3a-ig-quem h4{flex-basis:100%;margin:0;font:700 var(--d3-fs-mini) var(--vv-texto,Inter),sans-serif;text-transform:uppercase;letter-spacing:.06em;color:color-mix(in srgb,var(--d3-cartao) 55%,transparent)}
#vv-conteudo.vc.vc .d3a-ig-pessoa{display:flex;align-items:center;gap:8px;min-width:0}
#vv-conteudo.vc.vc .d3a-ig-pessoa .v2c-av{width:30px;height:30px;background:var(--d3-acao);color:var(--d3-cartao);font-size:var(--d3-fs-mini)}
#vv-conteudo.vc.vc .d3a-ig-pessoa > span{display:flex;flex-direction:column;min-width:0}
#vv-conteudo.vc.vc .d3a-ig-pessoa b{font:600 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;color:var(--d3-cartao)}
#vv-conteudo.vc.vc .d3a-ig-pessoa small{font-size:var(--d3-fs-mini);color:color-mix(in srgb,var(--d3-cartao) 58%,transparent)}
/* As informações: blocos de vidro escuro, cada um com o ponto da sua cor. */
#vv-conteudo.vc.vc .d3a-ig-infos{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:0}
#vv-conteudo.vc.vc .d3a-ig-info{--c:var(--d3-cartao);padding:10px 12px;border-radius:14px;background:color-mix(in srgb,var(--d3-cartao) 8%,transparent);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--d3-cartao) 10%,transparent)}
#vv-conteudo.vc.vc .d3a-ig-info dt{display:flex;align-items:center;gap:6px;font-size:var(--d3-fs-mini);color:color-mix(in srgb,var(--d3-cartao) 60%,transparent)}
#vv-conteudo.vc.vc .d3a-ig-info dt i{width:8px;height:8px;border-radius:50%;background:var(--c);box-shadow:0 0 0 3px color-mix(in srgb,var(--c) 25%,transparent)}
