#vv-conteudo.vc.vc .d3a-ig-info dd b.a{color:color-mix(in srgb,var(--d3-ajuste) 45%,var(--d3-cartao))}
#vv-conteudo.vc.vc .d3a-ig-info[data-cor="status"]{--c:var(--d3-st,var(--d3-info))}
#vv-conteudo.vc.vc .d3a-ig-info[data-cor="formato"]{--c:var(--d3-info)}
#vv-conteudo.vc.vc .d3a-ig-info[data-cor="obj-atracao"]{--c:var(--d3-info)}
#vv-conteudo.vc.vc .d3a-ig-info[data-cor="obj-educacao"]{--c:var(--d3-pronto)}
#vv-conteudo.vc.vc .d3a-ig-info[data-cor="obj-conversao"]{--c:var(--d3-acao)}
#vv-conteudo.vc.vc .d3a-ig-info[data-cor="ar"]{--c:var(--d3-ajuste)}
#vv-conteudo.vc.vc .d3a-ig-info[data-cor="prazo"]{--c:var(--d3-perigo)}
