@media (max-width:900px){
  #vv-conteudo.vc.vc .v2c-lado{grid-template-columns:minmax(0,1fr)}
  #vv-conteudo.vc.vc .d3a-palco{grid-template-columns:minmax(0,1fr);grid-template-rows:300px minmax(0,auto);height:auto}
  #vv-conteudo.vc.vc .d3a-palco .v2-baralho{height:auto;min-height:520px}
}
/* O botão que abre a tela cheia, no topo do baralho. */
#vv-conteudo.vc.vc .d3a-tela-cheia{border:0;background:transparent;padding:0;font:inherit;font-weight:600;color:var(--d3-acao);cursor:pointer}
#vv-conteudo.vc.vc .d3a-leque-c.vez{cursor:zoom-in}

/* ===== padrao-v2/d3-series.css ===== */
/* Séries históricas nos quadros D3 (14/11/2026): as linhas que antes ficavam em "sem histórico ainda" e agora vêm de
   vybe_serie_diaria (server/series-historicas.js). Só o que é novo: a linha da Saúde na ficha, o Score por semana, a
   carga com o limite na Visão do setor e a carga por mês do Comercial. As cores são as do 0-d3-base.css. */

/* Ficha do cliente · Saúde: a linha no lugar do tracejado, com o "desde" embaixo. */
#painel-clientes .d3f-hist{display:grid;gap:2px;min-height:28px}
#painel-clientes .d3f-hist .d3-graf{max-height:40px}
#painel-clientes .d3f-hist > small{font-size:var(--d3-fs-apoio);color:var(--d3-apagado,#6B665E)}

/* Pessoas · Produtividade · Score por semana: linha larga, a do mês anterior tracejada, as semanas embaixo. */
#vv-pessoas.v2p-janela .v2p-semana .d3p-leg{display:inline-flex;gap:10px;font-size:var(--d3-fs-apoio);color:var(--d3-apagado)}
#vv-pessoas.v2p-janela .v2p-semana .d3p-semana-g{margin:10px 0 0}
#vv-pessoas.v2p-janela .v2p-semana .d3p-semana-g .d3-graf{height:96px;width:100%}
#vv-pessoas.v2p-janela .v2p-semana .d3p-semana-x{display:flex;justify-content:space-between;gap:6px;margin-top:8px;font-size:var(--d3-fs-apoio);color:var(--d3-apagado);font-variant-numeric:tabular-nums}
#vv-pessoas.v2p-janela .v2p-semana .d3p-semana-x .agora b{color:var(--d3-tinta)}

/* Visão do setor · Pessoas e carga: o limite tracejado; passou do limite, linha e número em vermelho. */
.d3s-leg.meta{margin-left:10px}
.d3s-leg.meta::before{content:'- - ';letter-spacing:-1px}
.d3s-pes.acima .d3-graf polyline:not(.meta){stroke:var(--d3-perigo)}
.d3s-pes.acima .d3-graf circle{fill:var(--d3-perigo)}
.d3s-pes.acima .d3s-pes-n{color:var(--d3-perigo)}
.d3s-limite-btn{margin-left:8px;padding:0;border:0;background:none;font:inherit;font-size:var(--d3-fs-apoio);color:var(--d3-tinta);text-decoration:underline;cursor:pointer}
.d3s-limite{display:flex;flex-wrap:wrap;align-items:center;gap:8px;padding:8px 16px;border-top:1px solid var(--d3-linha);font-size:var(--d3-fs-texto)}
.d3s-limite[hidden]{display:none}
.d3s-limite input{width:64px;margin-left:6px;padding:4px 6px;border:1px solid var(--d3-borda,#D8D2C6);border-radius:8px;font:inherit}
.d3s-limite-msg{color:var(--d3-apagado)}

/* Comercial · Pacotes · Carga do cargo: a linha por mês com a capacidade tracejada. */
#vv-comercial.v2c.d3c .d3c-carga-g.d3c-carga-linha{display:grid;place-items:stretch;height:auto;padding:8px 0;gap:4px}
#vv-comercial.v2c.d3c .d3c-carga-linha svg.d3-graf{width:100%;height:64px}
#vv-comercial.v2c.d3c .d3c-carga-x{display:flex;justify-content:space-between;gap:8px;font-size:var(--d3-fs-apoio);color:var(--d3-apagado)}

/* Agentes · cabeçalho: a meta de acerto (só os donos) abre num cartão pequeno embaixo do botão. */
.d3t-meta{position:relative}
.d3t-meta > summary{list-style:none;cursor:pointer}
.d3t-meta > summary::-webkit-details-marker{display:none}
.d3t-meta-form{position:absolute;right:0;top:calc(100% + 6px);z-index:5;display:flex;flex-wrap:wrap;align-items:center;gap:8px;min-width:240px;padding:10px 12px;border:1px solid var(--d3-linha,#E6E0D6);border-radius:12px;background:var(--d3-cartao,#fff);box-shadow:0 8px 24px rgba(0,0,0,.08);font-size:var(--d3-fs-texto)}
.d3t-meta-form input{width:60px;margin:0 4px 0 6px;padding:4px 6px;border:1px solid var(--d3-borda,#D8D2C6);border-radius:8px;font:inherit}
.d3t-meta-msg{flex-basis:100%;color:var(--d3-apagado)}
/* Visão do setor · limite por pessoa: um campo por pessoa ao lado do padrão. */
.d3s-limite label{display:inline-flex;align-items:center;white-space:nowrap}

/* ===== padrao-v2/d3-time.css ===== */
/* DIREÇÃO 3 · TIME (moodboard 3 aprovado em 13/11/2026). Recursos Humanos (Produtividade, Pedidos e calendário,
   Recrutamento, Documentos, Academy), Equipe online, Conta e equipe, Agentes, perfil do agente e Automações.
   Fundo areia, cartão branco de canto 20, um bloco de ação laranja por tela, gráficos em linha. Usa as peças e os
   tokens de padrao-v2/0-d3-base.css. */

/* ===== RECURSOS HUMANOS ===== */
/* Quadros D3-Produtividade, D3-RhPedidos, D3-Recrutamento, D3-Documentos e D3-Academy. O prefixo com a classe da janela
   passa à frente de padrao-v2/pessoas.css, que vem depois na junção. */
#vv-pessoas.v2p-janela .vp-topo.vb-janela-topo{padding:24px 30px 0}
#vv-pessoas.v2p-janela .vp-topo.vb-janela-topo > .vb-cabecalho{flex-wrap:wrap;row-gap:10px}
#vv-pessoas.v2p-janela .vp-topo .vb-cabecalho-texto{flex:0 1 auto;display:flex;align-items:baseline;gap:14px;min-width:0}
#vv-pessoas.v2p-janela .vp-topo .vb-cabecalho-acoes{flex:1 1 auto;display:flex;justify-content:flex-end;min-width:0;margin-left:auto}
#vv-pessoas.v2p-janela .vp-topo .vb-cabecalho-texto > h2{white-space:nowrap}
#vv-pessoas.v2p-janela .vp-topo.vb-janela-topo .vb-cabecalho-texto > p{max-width:none;margin:0;font:400 var(--d3-fs-destaque) var(--vv-texto,Inter),sans-serif;color:var(--d3-apagado);white-space:nowrap}
#vv-pessoas.v2p-janela .vp-topo .vp-topo-botoes{gap:8px}
#vv-pessoas.v2p-janela .vp-topo-botoes > .d3p-abas{order:0;display:flex;gap:0;margin:0;padding:4px;border:0;border-radius:999px;background:var(--d3-trilho);overflow-x:auto;scrollbar-width:none}
#vv-pessoas.v2p-janela .vp-topo-botoes > .d3p-abas[hidden]{display:none}
#vv-pessoas.v2p-janela .vp-topo-botoes > .d3p-abas > button{position:relative;flex:none;height:32px;margin:0;padding:0 12px;border:0;border-radius:999px;background:transparent;color:var(--d3-texto2);font:500 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;box-shadow:none;transition:background-color .25s cubic-bezier(.22,1,.36,1),color .25s}
#vv-pessoas.v2p-janela .vp-topo-botoes > .d3p-abas > button::after{display:none}
#vv-pessoas.v2p-janela .vp-topo-botoes > .d3p-abas > button[aria-selected="true"]{background:var(--d3-tinta);color:#FFFFFF;font-weight:600;animation:d3pAbaEstica .35s cubic-bezier(.22,1,.36,1) both}
@keyframes d3pAbaEstica{from{transform:scaleX(.82)}to{transform:none}}
#vv-pessoas.v2p-janela .vp-periodo .vb-mes{height:40px;box-shadow:none}
#vv-pessoas.v2p-janela .vp-corpo{gap:14px;padding:14px 30px 26px}
#vv-pessoas.v2p-janela .v2p{gap:14px}

/* Bloco de ação: o único laranja cheio; quem fala em cima, a frase grande e o botão branco. */
#vv-pessoas.v2p-janela .v2p-fala.d3-acao{display:flex;align-items:center;gap:14px;padding:14px 20px;border-radius:22px}
#vv-pessoas.v2p-janela .v2p-fala > .v2p-ag{position:relative;width:36px;height:36px;background:#FFFFFF;color:var(--d3-agente);font:700 var(--d3-fs-destaque) var(--vv-texto,Inter),sans-serif}
#vv-pessoas.v2p-janela .v2p-fala > .d3-acao-frase{display:block;flex:1;min-width:0;margin:0;overflow:visible;font:600 var(--d3-fs-titulo)/1.3 var(--vv-titulo,"Inter Tight"),Inter,sans-serif;color:#FFFFFF}
#vv-pessoas.v2p-janela .v2p-fala > .d3-acao-frase b{display:inline;font-weight:600}
/* Acabamento premium (15/11/2026): a nota branca (.d3-nota, quando não há ação) com a frase do mesmo tamanho da do bloco
   laranja em RH, Conta, Agentes e Automações (o tamanho grande estava preso a .d3-acao-frase). */
#vv-pessoas.v2p-janela .v2p-fala.d3-nota{gap:14px;padding:14px 20px;border-radius:22px}
#vv-pessoas.v2p-janela .v2p-fala > .d3-nota-frase,#conta-root #v2c.d3c .d3-nota .d3-nota-frase,:is(#vv-agentes,#automacoes-root) .d3-nota .d3-nota-frase{display:block;flex:1;min-width:0;margin:0;overflow:visible;font:600 var(--d3-fs-titulo)/1.3 var(--vv-titulo,"Inter Tight"),Inter,sans-serif;color:var(--d3-tinta)}
#vv-pessoas.v2p-janela .v2p-fala .v2p-quem{display:block;margin-bottom:2px;font:600 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;color:#FFFFFF;opacity:.82}
#vv-pessoas.v2p-janela .v2p-fala > .v2p-btn{flex:none;height:40px;padding:0 20px;background:#FFFFFF;box-shadow:none;color:var(--d3-acao-texto);font:700 var(--d3-fs-destaque) var(--vv-texto,Inter),sans-serif}
#vv-pessoas.v2p-janela .v2p-fala > .v2p-btn:hover{background:#FFF4EE}
#vv-pessoas.v2p-janela .v2p-fala > .v2p-btn[aria-expanded="true"]{background:var(--d3-tinta);color:#FFFFFF}

/* Números: rótulo, número que chega (com o "/ 18" menor), linha ou barra e o pé curto. */
#vv-pessoas.v2p-janela .v2p-kpi.d3-num{gap:6px;padding:12px 16px;border-radius:18px}
#vv-pessoas.v2p-janela .v2p-kpi > .d3-num-rot{font-size:var(--d3-fs-texto);font-weight:400;color:var(--d3-apagado)}
#vv-pessoas.v2p-janela .d3p-num-linha{display:flex;align-items:flex-end;justify-content:space-between;gap:10px;min-width:0}
#vv-pessoas.v2p-janela .d3p-num-linha > .d3-num-v{font:700 36px/1 var(--vv-titulo,"Inter Tight"),Inter,sans-serif;white-space:nowrap}
#vv-pessoas.v2p-janela .d3p-num-linha > .d3-graf{flex:none;width:90px}
#vv-pessoas.v2p-janela .d3p-de{font-size:var(--d3-fs-titulo);font-weight:600;color:var(--d3-apagado);letter-spacing:0}
#vv-pessoas.v2p-janela .v2p-kpi > .d3-barra{margin-top:7px}
#vv-pessoas.v2p-janela .v2p-kpi > .d3p-num-sub{font-size:var(--d3-fs-texto);color:var(--d3-apagado)}
#vv-pessoas.v2p-janela .v2p-kpi .d3p-aviso{font-weight:600;color:var(--d3-ajuste)}
#vv-pessoas.v2p-janela .v2p-kpi.ruim .d3-num-v{color:var(--d3-perigo)}
#vv-pessoas.v2p-janela .v2p-kpi.atencao .d3-num-v{color:var(--d3-ajuste)}

/* Cartões, cabeçalhos e linhas. */
#vv-pessoas.v2p-janela .v2p-card{padding:14px 16px}
#vv-pessoas.v2p-janela .v2p-cab > h3{font:700 var(--d3-fs-destaque)/1.2 var(--vv-texto,Inter),sans-serif}
#vv-pessoas.v2p-janela .v2p-lin{padding:9px 0;font-size:var(--d3-fs-texto)}
#vv-pessoas.v2p-janela .v2p-grade{gap:14px}
#vv-pessoas.v2p-janela .v2p-linha[aria-expanded="true"]{margin:0 -16px;padding:0 16px;background:var(--d3-trilho);box-shadow:inset 3px 0 0 var(--d3-tinta)}
#vv-pessoas.v2p-janela .v2p-chip{height:36px;padding:0 14px;box-shadow:none;font-size:var(--d3-fs-texto)}
#vv-pessoas.v2p-janela .v2p-chip[aria-pressed="true"]{background:var(--d3-tinta)}
#vv-pessoas.v2p-janela .v2p-barra-f > .v2p-btn.s{height:36px;padding:0 14px;box-shadow:none}
#vv-pessoas.v2p-janela .v2p .v2p-busca.v2p-busca{height:36px;box-shadow:none}
#vv-pessoas.v2p-janela .v2p-btn.s:not(.k){background:var(--d3-trilho);box-shadow:none}
#vv-pessoas.v2p-janela .v2p-btn.s:not(.k):hover{background:var(--d3-borda)}
#vv-pessoas.v2p-janela .v2p-barra-f > .vp-periodo{display:flex;align-items:center;gap:8px}
#vv-pessoas.v2p-janela .v2p-barra-f > .vp-periodo .vp-seg{background:#FFFFFF}
#vv-pessoas.v2p-janela .v2p-barra-f > .vp-periodo .vp-seg button[aria-pressed="true"]{background:var(--d3-tinta);color:#FFFFFF;box-shadow:none}
#vv-pessoas.v2p-janela .v2p-barra-f > .vp-periodo .vb-mes{height:36px}
#vv-pessoas.v2p-janela .v2p-pe{display:flex;align-items:center;gap:8px}

/* Colunas da lista (Produtividade e Documentos): Pessoa · Metas · Conquistas · Score. */
#vv-pessoas.v2p-janela .d3p-th{display:grid;grid-template-columns:minmax(0,1fr) 64px 84px 180px 22px;gap:10px;padding:2px 0 6px;font-size:var(--d3-fs-apoio);color:var(--d3-apagado)}
#vv-pessoas.v2p-janela .d3p-th > span:last-child{grid-column:4}
#vv-pessoas.v2p-janela .d3p-th-docs{grid-template-columns:minmax(0,1fr) 56px 150px 22px}
#vv-pessoas.v2p-janela .d3p-th-docs > span:last-child{grid-column:3}
#vv-pessoas.v2p-janela .d3p-col-meta,#vv-pessoas.v2p-janela .d3p-col-conq,#vv-pessoas.v2p-janela .d3p-col-docs{flex:none;width:64px;font-size:var(--d3-fs-texto);font-variant-numeric:tabular-nums}
#vv-pessoas.v2p-janela .d3p-col-conq{width:84px}
#vv-pessoas.v2p-janela .d3p-col-docs{width:56px}
#vv-pessoas.v2p-janela .d3p-col-sit{flex:none;width:150px;display:flex}
#vv-pessoas.v2p-janela .d3p-col-meta.g{font-weight:600;color:var(--d3-pronto)}
#vv-pessoas.v2p-janela .d3p-col-meta.a{font-weight:600;color:var(--d3-ajuste)}
#vv-pessoas.v2p-janela .v2p-barra-lin.d3-barra{width:140px;height:6px;background:var(--d3-linha)}
#vv-pessoas.v2p-janela .v2p-barra-lin.d3-barra.a > i{background:var(--d3-ajuste)}
#vv-pessoas.v2p-janela .v2p-sc{width:30px;font:700 var(--d3-fs-destaque) var(--vv-titulo,"Inter Tight"),Inter,sans-serif}
#vv-pessoas.v2p-janela .v2p-sc.a{color:var(--d3-ajuste)}

/* Calendário do time: dias maiores, hoje branco com anel escuro, legenda embaixo. */
#vv-pessoas.v2p-janela .v2p-cal-duas{gap:20px}
#vv-pessoas.v2p-janela .v2p-cal{width:auto;flex:1 1 auto;max-width:520px;min-width:0;gap:5px}
#vv-pessoas.v2p-janela .v2p-cal-lado{flex:0 0 190px}
#vv-pessoas.v2p-janela .v2p-dia{height:58px;padding:5px 7px;border-radius:12px;background:var(--d3-trilho);color:var(--d3-apagado);font-size:var(--d3-fs-apoio)}
#vv-pessoas.v2p-janela .v2p-dia.hoje{background:#FFFFFF;box-shadow:inset 0 0 0 2px var(--d3-tinta);color:var(--d3-tinta);font-weight:700}
#vv-pessoas.v2p-janela .v2p-dia.fora{background:none}
#vv-pessoas.v2p-janela .v2p-pill.mi{height:18px;padding:0 6px;font-size:var(--d3-fs-mini)}
#vv-pessoas.v2p-janela .v2p-pill.an{background:#FFFFFF;color:var(--d3-tinta)}
#vv-pessoas.v2p-janela .v2p-pill.an::before{content:"";width:5px;height:5px;border-radius:50%;background:#9D50DD}
#vv-pessoas.v2p-janela .v2p-leg-t > span{font-weight:400;margin-left:6px;font-size:var(--d3-fs-apoio)}
#vv-pessoas.v2p-janela .v2p-leg{padding:7px 0;border-top:1px solid var(--d3-linha);font-size:var(--d3-fs-texto)}
#vv-pessoas.v2p-janela .d3p-legenda{display:flex;flex-wrap:wrap;gap:12px;margin-top:auto;padding-top:10px;border-top:1px solid var(--d3-linha);font-size:var(--d3-fs-apoio);color:var(--d3-apagado)}
#vv-pessoas.v2p-janela .v2p-leg-fim + .d3p-legenda{margin-top:8px}
#vv-pessoas.v2p-janela .d3p-legenda > span{display:inline-flex;align-items:center;gap:5px}
#vv-pessoas.v2p-janela .d3p-legenda i{display:inline-block;width:12px;height:10px;border-radius:4px;box-sizing:border-box}
#vv-pessoas.v2p-janela .d3p-legenda i.g{background:var(--d3-pronto-veu)}
#vv-pessoas.v2p-janela .d3p-legenda i.pd{border:1px dashed var(--d3-meta)}
#vv-pessoas.v2p-janela .d3p-legenda i.an{width:7px;height:7px;border-radius:50%;background:#9D50DD}
#vv-pessoas.v2p-janela .v2p-baralho{height:272px}
#vv-pessoas.v2p-janela .v2p-carta{box-shadow:0 2px 4px rgba(31,29,26,.06),0 18px 30px -20px rgba(31,29,26,.4),inset 0 0 0 1px var(--d3-linha)}
#vv-pessoas.v2p-janela .v2p-col-baralho{padding:14px 16px;border-radius:var(--d3-r-cartao);background:var(--d3-cartao)}

/* Vencimentos (Documentos): linha do tempo com "hoje" e um ponto por renovação. */
#vv-pessoas.v2p-janela .d3p-venc{flex:1}
#vv-pessoas.v2p-janela .d3p-tl{position:relative;height:64px;margin:18px 6px 0}
#vv-pessoas.v2p-janela .d3p-tl::before{content:"";position:absolute;left:0;right:0;top:22px;height:2px;background:var(--d3-linha)}
#vv-pessoas.v2p-janela .d3p-tl-hoje{position:absolute;top:0;bottom:16px;width:2px;background:var(--d3-tinta)}
#vv-pessoas.v2p-janela .d3p-tl-hoje > b{position:absolute;top:-16px;left:50%;transform:translateX(-50%);font-size:var(--d3-fs-apoio);white-space:nowrap}
#vv-pessoas.v2p-janela .d3p-tl-pt{position:absolute;top:14px;display:flex;flex-direction:column;align-items:center;gap:6px;transform:translateX(-50%)}
#vv-pessoas.v2p-janela .d3p-tl-pt > i{width:14px;height:14px;border-radius:50%;background:var(--d3-ajuste);animation:d3PontoChega .9s cubic-bezier(.34,1.56,.64,1) both}
#vv-pessoas.v2p-janela .d3p-tl-pt.r > i{background:var(--d3-perigo)}
#vv-pessoas.v2p-janela .d3p-tl-pt > small{font:600 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;color:var(--d3-ajuste);white-space:nowrap}
#vv-pessoas.v2p-janela .d3p-tl-pt.r > small{color:var(--d3-perigo)}
#vv-pessoas.v2p-janela .d3p-tl-eixo{display:flex;justify-content:space-between;margin-top:8px;font-size:var(--d3-fs-apoio);color:var(--d3-apagado)}
#vv-pessoas.v2p-janela .d3p-tipos{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin-top:auto;padding-top:10px;border-top:1px solid var(--d3-linha)}
#vv-pessoas.v2p-janela .d3p-tipos > .v2p-chip{height:28px;background:var(--d3-trilho)}
#vv-pessoas.v2p-janela .d3p-tipos > .v2p-chip[aria-pressed="true"]{background:var(--d3-tinta)}

@media (prefers-reduced-motion:reduce){
  #vv-pessoas.v2p-janela .vp-topo-botoes > .d3p-abas > button[aria-selected="true"],#vv-pessoas.v2p-janela .d3p-tl-pt > i{animation:none}
}
@container v2p (max-width:900px){
  #vv-pessoas.v2p-janela .v2p-tres{grid-template-columns:repeat(2,minmax(0,1fr))}
  #vv-pessoas.v2p-janela .d3p-th{display:none}
}
@container v2p (max-width:620px){
  #vv-pessoas.v2p-janela .v2p-tres{grid-template-columns:minmax(0,1fr)}
  #vv-pessoas.v2p-janela .v2p-fala.d3-acao{flex-wrap:wrap;padding:12px 14px}
  #vv-pessoas.v2p-janela .v2p-fala > .d3-acao-frase{flex:1 1 calc(100% - 52px);font-size:var(--d3-fs-destaque)}
  #vv-pessoas.v2p-janela .v2p-fala > .d3-nota-frase{font-size:var(--d3-fs-destaque)}
