  #vv-pessoas.v2p-janela .vp-topo .vb-cabecalho-texto{flex-wrap:wrap;row-gap:2px}
  #vv-pessoas.v2p-janela .vp-topo-botoes > .d3p-abas{flex:1 1 100%;order:0}
  #vv-pessoas.v2p-janela .vp-corpo{padding:12px 16px 20px}
}

/* ===== FIM RECURSOS HUMANOS ===== */

/* ===== CONTA E EQUIPE · EQUIPE ONLINE ===== */
/* Conta e equipe (quadro D3-ContaEquipe): título com "Gestão", o bloco de ação, quatro números, três colunas (Pede ação
   e Operação · Seu perfil · Equipe com "dono" e "coordenação") e a fileira Abrir. O prefixo com os dois ids passa à
   frente de padrao-v2/topo.css (que vem depois na junção) só pela especificidade. */
#conta-root #v2c.d3c{gap:12px;margin:-22px -30px -36px;padding:14px 30px 30px;border-radius:var(--d3-r-janela);background:var(--d3-areia);font:400 var(--d3-fs-texto)/1.4 var(--vv-texto,Inter),sans-serif;color:var(--d3-tinta)}
#conta-root #v2c.d3c .v2c-perfil .v2c-dado > .v2c-sub{overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
#conta-root #v2c.d3c .v2c-topo{flex-wrap:nowrap;align-items:baseline;gap:8px}
#conta-root #v2c.d3c .v2c-topo h1{flex:0 1 auto;font:700 var(--d3-fs-numero)/1.1 var(--vv-titulo,"Inter Tight"),Inter,sans-serif;letter-spacing:-.02em}
#conta-root #v2c.d3c .d3c-onde{flex:1 1 auto;min-width:0;margin-left:6px;align-self:baseline;font-size:var(--d3-fs-destaque);color:var(--d3-apagado)}
#conta-root #v2c.d3c .v2c-topo .v2c-btn{height:40px;padding:0 16px;font:600 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;box-shadow:none}
#conta-root #v2c.d3c .v2c-topo .v2c-btn:not(.k){background:var(--d3-cartao);color:var(--d3-tinta)}
#conta-root #v2c.d3c .v2c-topo .v2c-btn.k{background:var(--d3-tinta);color:#FFFFFF}
#conta-root #v2c.d3c .d3c-fala > .d3-acao{border-radius:22px;padding:12px 20px}
#conta-root #v2c.d3c .d3-acao .d3-acao-av{width:36px;height:36px;font-size:var(--d3-fs-destaque)}
#conta-root #v2c.d3c .d3-acao .d3-acao-frase{display:flex;flex-direction:column;gap:2px;font:600 var(--d3-fs-titulo)/1.25 var(--vv-titulo,"Inter Tight"),Inter,sans-serif;color:#FFFFFF;-webkit-text-fill-color:#FFFFFF}
#conta-root #v2c.d3c .d3-acao .d3c-quem{font:600 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;opacity:.82}
#conta-root #v2c.d3c .d3-acao .d3-acao-btn{height:40px;padding:0 20px;font-size:var(--d3-fs-destaque);color:var(--d3-acao-texto);-webkit-text-fill-color:var(--d3-acao-texto)}
#conta-root #v2c.d3c .d3-acao .d3-acao-btn:disabled{opacity:.6;cursor:not-allowed}

/* Os quatro números. */
#conta-root #v2c.d3c .d3c-nums{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}
#conta-root #v2c.d3c .d3c-num{display:grid;grid-template-columns:auto minmax(0,1fr);align-items:center;gap:6px 8px;border:0;border-radius:18px;padding:12px 16px;text-align:left;font:inherit;color:var(--d3-tinta);cursor:pointer;-webkit-text-fill-color:currentColor}
#conta-root #v2c.d3c button.d3c-num:hover{box-shadow:inset 0 0 0 1px var(--d3-borda)}
#conta-root #v2c.d3c .d3c-num > .d3-num-rot{grid-column:1 / -1;font-size:var(--d3-fs-texto);font-weight:400}
#conta-root #v2c.d3c .d3c-num > .d3-num-v{font-size:36px;white-space:nowrap}
#conta-root #v2c.d3c .d3c-num > .d3-num-v small{font-size:var(--d3-fs-titulo);font-weight:600;color:var(--d3-apagado);letter-spacing:0}
#conta-root #v2c.d3c .d3c-num > .d3c-num-lado{min-width:0;display:flex;justify-content:flex-end}
#conta-root #v2c.d3c .d3c-num > .d3c-num-pe{grid-column:1 / -1;display:inline-flex;align-items:center;gap:5px;font-size:var(--d3-fs-texto);color:var(--d3-apagado)}
#conta-root #v2c.d3c .d3c-num > .d3-barra{grid-column:1 / -1;margin-top:7px}
#conta-root #v2c.d3c .d3c-num .v2c-av{width:26px;height:26px;font-size:10px}
#conta-root #v2c.d3c .d3c-num .v2c-av.mais{background:var(--d3-trilho);color:var(--d3-apagado)}
#conta-root #v2c.d3c .d3c-num .v2c-clis{gap:8px}
#conta-root #v2c.d3c .d3c-num .v2c-cli{max-width:120px;font-size:var(--d3-fs-texto);color:var(--d3-cart-vinicius);-webkit-text-fill-color:currentColor}
#conta-root #v2c.d3c .d3c-num .v2c-cli::before{width:5px;height:5px;background:currentColor}
#conta-root #v2c.d3c .d3c-num .v2c-cli + .v2c-cli{color:var(--d3-cart-ewerton)}

/* Três colunas; quem não administra fica com duas (Pede ação · Seu perfil). */
#conta-root #v2c.d3c .d3c-cols{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.1fr) minmax(0,1fr);gap:12px;align-items:stretch}
#conta-root #v2c.d3c .d3c-cols.so-eu{grid-template-columns:minmax(0,1fr) minmax(0,1.1fr)}
/* Confere responsivo (14/11/2026): no painel estreito (1024 com o menu aberto) as três colunas ficavam com 200 px e o
   perfil empilhava "PNG · JPG · até 2 MB" letra sobre letra. No painel estreito: Pede ação e perfil lado a
   lado e a Equipe embaixo, na largura toda (abaixo de 900 px de painel). */
#conta-root #v2c.d3c{container:d3conta / inline-size}
@container d3conta (max-width:900px){
  #conta-root #v2c.d3c .d3c-cols{grid-template-columns:minmax(0,1fr) minmax(0,1.1fr)}
  #conta-root #v2c.d3c .d3c-cols > .d3c-equipe{grid-column:1 / -1}
}
@container d3conta (max-width:620px){
  #conta-root #v2c.d3c .d3c-cols,#conta-root #v2c.d3c .d3c-cols.so-eu{grid-template-columns:minmax(0,1fr)}
}
#conta-root #v2c.d3c .d3c-col{display:flex;flex-direction:column;gap:12px;min-width:0}
#conta-root #v2c.d3c .d3c-cartao{display:flex;flex-direction:column;padding:14px 0 6px;border-radius:var(--d3-r-cartao);background:var(--d3-cartao);box-shadow:none}
#conta-root #v2c.d3c .d3c-operacao{flex:1}
#conta-root #v2c.d3c .d3c-cartao > .v2c-card-topo{align-items:center;margin:0;padding:0 16px 8px}
#conta-root #v2c.d3c .d3c-cartao > .v2c-card-topo h2{font:700 var(--d3-fs-destaque)/1.2 var(--vv-texto,Inter),sans-serif}
#conta-root #v2c.d3c .d3c-cartao > .v2c-lin{padding:10px 16px;border-top:1px solid var(--d3-linha);font-size:var(--d3-fs-texto)}
#conta-root #v2c.d3c .d3c-cartao > .v2c-tudo-certo{margin:0 16px 10px}
#conta-root #v2c.d3c .v2c-btn.s{height:30px;padding:0 12px;background:var(--d3-trilho);box-shadow:none;font:600 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif}
#conta-root #v2c.d3c .v2c-btn.s.k{background:var(--d3-tinta);color:#FFFFFF;-webkit-text-fill-color:#FFFFFF}
#conta-root #v2c.d3c .v2c-btn.s:hover{background:var(--d3-borda)}
#conta-root #v2c.d3c .v2c-btn.s.k:hover{background:#000000}
#conta-root #v2c.d3c .v2c-btn.s:disabled{background:var(--d3-trilho);color:var(--d3-apagado);-webkit-text-fill-color:var(--d3-apagado)}
#conta-root #v2c.d3c .v2c-pill{height:22px;font-size:var(--d3-fs-apoio)}
#conta-root #v2c.d3c .v2c-pill.n{background:var(--d3-trilho);color:var(--d3-tinta)}
#conta-root #v2c.d3c .v2c-pill.d3c-dono{background:var(--d3-tinta);color:#FFFFFF;-webkit-text-fill-color:#FFFFFF}

/* Pede ação: etiqueta e nome na primeira linha; o rótulo curto e o botão (que conta o estado) na segunda. */
#conta-root #v2c.d3c .d3c-pend{display:grid;grid-template-columns:auto minmax(0,1fr);align-items:center;gap:6px 10px}
#conta-root #v2c.d3c .d3c-pend > .d3c-pend-baixo{grid-column:1 / -1;display:flex;align-items:center;gap:6px;min-width:0}
#conta-root #v2c.d3c .d3c-pend-txt{flex:1 1 auto;min-width:0;font-size:var(--d3-fs-texto);color:var(--d3-apagado)}
#conta-root #v2c.d3c .d3c-pend-baixo > .v2c-btn{margin-left:auto}
#conta-root #v2c.d3c .d3c-pend-baixo > .v2c-btn.k{min-width:116px}
#conta-root #v2c.d3c .d3c-op{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px}
#conta-root #v2c.d3c .d3c-operacao > .d3c-op{padding-top:6px;padding-bottom:6px}
#conta-root #v2c.d3c .d3c-op > span{display:flex;flex-direction:column;gap:2px;min-width:0}
#conta-root #v2c.d3c .d3c-op small{font-size:var(--d3-fs-apoio);color:var(--d3-apagado)}

/* Seu perfil. */
#conta-root #v2c.d3c .v2c-perfil{padding:16px 18px 10px}
#conta-root #v2c.d3c .v2c-perfil > .v2c-quem{gap:12px;margin:0;padding-bottom:12px}
#conta-root #v2c.d3c .v2c-perfil .v2c-retrato{width:52px;height:52px;background:var(--d3-linha);box-shadow:inset 0 0 0 1.5px #C9C2B6;font:700 var(--d3-fs-titulo) var(--vv-texto,Inter),sans-serif}
#conta-root #v2c.d3c .v2c-perfil .v2c-retrato span{color:var(--d3-texto2)}
#conta-root #v2c.d3c .v2c-perfil .v2c-quem h2{font:700 var(--d3-fs-titulo)/1.2 var(--vv-titulo,"Inter Tight"),Inter,sans-serif}
#conta-root #v2c.d3c .v2c-perfil .v2c-quem .v2c-pill{height:24px;padding:0 10px}
#conta-root #v2c.d3c .v2c-perfil .v2c-lin{padding:10px 0;font-size:var(--d3-fs-texto)}
#conta-root #v2c.d3c .v2c-perfil .v2c-quem + .v2c-lin{border-top:1px solid var(--d3-linha)}
#conta-root #v2c.d3c .v2c-perfil .v2c-dado{grid-template-columns:64px minmax(0,1fr) auto;gap:0 10px}
#conta-root #v2c.d3c .d3c-fichas{display:flex;flex-wrap:wrap;gap:4px}
#conta-root #v2c.d3c .d3c-fichas > i{display:inline-flex;align-items:center;height:22px;padding:0 8px;border-radius:999px;background:var(--d3-trilho);color:var(--d3-texto2);font:600 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif}
#conta-root #v2c.d3c .v2c-senha-campos{gap:6px;padding:0 0 10px 74px}
#conta-root #v2c.d3c .v2c-senha-campos input{height:30px;border-radius:10px;padding:0 10px;font-size:var(--d3-fs-apoio);box-shadow:inset 0 0 0 1px var(--d3-borda)}
#conta-root #v2c.d3c .conta-ai-codigo,#conta-root #v2c.d3c .conta-ai-aviso{padding-left:74px}
#conta-root #v2c.d3c .v2c-nota{margin-top:auto;padding-top:8px;border-top:1px solid var(--d3-linha);font-size:var(--d3-fs-apoio)}
/* Tema: a aba preta estica até a escolha. */
#conta-root #v2c.d3c .d3c-seg{position:relative;background:var(--d3-trilho)}
#conta-root #v2c.d3c .d3c-seg > .d3c-seg-ind{position:absolute;top:4px;bottom:4px;left:4px;width:80px;border-radius:999px;background:var(--d3-tinta);transition:left .35s cubic-bezier(.32,.72,0,1),width .35s cubic-bezier(.32,.72,0,1)}
#conta-root #v2c.d3c .d3c-seg[data-tema="escuro"] > .d3c-seg-ind{left:84px;width:76px}
#conta-root #v2c.d3c .d3c-seg > button{position:relative;width:80px;height:32px;padding:0;background:none;box-shadow:none;font:500 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;color:var(--d3-texto2);-webkit-text-fill-color:var(--d3-texto2);transition:color .35s}
#conta-root #v2c.d3c .d3c-seg > button + button{width:76px}
#conta-root #v2c.d3c .d3c-seg > button[aria-checked="true"]{background:none;box-shadow:none;font-weight:600;color:#FFFFFF;-webkit-text-fill-color:#FFFFFF}

/* Equipe: uma linha por pessoa, "dono" cheia e "coordenação" clara; o pé abre a seção com as ações. */
#conta-root #v2c.d3c .d3c-equipe{padding-bottom:0;overflow:hidden}
#conta-root #v2c.d3c .d3c-eq{display:grid;grid-template-columns:26px minmax(0,1fr) auto;gap:10px;padding:8px 16px}
#conta-root #v2c.d3c .d3c-eq > :is(b,span:not(.v2c-av):not(.v2c-pill)){min-width:0;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
#conta-root #v2c.d3c .d3c-eq > .v2c-av{width:26px;height:26px;margin:0;box-shadow:none;font-size:var(--d3-fs-mini)}
#conta-root #v2c.d3c .d3c-eq-pe{margin-top:auto;height:38px;padding:0 16px;border:0;border-top:1px solid var(--d3-linha);background:transparent;color:var(--d3-texto2);-webkit-text-fill-color:var(--d3-texto2);font:600 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;text-align:left;cursor:pointer}
#conta-root #v2c.d3c .d3c-eq-pe:hover{color:var(--d3-tinta);-webkit-text-fill-color:var(--d3-tinta)}
#conta-root #v2c.d3c .d3c-eq-erro{margin:0;padding:8px 16px}

/* A seção aberta pela fileira e a fileira Abrir. */
#conta-root #v2c.d3c .v2c-secao{border-radius:var(--d3-r-cartao);box-shadow:none}
#conta-root #v2c.d3c .v2c-abrir{gap:6px}
#conta-root #v2c.d3c .v2c-abrir > .v2c-sub{margin-right:4px}
#conta-root #v2c.d3c .v2c-chip{height:30px;background:var(--d3-cartao);box-shadow:none}
#conta-root #v2c.d3c .v2c-chip[aria-pressed="true"]{background:var(--d3-tinta)}

@media (max-width:900px){
  #conta-root #v2c.d3c .v2c-topo{flex-wrap:wrap}
  #conta-root #v2c.d3c .v2c-topo h1{font-size:24px}
  #conta-root #v2c.d3c .d3c-onde{flex:1 1 auto}
  #conta-root #v2c.d3c .d3-acao .d3-acao-frase{font-size:var(--d3-fs-destaque)}
  #conta-root #v2c.d3c .d3-nota .d3-nota-frase{font-size:var(--d3-fs-destaque)}
  #conta-root #v2c.d3c .d3c-fala > .d3-acao{flex-wrap:wrap;padding:12px 14px}
  #conta-root #v2c.d3c .d3-acao .d3-acao-frase{flex:1 1 calc(100% - 52px)}
  #conta-root #v2c.d3c .d3-acao .d3-acao-btn{margin-left:50px}
  #conta-root #v2c.d3c .d3c-nums{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
  #conta-root #v2c.d3c .d3c-num > .d3-num-v{font-size:var(--d3-fs-numero)}
  #conta-root #v2c.d3c .d3c-num > .d3c-num-lado{grid-column:1 / -1;justify-content:flex-start}
  #conta-root #v2c.d3c .d3c-cols,#conta-root #v2c.d3c .d3c-cols.so-eu{grid-template-columns:minmax(0,1fr)}
  #conta-root #v2c.d3c .v2c-senha-campos,#conta-root #v2c.d3c .conta-ai-codigo,#conta-root #v2c.d3c .conta-ai-aviso{padding-left:0}
  #conta-root #v2c.d3c .v2c-perfil .v2c-dado{grid-template-columns:minmax(0,1fr) auto}
}
@media (prefers-reduced-motion:reduce){
  #conta-root #v2c.d3c .d3c-seg > .d3c-seg-ind,#conta-root #v2c.d3c .d3c-seg > button{transition:none}
}

/* Equipe online (quadro D3-EquipeOnline). A marcação é de vybe-mundo.js (mostrarEquipe); aqui só a forma: fundo
   areia, a fala do VYBES vira o bloco de ação laranja, "Conversa da equipe" deixa de ser laranja, números grandes e
   cartões com cabeçalho e linhas de borda fina. */
#vv-placa .v2e{gap:14px;margin:-26px -30px;padding:26px 30px;min-height:calc(100% + 52px);box-sizing:border-box;border-radius:var(--d3-r-janela);background:var(--d3-areia)}
#vv-placa .v2e .v2e-topo{gap:8px}
#vv-placa .v2e .v2e-topo > h1{font:700 var(--d3-fs-numero)/1.1 var(--vv-titulo,"Inter Tight"),Inter,sans-serif;letter-spacing:-.02em}
#vv-placa .v2e .v2e-topo > .vv-moedas-selo{height:40px;padding:0 16px;border-radius:999px;background:var(--d3-trilho);font:600 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif}
#vv-placa .v2e .v2e-topo > .v2n-btn.p{height:40px;background:var(--d3-cartao);color:var(--d3-tinta);box-shadow:none;font:600 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif}
#vv-placa .v2e .v2e-topo > .v2n-btn.p:hover{box-shadow:inset 0 0 0 1px var(--d3-borda)}
/* A fala vira o bloco de ação (a única faixa laranja). */
#vv-placa .v2e .v2n-fala{gap:14px;padding:14px 20px;border-radius:22px;background:var(--d3-acao);box-shadow:none}
#vv-placa .v2e .v2n-fala > .v2n-ag{width:36px;height:36px;background:#FFFFFF;color:var(--d3-agente);isolation:isolate}
/* o pulso branco no compositor (como o do bloco de ação em 0-d3-base.css); na fala quieta o branco não aparecia: sem pulso */
#vv-placa .v2e .v2n-fala > .v2n-ag::after{content:"";inset:0;z-index:-1;border:0;border-radius:50%;background:inherit;pointer-events:none;animation:d3PulsaBrancoAnel 2.4s ease-in-out infinite}
#vv-placa .v2e .v2n-fala.v2n-fala-quieta > .v2n-ag::after{content:none}
#vv-placa .v2e .v2n-fala > p{font:600 var(--d3-fs-titulo)/1.3 var(--vv-titulo,"Inter Tight"),Inter,sans-serif;color:#FFFFFF}
#vv-placa .v2e .v2n-fala > p b{font-weight:600;color:#FFFFFF}
#vv-placa .v2e .v2n-fala .v2n-quem{font:600 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;color:#FFFFFF;opacity:.82}
#vv-placa .v2e .v2n-fala > .v2n-btn{height:40px;padding:0 20px;background:#FFFFFF;color:var(--d3-acao-texto);box-shadow:none;font:700 var(--d3-fs-destaque) var(--vv-texto,Inter),sans-serif}
#vv-placa .v2e .v2n-fala > .v2n-btn:hover{background:#FFF4EE}
/* Os três números. */
#vv-placa .v2e .v2e-nums{gap:12px}
#vv-placa .v2e .v2e-nums > .v2n-kpi{padding:12px 16px;border-radius:18px;box-shadow:none}
#vv-placa .v2e .v2e-nums > .v2n-kpi > b{margin:4px 0;font:700 36px/1 var(--vv-titulo,"Inter Tight"),Inter,sans-serif;justify-content:space-between}
#vv-placa .v2e .v2e-nums > .v2n-kpi > b > .v2-num{animation:d3NumChega .55s cubic-bezier(.22,1,.36,1) both}
#vv-placa .v2e .v2e-nums > .v2n-kpi:nth-child(2) > b > .v2-num{animation-delay:.15s}
#vv-placa .v2e .v2e-nums > .v2n-kpi:nth-child(3) > b > .v2-num{animation-delay:.3s}
#vv-placa .v2e .v2e-nums > .v2n-kpi.quieto > b{color:var(--d3-tinta)}
#vv-placa .v2e .v2n-avs .v2n-av{width:26px;height:26px;font-size:10px}
/* Cartões: título em cima, linhas com borda fina, sem sombra. */
#vv-placa .v2e .v2e-grade > .v2n-card,#vv-placa .v2e .v2e-esq > .v2n-card{display:flex;flex-direction:column;padding:14px 0 6px;border-radius:var(--d3-r-cartao);box-shadow:none}
#vv-placa .v2e .v2n-card > .v2n-cab{align-items:center;margin:0;padding:0 16px 8px}
#vv-placa .v2e .v2n-card > .v2n-cab > h2{font:700 var(--d3-fs-destaque)/1.2 var(--vv-texto,Inter),sans-serif}
#vv-placa .v2e .v2n-card .v2n-lin{padding:10px 16px;font-size:var(--d3-fs-texto)}
#vv-placa .v2e .v2n-card > .v2n-cab + .v2n-lin{border-top:1px solid var(--d3-linha)}
#vv-placa .v2e .v2e-nada,#vv-placa .v2e .v2e-pe{padding-left:16px;padding-right:16px}
#vv-placa .v2e .v2e-pe{padding-top:8px;padding-bottom:4px;border-top:1px solid var(--d3-linha)}
#vv-placa .v2e .v2e-missoes .v2e-cx{width:18px;height:18px}
#vv-placa .v2e .v2e-filtros{margin:0;padding:0 16px 8px}
#vv-placa .v2e .v2e-filtros > .v2n-busca{flex:1 1 180px;min-width:0;height:34px;padding:0 14px;border:0;border-radius:999px;background:var(--d3-trilho);box-shadow:none}
#vv-placa .v2e .v2e-filtros > .v2n-chip{height:34px;background:var(--d3-trilho);box-shadow:none}
#vv-placa .v2e .v2e-filtros > .v2n-chip[aria-pressed="true"]{background:var(--d3-tinta);color:#FFFFFF}
#vv-placa .v2e .v2e-lista > .v2n-lin,#vv-placa .v2e .v2e-lista > .v2e-sala > .v2n-lin{padding:10px 16px;border-top:1px solid var(--d3-linha)}
#vv-placa .v2e .v2e-sala[aria-expanded="true"]{box-shadow:inset 3px 0 0 var(--d3-tinta);background:var(--d3-trilho)}
#vv-placa .v2e .v2e-det{margin:0 16px 10px;padding:4px 12px;border-radius:14px;background:var(--d3-cartao)}
#vv-placa .v2e .v2e-portas{gap:6px}
#vv-placa .v2e .v2e-portas > .v2n-chip{background:var(--d3-cartao);box-shadow:none}
@media (max-width:900px){
  #vv-placa .v2e{margin:-16px;padding:16px;min-height:calc(100% + 32px)}
  #vv-placa .v2e .v2e-topo > h1{font-size:24px}
  #vv-placa .v2e .v2n-fala{flex-wrap:wrap;padding:12px 14px}
  #vv-placa .v2e .v2n-fala > p{flex:1 1 calc(100% - 52px);font-size:var(--d3-fs-destaque)}
  #vv-placa .v2e .v2n-fala > .v2n-btn{margin-left:50px}
  #vv-placa .v2e .v2e-nums > .v2n-kpi > b{font-size:26px}
}
@media (prefers-reduced-motion:reduce){
  #vv-placa .v2e .v2n-fala > .v2n-ag,#vv-placa .v2e .v2e-nums > .v2n-kpi > b > .v2-num{animation:none}
  #vv-placa .v2e .v2n-fala > .v2n-ag::after{content:none}
}

/* ===== FIM CONTA E EQUIPE · EQUIPE ONLINE ===== */

/* ===== AGENTES · PERFIL DO AGENTE · AUTOMAÇÕES ===== */
/* Quadros D3-Agentes, D3-PerfilAgente e D3-Automacoes: fundo areia, cartões brancos sem sombra, o bloco de ação
   laranja, os números em cartão (d3-num) com a linha curta de baixo e as pílulas claras com bolinha da cor do estado. */
#vv-agentes.v2a,#automacoes-root.v2r{background:var(--d3-areia)}
:is(#vv-agentes,#automacoes-root) .v2g-card.v2g-card{border-radius:var(--d3-r-cartao);box-shadow:none}
:is(#vv-agentes,#automacoes-root) .d3-acao{border-radius:22px;padding:14px 16px 14px 20px}
:is(#vv-agentes,#automacoes-root) .d3-acao .d3-acao-av{width:36px;height:36px;font-size:var(--d3-fs-destaque)}
:is(#vv-agentes,#automacoes-root) .d3-acao .d3-acao-frase{font:600 var(--d3-fs-titulo)/1.25 var(--vv-titulo,"Inter Tight"),Inter,sans-serif;white-space:nowrap}
:is(#vv-agentes,#automacoes-root) .d3-acao .d3-acao-frase > .d3t-quem{display:block;margin-bottom:2px;font:600 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;color:#FFFFFF;opacity:.82}
:is(#vv-agentes,#automacoes-root) .d3-acao .d3-acao-btn{height:40px;padding:0 20px;font-size:var(--d3-fs-destaque)}
:is(#vv-agentes,#automacoes-root) .d3t-nums{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}
:is(#vv-agentes,#automacoes-root) .d3t-nums > .d3-num{border:0;border-radius:18px;text-align:left;font:inherit;color:var(--d3-tinta)}
:is(#vv-agentes,#automacoes-root) .d3t-nums > button.d3-num{cursor:pointer}
:is(#vv-agentes,#automacoes-root) .d3t-nums > button.d3-num:hover{box-shadow:inset 0 0 0 1px var(--d3-borda)}
:is(#vv-agentes,#automacoes-root) .d3t-nums .d3-num-rot{font-weight:400;font-size:var(--d3-fs-texto)}
:is(#vv-agentes,#automacoes-root) .d3t-nums .d3-num-v{font-size:34px}
:is(#vv-agentes,#automacoes-root) .d3t-nums .d3-num-v small{font:600 var(--d3-fs-titulo) var(--vv-titulo,"Inter Tight"),Inter,sans-serif;letter-spacing:0;color:var(--d3-apagado)}
:is(#vv-agentes,#automacoes-root) .d3t-nums .d3-barra{margin-top:4px}
:is(#vv-agentes,#automacoes-root) .d3t-sub{display:flex;flex-wrap:wrap;align-items:center;gap:5px;min-width:0;font:400 var(--d3-fs-texto)/1.35 var(--vv-texto,Inter),sans-serif;color:var(--d3-apagado)}
:is(#vv-agentes,#automacoes-root) .d3-num.r .d3t-sub{color:var(--d3-perigo)}
:is(#vv-agentes,#automacoes-root) .d3t-a{font-weight:600;color:var(--d3-ajuste)}
/* Pílula clara com a bolinha na cor do estado (--c); cheia só no que venceu e no finalizado. */
:is(#vv-agentes,#automacoes-root) .d3t-pil{flex:none;display:inline-flex;align-items:center;gap:5px;height:22px;padding:0 9px;border-radius:999px;background:var(--d3-trilho);color:var(--d3-texto2);font:600 var(--d3-fs-apoio)/1 var(--vv-texto,Inter),sans-serif;white-space:nowrap}
:is(#vv-agentes,#automacoes-root) .d3t-pil > i{flex:none;width:7px;height:7px;border-radius:50%;background:var(--c,var(--d3-meta))}
:is(#vv-agentes,#automacoes-root) .d3t-pil.cheia-r{background:var(--d3-perigo-veu);color:var(--d3-perigo)}
:is(#vv-agentes,#automacoes-root) .d3t-pil.cheia-g{background:var(--d3-pronto-veu);color:var(--d3-pronto)}
:is(#vv-agentes,#automacoes-root) .d3t-pe{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin:0;padding:10px 0 0;border-top:1px solid var(--d3-linha)}
:is(#vv-agentes,#automacoes-root) .d3t-pe .v2g-chip{height:28px;padding:0 10px;border-radius:999px;background:var(--d3-trilho);box-shadow:none;font-weight:600}
:is(#vv-agentes,#automacoes-root) .d3t-pe .v2g-chip[aria-pressed="true"]{background:var(--d3-tinta);color:#FFFFFF}
:is(#vv-agentes,#automacoes-root) .v2g-btn.s:not(.k){background:var(--d3-trilho);box-shadow:none}
:is(#vv-agentes,#automacoes-root) .v2g-btn.s:not(.k):hover{background:var(--d3-borda)}

/* Agentes · topo: título com o dia ao lado; o sinal da central em âmbar com "Tentar de novo". */
#vv-agentes.v2a .d3t-topo .vb-cabecalho-texto{display:flex;align-items:baseline;flex-wrap:wrap;gap:4px 14px}
#vv-agentes.v2a .d3t-topo .vb-cabecalho-texto > p{margin:0;font:400 var(--d3-fs-destaque) var(--vv-texto,Inter),sans-serif;color:var(--d3-apagado)}
#vv-agentes.v2a .d3t-sinal{display:inline-flex;align-items:center;gap:10px;height:40px;padding:0 4px 0 14px;border-radius:999px;background:var(--d3-ajuste-veu);color:var(--d3-ajuste);font:600 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;white-space:nowrap}
#vv-agentes.v2a .d3t-sinal::before{content:"";width:7px;height:7px;border-radius:50%;background:currentColor}
#vv-agentes.v2a .d3t-sinal > button{height:32px;padding:0 12px;border:0;border-radius:999px;background:#FFFFFF;color:var(--d3-ajuste);font:600 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;cursor:pointer}
#vv-agentes.v2a .d3t-pensa{background:var(--d3-trilho);box-shadow:none}
#vv-agentes.v2a .d3t-pensa > span{display:grid;place-items:center;width:18px;height:18px;border-radius:50%;box-shadow:inset 0 0 0 1.5px var(--d3-apagado);color:var(--d3-apagado);font:700 var(--d3-fs-mini) var(--vv-texto,Inter),sans-serif}
#vv-agentes.v2a .vga-detalhe.v2a-corpo{gap:14px}

/* Agentes · "Para você decidir" em cartões e "Como cada um está indo". */
#vv-agentes.v2a .d3t-grade{grid-template-columns:minmax(0,1.15fr) minmax(0,1fr);align-items:stretch}
#vv-agentes.v2a .d3t-decidir,#vv-agentes.v2a .d3t-grade > .v2a-vao{display:flex;flex-direction:column;padding:14px 18px 12px}
#vv-agentes.v2a .d3t-decidir > .v2g-cab,#vv-agentes.v2a .d3t-grade > .v2a-vao > .v2g-cab{align-items:center;margin-bottom:6px}
#vv-agentes.v2a .d3t-decidir > .v2g-cab .v2g-sub{display:inline-flex;align-items:center;gap:8px}
#vv-agentes.v2a .d3t-decidir > .v2g-cab .d3t-pil{background:var(--d3-ajuste-veu);color:var(--d3-ajuste)}
#vv-agentes.v2a .d3t-peds{flex:1;display:flex;flex-direction:column}
#vv-agentes.v2a .d3t-ped{display:flex;flex-direction:column;gap:9px;min-width:0;padding:14px 0;border-top:1px solid var(--d3-linha);outline:none}
#vv-agentes.v2a .d3t-ped.frente{border-top:0;padding-top:6px}
#vv-agentes.v2a .d3t-ped-cab{display:flex;flex-wrap:wrap;align-items:center;gap:6px 8px;min-width:0;font:400 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif}
#vv-agentes.v2a .d3t-ped-cab > b{font-weight:700}
#vv-agentes.v2a .d3t-prazo{margin-left:auto;font:600 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;color:var(--d3-apagado)}
#vv-agentes.v2a .d3t-prazo.r{color:var(--d3-ajuste)}
#vv-agentes.v2a .d3t-ped-tit{font:600 var(--d3-fs-titulo)/1.25 var(--vv-titulo,"Inter Tight"),Inter,sans-serif;color:var(--d3-tinta);overflow-wrap:anywhere}
#vv-agentes.v2a .d3t-ped-prova{display:flex;flex-direction:column;gap:2px;padding:8px 12px;border-radius:12px;background:var(--d3-trilho);font:400 var(--d3-fs-texto)/1.4 var(--vv-texto,Inter),sans-serif;color:var(--d3-texto2)}
#vv-agentes.v2a .d3t-ped-prova > span{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;white-space:pre-line;overflow-wrap:anywhere}
#vv-agentes.v2a .d3t-ped-prova > small{font-size:var(--d3-fs-apoio);color:var(--d3-apagado)}
#vv-agentes.v2a .d3t-ped-pe{display:flex;flex-wrap:wrap;align-items:center;gap:8px}
#vv-agentes.v2a .d3t-veio{flex:1 1 120px;min-width:0;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;color:var(--d3-apagado);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#vv-agentes.v2a .d3t-ped-pe > .v2g-btn{height:36px;padding:0 16px;font-size:var(--d3-fs-texto)}
#vv-agentes.v2a .d3t-decidir > .d3t-pe{margin-top:auto}
#vv-agentes.v2a .d3t-agl.v2a-agl{grid-template-columns:28px minmax(0,1fr) auto 52px 64px 32px;padding:10px 0}
#vv-agentes.v2a .d3t-agl .v2a-agl-nome .v2g-sub{margin-left:4px}
/* A cor do humor (--humor) fica na linha, sem a faixa lateral que o quadro D3 não tem. */
#vv-agentes.v2a .d3t-agl.v2-humor:not(#vb-h1):not(#vb-h2){box-shadow:none}
#vv-agentes.v2a .d3t-ped-n{font:400 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;color:var(--d3-apagado);text-align:right}
#vv-agentes.v2a .d3t-ped-n.r{font-weight:600;color:var(--d3-ajuste)}
#vv-agentes.v2a .d3t-agl .d3-barra{height:4px}
#vv-agentes.v2a .d3-barra.parada > i{animation:none}
#vv-agentes.v2a .d3t-agl .v2a-nt{font-size:var(--d3-fs-titulo)}
#vv-agentes.v2a .d3t-grade > .v2a-vao > .d3t-pe{margin-top:auto}
#vv-agentes.v2a .d3t-conta{margin-left:auto;padding:5px 10px;border-radius:999px;background:var(--d3-trilho);font:400 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;color:var(--d3-apagado)}
#vv-agentes.v2a .d3t-conta > b{font-weight:600;color:var(--d3-tinta)}
#vv-agentes.v2a .v2a-alerta{margin:8px 0 0;padding:8px 12px;border-radius:12px}

/* Perfil do agente: números no alto e três colunas. */
#vv-agentes.v2a .v2a-topo > .v2g-ag{width:44px;height:44px}
#vv-agentes.v2a .v2a-topo .v2g-btn:not(.s),#vv-agentes.v2a .v2a-topo .v2g-btn.s{height:40px;padding:0 16px;background:var(--d3-trilho);box-shadow:none;font-size:var(--d3-fs-texto)}
#vv-agentes.v2a .v2a-onde{font-size:var(--d3-fs-destaque)}
#vv-agentes.v2a .d3t-perfil{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.1fr) minmax(0,1.1fr);gap:14px;align-items:start}
#vv-agentes.v2a .d3t-perfil > div{display:flex;flex-direction:column;gap:14px;min-width:0}
#vv-agentes.v2a .d3t-perfil .v2g-card{padding:14px 16px}
#vv-agentes.v2a .d3t-perfil .v2g-cab{align-items:center;margin-bottom:6px}
#vv-agentes.v2a .d3t-perfil .v2a-faz .d3t-pe{margin-top:8px}
#vv-agentes.v2a .d3t-perfil .v2a-fazl{min-height:22px}
#vv-agentes.v2a .d3t-aprendeu .v2g-lin{padding:9px 0;gap:10px;font-size:var(--d3-fs-texto)}
#vv-agentes.v2a .d3t-aprendeu .d3t-pil{align-self:flex-start}
#vv-agentes.v2a .d3t-espera{padding:14px 16px}
#vv-agentes.v2a .d3t-espera .v2a-mesa{align-items:stretch}
#vv-agentes.v2a .d3t-espera .v2a-baralho.menor{width:auto;max-width:calc(100% - 28px);height:250px}
#vv-agentes.v2a .d3t-espera .v2a-decide,#vv-agentes.v2a .d3t-espera .v2a-baralho.menor ~ .v2a-decide{width:auto;max-width:calc(100% - 28px)}
#vv-agentes.v2a .d3t-espera .v2a-carta{padding:14px;gap:8px;background:#FFFFFF}
#vv-agentes.v2a .d3t-espera .v2a-carta[data-pos="1"],#vv-agentes.v2a .d3t-espera .v2a-carta[data-pos="2"]{background:#F9F8F5}
#vv-agentes.v2a .d3t-espera .v2a-tit{font-size:var(--d3-fs-titulo)}
#vv-agentes.v2a .d3t-espera .v2a-prova{padding:10px 12px;border-radius:12px}
#vv-agentes.v2a .d3t-espera .v2a-vazio{width:auto;padding:0}
#vv-agentes.v2a .d3t-exec .d3-graf polyline.meta{stroke-dasharray:3 4}
#vv-agentes.v2a .d3t-leg{display:inline-flex;align-items:center;gap:6px}
#vv-agentes.v2a .d3t-leg > i{display:inline-block;width:16px;height:0;border-top:2.5px solid var(--d3-tinta)}
#vv-agentes.v2a .d3t-leg > i.t{border-top:1.5px dashed var(--d3-meta);margin-left:6px}
#vv-agentes.v2a .d3t-eixo{display:flex;justify-content:space-between;margin-top:8px;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;color:var(--d3-apagado)}
#vv-agentes.v2a .d3t-eixo > b{color:var(--d3-tinta)}
#vv-agentes.v2a .d3t-perfil .v2a-rotinas .v2g-lin{flex-wrap:wrap;gap:4px 10px;padding:10px 0}
#vv-agentes.v2a .d3t-perfil .v2a-rotinas .v2g-lin > p{flex:1 1 100%}
#vv-agentes.v2a .d3t-perfil .v2a-rotinas .v2g-lin > .v2g-sub{flex:1 1 auto;min-width:0}
/* Pílulas do agente: claras com a bolinha na cor (vermelho no urgente, âmbar na atenção, azul na sombra); cheia só
   em Resolvido e Valendo, o equivalente do Finalizado. */
#vv-agentes.v2a :is(.v2g-pill.r,.v2g-pill.a,.v2g-pill.b,.v2g-pill.v,.v2g-pill.n){background:var(--d3-trilho);color:var(--d3-texto2)}
#vv-agentes.v2a :is(.v2g-pill.r,.v2g-pill.a,.v2g-pill.b,.v2g-pill.v)::before{content:"";flex:none;width:7px;height:7px;border-radius:50%;background:var(--c)}
#vv-agentes.v2a .v2g-pill.r{--c:var(--d3-perigo)}
#vv-agentes.v2a .v2g-pill.a{--c:#E0A21B}
#vv-agentes.v2a :is(.v2g-pill.b,.v2g-pill.v){--c:#0D74CE}

/* Automações: título com "Gestão" ao lado, a aba preta escolhida, "Nova regra" preta e as regras em linha. */
#automacoes-root.v2r > .vb-cabecalho .vb-cabecalho-texto{display:flex;align-items:baseline;flex-wrap:wrap;gap:4px 14px}
#automacoes-root.v2r > .vb-cabecalho .vb-cabecalho-texto > p{margin:0;font:400 var(--d3-fs-destaque) var(--vv-texto,Inter),sans-serif;color:var(--d3-apagado)}
/* A aba escolhida é preta sobre o trilho (a regra antiga de vybe-mundo.css que pintava de cinza todo botão dentro de um
