/* Minha sala no quadro (d3s-painel, confere responsivo de 14/11/2026): o 3D fica dentro do cartão e não há mais coluna
   à esquerda; o dock herdava o recuo do quarto antigo (left = coluna + vão) e, em 1024, passava da borda direita. */
@media (min-width:901px){body.mundo.mundo-quarto.d3s-painel #vv-dock-salas-faixa{left:var(--vv-palco-esq,0px)}}

/* Acabamento premium (15/11/2026, item 12): o aviso encolhido em pílula ao lado do dock (#vv-wa-avisos.pilula, posto por
   vybe-core.js na vaga que sobra, às vezes só 120 px) destoava do dock e cortava o nome do grupo logo no começo. Fica com a
   cara do dock (branco, a mesma sombra, sem borda) e com menos folga em volta do ícone, para o nome ganhar espaço; o nome
   termina em "…". A largura vem do script (mínimo 120): subir para 170 é com vybe-core.js. */
#vv-wa-avisos.pilula:not(.aberto) .vv-aviso-curto{gap:5px;padding:0 12px 0 5px;border:0;background:var(--d3-cartao);box-shadow:0 2px 4px rgba(31,29,26,.06),0 24px 40px -24px rgba(31,29,26,.35)}
#vv-wa-avisos.pilula:not(.aberto) .vv-aviso-curto-ic{background:var(--d3-trilho);color:var(--d3-tinta)}
#vv-wa-avisos.pilula:not(.aberto) .vv-aviso-curto-txt b{font-size:var(--d3-fs-apoio);color:var(--d3-tinta)}

/* ===== padrao-v2/entrada.css ===== */
/* PADRÃO V2 · LOGIN E ENTRADA, VYBES E CRIAR (quadros EntradaDepois e VybesCriarDepois do moodboard, 13/11/2026).
   Login: um campo por vez, cartão branco de 380 com raio 28 sobre o fundo #F1EEE8 a #E6E0D6. Entrada: a fala do VYBES,
   "Continuar de onde parou" (só quando o navegador guardou algo) e três atalhos. Hoje sem fila: a conversa do VYBES com
   as abas dos agentes e o Criar com os quatro tipos, que abre no lugar. */

/* ---------- Login ---------- */
#login-gate.v2lg-portao{background:linear-gradient(180deg,#F1EEE8 0%,#E6E0D6 100%);color:#1F1D1A;font-family:var(--vv-texto,Inter),system-ui,sans-serif}
#login-gate .v2lg{position:relative;z-index:5;width:380px;max-width:100%;box-sizing:border-box;display:flex;flex-direction:column;gap:18px;margin:auto;padding:28px;border-radius:28px;background:#FFFFFF;color:#1F1D1A;box-shadow:0 1px 2px rgba(31,29,26,.05),0 12px 24px -18px rgba(31,29,26,.22),0 30px 60px -40px rgba(31,29,26,.35);animation:v2lg-entra .45s var(--vv-suave,cubic-bezier(.22,1,.36,1)) both}
@keyframes v2lg-entra{from{transform:translateY(12px) scale(.98)}to{transform:none}}
#login-gate .v2lg p{margin:0}
#login-gate .v2lg-marca{display:flex;align-items:center;gap:10px}
#login-gate .v2lg-logo{flex:none;display:grid;place-items:center;width:32px;height:32px;border-radius:10px;background:var(--d3-acao,#C2490C);color:#FFFFFF;font:700 var(--d3-fs-destaque) var(--vv-texto,Inter),sans-serif}
#login-gate .v2lg-marca > b{flex:1;font:600 var(--d3-fs-destaque) var(--vv-texto,Inter),sans-serif;color:#1F1D1A}
#login-gate .v2lg-pts{display:flex;gap:6px;align-items:center}
#login-gate .v2lg-pts > i{width:6px;height:6px;border-radius:50%;background:#D9D3C8;transition:width .25s,background-color .25s}
#login-gate .v2lg:is([data-passo="quem"],[data-passo="email"]) .v2lg-pts > i.um,#login-gate .v2lg[data-passo="senha"] .v2lg-pts > i.dois{width:18px;border-radius:3px;background:#1F1D1A}
#login-gate .v2lg-sub{font:400 var(--d3-fs-texto)/1.35 var(--vv-texto,Inter),sans-serif;color:#6B665E}
#login-gate .v2lg-ola{flex:1;min-width:0;display:flex;flex-direction:column}
#login-gate .v2lg-ola > b{font:700 24px/1.15 var(--vv-titulo,"Inter Tight"),Inter,sans-serif;letter-spacing:-.01em;color:#1F1D1A;overflow-wrap:anywhere}
#login-gate .v2lg-av{flex:none;display:inline-grid;place-items:center;overflow:hidden;width:28px;height:28px;border-radius:50%;background:#EFEBE4;color:#4A463F;font:700 var(--d3-fs-mini) var(--vv-texto,Inter),sans-serif;box-shadow:0 0 0 2px #FFFFFF}
#login-gate .v2lg-av > img{width:100%;height:100%;object-fit:cover}
#login-gate .v2lg-av.g{width:56px;height:56px;font-size:var(--d3-fs-titulo);box-shadow:none}
/* passo 1: quem é você */
#login-gate .v2lg-quem{display:flex;flex-direction:column;gap:14px}
#login-gate .v2lg-rostos{display:grid;grid-template-columns:repeat(auto-fill,minmax(96px,1fr));gap:8px;max-height:min(46vh,330px);overflow-y:auto;padding:2px}
#login-gate .v2lg-rosto{appearance:none;display:flex;flex-direction:column;align-items:center;gap:8px;min-width:0;padding:12px 6px;border:0;border-radius:18px;background:#F9F8F5;color:#1F1D1A;font:600 var(--d3-fs-texto)/1.25 var(--vv-texto,Inter),sans-serif;cursor:pointer;transition:transform .14s var(--vv-mola,cubic-bezier(.34,1.56,.64,1)),background-color .2s,box-shadow .2s}
#login-gate .v2lg-rosto > .v2lg-av{width:56px;height:56px;font-size:var(--d3-fs-titulo);box-shadow:none}
#login-gate .v2lg-rosto > b{max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:600}
#login-gate .v2lg-rosto:hover{background:#FFFFFF;box-shadow:inset 0 0 0 1.5px #1F1D1A}
#login-gate .v2lg-rosto:active{transform:scale(.96)}
#login-gate .v2lg-rosto-vazio{height:104px;border-radius:18px;background:#F3F1EC;animation:v2lg-pisca 1.2s ease-in-out infinite alternate}
@keyframes v2lg-pisca{to{opacity:.45}}
/* passo 2: a senha, com quem é */
#login-gate .v2lg-eu{display:none;align-items:center;gap:14px}
#login-gate .v2lg-campo{display:none;flex-direction:column;gap:8px}
#login-gate .v2lg-campo > span{font:600 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;color:#1F1D1A}
#login-gate .v2lg-campo > input{width:100%;height:46px;box-sizing:border-box;margin:0;padding:0 20px;border:0;border-radius:999px;background:#F9F8F5;box-shadow:inset 0 0 0 1.5px #1F1D1A;color:#1F1D1A;font:400 var(--d3-fs-destaque) var(--vv-texto,Inter),sans-serif;outline:none}
#login-gate .v2lg-campo > input::placeholder{color:#8A847A}
#login-gate .v2lg-campo > input:focus-visible{box-shadow:inset 0 0 0 2px #1F1D1A;outline:0}
#login-gate .v2lg-so-email{display:none}
#login-gate .v2lg-entrar{appearance:none;display:none;align-items:center;justify-content:center;height:46px;padding:0 16px;border:0;border-radius:999px;background:#1F1D1A;color:#FFFFFF;font:600 var(--d3-fs-destaque) var(--vv-texto,Inter),sans-serif;cursor:pointer;transition:transform .14s var(--vv-mola,cubic-bezier(.34,1.56,.64,1)),background-color .2s}
#login-gate .v2lg-entrar:hover{background:#000000}
#login-gate .v2lg-entrar:active{transform:scale(.96)}
#login-gate .v2lg-entrar:disabled{opacity:.7;cursor:progress}
#login-gate .v2lg[data-passo="senha"] .v2lg-eu{display:flex}
#login-gate .v2lg[data-passo="senha"] .v2lg-campo-senha,#login-gate .v2lg[data-passo="email"] .v2lg-campo-email{display:flex}
#login-gate .v2lg[data-passo="email"] .v2lg-so-email{display:flex}
#login-gate .v2lg:is([data-passo="senha"],[data-passo="email"]) .v2lg-entrar{display:flex}
#login-gate .v2lg:not([data-passo="quem"]) .v2lg-quem{display:none}
#login-gate .v2lg-btn{appearance:none;flex:none;display:inline-flex;align-items:center;justify-content:center;height:38px;padding:0 16px;border:0;border-radius:999px;background:#FFFFFF;box-shadow:inset 0 0 0 1px #E6E0D6;color:#1F1D1A;font:600 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;cursor:pointer;transition:transform .14s var(--vv-mola,cubic-bezier(.34,1.56,.64,1))}
#login-gate .v2lg-btn.s{height:30px;padding:0 12px;font-size:var(--d3-fs-texto)}
#login-gate .v2lg-btn:hover{box-shadow:inset 0 0 0 1px #1F1D1A}
#login-gate .v2lg-btn:active{transform:scale(.96)}
#login-gate .v2lg-erro{margin:-6px 0 0;padding:10px 14px;border-radius:14px;background:#FDECEE;color:#B42318;font:600 var(--d3-fs-texto)/1.4 var(--vv-texto,Inter),sans-serif}
#login-gate .v2lg-erro[hidden]{display:none}
/* o pé: Outra pessoa, os outros rostos e Não estou na lista */
#login-gate .v2lg-pe{display:flex;flex-wrap:wrap;align-items:center;gap:10px;padding-top:14px;border-top:1px solid #F1EDE6}
#login-gate .v2lg-pe-rot{flex:1}
#login-gate .v2lg:not([data-passo="senha"]) :is(.v2lg-pe-rot,#login-outros){display:none}
#login-gate .v2lg:not([data-passo="senha"]) .v2lg-pe{justify-content:flex-end}
#login-gate .v2lg-avs{display:inline-flex;padding-left:8px}
#login-gate .v2lg-avs[hidden]{display:none}
#login-gate .v2lg-mini{appearance:none;margin:0 0 0 -8px;padding:0;border:0;border-radius:50%;background:none;cursor:pointer;transition:transform .14s var(--vv-mola,cubic-bezier(.34,1.56,.64,1))}
#login-gate .v2lg-mini:hover{transform:translateY(-2px);position:relative;z-index:1}
#login-gate .v2lg-chip{appearance:none;display:inline-flex;align-items:center;gap:6px;height:30px;padding:0 12px;border:0;border-radius:999px;background:#FFFFFF;box-shadow:inset 0 0 0 1px #E6E0D6;color:#1F1D1A;font:500 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;cursor:pointer;white-space:nowrap}
#login-gate .v2lg-chip:hover{box-shadow:inset 0 0 0 1px #1F1D1A}
#login-gate .v2lg[data-passo="email"] .v2lg-outro,#login-gate .v2lg:not([data-passo="email"]) .v2lg-voltar,#login-gate .v2lg:not(.tem-rostos) .v2lg-voltar{display:none}
#login-gate .v2lg-ajuda{display:none;font:400 var(--d3-fs-texto)/1.4 var(--vv-texto,Inter),sans-serif;color:#6B665E}
#login-gate .v2lg[data-passo="email"] .v2lg-ajuda{display:block}
#login-gate .v2lg button:focus-visible{outline:2px solid #C2490C;outline-offset:2px}
#login-gate .v2lg input:focus-visible{outline:none}
@media (max-width:420px){
  #login-gate.v2lg-portao{padding:16px}
  #login-gate .v2lg{padding:22px;gap:16px;border-radius:24px}
  #login-gate .v2lg-rostos{grid-template-columns:repeat(3,minmax(0,1fr))}
}
@media (prefers-reduced-motion:reduce){#login-gate .v2lg,#login-gate .v2lg-rosto-vazio{animation:none}#login-gate :is(.v2lg-rosto,.v2lg-entrar,.v2lg-btn,.v2lg-mini){transition:none}}

/* ---------- Entrada logo depois do login ---------- */
#vv-entrada.v2en-camada{position:fixed;inset:0;z-index:2147470000;display:flex;overflow-y:auto;padding:28px 16px;box-sizing:border-box;background:linear-gradient(180deg,#F1EEE8 0%,#E6E0D6 100%);color:#1F1D1A;font-family:var(--vv-texto,Inter),system-ui,sans-serif}
#vv-entrada[hidden]{display:none}
/* Direção 3 (quadro D3-Entrada): a entrada é uma janela branca de raio 28; a fala do VYBES vira o bloco de ação laranja,
   os cartões de dentro são #F9F8F5 e o Continuar é preto. */
#vv-entrada .v2en{width:min(760px,100%);box-sizing:border-box;margin:auto;padding:30px;border-radius:var(--d3-r-janela,28px);background:#FFFFFF;box-shadow:0 2px 6px rgba(31,29,26,.08),0 40px 80px -30px rgba(31,29,26,.45);display:flex;flex-direction:column;gap:14px;animation:v2lg-entra .45s var(--vv-suave,cubic-bezier(.22,1,.36,1)) both}
#vv-entrada .v2en :is(p,h1,h2){margin:0}
#vv-entrada .v2en-topo{display:flex;align-items:center;gap:12px}
#vv-entrada .v2en-ola{flex:1;min-width:0;display:flex;flex-direction:column}
#vv-entrada .v2en-ola > small,#vv-entrada .v2en-online{font:400 var(--d3-fs-texto)/1.35 var(--vv-texto,Inter),sans-serif;color:#6B665E}
#vv-entrada .v2en-ola > h1{font:700 var(--d3-fs-numero)/1.1 var(--vv-titulo,"Inter Tight"),Inter,sans-serif;letter-spacing:-.01em;color:#1F1D1A}
#vv-entrada .v2en-avs{display:inline-flex;padding-left:8px}
#vv-entrada .v2en-av{display:inline-grid;place-items:center;width:28px;height:28px;margin-left:-8px;border-radius:50%;background:#EFEBE4;color:#4A463F;font:700 var(--d3-fs-mini) var(--vv-texto,Inter),sans-serif;box-shadow:0 0 0 2px #FFFFFF;animation:v2-pop .45s var(--vv-mola,cubic-bezier(.34,1.56,.64,1)) both}
#vv-entrada .v2en-card{padding:16px 18px;border-radius:20px;background:#F9F8F5;box-shadow:none}
#vv-entrada .v2en-card.v2en-fala{padding:14px 16px 14px 18px;background:var(--d3-acao,#C2490C);color:#FFFFFF}
#vv-entrada .v2en-fala{display:flex;align-items:center;gap:14px}
#vv-entrada .v2en-fala > p{flex:1;min-width:0;font:600 var(--d3-fs-destaque)/1.35 var(--vv-titulo,"Inter Tight"),Inter,sans-serif;color:#FFFFFF}
#vv-entrada .v2en-fala b{font-weight:700}
#vv-entrada .v2en-quem{display:block;margin-bottom:2px;font:600 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;color:rgba(255,255,255,.78)}
#vv-entrada .v2en-fala > .v2en-ag{width:32px;height:32px;background:#FFFFFF;color:var(--d3-agente,#6E56CF);font-size:var(--d3-fs-texto);isolation:isolate}
/* o pulso branco no compositor (como o do bloco de ação em 0-d3-base.css): avatar de 32, então 1.5 = (32 + 16) / 32 */
#vv-entrada .v2en-fala > .v2en-ag::after{display:block;content:"";inset:0;z-index:-1;border:0;border-radius:50%;background:inherit;pointer-events:none;--d3-anel-o:.7;--d3-anel-k:1.5;animation:d3PulsaAnel 2.4s ease-in-out infinite}
@media (prefers-reduced-motion:reduce){#vv-entrada .v2en-fala > .v2en-ag::after{display:none}}
#vv-entrada .v2en-ag,#vv-hoje .v2vb-ag{flex:none;position:relative;display:grid;place-items:center;width:40px;height:40px;border-radius:50%;background:#6E56CF;color:#FFFFFF;font:700 var(--d3-fs-destaque) var(--vv-texto,Inter),sans-serif}
#vv-entrada .v2en-ag::after,#vv-hoje .v2vb-ag::after{content:"";position:absolute;inset:-5px;border-radius:50%;border:2px solid #6E56CF;opacity:0;animation:v2en-pulso 3.6s ease-out infinite}
@keyframes v2en-pulso{0%{opacity:.5;transform:scale(.85)}70%,100%{opacity:0;transform:scale(1.25)}}
#vv-entrada .v2en-cont{display:flex;flex-direction:column;gap:12px}
#vv-entrada .v2en-cont-topo{display:flex;align-items:baseline;gap:8px}
#vv-entrada .v2en-cont-topo > h2{flex:1;font:600 var(--d3-fs-destaque)/1.2 var(--vv-titulo,"Inter Tight"),Inter,sans-serif;color:#1F1D1A}
#vv-entrada .v2en-cont-topo > small{font:400 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;color:#6B665E}
#vv-entrada .v2en-cont > p{display:flex;flex-direction:column;gap:2px;font:400 var(--d3-fs-destaque)/1.35 var(--vv-texto,Inter),sans-serif}
#vv-entrada .v2en-cont > p > b{font-weight:700;overflow-wrap:anywhere}
#vv-entrada .v2en-cont > p > small{font:400 var(--d3-fs-texto)/1.35 var(--vv-texto,Inter),sans-serif;color:#6B665E}
#vv-entrada .v2en-cont .cliente-carteira{display:inline-flex;align-items:center;gap:6px;padding:0;border:0;background:none;color:#1F1D1A;font:inherit;font-weight:600}
#vv-entrada .v2en-cont .cliente-carteira::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--carteira-texto,#C2490C)}
#vv-entrada .v2en-btn{appearance:none;align-self:flex-start;display:inline-flex;align-items:center;height:44px;padding:0 22px;border:0;border-radius:999px;background:#1F1D1A;color:#FFFFFF;font:600 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;box-shadow:0 8px 16px -10px #C2490C;cursor:pointer;transition:transform .14s var(--vv-mola,cubic-bezier(.34,1.56,.64,1)),background-color .2s}
#vv-entrada .v2en-btn:hover{background:#000000}
#vv-entrada .v2en-btn:active,#vv-entrada .v2en-at:active{transform:scale(.96)}
#vv-entrada .v2en-ats{display:flex;gap:10px}
#vv-entrada .v2en-at{appearance:none;flex:1;min-width:0;display:flex;flex-direction:column;align-items:flex-start;gap:8px;padding:14px;border:0;border-radius:20px;background:#F9F8F5;color:#1F1D1A;font:600 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;text-align:left;cursor:pointer;box-shadow:0 1px 2px rgba(31,29,26,.05),0 12px 24px -18px rgba(31,29,26,.22);transition:transform .14s var(--vv-mola,cubic-bezier(.34,1.56,.64,1)),box-shadow .2s}
#vv-entrada .v2en-at:hover{box-shadow:inset 0 0 0 1.5px #1F1D1A,0 12px 24px -18px rgba(31,29,26,.22)}
#vv-entrada .v2en-at > svg{width:18px;height:18px}
#vv-entrada .v2en-at > small{font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter),sans-serif;color:#6B665E}
#vv-entrada :is(.v2en-at,.v2en-btn):focus-visible{outline:2px solid #1F1D1A;outline-offset:2px}
@media (max-width:520px){
  #vv-entrada .v2en-ola > h1{font-size:26px}
  #vv-entrada .v2en-ats{flex-direction:column}
  #vv-entrada .v2en-at{flex-direction:row;align-items:center;gap:10px}
  #vv-entrada .v2en-at > small{margin-left:auto;text-align:right}
}

/* ---------- Criar (no Hoje sem fila e na janela do botão Criar) ---------- */
#vv-criar.v2cr-camada{position:fixed;inset:0;z-index:2147470000;display:flex;align-items:flex-start;justify-content:center;overflow-y:auto;padding:min(10vh,90px) 16px 24px;box-sizing:border-box;background:rgba(31,29,26,.28)}
#vv-criar[hidden]{display:none}
#vv-criar .v2cr-janela{width:min(620px,100%);padding:22px;border-radius:28px;background:#F9F8F5;box-shadow:0 24px 48px -30px rgba(31,29,26,.5);animation:v2lg-entra .35s var(--vv-suave,cubic-bezier(.22,1,.36,1)) both}
:is(#vv-hoje,#vv-criar) .v2cr{min-width:0;display:flex;flex-direction:column;gap:12px;color:#1F1D1A;font-family:var(--vv-texto,Inter),system-ui,sans-serif}
:is(#vv-hoje,#vv-criar) .v2cr :is(p,h3){margin:0}
:is(#vv-hoje,#vv-criar) .v2cr-topo{display:flex;align-items:baseline;gap:8px;min-height:22px}
:is(#vv-hoje,#vv-criar) .v2cr-topo > h3{flex:1;font:600 var(--d3-fs-destaque)/1.2 var(--vv-titulo,"Inter Tight"),Inter,sans-serif;color:#1F1D1A}
:is(#vv-hoje,#vv-criar) .v2cr-topo > small,:is(#vv-hoje,#vv-criar) .v2cr-pe{font:400 var(--d3-fs-texto)/1.4 var(--vv-texto,Inter),sans-serif;color:#6B665E}
:is(#vv-hoje,#vv-criar) .v2cr-x{appearance:none;align-self:center;display:grid;place-items:center;width:30px;height:30px;padding:0;border:0;border-radius:50%;background:#FFFFFF;box-shadow:inset 0 0 0 1px #E6E0D6;color:#1F1D1A;cursor:pointer}
:is(#vv-hoje,#vv-criar) .v2cr-x > svg{width:12px;height:12px;stroke-width:3}
:is(#vv-hoje,#vv-criar) .v2cr-dem{padding:6px 18px 16px;border-radius:20px;background:#FFFFFF;box-shadow:0 1px 2px rgba(31,29,26,.05),0 12px 24px -18px rgba(31,29,26,.22)}
:is(#vv-hoje,#vv-criar) .v2cr-dem[aria-expanded="false"]{padding-bottom:6px}
:is(#vv-hoje,#vv-criar) .v2cr-lin{appearance:none;width:100%;display:flex;align-items:center;gap:12px;margin:0;padding:12px 0;border:0;background:none;color:inherit;font:400 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;text-align:left;cursor:pointer}
:is(#vv-hoje,#vv-criar) .v2cr-lin > svg{flex:none;width:22px;height:22px;color:#C2490C}
:is(#vv-hoje,#vv-criar) .v2cr-nome{flex:1;min-width:0;display:flex;flex-direction:column}
:is(#vv-hoje,#vv-criar) .v2cr-nome > b{font:600 var(--d3-fs-destaque)/1.25 var(--vv-titulo,"Inter Tight"),Inter,sans-serif}
:is(#vv-hoje,#vv-criar) .v2cr-nome > small,:is(#vv-hoje,#vv-criar) .v2cr-etapa{font:400 var(--d3-fs-texto)/1.35 var(--vv-texto,Inter),sans-serif;color:#6B665E}
