/* ---------- Notas: a janela do topo ---------- */
#v2-notas.v2nt{position:fixed;z-index:880;top:76px;right:14px;display:flex;flex-direction:column;box-sizing:border-box;width:340px;max-width:calc(100vw - 16px);max-height:min(640px,calc(100dvh - 96px));margin:0;padding:0;border:0;border-radius:24px;overflow:hidden;background:#FFFFFF;color:#1F1D1A;box-shadow:0 2px 4px rgba(31,29,26,.06),0 24px 40px -24px rgba(31,29,26,.35);font:400 var(--d3-fs-texto)/1.35 var(--vv-texto,Inter),system-ui,sans-serif;color-scheme:light;animation:v2nt-surge .18s cubic-bezier(.2,.8,.2,1) both}
