#vv-hoje .vcr-fila .vcr-pill.v{background:#EEEAFB;color:#4B36A8}
#vv-hoje .vcr-fila .vcr-pill.r{background:#FDECEE;color:#B42318}
#vv-hoje .vcr-fila .vcr-sug-meio .cliente-carteira{display:inline-flex;align-items:center;gap:6px;padding:0;border:0;border-radius:0;background:none;font:inherit;font-weight:600}
#vv-hoje .vcr-fila .vcr-sug-meio .cliente-carteira::before{content:"";flex:none;width:8px;height:8px;border-radius:50%;background:currentColor}
#vv-hoje .vcr-fila .vcr-sug-acoes{display:flex;flex-wrap:wrap;align-items:center;gap:6px;width:auto}
#vv-hoje .vcr-fila .vcr-sug-acoes > button{appearance:none;display:inline-flex;align-items:center;justify-content:center;height:30px;min-height:30px;padding:0 12px;border:0;border-radius:999px;background:#FFFFFF;box-shadow:inset 0 0 0 1px #E6E0D6;color:#1F1D1A;font:600 var(--d3-fs-texto) var(--vv-texto);cursor:pointer}
#vv-hoje .vcr-fila .vcr-sug[data-vcr-tipo="delegar"] .vcr-sug-acoes > button.vc-acao,
#vv-hoje .vcr-fila .vcr-sug-acoes > button[data-vcr-confirmar]{background:#1F1D1A;color:#FFFFFF;box-shadow:none}
#vv-hoje .vcr-fila .vcr-sug-acoes > button:disabled{opacity:.45;cursor:default}
#vv-hoje .vcr-fila .vcr-sug-acoes > button:focus-visible{outline:2px solid var(--ds-acao,#C2490C);outline-offset:2px}
#vv-hoje .vcr-fila > .vcr-nota{margin:0;padding-top:8px;font:400 var(--d3-fs-texto)/1.4 var(--vv-texto);color:#6B665E}
#vv-hoje .vcr-fila > .vv-vazio{margin:8px 0 0;padding:0;border:0;background:none;font:400 var(--d3-fs-texto)/1.45 var(--vv-texto);color:#6B665E}

/* ===== padrao-v2/projetos.css ===== */
/* ======================================================================================
   PADRÃO V2 · PROJETOS (moodboard, quadro DEPOIS de Projetos, Produção › Projetos pontuais; 12/11/2026).
   Usa as peças v2p-* de padrao-v2/pessoas.css (janela, cartão, fala, ficha, pílula, botão, avatar, caixinha) e os
   movimentos do bloco PADRÃO V2 · BASE de vybe-mundo.css (v2-barra, v2-num, v2-risca, v2-estado, v2-pop, v2-chegou).
   Aqui fica só o que é deste quadro: a grade 350px + o resto, o cartão do projeto e a página do projeto aberto.
   ====================================================================================== */

/* ---------- a grade: cartões à esquerda, o projeto aberto à direita ---------- */
#vv-pessoas .v2pj-grade{flex:1 0 auto;display:grid;grid-template-columns:350px minmax(0,1fr);gap:14px;align-items:stretch;min-width:0}
#vv-pessoas .v2pj-grade.so-lista{grid-template-columns:minmax(0,1fr)}
#vv-pessoas .v2pj-lista{display:flex;flex-direction:column;gap:14px;min-width:0}
#vv-pessoas .v2pj-grade.so-lista > .v2pj-lista{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));align-content:start}
#vv-pessoas .v2pj-grade.so-lista .v2pj-resto{grid-column:1 / -1}
#vv-pessoas .v2p .v2pj-resto{padding:0 2px}

/* o cliente com a bolinha da cor dele */
#vv-pessoas .v2pj-cli{display:inline-flex;align-items:center;gap:6px;min-width:0;font:600 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;color:#1F1D1A}
#vv-pessoas .v2pj-cli::before{content:"";flex:none;width:8px;height:8px;border-radius:50%;background:var(--c,#6B665E)}

/* ---------- o cartão do projeto ---------- */
#vv-pessoas .v2p-card.v2pj-card{appearance:none;display:flex;flex-direction:column;gap:10px;width:100%;box-sizing:border-box;padding:16px;color:#1F1D1A;font:400 var(--d3-fs-texto)/1.4 var(--vv-texto,Inter),sans-serif;text-align:left;cursor:pointer;transition:box-shadow .2s,transform .14s var(--vv-mola,cubic-bezier(.34,1.56,.64,1))}
#vv-pessoas .v2p-card.v2pj-card:hover{box-shadow:0 0 0 1px #E6E0D6,0 12px 24px -18px rgba(31,29,26,.22)}
#vv-pessoas .v2p-card.v2pj-card:active{transform:scale(.985)}
#vv-pessoas .v2p-card.v2pj-card[aria-pressed="true"]{box-shadow:0 0 0 2px var(--c,#3B5BA9),0 12px 24px -18px rgba(31,29,26,.22)}
#vv-pessoas .v2p-card.v2pj-card:focus-visible{outline:2px solid #C2490C;outline-offset:2px}
#vv-pessoas .v2pj-topo{display:flex;align-items:center;gap:8px;min-width:0}
#vv-pessoas .v2pj-topo > .v2pj-cli{flex:1;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
#vv-pessoas .v2p .v2pj-tit{display:block;font:600 var(--d3-fs-destaque)/1.25 var(--vv-titulo,"Inter Tight"),Inter,sans-serif;color:#1F1D1A;overflow-wrap:anywhere}
#vv-pessoas .v2pj-prog{display:flex;align-items:center;gap:10px;min-width:0}
#vv-pessoas .v2pj-prog > .v2-barra{flex:1;display:block;min-width:40px;background:#EAE6DE;border-radius:3px}
#vv-pessoas .v2pj-prog > .v2p-sub{flex:none;white-space:nowrap}
#vv-pessoas .v2pj-pe{display:flex;align-items:center;gap:8px;min-width:0;min-height:28px}
#vv-pessoas .v2p .v2pj-prox{flex:1;min-width:0;text-align:right;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
#vv-pessoas .v2p .v2pj-prox.ruim,#vv-pessoas .v2p .v2pj-quando.ruim,#vv-pessoas .v2p .v2pj-ruim{color:#B42318;font-weight:600}

/* ---------- a página do projeto aberto ---------- */
#vv-pessoas .v2p-card.v2pj-pag{display:flex;flex-direction:column;min-width:0;padding:22px}
#vv-pessoas .v2pj-vira{transform-origin:0 12%;animation:v2pj-vira .45s var(--vv-suave,cubic-bezier(.22,1,.36,1)) both}
@keyframes v2pj-vira{from{opacity:0;transform:scale(.6,.4)}to{opacity:1;transform:none}}
#vv-pessoas .v2pj-pag-topo{display:flex;flex-wrap:wrap;align-items:center;gap:8px;min-width:0}
#vv-pessoas .v2pj-pag-topo > .v2pj-cli{font-size:var(--d3-fs-texto)}
#vv-pessoas .v2pj-esp{flex:1}
#vv-pessoas .v2pj-pag-topo svg{display:block}
#vv-pessoas .v2pj-mais{position:relative;display:inline-flex}
#vv-pessoas .v2pj-menu{position:absolute;top:36px;right:0;z-index:5;display:flex;flex-direction:column;min-width:200px;padding:6px;border-radius:14px;background:#FFFFFF;box-shadow:0 0 0 1px #E6E0D6,0 18px 32px -18px rgba(31,29,26,.4)}
#vv-pessoas .v2pj-menu > button{appearance:none;margin:0;padding:9px 12px;border:0;border-radius:10px;background:none;color:#1F1D1A;font:500 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;text-align:left;cursor:pointer}
#vv-pessoas .v2pj-menu > button:hover,#vv-pessoas .v2pj-menu > button:focus-visible{background:#F3F1EC;outline:none}
#vv-pessoas .v2p .v2pj-pag-tit{margin:12px 0 0;font:700 22px/1.2 var(--vv-titulo,"Inter Tight"),Inter,sans-serif;letter-spacing:-.01em;color:#1F1D1A;overflow-wrap:anywhere}
#vv-pessoas .v2p .v2pj-quem{margin-top:4px}
#vv-pessoas .v2p .v2pj-desc{margin-top:6px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
#vv-pessoas .v2pj-prog-g{gap:12px;margin-top:14px}
#vv-pessoas .v2pj-prog-g > .v2-barra{height:8px;border-radius:4px}
#vv-pessoas .v2pj-prog-g > b{flex:none;font-size:var(--d3-fs-texto)}
#vv-pessoas .v2pj-etapas{margin-top:10px}
#vv-pessoas .v2pj-etapas > .v2p-lin:first-child{border-top:0}
#vv-pessoas .v2pj-etapa > p{display:flex;flex-wrap:wrap;align-items:center;gap:4px 6px}
#vv-pessoas .v2pj-etapa > p > b{font-weight:700}
#vv-pessoas .v2pj-etapa .v2-risca.feita{color:#6B665E}
#vv-pessoas .v2pj-quando{flex:none;white-space:nowrap}
#vv-pessoas .v2pj-rodape{margin-top:auto;display:flex;flex-wrap:wrap;align-items:center;gap:10px;padding-top:12px;border-top:1px solid #F1EDE6}
#vv-pessoas .v2pj-etapas + .v2pj-rodape{margin-top:auto}
#vv-pessoas .v2p-card.v2pj-pag > .v2pj-etapas{margin-bottom:12px}
#vv-pessoas .v2pj-rodape > p{flex:1;min-width:120px}
#vv-pessoas .v2p .v2pj-rodape .v2p-btn.v2-estado{position:relative}

/* ---------- o formulário no lugar da página ---------- */
#vv-pessoas .v2p .vp-cartao.v2pj-form{min-width:0;margin:0;padding:22px}
#vv-pessoas .v2p .v2pj-form > .vp-titulo{margin:0 0 6px;font:700 22px/1.2 var(--vv-titulo,"Inter Tight"),Inter,sans-serif;letter-spacing:-.01em;color:#1F1D1A}
#vv-pessoas .v2pj-form .vp-etapa-form{border:0;border-radius:14px;background:#F6F3EE}
#vv-pessoas .v2pj-form .vp-etapa-form label{min-width:0}
#vv-pessoas .v2pj-form .vp-etapa-form label > :is(input,select){width:100%;min-width:0;box-sizing:border-box}
#vv-pessoas .v2pj-form .vp-etapa-form .vp-link.perigo{height:30px;margin:0;padding:0 10px;border:0;border-radius:999px;background:none;box-shadow:none;color:#B42318}
#vv-pessoas .v2pj-form .vp-etapa-form .vp-link.perigo:hover{background:#FDECEE}
@media (min-width:720px){#vv-pessoas .v2pj-form .vp-etapa-form{grid-template-columns:minmax(0,1.6fr) minmax(0,1.3fr) minmax(0,1.15fr) minmax(0,1.15fr) minmax(0,.9fr) auto}}

/* ---------- Linha do tempo ---------- */
#vv-pessoas .v2p-card.v2pj-tempo{display:flex;flex-direction:column;gap:12px;min-width:0}
#vv-pessoas .v2pj-cab{flex-wrap:wrap;align-items:center;margin:0}
#vv-pessoas .v2pj-cab > h3{flex:0 1 auto}
#vv-pessoas .v2pj-cab > small{flex:1;text-align:left}
#vv-pessoas .v2pj-ctl{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-left:auto}
#vv-pessoas .v2p .v2pj-ctl .v2pj-sel{height:30px;min-height:0;max-width:220px;box-sizing:border-box;margin:0;padding:0 28px 0 12px;border:0;border-radius:999px;background-color:#FFFFFF;box-shadow:inset 0 0 0 1px #E6E0D6;color:#1F1D1A;font:500 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif}
#vv-pessoas .v2pj-seg{display:inline-flex;padding:4px;border-radius:999px;background:#EAE6DE}
#vv-pessoas .v2pj-seg > button{appearance:none;height:26px;margin:0;padding:0 12px;border:0;border-radius:999px;background:none;color:#6B665E;font:600 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;cursor:pointer}
#vv-pessoas .v2pj-seg > button[aria-pressed="true"]{background:#FFFFFF;color:#1F1D1A;box-shadow:0 1px 3px rgba(31,29,26,.18)}
#vv-pessoas .v2pj-seg > button:focus-visible{outline:2px solid #C2490C;outline-offset:2px}
#vv-pessoas .v2pj-ctl .vp-nav{display:flex;gap:6px}
#vv-pessoas .v2p .v2pj-ctl .vp-nav .vp-sec{height:30px;min-height:30px;padding:0 12px;font-size:var(--d3-fs-texto)}
#vv-pessoas .v2pj-tempo .vp-gantt{padding:0;border:0;border-radius:0;background:transparent}
#vv-pessoas .v2pj-tempo .vp-gantt-proj{border-bottom-color:#F1EDE6}
#vv-pessoas .v2pj-tempo .vp-gantt-trilho{background:#F3F1EC}
#vv-pessoas .v2pj-tempo .vp-gantt-barra{background:#3B5BA9}
#vv-pessoas .v2pj-tempo .vp-gantt-barra.proj{background:#EAE6DE}
#vv-pessoas .v2pj-tempo .vp-gantt-barra.feita{background:#11613A}
#vv-pessoas .v2pj-tempo .vp-gantt-barra.atrasada{background:#B42318}
#vv-pessoas .v2pj-tempo .vp-dia{border:0;border-radius:14px;background:#F6F3EE}
#vv-pessoas .v2pj-tempo .vp-dia.hoje{background:#FFF1E6;box-shadow:inset 0 0 0 1.5px #1F1D1A}
#vv-pessoas .v2pj-tempo .vp-etapa-dia{border-radius:10px;border-left-color:#3B5BA9}
#vv-pessoas .v2pj-tempo .vp-etapa-dia.feita{border-left-color:#11613A}
#vv-pessoas .v2pj-tempo .vp-etapa-dia.atrasada{border-left-color:#B42318}

@media (prefers-reduced-motion:reduce){
  #vv-pessoas .v2pj-vira{animation:none}
  #vv-pessoas .v2p-card.v2pj-card{transition:none}
}

/* ---------- larguras menores: uma coluna, nada vaza ---------- */
@container v2p (max-width:900px){
  #vv-pessoas .v2pj-grade{grid-template-columns:minmax(0,1fr)}
}
@container v2p (max-width:620px){
  #vv-pessoas .v2p-card.v2pj-pag{padding:16px}
  #vv-pessoas .v2p .v2pj-pag-tit{font-size:20px}
  #vv-pessoas .v2pj-grade.so-lista > .v2pj-lista{grid-template-columns:minmax(0,1fr)}
  #vv-pessoas .v2p-lin.v2pj-etapa{flex-wrap:nowrap}
  #vv-pessoas .v2p-lin.v2pj-etapa > p{flex:1 1 auto}
  #vv-pessoas .v2pj-ctl{margin-left:0}
}

/* ===== padrao-v2/status.css ===== */
/* PADRÃO V2 · TROCA DE STATUS (quadro Status do moodboard): menu curto com próximo, seguinte e volta; "Todos os N status".
   DIREÇÃO 3 (quadro D3-StatusMenu, 13/11/2026): menu branco de 260, cada status em pílula clara com a bolinha do catálogo
   (cheia só em Alteração, Atrasada e Finalizado), "Todos os N status" em tinta sublinhada e "Ordem e próximo passo" com o
   ícone. A lista inteira abre com "Todos · N" e o quadro; o atual leva o visto. */
body.mundo #status-editor.status-editor{min-width:260px;padding:8px}
body.mundo #status-editor .status-editor-head{padding:6px 10px 8px;font:600 var(--d3-fs-apoio)/1.2 var(--vv-texto,Inter,sans-serif);letter-spacing:0;text-transform:none}
body.mundo #status-editor .v2-st-cab{display:flex;align-items:baseline;justify-content:space-between;gap:12px}
body.mundo #status-editor .v2-st-cab small{font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif)}
#status-editor .v2-st-op{display:flex;align-items:center;gap:8px;min-height:40px;padding:0 10px}
#status-editor .v2-st-op.current{box-shadow:inset 0 0 0 999px #F3F1EC}
#status-editor .v2-st-op .status-editor-check{margin-left:auto;display:inline-grid;place-items:center}
#status-editor .v2-st-op .status-editor-check svg{stroke:#1F1D1A}
#status-editor .v2-st-dica{margin-left:auto;font:400 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;color:#6B665E}
#status-editor .v2-st-todos{min-height:40px;margin-top:4px;border-top:1px solid #F1EDE6;justify-content:flex-start;font-weight:600}
#status-editor .v2-st-op .v2-st-pilula{gap:5px;height:24px;padding:0 10px;background:#F3F1EC;color:#4A463F;font:600 var(--d3-fs-texto)/24px var(--vv-texto,Inter,system-ui,sans-serif)}
#status-editor .v2-st-op .v2-st-pilula::before{content:"";flex:none;width:7px;height:7px;border-radius:50%;background:var(--c,#8A847A)}
#status-editor .v2-st-op .v2-st-pilula:is(.a,.r,.g)::before{display:none}
#status-editor .v2-st-op .v2-st-pilula.n,#status-editor .v2-st-op .v2-st-pilula.b,#status-editor .v2-st-op .v2-st-pilula.v{background:#F3F1EC;color:#4A463F}
#status-editor .v2-st-todos .v2-st-todos-txt{color:#1F1D1A;font-weight:600;text-decoration:underline;text-underline-offset:3px}

/* Ordem e próximo passo (13/11/2026): o link no pé do menu de status e a janela que escolhe como o botão principal
   da peça usa a ordem (vybe-status.js, abrirFluxoDoStatus). Direção 3: três cartões de escolha com ícone, o escolhido
   preto; "Depois de cada status" em linhas com número, pílula, seta e destino; pé com "Mudar a ordem da lista". */
#status-editor .v2-st-fluxo{gap:10px;min-height:40px;justify-content:flex-start;font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif)}
#status-editor .v2-st-fluxo svg{flex:none}
#workflow-modal:has(.fx-fluxo){background:#FFFFFF}
#workflow-modal .workflow-kicker > span:first-child:has(~ .fx-selo){color:#6B665E;font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);letter-spacing:0;text-transform:none}
#workflow-modal .workflow-kicker > .fx-selo,#workflow-modal .fx-selo{display:inline-flex;align-items:center;height:22px;margin-left:auto;margin-right:10px;padding:0 9px;border-radius:999px;background:#F3F1EC;color:#4A463F;font:600 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);white-space:nowrap}
#workflow-modal .fx-fluxo{display:grid;gap:14px;margin:4px 0 16px}
#workflow-modal .fx-titulo{margin:0;font:700 26px/1.1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.02em;color:#1F1D1A}
#workflow-modal .fx-modos{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}
#workflow-modal .fx-modo{appearance:none;display:flex;align-items:center;gap:12px;width:100%;min-height:58px;margin:0;padding:10px 14px;border:0;border-radius:16px;background:#F3F1EC;color:#1F1D1A;text-align:left;cursor:pointer;
  font:inherit;transition:background-color .15s,color .15s,scale .14s cubic-bezier(.34,1.56,.64,1)}
#workflow-modal .fx-modo > span:last-child{display:grid;gap:1px;min-width:0}
#workflow-modal .fx-modo-ic{flex:none;display:grid;place-items:center;width:32px;height:32px;border-radius:10px;background:#FFFFFF;color:#1F1D1A}
#workflow-modal .fx-modo:hover{background:#EAE6DE}
#workflow-modal .fx-modo:active{scale:.98}
#workflow-modal .fx-modo b{font:600 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif)}
#workflow-modal .fx-modo small{font:400 var(--d3-fs-apoio)/1.35 var(--vv-texto,Inter,sans-serif);color:#6B665E}
#workflow-modal .fx-modo.on{background:#1F1D1A;color:#FFFFFF}
#workflow-modal .fx-modo.on small{color:#D9D4CB}
#workflow-modal .fx-modo:focus-visible{outline:2px solid #1F1D1A;outline-offset:2px}
#workflow-modal .fx-lista-topo{display:flex;align-items:baseline;justify-content:space-between;gap:12px;padding-bottom:4px;border-bottom:1px solid #F1EDE6}
#workflow-modal .fx-lista-topo b{font:600 var(--d3-fs-destaque) var(--vv-texto,Inter,sans-serif);color:#1F1D1A}
#workflow-modal .fx-legenda{display:inline-flex;align-items:center;gap:6px;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:#6B665E}
#workflow-modal .fx-legenda i{width:10px;height:10px;margin-left:6px;border-radius:50%;background:#F3F1EC}
#workflow-modal .fx-legenda i.fx-leg-on{background:#FFFFFF;box-shadow:inset 0 0 0 1.5px #1F1D1A}
#workflow-modal .fx-lista{display:grid;gap:0;margin:-8px 0 0;padding:0;max-height:min(420px,52vh);overflow:auto;list-style:none}
#workflow-modal .fx-linha{display:grid;grid-template-columns:28px minmax(0,1fr) auto minmax(0,230px);align-items:center;gap:8px;min-height:46px;padding:0;border-top:1px solid #F1EDE6;font:400 var(--d3-fs-texto)/1.35 var(--vv-texto,Inter,sans-serif);color:#1F1D1A;animation:d3LinhaNova .35s cubic-bezier(.22,1,.36,1) both}
#workflow-modal .fx-linha:first-child{border-top:0}
#workflow-modal .fx-n{font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:#6B665E;text-align:center}
#workflow-modal .fx-de{display:flex;align-items:center;min-width:0;overflow:hidden}
#workflow-modal .fx-pil{display:inline-flex;align-items:center;gap:5px;height:24px;max-width:100%;padding:0 10px;border-radius:999px;background:#F3F1EC;color:#4A463F;font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#workflow-modal .fx-pil::before{content:"";flex:none;width:7px;height:7px;border-radius:50%;background:var(--c,#8A847A)}
#workflow-modal .fx-pil:is(.a,.r,.g)::before{display:none}
#workflow-modal .fx-pil.a{background:#FFF4D6;color:#7A4A00}
#workflow-modal .fx-pil.r{background:#FDECEE;color:#B42318}
#workflow-modal .fx-pil.g{background:#E8F5EC;color:#11613A}
#workflow-modal .fx-seta{color:#B5AFA5}
#workflow-modal .fx-para{display:flex;align-items:center;height:36px;padding:0 14px;border-radius:999px;background:#F9F8F5;color:#4A463F;font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#workflow-modal .fx-linha select{min-width:0;width:100%;height:36px;padding:0 12px;border:0;border-radius:999px;background:#F3F1EC;color:#1F1D1A;font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif)}
#workflow-modal .fx-linha select.escolhido{background:#FFFFFF;box-shadow:inset 0 0 0 1.5px #1F1D1A;font-weight:600}
#workflow-modal .fx-ordem-btn{display:inline-flex;align-items:center;gap:8px;margin-right:auto}
@media (max-width:720px){
  #workflow-modal .fx-modos{grid-template-columns:minmax(0,1fr)}
  #workflow-modal .fx-linha{grid-template-columns:24px minmax(0,1fr) auto minmax(0,1fr)}
}
@media (max-width:520px){
  #workflow-modal .fx-linha{grid-template-columns:24px minmax(0,1fr);gap:4px;padding:6px 0}
  #workflow-modal .fx-seta{display:none}
  #workflow-modal :is(.fx-para,.fx-linha select){grid-column:2}
}
@media (prefers-reduced-motion:reduce){#workflow-modal .fx-modo{transition:none}#workflow-modal .fx-linha{animation:none}}

/* ===== padrao-v2/topo.css ===== */
/* ======================================================================================
   PADRÃO V2 · TOPO (moodboard, quadros DEPOIS "Janelas do topo" e "Conta e equipe"; 12/11/2026).
   Janelas do topo: uma janela só, 340 de largura, mesmo cabeçalho (nome + X redondo de 30), corpo e pé com linha
   fina, branca, raio 24, aberta embaixo do ícone. Vale para a Busca (#v2j-busca), os Avisos (.vv-avisos-painel) e o
   menu da Conta (.vv-menu-conta). Conta e equipe (#conta-root .v2c): janela #F9F8F5, cartão branco de raio 20 sem
   borda, controle em pílula (38 e 30), ficha selecionada preta, uma ação #C2490C. Nada aqui força regra antiga.
   ====================================================================================== */

/* ---------- Busca ---------- */
#v2j-busca{--v2j-topo:11vh;box-sizing:border-box;width:420px;max-width:calc(100vw - 16px);max-height:calc(100dvh - var(--v2j-topo) - 16px);margin:var(--v2j-topo) auto auto;padding:0;overflow:hidden;font:400 var(--d3-fs-texto)/1.35 var(--vv-texto,Inter),system-ui,sans-serif;color:#1F1D1A}
#v2j-busca[open]{display:flex;flex-direction:column}
#v2j-busca::backdrop{background:transparent;-webkit-backdrop-filter:none;backdrop-filter:none}
#v2j-busca .v2j-cab{flex:none;display:flex;align-items:center;gap:8px;padding:14px 14px 10px 18px}
#v2j-busca .v2j-cab h2{flex:1;min-width:0;margin:0;font:600 var(--d3-fs-destaque)/1.2 var(--vv-titulo,"Inter Tight"),Inter,sans-serif;color:#1F1D1A}
#v2j-busca .v2j-pill{display:inline-flex;align-items:center;height:22px;padding:0 9px;border-radius:999px;background:#EFEBE4;color:#4A463F;font:600 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;white-space:nowrap}
#v2j-busca .v2j-x.spotlight-fechar{appearance:none;flex:none;display:grid;place-items:center;width:30px;height:30px;padding:0;border:0;border-radius:50%;background:#FFFFFF;color:#1F1D1A;box-shadow:inset 0 0 0 1px #E6E0D6;cursor:pointer}
#v2j-busca .v2j-x.spotlight-fechar:hover{background:#F3F1EC}
#v2j-busca .v2j-x svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
#v2j-busca .v2j-oculto{position:absolute;left:-9999px}
#v2j-busca .v2j-corpo{flex:1;min-height:0;display:flex;flex-direction:column;padding:0 12px}
#v2j-busca .spotlight-campo{flex:none;display:flex;flex-wrap:wrap;align-items:center;gap:6px;padding:0 4px 10px;border:0;background:none;box-shadow:none}
#v2j-busca #spotlight-input{flex:1;min-width:140px;height:36px;box-sizing:border-box;padding:0 16px;border-radius:999px;font:400 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;letter-spacing:0;outline:none}
#v2j-busca #spotlight-input:focus-visible{border-color:#1F1D1A}
#v2j-busca #spotlight-input::placeholder{color:#6B665E}
#v2j-busca .spotlight-escopo{display:inline-flex;align-items:center;gap:6px;height:30px;padding:0 6px 0 12px;border:0;border-radius:999px;background:#1F1D1A;color:#FFFFFF;font:500 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;white-space:nowrap;max-width:100%}
#v2j-busca .spotlight-escopo[hidden]{display:none}
#v2j-busca .spotlight-escopo b{color:#FFFFFF;font-weight:600;overflow:hidden;text-overflow:ellipsis}
#v2j-busca .spotlight-escopo button{appearance:none;display:grid;place-items:center;width:20px;height:20px;padding:0;border:0;border-radius:50%;background:rgba(255,255,255,.18);color:#FFFFFF;font:400 var(--d3-fs-destaque)/1 Inter,sans-serif;cursor:pointer}
#v2j-busca .spotlight-abas{flex:none;display:flex;flex-wrap:wrap;gap:6px;padding:0;border:0;background:none}
#v2j-busca .spotlight-abas > button{padding:0 11px}
#v2j-busca .spotlight-abas button{appearance:none;display:inline-flex;align-items:center;height:30px;min-height:0;padding:0 12px;border:0;border-radius:999px;background:#FFFFFF;color:#1F1D1A;box-shadow:inset 0 0 0 1px #E6E0D6;font:500 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;cursor:pointer}
#v2j-busca .spotlight-abas button[aria-selected="true"]{background:#1F1D1A;color:#FFFFFF;box-shadow:none}
#v2j-busca .spotlight-lista{flex:1;min-height:0;overflow-y:auto;overscroll-behavior:contain;margin:0;padding:0 0 8px;border:0}
#v2j-busca .spotlight-grupo{margin:0;padding:12px 8px 4px;border:0;background:none;font:600 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;letter-spacing:0;text-transform:none;color:#6B665E}
#v2j-busca .spotlight-linha{display:flex;align-items:center;gap:10px;min-height:40px;margin:0;padding:0 8px;border:0;border-radius:12px;background:none;font-size:var(--d3-fs-texto);color:#1F1D1A;cursor:pointer}
#v2j-busca .spotlight-linha[aria-selected="true"]{background:#F3F1EC;box-shadow:none}
#v2j-busca .spotlight-titulo{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font:400 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;color:#1F1D1A}
#v2j-busca .spotlight-sub,#v2j-busca .spotlight-dica{flex:none;max-width:52%;margin-left:auto;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;text-align:right;font:400 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;color:#6B665E}
#v2j-busca .spotlight-dica{display:none}
#v2j-busca .spotlight-linha[aria-selected="true"] .spotlight-dica{display:block}
#v2j-busca .spotlight-linha[aria-selected="true"] .spotlight-sub{display:none}
#v2j-busca .spotlight-avatar{flex:none;display:inline-grid;place-items:center;width:28px;height:28px;border-radius:50%;background:#EFEBE4;color:#4A463F;font:700 var(--d3-fs-mini) var(--vv-texto,Inter),sans-serif}
#v2j-busca .spotlight-mais{flex:1;font:600 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;color:#C2490C}
#v2j-busca .spotlight-vazio{padding:18px 8px;border:0;background:none;text-align:left;font:400 var(--d3-fs-texto)/1.45 var(--vv-texto,Inter),sans-serif;color:#6B665E}
/* o cliente, com a bolinha na cor dele, no lugar da etiqueta */
#v2j-busca .spotlight-titulo :is(.cliente-carteira,.spotlight-cli){display:inline-flex;align-items:center;gap:6px;max-width:100%;padding:0;border:0;border-radius:0;background:none;font:600 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;white-space:nowrap}
#v2j-busca .spotlight-titulo :is(.cliente-carteira,.spotlight-cli)::before{content:"";flex:none;width:8px;height:8px;border-radius:50%;background:var(--carteira-texto,#C2490C)}
#v2j-busca .v2j-pe{flex:none;display:flex;align-items:center;gap:8px;margin:0;padding:12px 14px;border:0;border-top:1px solid #F1EDE6;background:none;font:400 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;color:#6B665E}
#v2j-busca .v2j-pe .spotlight-teclas{display:inline-flex;flex-wrap:wrap;align-items:center;gap:6px 6px}
#v2j-busca .v2j-pe kbd{display:inline-grid;place-items:center;min-width:22px;height:22px;margin-left:6px;padding:0 7px;border-radius:7px;background:var(--d3-trilho);color:var(--d3-tinta);font:600 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif}
#v2j-busca .v2j-pe kbd:first-child{margin-left:0}
@media (max-width:599px){
  #v2j-busca{--v2j-topo:8px;width:auto;max-width:none;margin:8px 8px auto}
  /* Confere responsivo (14/11/2026): no celular a busca descia até o pé da tela, por cima da barra de baixo; termina
     acima dela, como as outras janelas. O toque vai a 44 (fechar e campo) e 36 (abas); "Esc" e as teclas de atalho
     não servem no telefone e saem. */
  #v2j-busca{max-height:calc(100dvh - 84px - env(safe-area-inset-bottom))}
  #v2j-busca .v2j-x.spotlight-fechar{width:44px;height:44px}
  #v2j-busca #spotlight-input{height:44px}
  #v2j-busca .spotlight-abas button{height:36px}
  #v2j-busca .v2j-cab .v2j-pill,#v2j-busca .v2j-pe{display:none}
}

/* ---------- Avisos ---------- */
/* O cabeçalho vira "conteúdo" da grade da janela: o nome e o X ficam no alto, o corpo no meio e "Marcar como lidos"
   desce para o pé, ao lado do Centro de Operação, como no quadro. */
#mundo-hud .vv-avisos-painel{display:grid;grid-template-columns:auto minmax(0,1fr) auto;grid-template-rows:auto minmax(0,1fr) auto;width:340px;max-width:calc(100vw - 16px);border:0;border-radius:24px;background:#FFFFFF;box-shadow:0 2px 4px rgba(31,29,26,.06),0 24px 40px -24px rgba(31,29,26,.35);font:400 var(--d3-fs-texto)/1.35 var(--vv-texto,Inter),system-ui,sans-serif;color:#1F1D1A}
#mundo-hud .vv-avisos-painel .vv-avisos-cab{display:contents}
#mundo-hud .vv-avisos-painel .vv-avisos-cab > div{grid-area:1 / 1 / 2 / 3;display:flex;align-items:center;gap:8px;min-width:0;padding:14px 0 10px 18px}
#mundo-hud .vv-avisos-painel .vv-avisos-cab h2{flex:1;min-width:0;margin:0;font:600 var(--d3-fs-destaque)/1.2 var(--vv-titulo,"Inter Tight"),Inter,sans-serif;color:#1F1D1A}
#mundo-hud .vv-avisos-painel .vv-avisos-cab small{flex:none;display:inline-flex;align-items:center;height:22px;margin:0;padding:0 9px;border-radius:999px;background:#EFEBE4;color:#4A463F;font:600 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;white-space:nowrap}
#mundo-hud .vv-avisos-painel:has(.nao-lido) .vv-avisos-cab small{background:#FFF4D6;color:#7A4A00}
#mundo-hud .vv-avisos-painel .vv-aviso-x{grid-area:1 / 3 / 2 / 4;align-self:center;display:grid;place-items:center;width:30px;min-width:30px;height:30px;min-height:30px;margin:4px 14px 0 8px;padding:0;border:0;border-radius:50%;background:#FFFFFF;color:#1F1D1A;box-shadow:inset 0 0 0 1px #E6E0D6}
#mundo-hud .vv-avisos-painel .vv-aviso-x svg{width:18px;height:18px;stroke-width:1.8}
#mundo-hud .vv-avisos-painel .vv-avisos-corpo{grid-area:2 / 1 / 3 / 4;padding:0 18px 6px}
#mundo-hud .vv-avisos-painel .vv-avisos-corpo h3{margin:0;padding:12px 0 4px;font:600 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;color:#6B665E}
#mundo-hud .vv-avisos-painel .vv-avisos-corpo ul{display:block}
#mundo-hud .vv-avisos-painel .vv-aviso-linha{display:flex;flex-wrap:wrap;align-items:center;gap:6px 12px;padding:12px 0;border:0;border-top:1px solid #F1EDE6;border-radius:0;background:none;font-size:var(--d3-fs-texto)}
#mundo-hud .vv-avisos-painel ul > .vv-aviso-linha:first-child{border-top:0}
#mundo-hud .vv-avisos-painel .vv-aviso-ic{display:none}
#mundo-hud .vv-avisos-painel .vv-aviso-txt{flex:1;min-width:0;gap:1px}
#mundo-hud .vv-avisos-painel .vv-aviso-txt b{font:600 var(--d3-fs-texto)/1.35 var(--vv-texto,Inter),sans-serif;color:#1F1D1A}
#mundo-hud .vv-avisos-painel .vv-aviso-linha.urgente .vv-aviso-txt b{color:#B42318}
#mundo-hud .vv-avisos-painel .vv-aviso-txt small{font:400 var(--d3-fs-texto)/1.35 var(--vv-texto,Inter),sans-serif;color:#6B665E}
#mundo-hud .vv-avisos-painel .vv-aviso-novo{display:inline-flex;align-items:center;height:18px;margin-right:6px;padding:0 7px;border-radius:999px;background:#FFF4D6;color:#7A4A00;font:600 var(--d3-fs-mini) var(--vv-texto,Inter),sans-serif;vertical-align:1px}
#mundo-hud .vv-avisos-painel :is(.vv-aviso-acao,.vv-aviso-lidos,.vv-avisos-pe .vc-sec){flex:none;height:30px;min-height:30px;padding:0 12px;border:0;border-radius:999px;background:#FFFFFF;color:#1F1D1A;box-shadow:inset 0 0 0 1px #E6E0D6;font:600 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;white-space:nowrap}
#mundo-hud .vv-avisos-painel :is(.vv-aviso-acao,.vv-aviso-lidos,.vv-avisos-pe .vc-sec):hover:not(:disabled){background:#F3F1EC;color:#1F1D1A}
#mundo-hud .vv-avisos-painel .vv-aviso-lidos:disabled{color:#6B665E;background:#F9F8F5}
#mundo-hud .vv-avisos-painel .vv-aviso-linha > .vv-aviso-pecas{flex:0 0 100%;margin:0;padding:0 0 0 6px}
#mundo-hud .vv-avisos-painel .vv-aviso-linha.peca{padding:8px 0;border-top:0;border-style:none}
#mundo-hud .vv-avisos-painel .vv-aviso-linha.peca .vv-aviso-txt b{font-weight:400;font-size:var(--d3-fs-texto);color:#4A463F}
#mundo-hud .vv-avisos-painel .vv-aviso-mais{padding:0 0 8px;font:400 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;color:#6B665E}
#mundo-hud .vv-avisos-painel .vv-aviso-vazio{justify-items:start;padding:18px 0;text-align:left}
#mundo-hud .vv-avisos-painel .vv-aviso-vazio.vv-aviso-ultimo{padding:12px 0 0}
#mundo-hud .vv-avisos-painel .vv-aviso-vazio b{font:600 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif}
#mundo-hud .vv-avisos-painel .vv-aviso-lidos{grid-area:3 / 1 / 4 / 2;align-self:center;margin:12px 0 12px 14px}
#mundo-hud .vv-avisos-painel .vv-avisos-pe{grid-area:3 / 2 / 4 / 4;justify-content:flex-end;padding:12px 14px 12px 8px;border:0}
#mundo-hud .vv-avisos-painel:has(.vv-aviso-lidos,.vv-avisos-pe) .vv-avisos-corpo{border-bottom:1px solid #F1EDE6}
@media (max-width:599px){
  #mundo-hud .vv-avisos-painel{width:auto;max-width:none}
}

/* ---------- menu da Conta ---------- */
#mundo-hud .vv-menu-conta{display:flex;flex-wrap:wrap;align-items:center;box-sizing:border-box;width:340px;max-width:calc(100vw - 16px);padding:0 12px;border:0;border-radius:24px;background:#FFFFFF;box-shadow:0 2px 4px rgba(31,29,26,.06),0 24px 40px -24px rgba(31,29,26,.35);font:400 var(--d3-fs-texto)/1.35 var(--vv-texto,Inter),system-ui,sans-serif;color:#1F1D1A}
#mundo-hud .vv-menu-conta::before{content:"Conta";flex:0 0 100%;box-sizing:border-box;padding:18px 6px 12px;font:600 var(--d3-fs-destaque)/1.2 var(--vv-titulo,"Inter Tight"),Inter,sans-serif;color:#1F1D1A}
#mundo-hud .vv-menu-conta > *{flex:0 0 100%;box-sizing:border-box}
#mundo-hud .vv-menu-conta > hr{display:none}
#mundo-hud .vv-menu-conta .vv-menu-quem{gap:12px;min-height:60px;padding:0 8px}
#mundo-hud .vv-menu-conta .vv-menu-av{width:44px;height:44px;background:#EFEBE4;color:#4A463F;font:700 var(--d3-fs-destaque) var(--vv-texto,Inter),sans-serif}
#mundo-hud .vv-menu-conta .vv-menu-quem b{font:700 var(--d3-fs-destaque) var(--vv-texto,Inter),sans-serif;color:#1F1D1A}
#mundo-hud .vv-menu-conta .vv-menu-quem small{font:400 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;color:#6B665E}
#mundo-hud .vv-menu-conta button[data-conta-acao]{gap:10px;min-height:40px;padding:0 8px;border-radius:12px;color:#1F1D1A}
#mundo-hud .vv-menu-conta button[data-conta-acao]:hover{background:#F3F1EC}
#mundo-hud .vv-menu-conta .vv-menu-ic{width:18px;height:18px;border-radius:0;background:none;color:#1F1D1A}
#mundo-hud .vv-menu-conta .vv-menu-ic svg{width:18px;height:18px;stroke-width:1.8}
#mundo-hud .vv-menu-conta button[data-conta-acao] > span{flex:1;display:flex;align-items:center;gap:10px;min-width:0}
#mundo-hud .vv-menu-conta button[data-conta-acao] b{flex:none;font:400 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;color:#1F1D1A}
#mundo-hud .vv-menu-conta button[data-conta-acao] small{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;text-align:right;font:400 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;color:#6B665E}
#mundo-hud .vv-menu-conta .vv-menu-tema-linha{flex-wrap:wrap;justify-content:flex-start;gap:0;padding:0 8px 6px}
#mundo-hud .vv-menu-conta .vv-menu-tema-linha > span:first-child{flex:0 0 100%;padding:12px 0 6px;font:600 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;color:#6B665E}
#mundo-hud .vv-menu-conta .vv-menu-tema-linha .vb-alternar{display:inline-flex;gap:0;padding:4px;border:0;border-radius:999px;background:#EAE6DE}
#mundo-hud .vv-menu-conta .vv-menu-tema-linha .vb-alternar button{display:inline-flex;align-items:center;justify-content:center;width:auto;height:30px;padding:0 14px;border:0;border-radius:999px;background:none;color:#6B665E;font:600 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif}
#mundo-hud .vv-menu-conta .vv-menu-tema-linha .vb-alternar button[aria-checked="true"]{background:#FFFFFF;color:#1F1D1A;box-shadow:0 1px 3px rgba(31,29,26,.18)}
/* o pé: "mais ajustes" à esquerda, Sair em botão à direita */
#mundo-hud .vv-menu-conta button[data-conta-acao="ajustes"]{order:2;flex:1 1 0;min-width:0;margin:6px 0 0;padding:12px 2px;border-top:1px solid #F1EDE6;border-radius:0}
#mundo-hud .vv-menu-conta button[data-conta-acao="ajustes"]:hover{background:none}
#mundo-hud .vv-menu-conta button[data-conta-acao="ajustes"] .vv-menu-ic,#mundo-hud .vv-menu-conta button[data-conta-acao="ajustes"] small{display:none}
#mundo-hud .vv-menu-conta button[data-conta-acao="ajustes"] b{font-size:var(--d3-fs-texto);color:#6B665E}
#mundo-hud .vv-menu-conta button[data-conta-acao="ajustes"]:hover b{color:#1F1D1A}
#mundo-hud .vv-menu-conta button[data-conta-acao="sair"]{order:3;flex:0 0 auto;width:auto;min-height:0;margin:6px 0 0;padding:12px 2px;border-top:1px solid #F1EDE6;border-radius:0}
#mundo-hud .vv-menu-conta button[data-conta-acao="sair"]:hover{background:none}
#mundo-hud .vv-menu-conta button[data-conta-acao="sair"] .vv-menu-ic{display:none}
#mundo-hud .vv-menu-conta button[data-conta-acao="sair"] b{display:inline-flex;align-items:center;height:30px;padding:0 12px;border-radius:999px;background:#FFFFFF;box-shadow:inset 0 0 0 1px #E6E0D6;font:600 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;color:#1F1D1A}
#mundo-hud .vv-menu-conta button[data-conta-acao="sair"]:hover b{background:#F3F1EC}
#mundo-hud .vv-menu-conta button[data-conta-acao^="vercomo:"]:last-child{margin-bottom:12px}

/* ---------- Conta e equipe ---------- */
