#conta-root .v2c .v2c-sub{font-size:var(--d3-fs-texto);color:#6B665E}
#conta-root .v2c-topo{display:flex;flex-direction:row;flex-wrap:wrap;align-items:center;gap:12px;margin-right:var(--vv-caixa-vao,0px);text-align:left}
#conta-root .v2c-card{min-width:0;box-sizing:border-box;padding:18px;border:0;border-radius:20px;background:#FFFFFF;box-shadow:0 1px 2px rgba(31,29,26,.05),0 12px 24px -18px rgba(31,29,26,.22)}
#conta-root .v2c-btn{appearance:none;flex:none;display:inline-flex;align-items:center;justify-content:center;gap:6px;height:38px;min-height:0;padding:0 16px;border:0;border-radius:999px;background:#FFFFFF;color:#1F1D1A;box-shadow:inset 0 0 0 1px #E6E0D6;font:600 var(--d3-fs-texto) var(--vv-texto,Inter),sans-serif;white-space:nowrap;cursor:pointer;transition:transform .14s cubic-bezier(.34,1.56,.64,1),background-color .2s,color .2s}
#conta-root .v2c-btn:active{transform:scale(.96)}
#conta-root .v2c-btn:hover{background:#F3F1EC}
#conta-root .v2c-btn:focus-visible,#conta-root .v2c-chip:focus-visible,#conta-root .v2c-link:focus-visible,#conta-root .v2c-seg button:focus-visible{outline:2px solid #C2490C;outline-offset:2px}
#conta-root .v2c-btn.p{background:#C2490C;color:#FFFFFF;box-shadow:0 8px 16px -10px #C2490C}
#conta-root .v2c-btn.p:hover{background:#A83E09}
#conta-root .v2c-btn.k,#conta-root .v2c-btn[aria-pressed="true"]{background:#1F1D1A;color:#FFFFFF;box-shadow:none}
#conta-root .v2c-btn.s{height:30px;padding:0 12px;font-size:var(--d3-fs-texto)}
#conta-root .v2c-btn:disabled{background:#F3F1EC;color:#6B665E;box-shadow:none;cursor:not-allowed}
#conta-root .v2c-btn.v2-estado[data-estado="indo"]{position:relative;color:transparent;pointer-events:none}
#conta-root .v2c-pill{flex:none;display:inline-flex;align-items:center;gap:5px;height:22px;padding:0 9px;border-radius:999px;font:600 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;white-space:nowrap}
