/* a fala do VYBES */
#conta-root .v2c-fala{display:flex;align-items:center;gap:14px}
#conta-root .v2c-fala p{flex:1;min-width:0;font-size:var(--d3-fs-destaque);line-height:1.45;color:#1F1D1A}
#conta-root .v2c-ag{flex:none;position:relative;display:grid;place-items:center;width:40px;height:40px;border-radius:50%;background:#6E56CF;color:#FFFFFF;font:700 var(--d3-fs-destaque) var(--vv-texto,Inter),sans-serif}
#conta-root .v2c-ag::after{content:"";position:absolute;inset:-5px;border-radius:50%;border:2px solid #6E56CF;opacity:0;animation:v2c-pulso 3.6s ease-out infinite}
@keyframes v2c-pulso{0%{opacity:.5;transform:scale(.85)}70%,100%{opacity:0;transform:scale(1.25)}}
#conta-root .v2c-quem-fala{display:block;margin-bottom:2px;font:600 var(--d3-fs-apoio) var(--vv-texto,Inter),sans-serif;color:#4B36A8}
/* os três números */
#conta-root .v2c-tres{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}
