#vv-wa-avisos.pilula:not(.aberto) .vv-aviso-curto-ic{background:var(--d3-fume-veu);color:var(--d3-fume-texto)}
#vv-wa-avisos.pilula:not(.aberto) .vv-aviso-curto-txt b{color:var(--d3-fume-texto)}
#vv-dock-salas-faixa .vq-dock .vq-item.vq-entrar{background:var(--d3-fume-texto);color:var(--d3-tinta)}
#vv-dock-salas-faixa .vq-dock .vq-item.voz{background:var(--d3-fume-veu)}
#vv-dock-salas-faixa .vq-dock .vq-item:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}
#vv-dock-salas-faixa .vq-dock .vq-sep{background:var(--d3-fume-borda)}
#vv-dock-salas-faixa .vq-dock .vq-conta{background:var(--d3-fume-texto);color:var(--d3-tinta)}
#vv-dock-salas-faixa .vq-dock .vq-voz{border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu);color:var(--d3-fume-texto)}
#vv-dock-salas-faixa .vq-dock .vq-voz button{border-radius:var(--d3-r-botao);background:var(--d3-fume-texto);color:var(--d3-tinta)}
#vv-dock-salas-faixa .vq-dock .vq-voz button:disabled{background:var(--d3-fume-veu);color:var(--d3-fume-apagado)}

/* 3 · A FAMÍLIA DE PEÇAS (prancha V2-Pecas). Classes soltas, para qualquer tela: botão de 34 px com canto 8 em três
   papéis, rótulo, selo, foto do cliente, etiqueta e os estados (vazio, carregando, erro). As peças antigas do Hoje
   (d3h-btn, d3h-link, d3h-pill) recebem os mesmos valores mais abaixo. */
.d3v-btn{appearance:none;display:inline-flex;align-items:center;justify-content:center;gap:6px;height:34px;margin:0;padding:0 14px;box-sizing:border-box;border:0;border-radius:var(--d3-r-botao);background:var(--d3-tinta);color:var(--d3-escuro-texto);font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);text-decoration:none;white-space:nowrap;cursor:pointer;transition:background-color .2s,box-shadow .2s}
.d3v-btn:hover{background:var(--d3-texto2)}
.d3v-btn.sec{background:var(--d3-veu);color:var(--d3-tinta);font-weight:500}
.d3v-btn.sec:hover{background:var(--d3-veu-forte)}
.d3v-btn.txt{padding:0 4px;background:none;color:var(--d3-tinta);font-weight:500}
.d3v-btn.txt:hover{background:var(--d3-veu)}
.d3v-btn.ico{width:34px;padding:0}
.d3v-btn.s{height:28px;padding:0 10px}
.d3v-btn.ico.s{width:28px;padding:0}
.d3v-btn.vidro{background:var(--d3-fume-veu);color:var(--d3-fume-texto);font-weight:500}
.d3v-btn.vidro:hover{background:var(--d3-fume-veu-forte)}
.d3v-btn:focus-visible{outline:2px solid var(--d3-acao);outline-offset:2px}
.d3v-btn:disabled,.d3v-btn[aria-disabled="true"]{background:var(--d3-veu);color:var(--d3-meta);cursor:default}
.d3v-rot{font:400 var(--d3-fs-apoio)/1.3 var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
.d3v-selo{flex:none;display:grid;place-items:center;width:24px;height:24px;border-radius:7px;background:var(--d3-info)}
.d3v-selo[data-k="r"]{background:var(--d3-perigo)}
.d3v-selo[data-k="roxo"]{background:var(--d3-agente)}
.d3v-selo[data-k="g"]{background:var(--d3-pronto)}
.d3v-selo > svg{width:12px;height:12px;fill:none;stroke:var(--d3-escuro-texto);stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round}
.d3v-foto{flex:none;display:grid;place-items:center;width:28px;height:28px;border-radius:8px;object-fit:cover;background:var(--d3-veu-forte);color:var(--d3-texto2);font:600 var(--d3-fs-mini) var(--vv-texto,Inter,sans-serif);font-style:normal;text-transform:uppercase}
.d3v-foto.g{width:40px;height:40px;border-radius:10px;font-size:var(--d3-fs-texto)}
.d3v-st{display:inline-flex;align-items:center;gap:6px;min-width:0;max-width:100%;font:400 var(--d3-fs-apoio)/1.3 var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3v-st > i{flex:none;width:7px;height:7px;border-radius:50%;background:var(--st,var(--d3-meta))}
.d3v-etiqueta{display:inline-flex;align-items:center;height:20px;padding:0 8px;border-radius:999px;background:var(--d3-veu);color:var(--d3-tinta);font:500 var(--d3-fs-mini) var(--vv-texto,Inter,sans-serif);white-space:nowrap}
.d3v-estado{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;flex:1 1 auto;min-height:96px;margin:0;padding:12px 16px;text-align:center;font:400 var(--d3-fs-apoio)/1.4 var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
.d3v-estado > b{font:600 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}
.d3v-estado.erro{border-radius:12px;background:var(--d3-perigo-veu)}
/* Carregando: barras que respiram (de .55 a 1, nunca de zero). */
@keyframes d3vRespira{0%,100%{opacity:.55}50%{opacity:1}}
.d3v-esq{display:block;border-radius:16px;background:var(--d3-folha);animation:d3vRespira 1.6s ease-in-out infinite}
.d3v-esq.linha{height:10px;border-radius:5px;background:var(--d3-veu-forte)}
@media (prefers-reduced-motion:reduce){.d3v-esq{animation:none}}

/* 4 · HOJE NO ESQUELETO DA PRANCHA V2-Hoje (abas Agência, Criação e Minhas tarefas: a raiz leva .d3q). A janela é
   vidro fumê; à esquerda a saudação, os quatro números, o cartão do trabalho com o laranja ao lado e o pé; à direita a
   coluna de consulta, direto no vidro. Em 1440 × 900 cabe tudo, com o dock à vista; o que é lista rola dentro do cartão. */
body.mundo #mundo-hud > #vv-hoje.vv-hoje.d3h-tela:has(> .d3q){padding:16px;border:0;border-radius:20px;background:var(--d3-fume);box-shadow:inset 0 0 0 1px var(--d3-fume-borda),0 30px 60px -40px rgba(0,0,0,.6);color:var(--d3-fume-texto)}
#vv-hoje.d3h-tela > .d3q{display:grid;grid-template-columns:minmax(0,1fr) 316px;gap:16px;align-items:stretch;height:100%;min-height:676px;box-sizing:border-box;color:var(--d3-tinta)}
#vv-hoje .d3q-main{display:flex;flex-direction:column;gap:16px;min-width:0;min-height:0}
#vv-hoje .d3q-main > *{flex:none}
#vv-hoje .d3q-meio,#vv-hoje .d3q-pe{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(0,1fr);gap:12px;align-items:stretch;min-width:0}
#vv-hoje .d3q-main > .d3q-meio{flex:1.18 1 0;min-height:284px}
#vv-hoje .d3q-main > .d3q-pe{flex:1 1 0;min-height:232px}
#vv-hoje .d3q-pe:empty{display:none}
#vv-hoje .d3q-pe > :only-child{grid-column:1 / -1}
#vv-hoje .d3q-acao{display:flex;flex-direction:column;min-width:0;min-height:0}
#vv-hoje .d3q-acao > *{flex:1 1 auto;min-height:0}

/* Saudação e abas, no vidro: letra branca; a linha de apoio embaixo do título. */
#vv-hoje .d3q .d3h-topo{flex-wrap:nowrap;align-items:center;min-height:48px;gap:16px;color:var(--d3-fume-texto)}
#vv-hoje .d3q .d3h-ola{display:flex;flex-direction:column;align-items:flex-start;flex-wrap:nowrap;gap:3px;min-width:0}
#vv-hoje .d3q .d3h-ola > h2{font:600 24px/1.1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.02em;color:var(--d3-fume-texto);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%}
#vv-hoje .d3q .d3h-ola > small{font:400 var(--d3-fs-texto)/1.2 var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-apagado)}
#vv-hoje .d3q .d3h-topo-dir{flex:none;flex-wrap:nowrap;gap:8px}
#vv-hoje .d3q .d3h-topo .vv-seg,#vv-hoje .d3q .d3h-topo .vv-seg.vb-abas:not(#vb-a):not(#vb-b){gap:2px;height:36px;padding:3px;box-sizing:border-box;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu);--ds-on-fundo:var(--d3-fume-texto);--ds-on-texto:var(--d3-tinta)}
#vv-hoje .d3q .d3h-topo .vv-seg > button,#vv-hoje .d3q .d3h-topo .vv-seg.vb-abas:not(#vb-a):not(#vb-b) [role="tab"]{height:30px;padding:0 12px;border-radius:var(--d3-r-botao);color:var(--d3-fume-texto);font:400 var(--d3-fs-texto)/1 var(--vv-texto,Inter,sans-serif)}
#vv-hoje .d3q .d3h-topo .vv-seg.vb-abas:not(#vb-a):not(#vb-b) [role="tab"]:hover{color:var(--d3-fume-texto)}
#vv-hoje .d3q .d3h-topo .vv-seg > button[aria-selected="true"],#vv-hoje .d3q .d3h-topo .vv-seg.vb-abas:not(#vb-a):not(#vb-b) [role="tab"][aria-selected="true"]{background:var(--d3-fume-texto);color:var(--d3-tinta);font-weight:600}
#vv-hoje .d3q .d3h-topo .vv-seg.vb-abas.vb-abas-desliza:not(#vb-a):not(#vb-b) [role="tab"][aria-selected="true"]{background:transparent;color:var(--d3-tinta)}
#vv-hoje .d3q .d3h-topo .vv-seg.vb-abas.vb-abas-desliza:not(#vb-a):not(#vb-b)::before{top:3px;bottom:3px;border-radius:var(--d3-r-botao);background:var(--d3-fume-texto)}
#vv-hoje .d3q .d3h-topo :is(.d3h-dia > summary,button.d3h-dia,.d3h-mais-menu > summary,.d3h-btn){height:36px;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu);color:var(--d3-fume-texto)}
#vv-hoje .d3q .d3h-topo :is(.d3h-dia > summary,button.d3h-dia) > b{color:var(--d3-fume-texto);font-weight:600}
#vv-hoje .d3q .d3h-topo :is(.d3h-dia > summary,button.d3h-dia) > i{width:28px;height:28px;border-radius:var(--d3-r-botao);background:var(--d3-fume-veu-forte);color:var(--d3-fume-texto);font-weight:600}
#vv-hoje .d3q .d3h-topo .d3h-mais-menu > summary{width:36px}
#vv-hoje .d3q .d3h-topo :is(.v2t-dia-pop,.d3h-mais-pop){color:var(--d3-tinta)}
#vv-hoje .d3q .d3h-topo .d3h-mais-pop > .d3h-btn{height:34px;border-radius:var(--d3-r-botao);background:var(--d3-veu);color:var(--d3-tinta)}
#vv-hoje .d3q .d3h-topo :is(.vv-seg > button,summary,button.d3h-dia):focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}

/* Números: rótulo e selo em cima; embaixo o número com a nota e, ao lado, o gráfico na cor do que o número é. */
#vv-hoje .d3q .d3h-nums{gap:12px}
#vv-hoje .d3q .d3h-num{display:grid;grid-template-columns:minmax(0,1fr) auto;grid-template-rows:auto 1fr;gap:8px 10px;height:116px;padding:14px;box-sizing:border-box;border:0;border-radius:16px;background:var(--d3-folha);box-shadow:var(--d3-folha-sombra);color:var(--d3-tinta);text-align:left;--k:var(--d3-info)}
#vv-hoje .d3q .d3h-num[data-k="r"]{--k:var(--d3-perigo)}
#vv-hoje .d3q .d3h-num[data-k="roxo"]{--k:var(--d3-agente)}
#vv-hoje .d3q .d3h-num[data-k="g"]{--k:var(--d3-pronto)}
#vv-hoje .d3q button.d3h-num{cursor:pointer;transition:transform .2s,box-shadow .2s}
#vv-hoje .d3q button.d3h-num:hover{background:var(--d3-cartao);box-shadow:0 18px 34px -22px rgba(0,0,0,.7);transform:translateY(-1px)}
#vv-hoje .d3q button.d3h-num:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}
#vv-hoje .d3q .d3h-num > .d3-num-rot{align-self:center;padding:0;font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}
#vv-hoje .d3q .d3h-num > .d3h-num-selo{position:static;align-self:center;display:grid;place-items:center;width:24px;height:24px;border-radius:7px;background:var(--k)}
#vv-hoje .d3h-num-selo > svg{width:12px;height:12px;fill:none;stroke:var(--d3-escuro-texto);stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round}
#vv-hoje .d3q .d3h-num-linha{grid-column:1 / -1;display:flex;align-items:flex-end;justify-content:space-between;gap:10px;min-width:0}
#vv-hoje .d3q .d3h-num-txt{display:flex;flex-direction:column;gap:4px;min-width:0;min-height:46px}
#vv-hoje .d3q .d3h-num-txt > .d3-num-v{display:block;font:600 var(--d3-fs-numero)/1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.02em;color:var(--d3-tinta);font-variant-numeric:tabular-nums;white-space:nowrap}
#vv-hoje .d3q .d3h-num.r .d3-num-v{color:var(--d3-perigo)}
#vv-hoje .d3q .d3h-num-txt > .d3-num-v > small{font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);letter-spacing:0;color:var(--d3-rotulo)}
#vv-hoje .d3q .d3h-num-sub{font:400 var(--d3-fs-apoio)/1.2 var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#vv-hoje .d3q .d3h-num-sub.r{color:var(--d3-rotulo)}
#vv-hoje .d3q .d3h-num-linha > .d3-graf{flex:none;width:84px;height:36px}
#vv-hoje .d3q .d3h-num-linha > .d3-graf polyline:not(.meta){stroke:var(--k);stroke-width:2.2}
#vv-hoje .d3q .d3h-num-linha > .d3-graf circle{fill:var(--k)}
#vv-hoje .d3v-barras{flex:none;display:flex;align-items:flex-end;gap:3px;height:36px}
#vv-hoje .d3v-barras > i{width:5px;height:var(--h,60%);border-radius:2px;background:var(--k);opacity:.22}
#vv-hoje .d3v-barras > i.on{opacity:1}
#vv-hoje .d3v-anel{flex:none;width:44px;height:44px;transform:rotate(-90deg)}
#vv-hoje .d3v-anel > circle{fill:none;stroke:var(--k);stroke-width:5;stroke-linecap:round}
#vv-hoje .d3v-anel > circle:first-child{opacity:.16}

/* Cartão (folha clara): cabeçalho de 44, título 14/600, rótulo cinza, divisória fina; o corpo rola por dentro. */
#vv-hoje .d3q .d3h-cartao{padding:0;border-radius:16px;background:var(--d3-folha);box-shadow:var(--d3-folha-sombra);color:var(--d3-tinta);overflow:hidden;min-height:0;--d3-linha:var(--d3-divisa);--d3-apagado:var(--d3-rotulo)}
#vv-hoje .d3q .d3h-cab{flex:none;height:44px;padding:0 16px;box-sizing:border-box}
#vv-hoje .d3q .d3h-cab > h3{font:600 14px/1.25 var(--vv-texto,Inter,sans-serif)}
#vv-hoje .d3q .d3h-aux{gap:10px;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
#vv-hoje .d3q .d3h-corpo{flex:1 1 auto;min-height:0;overflow-y:auto;scrollbar-width:thin}
#vv-hoje .d3q .d3h-link{color:var(--d3-tinta);font-weight:500;text-decoration:none;border-radius:4px}
#vv-hoje .d3q .d3h-link:hover{text-decoration:underline;text-underline-offset:3px}
#vv-hoje .d3q :is(.d3h-link,.d3h-lin,.d3h-ficha,.d3q-cli,.v2t-ficha,.v2t-nome,.v2t-cx,.d3h-btn,.d3-acao-btn,.d3h-pes):focus-visible{outline:2px solid var(--d3-acao);outline-offset:-2px}
#vv-hoje .d3q .d3h-vazio{padding:12px 16px;font:400 var(--d3-fs-apoio)/1.4 var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
#vv-hoje .d3q .d3h-pe{flex:none;padding:10px 16px}

/* Botões do Hoje: a mesma família (34 px, canto 8; 28 px só dentro de linha). */
#vv-hoje .d3q .d3h-btn{height:34px;padding:0 14px;border-radius:var(--d3-r-botao);background:var(--d3-veu);color:var(--d3-tinta);font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif)}
#vv-hoje .d3q .d3h-btn:hover{background:var(--d3-veu-forte)}
#vv-hoje .d3q .d3h-btn.k{background:var(--d3-tinta);color:var(--d3-escuro-texto);font-weight:600}
#vv-hoje .d3q .d3h-btn.k:hover{background:var(--d3-texto2)}
#vv-hoje .d3q .d3h-btn.s{height:28px;padding:0 10px}
#vv-hoje .d3q .d3h-btn:disabled{background:var(--d3-veu);color:var(--d3-meta)}
#vv-hoje .d3q .d3h-btn.d3h-passo{flex:none;width:34px;padding:0}
#vv-hoje .d3q .d3h-btn.d3h-passo > svg{width:15px;height:15px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}

/* Linha da fila (Pede ação, Pediram ajuste): o grupo uma vez só, a foto do cliente, cliente · peça, o status como ponto
   de cor com texto, a data e quem faz. Vermelho só no que venceu; âmbar no que é hoje. */
#vv-hoje .d3q .d3h-lin{gap:10px;min-height:38px;padding:5px 16px;border-top:1px solid var(--d3-divisa);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif)}
#vv-hoje .d3q .d3h-lin:hover,#vv-hoje .d3q .d3h-tarefas .v2-linha:hover{background:var(--d3-veu)}
#vv-hoje .d3q .d3h-q{width:56px;font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);letter-spacing:0;text-transform:none;color:var(--d3-rotulo)}
#vv-hoje .d3q .d3h-q.r{color:var(--d3-perigo)}
#vv-hoje .d3q .d3h-q.a{color:var(--d3-ambar)}
#vv-hoje .d3q .d3h-q.ok{color:var(--d3-pronto)}
#vv-hoje .d3q .d3h-nome{color:var(--d3-rotulo)}
#vv-hoje .d3q .cliente-carteira{font-weight:600}
#vv-hoje .d3q .cliente-carteira::before{content:none}
#vv-hoje .d3q .d3h-st{max-width:120px}
#vv-hoje .d3q .pill.vv-st-ponto{height:auto;padding:0;border-radius:0;background:none;color:var(--d3-tinta);font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif)}
#vv-hoje .d3q .d3h-qd{min-width:76px;text-align:right;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);font-variant-numeric:tabular-nums}
#vv-hoje .d3q .d3h-qd.r{color:var(--d3-perigo)}
#vv-hoje .d3q .d3h-qd.a{color:var(--d3-ambar)}
#vv-hoje .d3q .d3h-av{width:24px;height:24px;background:var(--d3-veu-forte);color:var(--d3-tinta);font:600 10px var(--vv-texto,Inter,sans-serif)}
#vv-hoje .d3q .d3h-av.sd{background:none;box-shadow:inset 0 0 0 1px rgba(31,29,26,.28);color:var(--d3-rotulo);font-weight:400;font-size:var(--d3-fs-texto)}

/* "De olho": uma faixa de contadores no pé do cartão (número e rótulo, divisória fina entre eles). */
#vv-hoje .d3q .d3h-olho{flex:none;flex-wrap:wrap;align-items:center;gap:0;height:44px;margin-top:auto;padding:0 16px;box-sizing:border-box;border-top:1px solid var(--d3-divisa);overflow:hidden}
#vv-hoje .d3q .d3h-olho > span{flex:none;height:44px;display:inline-flex;align-items:center;margin-right:14px;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
#vv-hoje .d3q .d3h-olho > .d3h-ficha{flex:none;display:inline-flex;align-items:baseline;gap:5px;max-width:none;height:20px;margin:12px 0;padding:0 12px;border-radius:0;border-left:1px solid var(--d3-veu-forte);background:none;color:var(--d3-tinta);font:inherit;overflow:visible}
#vv-hoje .d3q .d3h-olho > span + .d3h-ficha{padding-left:0;border-left:0}
#vv-hoje .d3q .d3h-olho > .d3h-ficha:hover{background:none}
#vv-hoje .d3q .d3h-olho > .d3h-ficha:hover > small{color:var(--d3-tinta)}
#vv-hoje .d3q .d3h-ficha > b{font:600 14px var(--vv-texto,Inter,sans-serif);font-variant-numeric:tabular-nums}
#vv-hoje .d3q .d3h-ficha.r > b{color:var(--d3-perigo)}
#vv-hoje .d3q .d3h-ficha.a > b{color:var(--d3-ambar)}
#vv-hoje .d3q .d3h-ficha > small{font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);white-space:nowrap}

/* O cartão laranja: o único laranja cheio da tela. Rótulo (quem ou o que é), número ou arte, título em uma frase, linha
   de apoio e até dois botões. A luz fica no canto, longe do texto; a letra é branca cheia sobre o laranja escuro. */
#vv-hoje .d3q .d3v-laranja{position:relative;display:flex;flex-direction:column;align-items:stretch;gap:4px;padding:16px;border-radius:16px;overflow:hidden;background:var(--d3-laranja);box-shadow:0 18px 34px -20px rgba(194,73,12,.85);color:var(--d3-escuro-texto);font:400 var(--d3-fs-texto)/1.4 var(--vv-texto,Inter,sans-serif);
  --d3-tinta:var(--d3-escuro-texto);--d3-texto2:var(--d3-escuro-texto);--d3-apagado:var(--d3-escuro-texto);--d3-rotulo:var(--d3-escuro-texto);--d3-linha:rgba(255,255,255,.2);--d3-divisa:rgba(255,255,255,.2)}
#vv-hoje .d3q .d3v-laranja::before{content:"";position:absolute;right:-60px;top:-70px;width:180px;height:180px;border-radius:50%;background:rgba(255,255,255,.16);pointer-events:none}
#vv-hoje .d3q .d3v-laranja::after{content:"";position:absolute;right:24px;top:84px;width:64px;height:64px;border-radius:50%;background:rgba(255,255,255,.1);pointer-events:none}
#vv-hoje .d3q .d3v-laranja > *{position:relative;z-index:1}
#vv-hoje .d3v-lar-rot{display:flex;align-items:center;gap:8px;font:400 var(--d3-fs-apoio)/1.3 var(--vv-texto,Inter,sans-serif)}
#vv-hoje .d3v-lar-rot > .d3-acao-av{flex:none;display:grid;place-items:center;width:26px;height:26px;border-radius:50%;background:var(--d3-escuro-texto);color:var(--d3-agente);font:700 var(--d3-fs-mini) var(--vv-texto,Inter,sans-serif)}
#vv-hoje .d3v-lar-txt{display:flex;flex-direction:column;gap:4px;margin-top:auto;min-width:0}
#vv-hoje .d3v-lar-num{font:600 60px/1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.03em;font-variant-numeric:tabular-nums}
#vv-hoje .d3v-lar-txt > .d3-acao-frase{flex:none;overflow:visible;white-space:normal;font:600 19px/1.25 var(--vv-titulo,"Inter Tight",Inter,sans-serif)}
#vv-hoje .d3v-lar-txt > small{font:400 var(--d3-fs-texto)/1.4 var(--vv-texto,Inter,sans-serif)}
#vv-hoje .d3v-lar-bts{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}
#vv-hoje .d3q .d3v-laranja :is(.d3-acao-btn,.d3h-btn){appearance:none;flex:none;display:inline-flex;align-items:center;justify-content:center;height:34px;margin:0;padding:0 14px;border:0;border-radius:var(--d3-r-botao);background:rgba(255,255,255,.16);box-shadow:inset 0 0 0 1px rgba(255,255,255,.38);color:var(--d3-escuro-texto);font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);white-space:nowrap;cursor:pointer}
#vv-hoje .d3q .d3v-laranja :is(.d3-acao-btn,.d3h-btn):hover{background:rgba(255,255,255,.26)}
#vv-hoje .d3q .d3v-laranja :is(.d3-acao-btn:not(.d3v-veu),.d3h-btn.k){background:var(--d3-escuro-texto);box-shadow:none;color:var(--d3-acao-texto);font-weight:600}
#vv-hoje .d3q .d3v-laranja :is(.d3-acao-btn:not(.d3v-veu),.d3h-btn.k):hover{background:rgba(255,255,255,.9)}
#vv-hoje .d3q .d3v-laranja .d3h-btn.d3h-passo{width:34px;padding:0}
#vv-hoje .d3q .d3v-laranja .d3h-btn:disabled{background:rgba(255,255,255,.08);box-shadow:inset 0 0 0 1px rgba(255,255,255,.2);color:rgba(255,255,255,.55)}
#vv-hoje .d3q .d3v-laranja :is(button,a,.d3h-baralho):focus-visible{outline:2px solid var(--d3-escuro-texto);outline-offset:2px}
#vv-hoje .d3q .d3v-laranja .d3h-link{color:var(--d3-escuro-texto)}
/* Os passos do guia do dia: três linhas finas com o número. */
#vv-hoje .d3q .d3v-laranja > .d3h-acao-passos{display:flex;flex-direction:column;gap:4px;margin:8px 0 0;padding:0;list-style:none}
#vv-hoje .d3q .d3v-laranja > .d3h-acao-passos > li{max-width:none;min-width:0}
#vv-hoje .d3q .d3v-laranja > .d3h-acao-passos button{appearance:none;display:flex;align-items:center;gap:8px;width:100%;height:30px;margin:0;padding:0 10px 0 6px;border:0;border-radius:var(--d3-r-botao);background:rgba(255,255,255,.14);box-shadow:none;color:var(--d3-escuro-texto);font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
#vv-hoje .d3q .d3v-laranja > .d3h-acao-passos button:hover{background:rgba(255,255,255,.24)}
#vv-hoje .d3q .d3v-laranja > .d3h-acao-passos button > i{flex:none;display:grid;place-items:center;width:18px;height:18px;border-radius:50%;background:rgba(255,255,255,.22);color:var(--d3-escuro-texto);font:600 var(--d3-fs-mini) var(--vv-texto,Inter,sans-serif);font-style:normal}
#vv-hoje .d3q .d3v-laranja > .d3h-acao-passos button > span{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

/* Baralho de aprovar. As cartas guardam a arte e o texto; o que muda é onde cada parte aparece. */
#vv-hoje .d3q .d3h-decidir{gap:0}
#vv-hoje .d3q .d3h-decidir > .d3h-cab{padding:0 16px}
#vv-hoje .d3q .d3h-baralho{min-height:0;height:auto;outline:none;overflow:visible}
#vv-hoje .d3q .d3h-baralho > .d3h-carta{display:contents}
#vv-hoje .d3q .d3h-baralho > .d3h-carta:not([data-pos]){display:none}
#vv-hoje .d3q .d3h-arte{position:relative;overflow:hidden;border-radius:12px;background:var(--d3-escuro);box-shadow:0 18px 30px -16px rgba(0,0,0,.6)}
#vv-hoje .d3q .d3h-arte > :is(img,video){position:absolute;inset:0;width:100%;height:100%;object-fit:cover;display:block}
#vv-hoje .d3q .d3h-arte > span{position:absolute;left:8px;top:8px;bottom:auto;max-width:calc(100% - 16px);height:20px;padding:0 8px;display:inline-flex;align-items:center;border-radius:999px;background:rgba(255,255,255,.92);color:var(--d3-tinta-fixa);font:500 var(--d3-fs-mini) var(--vv-texto,Inter,sans-serif)}
#vv-hoje .d3q .d3h-carta-txt{gap:6px}
#vv-hoje .d3q .d3h-carta-cli{display:inline-flex;align-items:center;gap:8px;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
#vv-hoje .d3q .d3h-carta-cli .cliente-carteira{--carteira-texto:var(--d3-rotulo);font-weight:400}
#vv-hoje .d3q .d3h-carta-cli > .d3v-foto{width:20px;height:20px;border-radius:6px;font-size:9px}
#vv-hoje .d3q .d3h-carta-txt > b{font:600 18px/1.2 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.01em}
#vv-hoje .d3q .d3h-carta-txt > small{font:400 var(--d3-fs-apoio)/1.45 var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
#vv-hoje .d3q .d3h-decidir-acoes{gap:8px}
#vv-hoje .d3q .d3h-decidir-acoes > .d3h-btn{flex:none}
#vv-hoje .d3q .d3h-decidir-acoes > .d3v-vao{flex:1 1 auto}
/* Na folha clara (Agência): a arte em leque à esquerda (a do meio em foco, as vizinhas menores e escurecidas) e, ao
   lado, o cliente, a peça, o status e os botões. */
#vv-hoje .d3q .d3v-leque{container:leque / inline-size;display:grid;grid-template-columns:minmax(132px,236px) minmax(292px,1fr);grid-template-rows:44px minmax(0,1fr) auto;column-gap:20px;padding:0 16px 16px}
#vv-hoje .d3q .d3v-leque > .d3h-cab{grid-column:1 / -1;padding:0}
#vv-hoje .d3q .d3v-leque > .d3h-baralho{grid-column:1 / -1;grid-row:2;display:grid;grid-template-columns:subgrid;border-radius:12px}
#vv-hoje .d3q .d3v-leque .d3h-arte{grid-column:1;grid-row:1;justify-self:center;align-self:start;height:calc(100% + 42px);max-height:190px;aspect-ratio:3 / 4;flex:none;transition:transform .45s cubic-bezier(.22,1,.36,1),filter .45s,opacity .3s;cursor:pointer}
#vv-hoje .d3q .d3v-leque .d3h-carta[data-pos="0"] > .d3h-arte{z-index:3;cursor:default}
#vv-hoje .d3q .d3v-leque .d3h-carta[data-pos="1"] > .d3h-arte{z-index:2;transform:translateX(44%) scale(.76);filter:brightness(.55)}
#vv-hoje .d3q .d3v-leque .d3h-carta[data-pos="fora"] > .d3h-arte{z-index:1;transform:translateX(-44%) scale(.76);filter:brightness(.55)}
#vv-hoje .d3q .d3v-leque .d3h-carta[data-pos="2"] > .d3h-arte{z-index:0;transform:translateX(60%) scale(.6);opacity:0;pointer-events:none}
#vv-hoje .d3q .d3v-leque .d3h-carta-txt{grid-column:2;grid-row:1;align-self:end;display:none;padding-bottom:10px}
#vv-hoje .d3q .d3v-leque .d3h-carta[data-pos="0"] > .d3h-carta-txt{display:flex}
#vv-hoje .d3q .d3v-leque > .d3h-decidir-acoes{grid-column:2;grid-row:3}
#vv-hoje .d3q .d3v-leque > :is(.d3h-vazio,.d3v-estado){grid-column:1 / -1;grid-row:2 / 4}
#vv-hoje .d3q .d3v-leque .d3h-baralho:focus-visible{outline:2px solid var(--d3-acao);outline-offset:4px}
@container leque (max-width:500px){
  #vv-hoje .d3q .d3v-leque .d3h-carta:not([data-pos="0"]) > .d3h-arte{display:none}
}
/* No laranja (Criação e Minhas tarefas): a arte grande em cima, depois o cliente, a peça, a linha de apoio e os botões. */
#vv-hoje .d3q .d3h-decidir.d3v-laranja > .d3h-cab{height:auto;padding:0;justify-content:flex-start;gap:10px}
#vv-hoje .d3q .d3h-decidir.d3v-laranja > .d3h-cab > h3{font:400 var(--d3-fs-apoio)/1.3 var(--vv-texto,Inter,sans-serif);color:var(--d3-escuro-texto)}
#vv-hoje .d3q .d3h-decidir.d3v-laranja .d3h-aux{color:var(--d3-escuro-texto)}
#vv-hoje .d3q .d3h-decidir.d3v-laranja > .d3h-baralho{flex:1 1 auto;display:flex;flex-direction:column;margin:6px 0 0;border-radius:12px}
#vv-hoje .d3q .d3h-decidir.d3v-laranja .d3h-carta:not([data-pos="0"]) > *{display:none}
#vv-hoje .d3q .d3h-decidir.d3v-laranja .d3h-arte{flex:1 1 0;min-height:72px}
#vv-hoje .d3q .d3h-decidir.d3v-laranja .d3h-carta-txt{flex:none;gap:2px;padding-top:10px}
#vv-hoje .d3q .d3h-decidir.d3v-laranja .d3h-carta-txt > b{font-size:17px}
#vv-hoje .d3q .d3h-decidir.d3v-laranja .d3h-carta-cli,#vv-hoje .d3q .d3v-laranja .cliente-carteira{--carteira-texto:var(--d3-escuro-texto);color:var(--d3-escuro-texto);font-weight:400}
#vv-hoje .d3q .d3h-decidir.d3v-laranja .d3h-carta-cli > .d3v-foto,#vv-hoje .d3q .d3h-decidir.d3v-laranja .d3h-pills{display:none}
#vv-hoje .d3q .d3h-decidir.d3v-laranja > .d3h-decidir-acoes{margin-top:10px}
#vv-hoje .d3q .d3h-decidir.d3v-laranja > :is(.d3h-vazio,.d3v-estado){margin-top:auto;padding:0;border:0;text-align:left;align-items:flex-start;color:var(--d3-escuro-texto)}

/* Clientes de olho: três linhas com a foto do perfil, o motivo e o estado. */
#vv-hoje .d3q .d3q-olho-l{display:flex;flex-direction:column;flex:1 1 auto;min-height:0;gap:0;padding:0}
#vv-hoje .d3q .d3q-cli{flex:1 1 0;display:flex;align-items:center;gap:12px;min-height:44px;margin:0;padding:0 16px;border:0;border-top:1px solid var(--d3-divisa);border-radius:0;background:none;color:var(--d3-tinta);text-align:left;cursor:pointer}
#vv-hoje .d3q .d3q-cli:hover{background:var(--d3-veu);box-shadow:none}
#vv-hoje .d3q .d3q-cli > span{display:flex;flex-direction:column;gap:2px;flex:1 1 auto;min-width:0}
#vv-hoje .d3q .d3q-cli b{font:600 var(--d3-fs-texto)/1.25 var(--vv-texto,Inter,sans-serif);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#vv-hoje .d3q .d3q-cli small{font:400 var(--d3-fs-apoio)/1.3 var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#vv-hoje .d3q .d3q-cli > u{flex:none;display:inline-flex;align-items:center;gap:6px;width:auto;height:auto;border-radius:0;background:none;color:var(--d3-pronto);font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);text-decoration:none}
#vv-hoje .d3q .d3q-cli > u::before{content:"";width:8px;height:8px;border-radius:50%;background:currentColor}
#vv-hoje .d3q .d3q-cli.a > u{background:none;color:var(--d3-ambar)}
#vv-hoje .d3q .d3q-cli.r > u{background:none;color:var(--d3-perigo)}

/* Minhas tarefas: filtros em texto (o escolhido ganha fundo), busca em ícone e "Por status"; a linha com a caixa de marcar. */
#vv-hoje .d3q .d3h-filtros{flex:none;gap:2px;padding:0 16px 10px}
#vv-hoje .d3q .d3h-filtros .v2t-ficha{display:inline-flex;align-items:center;gap:6px;height:28px;padding:0 8px;border-radius:var(--d3-r-botao);background:none;color:var(--d3-rotulo);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif)}
#vv-hoje .d3q .d3h-filtros .v2t-ficha:hover{background:var(--d3-veu)}
#vv-hoje .d3q .d3h-filtros .v2t-ficha > b{font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
#vv-hoje .d3q .d3h-filtros .v2t-ficha.r{background:none;color:var(--d3-rotulo)}
#vv-hoje .d3q .d3h-filtros .v2t-ficha.r > b{color:var(--d3-perigo)}
#vv-hoje .d3q .d3h-filtros .v2t-ficha[aria-selected="true"]{background:var(--d3-veu-forte);color:var(--d3-tinta);font-weight:600}
#vv-hoje .d3q .d3h-filtros .v2t-busca{height:28px;border-radius:var(--d3-r-botao);background-color:var(--d3-veu);margin-left:auto}
#vv-hoje .d3q .d3h-filtros > .d3h-btn{margin-left:4px}
#vv-hoje .d3q .d3h-filtros > .d3h-btn[aria-pressed="true"]{background:var(--d3-tinta);color:var(--d3-escuro-texto)}
#vv-hoje .d3q .d3h-cartao .v2-lista.d3h-lista{flex:1 1 auto;min-height:0;padding:0;border-radius:0;background:none;box-shadow:none;overflow-y:auto;scrollbar-width:thin}
#vv-hoje .d3q .d3h-lista > .d3h-vazio{display:flex;flex-direction:column;align-items:center;justify-content:center;flex:1 1 auto;gap:6px;border-top:1px solid var(--d3-divisa);text-align:center;font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}
#vv-hoje .d3q .d3h-lista > .d3h-vazio::before{content:"";width:26px;height:26px;border-radius:7px;background:var(--d3-pronto) url("data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 viewBox=%270 0 24 24%27 fill=%27none%27 stroke=%27white%27 stroke-width=%272.6%27 stroke-linecap=%27round%27 stroke-linejoin=%27round%27%3E%3Cpath d=%27M5 12l4 4 10-10%27/%3E%3C/svg%3E") center / 14px no-repeat}
#vv-hoje .d3q .d3h-lista-pe{flex:none;padding:10px 16px;border-top:1px solid var(--d3-divisa);font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
#vv-hoje .d3q .d3h-tarefas .v2-linha{border-top:1px solid var(--d3-divisa)}
#vv-hoje .d3q .d3h-tarefas .v2-linha[aria-expanded="true"]{background:var(--d3-veu)}
#vv-hoje .d3q .d3h-tarefas .v2t-lin{gap:10px;min-height:38px;padding:5px 16px;box-sizing:border-box}
#vv-hoje .d3q .d3h-tarefas .d3h-q{width:56px}
#vv-hoje .d3q .d3h-tarefas .v2t-cx{width:20px;height:20px;border-radius:6px;background:none;box-shadow:inset 0 0 0 1.5px rgba(31,29,26,.3)}
#vv-hoje .d3q .d3h-tarefas .v2t-cx:hover{box-shadow:inset 0 0 0 1.5px var(--d3-pronto)}
#vv-hoje .d3q .d3h-tarefas .v2t-cx.ok{background:var(--d3-pronto);box-shadow:none}
#vv-hoje .d3q .d3h-tarefas .v2t-nome{flex:1 1 0;color:var(--d3-rotulo)}
#vv-hoje .d3q .d3h-tarefas .v2t-quando{min-width:44px;justify-content:flex-end}
#vv-hoje .d3q .d3h-tarefas .v2t-st{max-width:120px}
#vv-hoje .d3q .d3h-tarefas .v2t-st .vv-demanda-status{border-radius:var(--d3-r-botao)}
#vv-hoje .d3q .d3h-tarefas .v2t-det .focus-brief-btn{display:inline-flex;align-items:center;gap:6px;height:28px;padding:0 10px;border:0;border-radius:var(--d3-r-botao);background:var(--d3-veu);box-shadow:none;color:var(--d3-tinta);font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);text-decoration:none}
#vv-hoje .d3q .d3h-tarefas .v2t-det .focus-brief-btn:hover{background:var(--d3-veu-forte)}
#vv-hoje .d3q .d3h-tarefas .v2t-q{font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);text-decoration:none}
#vv-hoje .d3q .d3h-tarefas .v2t-q.ruim{color:var(--d3-perigo)}
#vv-hoje .d3q .d3h-tarefas .v2t-q.atencao{color:var(--d3-ambar)}
#vv-hoje .d3q .d3h-tarefas .v2t-etapa.agora{font-weight:600}
#vv-hoje .d3q .d3h-tarefas :is(.v2t-grupo,.d3h-grupo-cel){padding:10px 16px 4px;font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);letter-spacing:0;text-transform:none;color:var(--d3-rotulo)}
#vv-hoje .d3q .d3h-tarefas .v2t-det{margin:0 16px 12px 92px}

/* Fila do Danilo (vem pronta do módulo da Criação): a mesma folha dos outros cartões, do tamanho da linha. */
#vv-hoje .d3q .d3h-danilo.d3h-danilo-solta{display:flex;flex-direction:column;min-width:0;min-height:0}
#vv-hoje .d3q .d3h-danilo.d3h-danilo-solta > .vcr-fila.vcr-fila{flex:1 1 auto;min-height:0;border-radius:16px;background:var(--d3-folha);box-shadow:var(--d3-folha-sombra);overflow-y:auto;scrollbar-width:thin}
#vv-hoje .d3q .d3h-danilo .vcr-fila .vcr-editar{height:34px;border-radius:var(--d3-r-botao);background:var(--d3-veu);color:var(--d3-tinta);font-weight:500}
