#vv-hoje .d3q > .d3h-lado{display:flex;flex-direction:column;gap:12px;min-width:0;min-height:0;padding:0;border-radius:0;background:none;color:var(--d3-fume-texto);overflow-y:auto;scrollbar-width:none;
  --d3-tinta:var(--d3-escuro-texto);--d3-texto2:rgba(255,255,255,.86);--d3-apagado:var(--d3-fume-apagado);--d3-rotulo:var(--d3-fume-apagado);--d3-meta:rgba(255,255,255,.4);--d3-linha:transparent;--d3-divisa:transparent;--d3-borda:var(--d3-fume-borda);
  --d3-trilho:var(--d3-fume-veu);--d3-areia:var(--d3-fume-veu);--d3-cartao:var(--d3-fume-veu);--d3-veu:var(--d3-fume-veu);--d3-veu-forte:var(--d3-fume-veu-forte);
  --d3-perigo:var(--d3-perigo-vidro);--d3-pronto:var(--d3-pronto-claro);--d3-ajuste:var(--d3-ajuste-claro);--d3-ambar:var(--d3-ajuste-claro);--d3-info:var(--d3-info-claro);--d3-agente-texto:var(--d3-agente-claro);
  --d3-perigo-veu:rgba(255,156,143,.16);--d3-pronto-veu:rgba(127,216,164,.16);--d3-ajuste-veu:rgba(242,196,109,.16);--d3-info-veu:rgba(157,187,255,.16);--d3-agente-veu:rgba(185,168,255,.16)}
#vv-hoje .d3q > .d3h-lado::-webkit-scrollbar{display:none}
#vv-hoje .d3q > .d3h-lado{-webkit-mask-image:linear-gradient(to bottom,rgba(0,0,0,1) calc(100% - 20px),rgba(0,0,0,0) 100%);mask-image:linear-gradient(to bottom,rgba(0,0,0,1) calc(100% - 20px),rgba(0,0,0,0) 100%);padding-bottom:16px;box-sizing:border-box}
#vv-hoje .d3q > .d3h-lado > *{flex:none}
#vv-hoje .d3q > .d3h-lado > .d3h-cartao,#vv-hoje .d3q > .d3h-lado > .d3h-cartao:only-child{padding:0;border:0;border-radius:0;background:none;box-shadow:none;color:var(--d3-fume-texto);overflow:visible}
#vv-hoje .d3q > .d3h-lado .d3h-cab{height:auto;padding:0 0 6px;align-items:baseline}
#vv-hoje .d3q > .d3h-lado .d3h-cab > h3{font:600 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-texto)}
#vv-hoje .d3q > .d3h-lado .d3h-corpo{display:flex;flex-direction:column;gap:6px;overflow:visible;padding:0}
#vv-hoje .d3q > .d3h-lado :is(.d3h-ag,.d3h-agl,.d3h-zap){margin:0;min-height:40px;padding:4px 10px;box-sizing:border-box;border:0;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu);color:var(--d3-fume-texto)}
#vv-hoje .d3q > .d3h-lado :is(.d3h-ag,.d3h-agl,.d3h-zap,.d3h-apr-lin,.d3h-pes,.d3h-mini,.d3h-zap-cab):hover{background:var(--d3-fume-veu-forte)}
#vv-hoje .d3q > .d3h-lado :is(button,a,summary):focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:1px}
#vv-hoje .d3q > .d3h-lado .d3h-ag > b{flex:0 0 38px;display:inline-flex;align-items:center;gap:8px;font-weight:600;font-variant-numeric:tabular-nums}
