#vv-hoje .d3q > .d3h-lado .d3h-av.ag{background:var(--d3-agente);color:var(--d3-fume-texto)}
#vv-hoje .d3q > .d3h-lado .d3h-vazio{margin:0;padding:10px;border:0;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu);color:var(--d3-fume-apagado)}
#vv-hoje .d3q > .d3h-lado .d3h-link{color:var(--d3-fume-texto)}
#vv-hoje .d3q > .d3h-lado .d3h-mais{align-self:flex-start;padding:2px 0}
#vv-hoje .d3q > .d3h-lado .d3h-pe{padding:6px 0 0}
#vv-hoje .d3q > .d3h-lado .d3h-pill{background:var(--d3-fume-veu);color:var(--d3-fume-texto)}
#vv-hoje .d3q > .d3h-lado .d3h-pill.g{background:var(--d3-pronto-veu);color:var(--d3-pronto)}
#vv-hoje .d3q > .d3h-lado .d3h-pill.r{background:var(--d3-perigo-veu);color:var(--d3-perigo)}
#vv-hoje .d3q > .d3h-lado :is(.d3h-pes-n,.d3h-pes small,.d3h-aux){color:var(--d3-fume-apagado)}
