#vv-hoje .d3q .d3h-mini{appearance:none;display:flex;flex-direction:column;gap:2px;margin:0;border:0;text-align:left;cursor:pointer;padding:8px 10px;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu);color:var(--d3-fume-texto)}
#vv-hoje .d3q .d3h-mini > b{font:600 16px/1.1 var(--vv-titulo,"Inter Tight",Inter,sans-serif)}
#vv-hoje .d3q .d3h-mini > small{font:400 var(--d3-fs-mini)/1.25 var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-apagado)}
#vv-hoje .d3q .d3h-mes{display:flex;flex-direction:column;gap:8px;padding:12px;border-radius:14px;background:var(--d3-fume-escuro);box-shadow:inset 0 0 0 1px rgba(255,255,255,.1)}
