body.ver-agenda #mundo-hud #vv-agenda .vv-evento span{font-size:var(--d3-fs-apoio);color:var(--d3-fume-apagado)}
body.ver-agenda #mundo-hud #vv-agenda .vd-agenda-rotulo{font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-apagado)}
body.ver-agenda #mundo-hud #vv-agenda .vd-agenda-linha > span{font-weight:400;color:var(--d3-fume-apagado)}
body.ver-agenda #mundo-hud #vv-agenda .vd-agenda-linha .vd-chip{border-color:var(--d3-fume-borda);background:none;color:var(--d3-fume-texto)}
body.ver-agenda #mundo-hud #vv-agenda .vd-agenda-linha .vd-chip > span{color:var(--d3-fume-texto);font-weight:400}
body.ver-agenda #mundo-hud #vv-agenda .vv-roteiro{border-radius:var(--d3-r-botao);background:var(--d3-fume-veu);box-shadow:none;color:var(--d3-fume-texto)}
body.ver-agenda #mundo-hud #vv-agenda .vv-dica{color:var(--d3-fume-apagado)}
body.ver-agenda #mundo-hud #vv-agenda .vv-agenda-abrir{font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif)}
body.ver-agenda #mundo-hud #vv-agenda .vv-agenda-abrir:hover{background:var(--d3-fume-painel);color:var(--d3-fume-texto);text-decoration:underline;text-underline-offset:3px}
body.mundo .vv-conversa.vv-conversa .vv-conversa-topo.vv-conversa-topo,body.mundo .vv-conversa.vv-conversa .vv-conversa-form.vv-conversa-form{background:var(--d3-fume-painel);border-color:var(--d3-fume-borda)}
body.mundo .vv-conversa.vv-conversa .vv-conversa-titulo{color:var(--d3-fume-texto)}
body.mundo #mundo-hud .vv-menu-conta button[data-conta-acao="sair"]{border-top-color:var(--d3-fume-borda);background:none}
body.mundo #mundo-hud .vv-menu-conta button[data-conta-acao="sair"] b{border-radius:var(--d3-r-botao);background:var(--d3-fume-veu);box-shadow:none;color:var(--d3-fume-texto);font-weight:500}
