body.mundo #v2j-busca .spotlight-grupo{font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);letter-spacing:0;text-transform:none}
body.mundo #v2j-busca :is(#spotlight-input,.spotlight-campo){border:0;border-radius:var(--d3-r-botao);background:var(--d3-fume-veu);box-shadow:none}
body.mundo #v2j-busca #spotlight-input:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:1px;box-shadow:none}
body.mundo #v2j-busca :is(.v2j-pill,.v2j-pe kbd,.spotlight-escopo button,.spotlight-abas > button,.spotlight-abas button,.spotlight-mais,.spotlight-avatar){border:0;border-radius:var(--d3-r-botao);background:var(--d3-fume-veu);box-shadow:none;color:var(--d3-fume-texto)}
body.mundo #v2j-busca .spotlight-abas button[aria-selected="true"]{background:var(--d3-fume-texto);color:var(--d3-tinta-fixa)}
body.mundo #v2j-busca .v2j-x.spotlight-fechar{border:0;border-radius:var(--d3-r-botao);background:var(--d3-fume-veu);box-shadow:none;color:var(--d3-fume-texto)}
body.mundo #v2j-busca .v2j-x.spotlight-fechar:hover{background:var(--d3-fume-veu-forte)}
body.mundo #v2j-busca .spotlight-linha{border-radius:var(--d3-r-botao);background:none;color:var(--d3-fume-texto)}
body.mundo #v2j-busca .spotlight-linha[aria-selected="true"]{background:var(--d3-fume-veu-forte)}
body.mundo #v2j-busca .spotlight-linha[aria-selected="true"] :is(.spotlight-dica,.spotlight-sub){color:var(--d3-fume-apagado)}
body.mundo #v2j-busca :is(.v2j-cab,.v2j-pe,.spotlight-lista){border-color:var(--d3-fume-borda);background:none}
.vv-tour-raiz .vv-tour-balao{border:0;border-radius:var(--d3-r-ilha);background:var(--d3-fume-painel);box-shadow:inset 0 0 0 1px var(--d3-fume-borda),0 30px 60px -30px rgba(0,0,0,.7);color:var(--d3-fume-texto)}
.vv-tour-raiz .vv-tour-balao :is(h2,h3,h4,p,b,.vv-tour-titulo){color:var(--d3-fume-texto)}
.vv-tour-raiz .vv-tour-balao :is(.vv-tour-quem small,.vv-tour-quem span,.vv-tour-passo,.vv-tour-nao,small){color:var(--d3-fume-apagado)}
.vv-tour-raiz .vv-tour-balao .vv-tour-bico{background:var(--d3-fume-painel)}
.vv-tour-raiz .vv-tour-balao button{border-radius:var(--d3-r-botao)}
.vv-tour-raiz .vv-tour-balao button:not(.vv-tour-principal):not(.vv-tour-prox){border:0;background:var(--d3-fume-veu);box-shadow:none;color:var(--d3-fume-texto)}
.vv-tour-raiz .vv-tour-balao :is(.vv-tour-principal,.vv-tour-prox){border:0;background:var(--d3-fume-texto);color:var(--d3-tinta-fixa)}

/* 11 · PEÇAS DOS MÓDULOS (pranchas V2-M-*). As mesmas da prancha V2-Peças, soltas, para a janela de cada módulo: o cartão
   laranja (.d3m-laranja), o botão no laranja (.d3m-btn.l), a coluna de consulta direto no vidro (.d3m-lado, .d3m-cons,
   .d3m-vlin), a régua de dias (.d3m-regua), a trilha de etapas (.d3m-trilha) e a faixa "De olho" (.d3m-olho). */
.d3m-laranja{position:relative;display:flex;flex-direction:column;align-items:stretch;gap:4px;min-width:0;box-sizing:border-box;padding:16px;border-radius:16px;overflow:hidden;background:var(--d3-laranja);box-shadow:0 18px 34px -20px rgba(194,73,12,.85);color:var(--d3-escuro-texto);font:400 var(--d3-fs-texto)/1.4 var(--vv-texto,Inter,sans-serif)}
.d3m-laranja::before{content:"";position:absolute;right:-70px;top:-90px;width:190px;height:190px;border-radius:50%;background:rgba(255,255,255,.07);pointer-events:none}
.d3m-laranja > *{position:relative;z-index:1}
.d3m-lar-rot{display:flex;align-items:center;gap:8px;font:400 var(--d3-fs-apoio)/1.3 var(--vv-texto,Inter,sans-serif)}
.d3m-laranja .d3m-lar-rot > .d3-acao-av{flex:none;display:grid;place-items:center;width:26px;height:26px;border-radius:50%;background:var(--d3-escuro-texto);color:var(--d3-agente);font:700 var(--d3-fs-mini) var(--vv-texto,Inter,sans-serif)}
.d3m-laranja .d3m-lar-rot > .d3-acao-av::after{content:none}
.d3m-lar-txt{display:flex;flex-direction:column;gap:4px;margin-top:auto;min-width:0}
.d3m-lar-num{font:600 60px/1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.03em;font-variant-numeric:tabular-nums}
.d3m-laranja .d3m-lar-txt > .d3-acao-frase{flex:none;overflow:visible;white-space:normal;font:600 19px/1.25 var(--vv-titulo,"Inter Tight",Inter,sans-serif)}
.d3m-lar-txt > small{font:400 var(--d3-fs-texto)/1.4 var(--vv-texto,Inter,sans-serif)}
.d3m-lar-bts{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}
.d3m-btn{appearance:none;display:inline-flex;align-items:center;justify-content:center;gap:6px;height:34px;margin:0;padding:0 14px;box-sizing:border-box;border:0;border-radius:var(--d3-r-botao);background:var(--d3-tinta);color:var(--d3-escuro-texto);font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);white-space:nowrap;cursor:pointer}
.d3m-btn.l{background:var(--d3-escuro-texto);color:var(--d3-acao-texto)}
.d3m-btn.l:hover{background:rgba(255,255,255,.9)}
.d3m-btn.l.s{background:rgba(255,255,255,.07);box-shadow:inset 0 0 0 1px rgba(255,255,255,.5);color:var(--d3-escuro-texto);font-weight:500}
.d3m-btn.l.s:hover{background:rgba(255,255,255,.18)}
.d3m-btn:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}
.d3m-lado{display:flex;flex-direction:column;gap:12px;min-width:0;color:var(--d3-fume-texto);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif)}
.d3m-cons{display:flex;flex-direction:column;gap:6px;min-width:0}
.d3m-cons-cab{display:flex;justify-content:space-between;align-items:baseline;gap:8px;height:18px}
.d3m-cons-cab > b{font-weight:600}
.d3m-cons-cab > span{font-size:var(--d3-fs-apoio);color:var(--d3-fume-apagado);white-space:nowrap}
.d3m-vlin{appearance:none;display:flex;align-items:center;gap:10px;width:100%;height:36px;margin:0;padding:0 10px;box-sizing:border-box;border:0;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu);color:var(--d3-fume-texto);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);text-align:left;list-style:none;cursor:pointer}
.d3m-vlin::-webkit-details-marker{display:none}
.d3m-vlin:hover{background:var(--d3-fume-veu-forte)}
.d3m-vlin:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:1px}
.d3m-vlin > span:first-child,.d3m-vnome{flex:1 1 auto;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-vlin > span:first-child > b{font-weight:600}
.d3m-vlin > svg{flex:none;width:14px;height:14px;fill:none;stroke:var(--d3-fume-apagado);stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.d3m-vlin > .d3m-vnome{flex:0 0 auto;max-width:96px}
.d3m-vlin > .d3m-pt + .d3m-vnome{flex:1 1 auto;max-width:none}
.d3m-pes{flex:none;display:grid;place-items:center;width:22px;height:22px;border-radius:50%;background:var(--d3-fume-veu-forte);color:var(--d3-fume-texto);font:600 10px var(--vv-texto,Inter,sans-serif);font-style:normal}
.d3m-pt{flex:none;width:7px;height:7px;border-radius:50%;background:var(--d3-fume-apagado)}
.d3m-pt.r{background:var(--d3-perigo-claro)}
.d3m-pt.a{background:var(--d3-ajuste-claro)}
.d3m-vbarra{flex:1 1 auto;min-width:20px;height:4px;border-radius:2px;background:var(--d3-fume-veu-forte);overflow:hidden}
.d3m-vbarra > i{display:block;width:var(--v,0%);height:100%;border-radius:2px;background:var(--d3-mod-vybe-claro)}
.d3m-vbarra.a > i{background:var(--d3-ajuste-claro)}
.d3m-vbarra.r > i{background:var(--d3-perigo-claro)}
.d3m-vn{flex:none;min-width:36px;text-align:right;color:var(--d3-fume-apagado);font-variant-numeric:tabular-nums}
.d3m-vn > b,b.d3m-vn{font-weight:600;color:var(--d3-fume-texto)}
.d3m-vvazio{margin:0;padding:10px;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu);color:var(--d3-fume-apagado);font-size:var(--d3-fs-apoio)}
.d3m-trilha{flex:none;display:inline-flex;gap:3px}
.d3m-trilha > i{width:15px;height:4px;border-radius:2px;background:var(--d3-veu-forte)}
.d3m-trilha > i.ok{background:var(--d3-tinta)}
.d3m-trilha > i.vez{background:var(--d3-acao)}

/* 12 · PRODUÇÃO (Painel de trabalho) NA PRANCHA V2-M-Producao. Vale na vista Semana (as outras vistas seguem como estavam
   até a prancha de cada uma). A janela é vidro fumê; a casa vira uma coluna da altura da janela, com a coluna de consulta
   presa à direita; o cartão do dia é a cabeça (#pv2-semana), a lista (a semana ativa) e o pé "De olho" (#pv2-pe). */
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] #mundo-moldura{border-radius:20px;background:var(--d3-fume);box-shadow:inset 0 0 0 1px var(--d3-fume-borda),0 30px 60px -40px rgba(0,0,0,.6)}
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] .container.pv2-casa{position:relative;display:flex;flex-direction:column;box-sizing:border-box;width:auto;max-width:none;height:100%;min-height:540px;margin:0;padding:16px 348px 16px 16px;color:var(--d3-tinta)}
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] .container.pv2-casa > *{flex:none;min-width:0;margin-left:-14px;margin-right:318px}
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] #pv2-painel{display:block;margin:2px -14px 16px -14px;padding:0;background:none;box-shadow:none}
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] #pv2-painel > .d3m-topo{display:flex;align-items:center;gap:8px;min-height:48px;margin:0;padding:0 104px 0 0;color:var(--d3-fume-texto)}
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] #pv2-lado{position:absolute;right:16px;top:72px;bottom:-4px;width:316px;overflow-y:auto;scrollbar-width:none}
#pv2-painel .d3m-tit{display:flex;flex-direction:column;gap:3px;min-width:0;margin-right:auto}
#pv2-painel .d3m-troca{position:relative}
#pv2-painel .d3m-troca > summary{display:inline-flex;align-items:center;gap:6px;list-style:none;cursor:pointer;border-radius:var(--d3-r-botao)}
#pv2-painel .d3m-troca > summary::-webkit-details-marker{display:none}
#pv2-painel .d3m-troca > summary > h2{margin:0;font:600 24px/1.1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.02em}
#pv2-painel .d3m-troca > summary > svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
#pv2-painel .d3m-troca > summary:focus-visible{outline:2px solid currentColor;outline-offset:3px}
#pv2-painel .d3m-troca > .pv2-pop{left:0;right:auto;min-width:220px}
#pv2-painel .d3m-troca > .pv2-pop > [aria-current]{font-weight:600}
#pv2-painel .d3m-modos{position:relative}
#pv2-painel .d3m-modos > .pv2-pop{left:0;right:0;top:auto;bottom:calc(100% + 6px)}
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] #pv2-painel .d3m-troca > summary > h2{color:var(--d3-fume-texto)}
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] #pv2-painel .d3p-data{font:400 var(--d3-fs-texto)/1.2 var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-apagado);white-space:nowrap}
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] #pv2-painel #pv2-vistas{flex:none;gap:2px;height:36px;padding:3px;box-sizing:border-box;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu);box-shadow:none}
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] #pv2-painel #pv2-vistas > button{height:30px;padding:0 12px;border-radius:var(--d3-r-botao);background:none;box-shadow:none;color:var(--d3-fume-texto);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif)}
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] #pv2-painel #pv2-vistas > button[aria-checked="true"]{background:var(--d3-fume-texto);color:var(--d3-tinta);font-weight:600}
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] #pv2-painel :is(#pv2-vistas > button,.pv2-busca,.d3p-novo):focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] #pv2-painel .pv2-busca{flex:0 0 34px;width:34px;max-width:34px;min-width:0;height:34px;padding:0 0 0 32px;box-sizing:border-box;border:0;border-radius:var(--d3-r-botao);background-color:var(--d3-fume-veu-forte);background-image:url("data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 viewBox=%270 0 24 24%27 fill=%27none%27 stroke=%27white%27 stroke-width=%272%27 stroke-linecap=%27round%27%3E%3Ccircle cx=%2711%27 cy=%2711%27 r=%276%27/%3E%3Cpath d=%27m20 20-4.5-4.5%27/%3E%3C/svg%3E");background-repeat:no-repeat;background-position:9px center;background-size:16px;box-shadow:none;color:var(--d3-fume-texto);cursor:pointer;transition:max-width .2s,flex-basis .2s}
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] #pv2-painel .pv2-busca::placeholder{color:transparent}
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] #pv2-painel .pv2-busca:focus{flex-basis:200px;width:200px;max-width:200px;padding-right:10px;cursor:text}
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] #pv2-painel .pv2-busca:focus::placeholder{color:var(--d3-fume-apagado)}
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] #pv2-painel .d3p-novo{flex:none;height:34px;padding:0 14px;border-radius:var(--d3-r-botao);background:var(--d3-fume-texto);box-shadow:none;color:var(--d3-tinta);font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif)}
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] #pv2-painel .d3p-novo > svg{stroke:var(--d3-tinta)}
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] #pv2-alto{display:block;margin:0;padding:0}
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] #pv2-alto > .d3m-laranja{min-height:244px;margin:0}
/* Fora da vista Semana, a coluna de consulta, a régua e o pé saem (as outras vistas seguem como estavam). */
body.mundo:not([data-pv2-vista="semana"]) :is(#pv2-lado,#pv2-regua,#pv2-pe){display:none}
body.mundo:not([data-pv2-vista="semana"]) #pv2-painel > .d3m-topo{display:flex;flex-wrap:wrap;align-items:center;gap:8px}

/* A régua da semana. */
.d3m-regua{display:grid;grid-template-columns:28px repeat(7,minmax(0,1fr)) 28px;gap:8px;height:72px;margin-top:0;margin-bottom:12px}
.d3m-regua:has(> .d3m-regua-hoje){grid-template-columns:28px repeat(7,minmax(0,1fr)) 28px auto}
.d3m-regua :is(.d3m-dia,.d3m-regua-seta,.d3m-regua-hoje){appearance:none;margin:0;border:0;border-radius:12px;background:var(--d3-fume-veu);color:var(--d3-fume-texto);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);cursor:pointer}
.d3m-regua :is(.d3m-dia,.d3m-regua-seta,.d3m-regua-hoje):hover{background:var(--d3-fume-veu-forte)}
.d3m-regua :is(.d3m-dia,.d3m-regua-seta,.d3m-regua-hoje):focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}
.d3m-regua-seta{display:grid;place-items:center;padding:0}
.d3m-regua-seta:disabled{opacity:.4;cursor:default}
.d3m-regua-seta > svg{width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.d3m-regua-hoje{padding:0 12px;font-weight:500}
.d3m-dia{display:flex;flex-direction:column;justify-content:space-between;min-width:0;padding:10px 12px;text-align:left}
.d3m-dia > span{display:flex;align-items:center;justify-content:space-between;gap:8px;min-width:0}
.d3m-dia > span:first-child > b{font-weight:500;white-space:nowrap}
.d3m-dia > span:first-child > small{font-size:var(--d3-fs-apoio);color:var(--d3-fume-apagado)}
.d3m-dia-n{flex:none;font:600 var(--d3-fs-destaque) var(--vv-texto,Inter,sans-serif);font-variant-numeric:tabular-nums}
.d3m-dia-n > small{font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-apagado)}
.d3m-dia-b{flex:1 1 auto;display:block;height:4px;border-radius:2px;background:var(--d3-fume-veu-forte);overflow:hidden}
.d3m-dia-b > i{display:block;width:var(--v,0%);height:100%;border-radius:2px;background:var(--d3-mod-vybe-claro)}
.d3m-dia.d3m-on,.d3m-dia.d3m-on:hover{background:var(--d3-folha);box-shadow:var(--d3-folha-sombra);color:var(--d3-tinta)}
.d3m-dia.d3m-on > span:first-child > b{font-weight:600}
.d3m-dia.d3m-on :is(small,.d3m-dia-n > small){color:var(--d3-rotulo)}
.d3m-dia.d3m-on .d3m-dia-b{background:var(--d3-veu-forte)}
.d3m-dia.d3m-on .d3m-dia-b > i{background:var(--d3-pronto)}

/* O cartão do dia: cabeça, lista e pé, três partes da mesma folha. */
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] #pv2-semana{display:flex;align-items:center;gap:10px;min-height:44px;margin-top:0;margin-bottom:0;padding:0 16px;box-sizing:border-box;border-radius:16px 16px 0 0;background:var(--d3-folha);color:var(--d3-tinta)}
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] #pv2-semana > h3{margin:0 auto 0 0;font:600 14px/1.25 var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);white-space:nowrap}
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] #pv2-semana > h3 > span{font-weight:400;color:var(--d3-rotulo)}
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] #pv2-semana :is(#pv2-modo,#pv2-abas){gap:2px;padding:0;border-radius:0;background:none;box-shadow:none}
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] #pv2-semana :is(#pv2-modo,#pv2-abas) > button,body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] #pv2-semana #pv2-filtros-rot{height:28px;padding:0 10px;border:0;border-radius:var(--d3-r-botao);background:none;box-shadow:none;color:var(--d3-rotulo);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif)}
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] #pv2-semana :is(#pv2-modo,#pv2-abas) > button:hover,body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] #pv2-semana #pv2-filtros-rot:hover{background:var(--d3-veu)}
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] #pv2-semana :is(#pv2-modo,#pv2-abas) > button[aria-checked="true"]{background:var(--d3-veu-forte);color:var(--d3-tinta);font-weight:600}
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] #pv2-semana #pv2-abas > i{display:none}
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] #pv2-semana #pv2-filtros-rot{color:var(--d3-tinta);font-weight:500}
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] #pv2-semana #pv2-filtros-rot.tem{background:var(--d3-tinta);color:var(--d3-escuro-texto)}
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] #pv2-semana #pv2-filtros-menu{position:relative;padding-left:10px;border-left:1px solid var(--d3-veu-forte)}
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] .container.pv2-casa > .week-panel.active{flex:1 1 0;min-height:0;margin-top:0;margin-bottom:0;padding:0;overflow-y:auto;scrollbar-width:thin;border-radius:0;background:var(--d3-folha);box-shadow:none}
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] #pv2-pe{display:flex;align-items:center;min-height:44px;margin-top:0;margin-bottom:-40px;padding:0 16px;box-sizing:border-box;border-top:1px solid var(--d3-divisa);border-radius:0 0 16px 16px;background:var(--d3-folha);box-shadow:var(--d3-folha-sombra);overflow:hidden}
#pv2-pe .d3m-olho-rot{flex:none;margin-right:14px;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
#pv2-pe #pv2-chips{display:flex;align-items:center;gap:0;min-width:0}
#pv2-pe #pv2-chips > .pv2-chip{appearance:none;flex:none;display:inline-flex;flex-direction:row-reverse;align-items:baseline;gap:5px;height:20px;margin:0;padding:0 12px;border:0;border-left:1px solid var(--d3-veu-forte);border-radius:0;background:none;box-shadow:none;color:var(--d3-rotulo);font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);white-space:nowrap;cursor:pointer}
#pv2-pe #pv2-chips > .pv2-chip:first-child{padding-left:0;border-left:0}
#pv2-pe #pv2-chips > .pv2-chip > b{font:600 14px var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);font-variant-numeric:tabular-nums}
#pv2-pe #pv2-chips > .pv2-chip:nth-child(-n+2) > b{color:var(--d3-perigo)}
#pv2-pe #pv2-chips > .pv2-chip:nth-child(3) > b{color:var(--d3-ambar)}
#pv2-pe #pv2-chips > .pv2-chip:hover,#pv2-pe #pv2-chips > .pv2-chip[aria-pressed="true"]{color:var(--d3-tinta)}
#pv2-pe #pv2-chips > .pv2-chip[aria-pressed="true"]{text-decoration:underline;text-underline-offset:3px}
#pv2-pe #pv2-chips > .pv2-chip:focus-visible{outline:2px solid var(--d3-acao);outline-offset:2px}
/* O que mais aparecer na casa (a fila do que pede ação, a de hoje, a seleção em lote) fica em folha clara. */
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] .container.pv2-casa > :not(#pv2-painel):not(#pv2-regua):not(#pv2-semana):not(.week-panel):not(#pv2-pe):not(#pv2-reserva){margin-top:0;margin-bottom:12px;border-radius:16px;background:var(--d3-folha);max-height:46%;overflow-y:auto}

/* "Por dia": um dia só, em linhas. Hora, foto, cliente e peça, a trilha das etapas, o status e quem faz. */
.pv2.pv2-dias.d3m-um-dia:is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6){display:block;padding:0;gap:0}
.pv2.pv2-dias.d3m-um-dia:is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) > .pv2-col{position:relative;display:block;min-width:0;margin:0;padding:0;border:0;border-radius:0;background:none;box-shadow:none}
.pv2.pv2-dias.d3m-um-dia:is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) .d3m-colunas{display:flex;align-items:center;gap:10px;height:24px;padding:0 16px;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
.pv2.pv2-dias.d3m-um-dia:is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) .d3m-colunas > span:nth-child(1){flex:0 0 44px}
.pv2.pv2-dias.d3m-um-dia:is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) .d3m-colunas > span:nth-child(2){flex:0 0 28px}
.pv2.pv2-dias.d3m-um-dia:is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) .d3m-colunas > span:nth-child(3){flex:1 1 auto}
.pv2.pv2-dias.d3m-um-dia:is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) .d3m-colunas > span:nth-child(4){flex:0 0 96px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pv2.pv2-dias.d3m-um-dia:is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) .d3m-colunas > span:nth-child(5){flex:0 0 150px}
.pv2.pv2-dias.d3m-um-dia:is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) .d3m-colunas > span:nth-child(6){flex:0 0 112px}
.pv2.pv2-dias.d3m-um-dia:is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) .pv2-cab{position:absolute;right:16px;top:0;height:24px;display:flex;align-items:center;margin:0;padding:0;border:0;background:none}
.pv2.pv2-dias.d3m-um-dia:is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) .pv2-cab > :not(.pv2-dia-menu){display:none}
.pv2.pv2-dias.d3m-um-dia:is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) .pv2-cab > .pv2-dia-menu > summary{font-size:0;list-style:none;cursor:pointer;border-radius:4px}
.pv2.pv2-dias.d3m-um-dia:is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) .pv2-cab > .pv2-dia-menu > summary::after{content:"Ações do dia";font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}
.pv2.pv2-dias.d3m-um-dia:is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) .pv2-cab > .pv2-dia-menu > .pv2-pop{right:0;left:auto}
.pv2.pv2-dias.d3m-um-dia:is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) .d3p-linhas{display:block;padding:0}
.pv2.pv2-dias.d3m-um-dia:is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) .pv2-pc{margin:0;padding:0;border:0;border-top:1px solid var(--d3-divisa);border-radius:0;background:none;box-shadow:none}
.pv2.pv2-dias.d3m-um-dia:is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) .pv2-pc:hover,.pv2.pv2-dias.d3m-um-dia:is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) .pv2-pc[aria-expanded="true"]{background:var(--d3-veu)}
.pv2.pv2-dias.d3m-um-dia:is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) .pv2-pc.feita .pv2-t{text-decoration:line-through;color:var(--d3-rotulo)}
.pv2.pv2-dias.d3m-um-dia:is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) .pv2-pc-lin{display:flex;align-items:center;gap:10px;min-height:44px;margin:0;padding:0 16px;box-sizing:border-box}
.pv2.pv2-dias.d3m-um-dia:is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) .pv2-pc-lin:focus-visible{outline:2px solid var(--d3-acao);outline-offset:-2px}
.pv2.pv2-dias.d3m-um-dia:is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) .d3m-hora{flex:0 0 44px;font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);font-variant-numeric:tabular-nums}
.pv2.pv2-dias.d3m-um-dia:is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) .d3m-hora > .d3p-hora{padding:0;border-radius:0;background:none;color:inherit;font:inherit}
.pv2.pv2-dias.d3m-um-dia:is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) .pv2-t{flex:1 1 auto;min-width:0;margin:0;font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pv2.pv2-dias.d3m-um-dia:is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) .pv2-t .pv2-cli{font-weight:600}
.pv2.pv2-dias.d3m-um-dia:is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) .pv2-t .pv2-cli::before{content:none}
.pv2.pv2-dias.d3m-um-dia:is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) .d3m-trilha{flex:0 0 96px}
.pv2.pv2-dias.d3m-um-dia:is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) .pv2-r{flex:0 0 150px;display:flex;align-items:center;gap:8px;min-width:0;margin:0}
.pv2.pv2-dias.d3m-um-dia:is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) .pv2-avs{flex:0 0 112px;display:flex;justify-content:flex-end}
.pv2.pv2-dias.d3m-um-dia:is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) .d3p-quando{font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif)}
.pv2.pv2-dias.d3m-um-dia:is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) .pv2-nada{margin:0;padding:28px 16px;border-top:1px solid var(--d3-divisa);text-align:center;font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}
.pv2.pv2-dias.d3m-um-dia:is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) .pv2-det{padding:0 16px 12px 108px}
/* Na Grade e no Por cliente, a linha continua compacta: sem a foto e sem a trilha. */
.pv2.pv2-dias:not(.d3m-um-dia):is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) :is(.d3m-trilha,.pv2-pc-lin > .d3v-foto){display:none}
.pv2.pv2-dias:not(.d3m-um-dia):is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6) .d3m-hora:empty{display:none}
body.mundo.mundo-modulo[data-modo="gestor"][data-pv2-vista="semana"] .pv2.pv2-dias:not(.d3m-um-dia):is(#pv2-dias-s1,#pv2-dias-s2,#pv2-dias-s3,#pv2-dias-s4,#pv2-dias-s5,#pv2-dias-s6){padding:12px 16px}

/* Telas menores: uma coluna; a coluna de consulta desce para o fim e a janela rola. */
