#grupos-board.d3m-a-v2 .d3m-a-data > input.grupo-data-campo{position:absolute;inset:0;width:100%;height:100%;min-width:0;margin:0;padding:0;border:0;opacity:0;cursor:pointer}
#grupos-board.d3m-a-v2 .d3m-a-g-tab td.d3m-a-g-quem{text-align:right}
#grupos-board.d3m-a-v2 .d3m-a-g-quem .pv2-av{display:inline-grid;place-items:center;width:24px;height:24px;margin:0;padding:0;border:0;border-radius:50%;background:var(--d3-veu-forte);box-shadow:none;color:var(--d3-tinta);font:600 10px var(--vv-texto,Inter,sans-serif);cursor:pointer}
#grupos-board.d3m-a-v2 .d3m-a-g-quem .pv2-av.sd{background:none;box-shadow:inset 0 0 0 1px var(--d3-rotulo);color:var(--d3-rotulo);font-size:0}
#grupos-board.d3m-a-v2 .d3m-a-g-quem .pv2-av.sd::before{content:"+";font:400 14px/1 var(--vv-texto,Inter,sans-serif)}
#grupos-board.d3m-a-v2 .d3m-a-g-quem .pv2-av.mais{margin-left:-6px;font-size:9px}
#grupos-board.d3m-a-v2 .d3m-a-g-tab td.grupo-cadastro{color:var(--d3-rotulo);font-size:var(--d3-fs-apoio)}
#grupos-board.d3m-a-v2 .d3m-a-cab .grupo-menu-btn{appearance:none;display:grid;place-items:center;width:28px;height:28px;margin:0;padding:0;border:0;border-radius:var(--d3-r-botao);background:none;color:var(--d3-tinta);cursor:pointer}
#grupos-board.d3m-a-v2 .d3m-a-cab .grupo-menu-btn:hover{background:var(--d3-veu)}
#grupos-board.d3m-a-v2 .d3m-a-cab .grupo-adicionar > svg{width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round}
.d3m-a-pe .d3v-btn.txt{color:var(--d3-tinta);font-size:var(--d3-fs-apoio)}
/* Na coluna de consulta: a lista de grupos (o escolhido em folha clara), a busca e a nota. */
.d3m-a-grupos{display:flex;flex-direction:column;gap:6px}
