.d3m-a-busca > svg{flex:none;width:14px;height:14px;fill:none;stroke:var(--d3-fume-texto);stroke-width:2;stroke-linecap:round}
#pv2-lado-v .d3m-a-busca > input#busca-cliente-conteudos{flex:1 1 auto;min-width:0;height:38px;margin:0;padding:0;border:0;outline:0;background:none;box-shadow:none;color:var(--d3-fume-texto);-webkit-text-fill-color:var(--d3-fume-texto);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif)}
#pv2-lado-v .d3m-a-busca > input#busca-cliente-conteudos::placeholder{color:var(--d3-fume-apagado);-webkit-text-fill-color:var(--d3-fume-apagado)}
.d3m-a-nota-v > p{margin:0;font:400 var(--d3-fs-texto)/1.5 var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-apagado);-webkit-text-fill-color:var(--d3-fume-apagado)}

/* 5 · EQUIPE. A carga por pessoa em linhas de 52 (avatar, nome e papel, a barra por etapa, as prontas e o total) e as peças
   por formato em colunas. As cores da barra são as do que cada etapa é: verde pronto, laranja em produção, azul esperando
   captação e cinza a fazer. */
#panel-team.d3m-a-v2 > :not(.d3m-a-folha){display:none}
body.mundo.mundo-modulo[data-modo="gestor"]:is([data-pv2-vista="mes"],[data-pv2-vista="grupos"],[data-pv2-vista="equipe"]) .container.pv2-casa > #panel-team.d3m-a-v2 > #pv2-eq-carga{flex:1 1 0}
body.mundo.mundo-modulo[data-modo="gestor"]:is([data-pv2-vista="mes"],[data-pv2-vista="grupos"],[data-pv2-vista="equipe"]) .container.pv2-casa > #panel-team.d3m-a-v2 > #pv2-eq-formato{flex:0 0 clamp(200px,42%,332px)}
.d3m-a-eq-leg{flex:none;display:inline-flex;align-items:center;gap:12px;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);white-space:nowrap}
.d3m-a-eq-leg > span{display:inline-flex;align-items:center;gap:6px}
.d3m-a-eq-leg i,.d3m-a-eq-b > i{background:var(--d3-meta)}
.d3m-a-eq-leg i{width:9px;height:9px;border-radius:3px}
:is(.d3m-a-eq-leg,.d3m-a-eq-b) i.g{background:var(--d3-mod-vybe)}
:is(.d3m-a-eq-leg,.d3m-a-eq-b) i.p{background:var(--d3m-a-producao)}
:is(.d3m-a-eq-leg,.d3m-a-eq-b) i.c{background:var(--d3m-a-captacao)}
.d3m-a-eq-lista{display:flex;flex-direction:column;min-height:0;overflow-y:auto;scrollbar-width:thin}
.d3m-a-eq-lin{appearance:none;flex:none;display:flex;align-items:center;gap:10px;width:100%;height:52px;margin:0;padding:0 16px;box-sizing:border-box;border:0;border-top:1px solid var(--d3-divisa);border-radius:0;background:none;color:var(--d3-tinta);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
.d3m-a-eq-lin:hover{background:var(--d3-veu)}
.d3m-a-eq-lin:focus-visible{outline:2px solid var(--d3-acao);outline-offset:-2px}
.d3m-a-eq-av{flex:none;display:grid;place-items:center;width:24px;height:24px;border-radius:50%;background:var(--d3-veu-forte);color:var(--d3-tinta);font:600 10px var(--vv-texto,Inter,sans-serif);font-style:normal}
.d3m-a-eq-av.sd{background:none;box-shadow:inset 0 0 0 1px var(--d3-rotulo);color:var(--d3-rotulo);font:400 14px/1 var(--vv-texto,Inter,sans-serif)}
.d3m-a-eq-nome{flex:1 1 0;min-width:0;color:var(--d3-rotulo);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-a-eq-nome > b{font-weight:600;color:var(--d3-tinta)}
.d3m-a-eq-b{flex:0 0 300px;display:flex;gap:2px;height:8px;border-radius:4px;overflow:hidden}
.d3m-a-eq-b > i{flex:1 1 0;min-width:2px;border-radius:2px}
.d3m-a-eq-pr{flex:0 0 90px;text-align:right;font-size:var(--d3-fs-apoio);color:var(--d3-tinta);white-space:nowrap;font-variant-numeric:tabular-nums}
.d3m-a-eq-n{flex:0 0 48px;text-align:right;font:600 var(--d3-fs-destaque) var(--vv-texto,Inter,sans-serif);font-variant-numeric:tabular-nums}
.d3m-a-eq-n.r{color:var(--d3-perigo)}
.d3m-a-eq-cols{flex:1 1 0;min-height:120px;display:flex;align-items:flex-end;gap:16px;padding:8px 20px 14px;box-sizing:border-box;overflow:hidden}
.d3m-a-eq-col{flex:1 1 0;min-width:0;display:flex;flex-direction:column;justify-content:flex-end;gap:4px;height:100%}
.d3m-a-eq-col > b{padding-left:1px;font:600 var(--d3-fs-titulo)/1 var(--vv-texto,Inter,sans-serif);font-variant-numeric:tabular-nums}
.d3m-a-eq-col > i{flex:none;display:block;height:calc((100% - 46px) * var(--k,0));min-height:4px;border-radius:6px 6px 2px 2px;background:var(--d3-texto2)}
.d3m-a-eq-col > span{flex:none;display:flex;justify-content:space-between;gap:6px;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);white-space:nowrap}
.d3m-a-eq-col > span > span{min-width:0;overflow:hidden;text-overflow:ellipsis}
.d3m-a-eq-col > span > small{flex:none;font-size:inherit;color:var(--d3-rotulo);font-variant-numeric:tabular-nums}

/* 9 · TELAS MENORES. Sem largura para as duas colunas, a coluna de consulta desce para depois da folha e a janela rola. */
