  body.mundo.mundo-modulo[data-modo="gestor"]:is([data-pv2-vista="mes"],[data-pv2-vista="grupos"],[data-pv2-vista="equipe"],[data-pv2-vista="feed"]) .container.pv2-casa{height:auto;min-height:0;padding:16px}
  body.mundo.mundo-modulo[data-modo="gestor"]:is([data-pv2-vista="mes"],[data-pv2-vista="grupos"],[data-pv2-vista="equipe"],[data-pv2-vista="feed"]) .container.pv2-casa > *{margin-left:-14px;margin-right:-14px}
  body.mundo.mundo-modulo[data-modo="gestor"]:is([data-pv2-vista="mes"],[data-pv2-vista="grupos"],[data-pv2-vista="equipe"],[data-pv2-vista="feed"]) #pv2-painel{display:flex;flex-direction:column;gap:12px;margin:2px -14px 12px}
  body.mundo.mundo-modulo[data-modo="gestor"]:is([data-pv2-vista="mes"],[data-pv2-vista="grupos"],[data-pv2-vista="equipe"],[data-pv2-vista="feed"]) #pv2-painel > .d3m-topo{flex-wrap:wrap;padding:0}
  body.mundo.mundo-modulo[data-modo="gestor"]:is([data-pv2-vista="mes"],[data-pv2-vista="grupos"],[data-pv2-vista="equipe"]) :is(#pv2-painel,#pv2-lado,#pv2-lado-v){display:contents}
  body.mundo.mundo-modulo[data-modo="gestor"]:is([data-pv2-vista="mes"],[data-pv2-vista="grupos"],[data-pv2-vista="equipe"]) #pv2-painel > .d3m-topo{order:0;margin:2px -14px 12px}
  body.mundo.mundo-modulo[data-modo="gestor"]:is([data-pv2-vista="mes"],[data-pv2-vista="grupos"],[data-pv2-vista="equipe"]) #pv2-lado-v > .d3m-laranja{order:1;margin:0 -14px 12px}
  body.mundo.mundo-modulo[data-modo="gestor"]:is([data-pv2-vista="mes"],[data-pv2-vista="grupos"],[data-pv2-vista="equipe"]) .container.pv2-casa > *{order:2}
  body.mundo.mundo-modulo[data-modo="gestor"]:is([data-pv2-vista="mes"],[data-pv2-vista="grupos"],[data-pv2-vista="equipe"]) #pv2-lado-v > .d3m-cons{order:3;margin:12px -14px 0}
  body.mundo.mundo-modulo[data-modo="gestor"]:is([data-pv2-vista="mes"],[data-pv2-vista="grupos"],[data-pv2-vista="equipe"]) .container.pv2-casa > .d3m-a-v2 > .d3m-a-folha,body.mundo.mundo-modulo[data-modo="gestor"]:is([data-pv2-vista="mes"],[data-pv2-vista="grupos"],[data-pv2-vista="equipe"]) .container.pv2-casa > .d3m-a-v2 > .d3m-a-folha:last-child{flex:none;order:2;margin:0 -14px 12px}
  .d3m-a-lado-v .d3m-laranja{min-height:0}
  body.mundo.mundo-modulo[data-modo="gestor"]:is([data-pv2-vista="mes"],[data-pv2-vista="grupos"],[data-pv2-vista="equipe"]) .container.pv2-casa > #panel-team.d3m-a-v2 > :is(#pv2-eq-carga,#pv2-eq-formato){flex:none}
  .d3m-a-eq-cols{height:200px}
  .d3m-a-g-rola{flex:none;max-height:70vh}
  .d3m-a-mes-grade{flex:none;grid-template-rows:repeat(var(--linhas,6),72px)}
}
@media (max-width:900px){
  body.mundo.mundo-modulo[data-modo="gestor"]:is([data-pv2-vista="mes"],[data-pv2-vista="grupos"],[data-pv2-vista="equipe"],[data-pv2-vista="feed"]) #pv2-painel .d3m-tit{flex:1 1 100%;padding-right:52px}
  body.mundo.mundo-modulo[data-modo="gestor"]:is([data-pv2-vista="mes"],[data-pv2-vista="grupos"],[data-pv2-vista="equipe"],[data-pv2-vista="feed"]) #pv2-painel.pv2 .d3p-data{white-space:normal}
  body.mundo.mundo-modulo[data-modo="gestor"]:is([data-pv2-vista="mes"],[data-pv2-vista="grupos"],[data-pv2-vista="equipe"],[data-pv2-vista="feed"]) #pv2-painel.pv2 #pv2-vistas{flex:1 1 100%;overflow-x:auto;scrollbar-width:none}
