#vv-conteudo.vc.vc.vc.d3m-a-v2 .d3v-btn.vidro{color:var(--d3-fume-texto)}
#vv-conteudo.vc.vc.vc.d3m-a-v2 .d3v-btn:disabled{color:var(--d3-meta)}
#vv-conteudo.vc.vc.vc.d3m-a-v2 .d3m-vlin{color:var(--d3-fume-texto)}
#vv-conteudo.vc.vc.vc.d3m-a-v2 .d3m-a-filtro{color:var(--d3-tinta)}
#vv-conteudo.vc.vc.vc.d3m-a-v2 .d3m-a-ap-topo{flex:none;display:flex;flex-wrap:nowrap;align-items:center;gap:8px;min-height:48px;margin:0;padding:0}
#vv-conteudo.vc.vc.vc.d3m-a-v2 .d3m-a-ap-tit{flex:1 1 auto;min-width:0;display:flex;flex-direction:column;gap:3px}
#vv-conteudo.vc.vc.vc.d3m-a-v2 .d3m-a-ap-tit > h2{margin:0;font:600 24px/1.1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.02em;color:var(--d3-fume-texto);-webkit-text-fill-color:var(--d3-fume-texto)}
#vv-conteudo.vc.vc.vc.d3m-a-v2 .d3m-a-ap-linha{font:400 var(--d3-fs-texto)/1.2 var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-apagado);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
/* As abas são escolha única (role="radio" com aria-checked): a folha antiga pinta com força [role="tab"], aria-selected e a
   lista de abas (.vb-abas); com rádio, nada disso casa. */
#vv-conteudo.vc.vc.vc.d3m-a-v2 .d3m-a-vseg{--ds-on-fundo:var(--d3-fume-texto);--ds-on-texto:var(--d3-tinta);--ds-on-borda:transparent;flex:none;display:inline-flex;gap:2px;height:36px;padding:3px;box-sizing:border-box;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu);box-shadow:none}
#vv-conteudo.vc.vc.vc.d3m-a-v2 .d3m-a-vseg > button{--ds-on-fundo:var(--d3-fume-texto);--ds-on-texto:var(--d3-tinta);--ds-on-borda:transparent;height:30px;padding:0 12px;border-radius:var(--d3-r-botao);background:none;box-shadow:none;color:var(--d3-fume-texto);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif)}
