#vv-conteudo.vc.vc.vc.d3m-a-v2 :is(.d3m-a-vseg > button,.d3m-ico,.d3m-a-ap-item,.d3m-vlin,.d3m-a-ap-link):focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px;box-shadow:none}
#vv-conteudo.vc.vc.vc.d3m-a-v2 .d3m-a-ap-mes{display:inline-flex;align-items:center;gap:8px;padding:0;background:none}
#vv-conteudo.vc.vc.vc.d3m-a-v2 .d3m-ico{flex:none;width:34px;height:34px;padding:0;border:0;border-radius:var(--d3-r-botao);background:var(--d3-fume-veu-forte);box-shadow:none;color:var(--d3-fume-texto)}
