#vv-conteudo.vc.vc.vc.d3m-a-v2 .d3m-ico > svg{width:16px;height:16px}
#vv-conteudo.vc.vc.vc.d3m-a-v2 .vc-ajuda{flex:none;margin:0;padding:12px 16px;border:0;border-radius:16px;background:var(--d3-folha);color:var(--d3-tinta)}
#vv-conteudo.vc.vc.vc.d3m-a-v2 .vc-corpo.d3m-a-ap-corpo{flex:1 1 0;min-height:0;margin:0;padding:0;overflow:visible}
#vv-conteudo.vc.vc.vc.d3m-a-v2 .d3m-lado :is(.d3m-cons-cab > b){font-weight:600;color:var(--d3-fume-texto);-webkit-text-fill-color:var(--d3-fume-texto)}
#vv-conteudo.vc.vc.vc.d3m-a-v2 .d3m-lado .d3m-cons-cab > span{color:var(--d3-fume-apagado);-webkit-text-fill-color:var(--d3-fume-apagado)}
#vv-conteudo.vc.vc.vc.d3m-a-v2 .d3m-laranja{padding:16px;border-radius:16px;min-height:0}
#vv-conteudo.vc.vc.vc.d3m-a-v2 .d3m-laranja :is(.d3m-lar-rot,.d3m-lar-num,.d3-acao-frase,.d3m-lar-txt > small){color:var(--d3-escuro-texto);-webkit-text-fill-color:var(--d3-escuro-texto)}
#vv-conteudo.vc.vc.vc.d3m-a-v2 .d3m-laranja .d3m-lar-rot > .d3-acao-av{-webkit-text-fill-color:var(--d3-agente)}
#vv-conteudo.vc.vc.vc.d3m-a-v2 .d3m-laranja .d3m-lar-txt{margin-top:14px}
#vv-conteudo.vc.vc.vc.d3m-a-v2 .d3m-laranja .d3m-lar-txt > .d3-acao-frase{font-size:24px;line-height:1.15}
#vv-conteudo.vc.vc.vc.d3m-a-v2 .d3m-laranja .d3m-lar-num + .d3-acao-frase{font-size:19px;line-height:1.25}
#vv-conteudo.vc.vc.vc.d3m-a-v2 .d3m-laranja .d3m-btn{flex:1 1 0}
#vv-conteudo.vc.vc.vc.d3m-a-v2 .d3m-a-ap-selo{align-self:flex-start;display:inline-flex;align-items:center;height:20px;padding:0 8px;border-radius:999px;background:var(--d3-folha);color:var(--d3-tinta);-webkit-text-fill-color:var(--d3-tinta);font:500 var(--d3-fs-mini) var(--vv-texto,Inter,sans-serif);white-space:nowrap}
#vv-conteudo.vc.vc.vc.d3m-a-v2 .d3m-a-ap-link{appearance:none;margin:0;padding:0 2px;border:0;border-radius:4px;background:none;color:var(--d3-fume-texto);-webkit-text-fill-color:var(--d3-fume-texto);font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);cursor:pointer}
#vv-conteudo.vc.vc.vc.d3m-a-v2 .d3m-a-ap-link:hover{text-decoration:underline;text-underline-offset:3px}

/* 2 · PARA APROVAR: três colunas. */
