/* ===== padrao-v2/zm-a-4-direcao.css ===== */
/* MÓDULOS V2 · GRUPO A · DIREÇÃO DE ARTE (prancha V2-M-Direcao-Arte, aprovada pelo Paulo em 16/11/2026). O módulo aberto
   pelo menu lateral, na mesma janela de vidro do Hoje: a folha "Esperam o seu parecer" com as artes e "Pediram ajuste" ao
   lado; a folha do time em linhas com o pé "De olho"; e, direto no vidro, o laranja com a peça da vez, a Fila do Danilo e
   os atalhos. As peças .d3m-a-* comuns (folha, cabeça, pé, filtro) vêm de zm-a-1-producao.css. */
#vv-hoje .d3m-a-da .d3q-main > .d3m-a-da-parecer{flex:none}
#vv-hoje .d3m-a-da .d3q-main > .d3m-a-da-time{flex:1 1 0;min-height:0}
#vv-hoje .d3m-a-da .d3m-a-cab > h3{margin:0 auto 0 0;font:600 14px/1.25 var(--vv-texto,Inter,sans-serif);letter-spacing:0;color:var(--d3-tinta);-webkit-text-fill-color:var(--d3-tinta)}
#vv-hoje .d3m-a-da .d3m-a-cab > h3 > span + span{font-weight:400;color:var(--d3-rotulo);-webkit-text-fill-color:var(--d3-rotulo)}
#vv-hoje .d3m-a-da .d3m-a-filtro{color:var(--d3-tinta);font-weight:500}
/* Esperam o seu parecer: as artes (a imagem de 150 × 200, o nome, o cliente, o head e a espera) e a caixa dos ajustes. */
#vv-hoje .d3m-a-da-linha{display:grid;grid-template-columns:minmax(0,1.9fr) minmax(0,1fr);gap:12px;padding:0 16px 16px}
#vv-hoje .d3m-a-da-artes{display:flex;gap:16px;min-width:0}
#vv-hoje .d3m-a-da-artes > .d3v-estado{min-height:200px}
#vv-hoje .d3m-a-da .d3m-a-da-arte{appearance:none;flex:1 1 0;min-width:0;display:flex;align-items:stretch;gap:14px;margin:0;padding:0;border:0;border-radius:12px;background:none;box-shadow:none;color:var(--d3-tinta);font:400 var(--d3-fs-apoio)/1.4 var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
#vv-hoje .d3m-a-da .d3m-a-da-arte:hover{background:var(--d3-veu)}
#vv-hoje .d3m-a-da .d3m-a-da-arte:focus-visible{outline:2px solid var(--d3-acao);outline-offset:2px}
#vv-hoje .d3m-a-da-img{position:relative;flex:none;display:block;width:150px;height:200px;border-radius:12px;overflow:hidden;background:var(--d3-fume-painel)}
#vv-hoje .d3m-a-da-img.vazia{background:linear-gradient(170deg,var(--d3-fume-painel) 20%,var(--d3-acao-texto) 120%)}
#vv-hoje .d3m-a-da-img > img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;display:block}
#vv-hoje .d3m-a-da-img > :is(i,.vc-previa-selo){position:absolute;right:8px;bottom:8px;font-style:normal;color:var(--d3-fume-texto)}
#vv-hoje .d3m-a-da-selo{position:absolute;left:8px;top:8px;z-index:1;display:inline-flex;align-items:center;height:20px;padding:0 8px;border-radius:999px;background:var(--d3-folha);color:var(--d3-tinta);font:500 var(--d3-fs-mini) var(--vv-texto,Inter,sans-serif)}
#vv-hoje .d3m-a-da-txt{flex:1 1 auto;min-width:0;display:flex;flex-direction:column;gap:5px;padding:12px 4px 4px 0}
#vv-hoje .d3m-a-da-txt > b{font:600 var(--d3-fs-destaque)/1.25 var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);-webkit-text-fill-color:var(--d3-tinta);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
#vv-hoje .d3m-a-da-cli{display:flex;align-items:center;gap:8px;min-width:0;font-size:var(--d3-fs-texto);color:var(--d3-tinta)}
#vv-hoje .d3m-a-da-cli > :first-child{flex:none;width:22px;height:22px;border-radius:6px;font-size:9px}
#vv-hoje .d3m-a-da-cli > span:last-child{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#vv-hoje .d3m-a-da-txt > small{font-size:var(--d3-fs-apoio);color:var(--d3-rotulo);-webkit-text-fill-color:var(--d3-rotulo)}
#vv-hoje .d3m-a-da-txt > small.r{color:var(--d3-perigo);-webkit-text-fill-color:var(--d3-perigo)}
#vv-hoje .d3m-a-da-txt > small.t{color:var(--d3-tinta);-webkit-text-fill-color:var(--d3-tinta)}
#vv-hoje .d3m-a-da-txt > .d3m-a-da-arq{margin-top:auto}
#vv-hoje .d3m-a-da .d3m-a-da-mais{appearance:none;flex:none;align-self:center;height:34px;margin:0;padding:0 10px;border:0;border-radius:var(--d3-r-botao);background:var(--d3-veu);color:var(--d3-tinta);font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);cursor:pointer}
#vv-hoje .d3m-a-da-ajuste{display:flex;flex-direction:column;gap:6px;min-width:0;min-height:200px;padding:14px;box-sizing:border-box;border-radius:12px;background:var(--d3-veu);font:400 var(--d3-fs-apoio)/1.5 var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
#vv-hoje .d3m-a-da-ajuste > b{font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);-webkit-text-fill-color:var(--d3-tinta)}
#vv-hoje .d3m-a-da-ajuste > p{margin:0;color:var(--d3-rotulo);-webkit-text-fill-color:var(--d3-rotulo)}
#vv-hoje .d3m-a-da-ajustes{min-height:0;overflow-y:auto;scrollbar-width:thin}
#vv-hoje .d3m-a-da .d3m-a-da-link{appearance:none;align-self:flex-start;margin:auto 0 0;padding:0 2px;border:0;border-radius:4px;background:none;color:var(--d3-tinta);-webkit-text-fill-color:var(--d3-tinta);font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);cursor:pointer}
#vv-hoje .d3m-a-da .d3m-a-da-link:hover{text-decoration:underline;text-underline-offset:3px}
/* O time: pessoa, os pontos contra o limite (a barra), o que venceu, o que é de hoje e as abertas. */
#vv-hoje .d3m-a-da-cols,#vv-hoje .d3m-a-da .d3m-a-da-pes{display:grid;grid-template-columns:28px minmax(120px,1fr) minmax(200px,1.1fr) 70px 56px 64px;align-items:center;gap:10px;padding:0 16px;box-sizing:border-box}
#vv-hoje .d3m-a-da-cols{flex:none;height:26px;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
#vv-hoje .d3m-a-da-cols > span:first-child{grid-column:1/3;padding-left:38px}
#vv-hoje .d3m-a-da-cols > span:nth-child(n+3){text-align:right}
#vv-hoje .d3m-a-da-lista{flex:1 1 0;min-height:0;overflow-y:auto;scrollbar-width:thin}
#vv-hoje .d3m-a-da .d3m-a-da-pes{appearance:none;width:100%;height:46px;margin:0;border:0;border-top:1px solid var(--d3-divisa);border-radius:0;background:none;box-shadow:none;color:var(--d3-tinta);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
#vv-hoje .d3m-a-da .d3m-a-da-pes:hover{background:var(--d3-veu)}
#vv-hoje .d3m-a-da .d3m-a-da-pes:focus-visible{outline:2px solid var(--d3-acao);outline-offset:-2px}
#vv-hoje .d3m-a-da-av{display:grid;place-items:center;width:24px;height:24px;border-radius:50%;background:var(--d3-veu-forte);color:var(--d3-tinta);font:600 10px var(--vv-texto,Inter,sans-serif);font-style:normal}
#vv-hoje .d3m-a-da-nome{min-width:0;color:var(--d3-rotulo);-webkit-text-fill-color:var(--d3-rotulo);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#vv-hoje .d3m-a-da-nome > b{font-weight:600;color:var(--d3-tinta);-webkit-text-fill-color:var(--d3-tinta)}
#vv-hoje .d3m-a-da-carga{display:flex;align-items:center;gap:12px;min-width:0;font-size:var(--d3-fs-apoio);color:var(--d3-rotulo);white-space:nowrap;font-variant-numeric:tabular-nums}
#vv-hoje .d3m-a-da-carga > span{flex:0 0 62px}
#vv-hoje .d3m-a-da-carga b{font-weight:600;color:var(--d3-tinta)}
#vv-hoje .d3m-a-da-b{flex:1 1 auto;display:block;height:4px;border-radius:2px;background:var(--d3-veu-forte);overflow:hidden}
#vv-hoje .d3m-a-da-b > i{display:block;width:var(--v,0%);height:100%;border-radius:2px;background:var(--d3-mod-vybe)}
#vv-hoje .d3m-a-da-b.a > i{background:var(--d3m-a-producao)}
#vv-hoje .d3m-a-da-b.r > i{background:var(--d3-perigo)}
#vv-hoje .d3m-a-da-n{text-align:right;font-variant-numeric:tabular-nums}
#vv-hoje .d3m-a-da-n.r{font-weight:600;color:var(--d3-perigo)}
#vv-hoje .d3m-a-da .d3m-a-da-olho{appearance:none;flex:none;display:inline-flex;align-items:baseline;gap:5px;height:20px;margin:0;padding:0 12px;border:0;border-left:1px solid var(--d3-veu-forte);border-radius:0;background:none;box-shadow:none;color:var(--d3-rotulo);-webkit-text-fill-color:var(--d3-rotulo);font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);white-space:nowrap}
#vv-hoje .d3m-a-da button.d3m-a-da-olho{cursor:pointer}
#vv-hoje .d3m-a-da button.d3m-a-da-olho:hover{color:var(--d3-tinta);-webkit-text-fill-color:var(--d3-tinta)}
#vv-hoje .d3m-a-da-pe > span:first-child + .d3m-a-da-olho{padding-left:0;border-left:0}
#vv-hoje .d3m-a-da-olho > b{font:600 14px var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);-webkit-text-fill-color:var(--d3-tinta);font-variant-numeric:tabular-nums}
#vv-hoje .d3m-a-da-olho > b.r{color:var(--d3-perigo);-webkit-text-fill-color:var(--d3-perigo)}
#vv-hoje .d3m-a-da-olho > b.a{color:var(--d3-ambar);-webkit-text-fill-color:var(--d3-ambar)}
/* A coluna de consulta: o laranja, a Fila do Danilo e os atalhos. */
#vv-hoje .d3m-a-da-lado{gap:12px;min-height:0;padding-top:62px;overflow-y:auto;scrollbar-width:none}
#vv-hoje .d3m-a-da-lado .d3m-cons-cab > b{font-weight:600;color:var(--d3-fume-texto);-webkit-text-fill-color:var(--d3-fume-texto)}
#vv-hoje .d3m-a-da-lado .d3m-cons-cab > span{color:var(--d3-fume-apagado);-webkit-text-fill-color:var(--d3-fume-apagado)}
#vv-hoje .d3m-a-da-nota{margin:0;font:400 var(--d3-fs-texto)/1.5 var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-apagado);-webkit-text-fill-color:var(--d3-fume-apagado)}
#vv-hoje .d3m-a-da-lado .d3m-vlin{color:var(--d3-fume-texto)}
#vv-hoje .d3m-a-da-lado .d3m-vlin > span:first-child{color:var(--d3-fume-apagado);-webkit-text-fill-color:var(--d3-fume-apagado)}
#vv-hoje .d3m-a-da-lado .d3m-vlin > span:first-child > b{font-weight:600;color:var(--d3-fume-texto);-webkit-text-fill-color:var(--d3-fume-texto)}
#vv-hoje .d3m-a-da-lado .d3m-vlin > svg{flex:none;width:14px;height:14px;fill:none;stroke:var(--d3-fume-apagado);stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
#vv-hoje .d3m-a-da-lado > .d3h-danilo.d3m-a-da-fila{flex:none;max-height:260px;overflow-y:auto;scrollbar-width:none;border-radius:16px;background:var(--d3-folha);box-shadow:var(--d3-folha-sombra);color:var(--d3-tinta)}
#vv-hoje .d3m-a-da-lado > *{flex:none}
/* Telas baixas (1366 × 768): o laranja e a fila um degrau menores, para a coluna caber sem rolar. */
@media (max-height:800px){
  #vv-hoje .d3m-a-da-lado .d3v-lar-num{font-size:40px}
  #vv-hoje .d3m-a-da-lado > .d3h-danilo.d3m-a-da-fila{max-height:132px}
  #vv-hoje .d3m-a-da-img{height:168px}
  #vv-hoje .d3m-a-da-ajuste,#vv-hoje .d3m-a-da-artes > .d3v-estado{min-height:168px}
}

/* Telas menores: uma coluna; as artes e os ajustes empilham e a tabela do time rola de lado dentro da folha. */
@media (max-width:1180px){
  #vv-hoje .d3m-a-da .d3q-main > .d3m-a-da-time{flex:none}
  #vv-hoje .d3m-a-da-lista{flex:none;overflow:visible}
  #vv-hoje .d3m-a-da-lado{padding-top:0;overflow:visible}
}
@media (max-width:760px){
  #vv-hoje .d3m-a-da-linha{grid-template-columns:minmax(0,1fr)}
  #vv-hoje .d3m-a-da-artes{flex-direction:column}
  #vv-hoje .d3m-a-da-img{width:96px;height:128px}
  #vv-hoje .d3m-a-da-ajuste{min-height:0}
  #vv-hoje .d3m-a-da-cols{display:none}
  #vv-hoje .d3m-a-da .d3m-a-da-pes{grid-template-columns:28px minmax(0,1fr) 44px 44px;grid-template-rows:auto auto;height:auto;padding:8px 14px;gap:4px 10px}
  #vv-hoje .d3m-a-da-carga{grid-column:2/5;grid-row:2}
  #vv-hoje .d3m-a-da-pes > .d3m-a-da-n:nth-of-type(3){display:none}
  #vv-hoje .d3m-a-da-pe{flex-wrap:wrap;gap:4px 0;padding:8px 14px}
}

/* ===== padrao-v2/zm-b-clientes.css ===== */
/* CLIENTES NA DIREÇÃO V2 (pranchas V2-M-Clientes, V2-M-Clientes-Fichas, V2-M-Clientes-Cerebro e V2-M-Clientes-Celular,
   aprovadas pelo Paulo em 16/11/2026). Fragmento do grupo B (Clientes, ficha do cliente, Onboarding e Reuniões).
   A janela é vidro fumê; o alto fica no vidro (título que troca de tela, frase da carteira, Lista/Fichas/Cérebro, busca,
   Mais e Novo cliente); a folha clara traz a lista com a pior nota primeiro e o pé "De olho"; a coluna de consulta fica
   direto no vidro (cartão laranja, a carteira, por head e Abrir como). Peças locais levam o prefixo cv2- (e d3m-b- quando
   são candidatas a peça comum); as comuns (d3m-laranja, d3m-btn, d3m-lado, d3m-cons, d3m-vlin, d3m-ico, d3v-*) vêm de z-direcao.css. */

/* 1 · A janela e o esqueleto. O corpo da página é quem rola nos módulos; aqui a casa ocupa a altura da janela e só a
   lista rola por dentro. data-cv2 diz o que está na tela (lista ou ficha), posto por numerosDaListaDeClientes. */
body.mundo.mundo-modulo[data-modo="clientes"][data-cv2="lista"] #mundo-moldura{border-radius:20px;background:var(--d3-fume);box-shadow:inset 0 0 0 1px var(--d3-fume-borda),0 30px 60px -40px rgba(0,0,0,.6)}
body.mundo.mundo-modulo[data-modo="clientes"][data-cv2="lista"] #painel-clientes{box-sizing:border-box;height:calc(100% + 4px);margin:0 -16px 0 -2px;background:none;box-shadow:none}
body.mundo.mundo-modulo[data-modo="clientes"][data-cv2="lista"] #painel-clientes > .container{display:flex;flex-direction:column;gap:16px;box-sizing:border-box;width:auto;max-width:none;height:100%;min-height:480px;margin:0;color:var(--d3-tinta)}
/* A folha de antes prende o espaçamento da casa (22px 30px 36px, forçado): as duas peças voltam para a borda de 16 px da janela por margem. */
body.mundo.mundo-modulo[data-modo="clientes"][data-cv2="lista"] #painel-clientes #clientes-hero.cv2-topo{order:0;margin:-14px -30px 0}
body.mundo.mundo-modulo[data-modo="clientes"][data-cv2="lista"] #painel-clientes #clientes-corpo.cv2-corpo{order:1;margin:0 -30px -36px}
#painel-clientes #panel-clientes-lista.cv2-folha{order:0;gap:0}
#painel-clientes #clientes-hero.cv2-topo h2{font:600 24px/1.1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.02em}
#painel-clientes #clientes-hero.cv2-topo #clientes-frase{display:block}
#painel-clientes .cv2-topo{flex:none;display:flex;align-items:center;gap:8px;min-height:48px;margin:0;padding:0 96px 0 0;color:var(--d3-fume-texto)}
#painel-clientes .cv2-topo[hidden]{display:none}
#painel-clientes .cv2-topo > .d3m-tit{display:flex;flex-direction:column;gap:3px;min-width:0;margin-right:auto}
#painel-clientes .cv2-troca{appearance:none;display:inline-flex;align-items:center;gap:6px;align-self:flex-start;margin:0;padding:0;border:0;border-radius:var(--d3-r-botao);background:none;color:var(--d3-fume-texto);cursor:pointer}
#painel-clientes .cv2-troca > h2{margin:0;font:600 24px/1.1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.02em;white-space:nowrap;-webkit-text-fill-color:var(--d3-fume-texto)}
#painel-clientes .cv2-troca > svg{flex:none;width:16px;height:16px;fill:none;stroke:var(--d3-fume-apagado);stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
#painel-clientes .cv2-troca:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:3px}
#painel-clientes .cv2-sub{margin:0;font:400 var(--d3-fs-texto)/1.2 var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-apagado);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#painel-clientes .cv2-acoes{display:contents}
#painel-clientes .cv2-seg{order:1;flex:none;display:inline-flex;gap:2px;height:36px;padding:3px;box-sizing:border-box;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu)}
#painel-clientes .cv2-seg > button{appearance:none;height:30px;margin:0;padding:0 12px;border:0;border-radius:var(--d3-r-botao);background:none;color:var(--d3-fume-texto);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);white-space:nowrap;cursor:pointer}
#painel-clientes .cv2-seg > button:hover{background:var(--d3-fume-veu)}
#painel-clientes .cv2-seg > button[aria-checked="true"]{background:var(--d3-fume-texto);color:var(--d3-tinta);font-weight:600}
#painel-clientes .cv2-seg > button:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}
#painel-clientes .cv2-busca{order:2;flex:none;display:flex;margin:0}
#painel-clientes .cv2-busca.aberta > .d3m-ico,#painel-clientes .cv2-busca:not(.aberta) > input{display:none}
#painel-clientes .cv2-busca > input{width:200px;height:34px;margin:0;padding:0 10px;box-sizing:border-box;font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif)}
#painel-clientes .cv2-busca > input:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}
#painel-clientes .cv2-busca[hidden]{display:none}
#painel-clientes .cv2-topo > .cv2-acoes > .d3m-ico{order:3}
#painel-clientes .cv2-novo{order:4;appearance:none;flex:none;display:inline-flex;align-items:center;justify-content:center;gap:6px;height:34px;margin:0;padding:0 14px;box-sizing:border-box;border:0;border-radius:var(--d3-r-botao);background:var(--d3-fume-texto);color:var(--d3-tinta);font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);white-space:nowrap;cursor:pointer}
#painel-clientes .cv2-novo > svg{flex:none;width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round}
#painel-clientes .cv2-novo:hover{background:var(--d3-folha)}
#painel-clientes .cv2-novo:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}

#painel-clientes .cv2-corpo{flex:1 1 0;min-height:0;display:grid;grid-template-columns:minmax(0,1fr) 316px;gap:16px}
#painel-clientes .cv2-folha{display:flex;flex-direction:column;min-width:0;min-height:0;box-sizing:border-box;border-radius:var(--d3-r-ilha);overflow:hidden;background:var(--d3-folha);box-shadow:var(--d3-folha-sombra);color:var(--d3-tinta);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif)}
#painel-clientes .cv2-cab{flex:none;display:flex;align-items:center;justify-content:space-between;gap:10px;min-height:44px;padding:0 16px;box-sizing:border-box}
#painel-clientes .cv2-cab > h3{margin:0;min-width:0;font:600 14px/1.25 var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#painel-clientes .cv2-cab > h3 > span{font-weight:400;color:var(--d3-rotulo)}
#painel-clientes .cv2-filtros{flex:none;display:inline-flex;align-items:center;gap:10px;margin-left:auto}
#painel-clientes .cv2-filtros[hidden]{display:none}
#painel-clientes .cv2-chips{display:inline-flex;gap:2px}
#painel-clientes .cv2-risco{width:1px;height:16px;background:var(--d3-veu-forte)}
#painel-clientes .cv2-chip{appearance:none;display:inline-flex;align-items:center;gap:5px;height:26px;max-width:220px;margin:0;padding:0 9px;border:0;border-radius:7px;background:none;color:var(--d3-tinta);font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;cursor:pointer}
#painel-clientes .cv2-chip > span{color:var(--d3-rotulo);font-weight:400}
#painel-clientes .cv2-chip:hover{background:var(--d3-veu)}
#painel-clientes .cv2-chip:is([aria-checked="true"],[data-ligado="true"]){background:var(--d3-veu-forte);font-weight:600}
#painel-clientes .cv2-chip:focus-visible{outline:2px solid var(--d3-acao);outline-offset:1px}
#painel-clientes .cv2-folha > #grid-clientes-lista{flex:1 1 0;min-height:0;margin:0;padding:0;overflow:hidden}

/* 2 · A lista: rótulo do grupo, foto, cliente e segmento, head, a nota com a barra, o que está em aberto, a próxima
   reunião e o cadastro. A linha abre no lugar (.v2-abre) com o porquê da nota e os dois botões. */
#painel-clientes .cv2-tabela{display:flex;flex-direction:column;height:100%;min-height:0}
#painel-clientes .cv2-th{flex:none;display:flex;align-items:center;gap:10px;height:24px;padding:0 16px;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
#painel-clientes .cv2-th-b{appearance:none;display:inline-flex;align-items:center;gap:4px;min-width:0;margin:0;padding:0;border:0;border-radius:4px;background:none;color:inherit;font:inherit;text-align:left;cursor:pointer}
#painel-clientes .cv2-th-b:hover,#painel-clientes .cv2-th-b:not([aria-sort="none"]){color:var(--d3-tinta)}
#painel-clientes .cv2-th-b > i{font-style:normal}
#painel-clientes .cv2-th-b:focus-visible{outline:2px solid var(--d3-acao);outline-offset:2px}
#painel-clientes .cv2-linhas{flex:1 1 0;min-height:0;overflow-y:auto;scrollbar-width:thin}
#painel-clientes .cv2-linha{border-top:1px solid var(--d3-divisa)}
#painel-clientes .cv2-linha[aria-expanded="false"] > .v2-mais{visibility:hidden;transition:grid-template-rows .28s cubic-bezier(.22,1,.36,1),visibility 0s .28s}
#painel-clientes .cv2-tr{display:flex;align-items:center;gap:10px;height:37px;padding:0 16px;box-sizing:border-box;cursor:pointer}
#painel-clientes .cv2-tr:hover,#painel-clientes .cv2-linha[aria-expanded="true"] > .cv2-tr,#painel-clientes .cv2-linha.marcada > .cv2-tr{background:var(--d3-veu)}
#painel-clientes .cv2-grupo{flex:0 0 52px;font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-ambar);white-space:nowrap}
#painel-clientes .cv2-grupo.r{color:var(--d3-perigo)}
#painel-clientes .cv2-th-foto{flex:0 0 28px}
#painel-clientes :is(.cv2-nome,.cv2-h-cliente){flex:1 1 0;min-width:0}
#painel-clientes .cv2-nome{margin:0;font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#painel-clientes .cv2-nome > b{font-weight:600;color:var(--d3-tinta)}
#painel-clientes .cv2-nome > span{color:var(--d3-rotulo)}
#painel-clientes :is(.cv2-hd,.cv2-h-head){flex:0 0 104px;min-width:0}
#painel-clientes .cv2-hd{display:inline-flex;align-items:center;gap:6px;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}
#painel-clientes .cv2-hd > span{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#painel-clientes .cv2-pes{flex:none;display:grid;place-items:center;width:22px;height:22px;border-radius:50%;background:var(--d3-veu);color:var(--d3-tinta);font:600 10px var(--vv-texto,Inter,sans-serif);font-style:normal}
#painel-clientes .cv2-apagado{color:var(--d3-rotulo)}
#painel-clientes :is(.cv2-tr > .cv2-sa,.cv2-h-saude){flex:0 0 112px}
#painel-clientes .cv2-sa{display:inline-flex;align-items:center;gap:8px;color:var(--d3-tinta);font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif)}
#painel-clientes .cv2-sa > b{flex:0 0 20px;font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);font-variant-numeric:tabular-nums;color:var(--cv2-tom,var(--d3-tinta))}
#painel-clientes .cv2-sa.r{--cv2-tom:var(--d3-perigo)}
#painel-clientes .cv2-sa.a{--cv2-tom:var(--d3-ambar)}
#painel-clientes .cv2-sa.g{--cv2-tom:var(--d3-pronto)}
#painel-clientes .cv2-barra{flex:none;display:block;width:72px;height:4px;border-radius:2px;background:var(--d3-veu-forte);overflow:hidden}
#painel-clientes .cv2-barra > i{display:block;width:var(--v,0%);height:100%;border-radius:2px;background:var(--cv2-tom,var(--d3-tinta))}
#painel-clientes :is(.cv2-ab,.cv2-h-abertos){flex:0 0 150px;min-width:0}
#painel-clientes .cv2-ab{font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#painel-clientes .cv2-ruim{font-weight:400;color:var(--d3-perigo)}
#painel-clientes :is(.cv2-re,.cv2-h-reuniao){flex:0 0 96px;min-width:0}
#painel-clientes .cv2-re{font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);white-space:nowrap;overflow:hidden}
#painel-clientes .cv2-re.sem{color:var(--d3-ambar)}
#painel-clientes .cv2-re.cli-editavel{border-radius:4px;cursor:text}
#painel-clientes .cv2-re.cli-editavel:hover{background:var(--d3-veu)}
#painel-clientes .cv2-re > input{width:100%;height:26px;box-sizing:border-box;font:inherit}
#painel-clientes :is(.cv2-cd,.cv2-h-cadastro){flex:0 0 64px}
#painel-clientes .cv2-cd{display:inline-flex;align-items:center;gap:6px;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);font-variant-numeric:tabular-nums;white-space:nowrap}
#painel-clientes .cv2-cd.cheio{color:var(--d3-pronto)}
#painel-clientes .cv2-anel{flex:none;width:14px;height:14px}
#painel-clientes .cv2-anel > circle{fill:none;stroke:var(--d3-veu-forte);stroke-width:2.4}
#painel-clientes .cv2-anel > circle.v{stroke:var(--d3-rotulo);stroke-linecap:round}
#painel-clientes .cv2-anel.cheio > circle.v{stroke:var(--d3-pronto)}
#painel-clientes .cv2-extra{flex:0 0 104px;min-width:0;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#painel-clientes .cv2-th > .cv2-extra{color:inherit}
#painel-clientes .cv2-link{appearance:none;margin:0;padding:0;border:0;background:none;color:var(--d3-tinta);font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);text-decoration:underline;text-underline-offset:3px;cursor:pointer}
#painel-clientes :is(.cv2-vai,.cv2-th-vai){flex:0 0 14px}
#painel-clientes .cv2-vai{appearance:none;display:grid;place-items:center;height:24px;margin:0;padding:0;border:0;border-radius:4px;background:none;color:var(--d3-rotulo);cursor:pointer}
#painel-clientes .cv2-vai > svg{width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round;transition:transform .2s}
#painel-clientes .cv2-vai[aria-expanded="true"] > svg{transform:rotate(90deg)}
#painel-clientes .cv2-vai:focus-visible{outline:2px solid var(--d3-acao);outline-offset:2px}
#painel-clientes .cv2-det{display:flex;align-items:flex-end;gap:8px;padding:4px 16px 14px 116px}
#painel-clientes .cv2-det-texto{flex:1 1 auto;min-width:0;display:flex;flex-direction:column;gap:4px}
#painel-clientes .cv2-det-texto > p{margin:0;font:400 var(--d3-fs-apoio)/1.45 var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
#painel-clientes .cv2-det-texto > p > b{font-weight:600;color:var(--d3-tinta)}
#painel-clientes .cv2-vazio{gap:10px;min-height:180px}
/* A foto do cliente: a do Instagram ou as iniciais sobre a cor dele. O matiz (--h) vem do nome; a cor é conta, não hex. */
#painel-clientes .cv2-foto{background:linear-gradient(135deg,hsl(var(--h,28) 42% 16%),hsl(var(--h,28) 42% 31%));color:var(--d3-escuro-texto);font:600 var(--d3-fs-mini) var(--vv-texto,Inter,sans-serif)}
#painel-clientes .cv2-foto.g{width:52px;height:52px;border-radius:12px;font-size:var(--d3-fs-titulo)}
/* O pé "De olho": quatro contas da carteira; o clique recorta a lista. */
#painel-clientes .cv2-pe{flex:none;display:flex;align-items:center;min-height:44px;padding:0 16px;box-sizing:border-box;border-top:1px solid var(--d3-divisa);overflow:hidden}
#painel-clientes .cv2-pe[hidden]{display:none}
#painel-clientes .cv2-pe > .d3m-olho-rot{flex:none;margin-right:2px;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
#painel-clientes .cv2-olho{appearance:none;flex:none;display:inline-flex;align-items:baseline;gap:5px;height:20px;margin:0;padding:0 12px;border:0;border-left:1px solid var(--d3-veu-forte);border-radius:0;background:none;color:var(--d3-rotulo);font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);white-space:nowrap;cursor:pointer}
#painel-clientes .d3m-olho-rot + .cv2-olho{border-left:0}
#painel-clientes .cv2-olho > b{font:600 14px var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);font-variant-numeric:tabular-nums}
#painel-clientes .cv2-olho.r > b{color:var(--d3-perigo)}
#painel-clientes .cv2-olho.a > b{color:var(--d3-ambar)}
#painel-clientes .cv2-olho > small{font:inherit;color:inherit}
#painel-clientes .cv2-olho:hover,#painel-clientes .cv2-olho[aria-checked="true"]{color:var(--d3-tinta)}
#painel-clientes .cv2-olho[aria-checked="true"] > small{text-decoration:underline;text-underline-offset:3px}
#painel-clientes .cv2-olho:focus-visible{outline:2px solid var(--d3-acao);outline-offset:2px}

/* 3 · As fichas: cinco por linha, separadas por divisória fina (sem cartão dentro de cartão). */
#painel-clientes .cv2-fichas{height:100%;min-height:0;box-sizing:border-box;display:grid;grid-template-columns:repeat(5,minmax(0,1fr));align-content:start;overflow-y:auto;scrollbar-width:thin;border-top:1px solid var(--d3-divisa)}
#painel-clientes .cv2-ficha{appearance:none;display:flex;flex-direction:column;align-items:stretch;gap:4px;min-width:0;min-height:206px;margin:0;padding:16px;box-sizing:border-box;border:0;border-right:1px solid var(--d3-divisa);border-bottom:1px solid var(--d3-divisa);border-radius:0;background:none;box-shadow:none;color:var(--d3-tinta);font:400 var(--d3-fs-apoio)/1.3 var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
#painel-clientes .cv2-ficha:hover{background:var(--d3-veu)}
#painel-clientes .cv2-ficha:focus-visible{outline:2px solid var(--d3-acao);outline-offset:-2px}
#painel-clientes .cv2-ficha-alto{display:flex;align-items:flex-start;justify-content:space-between;gap:8px;margin-bottom:10px}
#painel-clientes .cv2-ficha-alto > .cv2-sa{flex-direction:column;align-items:flex-end;gap:6px}
#painel-clientes .cv2-ficha-alto > .cv2-sa > b{flex:none;font:600 20px/1 var(--vv-titulo,"Inter Tight",Inter,sans-serif)}
#painel-clientes .cv2-ficha-alto > .cv2-sa > .cv2-barra{width:44px}
#painel-clientes .cv2-ficha-nome{font:600 14px/1.3 var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);-webkit-text-fill-color:var(--d3-tinta);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#painel-clientes .cv2-ficha-seg{color:var(--d3-rotulo);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#painel-clientes .cv2-ficha-ab{margin-top:auto;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#painel-clientes .cv2-ficha > :is(span,b){flex:0 0 auto}
#painel-clientes .cv2-ficha > .cv2-hd{color:var(--d3-rotulo)}
#painel-clientes .cv2-ficha > .cv2-hd > .cv2-pes{width:18px;height:18px;font-size:9px}

/* 4 · A coluna de consulta. */
#painel-clientes .cv2-lado{min-height:0;overflow-y:auto;scrollbar-width:none}
#painel-clientes #clientes-aviso.cv2-aviso{order:0;display:block;margin:0;padding:0;border:0;background:none;box-shadow:none}
#painel-clientes #clientes-aviso.cv2-aviso[hidden],#painel-clientes .cv2-consulta[hidden]{display:none}
#painel-clientes .cv2-consulta{order:1;display:flex;flex-direction:column;gap:12px}
#painel-clientes .cv2-laranja{min-height:252px;margin:0;padding:16px;border-radius:var(--d3-r-ilha)}
#painel-clientes .cv2-laranja .d3m-lar-txt > small,#painel-clientes .cv2-laranja .d3m-lar-num{color:var(--d3-escuro-texto);-webkit-text-fill-color:var(--d3-escuro-texto)}
#painel-clientes .cv2-laranja .d3m-lar-bts{flex-wrap:nowrap}
#painel-clientes .cv2-abrir{flex:0 1 auto;min-width:0}
#painel-clientes .cv2-abrir > span{min-width:0;overflow:hidden;text-overflow:ellipsis}
#painel-clientes .cv2-laranja .d3m-btn.l.s{flex:none}
#painel-clientes .cv2-laranja .d3m-btn[aria-checked="true"]{background:var(--d3-fume-veu-forte)}
#painel-clientes .cv2-lado :is(.d3m-cons-cab > b,.d3m-vlin b,.d3m-lar-num,.d3-acao-frase,.d3m-lar-rot,.cv2-carteira b){-webkit-text-fill-color:currentColor}
#painel-clientes .cv2-lado .d3m-vlin{color:var(--d3-fume-texto)}
#painel-clientes .cv2-lado .d3m-vlin > span{flex:1 1 auto;min-width:0;color:var(--d3-fume-apagado);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#painel-clientes .cv2-lado .d3m-vlin > span > b{color:var(--d3-fume-texto)}
#painel-clientes .cv2-lado .d3m-vlin[aria-checked="true"]{background:var(--d3-fume-veu-forte);box-shadow:inset 0 0 0 1px var(--d3-fume-borda)}
#painel-clientes .cv2-lado .d3m-vlin > b.d3m-vn{min-width:0;color:var(--d3-fume-texto)}
#painel-clientes .cv2-carteira{appearance:none;display:flex;align-items:center;gap:14px;width:100%;margin:0;padding:12px;box-sizing:border-box;border:0;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu);color:var(--d3-fume-texto);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
#painel-clientes .cv2-carteira:hover{background:var(--d3-fume-veu-forte)}
#painel-clientes .cv2-carteira:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:1px}
#painel-clientes .cv2-carteira > span{display:flex;flex-direction:column;gap:3px;min-width:0}
#painel-clientes .cv2-carteira b{font-weight:600}
#painel-clientes .cv2-carteira small{font:inherit;color:var(--d3-fume-apagado)}
#painel-clientes .cv2-anel-g{flex:none;width:44px;height:44px}
#painel-clientes .cv2-anel-g > circle{fill:none;stroke:var(--d3-fume-veu-forte);stroke-width:5}
#painel-clientes .cv2-anel-g > circle.v{stroke:var(--d3-acao-claro);stroke-linecap:round}
#painel-clientes .cv2-nota{margin:0;font:400 var(--d3-fs-texto)/1.45 var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-apagado)}

/* 4b · O Cérebro (prancha V2-M-Clientes-Cerebro): a lista dos clientes no vidro, a folha do cliente e a consulta. */
#painel-clientes .cv2-corpo[data-visao="sinapses"]{grid-template-columns:248px minmax(0,1fr) 316px}
#painel-clientes .cv2-corpo[data-visao="sinapses"] > .cv2-folha > .cv2-cab{display:none}
#painel-clientes .cv2c-lista{gap:6px;min-height:0}
#painel-clientes .cv2c-lista[hidden]{display:none}
#painel-clientes .cv2c-lista > .d3m-cons-cab{flex:none;padding:0 8px 0 0}
#painel-clientes .cv2c-lista > .d3m-cons-cab > b{-webkit-text-fill-color:currentColor}
#painel-clientes .cv2c-nomes{flex:1 1 0;min-height:0;display:flex;flex-direction:column;gap:4px;overflow-y:auto;scrollbar-width:none}
#painel-clientes .cv2c-nome{appearance:none;flex:none;display:flex;align-items:center;gap:10px;height:36px;margin:0;padding:0 8px;box-sizing:border-box;border:0;border-radius:var(--d3-r-caixa);background:none;color:var(--d3-fume-texto);font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
#painel-clientes .cv2c-nome:hover{background:var(--d3-fume-veu)}
#painel-clientes .cv2c-nome:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:-2px}
#painel-clientes .cv2c-nome > .cv2-foto{width:22px;height:22px;border-radius:6px;font-size:9px}
#painel-clientes .cv2c-nome > span{flex:1 1 auto;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#painel-clientes .cv2c-nome > b{flex:none;font-weight:600;font-variant-numeric:tabular-nums;-webkit-text-fill-color:currentColor}
#painel-clientes .cv2c-nome.on{background:var(--d3-folha);box-shadow:var(--d3-folha-sombra);color:var(--d3-tinta);font-weight:600}
#painel-clientes .cv2c-central{display:flex;align-items:center;gap:10px;height:36px;margin:0;padding:0 10px;box-sizing:border-box;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu);color:var(--d3-fume-apagado);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif)}
#painel-clientes .cv2c-central b{font-weight:600;color:var(--d3-fume-texto);-webkit-text-fill-color:var(--d3-fume-texto)}
#painel-clientes .cv2c-central > .d3m-pt.g{background:var(--d3-pronto-claro)}
#painel-clientes .cv2-vidro{order:4;appearance:none;flex:none;display:inline-flex;align-items:center;height:34px;margin:0;padding:0 14px;box-sizing:border-box;border:0;border-radius:var(--d3-r-botao);background:var(--d3-fume-veu);box-shadow:inset 0 0 0 1px var(--d3-fume-borda);color:var(--d3-fume-texto);font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);white-space:nowrap;cursor:pointer}
#painel-clientes .cv2-vidro:hover{background:var(--d3-fume-veu-forte)}
#painel-clientes .cv2-vidro:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}
#painel-clientes #grid-clientes-lista > .cv2c{display:flex;height:100%;min-height:0;margin:0;padding:0;border:0;border-radius:0;background:none;box-shadow:none}
#painel-clientes .cv2c > .cb-centro{flex:1 1 0;display:flex;flex-direction:column;min-width:0;min-height:0;margin:0;padding:0;border:0;background:none}
#painel-clientes .cv2c .cv2c-cab{flex-direction:row;flex-wrap:nowrap;justify-content:space-between;margin:0;border:0;background:none}
#painel-clientes .cv2c .cv2c-cab > h3{text-align:left}
#painel-clientes .cv2c-corpo{flex:1 1 0;display:flex;flex-direction:column;min-height:0;margin:0 16px;border-radius:12px;overflow:auto;scrollbar-width:thin;background:var(--d3-veu)}
#painel-clientes .cv2c-corpo > *{flex:none}
#painel-clientes .cv2c-corpo :is(.cb-caminho button,.cb-areas small,.cb-mapa-rodape span){color:var(--d3-texto2)}
#painel-clientes .cv2c-corpo > .cb-palco{flex:1 1 0;min-height:240px;height:auto}
#painel-clientes .cv2c-corpo > .cb-palco > canvas{width:100%;height:100%}
#painel-clientes .cv2c-corpo > .cb-grafo{height:100%;min-height:0;border:0;border-radius:12px}
#painel-clientes .cv2c-pe{flex:none;margin:0;padding:10px 32px 14px;font:400 var(--d3-fs-apoio)/1.3 var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#painel-clientes .cv2c > .cb-inspetor:not(.cb-aberto){display:none}
#painel-clientes .cv2c > .cb-inspetor.cb-aberto{flex:0 0 300px;min-height:0;overflow-y:auto;border-left:1px solid var(--d3-divisa)}

/* 5 · Janela baixa (1366 × 768 e parecidas): o cartão laranja deita o número ao lado do título e as linhas encolhem,
   para a coluna de consulta caber inteira sem rolar. */
@media (max-height:820px) and (min-width:1181px){
  #painel-clientes .cv2-laranja{min-height:0}
  #painel-clientes .cv2-laranja .d3m-lar-txt{display:grid;grid-template-columns:auto minmax(0,1fr);column-gap:12px;row-gap:4px;align-items:center;margin-top:8px}
  #painel-clientes .cv2-laranja .d3m-lar-num{font-size:44px}
  #painel-clientes .cv2-laranja .d3m-lar-txt > .d3-acao-frase{font-size:var(--d3-fs-destaque)}
  #painel-clientes .cv2-laranja .d3m-lar-txt > :is(small,.d3m-lar-bts){grid-column:1 / -1}
  #painel-clientes .cv2-lado .d3m-vlin{height:32px}
  #painel-clientes .cv2-consulta{gap:10px}
  #painel-clientes .cv2-carteira{padding:8px 12px}
}

/* 6 · Telas menores: sem a coluna presa à direita, o laranja sobe para antes da lista e a consulta sai (o que ela abre
   está no título, em Lista/Fichas/Cérebro e em Mais). */
@media (max-width:1180px){
  #painel-clientes .cv2-corpo,#painel-clientes .cv2-corpo[data-visao="sinapses"]{grid-template-columns:minmax(0,1fr);grid-template-rows:auto minmax(0,1fr);gap:12px}
  #painel-clientes .cv2-corpo[data-visao="sinapses"]{grid-template-rows:auto auto minmax(0,1fr)}
  #painel-clientes .cv2c-lista{order:-2}
  #painel-clientes .cv2c-nomes{flex:none;flex-direction:row;overflow-x:auto;overflow-y:hidden}
  #painel-clientes .cv2c-nome{max-width:180px}
  #painel-clientes .cv2c > .cb-inspetor.cb-aberto{flex-basis:44%}
  #painel-clientes .cv2-lado{order:-1;overflow:visible}
  #painel-clientes .cv2-consulta{display:none}
  #painel-clientes .cv2-laranja{min-height:0}
  #painel-clientes .cv2-laranja .d3m-lar-txt{display:grid;grid-template-columns:auto minmax(0,1fr);column-gap:12px;row-gap:4px;align-items:center;margin-top:8px}
  #painel-clientes .cv2-laranja .d3m-lar-num{font-size:44px}
  #painel-clientes .cv2-laranja .d3m-lar-txt > .d3-acao-frase{font-size:var(--d3-fs-destaque)}
  #painel-clientes .cv2-laranja .d3m-lar-txt > :is(small,.d3m-lar-bts){grid-column:1 / -1}
  #painel-clientes .cv2-fichas{grid-template-columns:repeat(3,minmax(0,1fr))}
  #painel-clientes :is(.cv2-re,.cv2-h-reuniao,.cv2-extra){display:none}
}
@media (max-width:900px){
  /* No celular a janela encosta nas bordas e a casa antiga tem outro espaçamento (22px 30px 36px até 760 px; 16px 12px 70px abaixo). */
  body.mundo.mundo-modulo[data-modo="clientes"][data-cv2="lista"] #painel-clientes{height:100%;margin:0}
  body.mundo.mundo-modulo[data-modo="clientes"][data-cv2="lista"] #painel-clientes > .container{gap:12px;min-height:0}
  body.mundo.mundo-modulo[data-modo="clientes"][data-cv2="lista"] #painel-clientes #clientes-hero.cv2-topo{margin:-6px -24px 0}
  body.mundo.mundo-modulo[data-modo="clientes"][data-cv2="lista"] #painel-clientes #clientes-corpo.cv2-corpo{margin:0 -24px -20px}
  #painel-clientes .cv2-topo{flex-wrap:wrap;row-gap:12px;padding:0 52px 0 0}
  #painel-clientes .cv2-topo > .d3m-tit{flex:1 1 0;padding-right:0}
  #painel-clientes .cv2-seg{order:5;flex:1 1 100%;height:40px;margin-right:-52px}
  #painel-clientes .cv2-seg > button{flex:1 1 0;height:34px}
  #painel-clientes .cv2-novo{width:40px;height:40px;padding:0;font-size:0;gap:0}
  #painel-clientes .cv2-vidro{height:40px;padding:0 10px}
  #painel-clientes .cv2-novo > svg{width:18px;height:18px}
  #painel-clientes .cv2-topo :is(.cv2-acoes,.cv2-busca) > .d3m-ico{width:40px;height:40px}
  #painel-clientes .cv2-busca > input{width:150px;height:40px}
  #painel-clientes .cv2-laranja .d3m-lar-bts > .d3m-btn{flex:1 1 0;height:40px}
  #painel-clientes .cv2-cab,#painel-clientes .cv2c .cv2c-cab{flex-wrap:wrap;row-gap:4px;padding:8px 14px}
  #painel-clientes .cv2-corpo[data-visao="sinapses"] > .cv2-lado{display:none}
  #painel-clientes .cv2-corpo[data-visao="sinapses"]{grid-template-rows:auto minmax(0,1fr)}
  #painel-clientes .cv2c .cb-ampliar,#painel-clientes .cv2c .cv2-risco{display:none}
  #painel-clientes .cv2-filtros{margin-left:0;max-width:100%;overflow-x:auto;scrollbar-width:none}
  #painel-clientes .cv2-th{display:none}
  #painel-clientes .cv2-tr{display:grid;grid-template-columns:40px minmax(0,1fr) auto;grid-template-areas:"foto nome nota" "foto ab nota";column-gap:12px;row-gap:1px;height:auto;min-height:52px;padding:6px 14px}
  #painel-clientes .cv2-tr > :is(.cv2-grupo,.cv2-hd,.cv2-cd,.cv2-vai,.v2f-marcar){display:none}
  #painel-clientes .cv2-tr > .cv2-foto{grid-area:foto;width:40px;height:40px;border-radius:10px;font-size:var(--d3-fs-texto)}
  #painel-clientes .cv2-tr > .cv2-nome{grid-area:nome;align-self:end;font-size:14px}
  #painel-clientes .cv2-tr > .cv2-nome > span{display:none}
  #painel-clientes .cv2-tr > .cv2-ab{grid-area:ab;align-self:start;color:var(--d3-rotulo)}
  #painel-clientes .cv2-tr > .cv2-sa{grid-area:nota;flex-direction:column;align-items:flex-end;gap:5px}
  #painel-clientes .cv2-tr > .cv2-sa > b{flex:none;font-size:var(--d3-fs-destaque)}
  #painel-clientes .cv2-tr > .cv2-sa > .cv2-barra{width:44px}
  #painel-clientes .cv2-det{flex-wrap:wrap;padding:4px 14px 12px 66px}
  #painel-clientes .cv2-pe{display:none}
  #painel-clientes .cv2-fichas{grid-template-columns:repeat(2,minmax(0,1fr))}
  #painel-clientes .cv2-ficha{min-height:176px;padding:14px}
}
@media (max-width:760px){
  body.mundo.mundo-modulo[data-modo="clientes"][data-cv2="lista"] #painel-clientes #clientes-hero.cv2-topo{margin:0 -6px}
  body.mundo.mundo-modulo[data-modo="clientes"][data-cv2="lista"] #painel-clientes #clientes-corpo.cv2-corpo{margin:0 -6px -54px}
  #painel-clientes .cv2-sub{max-width:52vw}
}
@media (prefers-reduced-motion:reduce){
  #painel-clientes .cv2-linha[aria-expanded="false"] > .v2-mais,#painel-clientes .cv2-vai > svg{transition:none}
}

/* ===== padrao-v2/zm-b-ficha.css ===== */
/* A FICHA DO CLIENTE NA DIREÇÃO V2 (prancha V2-M-Cliente-Ficha, aprovada pelo Paulo em 16/11/2026). Fragmento do grupo B.
   A janela é vidro fumê. O alto fica no vidro, numa linha (voltar, a foto, o nome com a linha do cadastro, as abas, o
   lápis e Nova demanda). O Resumo tem três colunas: as folhas "Próximas entregas" e "Depois das vencidas"; o cartão
   laranja do Mateus com a folha "As vencidas"; e a consulta direto no vidro (Saúde, Última reunião, Dados e acessos,
   Planejamentos). Fora do Resumo, a aba mora numa folha que rola por dentro. Peças locais: fv2-*; as comuns vêm de
   z-direcao.css (d3m-*, d3v-*) e de zm-b-clientes.css (cv2-cab, cv2-chip, cv2-seg, cv2-novo, cv2-foto, cv2-laranja). */

/* 1 · A janela e o esqueleto (data-cv2="ficha" é posto por marcarTelaDeClientes). */
body.mundo.mundo-modulo[data-modo="clientes"][data-cv2="ficha"] #mundo-moldura{border-radius:20px;background:var(--d3-fume);box-shadow:inset 0 0 0 1px var(--d3-fume-borda),0 30px 60px -40px rgba(0,0,0,.6)}
body.mundo.mundo-modulo[data-modo="clientes"][data-cv2="ficha"] #painel-clientes{box-sizing:border-box;height:calc(100% + 4px);margin:0 -16px 0 -2px;background:none;box-shadow:none}
body.mundo.mundo-modulo[data-modo="clientes"][data-cv2="ficha"] #painel-clientes > .container{display:flex;flex-direction:column;box-sizing:border-box;width:auto;max-width:none;height:100%;min-height:480px;margin:0;color:var(--d3-tinta)}
/* A folha de antes prende o espaçamento da casa (22px 30px 36px, forçado): a ficha volta para a borda de 16 px por margem. */
body.mundo.mundo-modulo[data-modo="clientes"][data-cv2="ficha"] #painel-clientes #panel-cliente-detalhe{order:0;flex:1 1 0;display:flex;flex-direction:column;gap:16px;min-height:0;margin:-14px -30px -36px}
#painel-clientes #panel-cliente-detalhe > #cliente-detalhe-cabeca{flex:none;margin:0;padding:0;border:0;background:none;container:fv2topo / inline-size}
#painel-clientes #panel-cliente-detalhe > #client-master-detail{flex:1 1 0;display:block;min-height:0;margin:0;padding:0;background:none}

/* 2 · O alto. */
#painel-clientes .fv2-topo{display:flex;flex-wrap:wrap;align-items:center;gap:8px 12px;min-height:48px;margin:0;padding:0 96px 0 0;border:0;background:none;color:var(--d3-fume-texto)}
#painel-clientes .fv2-topo > .cv2-foto.g{width:44px;height:44px;font-size:var(--d3-fs-destaque)}
#painel-clientes .fv2-tit{flex:1 1 140px;display:flex;flex-direction:column;gap:3px;min-width:140px;margin:0}
#painel-clientes .fv2-nome{margin:0;font:600 24px/1.1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.02em;color:var(--d3-fume-texto);-webkit-text-fill-color:var(--d3-fume-texto);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#painel-clientes .fv2-meta{display:flex;align-items:center;gap:5px;min-width:0;margin:0;font:400 var(--d3-fs-texto)/1.2 var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-apagado);white-space:nowrap;overflow:hidden}
#painel-clientes .fv2-meta > .clf-ponto{font-style:normal}
#painel-clientes .fv2-meta > .clf-meta-item{color:inherit;border-radius:4px}
#painel-clientes .fv2-meta > .clf-meta-item.editavel{cursor:pointer}
#painel-clientes .fv2-meta > .clf-meta-item.editavel:hover{color:var(--d3-fume-texto);text-decoration:underline;text-underline-offset:3px}
#painel-clientes .fv2-meta > .clf-meta-item:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}
#painel-clientes .fv2-meta > .fv2-sit{appearance:none;height:auto;margin:0;padding:0;border:0;border-radius:4px;background:none;box-shadow:none;color:var(--d3-fume-apagado);font:inherit;text-transform:lowercase;cursor:pointer}
#painel-clientes .fv2-meta > button.fv2-sit:hover{color:var(--d3-fume-texto);text-decoration:underline;text-underline-offset:3px}
#painel-clientes .fv2-abas-topo{flex:0 1 auto;display:flex;min-width:0}
#painel-clientes .fv2-abas{order:0;max-width:100%;overflow-x:auto;scrollbar-width:none}
#painel-clientes .fv2-abas > button{flex:none;display:inline-flex;align-items:center;gap:6px}
#painel-clientes .fv2-abas > button > svg{flex:none}
#painel-clientes .fv2-abas .v2f-q{min-width:0;height:auto;margin:0;padding:0;border:0;border-radius:0;background:none;box-shadow:none;font-size:inherit;font-weight:400;color:var(--d3-fume-apagado);font-variant-numeric:tabular-nums}
#painel-clientes .fv2-abas > button[aria-checked="true"] .v2f-q{color:var(--d3-rotulo)}
#painel-clientes .fv2-acoes{flex:none;display:inline-flex;align-items:center;gap:8px;margin:0}
/* Sem largura para tudo numa linha (janela estreita ou muitas abas), as abas descem para uma linha só delas. */
@container fv2topo (max-width:1480px){
  #painel-clientes .fv2-abas-topo{order:9;flex:1 1 100%}
}

/* 3 · O Resumo: três colunas da altura da janela; só as listas rolam por dentro. */
#painel-clientes .fv2-resumo{display:grid;grid-template-columns:minmax(0,1fr) 340px 300px;gap:16px;height:100%;min-height:0;margin:0;padding:0}
#painel-clientes .fv2-col{display:flex;flex-direction:column;gap:16px;min-width:0;min-height:0}
#painel-clientes .fv2-folha{display:flex;flex-direction:column;min-width:0;min-height:0;box-sizing:border-box;border-radius:var(--d3-r-ilha);overflow:hidden;background:var(--d3-folha);box-shadow:var(--d3-folha-sombra);color:var(--d3-tinta);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif)}
#painel-clientes .fv2-cab-lado{flex:none;display:inline-flex;align-items:center;gap:8px;margin-left:auto;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);white-space:nowrap}
#painel-clientes .fv2-cab-lado > .cv2-chip{color:var(--d3-tinta);font-weight:500}
#painel-clientes .fv2-entregas{flex:none}
#painel-clientes .fv2-pecas{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;padding:0 16px 16px}
#painel-clientes .fv2-peca{appearance:none;position:relative;display:flex;flex-direction:column;justify-content:space-between;align-items:flex-start;gap:8px;min-width:0;height:176px;margin:0;padding:10px;box-sizing:border-box;border:0;border-radius:12px;overflow:hidden;background:linear-gradient(180deg,hsl(var(--h,28) 46% 30%) 0%,hsl(var(--h,28) 40% 14%) 100%);color:var(--d3-escuro-texto);font:400 var(--d3-fs-apoio)/1.3 var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
#painel-clientes .fv2-peca:hover{box-shadow:0 0 0 2px var(--d3-tinta)}
#painel-clientes .fv2-peca:focus-visible{outline:2px solid var(--d3-acao);outline-offset:2px}
#painel-clientes .fv2-peca-tipo{max-width:100%;height:20px;padding:0 8px;box-sizing:border-box;border-radius:999px;background:var(--d3-folha);color:var(--d3-tinta);font:500 var(--d3-fs-mini)/20px var(--vv-texto,Inter,sans-serif);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#painel-clientes .fv2-peca-pe{display:flex;flex-direction:column;gap:2px;min-width:0;max-width:100%}
#painel-clientes .fv2-peca-pe > b{font:600 var(--d3-fs-texto)/1.25 var(--vv-texto,Inter,sans-serif);color:var(--d3-escuro-texto);-webkit-text-fill-color:var(--d3-escuro-texto);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#painel-clientes .fv2-peca-st{display:inline-flex;align-items:center;gap:6px;min-width:0;color:var(--d3-escuro-texto);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#painel-clientes .fv2-peca-st > i{flex:none;width:7px;height:7px;border-radius:50%;background:var(--d3-fume-apagado)}
#painel-clientes .fv2-peca-st.a > i{background:var(--d3-ajuste-claro)}
#painel-clientes .fv2-peca-st.b > i{background:var(--d3-info-claro)}
#painel-clientes .fv2-peca-st.g > i{background:var(--d3-pronto-claro)}
#painel-clientes .fv2-pede,#painel-clientes .fv2-vencidas{flex:1 1 0}
#painel-clientes .fv2-linhas{flex:1 1 0;min-height:0;overflow-y:auto;scrollbar-width:thin}
#painel-clientes .fv2-lin{display:flex;align-items:center;gap:10px;min-height:44px;margin:0;padding:0 16px;box-sizing:border-box;border:0;border-top:1px solid var(--d3-divisa);background:none}
#painel-clientes .fv2-lin-rot{flex:0 0 104px;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#painel-clientes .fv2-lin-rot.a{color:var(--d3-ambar)}
#painel-clientes .fv2-lin > p{flex:1 1 auto;min-width:0;margin:0;font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#painel-clientes .fv2-lin > p > b{font-weight:600;color:var(--d3-tinta)}
#painel-clientes .fv2-lin > .d3v-btn{flex:none;box-shadow:inset 0 0 0 1px var(--d3-veu-forte)}
#painel-clientes .fv2-lin > input{flex:1 1 auto;min-width:0;height:28px}
#painel-clientes .fv2-alto{display:block;margin:0}
#painel-clientes .fv2-laranja{min-height:252px}
#painel-clientes .fv2-calmo{display:flex;flex-direction:column;align-items:flex-start;gap:6px;padding:16px;border-radius:var(--d3-r-ilha);background:var(--d3-fume-veu);color:var(--d3-fume-apagado);font:400 var(--d3-fs-texto)/1.4 var(--vv-texto,Inter,sans-serif)}
#painel-clientes .fv2-calmo > b{font:600 var(--d3-fs-titulo)/1.25 var(--vv-titulo,"Inter Tight",Inter,sans-serif);color:var(--d3-fume-texto);-webkit-text-fill-color:var(--d3-fume-texto)}
#painel-clientes .fv2-venc{appearance:none;display:flex;align-items:center;gap:10px;width:100%;height:38px;margin:0;padding:0 16px;box-sizing:border-box;border:0;border-top:1px solid var(--d3-divisa);border-radius:0;background:none;color:var(--d3-tinta);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
#painel-clientes .fv2-venc:hover{background:var(--d3-veu)}
#painel-clientes .fv2-venc:focus-visible{outline:2px solid var(--d3-acao);outline-offset:-2px}
#painel-clientes .fv2-pt{flex:none;width:7px;height:7px;border-radius:50%;background:none}
#painel-clientes .fv2-pt.a{background:var(--d3-ambar)}
#painel-clientes .fv2-venc-t{flex:1 1 auto;min-width:0;color:var(--d3-rotulo);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#painel-clientes .fv2-venc-t > b{font-weight:600;color:var(--d3-tinta)}
#painel-clientes .fv2-venc-q{flex:none;font-size:var(--d3-fs-apoio);color:var(--d3-perigo);font-variant-numeric:tabular-nums}
#painel-clientes .fv2-venc > .cv2-pes.vazio{background:none}
#painel-clientes .fv2-legenda{flex:none;display:flex;align-items:center;gap:6px;min-height:44px;margin:0;padding:0 16px;box-sizing:border-box;border-top:1px solid var(--d3-divisa);font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}

/* 4 · A consulta, direto no vidro. */
#painel-clientes .fv2-lado{min-height:0;overflow-y:auto;scrollbar-width:none}
#painel-clientes .fv2-lado :is(.d3m-cons-cab > b,.d3m-vlin b,.fv2-mot b,.fv2-nota b){-webkit-text-fill-color:currentColor}
#painel-clientes .fv2-lado .d3m-vlin{color:var(--d3-fume-texto)}
#painel-clientes .fv2-lado .d3m-vlin > span:not(.d3m-vbarra){flex:1 1 auto;min-width:0;color:var(--d3-fume-apagado);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#painel-clientes .fv2-lado .d3m-vlin > span > b{font-weight:600;color:var(--d3-fume-texto)}
#painel-clientes .fv2-lado .d3m-vlin > .d3m-vbarra{flex:0 0 56px}
#painel-clientes .fv2-lado div.d3m-vlin{cursor:default}
#painel-clientes #client-master-detail .fv2-lado .fv2-campo{display:flex;flex-direction:row;align-items:center;gap:10px;height:36px;margin:0;padding:0 10px;border:0;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu)}
#painel-clientes #client-master-detail .fv2-lado .fv2-campo > span > b{display:inline;font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-texto);-webkit-text-fill-color:var(--d3-fume-texto)}
#painel-clientes .fv2-lado .d3m-pt.g{background:var(--d3-pronto-claro)}
#painel-clientes .fv2-apoio{flex:none;font-style:normal;font-size:var(--d3-fs-apoio);color:var(--d3-fume-apagado)}
#painel-clientes .fv2-mini{appearance:none;flex:none;margin:0;padding:0 2px;border:0;border-radius:4px;background:none;color:var(--d3-fume-texto);font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);text-decoration:underline;text-underline-offset:3px;cursor:pointer}
#painel-clientes .fv2-mini:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}
#painel-clientes .fv2-campo > input{flex:1 1 auto;min-width:0;height:26px}
#painel-clientes .fv2-saude{appearance:none;display:flex;align-items:center;gap:14px;width:100%;margin:0;padding:12px;box-sizing:border-box;border:0;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu);color:var(--d3-fume-texto);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);text-align:left}
#painel-clientes button.fv2-saude{cursor:pointer}
#painel-clientes button.fv2-saude:hover{background:var(--d3-fume-veu-forte)}
#painel-clientes button.fv2-saude:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:1px}
#painel-clientes .fv2-nota{position:relative;flex:none;display:grid;place-items:center;width:56px;height:56px;--fv2-tom:var(--d3-fume-apagado)}
#painel-clientes .fv2-nota.r{--fv2-tom:var(--d3-perigo-claro)}
#painel-clientes .fv2-nota.a{--fv2-tom:var(--d3-ajuste-claro)}
#painel-clientes .fv2-nota.g{--fv2-tom:var(--d3-pronto-claro)}
#painel-clientes .fv2-nota > svg{position:absolute;inset:0;width:100%;height:100%}
#painel-clientes .fv2-nota > svg > circle{fill:none;stroke:var(--d3-fume-veu-forte);stroke-width:5}
#painel-clientes .fv2-nota > svg > circle.v{stroke:var(--fv2-tom);stroke-linecap:round}
#painel-clientes .fv2-nota > b{position:relative;font:600 20px/1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);color:var(--d3-fume-texto);font-variant-numeric:tabular-nums}
#painel-clientes .fv2-mots{display:flex;flex-direction:column;gap:3px;min-width:0}
#painel-clientes .fv2-mot{display:flex;gap:8px;min-width:0;color:var(--d3-fume-apagado);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#painel-clientes .fv2-mot > b{flex:0 0 26px;font-weight:600;color:var(--d3-fume-texto);font-variant-numeric:tabular-nums}
#painel-clientes .fv2-acessos{display:flex;flex-direction:column;gap:6px;padding:8px 10px;border-radius:var(--d3-r-caixa);background:var(--d3-fume-escuro);color:var(--d3-fume-texto)}
#painel-clientes .fv2-acessos[hidden]{display:none}
#painel-clientes .fv2-acessos > .clf-acesso{display:flex;align-items:center;gap:8px;min-width:0;margin:0;padding:0;border:0;background:none;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif)}
#painel-clientes .fv2-acessos > .clf-acesso > small{flex:0 0 96px;font:inherit;color:var(--d3-fume-apagado)}
#painel-clientes .fv2-acessos > .clf-acesso > b{flex:1 1 auto;min-width:0;font-weight:500;color:var(--d3-fume-texto);-webkit-text-fill-color:var(--d3-fume-texto);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#painel-clientes .fv2-acessos a{color:var(--d3-fume-texto)}

/* 5 · O Cadastro (leitura) mora numa folha que rola por dentro. As outras abas têm o esqueleto delas em zm-b-ficha2-abas.css. */
#painel-clientes .fv2-aba{height:100%;min-height:0;margin:0;padding:0}
#painel-clientes .fv2-aba-folha{height:100%;padding:16px;overflow-y:auto;scrollbar-width:thin}
#painel-clientes .fv2-aba-folha[data-aba="financeiro"]{padding:0}
#painel-clientes .fv2-fin{display:flex;flex-direction:column;min-height:100%}
#painel-clientes .fv2-fin > .cv2-cab{flex-wrap:wrap;row-gap:8px;padding-top:8px;padding-bottom:8px}
#painel-clientes .fv2-fin-alto{display:flex;flex-direction:column;gap:6px;padding:20px 16px;border-top:1px solid var(--d3-divisa)}
#painel-clientes .fv2-fin-valor{font:600 44px/1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.03em;color:var(--d3-tinta);font-variant-numeric:tabular-nums}
#painel-clientes .fv2-fin-grade{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:0;border-top:1px solid var(--d3-divisa)}
#painel-clientes .fv2-fin-campo{display:flex;flex-direction:column;gap:4px;padding:14px 16px;border-right:1px solid var(--d3-divisa)}
#painel-clientes .fv2-fin-campo > b{font:600 var(--d3-fs-destaque)/1.3 var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}

/* 6 · Janela baixa: o laranja deita o número e as peças encolhem. */
@media (max-height:820px) and (min-width:1181px){
  #painel-clientes .fv2-peca{height:128px}
  #painel-clientes .fv2-laranja{min-height:0}
  #painel-clientes .fv2-lado .d3m-vlin{height:32px}
  #painel-clientes .fv2-lado{gap:10px}
  #painel-clientes .fv2-saude{padding:8px 12px}
  #painel-clientes .fv2-semdado{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
}
/* 7 · Telas menores: uma coluna, e a ficha rola por dentro da janela. */
@media (max-width:1180px){
  #painel-clientes #panel-cliente-detalhe > #client-master-detail{overflow-y:auto;scrollbar-width:none}
  #painel-clientes .fv2-resumo{grid-template-columns:minmax(0,1fr);height:auto}
  #painel-clientes .fv2-meio{order:-1}
  #painel-clientes .fv2-laranja{min-height:0}
  #painel-clientes .fv2-pede,#painel-clientes .fv2-vencidas{flex:none}
  #painel-clientes .fv2-linhas{flex:none;max-height:320px}
  #painel-clientes .fv2-lado{overflow:visible}
}
@media (max-width:900px){
  body.mundo.mundo-modulo[data-modo="clientes"][data-cv2="ficha"] #painel-clientes{height:100%;margin:0}
  body.mundo.mundo-modulo[data-modo="clientes"][data-cv2="ficha"] #painel-clientes > .container{min-height:0}
  body.mundo.mundo-modulo[data-modo="clientes"][data-cv2="ficha"] #painel-clientes #panel-cliente-detalhe{gap:12px;margin:-6px -24px -20px}
  #painel-clientes .fv2-topo{padding:0}
  #painel-clientes .fv2-tit{padding-right:52px}
  #painel-clientes .fv2-nome{font-size:20px}
  #painel-clientes .fv2-meta{white-space:nowrap;overflow:hidden}
  #painel-clientes .fv2-abas-topo{order:9;flex:1 1 100%}
  #painel-clientes .fv2-acoes{order:8;flex:1 1 100%;justify-content:flex-end}
  #painel-clientes .fv2-meta > .clf-ponto{display:inline}
  #painel-clientes .fv2-pecas{grid-template-columns:repeat(2,minmax(0,1fr))}
  #painel-clientes .fv2-peca{height:128px}
  #painel-clientes .fv2-lin{flex-wrap:wrap;row-gap:4px;padding:8px 14px}
  #painel-clientes .fv2-lin-rot{flex:1 1 100%}
  #painel-clientes .fv2-lin > p{white-space:normal}
}
@media (max-width:760px){
  body.mundo.mundo-modulo[data-modo="clientes"][data-cv2="ficha"] #painel-clientes #panel-cliente-detalhe{margin:0 -6px -54px}
}

/* ===== padrao-v2/zm-b-ficha2-abas.css ===== */
/* AS ABAS DA FICHA DO CLIENTE NA DIREÇÃO V2 (pranchas V2-M-Cliente-Conteudo, -Demandas, -Reunioes, -Onboarding,
   -Ecossistema, -Cerebro e -Financeiro, aprovadas pelo Paulo em 16/11/2026). Fragmento do grupo B; vem depois de
   zm-b-ficha.css (o alto e o Resumo). Toda aba tem o mesmo esqueleto: as folhas claras à esquerda e, à direita, direto
   no vidro, o cartão laranja e a consulta (316 px). Peças locais: fv2-duas, fv2-vazio, fv2-barras, fv2-op (a lista da
   operação), fv2-tb (linhas de uma folha). As comuns vêm de z-direcao.css (d3m-*, d3v-*) e zm-b-clientes.css (cv2-*). */

/* 1 · O esqueleto das abas. */
#painel-clientes .fv2-duas{display:grid;grid-template-columns:minmax(0,1fr) 316px;gap:16px;height:100%;min-height:0;margin:0;padding:0}
#painel-clientes .fv2-duas > .fv2-col{gap:12px}
#painel-clientes #client-master-detail > .fv2-aba{display:block}
#painel-clientes .fv2-cheia{flex:1 1 0;min-height:168px}
#painel-clientes .fv2-fixa{flex:none}
#painel-clientes .fv2-lar-aba{flex:none;min-height:0;gap:10px}
#painel-clientes .fv2-lar-aba .d3m-lar-txt{margin-top:0}
#painel-clientes .fv2-duas .fv2-calmo{flex:none}
#painel-clientes .fv2-nota-lado{margin:0;font:400 var(--d3-fs-apoio)/1.5 var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-apagado)}
#painel-clientes .fv2-cab-acao{appearance:none;flex:none;margin:0 0 0 auto;padding:0 2px;border:0;border-radius:4px;background:none;color:var(--d3-tinta);font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);white-space:nowrap;cursor:pointer}
#painel-clientes .fv2-cab-acao:hover{text-decoration:underline;text-underline-offset:3px}
#painel-clientes .fv2-cab-acao:focus-visible{outline:2px solid var(--d3-acao);outline-offset:2px}
#painel-clientes .fv2-cab-nota{flex:none;margin-left:auto;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);white-space:nowrap}
#painel-clientes .fv2-cab-nota + .fv2-cab-acao{margin-left:0}
/* Vazio: o ícone na caixinha, o título e uma frase (o mesmo em todas as abas). */
#painel-clientes .fv2-vazio{flex:1 1 auto;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;min-height:0;margin:0;padding:10px 16px;box-sizing:border-box;text-align:center;font:400 var(--d3-fs-apoio)/1.5 var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
#painel-clientes .fv2-vazio > b{margin-top:6px;font:600 14px/1.3 var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);-webkit-text-fill-color:var(--d3-tinta)}
#painel-clientes .fv2-vazio > span{max-width:380px}
#painel-clientes .fv2-vazio > .d3v-btn{margin-top:8px}
#painel-clientes .fv2-vazio-ico{display:grid;place-items:center;width:44px;height:44px;border-radius:12px;background:var(--d3-veu);color:var(--d3-tinta)}
#painel-clientes .fv2-vazio-ico > svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
/* Barras de contagem no vidro (Por status, Por parte). */
#painel-clientes .fv2-barras{display:flex;flex-direction:column;padding:6px 2px;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu)}
#painel-clientes .fv2-barra-lin{appearance:none;display:flex;align-items:center;gap:10px;width:100%;height:23px;margin:0;padding:0 10px;box-sizing:border-box;border:0;border-radius:6px;background:none;color:var(--d3-fume-texto);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);text-align:left}
#painel-clientes button.fv2-barra-lin{cursor:pointer}
#painel-clientes button.fv2-barra-lin:is(:hover,[aria-pressed="true"]){background:var(--d3-fume-veu)}
#painel-clientes button.fv2-barra-lin:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:-2px}
#painel-clientes .fv2-barra-lin > span:first-child{flex:0 0 112px;min-width:0;color:var(--d3-fume-apagado);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#painel-clientes .fv2-barra-lin > .d3m-vbarra{flex:1 1 auto}
#painel-clientes .fv2-barra-lin > .d3m-vbarra > i{background:var(--st,var(--d3-fume-texto))}
#painel-clientes .fv2-barra-lin > .d3m-vbarra.g > i{background:var(--d3-pronto-claro)}
#painel-clientes .fv2-barra-lin > b{flex:0 0 auto;min-width:22px;text-align:right;font-weight:600;color:var(--d3-fume-texto);-webkit-text-fill-color:var(--d3-fume-texto);font-variant-numeric:tabular-nums;white-space:nowrap}

/* 2 · A lista da operação (abas Conteúdo e Demandas): marca, miniatura, nome, status, prazo, veiculação e quem. */
#painel-clientes .fv2-op-cab{gap:12px}
#painel-clientes .fv2-op-cab > .cv2-filtros{min-width:0}
#painel-clientes .fv2-op-cab .cv2-chip > span.cv2-ruim{color:var(--d3-perigo)}
#painel-clientes .fv2-op-th{flex:none;display:flex;align-items:center;gap:10px;height:24px;padding:0 16px;box-sizing:border-box;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
#painel-clientes .fv2-op-linhas{flex:1 1 0;display:flex;flex-direction:column;min-height:0;margin:0;padding:0;overflow-y:auto;scrollbar-width:thin}
#painel-clientes .fv2-op-lin{flex:none;display:flex;align-items:center;gap:10px;height:40px;margin:0;padding:0 16px;box-sizing:border-box;border-top:1px solid var(--d3-divisa);cursor:pointer}
#painel-clientes .fv2-op-lin:hover,#painel-clientes .fv2-op-lin.marcada{background:var(--d3-veu)}
#painel-clientes .fv2-op-c-marca{flex:0 0 16px}
#painel-clientes .fv2-op-c-mini{flex:0 0 28px}
#painel-clientes .fv2-op-c-nome{flex:1 1 0;min-width:0}
#painel-clientes .fv2-op-c-st{flex:0 0 160px;display:flex;align-items:center;min-width:0}
#painel-clientes .fv2-op-c-prazo{flex:0 0 64px}
#painel-clientes .fv2-op-c-veiculacao{flex:0 0 96px}
#painel-clientes .fv2-op-c-quem{flex:0 0 32px;display:flex;align-items:center}
/* A caixa de marcar: a folha antiga pinta toda caixa marcada de laranja (com #workspace-drawer no :is, peso de um id); aqui vale a tinta da prancha, por dois ids. */
#painel-clientes #client-master-detail .fv2-op-lin > input.fv2-op-marca{width:16px;height:16px;border:1.5px solid var(--d3-meta);border-radius:5px;background:none}
#painel-clientes #client-master-detail .fv2-op-lin > input.fv2-op-marca:checked{border-color:var(--d3-tinta);background:var(--d3-tinta) none}
#painel-clientes .fv2-op-marca{appearance:none;-webkit-appearance:none;flex:0 0 16px;display:grid;place-items:center;width:16px;height:16px;margin:0;padding:0;box-sizing:border-box;border:1.5px solid var(--d3-meta);border-radius:5px;background:none;cursor:pointer}
#painel-clientes .fv2-op-marca:hover{border-color:var(--d3-tinta)}
#painel-clientes .fv2-op-marca:checked{border-color:var(--d3-tinta);background:var(--d3-tinta)}
#painel-clientes .fv2-op-marca:checked::after{content:"";width:8px;height:4px;margin-top:-2px;border:solid var(--d3-contra,var(--d3-escuro-texto));border-width:0 0 2px 2px;transform:rotate(-45deg)}
#painel-clientes .fv2-op-marca:focus-visible{outline:2px solid var(--d3-acao);outline-offset:2px}
#painel-clientes .fv2-op-mini{appearance:none;flex:0 0 28px;display:grid;place-items:center;width:28px;height:28px;margin:0;padding:0;border:0;border-radius:7px;background:linear-gradient(160deg,hsl(var(--h,28) 46% 16%) 0%,hsl(var(--h,28) 46% 34%) 60%,hsl(var(--h,28) 52% 62%) 100%);color:var(--d3-escuro-texto);font-style:normal}
#painel-clientes button.fv2-op-mini{cursor:pointer}
#painel-clientes button.fv2-op-mini:hover{box-shadow:0 0 0 2px var(--d3-tinta)}
#painel-clientes button.fv2-op-mini:focus-visible{outline:2px solid var(--d3-acao);outline-offset:2px}
#painel-clientes .fv2-op-mini > svg{width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
#painel-clientes .fv2-op-nome{appearance:none;flex:1 1 0;min-width:0;height:26px;margin:0;padding:0;border:0;border-radius:4px;background:none;box-shadow:none;color:var(--d3-rotulo);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);text-align:left;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;cursor:pointer}
#painel-clientes .fv2-op-nome > b{font-weight:600;color:var(--d3-tinta)}
#painel-clientes .fv2-op-nome:focus-visible{outline:2px solid var(--d3-acao);outline-offset:1px}
/* O status na linha: o ponto na cor do status e o texto; o clique troca (a mesma peça da Produção). */
#painel-clientes .fv2-op .pv2-st{appearance:none;display:inline-flex;align-items:center;gap:6px;height:26px;max-width:100%;margin:0 0 0 -6px;padding:0 6px;box-sizing:border-box;border:0;border-radius:var(--d3-r-botao);background:none;box-shadow:none;color:var(--d3-tinta);font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);white-space:nowrap;cursor:pointer}
#painel-clientes .fv2-op .pv2-st::before{content:"";flex:none;width:7px;height:7px;border-radius:50%;background:var(--st,var(--d3-meta))}
#painel-clientes .fv2-op .pv2-st:hover{background:var(--d3-veu-forte)}
#painel-clientes .fv2-op .pv2-st:focus-visible{outline:2px solid var(--d3-acao);outline-offset:2px}
#painel-clientes .fv2-op .pv2-st-rot{min-width:0;overflow:hidden;text-overflow:ellipsis}
#painel-clientes .fv2-op .pv2-st-seta{flex:none;display:none}
#painel-clientes .fv2-op .pv2-st:is(:hover,:focus-visible) .pv2-st-seta{display:grid}
#painel-clientes .fv2-op .pv2-st-seta > svg{width:12px;height:12px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
#painel-clientes .fv2-op .pv2-st-ok{display:none}
/* A data na linha: o texto curto ("era 02/11", "hoje") por cima do campo de data de verdade. */
#painel-clientes .fv2-op-data{position:relative;display:block;height:26px;margin:0 0 0 -4px;padding:0 4px;box-sizing:border-box;border-radius:6px;color:var(--d3-tinta);font:400 var(--d3-fs-apoio)/26px var(--vv-texto,Inter,sans-serif);font-variant-numeric:tabular-nums;white-space:nowrap;overflow:hidden;cursor:pointer}
#painel-clientes .fv2-op-data.fv2-op-c-prazo{flex-basis:68px}
#painel-clientes .fv2-op-data.fv2-op-c-veiculacao{flex-basis:100px}
#painel-clientes .fv2-op-data.r{color:var(--d3-perigo);font-weight:500}
#painel-clientes .fv2-op-data.a{color:var(--d3-ambar);font-weight:500}
#painel-clientes .fv2-op-data.sem{color:var(--d3-rotulo)}
#painel-clientes .fv2-op-data:hover{background:var(--d3-veu-forte)}
#painel-clientes .fv2-op-data:focus-within{outline:2px solid var(--d3-acao);outline-offset:1px}
#painel-clientes .fv2-op-data > input{position:absolute;inset:0;width:100%;height:100%;margin:0;padding:0;border:0;opacity:0;cursor:pointer}
#painel-clientes .fv2-op .pv2-av{appearance:none;flex:none;display:grid;place-items:center;width:24px;height:24px;margin:0;padding:0;border:0;border-radius:50%;background:var(--d3-veu);box-shadow:none;color:var(--d3-tinta);font:600 10px var(--vv-texto,Inter,sans-serif);cursor:pointer}
#painel-clientes .fv2-op .pv2-av:hover{background:var(--d3-veu-forte)}
#painel-clientes .fv2-op .pv2-av.sd{background:none;box-shadow:inset 0 0 0 1.5px var(--d3-ambar);color:var(--d3-ambar)}
#painel-clientes .fv2-op .pv2-av:focus-visible{outline:2px solid var(--d3-acao);outline-offset:2px}
#painel-clientes .fv2-op-pe{flex:none;display:flex;align-items:center;justify-content:space-between;gap:10px;min-height:48px;padding:0 16px;box-sizing:border-box;border-top:1px solid var(--d3-divisa)}
#painel-clientes .fv2-op-pe-txt{display:inline-flex;align-items:center;gap:10px;min-width:0;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);white-space:nowrap;overflow:hidden}
#painel-clientes .fv2-op-pe-txt > b{font-weight:600;color:var(--d3-tinta)}
#painel-clientes .fv2-op-pe-txt > .cv2-chip{text-decoration:underline;text-underline-offset:3px}
#painel-clientes .fv2-op-pe-bts{flex:none;display:inline-flex;gap:8px}
#painel-clientes .fv2-op-acao{background:none;box-shadow:inset 0 0 0 1px var(--d3-veu-forte)}
#painel-clientes .fv2-op-acao:disabled{background:none;color:var(--d3-rotulo)}
/* Com a lista da aba na tela, as ações das marcadas ficam no pé dela: a barra de lote do painel dá lugar. */
body.mundo.mundo-modulo[data-modo="clientes"][data-cv2="ficha"]:is([data-fv2-aba="conteudo"],[data-fv2-aba="demandas"]) #lote-deck{display:none}

/* 3 · Linhas de uma folha (fv2-tb): o que as abas Reuniões, Onboarding, Ecossistema e Cérebro listam. */
#painel-clientes .fv2-tb{margin:0;padding:0;list-style:none}
#painel-clientes .fv2-tb-lin{appearance:none;display:flex;align-items:center;gap:12px;width:100%;min-height:44px;margin:0;padding:0 16px;box-sizing:border-box;border:0;border-top:1px solid var(--d3-divisa);border-radius:0;background:none;box-shadow:none;color:var(--d3-tinta);font:400 var(--d3-fs-texto)/1.35 var(--vv-texto,Inter,sans-serif);text-align:left;list-style:none}
#painel-clientes button.fv2-tb-lin{cursor:pointer}
#painel-clientes button.fv2-tb-lin:hover{background:var(--d3-veu)}
#painel-clientes button.fv2-tb-lin:focus-visible{outline:2px solid var(--d3-acao);outline-offset:-2px}
#painel-clientes .fv2-tb-lin > svg{flex:none;width:14px;height:14px;fill:none;stroke:var(--d3-rotulo);stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
#painel-clientes .fv2-tb-txt{flex:1 1 auto;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#painel-clientes .fv2-tb-txt > b{font-weight:600;color:var(--d3-tinta)}
#painel-clientes .fv2-n{flex:none;display:grid;place-items:center;width:24px;height:24px;border-radius:7px;background:var(--d3-veu);color:var(--d3-tinta);font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);font-style:normal;font-variant-numeric:tabular-nums}
#painel-clientes .fv2-est{flex:none;display:inline-flex;align-items:center;gap:6px;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);white-space:nowrap}
#painel-clientes .fv2-est > i{flex:none;width:7px;height:7px;border-radius:50%;background:var(--d3-meta)}
#painel-clientes .fv2-est.g > i{background:var(--d3-pronto)}
#painel-clientes .fv2-est.r > i{background:var(--d3-perigo)}
#painel-clientes .fv2-est.a > i{background:var(--d3-ambar)}
#painel-clientes .fv2-est.b > i{background:var(--d3-info)}

/* 4 · Aba Reuniões: a reunião em foco (pauta e ata lado a lado; no pé, a gravação), a pauta sugerida e as outras. */
#painel-clientes .fv2-reu{flex:0 1 auto;min-height:148px}
#painel-clientes .fv2-reu-corpo{flex:1 1 auto;min-height:0;overflow-y:auto;scrollbar-width:thin;border-top:1px solid var(--d3-divisa)}
#painel-clientes .fv2-reu-2{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,7fr)}
#painel-clientes .fv2-reu-parte{display:flex;flex-direction:column;gap:8px;min-width:0;padding:12px 16px 14px}
#painel-clientes .fv2-reu-parte + .fv2-reu-parte{border-left:1px solid var(--d3-divisa)}
#painel-clientes .fv2-reu-parte > ul{display:flex;flex-direction:column;gap:6px;margin:0;padding:0;list-style:none}
#painel-clientes .fv2-reu-parte > ul > li{display:flex;align-items:baseline;gap:9px;margin:0;font:400 var(--d3-fs-texto)/1.4 var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}
#painel-clientes .fv2-reu-parte > ul > li::before{content:"";flex:none;width:6px;height:6px;border-radius:50%;background:var(--d3-meta);transform:translateY(-1px)}
#painel-clientes .fv2-reu-parte > p{margin:0;font:400 var(--d3-fs-texto)/1.5 var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}
#painel-clientes .fv2-reu-parte > p.fv2-reu-sem{color:var(--d3-rotulo)}
#painel-clientes .fv2-reu-mais{border-top:1px solid var(--d3-divisa)}
#painel-clientes .fv2-reu-mais > summary{display:flex;align-items:center;min-height:40px;padding:0 16px;font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);list-style:none;cursor:pointer}
#painel-clientes .fv2-reu-mais > summary::-webkit-details-marker{display:none}
#painel-clientes .fv2-reu-mais > summary:hover{background:var(--d3-veu)}
#painel-clientes .fv2-reu-mais > summary:focus-visible{outline:2px solid var(--d3-acao);outline-offset:-2px}
#painel-clientes .fv2-reu-mais-c{padding:0 16px 14px;font:400 var(--d3-fs-texto)/1.5 var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}
#painel-clientes .fv2-reu-mais-c h5{margin:10px 0 4px;font:600 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
#painel-clientes .fv2-reu-mais-c p{margin:0 0 6px}
#painel-clientes .fv2-reu-mais-c .reu-sug{margin:0;padding:0;border:0;border-radius:0;background:none;box-shadow:none}
#painel-clientes .fv2-reu-mais-c .reu-sug > h5:first-child{display:none}
#painel-clientes .fv2-reu-mais-c .reu-sug > .d3v-btn{margin-top:8px}
#painel-clientes .fv2-reu-pe{flex:none;display:flex;align-items:center;gap:10px;min-height:52px;padding:0 16px;box-sizing:border-box;border-top:1px solid var(--d3-divisa);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
#painel-clientes .fv2-reu-estado{flex:1 1 auto;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#painel-clientes .fv2-reu-estado > b{font-weight:600;color:var(--d3-tinta)}
#painel-clientes .fv2-reu-mic{flex:none;display:grid;place-items:center;width:22px;height:22px;border-radius:7px;background:var(--d3-veu-forte);color:var(--d3-tinta)}
#painel-clientes .fv2-reu-mic.on{background:var(--d3-agente);color:var(--d3-contra,var(--d3-escuro-texto))}
#painel-clientes .fv2-reu-mic > svg{width:12px;height:12px;fill:none;stroke:currentColor;stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round}
#painel-clientes .fv2-reu-bts{flex:none;display:inline-flex;gap:8px}
#painel-clientes .fv2-reu-bts > a.d3v-btn{text-decoration:none}
#painel-clientes .fv2-reu-lin .fv2-tb-txt{color:var(--d3-rotulo)}
#painel-clientes .fv2-reu-dia{flex:0 0 76px;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);font-variant-numeric:tabular-nums}
#painel-clientes .fv2-duas > .fv2-lado div.d3m-vlin:hover{background:var(--d3-fume-veu)}
#painel-clientes .fv2-lado a.d3m-vlin{text-decoration:none}

/* 5 · Aba Onboarding: o questionário por parte, com a marca de respondida, a pergunta e a resposta. */
#painel-clientes .fv2-onb-sec{display:flex;align-items:center;justify-content:space-between;gap:10px;min-height:36px;padding:0 16px;box-sizing:border-box;border-top:1px solid var(--d3-divisa);background:var(--d3-veu);font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
#painel-clientes .fv2-onb-sec > b{font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}
#painel-clientes .fv2-onb-lin{align-items:flex-start;min-height:40px;padding-top:10px;padding-bottom:10px}
#painel-clientes .fv2-onb-marca{flex:none;display:grid;place-items:center;width:18px;height:18px;box-sizing:border-box;border:1.5px solid var(--d3-meta);border-radius:50%}
#painel-clientes .fv2-onb-lin.ok > .fv2-onb-marca{border-color:var(--d3-pronto);background:var(--d3-pronto);color:var(--d3-contra,var(--d3-escuro-texto))}
#painel-clientes .fv2-onb-marca > svg{width:10px;height:10px;fill:none;stroke:currentColor;stroke-width:3.4;stroke-linecap:round;stroke-linejoin:round}
#painel-clientes .fv2-onb-q{flex:0 0 42%;min-width:0;color:var(--d3-tinta)}
#painel-clientes .fv2-onb-r{flex:1 1 0;min-width:0;color:var(--d3-tinta);overflow-wrap:anywhere}
#painel-clientes .fv2-onb-lin.falta > .fv2-onb-r{color:var(--d3-rotulo)}

/* 6 · Aba Ecossistema: cada sistema numa linha, com o selo, a situação, o que falta e o botão que resolve. */
#painel-clientes .fv2-eco-lin{min-height:64px;gap:10px}
#painel-clientes .fv2-selo{flex:none;display:grid;place-items:center;width:22px;height:22px;border-radius:7px;background:var(--d3-pronto);color:var(--d3-contra,var(--d3-escuro-texto))}
#painel-clientes .fv2-selo.a{background:var(--d3-ajuste-claro);color:var(--d3-tinta-fixa)}
#painel-clientes .fv2-selo > svg{width:12px;height:12px;fill:none;stroke:currentColor;stroke-width:2.6;stroke-linecap:round;stroke-linejoin:round}
#painel-clientes .fv2-eco-c-selo{flex:0 0 22px}
#painel-clientes .fv2-eco-nome{flex:0 0 290px;min-width:0;color:var(--d3-rotulo);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#painel-clientes .fv2-eco-nome > b{font-weight:600;color:var(--d3-tinta)}
#painel-clientes .fv2-eco-sit{flex:0 0 150px;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#painel-clientes .fv2-eco-lin > .fv2-eco-sit.g{color:var(--d3-pronto)}
#painel-clientes .fv2-eco-lin > .fv2-eco-sit.a{color:var(--d3-ambar)}
#painel-clientes .fv2-eco-det{flex:1 1 0;min-width:0;color:var(--d3-rotulo);overflow:hidden}
#painel-clientes .fv2-eco-lin > .fv2-eco-det{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;line-clamp:2}
#painel-clientes .fv2-eco-th > .fv2-eco-nome,#painel-clientes .fv2-eco-th > .fv2-eco-det{color:inherit}
#painel-clientes .fv2-eco-lin > .d3v-btn{flex:none;text-decoration:none}
#painel-clientes .fv2-eco-pe > .fv2-eco-conta{cursor:default}
#painel-clientes .fv2-eco-pe > .fv2-eco-conta:hover{color:var(--d3-rotulo)}

/* 7 · Aba Cérebro: o que o VYBES sabe (o perfil, as cores e os quatro números), as regras de arte e os registros. */
#painel-clientes .fv2-cb-alto{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,.8fr);border-top:1px solid var(--d3-divisa)}
#painel-clientes .fv2-cb-quem{display:flex;flex-direction:column;gap:4px;min-width:0;padding:14px 16px;font:400 var(--d3-fs-apoio)/1.45 var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
#painel-clientes .fv2-cb-quem > b{font:600 20px/1.2 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.01em;color:var(--d3-tinta);-webkit-text-fill-color:var(--d3-tinta);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#painel-clientes .fv2-cb-quem > p{margin:0;font:400 var(--d3-fs-texto)/1.45 var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}
#painel-clientes .fv2-cb-cores{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));align-content:center;gap:10px 16px;padding:14px 16px;border-left:1px solid var(--d3-divisa)}
#painel-clientes .fv2-cb-cores > span{display:flex;align-items:center;gap:10px;min-width:0;font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);white-space:nowrap}
#painel-clientes .fv2-cb-cores > span > em{min-width:0;font-style:normal;overflow:hidden;text-overflow:ellipsis}
#painel-clientes .fv2-cb-cores > span > i{flex:none;width:28px;height:28px;border-radius:8px;box-shadow:inset 0 0 0 1px var(--d3-veu-forte)}
#painel-clientes .fv2-cb-nums{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border-top:1px solid var(--d3-divisa)}
#painel-clientes .fv2-cb-num{display:flex;flex-direction:column;gap:2px;min-width:0;padding:12px 16px;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
#painel-clientes .fv2-cb-num + .fv2-cb-num{border-left:1px solid var(--d3-divisa)}
#painel-clientes .fv2-cb-num > b{font:600 var(--d3-fs-numero)/1.1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.02em;color:var(--d3-tinta);-webkit-text-fill-color:currentColor;font-variant-numeric:tabular-nums}
#painel-clientes .fv2-cb-num.r > b{color:var(--d3-perigo)}
#painel-clientes .fv2-cb-num.a > b{color:var(--d3-ambar)}
#painel-clientes .fv2-cb-regras{flex:0 1 auto;min-height:96px}
#painel-clientes .fv2-cb-regras > .fv2-linhas{flex:0 1 auto}
#painel-clientes .fv2-pt-g{flex:none;width:6px;height:6px;border-radius:50%;background:var(--d3-pronto)}
#painel-clientes .fv2-reg > .reg-item{margin:0;padding:0;border:0;background:none}
#painel-clientes .fv2-reg summary.fv2-tb-lin{cursor:pointer}
#painel-clientes .fv2-reg summary.fv2-tb-lin::-webkit-details-marker{display:none}
#painel-clientes .fv2-reg summary.fv2-tb-lin:hover{background:var(--d3-veu)}
#painel-clientes .fv2-reg summary > small{flex:none;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);white-space:nowrap}
#painel-clientes .fv2-reg-c{padding:4px 16px 14px;font:400 var(--d3-fs-texto)/1.5 var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}
#painel-clientes .fv2-reg-c > p{margin:0 0 6px}
#painel-clientes .fv2-reg-c > h5{margin:10px 0 4px;font:600 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
#painel-clientes .fv2-reg-c > pre{margin:0;padding:10px;border-radius:var(--d3-r-caixa);background:var(--d3-veu);font:400 var(--d3-fs-apoio)/1.5 ui-monospace,Menlo,Consolas,monospace;white-space:pre-wrap;overflow-wrap:anywhere}

/* 8 · Aba Financeiro (só donos): Contrato, Custo e Margem no alto; o pagamento e as datas embaixo. */
#painel-clientes .fv2-fin-tres{flex:none;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
#painel-clientes .fv2-fin-cartao{align-items:flex-start;gap:4px;min-height:172px;padding:16px;font:400 var(--d3-fs-apoio)/1.45 var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
#painel-clientes .fv2-fin-rot{font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}
#painel-clientes .fv2-fin-num{font:600 24px/1.2 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.02em;color:var(--d3-tinta);-webkit-text-fill-color:currentColor;font-variant-numeric:tabular-nums}
#painel-clientes .fv2-fin-num.sem{color:var(--d3-rotulo)}
#painel-clientes .fv2-fin-num.r{color:var(--d3-perigo)}
#painel-clientes .fv2-fin-cartao > p{margin:0}
#painel-clientes .fv2-fin-cartao > .d3v-btn{margin-top:auto}
#painel-clientes .fv2-fin-pag > .fv2-fin-grade{flex:none;grid-template-columns:repeat(4,minmax(0,1fr))}
#painel-clientes .fv2-fin-pag .fv2-fin-campo:last-child{border-right:0}
#painel-clientes .fv2-fin-pag .fv2-fin-campo > b{font:600 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif)}
#painel-clientes .fv2-fin-pag .fv2-est{font:inherit}
#painel-clientes .fv2-fin-obs{flex:none;display:flex;flex-direction:column;gap:4px;margin:0;padding:12px 16px;border-top:1px solid var(--d3-divisa);font:400 var(--d3-fs-texto)/1.5 var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}
#painel-clientes .fv2-fin-pag > .fv2-vazio{border-top:1px solid var(--d3-divisa)}

/* 9 · Janela baixa: o vazio perde o ícone, o número do laranja encolhe e as folhas dividem melhor a altura. */
@media (max-height:820px) and (min-width:1181px){
  #painel-clientes .fv2-cheia{min-height:112px}
  #painel-clientes .fv2-vazio-ico{display:none}
  #painel-clientes .fv2-vazio > b{margin-top:0}
  #painel-clientes .fv2-duas > .fv2-lado{gap:8px}
  #painel-clientes .fv2-lar-aba{gap:6px;padding-top:12px;padding-bottom:12px}
  #painel-clientes .fv2-lar-aba .d3m-lar-num{font-size:40px}
  #painel-clientes .fv2-lar-aba .d3m-lar-bts{margin-top:6px}
  #painel-clientes .fv2-barra-lin{height:21px}
  #painel-clientes .fv2-fin-cartao{min-height:148px}
}
/* 10 · Telas menores: uma coluna (a ficha rola por dentro da janela) e a linha da lista em dois andares. */
@media (max-width:1180px){
  #painel-clientes #client-master-detail > .fv2-aba{height:auto}
  #painel-clientes .fv2-duas{grid-template-columns:minmax(0,1fr);height:auto}
  /* Numa coluna, o cartão laranja vem primeiro, depois as folhas e por último a consulta. */
  #painel-clientes .fv2-duas > .fv2-col,#painel-clientes .fv2-duas > .fv2-lado{display:contents}
  #painel-clientes .fv2-duas .fv2-lar-aba,#painel-clientes .fv2-duas .fv2-calmo{order:-1}
  #painel-clientes .fv2-duas .d3m-cons{color:var(--d3-fume-texto);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif)}
  #painel-clientes .fv2-reu,#painel-clientes .fv2-cb-regras{flex:none}
  #painel-clientes .fv2-duas .fv2-linhas{max-height:420px}
  #painel-clientes .fv2-cheia{flex:none}
  #painel-clientes .fv2-op-linhas{flex:none;max-height:440px}
}
@media (max-width:900px){
  #painel-clientes .fv2-op-cab{flex-wrap:wrap;row-gap:4px;padding-top:8px;padding-bottom:8px}
  #painel-clientes .fv2-op-cab > .cv2-filtros{margin-left:0;max-width:100%;overflow-x:auto;scrollbar-width:none}
  #painel-clientes .fv2-op-th{display:none}
  #painel-clientes .fv2-op-lin{flex-wrap:wrap;height:auto;row-gap:0;padding:6px 14px}
  #painel-clientes .fv2-op-mini{display:none}
  #painel-clientes .fv2-op-nome{flex:1 1 calc(100% - 26px)}
  #painel-clientes .fv2-op-lin > .fv2-op-c-st{flex:1 1 0;margin-left:26px}
  #painel-clientes .fv2-op-lin > .fv2-op-c-prazo{display:none}
  #painel-clientes .fv2-op-data.fv2-op-c-veiculacao{flex:0 0 auto}
  #painel-clientes .fv2-op-pe{flex-wrap:wrap;row-gap:6px;padding-top:8px;padding-bottom:8px}
  #painel-clientes .fv2-op-pe-bts{flex-wrap:wrap}
}
@media (max-width:760px){
  #painel-clientes .fv2-duas .cv2-cab{flex-wrap:wrap;row-gap:2px;min-height:44px;padding:8px 14px}
  #painel-clientes .fv2-duas .cv2-cab > h3{flex:1 1 100%;white-space:normal}
  #painel-clientes .fv2-duas .cv2-cab > :is(.fv2-cab-nota,.fv2-cab-lado){margin-left:0}
  #painel-clientes .fv2-duas .cv2-cab > .fv2-cab-acao{margin-left:auto}
  #painel-clientes .fv2-tb-lin{padding-left:14px;padding-right:14px}
  #painel-clientes .fv2-reu-2{grid-template-columns:minmax(0,1fr)}
  #painel-clientes .fv2-reu-parte + .fv2-reu-parte{border-left:0;border-top:1px solid var(--d3-divisa)}
  #painel-clientes .fv2-reu-pe{flex-wrap:wrap;row-gap:8px;padding:10px 14px}
  #painel-clientes .fv2-reu-estado{flex:1 1 calc(100% - 40px);white-space:normal}
  #painel-clientes .fv2-reu-lin{flex-wrap:wrap;row-gap:2px;padding-top:8px;padding-bottom:8px}
  #painel-clientes .fv2-reu-lin > .fv2-tb-txt{flex:1 1 calc(100% - 100px)}
  #painel-clientes .fv2-onb-lin{flex-wrap:wrap;row-gap:2px}
  #painel-clientes .fv2-onb-q{flex:1 1 calc(100% - 32px)}
  #painel-clientes .fv2-onb-r{flex:1 1 100%;margin-left:30px}
  #painel-clientes .fv2-eco-th{display:none}
  #painel-clientes .fv2-eco-lin{flex-wrap:wrap;row-gap:4px;min-height:0;padding-top:10px;padding-bottom:10px}
  #painel-clientes .fv2-eco-lin > .fv2-eco-nome{flex:1 1 calc(100% - 34px)}
  #painel-clientes .fv2-eco-lin > .fv2-eco-sit{flex:1 1 calc(100% - 34px);margin-left:32px}
  #painel-clientes .fv2-eco-lin > .fv2-eco-det{flex:1 1 100%;margin-left:32px}
  #painel-clientes .fv2-eco-lin > .d3v-btn{margin-left:32px}
  #painel-clientes .fv2-eco-pe{flex-wrap:wrap;row-gap:4px;padding-top:8px;padding-bottom:8px;overflow:visible}
  #painel-clientes .fv2-cb-alto{grid-template-columns:minmax(0,1fr)}
  #painel-clientes .fv2-cb-cores{border-left:0;border-top:1px solid var(--d3-divisa)}
  #painel-clientes .fv2-cb-nums{grid-template-columns:repeat(2,minmax(0,1fr))}
  #painel-clientes .fv2-cb-num:nth-child(3){border-left:0}
  #painel-clientes .fv2-cb-num:nth-child(n+3){border-top:1px solid var(--d3-divisa)}
  #painel-clientes .fv2-reg summary > small{display:none}
  #painel-clientes .fv2-fin-tres{grid-template-columns:minmax(0,1fr)}
  #painel-clientes .fv2-fin-cartao{min-height:0}
  #painel-clientes .fv2-fin-cartao > .d3v-btn{margin-top:10px}
  #painel-clientes .fv2-fin-pag > .fv2-fin-grade{grid-template-columns:repeat(2,minmax(0,1fr))}
}

/* ===== padrao-v2/zm-c-agenda.css ===== */
/* DIREÇÃO V2 · AGENDA E CAPTAÇÕES (pranchas V2-M-Agenda e V2-M-Agenda-Roteiros, 16/11/2026). A janela é vidro fumê; a
   semana é uma grade de horas numa folha clara e a consulta fica direto no vidro. Vale no computador (data-agv2 no body,
   posto por renderProductionCommand); no celular a Agenda segue como estava. */
body.mundo.mundo-modulo[data-modo="producao"][data-agv2] #mundo-moldura{border-radius:20px;background:var(--d3-fume);box-shadow:inset 0 0 0 1px var(--d3-fume-borda),0 30px 60px -40px rgba(0,0,0,.6)}
/* A tela ocupa a janela inteira (o corpo da página, que é a janela, é o bloco de referência), sem depender dos respiros
   que o tema antigo força na casa (.container). A casa acompanha a janela para a animação de abrir não dar salto. */
body.mundo.mundo-modulo[data-modo="producao"][data-agv2] .container.pv2-casa{box-sizing:border-box;height:100%;min-height:0;margin:0 -18px}
body.mundo.mundo-modulo[data-modo="producao"][data-agv2]{scrollbar-gutter:auto}
.agv2-tela{position:absolute;inset:0;padding:16px}
/* À direita do topo ficam os dois botões da janela (tela cheia e fechar). */
.agv2-tela > .d3m-c-topo{padding-right:104px}
/* A régua e o "De olho" são do Painel de trabalho: na Agenda não aparecem. */
body.mundo.mundo-modulo[data-modo="producao"] :is(#pv2-regua,#pv2-pe){display:none}
.agv2-outra{flex:1 1 0;padding:16px;overflow:auto}

/* As cores da agenda: captação verde, reunião roxa, compromisso azul e a gravação sem fechar no laranja. */
.agv2 .t-captacao{--agv2-cor:var(--d3-mod-vybe);--agv2-clara:var(--d3-mod-vybe-claro)}
.agv2 .t-reuniao{--agv2-cor:var(--d3-agente-texto);--agv2-clara:var(--d3-agente-claro)}
.agv2 .t-outro{--agv2-cor:var(--d3-info);--agv2-clara:var(--d3-info-claro)}
.agv2 .fechar{--agv2-cor:var(--d3-acao);--agv2-clara:var(--d3-acao-claro)}
.agv2-folha.carregando{opacity:.7}
.agv2-legenda{flex:none;display:inline-flex;align-items:center;gap:2px}
.agv2-leg{appearance:none;display:inline-flex;align-items:center;gap:6px;height:24px;margin:0;padding:0 6px;border:0;border-radius:6px;background:none;color:var(--d3-tinta);font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);white-space:nowrap;cursor:pointer}
.agv2-leg:hover{background:var(--d3-veu)}
.agv2-leg > i{flex:none;width:10px;height:10px;border-radius:3px;background:var(--agv2-cor)}
.agv2-leg[aria-checked="false"]{color:var(--d3-rotulo);text-decoration:line-through}
.agv2-leg[aria-checked="false"] > i{background:var(--d3-veu-forte)}
.agv2-leg:focus-visible{outline:2px solid var(--d3-acao);outline-offset:1px}
.agv2-aviso{flex:none;margin:0;padding:6px 16px;background:var(--d3-ajuste-veu);color:var(--d3-ajuste);font-size:var(--d3-fs-apoio)}

/* A semana em grade de horas. --agv2-hora é a altura de uma hora: a grade enche a folha (altura da folha dividida pelas
   horas) e só rola por dentro quando a hora ficaria com menos de 36 px. */
.agv2-semana{flex:1 1 0;display:flex;flex-direction:column;min-height:0;padding:0 16px 16px}
.agv2-cab{flex:none;display:grid;grid-template-columns:44px repeat(7,minmax(0,1fr));height:36px;border-top:1px solid var(--d3-divisa)}
.agv2-dia{appearance:none;display:flex;align-items:center;gap:6px;min-width:0;margin:0;padding:0 4px 0 6px;border:0;border-left:1px solid var(--d3-divisa);border-radius:0;background:none;color:var(--d3-tinta);font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
.agv2-dia:hover{background:var(--d3-veu)}
.agv2-dia > b{flex:none;font-weight:500;white-space:nowrap}
.agv2-dia.hoje > b{display:inline-flex;align-items:center;height:22px;padding:0 8px;border-radius:7px;background:var(--d3-tinta);color:var(--d3-escuro-texto);font-weight:600}
.agv2-dia > span{min-width:0;font-size:var(--d3-fs-mini);color:var(--d3-rotulo);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.agv2-dia:focus-visible{outline:2px solid var(--d3-acao);outline-offset:-2px}
.agv2-todo{flex:none;display:grid;grid-template-columns:44px repeat(7,minmax(0,1fr));border-top:1px solid var(--d3-divisa)}
.agv2-todo > span{align-self:center;font-size:var(--d3-fs-mini);color:var(--d3-rotulo)}
.agv2-todo > div{display:flex;flex-direction:column;gap:2px;min-width:0;padding:3px;border-left:1px solid var(--d3-divisa)}
.agv2-todo .agv2-ev{position:static;width:100%;height:24px}
.agv2-rola{flex:1 1 0;min-height:0;overflow-x:hidden;overflow-y:auto;scrollbar-width:thin;border-top:1px solid var(--d3-divisa);container-type:size}
.agv2-grade{position:relative;display:grid;grid-template-columns:44px repeat(7,minmax(0,1fr));--agv2-hora:max(36px,calc(100cqh / var(--agv2-n,11)));height:calc(var(--agv2-hora) * var(--agv2-n,11))}
.agv2-horas{position:relative}
.agv2-horas > span{position:absolute;left:0;margin-top:4px;font-size:var(--d3-fs-mini);color:var(--d3-rotulo);font-variant-numeric:tabular-nums}
.agv2-col{position:relative;min-width:0;border-left:1px solid var(--d3-divisa);background-image:repeating-linear-gradient(180deg,transparent 0,transparent calc(var(--agv2-hora) - 1px),var(--d3-divisa) calc(var(--agv2-hora) - 1px),var(--d3-divisa) var(--agv2-hora))}
.agv2-col.feriado{background-color:var(--d3-veu)}
.agv2-col.alvo{background-color:var(--d3-veu-forte)}
.agv2-ev{appearance:none;position:absolute;display:flex;flex-direction:column;align-items:flex-start;gap:2px;min-width:0;margin:0;padding:6px 8px;box-sizing:border-box;border:0;border-radius:8px;overflow:hidden;background:var(--agv2-cor);box-shadow:none;color:var(--d3-escuro-texto);font:400 var(--d3-fs-mini)/1.25 var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
.agv2-ev:hover{filter:brightness(1.1)}
.agv2-ev > b{flex:none;max-width:100%;font-size:var(--d3-fs-apoio);font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.agv2-ev-s{color:inherit;flex:0 1 auto;max-width:100%;min-height:0;overflow:hidden;font-size:var(--d3-fs-mini)}
.agv2-ev-h{flex:none;max-width:100%;font-variant-numeric:tabular-nums;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.agv2-ev-h > b{font-weight:600}
.agv2-ev.curto{justify-content:center;padding:0 8px}
.agv2-ev:is(.curto,.baixo) > :is(.agv2-selo,.agv2-ev-s){display:none}
.agv2-ev.medio > .agv2-ev-s{display:none}
.agv2-ev.baixo{gap:0;padding:2px 8px}
.agv2-selo{flex:none;display:inline-block;max-width:100%;height:18px;margin-top:auto;padding:0 7px;box-sizing:border-box;border-radius:999px;background:var(--d3-escuro-texto);color:var(--d3-tinta-fixa);font:500 var(--d3-fs-mini)/18px var(--vv-texto,Inter,sans-serif);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.agv2-ev.sel{outline:2px solid var(--d3-tinta);outline-offset:1px;z-index:2}
.agv2-ev:focus-visible{outline:2px solid var(--d3-acao);outline-offset:1px;z-index:2}
.agv2-agora{position:absolute;left:0;right:0;z-index:3;height:2px;margin-top:-1px;background:var(--d3-perigo);pointer-events:none}
.agv2-agora::before{content:"";position:absolute;left:-4px;top:-3px;width:8px;height:8px;border-radius:50%;background:var(--d3-perigo)}

/* A consulta no vidro. */
.agv2-laranja{flex:none;min-height:216px}
.agv2-hoje-lin > i{flex:none;width:3px;height:18px;border-radius:2px;background:var(--agv2-clara)}
.agv2-abrir{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(0,1fr);gap:6px}
.agv2-abrir > .d3m-cons-cab{grid-column:1 / -1}
.agv2-hoje-h{flex:none;font-weight:600;font-variant-numeric:tabular-nums}
/* Janela baixa (1366 × 768): o cartão laranja encolhe para a consulta inteira caber sem rolar. */
@media (max-height:820px){.agv2-laranja,.rotv2-laranja{min-height:0}.agv2-lado{gap:10px}.agv2-lado .d3m-vlin{height:34px}}
/* "O que precisa de você" (o inspetor de sempre) abre no lugar da consulta, numa folha que rola por dentro. */
.agv2-inspetor{padding:14px;overflow-y:auto;scrollbar-width:thin}
/* Mês e Dia ainda não têm prancha: seguem com o desenho de antes, dentro da folha. */
.agv2-antiga{flex:1 1 0;min-height:0;padding:0 16px 16px;overflow:auto;scrollbar-width:thin}

/* ROTEIROS (prancha V2-M-Agenda-Roteiros). Cada roteiro é uma folha aberta; a lista rola por dentro. */
.rotv2-lista{display:flex;flex-direction:column;gap:12px;min-width:0;min-height:0;overflow-y:auto;scrollbar-width:thin;border-radius:16px}
.rotv2-cartao{flex:none}
.rotv2-cab{display:flex;align-items:center;gap:10px;min-width:0;min-height:52px;padding:0 16px;box-sizing:border-box}
.rotv2-tit{flex:1 1 auto;display:flex;flex-direction:column;gap:2px;min-width:0}
.rotv2-tit > b{font:600 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.rotv2-sub{font:400 var(--d3-fs-apoio)/1.3 var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.rotv2-aviso{flex:none;font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-ambar);white-space:nowrap}
.rotv2-sem{background:none;box-shadow:inset 0 0 0 1px var(--d3-meta);color:var(--d3-rotulo)}
.rotv2-corpo{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);border-top:1px solid var(--d3-divisa)}
.rotv2-corpo > section{min-width:0;padding:12px 16px 14px}
.rotv2-corpo > section + section{border-left:1px solid var(--d3-divisa)}
.rotv2-rot{display:block;margin:0 0 6px;font:400 var(--d3-fs-apoio)/1.3 var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
.rotv2-corpo ul{display:flex;flex-direction:column;gap:6px;margin:0;padding:0;list-style:none}
.rotv2-corpo > section:first-child li{position:relative;padding-left:15px}
.rotv2-corpo > section:first-child li::before{content:"";position:absolute;left:0;top:6px;width:6px;height:6px;border-radius:50%;background:var(--d3-meta)}
.rotv2-cont > li{display:flex;align-items:baseline;justify-content:space-between;gap:10px;min-width:0}
.rotv2-cont > li > span:first-child{min-width:0;color:var(--d3-rotulo);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.rotv2-cont > li > span:first-child > b{font-weight:600;color:var(--d3-tinta)}
.rotv2-cont > li > .d3v-st{flex:none;max-width:45%}
.rotv2-nada{margin:0;color:var(--d3-rotulo)}
.rotv2-nada.a{color:var(--d3-ambar)}
.rotv2-mes{flex:none;margin:4px 0 -4px;font:600 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-texto)}
.rotv2-mes > span{font-weight:400;color:var(--d3-fume-apagado)}
.rotv2-laranja{flex:none;min-height:216px}
.rotv2-clientes-lista{display:flex;flex-direction:column;gap:6px}

@media (max-width:1100px){
  body.mundo.mundo-modulo[data-modo="producao"][data-agv2] .container.pv2-casa{height:auto}
  body.mundo.mundo-modulo[data-modo="producao"][data-agv2]{scrollbar-gutter:stable}
  .agv2-tela{position:static;margin:0 -30px;padding:10px 16px 16px}
  .agv2-tela > .d3m-c-topo{padding-right:0}
  .agv2-tela > .d3m-c-topo > .d3m-c-tit{flex:1 1 100%;padding-right:104px;box-sizing:border-box}
  .agv2-folha{height:560px}
  .rotv2-lista{overflow:visible}
  .agv2-outra{flex:none}
}
@media (max-width:900px){
  body.mundo.mundo-modulo[data-modo="producao"][data-agv2] .container.pv2-casa{margin-left:-10px;margin-right:-10px}
}

/* ===== padrao-v2/zm-c-base.css ===== */
/* DIREÇÃO V2 · MÓDULOS DO GRUPO C (Agenda, Planejamentos, Impressões, Projetos, Fornecedores, Creators e Conversas).
   Peças locais do esqueleto das pranchas V2-M-*, com o prefixo .d3m-c- (para unificar depois com as de z-direcao.css):
   a tela (.d3m-c-tela), o topo da janela no vidro (.d3m-c-topo: título com seta, linha de apoio, segmento, botão de
   ícone e botão branco), o corpo em duas colunas (.d3m-c-corpo: o trabalho numa folha e a consulta de 316 px direto no
   vidro) e a folha clara (.d3m-c-folha). Só tokens --d3-*; sem !important. */
.d3m-c-tela{display:flex;flex-direction:column;gap:16px;min-width:0;min-height:0;box-sizing:border-box;color:var(--d3-fume-texto);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);text-align:left}
.d3m-c-topo{flex:none;display:flex;align-items:center;gap:8px;min-width:0;min-height:48px;color:var(--d3-fume-texto)}
.d3m-c-tit{display:flex;flex-direction:column;gap:3px;min-width:0;margin-right:auto}
.d3m-c-h{margin:0;font:600 24px/1.1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.02em;white-space:nowrap;color:var(--d3-fume-texto)}
.d3m-c-sub{font:400 var(--d3-fs-apoio)/1.2 var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-apagado);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-c-troca{position:relative;align-self:flex-start}
.d3m-c-troca > summary{display:inline-flex;align-items:center;gap:6px;list-style:none;border-radius:var(--d3-r-botao);cursor:pointer}
.d3m-c-troca > summary::-webkit-details-marker{display:none}
.d3m-c-troca > summary > svg{flex:none;width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.d3m-c-troca > summary:focus-visible{outline:2px solid currentColor;outline-offset:3px}
.d3m-c-pop{position:absolute;z-index:40;left:0;top:calc(100% + 6px);display:flex;flex-direction:column;gap:2px;min-width:220px;padding:6px;box-sizing:border-box;border-radius:12px;background:var(--d3-fume-painel);box-shadow:inset 0 0 0 1px var(--d3-fume-borda),0 18px 40px -18px rgba(0,0,0,.7)}
.d3m-c-pop > button{appearance:none;display:flex;align-items:center;gap:8px;height:32px;margin:0;padding:0 10px;border:0;border-radius:var(--d3-r-botao);background:none;color:var(--d3-fume-texto);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);text-align:left;white-space:nowrap;cursor:pointer}
.d3m-c-pop > button:hover{background:var(--d3-fume-veu)}
.d3m-c-pop > button[aria-checked="true"]{background:var(--d3-fume-veu);font-weight:600}
.d3m-c-pop > button:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:-2px}
.d3m-c-pop-rot{padding:6px 10px 4px;font:400 var(--d3-fs-mini)/1.3 var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-apagado)}
.d3m-c-seg{flex:none;display:inline-flex;gap:2px;height:36px;padding:3px;box-sizing:border-box;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu)}
.d3m-c-seg > button{appearance:none;display:inline-flex;align-items:center;gap:6px;height:30px;margin:0;padding:0 12px;border:0;border-radius:var(--d3-r-botao);background:none;box-shadow:none;color:var(--d3-fume-texto);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);white-space:nowrap;cursor:pointer}
.d3m-c-seg > button:hover{background:var(--d3-fume-veu)}
.d3m-c-seg > button[aria-checked="true"]{background:var(--d3-fume-texto);color:var(--d3-tinta-fixa);font-weight:600}
.d3m-c-seg > button > b{font-weight:400;color:var(--d3-fume-apagado);font-variant-numeric:tabular-nums}
.d3m-c-seg > button[aria-checked="true"] > b{color:var(--d3-rotulo-fixo)}
.d3m-c-ico{appearance:none;flex:none;display:grid;place-items:center;width:34px;height:34px;margin:0;padding:0;border:0;border-radius:var(--d3-r-botao);background:var(--d3-fume-veu-forte);color:var(--d3-fume-texto);cursor:pointer}
.d3m-c-ico:hover{background:var(--d3-fume-borda)}
.d3m-c-ico > svg,.d3m-c-btn > svg,.d3m-c-busca > svg{flex:none;width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.d3m-c-btn{appearance:none;flex:none;display:inline-flex;align-items:center;justify-content:center;gap:6px;height:34px;margin:0;padding:0 14px;box-sizing:border-box;border:0;border-radius:var(--d3-r-botao);background:var(--d3-fume-texto);box-shadow:none;color:var(--d3-tinta-fixa);font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);text-decoration:none;white-space:nowrap;cursor:pointer}
.d3m-c-btn:hover{background:var(--d3-folha)}
.d3m-c-btn.v{background:var(--d3-fume-veu);box-shadow:inset 0 0 0 1px var(--d3-fume-borda);color:var(--d3-fume-texto);font-weight:500}
.d3m-c-btn.v:hover{background:var(--d3-fume-veu-forte)}
/* Na folha clara: contorno fino, 28 px. */
.d3m-c-btn.c{height:28px;padding:0 10px;background:none;box-shadow:inset 0 0 0 1px var(--d3-meta);color:var(--d3-tinta);font-weight:500}
.d3m-c-btn.c:hover{background:var(--d3-veu)}
.d3m-c-btn.c.k{background:var(--d3-tinta);box-shadow:none;color:var(--d3-escuro-texto);font-weight:600}
.d3m-c-btn.c.k:hover{background:var(--d3-texto2)}
:is(.d3m-c-ico,.d3m-c-btn,.d3m-c-seg > button):focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}
.d3m-c-btn.c:focus-visible{outline-color:var(--d3-acao)}
:is(.d3m-c-ico,.d3m-c-btn):disabled{opacity:.6;cursor:default}
/* A busca do topo: um ícone de 34 px; no foco (e enquanto tem texto) abre o campo. O campo é claro com letra escura, como
   o tema antigo obriga os campos da janela a ser. */
.d3m-c-busca{flex:none;display:flex;align-items:center;height:34px;border-radius:var(--d3-r-botao);background:var(--d3-fume-veu-forte);color:var(--d3-fume-texto);cursor:pointer}
.d3m-c-busca > svg{margin:0 9px;pointer-events:none}
:is(#agv2-topo,#vv-planejamentos,#vv-impressoes,#vv-pessoas,#vv-comercial,#vv-whatsapp) .d3m-c-busca.d3m-c-busca > input{flex:none;width:0;min-width:0;height:28px;margin:0;padding:0;box-sizing:border-box;opacity:0;font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);transition:width .2s}
:is(#agv2-topo,#vv-planejamentos,#vv-impressoes,#vv-pessoas,#vv-comercial,#vv-whatsapp) .d3m-c-busca.d3m-c-busca > input:is(:focus,:not(:placeholder-shown)){width:210px;margin-right:3px;padding:0 10px;opacity:1;outline:0}
:is(#agv2-topo,#vv-planejamentos,#vv-impressoes,#vv-pessoas,#vv-comercial,#vv-whatsapp) .d3m-c-busca.d3m-c-busca{display:flex;flex-direction:row;align-items:center;gap:0;margin:0}
.d3m-c-busca:focus-within{box-shadow:inset 0 0 0 2px var(--d3-fume-texto)}
/* A janela de módulo (as que abrem por cima do mundo: Planejamentos, Impressões, Projetos, Fornecedores, Creators e
   Conversas) vira vidro fumê quando a tela V2 está nela (.d3m-c-janela, posta pelo módulo). A posição continua a do tema. */
:is(#vv-planejamentos,#vv-impressoes,#vv-pessoas,#vv-comercial,#vv-whatsapp).d3m-c-janela.d3m-c-janela{display:flex;flex-direction:column;gap:16px;padding:16px;box-sizing:border-box;border:0;background:var(--d3-fume);box-shadow:inset 0 0 0 1px var(--d3-fume-borda),0 30px 60px -40px rgba(0,0,0,.6);color:var(--d3-fume-texto);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);overflow:hidden}
:is(#vv-planejamentos,#vv-impressoes,#vv-pessoas,#vv-comercial,#vv-whatsapp).d3m-c-janela[hidden]{display:none}
/* Menus do topo (details): o botão é o summary; a lista abre embaixo, alinhada à direita com .dir. */
.d3m-c-menu{flex:none;position:relative}
.d3m-c-menu > summary{list-style:none}
.d3m-c-menu > summary::-webkit-details-marker{display:none}
.d3m-c-pop.dir{left:auto;right:0;max-height:min(420px,60vh);overflow-y:auto;scrollbar-width:thin}
.d3m-c-pop > button > small{margin-left:auto;padding-left:12px;font-size:var(--d3-fs-mini);color:var(--d3-fume-apagado)}
.d3m-c-ico.on{background:var(--d3-fume-texto);color:var(--d3-tinta-fixa)}
/* O fechar da janela, no fim do topo: o mesmo botão de ícone no vidro. */
.d3m-c-topo > .d3m-c-x{appearance:none;flex:none;display:grid;place-items:center;position:static;width:34px;height:34px;margin:0;padding:0;border:0;border-radius:var(--d3-r-botao);background:var(--d3-fume-veu-forte);box-shadow:none;color:var(--d3-fume-texto);cursor:pointer}
.d3m-c-topo > .d3m-c-x:hover{background:var(--d3-fume-borda)}
.d3m-c-topo > .d3m-c-x > svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round}
.d3m-c-topo > .d3m-c-x:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}
/* Fichas na cabeça da folha: texto de 28 px; a escolhida fica no véu forte. */
.d3m-c-abas{flex:none;display:inline-flex;align-items:center;gap:2px}
.d3m-c-abas > button{appearance:none;display:inline-flex;align-items:center;gap:6px;height:28px;margin:0;padding:0 10px;border:0;border-radius:var(--d3-r-botao);background:none;box-shadow:none;color:var(--d3-tinta);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);white-space:nowrap;cursor:pointer}
.d3m-c-abas > button:hover{background:var(--d3-veu)}
.d3m-c-abas > button[aria-checked="true"]{background:var(--d3-veu-forte);font-weight:600}
.d3m-c-abas > button > b{font-weight:400;color:var(--d3-rotulo);font-variant-numeric:tabular-nums}
.d3m-c-abas > button:focus-visible{outline:2px solid var(--d3-acao);outline-offset:1px}
@media (max-width:1100px){:is(#vv-planejamentos,#vv-impressoes,#vv-pessoas,#vv-comercial,#vv-whatsapp).d3m-c-janela.d3m-c-janela{overflow-y:auto}}
/* O texto miúdo dos cartões (com classe, para o cinza do tema antigo não pegar). */
.d3m-c-s{color:inherit}
/* O corpo: o trabalho à esquerda, a consulta de 316 px à direita. Nada rola na janela; só as listas, por dentro. */
.d3m-c-corpo{flex:1 1 0;display:grid;grid-template-columns:minmax(0,1fr) 316px;gap:16px;min-width:0;min-height:0}
.d3m-c-corpo.um{grid-template-columns:minmax(0,1fr)}
.d3m-c-corpo > .d3m-lado{min-height:0;overflow-y:auto;scrollbar-width:none}
.d3m-c-corpo .d3m-vlin > .d3m-vnome{flex:1 1 auto;max-width:none}
.d3m-c-corpo .d3m-vlin > .d3m-vnome > b{font-weight:600}
.d3m-c-corpo .d3m-vlin[aria-checked="true"]{background:var(--d3-folha);color:var(--d3-tinta)}
.d3m-c-corpo .d3m-vlin[aria-checked="true"] :is(.d3m-vn,b.d3m-vn){color:var(--d3-tinta)}
.d3m-c-corpo .d3m-vlin > .d3v-foto{width:22px;height:22px;border-radius:6px;background:var(--d3-fume-veu-forte);color:var(--d3-fume-texto);font-size:10px}
.d3m-c-corpo .d3m-vlin[aria-checked="true"] > .d3v-foto{background:var(--d3-veu-forte);color:var(--d3-tinta)}
.d3m-c-corpo .d3m-vlin > .d3m-vn{min-width:16px}
.d3m-c-folha{display:flex;flex-direction:column;min-width:0;min-height:0;box-sizing:border-box;border-radius:16px;overflow:hidden;background:var(--d3-folha);box-shadow:var(--d3-folha-sombra);color:var(--d3-tinta);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif)}
.d3m-c-folha-cab{flex:none;display:flex;align-items:center;gap:10px;min-width:0;min-height:44px;padding:0 16px;box-sizing:border-box}
.d3m-c-h3{min-width:0;margin:0 auto 0 0;font:600 14px/1.25 var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-c-h3 > span{font-weight:400;color:var(--d3-rotulo)}
.d3m-c-folha.d3v-estado{flex:none;min-height:160px}
.d3m-c-folha.d3v-estado > .d3v-btn{margin-top:8px}
/* Telas menores: uma coluna; a consulta desce para depois do trabalho e a janela rola (como no Hoje, seção 6). */
@media (max-width:1100px){
  .d3m-c-topo{flex-wrap:wrap}
  .d3m-c-corpo{flex:none;grid-template-columns:minmax(0,1fr)}
  .d3m-c-corpo > .d3m-lado{overflow:visible}
}

/* ===== padrao-v2/zm-c-comercial.css ===== */
/* DIREÇÃO V2 · FORNECEDORES (prancha V2-M-Fornecedores, 16/11/2026) e as peças que Fornecedores e Creators dividem (.m2-*).
   A janela (#vv-comercial) ganha .d3m-c-janela (zm-c-base.css) quando uma destas abas está nela, no computador. A folha
   traz uma linha por fornecedor; a consulta, o cartão laranja do Nestor, o mês e os atalhos. Só tokens --d3-*. */
.m2-aviso{flex:none;margin:-8px 0;padding:0;font:600 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-pronto-claro)}
.m2-aviso.erro{color:var(--d3-perigo-vidro)}
.m2-laranja{flex:none;min-height:244px}
.m2-tiles{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px}
.m2-tile{display:flex;flex-direction:column;gap:3px;min-width:0;padding:10px;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu)}
.m2-tile > b{font:600 var(--d3-fs-destaque) var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-texto);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-variant-numeric:tabular-nums}
.m2-tile > span{font-size:var(--d3-fs-apoio);color:var(--d3-fume-apagado);white-space:nowrap}
.m2-nota{margin:0;font:400 var(--d3-fs-apoio)/1.45 var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-apagado)}
.m2-mais > svg{transition:transform .15s}
.m2-mais[aria-expanded="true"] > svg{transform:rotate(90deg)}
.m2-mais-l{display:flex;flex-direction:column;gap:4px;margin-top:4px}
.m2-mais-l > .d3m-vlin{height:30px}
.m2-mais-l > .d3m-vlin[aria-checked="true"]{background:var(--d3-folha);color:var(--d3-tinta)}
.m2-mais-l > .d3m-vlin > .d3m-vn{flex:none;font-weight:600;font-variant-numeric:tabular-nums}
/* O pé "De olho" da folha: os números que filtram a lista. */
.m2-pe{flex:none;display:flex;align-items:center;min-height:44px;margin-top:auto;padding:0 16px;box-sizing:border-box;border-top:1px solid var(--d3-divisa);font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);white-space:nowrap;overflow:hidden}
.m2-pe-rot{margin-right:14px}
.m2-pe > :is(span,button):not(.m2-pe-rot){appearance:none;height:20px;margin:0;padding:0 12px;border:0;border-left:1px solid var(--d3-veu-forte);border-radius:0;background:none;box-shadow:none;color:var(--d3-rotulo);font:inherit;line-height:20px}
.m2-pe > .m2-pe-rot + :is(span,button){padding-left:0;border-left:0}
.m2-pe > button{cursor:pointer}
.m2-pe > button:hover,.m2-pe > button[aria-checked="true"]{color:var(--d3-tinta)}
.m2-pe > button[aria-checked="true"]{text-decoration:underline;text-underline-offset:3px}
.m2-pe > button:focus-visible{outline:2px solid var(--d3-acao);outline-offset:2px}
.m2-pe b{margin-right:3px;font:600 14px var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);font-variant-numeric:tabular-nums}
.m2-pe .g b{color:var(--d3-pronto)}
.m2-pe .a b{color:var(--d3-ambar)}
/* O campo que completa o cadastro no lugar (BV ou contato) e os botões da linha aberta. */
.m2-campo{display:flex;flex-wrap:wrap;align-items:center;gap:8px;min-width:0}
.m2-campo > label{font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}
.m2-campo > label > b{font-weight:600}
:is(#vv-comercial,#vv-whatsapp).d3m-c-janela .m2-campo > input{flex:0 1 240px;width:240px;min-width:0;height:28px;margin:0;padding:0 10px;box-sizing:border-box;border:0;border-radius:var(--d3-r-botao);box-shadow:inset 0 0 0 1px var(--d3-meta);color:var(--d3-tinta);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif)}
:is(#vv-comercial,#vv-whatsapp).d3m-c-janela .m2-campo > input.curto{flex-basis:96px;width:96px}
:is(#vv-comercial,#vv-whatsapp).d3m-c-janela .m2-campo > input:focus-visible{outline:2px solid var(--d3-acao);outline-offset:1px}
.m2-acoes{display:flex;flex-wrap:wrap;gap:6px;margin:0}
.d3m-c-btn.c.ruim{color:var(--d3-perigo)}
.d3m-c-btn.c.k[data-estado="indo"]{opacity:.6;cursor:progress}
.d3m-c-btn.c.k[data-estado="feito"]{background:var(--d3-pronto)}
/* FORNECEDORES: a folha das linhas. */
.fo2-folha{min-height:0}
.fo2-cab,.fo2-lin{display:grid;grid-template-columns:60px minmax(0,1fr) minmax(0,160px) 84px minmax(0,150px) 104px 104px;align-items:center;gap:0 10px;padding:0 16px;box-sizing:border-box}
.fo2-cab{flex:none;height:24px;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);white-space:nowrap}
.fo2-lista{flex:1 1 0;display:flex;flex-direction:column;min-height:0;overflow-y:auto;scrollbar-width:thin}
.fo2-abre{flex:none;border-top:1px solid var(--d3-divisa)}
.fo2-lin{height:52px;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}
.fo2-abre:hover > .fo2-lin,.fo2-abre[aria-expanded="true"] > .fo2-lin{background:var(--d3-veu)}
.fo2-g{font-weight:500;color:var(--d3-rotulo);white-space:nowrap}
.fo2-g.r{color:var(--d3-perigo)}
.fo2-nome{min-width:0;font-size:var(--d3-fs-texto);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.fo2-nome > b{font-weight:600}
.fo2-nome > span{color:var(--d3-rotulo)}
.fo2-c{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-variant-numeric:tabular-nums}
.fo2-c.m{color:var(--d3-rotulo)}
.fo2-c.a{font-weight:500;color:var(--d3-ambar)}
.fo2-c > b.r{font-weight:500;color:var(--d3-perigo)}
.fo2-ac{display:flex;justify-content:flex-end;min-width:0}
.fo2-det{display:none;flex-direction:column;gap:8px;padding:6px 16px 14px 86px;background:var(--d3-veu);font:400 var(--d3-fs-apoio)/1.4 var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}
.fo2-abre[aria-expanded="true"] > .fo2-det{display:flex}
.fo2-det > p{margin:0}
.fo2-det > p > b{font-weight:600}
.fo2 .d3v-estado{flex:1 1 auto}
/* Janela baixa (1366 x 768): o laranja e a consulta encolhem para nada rolar. */
@media (max-height:820px){.m2-laranja{min-height:0}.m2-laranja .d3m-lar-num{font-size:44px}.m2-tile{padding:6px 10px}.fo2-lin{height:46px}}
@media (max-width:1400px){.fo2-cab,.fo2-lin{grid-template-columns:52px minmax(0,1fr) minmax(0,140px) 64px minmax(0,112px) 92px 100px;gap:0 8px}}
@media (max-width:1100px){
  .fo2-folha{height:560px}
  .fo2-cab,.fo2-lin{grid-template-columns:52px minmax(0,1fr) minmax(0,130px) 64px 100px}
  .fo2-cab > :is(:nth-child(5),:nth-child(6)),.fo2-lin > :is(:nth-child(5),:nth-child(6)){display:none}
}
/* Contraste: o âmbar escurece sobre a linha realçada e o botão vazado do laranja fica direto no laranja. */
.fo2-abre:hover .fo2-c.a,.fo2-abre[aria-expanded="true"] .fo2-c.a{color:var(--d3-ajuste)}
.m2-laranja .d3m-btn.l.s{background:none}
.m2-laranja .d3m-btn.l.s:hover{background:var(--d3-fume-veu)}
/* A folha do formulário (a de sempre) abre por cima da janela de vidro: a letra volta a ser a tinta. */
#vv-comercial.d3m-c-janela :is(.vc-folha,.vc-abas){color:var(--d3-tinta)}

/* ===== padrao-v2/zm-c-conversas.css ===== */
/* DIREÇÃO V2 · CONVERSAS (prancha V2-M-Conversas, 16/11/2026). A janela (#vv-whatsapp) ganha .d3m-c-janela (zm-c-base.css)
   no computador e vira três colunas: a lista dos grupos direto no vidro, a conversa numa folha clara e a consulta de
   316 px. Só rolam a lista e as mensagens, por dentro. Só tokens --d3-*. */
.d3m-c-corpo.cv2{grid-template-columns:288px minmax(0,1fr) 316px}
.cv2-lista{display:flex;flex-direction:column;gap:8px;min-width:0;min-height:0;color:var(--d3-fume-texto)}
.cv2-fichas{align-self:flex-start;height:32px;max-width:100%}
.cv2-fichas > button{height:26px;padding:0 8px;gap:4px;font-size:var(--d3-fs-apoio)}
.cv2-itens{flex:1 1 0;display:flex;flex-direction:column;gap:4px;min-height:0;overflow-y:auto;scrollbar-width:none}
.cv2-item{appearance:none;flex:none;display:flex;align-items:center;gap:10px;width:100%;height:56px;margin:0;padding:0 10px;box-sizing:border-box;border:0;border-radius:var(--d3-r-caixa);background:none;box-shadow:none;color:var(--d3-fume-texto);font:400 var(--d3-fs-apoio)/1.3 var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
.cv2-item:hover{background:var(--d3-fume-veu)}
.cv2-item.on{background:var(--d3-escuro-texto);color:var(--d3-tinta-fixa)}
.cv2-item:focus-visible,.cv2-mais:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:-2px}
.cv2-av{flex:none;display:grid;place-items:center;width:32px;height:32px;border-radius:50%;background:var(--d3-fume-veu-forte);color:var(--d3-fume-texto);font:600 var(--d3-fs-mini)/1 var(--vv-texto,Inter,sans-serif)}
.cv2-item.on > .cv2-av{background:var(--d3-veu-forte);color:var(--d3-tinta-fixa)}
.cv2-tx{flex:1 1 auto;display:flex;flex-direction:column;gap:3px;min-width:0}
.cv2-l1,.cv2-l2{display:flex;align-items:center;justify-content:space-between;gap:8px;min-width:0}
.cv2-l1 > b{min-width:0;font:600 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cv2-l1 > time{flex:none;font-size:var(--d3-fs-mini);color:var(--d3-fume-apagado);font-variant-numeric:tabular-nums}
.cv2-l2 > span{flex:1 1 auto;min-width:0;color:var(--d3-fume-apagado);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cv2-item.on :is(.cv2-l1 > time,.cv2-l2 > span){color:var(--d3-rotulo-fixo)}
.cv2-item.nao-lida .cv2-l2 > span{color:var(--d3-fume-texto)}
.cv2-item.nao-lida.on .cv2-l2 > span{color:var(--d3-tinta-fixa)}
.cv2-nl,.cv2-arroba{flex:none;display:grid;place-items:center;min-width:18px;height:18px;padding:0 5px;box-sizing:border-box;border-radius:999px;background:var(--d3-escuro-texto);color:var(--d3-tinta-fixa);font:600 var(--d3-fs-mini)/1 var(--vv-texto,Inter,sans-serif);font-style:normal;font-variant-numeric:tabular-nums}
.cv2-arroba{background:var(--d3-acao);color:var(--d3-escuro-texto)}
.cv2-item.on .cv2-nl{background:var(--d3-tinta-fixa);color:var(--d3-escuro-texto)}
.cv2-mais{appearance:none;flex:none;align-self:flex-start;height:32px;margin:0;padding:0 10px;border:0;border-radius:var(--d3-r-botao);background:none;box-shadow:none;color:var(--d3-fume-texto);font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);cursor:pointer}
.cv2-mais:hover{background:var(--d3-fume-veu)}
.cv2-lista .d3v-estado{flex:none;align-items:flex-start;padding:10px;text-align:left;color:var(--d3-fume-apagado)}
.cv2-lista .d3v-estado > b{color:var(--d3-fume-texto)}
/* A conversa: a folha clara, com a cabeça, as mensagens (só elas rolam) e o pé de só leitura. */
.cv2-folha{min-height:0}
.cv2-folha > .d3m-c-folha-cab{border-bottom:1px solid var(--d3-divisa)}
.cv2-so{flex:none;display:inline-flex;align-items:center;gap:6px;font-size:var(--d3-fs-apoio);color:var(--d3-rotulo);white-space:nowrap}
.cv2-so > svg{width:13px;height:13px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.cv2-lupa{flex:none;width:28px;padding:0}
.cv2-link{flex:none;border-radius:4px;color:var(--d3-tinta);font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);text-decoration:none;white-space:nowrap}
.cv2-link:hover{text-decoration:underline;text-underline-offset:3px}
.cv2-link:focus-visible{outline:2px solid var(--d3-acao);outline-offset:2px}
.cv2-procura{flex:none;display:flex;align-items:center;gap:10px;padding:8px 16px;border-bottom:1px solid var(--d3-divisa);font-size:var(--d3-fs-apoio);color:var(--d3-rotulo);white-space:nowrap}
#vv-whatsapp.d3m-c-janela .cv2-procura > input{flex:1 1 auto;min-width:0;height:28px;margin:0;padding:0 10px;box-sizing:border-box;border:0;border-radius:var(--d3-r-botao);box-shadow:inset 0 0 0 1px var(--d3-meta);color:var(--d3-tinta);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif)}
#vv-whatsapp.d3m-c-janela .cv2-procura > input:focus-visible{outline:2px solid var(--d3-acao);outline-offset:1px}
.cv2-msgs{flex:1 1 0;display:flex;flex-direction:column;gap:12px;min-height:0;padding:16px;box-sizing:border-box;overflow-y:auto;scrollbar-width:thin}
.cv2-msgs > :first-child{margin-top:auto}
.cv2-dia,.cv2-sep{flex:none;align-self:center;margin:0;font-size:var(--d3-fs-apoio);color:var(--d3-rotulo)}
.cv2-sep{align-self:stretch;display:flex;align-items:center;gap:10px;font-weight:600;color:var(--d3-acao-texto)}
.cv2-sep::before,.cv2-sep::after{content:"";flex:1 1 0;height:1px;background:var(--d3-veu-forte)}
.cv2-bl{flex:none;display:flex;align-items:flex-start;gap:10px;min-width:0}
.cv2-bl.eu{flex-direction:row-reverse}
.cv2-bl > .cv2-av{width:28px;height:28px;background:var(--d3-veu);color:var(--d3-tinta);font-size:10px}
.cv2-bl.agt > .cv2-av{background:var(--d3-agente-veu);color:var(--d3-agente-texto)}
.cv2-b{display:flex;flex-direction:column;gap:4px;min-width:0;max-width:min(420px,78%);padding:10px 12px;box-sizing:border-box;border-radius:12px;background:var(--d3-veu);color:var(--d3-tinta);font:400 var(--d3-fs-texto)/1.45 var(--vv-texto,Inter,sans-serif)}
.cv2-bl.eu > .cv2-b{background:var(--d3-veu-forte)}
.cv2-bl.para-voce > .cv2-b{box-shadow:inset 2px 0 0 var(--d3-acao)}
.cv2-bl.piscar > .cv2-b{box-shadow:inset 0 0 0 2px var(--d3-acao)}
.cv2-bc{display:flex;align-items:baseline;gap:8px;min-width:0;font-size:var(--d3-fs-apoio);line-height:1.3}
.cv2-bc > b{min-width:0;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cv2-bc > em{flex:none;font-style:normal;font-weight:500;color:var(--d3-acao-texto)}
.cv2-bc > time{flex:none;margin-left:auto;padding-left:8px;color:var(--d3-rotulo);font-variant-numeric:tabular-nums}
.cv2-citada{padding:4px 8px;border-radius:6px;box-shadow:inset 2px 0 0 var(--d3-meta);background:var(--d3-veu);font-size:var(--d3-fs-apoio);color:var(--d3-texto2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cv2-midia{font-size:var(--d3-fs-apoio);color:var(--d3-rotulo)}
.cv2-texto{overflow-wrap:anywhere;white-space:pre-wrap}
.cv2-apagada{display:inline-flex;align-items:center;gap:6px;font-size:var(--d3-fs-apoio);color:var(--d3-rotulo)}
.cv2-apagada > svg{flex:none;width:13px;height:13px}
.cv2-pe{flex:none;display:flex;align-items:center;gap:10px;min-height:52px;padding:0 16px;box-sizing:border-box;border-top:1px solid var(--d3-divisa);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
.cv2-pe > span{flex:1 1 auto;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cv2-folha > .d3v-estado{flex:1 1 auto}
/* A consulta. */
.cv2-laranja{flex:none;min-height:244px}
.cv2-laranja .d3m-btn.l.s{background:none}
.cv2-laranja .d3m-btn.l.s:hover{background:var(--d3-fume-veu)}
.cv2 .d3m-vlin.cv2-cli{height:40px}
.cv2 .d3m-vlin.cv2-cli > .d3v-foto{flex:none}
.cv2-ver{appearance:none;flex:none;margin:0;padding:0 2px;border:0;border-radius:4px;background:none;box-shadow:none;color:var(--d3-fume-texto);font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);text-decoration:underline;text-underline-offset:3px;white-space:nowrap;cursor:pointer}
.cv2-ver:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}
.cv2-nota{margin:0;font:400 var(--d3-fs-texto)/1.5 var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-apagado)}
.cv2-nota.caixa{padding:9px 10px;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu);font-size:var(--d3-fs-apoio);line-height:1.4}
/* Janela baixa (1366 x 768) e larguras menores. */
@media (max-height:820px){.cv2-laranja{min-height:0}.cv2-laranja .d3m-lar-num{font-size:40px}.cv2-laranja .d3m-c-s{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.cv2-item{height:50px}.cv2 > .d3m-lado{gap:10px}.cv2 .d3m-vlin{height:32px}.cv2 .d3m-vlin.cv2-cli{height:36px}.cv2-nota{line-height:1.4}}
@media (max-width:1400px){.d3m-c-corpo.cv2{grid-template-columns:264px minmax(0,1fr) 300px}}
@media (max-width:1100px){
  .d3m-c-corpo.cv2{grid-template-columns:240px minmax(0,1fr)}
  .cv2-lista,.cv2-folha{height:560px}
  .cv2 > .d3m-lado{grid-column:1 / -1}
}

/* ===== padrao-v2/zm-c-creators.css ===== */
/* DIREÇÃO V2 · CREATORS (prancha V2-M-Creators, 16/11/2026). As pessoas em grade na folha, quatro por linha; o cartão vira
   no lugar (.cr2-verso) com as campanhas, o campo do contato e os botões. As peças divididas com Fornecedores (.m2-*) e a
   janela ficam em zm-c-comercial.css e zm-c-base.css. Só tokens --d3-*. */
.cr2-folha{min-height:0}
.cr2-abas2{margin-left:2px;padding-left:10px;border-left:1px solid var(--d3-veu-forte)}
.cr2-nicho > summary{display:inline-flex;align-items:center;gap:4px;height:28px;padding:0 8px 0 10px;border-radius:var(--d3-r-botao);color:var(--d3-tinta);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);white-space:nowrap;cursor:pointer}
.cr2-nicho > summary:hover{background:var(--d3-veu)}
.cr2-nicho > summary.on{background:var(--d3-veu-forte);font-weight:600}
.cr2-nicho > summary > svg{flex:none;width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.cr2-nicho > summary:focus-visible{outline:2px solid var(--d3-acao);outline-offset:1px}
.cr2-grade{flex:1 1 0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));grid-auto-rows:minmax(280px,auto);align-content:start;min-height:0;overflow-x:hidden;overflow-y:auto;scrollbar-width:thin;border-top:1px solid var(--d3-divisa)}
.cr2-grade.vazia{display:flex}
.cr2-c{position:relative;display:flex;min-width:0;box-sizing:border-box;border-right:1px solid var(--d3-divisa);border-bottom:1px solid var(--d3-divisa)}
.cr2-c:nth-child(4n){border-right:0}
.cr2-frente{appearance:none;flex:1 1 auto;display:flex;flex-direction:column;align-items:center;gap:0;min-width:0;margin:0;padding:20px 12px 14px;box-sizing:border-box;border:0;border-radius:0;background:none;box-shadow:none;color:var(--d3-tinta);font:400 var(--d3-fs-apoio)/1.3 var(--vv-texto,Inter,sans-serif);text-align:center;cursor:pointer}
.cr2-frente:hover{background:var(--d3-veu)}
.cr2-frente:focus-visible{outline:2px solid var(--d3-acao);outline-offset:-2px}
.cr2-av{flex:none;display:grid;place-items:center;width:72px;height:72px;border-radius:50%;background:var(--d3-texto2);color:var(--d3-escuro-texto);font:600 22px/1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.01em}
.cr2-av.t0{background:var(--d3-mod-operacao)}
.cr2-av.t1{background:var(--d3-mod-negocio)}
.cr2-av.t2{background:var(--d3-mod-time)}
.cr2-av.t3{background:var(--d3-mod-vybe)}
.cr2-av.t4{background:var(--d3-info)}
.cr2-av.t5{background:var(--d3-agente-texto)}
.cr2-av.t6{background:var(--d3-perigo)}
.cr2-nome{max-width:100%;margin-top:12px;font:600 14px/1.3 var(--vv-texto,Inter,sans-serif);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cr2-arroba{max-width:100%;margin-top:3px;color:var(--d3-rotulo);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cr2-nums{display:flex;justify-content:center;gap:20px;margin-top:14px}
.cr2-nums > span{display:flex;flex-direction:column;align-items:center;gap:2px;font-size:var(--d3-fs-mini);color:var(--d3-rotulo);white-space:nowrap}
.cr2-nums > span > b{font:600 var(--d3-fs-destaque)/1.2 var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);font-variant-numeric:tabular-nums}
.cr2-tags{display:flex;align-items:center;justify-content:center;gap:8px;max-width:100%;margin-top:14px;white-space:nowrap;overflow:hidden}
.cr2-tags > i{flex:none;display:inline-flex;align-items:center;height:20px;padding:0 8px;border-radius:999px;background:var(--d3-veu-forte);font-style:normal;font-size:var(--d3-fs-mini);font-weight:500}
.cr2-tags > i.z{background:none;padding:0;color:var(--d3-rotulo);font-weight:400}
.cr2-ct{max-width:100%;margin-top:10px;color:var(--d3-rotulo);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cr2-ct.a{font-weight:500;color:var(--d3-ambar)}
.cr2-frente:hover > .cr2-ct.a{color:var(--d3-ajuste)}
.cr2-ct.g{font-weight:500;color:var(--d3-pronto)}
/* O verso: o cartão vira no lugar, sem empurrar a grade. */
.cr2-verso{position:absolute;inset:0;z-index:1;display:none;flex-direction:column;gap:8px;padding:12px;box-sizing:border-box;overflow-y:auto;scrollbar-width:thin;background:var(--d3-fume-painel);color:var(--d3-fume-texto);font:400 var(--d3-fs-apoio)/1.4 var(--vv-texto,Inter,sans-serif);text-align:left}
.cr2-c[aria-expanded="true"] > .cr2-verso{display:flex}
.cr2-verso-cab{flex:none;display:flex;align-items:center;gap:8px;min-width:0}
.cr2-verso-cab > b{flex:1 1 auto;min-width:0;font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cr2-x{appearance:none;flex:none;display:grid;place-items:center;width:24px;height:24px;margin:0;padding:0;border:0;border-radius:var(--d3-r-botao);background:var(--d3-fume-veu-forte);box-shadow:none;color:var(--d3-fume-texto);cursor:pointer}
.cr2-x > svg{width:12px;height:12px;fill:none;stroke:currentColor;stroke-width:2.4;stroke-linecap:round}
.cr2-x:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:1px}
.cr2-verso > p{margin:0;overflow-wrap:anywhere}
.cr2-verso > p > b{font-weight:600}
.cr2-k > .g{font-weight:600;color:var(--d3-pronto-claro)}
.cr2-k > .m{color:var(--d3-fume-apagado)}
.cr2-verso .m2-campo > label{color:var(--d3-fume-texto)}
:is(#vv-comercial,#vv-whatsapp).d3m-c-janela .cr2-verso .m2-campo > input{flex:1 1 100%;width:100%}
.cr2-verso .m2-acoes{margin-top:auto}
.cr2-verso .d3m-c-btn.c{box-shadow:inset 0 0 0 1px var(--d3-fume-borda);color:var(--d3-fume-texto)}
.cr2-verso .d3m-c-btn.c:hover{background:var(--d3-fume-veu)}
.cr2-verso .d3m-c-btn.c.k{background:var(--d3-fume-texto);box-shadow:none;color:var(--d3-tinta-fixa)}
.cr2-verso .d3m-c-btn.c.ruim{color:var(--d3-perigo-vidro)}
.cr2-verso .d3m-c-btn.c:focus-visible{outline-color:var(--d3-fume-texto)}
/* A consulta: os nichos em barras; cada linha filtra a grade. */
