/* ===== padrao-v2/zm-c-impressoes.css ===== */
/* DIREÇÃO V2 · IMPRESSÕES (pranchas V2-M-Impressoes, V2-M-Impressoes-Etapas e V2-M-Impressoes-Lista, 16/11/2026). A janela
   (#vv-impressoes) ganha .d3m-c-janela (zm-c-base.css). Linhas: o funil das 7 etapas no vidro, a folha com uma linha por
   peça e a consulta. Etapas: sete colunas no vidro. Lista: a tabela inteira numa folha. */
.imp2-aviso{flex:none;margin:-8px 0;padding:0;font:600 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-pronto-claro)}
.imp2-aviso:empty{display:none}
.imp2-aviso.erro{color:var(--d3-perigo-vidro)}
.imp2 .m{color:var(--d3-rotulo)}
.imp2 .r{color:var(--d3-perigo)}
.imp2 .a{color:var(--d3-ambar)}
.imp2 .g{color:var(--d3-pronto)}
/* O funil: sete caixas de vidro, o número da etapa, o nome e quantas peças estão nela. Cada uma filtra a lista. */
.imp2-funil{flex:none;display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:8px}
.imp2-funil:empty{display:none}
.imp2-fase{appearance:none;display:flex;flex-direction:column;justify-content:space-between;gap:8px;min-width:0;height:72px;margin:0;padding:10px 12px;box-sizing:border-box;border:0;border-radius:12px;background:var(--d3-fume-veu);box-shadow:none;color:var(--d3-fume-texto);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
.imp2-fase:hover{background:var(--d3-fume-veu-forte)}
.imp2-fase[aria-checked="true"]{background:var(--d3-folha);box-shadow:var(--d3-folha-sombra);color:var(--d3-tinta)}
.imp2-fase > span:first-child{display:flex;gap:8px;min-width:0;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.imp2-fase > span:first-child > b{font-weight:400;color:var(--d3-fume-apagado)}
.imp2-fase[aria-checked="true"] > span:first-child > b{color:var(--d3-rotulo)}
.imp2-fase-n{display:flex;align-items:baseline;gap:6px;min-width:0;white-space:nowrap}
.imp2-fase-n > b{font:600 var(--d3-fs-titulo)/1 var(--vv-texto,Inter,sans-serif);font-variant-numeric:tabular-nums}
.imp2-fase-n > small{font-size:var(--d3-fs-apoio);overflow:hidden;text-overflow:ellipsis}
.imp2-fase-n.r > small{color:var(--d3-perigo-vidro)}
.imp2-fase[aria-checked="true"] > .imp2-fase-n.r > small{color:var(--d3-perigo)}
.imp2-fase:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}
/* A folha das linhas. */
.imp2-folha{min-height:0}
.imp2-rola{overflow-y:auto;scrollbar-width:thin;padding:16px}
.imp2-cab,.imp2-lin{display:grid;grid-template-columns:68px 28px minmax(0,1fr) 100px 112px minmax(0,104px) minmax(0,108px) 82px;align-items:center;gap:0 10px;padding:0 16px;box-sizing:border-box}
.imp2-cab,.imp2-tcab{flex:none;height:24px;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
.imp2-cab > span:last-child,.imp2-v{text-align:right}
.imp2-lista{flex:1 1 0;min-height:0;overflow-y:auto;scrollbar-width:thin}
.imp2-lin,.imp2-tl{min-height:44px;border-top:1px solid var(--d3-divisa);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);cursor:pointer}
.imp2-tl{min-height:42px}
:is(.imp2-lin,.imp2-tl):hover,:is(.imp2-lin,.imp2-tl).aberta{background:var(--d3-veu)}
.imp2-g{font-size:var(--d3-fs-apoio);color:var(--d3-rotulo);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.imp2-oq{display:flex;align-items:baseline;min-width:0;color:var(--d3-rotulo);white-space:nowrap}
.imp2-oq > b{flex:0 1 auto;min-width:0;max-width:58%;font-weight:600;color:var(--d3-tinta);overflow:hidden;text-overflow:ellipsis}
.imp2-oq > b::after{content:" · ";white-space:pre;font-weight:400;color:var(--d3-rotulo)}
.imp2-oq > .imp2-nome{flex:1 1 0;min-width:40px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.imp2-nome,.imp2-semg,.imp2-arte{appearance:none;display:inline;margin:0;padding:0;border:0;border-radius:4px;background:none;box-shadow:none;color:inherit;font:inherit;text-align:left;cursor:pointer}
.imp2-nome:hover,.imp2-semg:hover,.imp2-arte:hover{text-decoration:underline;text-underline-offset:3px}
.imp2-semg{color:var(--d3-ambar)}
.imp2-arte{color:var(--d3-tinta)}
:is(.imp2-nome,.imp2-semg,.imp2-arte,.imp2-pe > button,.imp2-cartao,.imp2-col-mais,.imp2-col-nova):focus-visible{outline:2px solid var(--d3-acao);outline-offset:2px}
.imp2-c{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-variant-numeric:tabular-nums}
.imp2-v{white-space:nowrap;font-variant-numeric:tabular-nums}
.imp2-trilha{display:inline-flex;gap:3px}
.imp2-trilha > i{flex:1 1 0;height:4px;border-radius:2px;background:var(--d3-veu-forte)}
.imp2-trilha > i.ok{background:var(--d3-texto2)}
.imp2-trilha > i.vez{background:var(--st,var(--d3-meta))}
/* A ficha de sempre, aberta no lugar. */
.imp2-det{padding:4px 16px 14px 120px;background:var(--d3-veu)}
.imp2-det > .vi-ficha,.imp2-painel > .vi-ficha{position:static;width:auto;max-width:none;margin:0;border:0;border-radius:12px;box-shadow:none}
.imp2-pe{flex:none;display:flex;align-items:center;min-height:44px;padding:0 16px;box-sizing:border-box;border-top:1px solid var(--d3-divisa);font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);white-space:nowrap;overflow:hidden}
.imp2-pe-rot{margin-right:14px}
.imp2-pe > :is(span,button):not(.imp2-pe-rot){appearance:none;height:20px;margin:0;padding:0 12px;border:0;border-left:1px solid var(--d3-veu-forte);border-radius:0;background:none;box-shadow:none;color:var(--d3-rotulo);font:inherit;line-height:20px}
.imp2-pe > .imp2-pe-rot + :is(span,button){padding-left:0;border-left:0}
.imp2-pe > button{cursor:pointer}
.imp2-pe > button:hover,.imp2-pe > button[aria-checked="true"]{color:var(--d3-tinta)}
.imp2-pe > button[aria-checked="true"]{text-decoration:underline;text-underline-offset:3px}
.imp2-pe b{margin-right:3px;font:600 14px var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);font-variant-numeric:tabular-nums}
.imp2-pe .r > b,.imp2-pe .r b{color:var(--d3-perigo)}
.imp2-pe .a b{color:var(--d3-ambar)}
.imp2-pe .g b{color:var(--d3-pronto)}
.imp2-abas2{margin-left:8px;padding-left:10px;border-left:1px solid var(--d3-veu-forte)}
/* A consulta. */
.imp2-laranja{flex:none;min-height:216px}
.imp2-laranja .d3m-lar-num{font-size:52px}
.imp2-setas{display:inline-flex;align-items:center;gap:6px;margin-left:auto;font-size:var(--d3-fs-mini)}
.imp2-setas > .d3m-btn{width:22px;height:22px;padding:0}
.imp2-setas > .d3m-btn > svg{width:12px;height:12px;fill:none;stroke:currentColor;stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round}
.imp2-setas > .d3m-btn:disabled{opacity:.45;cursor:default}
.imp2-abrir{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.2fr);gap:6px}
.imp2-abrir > .d3m-cons-cab{grid-column:1 / -1}
.imp2-tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(0,1fr));gap:6px}
.imp2-tile{display:flex;flex-direction:column;gap:2px;min-width:0;padding:8px 10px;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu)}
.imp2-tile > b{font:600 var(--d3-fs-destaque) var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-texto);white-space:nowrap;font-variant-numeric:tabular-nums}
.imp2-tile > span{font-size:var(--d3-fs-apoio);color:var(--d3-fume-apagado)}
/* ETAPAS: sete colunas de vidro; o cartão é uma folha, e arrastar muda a etapa. */
.imp2-quadro{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:8px;min-width:0;min-height:0}
.imp2-col{display:flex;flex-direction:column;gap:8px;min-width:0;min-height:0;padding:8px;box-sizing:border-box;border-radius:14px;background:var(--d3-fume-veu)}
.imp2-col.alvo{background:var(--d3-fume-veu-forte);box-shadow:inset 0 0 0 2px var(--d3-fume-borda)}
.imp2-col-cab{flex:none;display:flex;justify-content:space-between;gap:8px;padding:4px 4px 0;font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-texto);white-space:nowrap}
.imp2-col-cab > span:first-child{min-width:0;overflow:hidden;text-overflow:ellipsis}
.imp2-col-cab > span:first-child > b{font-weight:400}
.imp2-col-cab > span:last-child{font-weight:400;color:var(--d3-fume-apagado)}
.imp2-col-lista{flex:1 1 0;display:flex;flex-direction:column;gap:8px;min-height:0;overflow-y:auto;scrollbar-width:none}
.imp2-col-vazio{margin:0;padding:8px 4px;font-size:var(--d3-fs-apoio);color:var(--d3-fume-apagado)}
.imp2-cartao{appearance:none;flex:none;display:flex;flex-direction:column;align-items:flex-start;gap:3px;min-width:0;margin:0;padding:10px;box-sizing:border-box;border:0;border-radius:10px;background:var(--d3-folha);box-shadow:var(--d3-folha-sombra);color:var(--d3-tinta);font:400 var(--d3-fs-apoio)/1.35 var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
.imp2-cartao.sel{outline:2px solid var(--d3-fume-texto);outline-offset:1px}
.imp2-cartao > b{max-width:100%;font-size:var(--d3-fs-texto);font-weight:600;overflow:hidden;text-overflow:ellipsis}
.imp2-cli{display:flex;align-items:center;gap:6px;max-width:100%;margin-bottom:2px}
.imp2-cli > .d3v-foto{width:20px;height:20px;border-radius:6px;font-size:9px}
.imp2-cli > span{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.imp2-cart-pe{display:flex;flex-direction:column;max-width:100%;margin-top:4px}
.imp2-cart-pe > span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.imp2-cart-pe > span:last-child:not(.r):not(.g){color:var(--d3-rotulo)}
.imp2-cart-l{flex:none;gap:6px;padding:10px;border-radius:10px;font-size:var(--d3-fs-apoio)}
.imp2-cart-l > .d3m-lar-rot{font-size:var(--d3-fs-mini)}
.imp2-cart-l .d3-acao-av{width:20px;height:20px;font-size:9px}
.imp2-cart-t{font:600 var(--d3-fs-texto)/1.25 var(--vv-texto,Inter,sans-serif)}
.imp2-cart-l > .d3m-btn{align-self:stretch;height:auto;min-height:30px;margin-top:4px;padding:4px 8px;white-space:normal}
.imp2-col-mais,.imp2-col-nova{appearance:none;flex:none;display:inline-flex;align-items:center;justify-content:center;gap:6px;height:28px;margin:0;padding:0 8px;border:0;border-radius:var(--d3-r-botao);background:none;box-shadow:none;color:var(--d3-fume-texto);font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);cursor:pointer}
.imp2-col-mais{justify-content:flex-start}
.imp2-col-mais:hover,.imp2-col-nova:hover{background:var(--d3-fume-veu)}
.imp2-col-nova > svg{width:12px;height:12px;fill:none;stroke:currentColor;stroke-width:2.2;stroke-linecap:round}
.imp2-nota{flex:none;margin:-8px 0 0;font-size:var(--d3-fs-apoio);color:var(--d3-fume-apagado)}
/* A ficha (ou o formulário) ao lado, nas vistas Etapas e Lista. */
.imp2-e:not(.um),.imp2-t:not(.um){grid-template-columns:minmax(0,1fr) 380px}
.imp2-painel{overflow-y:auto;scrollbar-width:thin;padding:14px}
/* LISTA: a tabela inteira. */
.imp2-tcab,.imp2-tl{display:grid;grid-template-columns:28px minmax(0,1.5fr) 82px 122px minmax(0,.8fr) 78px minmax(0,.8fr) 92px minmax(0,.8fr);align-items:center;gap:0 10px;padding:0 16px;box-sizing:border-box}
.imp2-t.semv :is(.imp2-tcab,.imp2-tl){grid-template-columns:28px minmax(0,1.5fr) 82px 122px minmax(0,.8fr) 78px minmax(0,.8fr) minmax(0,.8fr)}
.imp2-tcab > span:nth-child(8):not(:last-child){text-align:right}
/* Janela baixa (1366 x 768): o funil e a consulta encolhem para nada rolar. */
@media (max-height:820px){.imp2-laranja{min-height:0}.imp2-laranja .d3m-lar-num{font-size:40px}.imp2-laranja .d3m-c-s{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.imp2 > .d3m-lado{gap:8px}.imp2 .d3m-vlin{height:30px}.imp2-tile{padding:5px 10px}.imp2-fase{height:56px;padding:8px 12px}}
@media (max-width:1400px){
  .imp2-cab,.imp2-lin{grid-template-columns:60px 28px minmax(0,1fr) 76px 104px minmax(0,96px) minmax(0,104px) 80px;gap:0 8px}
}
@media (max-width:1500px){.imp2-e:not(.um) > .imp2-quadro{grid-template-columns:repeat(7,minmax(150px,1fr));overflow-x:auto;scrollbar-width:thin}}
@media (max-width:1100px){
  .imp2-folha{height:560px}
  .imp2-funil{grid-template-columns:repeat(4,minmax(0,1fr))}
  .imp2-quadro{grid-template-columns:repeat(7,minmax(180px,1fr));overflow-x:auto;height:520px}
  .imp2-e:not(.um),.imp2-t:not(.um){grid-template-columns:minmax(0,1fr)}
  .imp2-cab,.imp2-lin{grid-template-columns:56px 28px minmax(0,1fr) 112px minmax(0,96px) 80px}
  .imp2-cab > :is(:nth-child(4),:nth-child(6)),.imp2-lin > :is(.imp2-trilha,.imp2-trilha + .d3v-st + .imp2-c){display:none}
}

/* ===== padrao-v2/zm-c-planejamentos.css ===== */
/* DIREÇÃO V2 · PLANEJAMENTOS (prancha V2-M-Planejamentos, 16/11/2026). O mês numa folha, uma linha por cliente; a consulta
   no vidro. A janela (#vv-planejamentos) ganha .d3m-c-janela (zm-c-base.css) quando a tela V2 está nela. */
.plj2-folha{min-height:0}
.plj2-cab,.plj2-lin{display:grid;grid-template-columns:70px 28px minmax(0,1fr) 66px 128px minmax(0,172px) 76px 78px;align-items:center;gap:0 10px;padding:0 16px;box-sizing:border-box}
.plj2-cab{flex:none;height:24px;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
.plj2-lista{flex:1 1 0;min-height:0;overflow-y:auto;scrollbar-width:thin}
.plj2-lin{min-height:38px;border-top:1px solid var(--d3-divisa);cursor:pointer}
.plj2-lin.sem{cursor:default}
.plj2-lin:not(.sem):hover,.plj2-lin.aberta{background:var(--d3-veu)}
.plj2-g{font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);white-space:nowrap}
.plj2-g.r{color:var(--d3-perigo)}
.plj2-g.a{color:var(--d3-ambar)}
.plj2-nome{appearance:none;justify-self:start;max-width:100%;margin:0;padding:0;border:0;border-radius:4px;background:none;box-shadow:none;color:var(--d3-tinta);font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);text-align:left;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
button.plj2-nome{cursor:pointer}
button.plj2-nome:hover{text-decoration:underline;text-underline-offset:3px}
button.plj2-nome:focus-visible,.plj2-criar:focus-visible,.plj2-dl:focus-visible{outline:2px solid var(--d3-acao);outline-offset:2px}
.plj2-ver,.plj2-n{font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);white-space:nowrap;font-variant-numeric:tabular-nums}
.plj2-lin.sem > .plj2-ver,.plj2-semtxt{color:var(--d3-rotulo)}
.plj2-semtxt{font-size:var(--d3-fs-apoio)}
.plj2-trilha{display:inline-flex;gap:3px}
.plj2-trilha > i{flex:1 1 0;height:4px;border-radius:2px;background:var(--d3-veu-forte)}
.plj2-trilha > i.ok{background:var(--d3-texto2)}
.plj2-trilha > i.vez{background:var(--d3-meta)}
.plj2-trilha > i.vez.a{background:var(--d3-acao)}
.plj2-trilha > i.vez.b{background:var(--d3-agente)}
.plj2-trilha > i.vez.r{background:var(--d3-perigo)}
.plj2-trilha > i.vez.g{background:var(--d3-pronto)}
.plj2-head{display:inline-flex;align-items:center;gap:6px;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);white-space:nowrap;font-variant-numeric:tabular-nums}
.plj2-meu{display:inline-flex;align-items:center;height:20px;padding:0 6px;border-radius:999px;background:var(--d3-veu-forte);color:var(--d3-tinta);font-size:var(--d3-fs-mini)}
.plj2-ok{display:inline-grid}
.plj2-ok > svg{width:14px;height:14px;fill:none;stroke:var(--d3-pronto);stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round}
.plj2-criar{appearance:none;justify-self:end;height:28px;margin:0;padding:0 8px;border:0;border-radius:var(--d3-r-botao);background:none;box-shadow:none;color:var(--d3-tinta);font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);cursor:pointer}
.plj2-criar:hover{background:var(--d3-veu)}
/* A linha aberta no lugar: as etapas, os avisos das peças e os três jeitos de abrir. */
.plj2-det{display:flex;flex-wrap:wrap;align-items:center;gap:8px;padding:8px 16px 12px 124px;background:var(--d3-veu)}
.plj2-etapas{display:inline-flex;flex-wrap:wrap;align-items:center;gap:6px 14px;font-size:var(--d3-fs-apoio);color:var(--d3-tinta)}
.plj2-etapas > .p2-etp{display:inline-flex;align-items:center;gap:6px}
.plj2-etapas .p2-cx{flex:none;display:grid;place-items:center;width:14px;height:14px;border-radius:50%;box-shadow:inset 0 0 0 1.5px var(--d3-meta)}
.plj2-etapas .p2-cx.ok{background:var(--d3-pronto);box-shadow:none}
.plj2-etapas .p2-cx.at{box-shadow:inset 0 0 0 1.5px var(--d3-tinta)}
.plj2-etapas .p2-cx > svg{width:9px;height:9px;fill:none;stroke:var(--d3-escuro-texto);stroke-width:3;stroke-linecap:round;stroke-linejoin:round}
.plj2-det > .d3pl-av{display:inline-flex;align-items:center;height:20px;padding:0 8px;border-radius:999px;background:var(--d3-veu-forte);color:var(--d3-tinta);font:500 var(--d3-fs-mini) var(--vv-texto,Inter,sans-serif);white-space:nowrap}
.plj2-det > .d3pl-av.r{background:var(--d3-perigo-veu);color:var(--d3-perigo)}
.plj2-vao{flex:1 1 auto}
/* O pé "De olho", da mesma folha. */
.plj2-pe{flex:none;display:flex;align-items:center;min-height:44px;padding:0 16px;box-sizing:border-box;border-top:1px solid var(--d3-divisa);font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);white-space:nowrap;overflow:hidden}
.plj2-pe-rot{margin-right:14px}
.plj2-pe > span + span{padding:0 12px;border-left:1px solid var(--d3-veu-forte)}
.plj2-pe > .plj2-pe-rot + span{padding-left:0;border-left:0}
.plj2-pe > span > b{margin-right:3px;font:600 14px var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);font-variant-numeric:tabular-nums}
.plj2-pe > span.r > b{color:var(--d3-perigo)}
.plj2-pe > span.a > b{color:var(--d3-ambar)}
/* A consulta. */
.plj2-laranja{flex:none;min-height:216px}
.plj2-dist{display:flex;flex-direction:column;padding:6px 0;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu)}
.plj2-dl{appearance:none;display:grid;grid-template-columns:minmax(0,1fr) 118px 24px;align-items:center;gap:12px;height:23px;margin:0;padding:0 12px;border:0;border-radius:0;background:none;box-shadow:none;color:var(--d3-fume-apagado);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
.plj2-dl:hover,.plj2-dl[aria-checked="true"]{background:var(--d3-fume-veu);color:var(--d3-fume-texto)}
.plj2-dl > span:first-child{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.plj2-dl > b{text-align:right;font-weight:600;color:var(--d3-fume-texto);font-variant-numeric:tabular-nums}
.plj2-dl > .d3m-vbarra{min-width:0}
.plj2-dl > .d3m-vbarra.b > i{background:var(--d3-agente-claro)}
.plj2-dl > .d3m-vbarra.n > i{background:var(--d3-fume-apagado)}
.plj2-nota{margin:0;font:400 var(--d3-fs-texto)/1.45 var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-apagado)}
/* Janela baixa (1366 x 768): a consulta encolhe e a nota de onde o cliente aprova sai, para nada rolar. */
@media (max-height:820px){.plj2-laranja{min-height:0}.plj2 .d3m-vlin{height:32px}.plj2-nota-bloco{display:none}}
@media (max-width:1100px){.plj2-folha{height:560px}}
@media (max-width:900px){
  .plj2-cab,.plj2-lin{grid-template-columns:52px 28px minmax(0,1fr) 60px minmax(0,150px) 70px}
  .plj2-cab > :is(:nth-child(5),:nth-child(8)),.plj2-lin > :is(.plj2-trilha,.plj2-head){display:none}
  .plj2-lin.sem > .plj2-criar{grid-column:6}
}

/* ===== padrao-v2/zm-c-projetos.css ===== */
/* DIREÇÃO V2 · PROJETOS PONTUAIS (prancha V2-M-Projetos, 16/11/2026). A janela (#vv-pessoas, na aba Projetos) ganha
   .d3m-c-janela (zm-c-base.css). Abre na linha do tempo: uma folha com as etapas em barras e a consulta no vidro; os
   cartões continuam como aba, numa folha. */
.pj2-aviso{flex:none;margin:-8px 0;font:600 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-pronto-claro)}
.pj2-aviso:empty{display:none}
.pj2-tela{flex:1 1 0;display:flex;flex-direction:column;min-height:0}
.pj2-folha{min-height:0}
.pj2-erro{flex:none;display:flex;align-items:center;gap:8px;margin:0;padding:6px 16px;background:var(--d3-perigo-veu);color:var(--d3-perigo);font-size:var(--d3-fs-apoio)}
.pj2-legenda{flex:none;display:inline-flex;align-items:center;gap:12px;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);white-space:nowrap}
.pj2-legenda > span{display:inline-flex;align-items:center;gap:6px}
.pj2-legenda .pj2-barra{position:static;width:14px;height:5px}
/* A régua das semanas e a grade: 250 px para o nome da etapa, o resto é o tempo. */
.pj2-regua,.pj2-grade,.pj2-etapa{display:grid;grid-template-columns:250px minmax(0,1fr);gap:0 16px}
.pj2-regua{flex:none;height:28px;padding:0 16px;border-top:1px solid var(--d3-divisa);font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
.pj2-regua > div{position:relative}
.pj2-regua > div > span{position:absolute;top:7px;padding-left:4px;white-space:nowrap;font-variant-numeric:tabular-nums}
.pj2-rola{flex:1 1 0;min-height:0;overflow-y:auto;scrollbar-width:thin;border-top:1px solid var(--d3-divisa)}
.pj2-corpo{position:relative;min-height:100%;padding:0 16px;box-sizing:border-box}
.pj2-grade,.pj2-hoje{position:absolute;inset:0 16px;pointer-events:none}
.pj2-grade > div{position:relative}
.pj2-grade > div > i{position:absolute;top:0;bottom:0;width:1px;background:var(--d3-divisa)}
.pj2-hoje{left:282px;z-index:2}
.pj2-hoje > i{position:absolute;top:0;bottom:0;width:2px;margin-left:-1px;background:var(--d3-perigo)}
.pj2-proj{position:relative;padding:10px 0 8px;border-bottom:1px solid var(--d3-divisa)}
.pj2-cab{position:relative;z-index:3;display:flex;align-items:center;gap:8px;min-width:0;height:32px;margin-bottom:4px}
.pj2-nome,.pj2-et{appearance:none;margin:0;padding:0;border:0;border-radius:4px;background:none;box-shadow:none;color:var(--d3-tinta);font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);text-align:left;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;cursor:pointer}
.pj2-nome{flex:0 1 auto;min-width:0}
.pj2-nome:hover,.pj2-et:hover > span{text-decoration:underline;text-underline-offset:3px}
:is(.pj2-nome,.pj2-et):focus-visible{outline:2px solid var(--d3-acao);outline-offset:2px}
.pj2-cli{flex:0 1 auto;min-width:0;color:var(--d3-rotulo);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pj2-quando{flex:none;margin-left:auto;padding-left:8px;border-radius:4px;background:var(--d3-folha);font-size:var(--d3-fs-apoio);color:var(--d3-rotulo);white-space:nowrap}
.pj2-etapa{align-items:center;height:30px}
.pj2-et{display:flex;align-items:center;gap:8px;min-width:0;font-weight:400}
.pj2-et > span:last-child{min-width:0;overflow:hidden;text-overflow:ellipsis}
#vv-pessoas .pj2-et > .v2p-av{flex:none;display:grid;place-items:center;width:20px;height:20px;border-radius:50%;background:var(--d3-veu-forte);color:var(--d3-tinta);font:600 9px var(--vv-texto,Inter,sans-serif)}
.pj2-trilho{position:relative;height:100%}
.pj2-barra{position:absolute;top:50%;min-width:10px;height:8px;margin-top:-4px;border-radius:4px;background:var(--d3-veu-forte)}
.pj2-barra.ok{background:var(--d3-texto2)}
.pj2-barra.b{background:var(--d3-info)}
.pj2-barra.r{background:var(--d3-perigo)}
.pj2-sem{margin:0;padding:4px 0;font-size:var(--d3-fs-apoio);color:var(--d3-rotulo)}
.pj2-pe{flex:none;display:flex;align-items:center;min-height:44px;padding:0 16px;box-sizing:border-box;border-top:1px solid var(--d3-divisa);font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);white-space:nowrap;overflow:hidden}
.pj2-pe-rot{margin-right:14px}
.pj2-pe > span + span{padding:0 12px;border-left:1px solid var(--d3-veu-forte)}
.pj2-pe > .pj2-pe-rot + span{padding-left:0;border-left:0}
.pj2-pe > span > b{margin-right:3px;font:600 14px var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);font-variant-numeric:tabular-nums}
.pj2-pe > span.r > b{color:var(--d3-perigo)}
/* A consulta. */
.pj2-laranja{flex:none;min-height:216px}
.pj2-laranja .d3m-lar-num{font-size:52px}
.pj2-carga{cursor:default}
#vv-pessoas .pj2-carga > .v2p-av{flex:none;display:grid;place-items:center;width:22px;height:22px;border-radius:50%;background:var(--d3-fume-veu-forte);color:var(--d3-fume-texto);font:600 10px var(--vv-texto,Inter,sans-serif)}
.pj2 .d3m-vlin.pj2-carga > .d3m-vnome{flex:0 0 76px}
.pj2-ajuda{margin:0;padding:10px;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu);font-size:var(--d3-fs-apoio);line-height:1.45;color:var(--d3-fume-apagado)}
/* A página do projeto (ou o formulário) ao lado, numa folha que rola por dentro; e os cartões, na aba deles. */
.pj2.com-painel{grid-template-columns:minmax(0,1fr) 420px}
.pj2-painel,.pj2-cartoes{overflow-y:auto;scrollbar-width:thin;padding:14px}
.pj2-painel .v2p-card{margin:0;box-shadow:none}
@media (max-height:820px){.pj2-laranja{min-height:0}.pj2-laranja .d3m-lar-num{font-size:40px}.pj2 .d3m-vlin{height:32px}}
@media (max-width:1280px){.pj2-regua,.pj2-grade,.pj2-etapa{grid-template-columns:190px minmax(0,1fr)}.pj2-hoje{left:222px}.pj2.com-painel{grid-template-columns:minmax(0,1fr) 380px}}
@media (max-width:1100px){.pj2-tela{flex:none}.pj2-folha{height:560px}.pj2.com-painel{grid-template-columns:minmax(0,1fr)}}

/* ===== padrao-v2/zm-d-0-pecas.css ===== */
/* ===================================================================================================================
   MÓDULOS V2 · GRUPO D (Gestão, Financeiro, Comercial, Pacotes, Orçamentos, Contratos, Churn e Agentes) · PEÇAS LOCAIS.
   As pranchas V2-M-* repetem as mesmas peças em toda janela de módulo; as que ainda não existem em z-direcao.css ficam
   aqui, com o prefixo .d3m-d-, até serem unificadas: o topo da janela no vidro (título com menu, linha de apoio e as
   ferramentas), o cartão folha com cabeça de 48, o selo do setor, a linha de 40 com ponto e o número de 44.
   Só tokens --d3-*; nenhuma regra antiga é forçada.
   =================================================================================================================== */

/* Âmbar vivo para ponto e gráfico (o --d3-ajuste-claro é claro demais na folha e o --d3-ambar é cor de letra). */
:root{--d3m-d-ambar:color-mix(in srgb,var(--d3-ajuste-claro) 45%,var(--d3-ambar))}

/* Topo da janela, direto no vidro: título de 24, apoio de 12 e as ferramentas à direita. */
.d3m-d-topo{flex:none;display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:48px;margin:0;padding:0;color:var(--d3-fume-texto);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif)}
.d3m-d-tit{display:flex;flex-direction:column;gap:3px;min-width:0}
.d3m-d-tit :is(h1,h2){margin:0;font:600 24px/1.1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.02em;color:var(--d3-fume-texto);white-space:nowrap}
.d3m-d-sub{font:400 var(--d3-fs-apoio)/1.3 var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-apagado);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-d-ferr{flex:none;display:flex;align-items:center;gap:8px;min-width:0}
/* O título abre o menu das outras vistas; o "Mais" abre o resto. Os dois são <details> com a mesma caixa escura. */
.d3m-d-troca,.d3m-d-mais{position:relative}
.d3m-d-troca > summary{display:inline-flex;align-items:center;gap:6px;list-style:none;border-radius:var(--d3-r-botao);cursor:pointer}
.d3m-d-troca > summary::-webkit-details-marker,.d3m-d-mais > summary::-webkit-details-marker{display:none}
.d3m-d-troca > summary > svg{flex:none;width:16px;height:16px;fill:none;stroke:var(--d3-fume-apagado);stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.d3m-d-troca > summary:focus-visible,.d3m-d-mais > summary:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:3px}
.d3m-d-pop{position:absolute;z-index:30;top:calc(100% + 6px);left:0;display:flex;flex-direction:column;gap:2px;min-width:220px;padding:6px;box-sizing:border-box;border-radius:12px;background:var(--d3-fume-painel);box-shadow:inset 0 0 0 1px var(--d3-fume-borda),0 18px 40px -18px rgba(0,0,0,.7)}
.d3m-d-mais > .d3m-d-pop{left:auto;right:0}
.d3m-d-pop > :is(button,a){appearance:none;display:flex;align-items:center;gap:8px;height:32px;margin:0;padding:0 10px;border:0;border-radius:var(--d3-r-botao);background:none;color:var(--d3-fume-texto);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);text-align:left;text-decoration:none;white-space:nowrap;cursor:pointer}
.d3m-d-pop > :is(button,a):hover{background:var(--d3-fume-veu)}
.d3m-d-pop > :is(button,a)[aria-current]{background:var(--d3-fume-veu-forte);font-weight:600}
.d3m-d-pop > :is(button,a):focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:-2px}
/* Botão só de ícone, no vidro. */
.d3m-d-ico{appearance:none;flex:none;display:grid;place-items:center;width:34px;height:34px;margin:0;padding:0;border:0;border-radius:var(--d3-r-botao);background:var(--d3-fume-veu-forte);color:var(--d3-fume-texto);list-style:none;cursor:pointer}
.d3m-d-ico:hover{background:rgba(255,255,255,.26)}
.d3m-d-ico > svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.d3m-d-ico:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}
/* Botão com nome, no vidro (o secundário do topo). */
.d3m-d-vbtn{appearance:none;flex:none;display:inline-flex;align-items:center;justify-content:center;gap:6px;height:34px;margin:0;padding:0 14px;box-sizing:border-box;border:0;border-radius:var(--d3-r-botao);background:var(--d3-fume-veu);box-shadow:inset 0 0 0 1px var(--d3-fume-borda);color:var(--d3-fume-texto);font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);text-decoration:none;white-space:nowrap;cursor:pointer}
.d3m-d-vbtn:hover{background:var(--d3-fume-veu-forte)}
.d3m-d-vbtn.p{background:var(--d3-fume-texto);box-shadow:none;color:var(--d3-tinta);font-weight:600}
.d3m-d-vbtn.p:hover{background:rgba(255,255,255,.9)}
.d3m-d-vbtn > svg{flex:none;width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.d3m-d-vbtn:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}
/* Escolha de uma entre poucas, no vidro: trilho de 36, a escolhida branca. */
.d3m-d-seg{flex:none;display:inline-flex;gap:2px;height:36px;margin:0;padding:3px;box-sizing:border-box;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu)}
.d3m-d-seg > button{appearance:none;display:inline-flex;align-items:center;gap:6px;height:30px;margin:0;padding:0 12px;border:0;border-radius:var(--d3-r-botao);background:none;box-shadow:none;color:var(--d3-fume-texto);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);white-space:nowrap;cursor:pointer}
.d3m-d-seg > button:hover{background:var(--d3-fume-veu)}
.d3m-d-seg > button:is([aria-pressed="true"],[aria-selected="true"],[aria-checked="true"]){background:var(--d3-fume-texto);color:var(--d3-tinta);font-weight:600}
.d3m-d-seg > button:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}
/* Campo de escolha, no vidro. */
.d3m-d-topo select.d3m-d-sel{appearance:none;flex:none;height:34px;max-width:100%;margin:0;padding:0 32px 0 14px;box-sizing:border-box;border:0;border-radius:var(--d3-r-botao);background-color:var(--d3-fume-veu);background-image:url("data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 viewBox=%270 0 24 24%27 fill=%27none%27 stroke=%27white%27 stroke-width=%272%27 stroke-linecap=%27round%27 stroke-linejoin=%27round%27%3E%3Cpath d=%27M6 9l6 6 6-6%27/%3E%3C/svg%3E");background-repeat:no-repeat;background-position:right 10px center;background-size:13px;box-shadow:inset 0 0 0 1px var(--d3-fume-borda);color:var(--d3-fume-texto);font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);cursor:pointer}
.d3m-d-topo select.d3m-d-sel > option{background:var(--d3-cartao);color:var(--d3-tinta)}
.d3m-d-topo select.d3m-d-sel:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}

/* Cartão folha: cabeça de 48 com o selo do setor, o título e um atalho de texto. */
.d3m-d-folha{display:flex;flex-direction:column;min-width:0;min-height:0;margin:0;padding:0;box-sizing:border-box;border:0;border-radius:16px;overflow:hidden;background:var(--d3-folha);box-shadow:var(--d3-folha-sombra);color:var(--d3-tinta);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif)}
.d3m-d-cab{flex:none;display:flex;align-items:center;gap:10px;height:48px;margin:0;padding:0 16px;box-sizing:border-box}
.d3m-d-cab > h3{flex:1 1 auto;min-width:0;margin:0;font:600 14px/1.25 var(--vv-texto,Inter,sans-serif);letter-spacing:0;color:var(--d3-tinta);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-d-cab > h3 > small{font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
.d3m-d-cab > small{flex:none;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);white-space:nowrap}
.d3m-d-selo{flex:none;display:grid;place-items:center;width:22px;height:22px;border-radius:7px;background:var(--d3-tinta);color:var(--d3-escuro-texto)}
.d3m-d-selo.operacao{background:var(--d3-mod-operacao)}
.d3m-d-selo.negocio{background:var(--d3-agente)}
.d3m-d-selo.time{background:var(--d3-mod-time)}
.d3m-d-selo.vybe{background:var(--d3-mod-vybe)}
.d3m-d-selo.r{background:var(--d3-perigo)}
.d3m-d-selo > svg{width:11px;height:11px;fill:none;stroke:currentColor;stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round}
.d3m-d-elo{appearance:none;flex:none;display:inline-flex;align-items:center;height:24px;margin:0;padding:0 2px;border:0;border-radius:4px;background:none;box-shadow:none;color:var(--d3-tinta);font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);text-decoration:none;white-space:nowrap;cursor:pointer}
.d3m-d-elo:hover{text-decoration:underline;text-underline-offset:3px}
.d3m-d-elo:focus-visible{outline:2px solid var(--d3-acao);outline-offset:2px}
/* Linha de 40: ponto na cor do que diz, o texto e o apoio à direita. Com ação, a linha inteira é o botão. */
.d3m-d-lin{appearance:none;flex:none;display:flex;align-items:center;gap:10px;width:100%;height:40px;margin:0;padding:0 16px;box-sizing:border-box;border:0;border-top:1px solid var(--d3-divisa);border-radius:0;background:none;box-shadow:none;color:var(--d3-tinta);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);text-align:left}
button.d3m-d-lin{cursor:pointer}
button.d3m-d-lin:hover{background:var(--d3-veu)}
button.d3m-d-lin:focus-visible{outline:2px solid var(--d3-acao);outline-offset:-2px}
.d3m-d-lin > i{flex:none;width:7px;height:7px;border-radius:50%;background:var(--d3-meta)}
.d3m-d-lin > i.r{background:var(--d3-perigo)}
.d3m-d-lin > i.a{background:var(--d3m-d-ambar)}
.d3m-d-lin > i.g{background:var(--d3-mod-vybe)}
.d3m-d-lin > i.i{background:var(--d3-info)}
.d3m-d-lin > i.l{background:var(--d3-agente)}
.d3m-d-lin > span{flex:1 1 auto;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-d-lin > small{flex:none;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);white-space:nowrap;font-variant-numeric:tabular-nums}
/* Número de 44, na cor do que diz. */
.d3m-d-numero{appearance:none;display:block;margin:0;padding:0;border:0;border-radius:6px;background:none;box-shadow:none;font:600 44px/1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.03em;color:var(--d3-tinta);text-align:left;white-space:nowrap;font-variant-numeric:tabular-nums}
button.d3m-d-numero{cursor:pointer}
button.d3m-d-numero:focus-visible{outline:2px solid var(--d3-acao);outline-offset:3px}
.d3m-d-numero.r{color:var(--d3-perigo)}
.d3m-d-numero.g{color:var(--d3-pronto)}
.d3m-d-numero.a{color:var(--d3-ambar)}

/* Janela de módulo em vidro fumê (as telas do Comercial que já estão no esqueleto das pranchas V2-M-*): o topo e a tela
   ficam direto no vidro, com 16 de respiro; a tela ocupa a altura toda e só as listas rolam por dentro. */
body.mundo #vv-comercial.vc.d3m-d-m{display:flex;flex-direction:column;gap:16px;padding:16px;box-sizing:border-box;overflow:hidden;border:0;border-radius:20px;background:var(--d3-fume);box-shadow:inset 0 0 0 1px var(--d3-fume-borda),0 30px 60px -40px rgba(0,0,0,.6);backdrop-filter:none;-webkit-backdrop-filter:none;color:var(--d3-fume-texto);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif)}
#vv-comercial.d3m-d-m > .vc-corpo.d3m-d-m-corpo{flex:1 1 0;min-height:0;margin:0;padding:0;overflow:hidden}
#vv-comercial.d3m-d-m > .vc-abas{display:none}
/* O "Como funciona", o aviso de que gravou e o carregando, no vidro. */
#vv-comercial.d3m-d-m > .vc-ajuda{flex:none;margin:0;padding:10px 12px;border:0;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu);color:var(--d3-fume-texto);font-size:var(--d3-fs-apoio);line-height:1.45}
#vv-comercial.d3m-d-m > .vc-ajuda > b{display:block;margin-bottom:2px;font-weight:600}
#vv-comercial.d3m-d-m > .vc-ajuda > p{margin:0;color:var(--d3-fume-apagado)}
#vv-comercial.d3m-d-m > .vc-msg-geral{flex:none;margin:0;padding:8px 12px;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu);color:var(--d3-fume-texto);font-weight:500}
#vv-comercial.d3m-d-m > .vc-msg-geral.erro{color:var(--d3-perigo-vidro)}
#vv-comercial.d3m-d-m > .vc-corpo > .vc-vazio{height:100%;box-sizing:border-box;justify-content:center;border:0;border-radius:16px;background:var(--d3-fume-veu);color:var(--d3-fume-texto)}
#vv-comercial.d3m-d-m > .vc-corpo > .vc-vazio > p{margin:0;color:var(--d3-fume-texto)}
/* Números em folha: rótulo e selo em cima; embaixo o número de 28, a linha de apoio e o gráfico pequeno. */
.d3m-d-nums{flex:none;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
.d3m-d-folha.d3m-d-num{appearance:none;justify-content:space-between;width:auto;height:116px;margin:0;padding:14px;text-align:left}
button.d3m-d-num{cursor:pointer}
button.d3m-d-num:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}
.d3m-d-num-cab{display:flex;align-items:center;justify-content:space-between;gap:8px;font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}
.d3m-d-num-cab > span:first-child{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-d-num-cab > .d3m-d-selo{width:24px;height:24px}
.d3m-d-num-cab > .d3m-d-selo > svg{width:12px;height:12px}
.d3m-d-num-pe{display:flex;align-items:flex-end;justify-content:space-between;gap:10px}
.d3m-d-num-pe > span:first-child{display:flex;flex-direction:column;gap:4px;min-width:0}
.d3m-d-num-v{font:600 var(--d3-fs-numero)/1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.02em;color:var(--d3-tinta);white-space:nowrap;font-variant-numeric:tabular-nums}
.d3m-d-num-v.g{color:var(--d3-pronto)}
.d3m-d-num-v.r{color:var(--d3-perigo)}
.d3m-d-num-v.a{color:var(--d3-ambar)}
.d3m-d-num-v > small{font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);letter-spacing:0;color:var(--d3-rotulo)}
.d3m-d-num-pe > span:first-child > small{font:400 var(--d3-fs-mini) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#vv-comercial svg.d3m-d-mini,svg.d3m-d-mini{flex:none;display:block;width:84px;height:40px;overflow:visible;fill:none;color:var(--d3-tinta)}
svg.d3m-d-mini.r{color:var(--d3-perigo)}
svg.d3m-d-mini.g{color:var(--d3-mod-vybe)}
svg.d3m-d-mini.l{color:var(--d3-agente)}
svg.d3m-d-mini > .veu{fill:currentColor;stroke:none;opacity:.14}
svg.d3m-d-mini > .fio{fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round;vector-effect:non-scaling-stroke}
#vv-comercial svg.d3m-d-anel,svg.d3m-d-anel{flex:none;display:block;width:40px;height:40px;color:var(--d3-tinta)}
svg.d3m-d-anel.g{color:var(--d3-mod-vybe)}
svg.d3m-d-anel.r{color:var(--d3-perigo)}
svg.d3m-d-anel > .trilho{fill:none;stroke:var(--d3-veu-forte);stroke-width:4}
svg.d3m-d-anel > .fio{fill:none;stroke:currentColor;stroke-width:4;stroke-linecap:round}
.d3m-d-barrinhas{flex:none;display:flex;align-items:flex-end;gap:3px;width:56px;height:40px;color:var(--d3-tinta)}
.d3m-d-barrinhas.r{color:var(--d3-perigo)}
.d3m-d-barrinhas.g{color:var(--d3-mod-vybe)}
.d3m-d-barrinhas > i{flex:1 1 0;max-width:12px;height:var(--v,20%);border-radius:2px;background:currentColor}
/* Ponto verde da linha no vidro (o que está feito ou ganho). */
.d3m-pt.g{background:var(--d3-mod-vybe-claro)}
@media (max-height:820px){
  .d3m-d-folha.d3m-d-num{height:96px;padding:12px 14px}
}
@media (max-width:900px){
  body.mundo #vv-comercial.vc.d3m-d-m{padding:12px;gap:12px;overflow-y:auto}
  #vv-comercial.d3m-d-m > .vc-corpo.d3m-d-m-corpo{flex:none;overflow:visible}
  .d3m-d-nums{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
  .d3m-d-nums > .d3m-d-num:first-child:nth-last-child(odd){grid-column:1 / -1}
}
@media (max-width:900px){
  .d3m-d-nums > .d3m-d-num:not(:first-child:nth-last-child(odd)) .d3m-d-num-pe > :is(svg,.d3m-d-barrinhas,.d3m-d-fx-duas){display:none}
  .d3m-d-nums > .d3m-d-num:not(:first-child:nth-last-child(odd)) .d3m-d-num-v{font-size:22px}
}
.d3m-d-selo.i{background:var(--d3-info)}

/* ===== padrao-v2/zm-d-agentes.css ===== */
/* ===================================================================================================================
   AGENTES NA PRANCHA V2-M-Agentes (16/11/2026). A janela dos Agentes (#vv-agentes) vira vidro fumê só na tela principal
   (classe .d3m-d-m, posta por vybe-mundo-agentes.js); a fila em lista, o perfil do agente e "Como o VYBES pensa" seguem
   na janela de antes. Em cima, o cartão laranja com o pedido da frente ao lado da folha "Para você decidir"; embaixo, a
   folha "Quem é quem", três agentes por linha; na coluna de consulta, o acerto em 7 dias, o que os agentes viram, a
   central e o "Abrir". As peças .d3m-d-* vêm de zm-d-0-pecas.css e as .d3m-* de z-direcao.css. Só tokens --d3-*.
   =================================================================================================================== */
body.mundo #vv-agentes.vv-ag.d3m-d-m{display:flex;flex-direction:column;gap:16px;padding:16px;box-sizing:border-box;overflow:hidden;border:0;border-radius:20px;background:var(--d3-fume);box-shadow:inset 0 0 0 1px var(--d3-fume-borda),0 30px 60px -40px rgba(0,0,0,.6);color:var(--d3-fume-texto);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif)}
#vv-agentes.d3m-d-m > .vga-detalhe.d3m-d-m-corpo{flex:1 1 0;min-height:0;margin:0;padding:0;overflow:hidden}
#vv-agentes.d3m-d-m .d3m-d-tit h2{margin:0;padding:0;border:0;background:none;font:600 24px/1.1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.02em;color:var(--d3-fume-texto)}
#vv-agentes.d3m-d-m .d3m-d-cab > h3{margin:0;font:600 14px/1.25 var(--vv-texto,Inter,sans-serif);letter-spacing:0;color:var(--d3-tinta)}
#vv-agentes.d3m-d-m .d3m-d-cab > h3 > small{font:400 14px/1.25 var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
#vv-agentes.d3m-d-m .vga-vazio{margin:0;padding:16px;border-radius:16px;background:var(--d3-fume-veu);color:var(--d3-fume-texto);font-size:var(--d3-fs-texto)}
/* Topo: a busca abre ao lado da lupa; a central sem sinal avisa ali. */
.d3m-d-ag-topo .d3m-d-ag-busca{appearance:none;flex:0 1 180px;width:180px;min-width:0;height:34px;margin:0;padding:0 12px;box-sizing:border-box;border:0;border-radius:var(--d3-r-botao);background:var(--d3-fume-veu);box-shadow:inset 0 0 0 1px var(--d3-fume-borda);color:var(--d3-fume-texto);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif)}
.d3m-d-ag-topo .d3m-d-ag-busca::placeholder{color:var(--d3-fume-apagado)}
.d3m-d-ag-topo .d3m-d-ag-busca:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}
.d3m-d-ag-topo .d3m-d-ico[aria-expanded="true"]{background:var(--d3-fume-texto);color:var(--d3-tinta)}
.d3m-d-ag-sinal{display:inline-flex;align-items:center;gap:8px;font-size:var(--d3-fs-apoio);color:var(--d3-perigo-vidro);white-space:nowrap}

/* A tela: a coluna principal e a coluna de consulta de 316. */
.d3m-d-ag{display:grid;grid-template-columns:minmax(0,1fr) 316px;gap:16px;height:100%;min-height:0;margin:0;padding:0;color:var(--d3-tinta);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif)}
.d3m-d-ag-main{display:flex;flex-direction:column;gap:12px;min-width:0;min-height:0}
.d3m-d-ag-alto{flex:none;display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,1fr);gap:12px;height:232px}
.d3m-d-ag-lado{min-height:0}
.d3m-d-ag-lado > .d3m-cons{flex:none}
.d3m-d-ag-aviso{flex:none;display:flex;flex-wrap:wrap;align-items:center;gap:8px 12px;margin:0;padding:8px 12px;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu);color:var(--d3-fume-texto);font-size:var(--d3-fs-apoio);line-height:1.4}
.d3m-d-ag-aviso > .d3m-d-vbtn{height:28px;padding:0 10px;font-size:var(--d3-fs-apoio)}
/* O laranja com o pedido da frente: a frase, a prova em até três linhas e as respostas. */
.d3m-d-ag-pesa{min-height:0;height:100%}
.d3m-d-ag-pesa .d3m-lar-txt > .d3-acao-frase{font-size:22px;line-height:1.2;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.d3m-d-ag-pesa .d3m-lar-txt > small{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.d3m-d-ag-pesa .d3m-lar-bts{align-items:center}
.d3m-d-ag-so{font-size:var(--d3-fs-apoio);color:var(--d3-escuro-texto)}
.d3m-d-ag-elo{appearance:none;display:inline-flex;align-items:center;height:34px;margin:0 0 0 auto;padding:0 6px;border:0;border-radius:var(--d3-r-botao);background:none;box-shadow:none;color:var(--d3-escuro-texto);font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);white-space:nowrap;cursor:pointer}
.d3m-d-ag-elo:hover{text-decoration:underline;text-underline-offset:3px}
.d3m-d-ag-elo:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}
.d3m-d-ag-elo.v{height:18px;margin:0;padding:0 2px;color:var(--d3-fume-apagado);font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif)}
/* "Para você decidir": a fila em linhas de 64; a da frente fica marcada. */
.d3m-d-ag-decidir{min-height:0}
.d3m-d-ag-decidir > .d3m-d-cab,.d3m-d-ag-quemq > .d3m-d-cab{height:44px}
.d3m-d-ag-peds{flex:1 1 0;display:flex;flex-direction:column;min-height:0;overflow-y:auto;scrollbar-width:thin}
.d3m-d-ag-ped{appearance:none;flex:none;display:flex;align-items:center;gap:10px;width:100%;height:64px;margin:0;padding:0 16px;box-sizing:border-box;border:0;border-top:1px solid var(--d3-divisa);border-radius:0;background:none;box-shadow:none;color:var(--d3-tinta);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
.d3m-d-ag-ped:hover,.d3m-d-ag-ped[aria-pressed="true"]{background:var(--d3-veu)}
.d3m-d-ag-ped:focus-visible,.d3m-d-ag-cel:focus-visible{outline:2px solid var(--d3-acao);outline-offset:-2px}
.d3m-d-ag-g{flex:none;width:52px;font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);white-space:nowrap}
.d3m-d-ag-g.r{color:var(--d3-perigo)}
.d3m-d-ag-ped-t{flex:1 1 auto;display:flex;flex-direction:column;gap:3px;min-width:0}
.d3m-d-ag-ped-t > b{font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-d-ag-ped-t > small{font-size:var(--d3-fs-apoio);color:var(--d3-rotulo);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-d-ag-ped-q{flex:none;font-size:var(--d3-fs-apoio);color:var(--d3-rotulo);white-space:nowrap;font-variant-numeric:tabular-nums}
.d3m-d-ag-ped-q.r{font-weight:500;color:var(--d3-perigo)}
.d3m-d-ag-nada{flex:1 1 auto;display:flex;align-items:center;margin:0;padding:16px;border-top:1px solid var(--d3-divisa);font-size:var(--d3-fs-texto);color:var(--d3-rotulo)}
/* A bolinha lilás do agente: 40 na célula, 28 na fila e 22 no vidro. */
.d3m-d-ag-av{flex:none;display:grid;place-items:center;width:40px;height:40px;border-radius:50%;background:var(--d3-agente);color:var(--d3-escuro-texto);font:600 16px var(--vv-texto,Inter,sans-serif);font-style:normal}
.d3m-d-ag-av.p{width:28px;height:28px;font-size:var(--d3-fs-mini)}
.d3m-d-ag-av.v{width:22px;height:22px;font-size:10px}
/* "Quem é quem": três agentes por linha, cada célula com 110 de altura; a lista rola por dentro. */
.d3m-d-ag-quemq{flex:1 1 0;min-height:0}
.d3m-d-ag-grade{flex:1 1 0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));grid-auto-rows:minmax(88px,110px);align-content:start;min-height:0;overflow-y:auto;scrollbar-width:thin;border-top:1px solid var(--d3-divisa)}
.d3m-d-ag-cel{appearance:none;display:flex;align-items:center;gap:12px;min-width:0;margin:0;padding:0 16px;box-sizing:border-box;border:0;border-right:1px solid var(--d3-divisa);border-bottom:1px solid var(--d3-divisa);border-radius:0;background:none;box-shadow:none;color:var(--d3-tinta);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
.d3m-d-ag-cel:nth-child(3n){border-right:0}
.d3m-d-ag-cel:hover{background:var(--d3-veu)}
.d3m-d-ag-quem{flex:1 1 auto;display:flex;flex-direction:column;gap:4px;min-width:0}
.d3m-d-ag-quem > span:first-child{color:var(--d3-rotulo);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-d-ag-quem > span:first-child > b{font-weight:600;color:var(--d3-tinta)}
.d3m-d-ag-est{display:inline-flex;align-items:center;gap:6px;font-size:var(--d3-fs-apoio);white-space:nowrap}
.d3m-d-ag-est > i{flex:none;width:7px;height:7px;border-radius:50%;background:var(--d3-meta)}
.d3m-d-ag-est > i.g{background:var(--d3-mod-vybe)}
.d3m-d-ag-est > i.a{background:var(--d3m-d-ambar)}
.d3m-d-ag-quem > small{font-size:var(--d3-fs-apoio);color:var(--d3-rotulo);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-d-ag-quem > small.r{font-weight:500;color:var(--d3-perigo)}
.d3m-d-ag-nota{flex:none;display:flex;flex-direction:column;align-items:flex-end;gap:6px}
.d3m-d-ag-nota > b{font:600 var(--d3-fs-destaque) var(--vv-texto,Inter,sans-serif);font-variant-numeric:tabular-nums}
.d3m-d-ag-nota > b.r{color:var(--d3-perigo)}
.d3m-d-ag-barra{display:block;width:44px;height:4px;border-radius:2px;background:var(--d3-veu-forte);overflow:hidden;color:var(--d3-meta)}
.d3m-d-ag-barra.g{color:var(--d3-mod-vybe)}
.d3m-d-ag-barra.a{color:var(--d3m-d-ambar)}
.d3m-d-ag-barra.r{color:var(--d3-perigo)}
.d3m-d-ag-barra > i{display:block;width:var(--v,0%);height:100%;border-radius:2px;background:currentColor}
.d3m-d-ag-pe{flex:none;display:flex;align-items:center;justify-content:space-between;gap:12px;height:48px;padding:0 16px;border-top:1px solid var(--d3-divisa);font-size:var(--d3-fs-apoio);color:var(--d3-rotulo);white-space:nowrap;overflow:hidden}
.d3m-d-ag-pe > .d3m-d-elo:first-of-type{margin-right:auto;font-weight:400;color:var(--d3-rotulo)}
.d3m-d-ag-vagos{flex:none;display:inline-flex;gap:8px}
.d3m-d-ag-vagos > i{width:24px;height:24px;border-radius:50%;box-shadow:inset 0 0 0 1px var(--d3-meta)}
/* A coluna de consulta: o cartão do acerto, o que os agentes viram e a central. */
.d3m-d-ag-cartao{display:flex;align-items:flex-end;justify-content:space-between;gap:12px;min-height:78px;padding:12px;box-sizing:border-box;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu);color:var(--d3-fume-texto)}
.d3m-d-ag-cartao > span{display:flex;flex-direction:column;gap:4px;min-width:0}
.d3m-d-ag-cartao > span > b{font:600 36px/1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.02em;font-variant-numeric:tabular-nums}
.d3m-d-ag-cartao > span > b.r{color:var(--d3-perigo-vidro)}
.d3m-d-ag-cartao > span > small{font-size:var(--d3-fs-apoio);color:var(--d3-fume-apagado)}
.d3m-d-ag-cartao > svg.d3m-d-mini{width:120px;height:44px;color:var(--d3-fume-texto)}
.d3m-d-ag-lado .d3m-vlin{height:40px}
.d3m-d-ag-lado .d3m-vlin > .d3m-vnome{flex:1 1 auto;min-width:0;max-width:none;color:var(--d3-fume-texto);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-d-ag-lado .d3m-vlin > .d3m-vnome > b{font-weight:600}
.d3m-d-ag-lado .d3m-vlin > span:first-child,.d3m-d-ag-central > span{flex:1 1 auto;min-width:0;color:var(--d3-fume-apagado);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-d-ag-lado .d3m-vlin > span:first-child > b,.d3m-d-ag-central > span > b{font-weight:600;color:var(--d3-fume-texto)}
.d3m-d-ag-lado .d3m-vlin > svg{flex:none;width:14px;height:14px;stroke:var(--d3-fume-apagado)}
div.d3m-d-ag-central{cursor:default}
/* A meta do acerto (só donos), no vidro. */
.d3m-d-ag-lado .d3t-meta > summary{display:inline-flex;align-items:center;height:28px;padding:0 10px;border-radius:var(--d3-r-botao);background:var(--d3-fume-veu);color:var(--d3-fume-texto);font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);list-style:none;cursor:pointer}
.d3m-d-ag-lado .d3t-meta > summary::-webkit-details-marker{display:none}
.d3m-d-ag-lado .d3t-meta-form{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:6px 0 0;padding:8px 10px;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu);color:var(--d3-fume-texto);font-size:var(--d3-fs-apoio)}
.d3m-d-ag-lado .d3t-meta-form input{width:56px;height:28px;margin:0 4px;padding:0 6px;border:0;border-radius:6px;background:var(--d3-cartao);color:var(--d3-tinta);font:inherit}
.d3m-d-ag-lado .d3t-meta-form button{appearance:none;height:28px;margin:0;padding:0 12px;border:0;border-radius:var(--d3-r-botao);background:var(--d3-fume-texto);color:var(--d3-tinta);font:600 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);cursor:pointer}

/* Tela baixa (1366 × 768): o alto e as células um degrau menores. */
@media (max-height:820px){
  .d3m-d-ag-alto{height:196px}
  .d3m-d-ag-pesa{padding:12px 16px}
  .d3m-d-ag-pesa .d3m-lar-txt > .d3-acao-frase{font-size:18px}
  .d3m-d-ag-pesa .d3m-lar-bts{margin-top:6px}
  .d3m-d-ag-ped{height:52px}
  .d3m-d-ag-decidir > .d3m-d-cab,.d3m-d-ag-quemq > .d3m-d-cab{height:40px}
  .d3m-d-ag-grade{grid-auto-rows:minmax(72px,84px)}
  .d3m-d-ag-pe{height:40px}
  .d3m-d-ag-lado{gap:10px}
  .d3m-d-ag-lado .d3m-cons{gap:4px}
  .d3m-d-ag-lado .d3m-vlin{height:32px}
  .d3m-d-ag-cartao{min-height:64px;padding:8px 12px}
  .d3m-d-ag-cartao > span > b{font-size:28px}
}
@media (max-width:1280px){
  .d3m-d-ag{grid-template-columns:minmax(0,1fr) 264px}
  .d3m-d-ag-cel{gap:10px;padding:0 12px}
  .d3m-d-ag-g{width:44px}
}
/* Celular: uma coluna só, o laranja primeiro, e a janela rola. */
@media (max-width:900px){
  body.mundo #vv-agentes.vv-ag.d3m-d-m{padding:12px;gap:12px;overflow-y:auto;border-radius:0 0 14px 14px}
  #vv-agentes.d3m-d-m > .vga-detalhe.d3m-d-m-corpo{flex:none;overflow:visible}
  .d3m-d-ag-topo{flex-wrap:wrap;gap:8px}
  .d3m-d-ag-topo > .d3m-d-ferr{flex:1 1 100%;flex-wrap:wrap}
  .d3m-d-ag-topo .d3m-d-sub{white-space:normal}
  .d3m-d-ag{display:flex;flex-direction:column;height:auto;gap:12px}
  .d3m-d-ag-main,.d3m-d-ag-lado{display:contents}
  .d3m-d-ag-alto{display:flex;flex-direction:column;height:auto}
  .d3m-d-ag-pesa{height:auto;min-height:200px}
  .d3m-d-ag-peds,.d3m-d-ag-grade{flex:none;overflow:visible}
  .d3m-d-ag-quemq{flex:none}
  .d3m-d-ag-quemq > .d3m-d-cab{height:auto;flex-wrap:wrap;padding:10px 16px}
  .d3m-d-ag-quemq .d3m-d-pk-seg{flex:1 1 100%;justify-content:flex-start}
  .d3m-d-ag-grade{grid-template-columns:minmax(0,1fr);grid-auto-rows:auto}
  .d3m-d-ag-cel{min-height:84px;padding:10px 16px;border-right:0}
  .d3m-d-ag-g{width:auto;min-width:44px}
  .d3m-d-ag-pe{height:auto;flex-wrap:wrap;padding:10px 16px;white-space:normal}
  .d3m-d-ag-vagos{display:none}
  .d3m-d-ag-decidir .d3m-d-pk-olho{height:auto;flex-wrap:wrap;gap:4px 0;padding:10px 16px;white-space:normal}
}

/* ===== padrao-v2/zm-d-carteira.css ===== */
/* ===================================================================================================================
   CONTRATOS E CHURN NAS PRANCHAS V2-M-Contratos e V2-M-Churn (16/11/2026). A janela da Carteira (#vv-carteira) vira vidro
   fumê só nessas duas telas (classe .d3m-d-m, posta por vybe-mundo-carteira.js); Saúde e Onboarding seguem como estão.
   Contratos: uma folha com a lista em três grupos (Agora, Depois e Falta), a régua de doze meses com o mês da renovação
   e o "De olho" no pé; ao lado, o laranja do Vorcaro, os clientes ativos em doze meses e o "Abrir". Churn: três números
   em folha, as saídas por mês ao lado do porquê, "Quem saiu" em colunas e, ao lado, o laranja, quem está em risco e a
   retenção por ano de entrada. As peças .d3m-d-* vêm de zm-d-0-pecas.css e as .d3m-* de z-direcao.css. Só tokens --d3-*.
   =================================================================================================================== */
body.mundo .vc-camada > #vv-carteira.vc-janela.d3m-d-m{display:flex;flex-direction:column;gap:16px;padding:16px;overflow:hidden;border:0;border-radius:20px;background:var(--d3-fume);box-shadow:inset 0 0 0 1px var(--d3-fume-borda),0 30px 60px -40px rgba(0,0,0,.6);color:var(--d3-fume-texto);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif)}
#vv-carteira.d3m-d-m > .vc-corpo.d3m-d-m-corpo{flex:1 1 0;min-height:0;margin:0;padding:0;overflow:hidden}
#vv-carteira.d3m-d-m .d3m-d-tit h2{margin:0;font:600 24px/1.1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.02em;color:var(--d3-fume-texto)}
#vv-carteira.d3m-d-m .d3m-d-cab > h3{margin:0}
#vv-carteira.d3m-d-m :is(button,summary,select,input,textarea):focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px;box-shadow:none}
#vv-carteira.d3m-d-m .d3m-d-folha :is(button,select,input,textarea):focus-visible{outline-color:var(--d3-acao)}
/* O aviso de que gravou, o "Como funciona", o erro e o carregando, no vidro. */
#vv-carteira.d3m-d-m > .vc-aviso{flex:none;margin:0;padding:8px 12px;border:0;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu);color:var(--d3-fume-texto);font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif)}
#vv-carteira.d3m-d-m > .vc-aviso:empty{display:none}
#vv-carteira.d3m-d-m > .vc-ajuda{flex:none;max-height:30%;margin:0;padding:10px 12px;overflow-y:auto;scrollbar-width:thin;border:0;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu);color:var(--d3-fume-texto);font-size:var(--d3-fs-apoio);line-height:1.45}
#vv-carteira.d3m-d-m > .vc-ajuda > b{display:block;margin-bottom:2px;font-weight:600}
#vv-carteira.d3m-d-m > .vc-ajuda > p{margin:0;color:var(--d3-fume-apagado);font-size:var(--d3-fs-apoio)}
#vv-carteira.d3m-d-m .vc-erro{margin:0 0 12px;padding:8px 12px;border:0;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu);color:var(--d3-perigo-vidro);font-size:var(--d3-fs-texto)}
#vv-carteira.d3m-d-m .vc-carregando{margin:0;padding:16px;border-radius:16px;background:var(--d3-fume-veu);color:var(--d3-fume-texto)}
#vv-carteira.d3m-d-m > .d3m-d-ct-fin{flex:none;padding:12px 16px}

/* Topo: a busca abre ao lado da lupa. */
.d3m-d-ct-topo .d3m-d-ct-busca{appearance:none;flex:0 1 180px;width:180px;min-width:0;height:34px;margin:0;padding:0 12px;box-sizing:border-box;border:0;border-radius:var(--d3-r-botao);background:var(--d3-fume-veu);box-shadow:inset 0 0 0 1px var(--d3-fume-borda);color:var(--d3-fume-texto);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif)}
.d3m-d-ct-topo .d3m-d-ct-busca::placeholder{color:var(--d3-fume-apagado)}
.d3m-d-ct-topo .d3m-d-ico[aria-expanded="true"]{background:var(--d3-fume-texto);color:var(--d3-tinta)}

/* A tela: a coluna principal e a coluna de consulta de 316. */
.d3m-d-ct{display:grid;grid-template-columns:minmax(0,1fr) 316px;gap:16px;height:100%;min-height:0;margin:0;padding:0;color:var(--d3-tinta);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif)}
.d3m-d-ct-main{display:flex;flex-direction:column;gap:12px;min-width:0;min-height:0}
.d3m-d-ct-lado{min-height:0}
.d3m-d-ct-pesa{flex:none;min-height:252px}
.d3m-d-ct-lado > .d3m-cons{flex:none}
.d3m-d-ct-lado .d3m-vlin > span:first-of-type{flex:1 1 auto;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--d3-fume-apagado)}
.d3m-d-ct-lado .d3m-vlin > span:first-of-type > b{font-weight:600;color:var(--d3-fume-texto)}
.d3m-d-ct-lado .d3m-vlin > b.d3m-vn{flex:none;font-weight:600;color:var(--d3-fume-texto);font-variant-numeric:tabular-nums}
.d3m-d-ct-lado .d3m-vlin > svg{flex:none;width:14px;height:14px;stroke:var(--d3-fume-apagado)}
.d3m-d-ct-folha{flex:1 1 0;min-height:0}
.d3m-d-ct-folha.so{height:100%}
.d3m-d-ct-folha > .d3m-d-cab{height:44px}
#vv-carteira.d3m-d-m .d3m-d-cab > h3 > small{font:400 14px/1.25 var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
.d3m-d-pk-seg > button > b.a{color:var(--d3-ambar)}
.d3m-d-ct-rolo{flex:1 1 0;min-height:0;margin:0;padding:0;list-style:none;overflow-y:auto;scrollbar-width:thin}
.d3m-d-ct-leitor{position:absolute;width:1px;height:1px;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}

/* A linha do contrato: quando, quem, quanto por mês, desde quando, a régua de doze meses e a data da renovação. */
.d3m-d-ct-lin{appearance:none;display:grid;grid-template-columns:60px 28px minmax(0,1fr) 96px 72px 228px 96px;align-items:center;gap:10px;width:100%;height:38px;margin:0;padding:0 16px;box-sizing:border-box;border:0;border-top:1px solid var(--d3-divisa);border-radius:0;background:none;box-shadow:none;color:var(--d3-tinta);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);text-align:left}
.d3m-d-ct-lin.sem-valor{grid-template-columns:60px 28px minmax(0,1fr) 72px 228px 96px}
button.d3m-d-ct-lin{cursor:pointer}
button.d3m-d-ct-lin:hover{background:var(--d3-veu)}
.d3m-d-ct-cabl{flex:none;height:28px;border-top:0;font-size:var(--d3-fs-apoio);color:var(--d3-rotulo)}
.d3m-d-ct-g{font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);white-space:nowrap}
.d3m-d-ct-g.agora{color:var(--d3-perigo)}
.d3m-d-ct-g.falta{color:var(--d3-ambar)}
.d3m-d-ct-av{flex:none;display:grid;place-items:center;width:28px;height:28px;border-radius:8px;background:var(--d3-tinta);color:var(--d3-contra,var(--d3-escuro-texto));font:600 10px var(--vv-texto,Inter,sans-serif);font-style:normal;letter-spacing:.02em}
.d3m-d-ct-av.c0{background:var(--d3-mod-operacao)}
.d3m-d-ct-av.c1{background:var(--d3-agente)}
.d3m-d-ct-av.c2{background:var(--d3-mod-time)}
.d3m-d-ct-av.c3{background:var(--d3-mod-vybe)}
.d3m-d-ct-av.c4{background:var(--d3-info)}
.d3m-d-ct-n{min-width:0;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-d-ct-v{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}
b.d3m-d-ct-v{font-weight:500}
.d3m-d-ct-d{font-size:var(--d3-fs-apoio);white-space:nowrap;font-variant-numeric:tabular-nums}
.d3m-d-ct-lin .q{color:var(--d3-rotulo)}
.d3m-d-ct-regua{display:inline-flex;gap:3px;width:228px}
.d3m-d-ct-regua > i{flex:none;display:grid;place-items:center;width:16px;height:18px;border-radius:4px;background:var(--d3-veu);font:600 10px var(--vv-texto,Inter,sans-serif);font-style:normal}
.d3m-d-ct-regua > i.on{background:var(--d3-tinta);color:var(--d3-contra,var(--d3-escuro-texto))}
.d3m-d-ct-regua > i.on.r{background:var(--d3-perigo);color:var(--d3-escuro-texto)}
.d3m-d-ct-r{text-align:right;font-size:var(--d3-fs-apoio);white-space:nowrap;font-variant-numeric:tabular-nums}
.d3m-d-ct-r.a{font-weight:500;color:var(--d3-ambar)}
.d3m-d-ct-r.r{font-weight:500;color:var(--d3-perigo)}
.d3m-d-ct-r.k{font-weight:500}
.d3m-d-ct-li{margin:0}
.d3m-d-ct-li:first-child > .d3m-d-ct-lin{border-top:0}
.d3m-d-ct-li[aria-expanded="true"],.d3m-d-ch-li[aria-expanded="true"]{background:var(--d3-veu)}
/* O que abre no lugar: o histórico e os botões, ou o formulário de sempre. */
.d3m-d-ct-mais{display:none;margin:0;padding:0 16px 12px 114px}
[aria-expanded="true"] > .d3m-d-ct-mais{display:block}
.d3m-d-ct-mais > p{margin:0 0 4px;font-size:var(--d3-fs-apoio);line-height:1.4;color:var(--d3-rotulo)}
.d3m-d-ct-acoes{display:flex;flex-wrap:wrap;gap:6px;margin:8px 0 0}
.d3m-d-ct-btn{appearance:none;flex:none;display:inline-flex;align-items:center;justify-content:center;height:28px;margin:0;padding:0 10px;border:0;border-radius:var(--d3-r-botao);background:var(--d3-veu);box-shadow:none;color:var(--d3-tinta);font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);white-space:nowrap;cursor:pointer}
.d3m-d-ct-btn:hover{background:var(--d3-veu-forte)}
.d3m-d-ct-btn.k{background:var(--d3-tinta);color:var(--d3-contra,var(--d3-escuro-texto))}
/* O formulário de sempre (.vc-form), na folha. */
#vv-carteira.d3m-d-m .vc-form{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin:8px 0 0;padding:0}
#vv-carteira.d3m-d-m .vc-form .vc-campo.largo,#vv-carteira.d3m-d-m .vc-form .vc-linha-acoes{grid-column:1 / -1}
#vv-carteira.d3m-d-m :is(.vc-campo,.vc-ordem){display:flex;flex-direction:column;gap:3px;min-width:0;color:var(--d3-rotulo);font:500 var(--d3-fs-mini) var(--vv-texto,Inter,sans-serif)}
#vv-carteira.d3m-d-m :is(.vc-campo,.vc-ordem) :is(select,input,textarea){width:100%;min-height:34px;padding:6px 10px;border:1px solid var(--d3-veu-forte);border-radius:var(--d3-r-botao);background-color:var(--d3-cartao);color:var(--d3-tinta);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif)}
#vv-carteira.d3m-d-m .vc-form .vc-linha-acoes{display:flex;justify-content:flex-end;gap:8px;padding:4px 0 0}
#vv-carteira.d3m-d-m .vc-form :is(.vc-acao,.vc-sec){appearance:none;height:32px;margin:0;padding:0 14px;border:0;border-radius:var(--d3-r-botao);background:var(--d3-veu);box-shadow:none;color:var(--d3-tinta);font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);cursor:pointer}
#vv-carteira.d3m-d-m .vc-form .vc-acao{background:var(--d3-tinta);color:var(--d3-contra,var(--d3-escuro-texto));font-weight:600}
#vv-carteira.d3m-d-m .v2k-porque{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin:8px 0 0;font-size:var(--d3-fs-apoio);color:var(--d3-rotulo)}
#vv-carteira.d3m-d-m .v2k-porque > .v2c-sub{margin-right:4px;font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
#vv-carteira.d3m-d-m .v2k-porque > .v2c-chip{appearance:none;display:inline-flex;align-items:center;height:26px;margin:0;padding:0 10px;border:0;border-radius:var(--d3-r-botao);background:var(--d3-veu);box-shadow:none;color:var(--d3-tinta);font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);cursor:pointer}
#vv-carteira.d3m-d-m .v2k-porque > .v2c-chip[aria-pressed="true"]{background:var(--d3-tinta);color:var(--d3-contra,var(--d3-escuro-texto))}
/* "Registrar" e "Período e ordem": uma folha curta em cima da lista. */
.d3m-d-ct-registrar,.d3m-d-ct-periodo{flex:none;flex-direction:row;flex-wrap:wrap;align-items:flex-end;gap:8px 12px;padding:12px 16px;overflow:visible}
.d3m-d-ct-registrar > .vc-campo{flex:1 1 240px}
.d3m-d-ct-registrar > .vc-form,.d3m-d-ct-registrar > .v2k-porque,.d3m-d-ct-quem{flex:1 1 100%}
.d3m-d-ct-quem{margin:0;color:var(--d3-rotulo)}
.d3m-d-ct-quem > b{font-weight:600;color:var(--d3-tinta)}
.d3m-d-ct-registrar > .d3m-d-ct-btn{height:34px;padding:0 14px}
.d3m-d-ct-periodo{align-items:center}
.d3m-d-ct-periodo > .d3m-d-pk-seg{justify-content:flex-start}
.d3m-d-ct-periodo > .vc-ordem{flex:0 1 240px;flex-direction:row;align-items:center;gap:8px}
.d3m-d-ct-periodo > .d3m-d-elo{margin-left:auto}
.d3m-d-ct-periodo .vb-mes{display:inline-flex;align-items:center;gap:4px;margin:0;color:var(--d3-tinta)}
.d3m-d-ct-periodo .vb-mes > b{min-width:120px;font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);text-align:center}
.d3m-d-ct-periodo .vb-mes > button{appearance:none;display:grid;place-items:center;width:28px;height:28px;margin:0;padding:0;border:0;border-radius:var(--d3-r-botao);background:var(--d3-veu);color:var(--d3-tinta);cursor:pointer}
.d3m-d-ct-periodo .vb-mes > button:disabled{opacity:.4;cursor:default}
.d3m-d-ct-periodo .vb-mes > button > svg{width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
/* Vazio dentro da folha e a tira do que ainda não está ligado. */
.d3m-d-ct-nada{flex:1 1 auto;display:flex;flex-direction:column;align-items:flex-start;justify-content:center;gap:10px;min-height:64px;padding:16px;color:var(--d3-rotulo)}
.d3m-d-ct-nada > p{margin:0;font-size:var(--d3-fs-texto);color:var(--d3-rotulo)}
.d3m-d-ct-aviso{flex:none;display:flex;flex-wrap:wrap;align-items:center;gap:8px 12px;margin:0;padding:8px 12px;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu);color:var(--d3-fume-apagado);font-size:var(--d3-fs-apoio);line-height:1.4}
.d3m-d-ct-aviso > span{flex:1 1 320px;min-width:0}
.d3m-d-ct-aviso > span > b{font-weight:600;color:var(--d3-fume-texto)}
.d3m-d-ct-aviso > small{flex-basis:100%;font-size:var(--d3-fs-apoio);color:var(--d3-fume-apagado)}
.d3m-d-ct-aviso > .d3m-d-vbtn{height:28px;padding:0 10px;font-size:var(--d3-fs-apoio)}
/* Mês a mês, no lugar da lista: o número de agora, a linha e os meses. */
.d3m-d-ct-meses > .d3m-d-cab{gap:12px}
.d3m-d-ct-serie{flex:1 1 0;display:flex;flex-direction:column;gap:8px;min-height:0;padding:8px 16px 16px}
.d3m-d-ct-serie > p{display:flex;align-items:baseline;gap:10px;margin:0;font-size:var(--d3-fs-apoio);color:var(--d3-rotulo)}
.d3m-d-ct-serie > p > span.g{color:var(--d3-pronto)}
.d3m-d-ct-serie > p > span.r{color:var(--d3-perigo)}
.d3m-d-ct-serie > svg{flex:1 1 0;display:block;width:100%;min-height:80px}
.d3m-d-ct-eixo{flex:none;display:flex;justify-content:space-between;font-size:var(--d3-fs-mini);color:var(--d3-rotulo)}
.d3m-d-ct-eixo > .agora{font-weight:600;color:var(--d3-tinta)}
/* Clientes ativos em doze meses: o cartão de vidro com o número e a linha. */
.d3m-d-ct-cartao{appearance:none;display:flex;align-items:flex-end;justify-content:space-between;gap:12px;width:100%;height:72px;margin:0;padding:12px;box-sizing:border-box;border:0;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu);color:var(--d3-fume-texto);font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
.d3m-d-ct-cartao:hover,.d3m-d-ct-cartao[aria-pressed="true"]{background:var(--d3-fume-veu-forte)}
.d3m-d-ct-cartao > span{display:flex;flex-direction:column;gap:4px;min-width:0}
.d3m-d-ct-cartao > span > b{font:600 24px/1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);font-variant-numeric:tabular-nums}
.d3m-d-ct-cartao > span > small{font-size:var(--d3-fs-apoio);color:var(--d3-fume-apagado);white-space:nowrap}
.d3m-d-ct-cartao > svg.d3m-d-mini{width:120px;height:44px;color:var(--d3-fume-texto)}

/* ----- Churn ----- */
.d3m-d-ch .d3m-d-nums{flex:none}
.d3m-d-ch-meio{flex:1 1 0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;min-height:150px}
.d3m-d-ch-meio > .d3m-d-folha > .d3m-d-cab{height:44px}
.d3m-d-ch-corpo{flex:1 1 0;display:flex;flex-direction:column;justify-content:flex-end;min-height:0;padding:0 16px 14px;overflow:hidden}
.d3m-d-ch-porque > .d3m-d-ch-corpo{justify-content:center}
.d3m-d-ch-corpo > .d3m-d-ct-nada{padding:0}
/* Barras dos seis meses: o número em cima, a barra e o mês. */
.d3m-d-ch-barras{flex:1 1 0;display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:16px;min-height:0}
.d3m-d-ch-barras > span{display:flex;flex-direction:column;align-items:stretch;justify-content:flex-end;gap:6px;min-height:0;text-align:center}
.d3m-d-ch-barras > span > b{font:600 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);font-variant-numeric:tabular-nums}
.d3m-d-ch-barras > span > i{flex:none;height:4px;border-radius:2px;background:var(--d3-veu-forte)}
.d3m-d-ch-barras > span > i.on{flex:0 1 calc(var(--n,0) * 64px);min-height:12px;height:auto;border-radius:6px;background:var(--d3-perigo)}
.d3m-d-ch-barras > span > small{font-size:var(--d3-fs-apoio);color:var(--d3-rotulo)}
.d3m-d-ch-barras > span > small.agora{font-weight:600;color:var(--d3-tinta)}
/* Por que saíram: o motivo, a barra e quantas vezes. */
.d3m-d-ch-mots{display:flex;flex-direction:column;gap:2px;max-height:100%;overflow-y:auto;scrollbar-width:thin}
.d3m-d-ch-motl{display:grid;grid-template-columns:minmax(0,160px) minmax(0,1fr) 24px;align-items:center;gap:12px;min-height:28px;margin:0;font-size:var(--d3-fs-texto);color:var(--d3-tinta)}
.d3m-d-ch-motl > span:first-child{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-d-ch-motl.a > span:first-child{color:var(--d3-ambar)}
.d3m-d-ch-motl > b{font-weight:600;text-align:right;font-variant-numeric:tabular-nums}
.d3m-d-ch-barra{height:4px;border-radius:2px;background:var(--d3-veu);overflow:hidden}
.d3m-d-ch-barra > i{display:block;width:var(--v,0%);height:100%;border-radius:2px;background:var(--d3-perigo)}
.d3m-d-ch-motl.a .d3m-d-ch-barra > i{background:var(--d3m-d-ambar)}
/* Retenção por mês de entrada (a tabela de sempre), na folha. */
.d3m-d-ch-cohort{min-height:0;max-height:100%;overflow:auto;scrollbar-width:thin}
#vv-carteira.d3m-d-m .d3m-d-ch-cohort table{width:100%;border-collapse:collapse;font-size:var(--d3-fs-apoio);color:var(--d3-tinta)}
#vv-carteira.d3m-d-m .d3m-d-ch-cohort :is(th,td){height:26px;padding:0 8px;border:0;border-top:1px solid var(--d3-divisa);background:none;color:var(--d3-tinta);font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}
#vv-carteira.d3m-d-m .d3m-d-ch-cohort thead th{border-top:0;color:var(--d3-rotulo)}
#vv-carteira.d3m-d-m .d3m-d-ch-cohort :is(th,td):first-child{text-align:left}
#vv-carteira.d3m-d-m .d3m-d-ch-cohort td.u2{color:var(--d3-ambar);font-weight:500}
#vv-carteira.d3m-d-m .d3m-d-ch-cohort td.u3a{color:var(--d3-perigo);font-weight:500}
#vv-carteira.d3m-d-m .d3m-d-ch-cohort td.u6{color:var(--d3-pronto);font-weight:500}
#vv-carteira.d3m-d-m .d3m-d-ch-cohort .vc-nota{margin:8px 0 0;font-size:var(--d3-fs-apoio);color:var(--d3-rotulo)}
/* Quem saiu: a folha de baixo, em colunas. */
.d3m-d-ch-quem{flex:0 1 auto;max-height:42%}
/* Com o formulário aberto, as duas folhas do meio saem e "Quem saiu" ocupa a altura. */
.d3m-d-ch.com-form .d3m-d-ch-meio{display:none}
.d3m-d-ch-quem.com-form{flex:1 1 0;max-height:none}
.d3m-d-ch-quem.com-form > .d3m-d-ct-rolo{flex:1 1 0}
.d3m-d-ch-quem > .d3m-d-cab{height:44px;gap:12px}
.d3m-d-ch-quem > .d3m-d-ct-rolo{flex:0 1 auto}
.d3m-d-ch-lin{display:grid;grid-template-columns:minmax(0,1fr) 84px 110px minmax(0,.8fr) 96px 84px 130px;align-items:center;gap:10px;height:48px;margin:0;padding:0 16px;box-sizing:border-box;border-top:1px solid var(--d3-divisa);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}
.d3m-d-ch-lin.sem-valor{grid-template-columns:minmax(0,1fr) 84px 110px minmax(0,.8fr) 84px 130px}
.d3m-d-ch-cabl{flex:none;height:24px;border-top:0;font-size:var(--d3-fs-apoio);color:var(--d3-rotulo)}
.d3m-d-ch-lin > span{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-variant-numeric:tabular-nums}
.d3m-d-ch-lin > .d3m-d-ch-v{text-align:right}
.d3m-d-ch-lin > .d3m-d-ch-mot.a{font-weight:500;color:var(--d3-ambar)}
.d3m-d-ch-lin > .d3m-d-ct-btn{justify-self:end;height:30px;background:none;box-shadow:inset 0 0 0 1px var(--d3-veu-forte)}
.d3m-d-ch-lin > .d3m-d-ct-btn:hover{background:var(--d3-veu)}
.d3m-d-ch-n{appearance:none;min-width:0;height:32px;margin:0;padding:0;border:0;border-radius:4px;background:none;box-shadow:none;color:var(--d3-tinta);font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);text-align:left;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;cursor:pointer}
.d3m-d-ch-n:hover{text-decoration:underline;text-underline-offset:3px}
.d3m-d-ch-li{margin:0}
.d3m-d-ch-li > .d3m-d-ct-mais{padding:0 16px 12px}
/* Retenção por ano de entrada, no vidro. */
.d3m-d-ch-ret{appearance:none;display:flex;flex-direction:column;gap:2px;width:100%;margin:0;padding:8px 12px;box-sizing:border-box;border:0;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu);color:var(--d3-fume-texto);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
.d3m-d-ch-ret:hover{background:var(--d3-fume-veu-forte)}
.d3m-d-ch-ret > span{display:grid;grid-template-columns:40px minmax(0,1fr) 40px;align-items:center;gap:12px;height:23px}
.d3m-d-ch-ret > span > small{font-size:var(--d3-fs-texto);color:var(--d3-fume-apagado);font-variant-numeric:tabular-nums}
.d3m-d-ch-ret > span > b{font-weight:600;text-align:right;font-variant-numeric:tabular-nums}
.d3m-d-ct-lado .d3m-vlin > .d3m-d-ct-av{width:22px;height:22px;border-radius:7px;font-size:9px}

/* Tela baixa (1366 × 768): as linhas e o laranja um degrau menores. */
@media (max-height:820px){
  .d3m-d-ct-lin{height:32px}
  .d3m-d-ct-cabl{height:24px}
  .d3m-d-ct-av{width:24px;height:24px;border-radius:7px}
  .d3m-d-ct-folha > .d3m-d-cab,.d3m-d-ch-meio > .d3m-d-folha > .d3m-d-cab,.d3m-d-ch-quem > .d3m-d-cab{height:40px}
  .d3m-d-ct-pesa{min-height:188px;padding:12px 16px}
  .d3m-d-ct-pesa .d3m-lar-num{font-size:40px}
  .d3m-d-ct-pesa .d3m-lar-txt > .d3-acao-frase{font-size:16px}
  .d3m-d-ct-pesa .d3m-lar-bts{margin-top:6px}
  .d3m-d-ct-lado{gap:10px}
  .d3m-d-ct-lado .d3m-cons{gap:4px}
  .d3m-d-ct-lado .d3m-cons > .d3m-vlin{height:32px}
  .d3m-d-ct-cartao{height:60px;padding:8px 12px}
  .d3m-d-ch-lin{height:40px}
  .d3m-d-ch-cabl{height:22px}
  .d3m-d-ch-meio{min-height:120px}
  .d3m-d-ch-ret > span{height:20px}
}
/* Janela estreita: a coluna de consulta e a régua encolhem. */
@media (max-width:1280px){
  .d3m-d-ct{grid-template-columns:minmax(0,1fr) 264px}
  .d3m-d-ct-lin{grid-template-columns:52px 24px minmax(0,1fr) 84px 60px 228px 84px;gap:8px}
  .d3m-d-ct-lin.sem-valor{grid-template-columns:52px 24px minmax(0,1fr) 60px 228px 84px}
  .d3m-d-ct-av{width:24px;height:24px;border-radius:7px}
  .d3m-d-ct-pesa .d3m-lar-bts > .d3m-btn{padding:0 10px}
  .d3m-d-ch-lin{grid-template-columns:minmax(0,1fr) 64px 92px minmax(0,.8fr) 84px 76px 118px;gap:8px}
  .d3m-d-ch-lin.sem-valor{grid-template-columns:minmax(0,1fr) 64px 92px minmax(0,.8fr) 76px 118px}
}
/* Celular: uma coluna só, o laranja primeiro, e a janela rola; a linha fica com o nome, o valor e a renovação. */
@media (max-width:900px){
  body.mundo .vc-camada > #vv-carteira.vc-janela.d3m-d-m{padding:12px;gap:12px;overflow-y:auto;border-radius:0 0 14px 14px}
  #vv-carteira.d3m-d-m > .vc-corpo.d3m-d-m-corpo{flex:none;overflow:visible}
  .d3m-d-ct-topo{flex-wrap:wrap;gap:8px}
  .d3m-d-ct-topo > .d3m-d-ferr{flex:1 1 100%;flex-wrap:wrap}
  .d3m-d-ct-topo .d3m-d-sub{white-space:normal}
  .d3m-d-ct-topo .d3m-d-ct-busca{flex:1 1 140px}
  .d3m-d-ct{display:flex;flex-direction:column;height:auto;gap:12px}
  .d3m-d-ct-main,.d3m-d-ct-lado{display:contents}
  .d3m-d-ct-pesa{order:-1;min-height:200px}
  .d3m-d-ct-folha,.d3m-d-ch-quem,.d3m-d-ch-quem.com-form{flex:none;max-height:none}
  .d3m-d-ct-folha > .d3m-d-cab,.d3m-d-ch-quem > .d3m-d-cab,.d3m-d-ch-meio > .d3m-d-folha > .d3m-d-cab{height:auto;flex-wrap:wrap;padding:10px 16px}
  .d3m-d-ct-folha .d3m-d-pk-seg,.d3m-d-ch-quem .d3m-d-pk-seg{flex:1 1 100%;justify-content:flex-start}
  .d3m-d-ct-rolo,.d3m-d-ch-quem > .d3m-d-ct-rolo{flex:none;overflow:visible}
  .d3m-d-ct-cabl,.d3m-d-ch-cabl{display:none}
  .d3m-d-ct-lin,.d3m-d-ct-lin.sem-valor{grid-template-columns:28px minmax(0,1fr) auto;grid-auto-rows:auto;gap:2px 10px;height:auto;min-height:52px;padding:8px 16px}
  .d3m-d-ct-lin > :is(.d3m-d-ct-regua,.d3m-d-ct-d){display:none}
  .d3m-d-ct-lin > .d3m-d-ct-g{grid-column:1 / -1;grid-row:1}
  .d3m-d-ct-lin > .d3m-d-ct-g:empty{display:none}
  .d3m-d-ct-lin > .d3m-d-ct-av{grid-column:1;grid-row:2 / span 2}
  .d3m-d-ct-lin > .d3m-d-ct-n{grid-column:2;grid-row:2}
  .d3m-d-ct-lin > .d3m-d-ct-v{grid-column:3;grid-row:2}
  .d3m-d-ct-lin > .d3m-d-ct-r{grid-column:2 / -1;grid-row:3;text-align:left}
  .d3m-d-ct-mais{padding:0 16px 12px}
  #vv-carteira.d3m-d-m .vc-form{grid-template-columns:minmax(0,1fr)}
  .d3m-d-ch-meio{flex:none;grid-template-columns:minmax(0,1fr);min-height:0}
  .d3m-d-ch-meio > .d3m-d-folha{min-height:220px}
  .d3m-d-ch-lin,.d3m-d-ch-lin.sem-valor{grid-template-columns:minmax(0,1fr) auto;grid-auto-rows:auto;gap:2px 10px;height:auto;padding:10px 16px}
  .d3m-d-ch-lin > .d3m-d-ch-n{grid-column:1;grid-row:1;height:24px}
  .d3m-d-ch-lin > span{font-size:var(--d3-fs-apoio);color:var(--d3-rotulo)}
  .d3m-d-ch-lin > span:nth-of-type(1){grid-column:2;grid-row:1;text-align:right}
  .d3m-d-ch-lin > span:nth-of-type(n+2){grid-column:1}
  .d3m-d-ch-lin > .d3m-d-ch-v{text-align:left}
  .d3m-d-ch-lin > .d3m-d-ct-btn{grid-column:2;grid-row:2 / span 3;align-self:center;height:40px}
  .d3m-d-ct-btn{min-height:40px}
  .d3m-d-ct-periodo > .d3m-d-elo{margin-left:0}
}

/* ===== padrao-v2/zm-d-comercial.css ===== */
/* ===================================================================================================================
   COMERCIAL · CRM E FUNIL NA PRANCHA V2-M-Comercial (16/11/2026). A janela é vidro fumê (zm-d-0-pecas.css). Em cima, três
   números em folha; no meio, o quadro: uma coluna de vidro por fase aberta, com o cartão de 84 de cada oportunidade (a
   lista rola por dentro da coluna e o cartão abre no lugar, com o próximo passo e os botões); no pé, Ganho e Perdido em
   duas linhas. A coluna de consulta fica no vidro: o cartão laranja da proposta mais parada, as conversas do WhatsApp,
   por que se perde e o "Abrir". A lista, uma fase só e "Metas, corrida e formulário" abrem em folha no lugar do quadro.
   O HTML vem de vybe-mundo-comercial.js (topoM e funilM); as peças .d3m-d-* são de zm-d-0-pecas.css e as .d3m-* de
   z-direcao.css.
   =================================================================================================================== */
.d3m-d-cm{display:grid;grid-template-columns:minmax(0,1fr) 316px;gap:16px;height:100%;min-height:0;margin:0;padding:0;color:var(--d3-tinta);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif)}
.d3m-d-cm-main{display:flex;flex-direction:column;gap:12px;min-width:0;min-height:0}
/* Topo: a busca abre ao lado da lupa. */
.d3m-d-cm-topo .d3m-d-cm-busca{appearance:none;flex:0 1 180px;width:180px;min-width:0;height:34px;margin:0;padding:0 12px;box-sizing:border-box;border:0;border-radius:var(--d3-r-botao);background:var(--d3-fume-veu);box-shadow:inset 0 0 0 1px var(--d3-fume-borda);color:var(--d3-fume-texto);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif)}
.d3m-d-cm-topo .d3m-d-cm-busca::placeholder{color:var(--d3-fume-apagado)}
.d3m-d-cm-topo .d3m-d-cm-busca:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}
.d3m-d-cm-topo .d3m-d-ico[aria-expanded="true"]{background:var(--d3-fume-texto);color:var(--d3-tinta)}
.d3m-d-cm-topo .d3m-d-ico > svg,.d3m-d-cm-topo .d3m-d-troca > summary > svg{width:16px;height:16px}
.d3m-d-cm-topo .d3m-d-vbtn > svg{width:14px;height:14px}
.d3m-d-cm-topo .d3m-d-tit h2{padding:0;border:0;background:none}

/* O quadro: uma coluna de vidro por fase. */
.d3m-d-cm-quadro{flex:1 1 0;display:grid;grid-template-columns:repeat(var(--n,5),minmax(0,1fr));gap:8px;min-height:0}
.d3m-d-cm-col{display:flex;flex-direction:column;gap:8px;min-width:0;min-height:0;margin:0;padding:8px;box-sizing:border-box;border-radius:12px;background:var(--d3-fume-veu);color:var(--d3-fume-texto)}
.d3m-d-cm-col-cab{flex:none;display:flex;justify-content:space-between;align-items:baseline;gap:6px;height:24px;padding:0 4px;font-size:var(--d3-fs-apoio)}
.d3m-d-cm-col-cab > b{min-width:0;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-d-cm-col-cab > b > span{font-weight:400;color:var(--d3-fume-apagado);font-variant-numeric:tabular-nums}
.d3m-d-cm-col-cab > span{flex:none;color:var(--d3-fume-apagado);white-space:nowrap;font-variant-numeric:tabular-nums}
.d3m-d-cm-ops{flex:1 1 0;display:flex;flex-direction:column;gap:8px;min-height:0;overflow-y:auto;scrollbar-width:thin}
/* O cartão da oportunidade: empresa e valor em cima; há quanto tempo e quem cuida embaixo. */
.d3m-d-cm-op{flex:none;margin:0;border-radius:var(--d3-r-caixa);background:var(--d3-folha);box-shadow:var(--d3-folha-sombra);color:var(--d3-tinta)}
.d3m-d-cm-op-b{appearance:none;display:flex;flex-direction:column;justify-content:space-between;width:100%;height:84px;margin:0;padding:10px;box-sizing:border-box;border:0;border-radius:var(--d3-r-caixa);background:none;box-shadow:none;color:inherit;font:inherit;text-align:left;cursor:pointer}
.d3m-d-cm-op-b:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:1px}
.d3m-d-cm-op-t{display:flex;flex-direction:column;gap:3px;min-width:0}
.d3m-d-cm-op-t > b{font:600 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-d-cm-op-t > span{font-size:var(--d3-fs-apoio);color:var(--d3-rotulo);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-variant-numeric:tabular-nums}
.d3m-d-cm-op-pe{display:flex;align-items:center;justify-content:space-between;gap:6px;min-height:20px;font-size:var(--d3-fs-mini)}
.d3m-d-cm-op-pe > span{min-width:0;color:var(--d3-rotulo);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-d-cm-op-pe > span.r{color:var(--d3-perigo);font-weight:500}
.d3m-d-cm-op-pe > span.g{color:var(--d3-pronto);font-weight:500}
.d3m-d-cm-av{flex:none;display:grid;place-items:center;width:20px;height:20px;border-radius:50%;background:var(--d3-veu);color:var(--d3-tinta);font:600 10px var(--vv-texto,Inter,sans-serif);font-style:normal}
.d3m-d-cm-op[draggable="true"]{cursor:grab}
/* O que abre no lugar: o próximo passo, a etapa, quem cuida e os botões. */
.d3m-d-cm-mais{display:none;margin:0;padding:0 10px 10px}
.d3m-d-cm [aria-expanded="true"] > .d3m-d-cm-mais{display:block}
.d3m-d-cm-op[aria-expanded="true"]{box-shadow:var(--d3-folha-sombra),0 0 0 2px var(--d3-fume-texto)}
.d3m-d-cm-mais .v2c-pas{margin:0 0 4px;font-size:var(--d3-fs-apoio);line-height:1.4;color:var(--d3-rotulo)}
.d3m-d-cm-mais .v2c-pas > b{font-weight:600;color:var(--d3-tinta)}
.d3m-d-cm-mais .v2c-acoes{display:flex;flex-wrap:wrap;gap:6px;margin:8px 0 0}
.d3m-d-cm-mais .v2c-btn{appearance:none;display:inline-flex;align-items:center;height:28px;margin:0;padding:0 10px;border:0;border-radius:var(--d3-r-botao);background:var(--d3-veu);box-shadow:none;color:var(--d3-tinta);font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);white-space:nowrap;cursor:pointer}
.d3m-d-cm-mais .v2c-btn:hover{background:var(--d3-veu-forte)}
.d3m-d-cm-mais .v2c-btn.k{background:var(--d3-tinta);color:var(--d3-escuro-texto)}
.d3m-d-cm-mais .v2c-btn.ruim{color:var(--d3-perigo)}
.d3m-d-cm-mais .v2c-btn[data-estado="feito"]{background:var(--d3-pronto);color:var(--d3-escuro-texto)}
.d3m-d-cm-mais .v2c-btn:focus-visible{outline:2px solid var(--d3-acao);outline-offset:2px}
/* O pé da coluna Novo: o que o SDR propôs e o lead novo. */
.d3m-d-cm-col-pe{flex:none;display:flex;flex-direction:column;align-items:center;gap:2px;margin-top:auto}
.d3m-d-cm-sdr{font-size:var(--d3-fs-mini);color:var(--d3-fume-apagado);white-space:nowrap}
.d3m-d-cm-aqui{appearance:none;display:flex;align-items:center;justify-content:center;gap:6px;width:100%;height:30px;margin:0;padding:0;border:0;border-radius:var(--d3-r-botao);background:none;box-shadow:none;color:var(--d3-fume-texto);font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);cursor:pointer}
.d3m-d-cm-aqui:hover{background:var(--d3-fume-veu)}
.d3m-d-cm-aqui > svg{width:13px;height:13px}
.d3m-d-cm-aqui:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:1px}

/* Ganho e Perdido: duas linhas no vidro. */
.d3m-d-cm-fim{flex:none;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
.d3m-d-cm-fim > .d3m-vlin{height:40px;font-size:var(--d3-fs-apoio)}
.d3m-d-cm-fim > .d3m-vlin > span{flex:1 1 auto;min-width:0;color:var(--d3-fume-apagado);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-d-cm-fim > .d3m-vlin > span > b{font-weight:600;color:var(--d3-fume-texto)}
.d3m-d-cm-fim > .d3m-vlin[aria-pressed="true"]{background:var(--d3-fume-veu-forte);box-shadow:inset 0 0 0 1px var(--d3-fume-borda)}
.d3m-d-cm-fim > .d3m-vlin > svg,.d3m-d-cm-lado .d3m-vlin > svg{flex:none;width:14px;height:14px;stroke:var(--d3-fume-apagado)}

/* A folha que abre no lugar do quadro: a lista, uma fase só ou "Metas, corrida e formulário". */
.d3m-d-cm-folha{flex:1 1 0;min-height:0}
.d3m-d-cm-folha > .d3m-d-cab{border-bottom:1px solid var(--d3-divisa)}
.d3m-d-cm-rolo{flex:1 1 0;min-height:0;overflow-y:auto;scrollbar-width:thin}
.d3m-d-cm-li{margin:0}
.d3m-d-cm-li:first-child > .d3m-d-lin{border-top:0}
.d3m-d-cm-li > .d3m-d-lin > span > b{font-weight:600}
.d3m-d-cm-li > .d3m-d-lin > i.d3m-d-cm-av{width:20px;height:20px;background:var(--d3-veu)}
.d3m-d-cm-li > .d3m-d-cm-mais{padding:0 16px 12px 33px}
.d3m-d-cm-li[aria-expanded="true"]{background:var(--d3-veu)}
.d3m-d-cm-chips{flex:none;display:flex;flex-wrap:wrap;gap:6px;padding:10px 16px}
.d3m-d-cm-chips > button{appearance:none;display:inline-flex;align-items:center;gap:5px;height:28px;margin:0;padding:0 10px;border:0;border-radius:var(--d3-r-botao);background:var(--d3-veu);color:var(--d3-tinta);font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);cursor:pointer}
.d3m-d-cm-chips > button > b{font-weight:600}
.d3m-d-cm-chips > button[aria-pressed="true"]{background:var(--d3-tinta);color:var(--d3-escuro-texto)}
.d3m-d-cm-chips > button:focus-visible{outline:2px solid var(--d3-acao);outline-offset:2px}
.d3m-d-cm-nada{margin:0;padding:16px;font-size:var(--d3-fs-texto);color:var(--d3-rotulo)}
.d3m-d-cm-resto{padding:16px}
/* O aviso do que ainda não está ligado: uma tira no vidro. */
.d3m-d-cm-aviso{flex:none;display:flex;flex-wrap:wrap;align-items:center;gap:8px 12px;margin:0;padding:8px 12px;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu);color:var(--d3-fume-texto);font-size:var(--d3-fs-apoio);line-height:1.4}
.d3m-d-cm-aviso > span{flex:1 1 320px;min-width:0}
.d3m-d-cm-aviso > .d3m-d-cm-tec{flex-basis:100%;color:var(--d3-fume-apagado)}
.d3m-d-cm-aviso .v2c-btn{appearance:none;flex:none;height:28px;margin:0;padding:0 10px;border:0;border-radius:var(--d3-r-botao);background:var(--d3-fume-veu-forte);color:var(--d3-fume-texto);font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);cursor:pointer}

/* A coluna de consulta, no vidro. */
.d3m-d-cm-lado{min-height:0}
.d3m-d-cm-pesa{flex:none;min-height:244px}
.d3m-d-cm-lado > .d3m-cons{flex:none}
.d3m-d-cm-lado .d3m-vlin > span:first-of-type{flex:1 1 auto;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--d3-fume-apagado)}
.d3m-d-cm-lado .d3m-vlin > span:first-of-type > b{font-weight:600;color:var(--d3-fume-texto)}
.d3m-d-cm-lado .d3m-cons:not(.d3m-d-cm-abrir) > .d3m-vlin{height:40px}
.d3m-d-cm-zap{flex:none;display:grid;place-items:center;width:22px;height:22px;border-radius:7px;background:var(--d3-mod-vybe);color:var(--d3-escuro-texto)}
.d3m-d-cm-zap > svg{width:12px;height:12px}
.d3m-d-cm-mot{display:flex;flex-direction:column;padding:6px 0;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu)}
.d3m-d-cm-mot > button{appearance:none;display:grid;grid-template-columns:92px minmax(0,1fr) 20px;align-items:center;gap:10px;width:100%;height:23px;margin:0;padding:0 12px;border:0;border-radius:6px;background:none;color:var(--d3-fume-texto);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
.d3m-d-cm-mot > button:hover{background:var(--d3-fume-veu)}
.d3m-d-cm-mot > button > span:first-child{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-d-cm-mot > button > b{font-weight:600;text-align:right;font-variant-numeric:tabular-nums}
.d3m-d-cm-mot .d3m-vbarra > i{background:var(--d3-fume-texto)}
.d3m-d-cm-mot > button:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:-2px}

/* Tela baixa (1366 × 768): o laranja e as linhas um degrau menores. */
@media (max-height:820px){
  .d3m-d-cm-pesa{min-height:176px;padding:12px 16px}
  .d3m-d-cm-pesa .d3m-lar-num{font-size:40px}
  .d3m-d-cm-pesa .d3m-lar-txt > .d3-acao-frase{font-size:16px}
  .d3m-d-cm-pesa .d3m-lar-txt > small{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
  .d3m-d-cm-pesa .d3m-lar-bts{margin-top:6px}
  .d3m-d-cm-lado{gap:10px}
  .d3m-d-cm-lado .d3m-cons{gap:4px}
  .d3m-d-cm-lado .d3m-cons > .d3m-vlin{height:32px}
  .d3m-d-cm-lado .d3m-cons:not(.d3m-d-cm-abrir) > .d3m-vlin{height:34px}
  .d3m-d-cm-op-b{height:76px;padding:8px 10px}
}
/* Janela estreita: a coluna de consulta encolhe. */
@media (max-width:1180px){
  .d3m-d-cm{grid-template-columns:minmax(0,1fr) 264px}
  .d3m-d-cm-pesa .d3m-lar-bts > .d3m-btn{padding:0 10px}
}
/* Celular: uma coluna só, o laranja primeiro, e a janela rola; as fases viram uma coluna de cada vez. */
@media (max-width:900px){
  .d3m-d-cm-topo{flex-wrap:wrap;gap:8px}
  .d3m-d-cm-topo > .d3m-d-ferr{flex:1 1 100%;flex-wrap:wrap}
  .d3m-d-cm-topo .d3m-d-sub{white-space:normal}
  .d3m-d-cm{display:flex;flex-direction:column;height:auto;gap:12px}
  .d3m-d-cm-main{display:contents}
  .d3m-d-cm-lado{display:contents}
  .d3m-d-cm-pesa{order:-1;flex:none;min-height:200px}
  .d3m-d-cm-quadro{flex:none;display:flex;flex-direction:column}
  .d3m-d-cm-ops{flex:none;overflow:visible}
  .d3m-d-cm-fim{grid-template-columns:minmax(0,1fr)}
  .d3m-d-cm-folha{flex:none}
  .d3m-d-cm-rolo{flex:none;max-height:70vh}
}

/* ===================================================================================================================
   PRODUTOS E PACOTES NA PRANCHA V2-M-Pacotes (16/11/2026). Os números em folha, a esteira numa folha só (pacote e o que
   entra nele, tipo, preço, custo em horas, margem com a barra na cor do que diz e vendidos; a linha abre no lugar) com
   o "De olho" no pé, e a coluna de consulta com o laranja, o "Pede ação", a carga do time e o "Abrir". O HTML vem de
   abaPacotes (vybe-mundo-comercial.js). Custo e margem só são montados para quem é dono.
   =================================================================================================================== */
.d3m-d-pk > .d3m-d-cab{height:44px;border-bottom:0}
.d3m-d-cab > h3 > small{font-weight:400}
/* Fichas dentro da folha: texto, a escolhida com véu. */
.d3m-d-pk-seg{flex:none;display:inline-flex;flex-wrap:wrap;justify-content:flex-end;gap:2px;min-width:0}
.d3m-d-pk-seg > button{appearance:none;display:inline-flex;align-items:center;gap:6px;height:26px;margin:0;padding:0 10px;border:0;border-radius:var(--d3-r-botao);background:none;box-shadow:none;color:var(--d3-tinta);font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);white-space:nowrap;cursor:pointer}
.d3m-d-pk-seg > button > b{font-weight:400;color:var(--d3-rotulo);font-variant-numeric:tabular-nums}
.d3m-d-pk-seg > button:hover{background:var(--d3-veu)}
.d3m-d-pk-seg > button[aria-pressed="true"]{background:var(--d3-veu-forte);font-weight:600}
.d3m-d-pk-seg > button:focus-visible{outline:2px solid var(--d3-acao);outline-offset:1px}
/* A linha da esteira, em colunas. */
.d3m-d-pk-lin{appearance:none;display:grid;grid-template-columns:minmax(0,1fr) 72px 84px 104px 168px 88px 14px;align-items:center;gap:12px;width:100%;height:56px;margin:0;padding:0 16px;box-sizing:border-box;border:0;border-top:1px solid var(--d3-divisa);border-radius:0;background:none;box-shadow:none;color:var(--d3-tinta);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);text-align:left}
.d3m-d-pk-lin.sem-margem{grid-template-columns:minmax(0,1fr) 72px 84px 88px 14px}
button.d3m-d-pk-lin{cursor:pointer}
button.d3m-d-pk-lin:hover{background:var(--d3-veu)}
button.d3m-d-pk-lin:focus-visible{outline:2px solid var(--d3-acao);outline-offset:-2px}
.d3m-d-pk-cab{height:28px;border-top:0;font-size:var(--d3-fs-apoio);color:var(--d3-rotulo)}
.d3m-d-pk-n{min-width:0;color:var(--d3-rotulo);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-d-pk-n > b{font-weight:600;color:var(--d3-tinta)}
.d3m-d-pk-tipo{display:inline-flex;align-items:center;height:20px;padding:0 8px;border-radius:6px;background:var(--d3-veu);font:500 var(--d3-fs-mini) var(--vv-texto,Inter,sans-serif);font-style:normal;color:var(--d3-tinta)}
.d3m-d-pk-p,.d3m-d-pk-c,.d3m-d-pk-vd{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}
b.d3m-d-pk-p{font-weight:600}
b.d3m-d-pk-p.r{font-weight:500;color:var(--d3-perigo)}
.d3m-d-pk-c{color:var(--d3-rotulo)}
.d3m-d-pk-vd{font-size:var(--d3-fs-apoio)}
.d3m-d-pk-m{display:flex;align-items:center;gap:10px;min-width:0}
.d3m-d-pk-m > b{flex:none;width:38px;font-weight:600;text-align:right;font-variant-numeric:tabular-nums}
.d3m-d-pk-m > b.g{color:var(--d3-pronto)}
.d3m-d-pk-m > b.a{color:var(--d3-ambar)}
.d3m-d-pk-m > b.r{color:var(--d3-perigo)}
.d3m-d-pk-barra{flex:1 1 auto;min-width:20px;height:4px;border-radius:2px;background:var(--d3-veu-forte);overflow:hidden;color:var(--d3-mod-vybe)}
.d3m-d-pk-barra.a{color:var(--d3m-d-ambar)}
.d3m-d-pk-barra.r{color:var(--d3-perigo)}
.d3m-d-pk-barra > i{display:block;width:var(--v,0%);height:100%;border-radius:2px;background:currentColor}
.d3m-d-pk-lin > svg{width:14px;height:14px;stroke:var(--d3-rotulo)}
.d3m-d-pk-li{margin:0}
.d3m-d-pk-li.apagado > .d3m-d-pk-lin > .d3m-d-pk-n > b{color:var(--d3-rotulo)}
.d3m-d-pk-li[aria-expanded="true"]{background:var(--d3-veu)}
.d3m-d-pk-li > .d3m-d-cm-mais{padding:0 16px 12px}
/* "De olho": uma faixa de contadores no pé da folha. */
.d3m-d-pk-olho{flex:none;display:flex;align-items:center;gap:0;height:44px;padding:0 16px;border-top:1px solid var(--d3-divisa);overflow:hidden;font-size:var(--d3-fs-apoio);color:var(--d3-rotulo);white-space:nowrap}
.d3m-d-pk-olho > small{flex:none;margin-right:14px;font-size:inherit}
.d3m-d-pk-olho > span{flex:none;padding:0 12px;border-left:1px solid var(--d3-divisa)}
.d3m-d-pk-olho > small + span{padding-left:0;border-left:0}
.d3m-d-pk-olho b{margin-right:2px;font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);font-variant-numeric:tabular-nums}
.d3m-d-pk-olho b.a{color:var(--d3-ambar)}
.d3m-d-pk-olho b.r{color:var(--d3-perigo)}
.d3m-d-pk-olho > button{appearance:none;flex:none;height:28px;margin:0;padding:0 12px;border:0;border-left:1px solid var(--d3-divisa);border-radius:0;background:none;box-shadow:none;color:var(--d3-rotulo);font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);white-space:nowrap;cursor:pointer}
.d3m-d-pk-olho > button:hover,.d3m-d-pk-olho > button[aria-pressed="true"]{background:var(--d3-veu)}
.d3m-d-pk-olho > button:focus-visible{outline:2px solid var(--d3-acao);outline-offset:-2px}
/* "Pede ação" na coluna de consulta: o selo em texto, a frase e o botão na linha. */
.d3m-d-pk-ped{display:flex;align-items:center;gap:8px;min-height:40px;padding:4px 6px 4px 10px;box-sizing:border-box;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu);color:var(--d3-fume-texto)}
.d3m-d-pk-ped > span{flex:1 1 auto;display:flex;flex-direction:column;gap:1px;min-width:0;color:var(--d3-fume-apagado)}
.d3m-d-pk-ped > span > em{min-width:0;font-style:normal;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-d-pk-ped > span b{font-weight:600;color:var(--d3-fume-texto)}
.d3m-d-pk-ped > span > small{font-size:var(--d3-fs-mini);color:var(--d3-fume-apagado)}
.d3m-d-pk-ped > span > small.r{color:var(--d3-perigo-vidro)}
.d3m-d-pk-ped > span > small.a{color:var(--d3-ajuste-claro)}
.d3m-d-pk-ped > span > small.g{color:var(--d3-mod-vybe-claro)}
.d3m-d-pk-ped .v2c-cli,.d3m-d-pk-ped .v2c-cli *{color:var(--d3-fume-texto);font-weight:600}
.d3m-d-pk-ped > .v2c-btn{appearance:none;flex:none;height:28px;margin:0;padding:0 10px;border:0;border-radius:var(--d3-r-botao);background:var(--d3-fume-veu-forte);box-shadow:none;color:var(--d3-fume-texto);font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);white-space:nowrap;cursor:pointer}
.d3m-d-pk-ped > .v2c-btn:hover{background:rgba(255,255,255,.26)}
.d3m-d-pk-ped > .v2c-btn:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:1px}
.d3m-d-pk-serie{display:flex;flex-direction:column;gap:6px;margin-top:16px}
.d3m-d-pk-serie .d3-graf{display:block;width:100%;height:64px}
.d3m-d-pk-serie .d3c-carga-x{display:flex;justify-content:space-between;font-size:var(--d3-fs-mini);color:var(--d3-rotulo)}
@media (max-height:820px){
  .d3m-d-pk-lin{height:46px}
  .d3m-d-pk-cab{height:26px}
  .d3m-d-pk-ped{min-height:34px}
}
@media (max-width:1180px){
  .d3m-d-pk-lin{grid-template-columns:minmax(0,1fr) 64px 76px 84px 120px 76px 14px;gap:8px}
}
@media (max-width:900px){
  :is(.d3m-d-pk,.d3m-d-or) > .d3m-d-cab{height:auto;flex-wrap:wrap;padding:10px 16px}
  .d3m-d-pk-seg{flex:1 1 100%;justify-content:flex-start}
  .d3m-d-pk-cab{display:none}
  .d3m-d-pk-lin,.d3m-d-pk-lin.sem-margem{grid-template-columns:minmax(0,1fr) auto 14px;grid-auto-rows:auto;gap:2px 10px;height:auto;padding:10px 16px}
  .d3m-d-pk-lin > .d3m-d-pk-n{white-space:normal}
  .d3m-d-pk-lin > :is(span:nth-child(2),.d3m-d-pk-c,.d3m-d-pk-vd){display:none}
  .d3m-d-pk-lin > .d3m-d-pk-m{grid-column:1 / -1;grid-row:2}
  .d3m-d-pk-olho{height:auto;flex-wrap:wrap;gap:4px 0;padding:10px 16px;white-space:normal}
}

/* ===================================================================================================================
   ORÇAMENTOS NA PRANCHA V2-M-Orcamentos (16/11/2026). Duas folhas lado a lado: a lista em três grupos (Agora, Andando e
   Fechados), com o valor e a situação em ponto, e a proposta escolhida, com os itens, o total e o que dá para fazer
   com ela. Na coluna de consulta, o laranja do que vence, os números, o "Pede ação" e o "Abrir". O HTML vem de
   abaOrcamentos (vybe-mundo-comercial.js).
   =================================================================================================================== */
.d3m-d-or-main{flex-direction:row;gap:16px}
.d3m-d-or-main > .d3m-d-or{flex:3 1 0}
.d3m-d-or-main > .d3m-d-or-prop{flex:2 1 0}
/* A linha da lista: o grupo (uma vez), o cliente e o pacote, o valor e a situação. */
.d3m-d-or-lin{appearance:none;display:grid;grid-template-columns:64px minmax(0,1fr) auto;align-items:center;gap:6px;width:100%;height:64px;margin:0;padding:0 16px;box-sizing:border-box;border:0;border-top:1px solid var(--d3-divisa);border-radius:0;background:none;box-shadow:none;color:var(--d3-tinta);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
.d3m-d-or-lin:first-child{border-top:0}
.d3m-d-or-lin:hover{background:var(--d3-veu)}
.d3m-d-or-lin[aria-pressed="true"]{background:var(--d3-veu)}
.d3m-d-or-lin:focus-visible{outline:2px solid var(--d3-acao);outline-offset:-2px}
.d3m-d-or-g{font-size:var(--d3-fs-apoio);color:var(--d3-rotulo)}
.d3m-d-or-g.r{color:var(--d3-perigo)}
.d3m-d-or-n,.d3m-d-or-v{display:flex;flex-direction:column;gap:2px;min-width:0}
.d3m-d-or-n > b{font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-d-or-n > b *{color:inherit;font-weight:inherit}
/* O nome do cliente vem com a ficha da carteira; aqui é só o nome. */
#vv-comercial.d3m-d-m .d3m-d-pk-ped :is(.v2c-cli,.cliente-carteira){display:inline;margin:0;padding:0;border:0;border-radius:0;background:none;box-shadow:none;font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-texto)}
.d3m-d-or > .d3m-d-cab > h3{flex:1 0 auto}
.d3m-d-or > .d3m-d-pk-olho{padding:0 12px}
.d3m-d-or > .d3m-d-pk-olho > small{margin-right:10px}
.d3m-d-or > .d3m-d-pk-olho > :is(span,button){padding:0 10px}
.d3m-d-or-n > span{font-size:var(--d3-fs-apoio);color:var(--d3-rotulo);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-d-or-v{align-items:flex-end;white-space:nowrap}
.d3m-d-or-v > span:first-child{color:var(--d3-rotulo);font-variant-numeric:tabular-nums}
.d3m-d-or-v > span:first-child > b{font-weight:600;color:var(--d3-tinta)}
.d3m-d-or-v > span:last-child{display:inline-flex;align-items:center;gap:6px;font-size:var(--d3-fs-apoio)}
.d3m-d-or-v em{font-style:normal;color:var(--d3-rotulo)}
.d3m-d-or-v em.r{color:var(--d3-perigo)}
.d3m-d-or-v em.a{color:var(--d3-ambar)}
.d3m-d-or-pt{flex:none;width:7px;height:7px;border-radius:50%;background:var(--d3-meta)}
.d3m-d-or-pt.l{background:var(--d3-agente)}
.d3m-d-or-pt.g{background:var(--d3-mod-vybe)}
.d3m-d-or-pt.r{background:var(--d3-perigo)}
/* A proposta escolhida. */
.d3m-d-or-res{margin:0;padding:12px 16px;font-size:var(--d3-fs-apoio);line-height:1.5;color:var(--d3-rotulo)}
.d3m-d-or-it{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin:0 16px;padding:12px 0;border-top:1px solid var(--d3-divisa)}
.d3m-d-or-it > span{display:flex;flex-direction:column;gap:2px;min-width:0}
.d3m-d-or-it b{font-weight:600;font-variant-numeric:tabular-nums}
.d3m-d-or-it small{font-size:var(--d3-fs-apoio);color:var(--d3-rotulo)}
.d3m-d-or-tot{display:flex;align-items:flex-end;justify-content:space-between;gap:12px;margin:0 16px;padding:16px 0;border-top:1px solid var(--d3-divisa)}
.d3m-d-or-tot > span{display:flex;flex-direction:column;gap:4px;font-size:var(--d3-fs-apoio);color:var(--d3-rotulo)}
.d3m-d-or-tot > b{font:600 var(--d3-fs-numero)/1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.02em;white-space:nowrap;font-variant-numeric:tabular-nums}
.d3m-d-or-bts{flex:none;display:flex;flex-wrap:wrap;gap:8px;padding:12px 16px 16px}
.d3m-d-or-bt{appearance:none;flex:1 1 auto;display:inline-flex;align-items:center;justify-content:center;height:34px;margin:0;padding:0 12px;box-sizing:border-box;border:0;border-radius:var(--d3-r-botao);background:none;box-shadow:inset 0 0 0 1px var(--d3-veu-forte);color:var(--d3-tinta);font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);white-space:nowrap;cursor:pointer}
.d3m-d-or-bt:hover{background:var(--d3-veu)}
.d3m-d-or-bt.k{background:var(--d3-tinta);box-shadow:none;color:var(--d3-escuro-texto)}
.d3m-d-or-bt[data-estado="feito"]{background:var(--d3-pronto);box-shadow:none;color:var(--d3-escuro-texto)}
.d3m-d-or-bt:focus-visible{outline:2px solid var(--d3-acao);outline-offset:2px}
/* Os três números da coluna de consulta. */
.d3m-d-or-minis{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px}
.d3m-d-or-minis > span{display:flex;flex-direction:column;gap:2px;min-width:0;padding:10px;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu);color:var(--d3-fume-texto)}
.d3m-d-or-minis b{font:600 var(--d3-fs-destaque) var(--vv-texto,Inter,sans-serif);white-space:nowrap;font-variant-numeric:tabular-nums}
.d3m-d-or-minis small{font-size:var(--d3-fs-mini);color:var(--d3-fume-apagado);white-space:nowrap}
@media (max-height:820px){
  .d3m-d-or-lin{height:52px}
  .d3m-d-or-it{padding:8px 0}
  .d3m-d-or-tot{padding:10px 0}
  .d3m-d-or-minis > span{padding:6px 10px}
}
@media (max-width:1180px){
  .d3m-d-or-main{gap:12px}
  .d3m-d-or-lin{grid-template-columns:52px minmax(0,1fr) auto}
}
@media (max-width:900px){
  .d3m-d-or-lin{grid-template-columns:minmax(0,1fr) auto;height:auto;padding:10px 16px}
  .d3m-d-or-g:empty{display:none}
  .d3m-d-or-g{grid-column:1 / -1}
  .d3m-d-or-main > :is(.d3m-d-or,.d3m-d-or-prop){flex:none}
}

/* ===== padrao-v2/zm-d-financeiro.css ===== */
/* ===================================================================================================================
   FINANCEIRO · VORCARO (TESOURARIA) NA PRANCHA V2-M-Financeiro (16/11/2026). Só os donos. A janela é vidro fumê: três
   números em folha, "Pede decisão" e "Entrou e saiu", o cartão laranja (o lançamento que chegou pelo WhatsApp, com os
   campos para corrigir; sem ele, o item mais sério do "Pede decisão") e a coluna de consulta direto no vidro. "Lançar à
   mão" e "Decididas" abrem no lugar do gráfico. O HTML vem de vybe-mundo-financeiro.js (vorcaro e propostaHtml); as
   peças .d3m-d-* são de zm-d-0-pecas.css e as .d3m-* de z-direcao.css.
   =================================================================================================================== */
body.mundo #vv-comercial.fv2-casa:has(> .vc-corpo > .d3m-d-fx){border:0;border-radius:20px;background:var(--d3-fume);box-shadow:inset 0 0 0 1px var(--d3-fume-borda),0 30px 60px -40px rgba(0,0,0,.6);backdrop-filter:none;-webkit-backdrop-filter:none;color:var(--d3-fume-texto)}
#vv-comercial.fv2-casa > .vc-corpo:has(> .d3m-d-fx){padding:16px;overflow:hidden}
#vv-comercial .vc-corpo > .fv2.d3m-d-fx{display:flex;flex-direction:column;gap:16px;box-sizing:border-box;width:auto;max-width:none;height:100%;min-height:0;margin:0;padding:0;background:none;color:var(--d3-tinta);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif)}
/* Topo: o selo "só donos" vira texto com o cadeado; "Finanças" leva à visão do setor. */
#vv-comercial .fv2.d3m-d-fx .d3m-d-fx-topo .d3-selo-donos{display:inline-flex;align-items:center;gap:5px;height:auto;padding:0;border-radius:0;background:none;color:inherit;font:inherit;vertical-align:baseline}
#vv-comercial .fv2.d3m-d-fx .d3m-d-fx-topo .d3-selo-donos > svg{width:12px;height:12px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.d3m-d-fx-elo{appearance:none;margin:0;padding:0;border:0;border-radius:3px;background:none;color:inherit;font:inherit;text-decoration:underline;text-underline-offset:3px;cursor:pointer}
.d3m-d-fx-elo:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}

.d3m-d-fx-grade{flex:1 1 0;display:grid;grid-template-columns:minmax(0,1fr) 316px;gap:16px;min-height:0}
.d3m-d-fx-main{display:flex;flex-direction:column;gap:12px;min-width:0;min-height:0}
/* Os três números. */
.d3m-d-fx-nums{flex:none;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
.d3m-d-fx .d3m-d-fx-num{appearance:none;justify-content:space-between;width:auto;height:116px;padding:14px;text-align:left}
.d3m-d-fx button.d3m-d-fx-num{cursor:pointer}
.d3m-d-fx button.d3m-d-fx-num:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}
.d3m-d-fx-num-cab{display:flex;align-items:center;justify-content:space-between;gap:8px;font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}
.d3m-d-fx-num-cab > span:first-child{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-d-fx-num-cab > .d3m-d-selo{width:24px;height:24px}
#vv-comercial .fv2.d3m-d-fx .d3m-d-selo > svg{width:12px;height:12px;stroke-width:2.4}
#vv-comercial .fv2.d3m-d-fx .d3m-d-ico > svg,#vv-comercial .fv2.d3m-d-fx .d3m-d-troca > summary > svg{width:16px;height:16px}
.d3m-d-fx-num-pe{display:flex;align-items:flex-end;justify-content:space-between;gap:10px}
.d3m-d-fx-num-pe > span:first-child{display:flex;flex-direction:column;gap:4px;min-width:0}
.d3m-d-fx-v{font:600 var(--d3-fs-numero)/1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.02em;color:var(--d3-tinta);white-space:nowrap;font-variant-numeric:tabular-nums}
.d3m-d-fx-v.g{color:var(--d3-pronto)}
.d3m-d-fx-v.r{color:var(--d3-perigo)}
.d3m-d-fx-num-pe small{font:400 var(--d3-fs-mini) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#vv-comercial .fv2.d3m-d-fx svg.d3m-d-fx-mini{flex:none;display:block;width:84px;height:40px;overflow:visible;color:var(--d3-tinta)}
.d3m-d-fx-mini.r{color:var(--d3-perigo)}
.d3m-d-fx-mini.l{color:var(--d3-agente)}
.d3m-d-fx-mini > .veu{fill:currentColor;stroke:none;opacity:.14}
.d3m-d-fx-mini > .fio{fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round;vector-effect:non-scaling-stroke}
.d3m-d-fx-mini.l > .fio{stroke-dasharray:4 4}
.d3m-d-fx-duas{flex:none;display:flex;align-items:flex-end;gap:6px;width:84px;height:40px}
.d3m-d-fx-duas > i{flex:1 1 0;height:var(--v,0%);min-height:3px;border-radius:3px;background:var(--d3-mod-vybe)}
.d3m-d-fx-duas > i + i{background:var(--d3-meta)}

/* O meio: à esquerda "Pede decisão" e o lugar de baixo; à direita o laranja e a fila. */
.d3m-d-fx-meio{flex:1 1 0;display:grid;grid-template-columns:minmax(0,1fr) 380px;gap:12px;min-height:0}
.d3m-d-fx-esq,.d3m-d-fx-dir{display:flex;flex-direction:column;gap:12px;min-width:0;min-height:0}
.d3m-d-fx-pede{flex:0 1 auto;max-height:66%}
.d3m-d-fx-pede > .d3m-d-cab,.d3m-d-fx-baixo > .d3m-d-cab{height:44px;justify-content:space-between}
.d3m-d-fx .d3m-d-cab > h3{flex:0 1 auto;font:600 14px/1.25 var(--vv-texto,Inter,sans-serif);letter-spacing:0}
.d3m-d-fx .d3m-d-tit h1{font:600 24px/1.1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.02em}
.d3m-d-fx .d3m-d-cab > small{margin-left:auto}
.d3m-d-fx-rolo{flex:1 1 auto;min-height:0;overflow-y:auto;scrollbar-width:thin}
.d3m-d-fx-ach{display:flex;align-items:center;gap:10px;height:52px;padding:0 16px;box-sizing:border-box;border-top:1px solid var(--d3-divisa)}
.d3m-d-fx-ach > .d3m-d-selo.a{background:var(--d3m-d-ambar)}
.d3m-d-fx-ach > .d3m-d-selo.n{background:var(--d3-meta)}
.d3m-d-fx-ach-txt{flex:1 1 auto;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-d-fx-ach-txt > b{font-weight:600}
.d3m-d-fx-ach-txt > span{color:var(--d3-rotulo)}
.d3m-d-fx-ach-v{flex:none;min-width:96px;text-align:right;font-weight:500;white-space:nowrap;font-variant-numeric:tabular-nums}
.d3m-d-fx-ach-v:empty{display:none}
.d3m-d-fx-btn{appearance:none;flex:none;display:inline-flex;align-items:center;justify-content:center;width:76px;height:28px;margin:0;padding:0;border:0;border-radius:var(--d3-r-botao);background:none;box-shadow:inset 0 0 0 1px var(--d3-meta);color:var(--d3-tinta);font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);white-space:nowrap;cursor:pointer}
.d3m-d-fx-btn:hover{background:var(--d3-veu)}
.d3m-d-fx-btn:focus-visible{outline:2px solid var(--d3-acao);outline-offset:2px}
.d3m-d-fx-baixo{flex:1 1 0;min-height:150px}
.d3m-d-fx-leg{display:inline-flex;align-items:center;gap:10px}
.d3m-d-fx-leg > span{display:inline-flex;align-items:center;gap:5px;color:var(--d3-tinta)}
.d3m-d-fx-leg i{width:10px;height:10px;border-radius:3px;background:var(--d3-meta)}
.d3m-d-fx-leg i.e{background:var(--d3-mod-vybe)}
/* Entrou e saiu: um par de barras por mês, o valor em cima e o resultado embaixo. */
.d3m-d-fx-meses{flex:1 1 0;display:grid;grid-template-columns:repeat(var(--n,4),minmax(0,1fr));gap:20px;min-height:0;padding:0 24px 14px}
.d3m-d-fx-mes{display:flex;flex-direction:column;gap:6px;min-height:0}
.d3m-d-fx-par{flex:1 1 0;display:flex;align-items:flex-end;gap:6px;min-height:0}
.d3m-d-fx-par > span{flex:1 1 0;display:flex;flex-direction:column;justify-content:flex-end;align-items:center;gap:4px;height:100%;min-width:0;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);font-variant-numeric:tabular-nums}
.d3m-d-fx-par b{font-weight:600}
.d3m-d-fx-par i{flex:0 1 auto;width:100%;height:calc((100% - 20px) * var(--k,0));min-height:3px;border-radius:4px;background:var(--d3-meta)}
.d3m-d-fx-par i.e{background:var(--d3-mod-vybe)}
.d3m-d-fx-mes-pe{flex:none;display:flex;justify-content:space-between;font-size:var(--d3-fs-apoio)}
.d3m-d-fx-mes-pe > b{font-weight:500;font-variant-numeric:tabular-nums}
.d3m-d-fx-mes-pe > b.g{color:var(--d3-pronto)}
.d3m-d-fx-mes-pe > b.r{color:var(--d3-perigo)}

/* O cartão laranja com o lançamento do WhatsApp. */
.d3m-d-fx .d3m-d-fx-prop{flex:0 1 auto;gap:12px;min-height:0;margin:0;overflow-y:auto;scrollbar-width:none;transform:none}
.d3m-d-fx-quem{display:flex;align-items:center;gap:8px;margin:0;font-size:var(--d3-fs-apoio)}
.d3m-d-fx-quem > i{flex:none;display:grid;place-items:center;width:22px;height:22px;border-radius:50%;background:var(--d3-fume-escuro);color:var(--d3-escuro-texto);font:600 10px var(--vv-texto,Inter,sans-serif);font-style:normal}
.d3m-d-fx-quem b{font-weight:600}
.d3m-d-fx-val{display:flex;flex-direction:column;gap:4px;min-width:0}
.d3m-d-fx-prop .d3m-lar-num{font-size:52px;color:var(--d3-escuro-texto);white-space:nowrap}
.d3m-d-fx-prop .d3-acao-frase{flex:none;overflow:visible;white-space:normal;font:600 19px/1.25 var(--vv-titulo,"Inter Tight",Inter,sans-serif);color:var(--d3-escuro-texto)}
.d3m-d-fx-campos{display:flex;flex-direction:column;padding:2px 12px;border-radius:var(--d3-r-caixa);background:var(--d3-fume-escuro)}
.d3m-d-fx-campos > label{display:flex;align-items:center;justify-content:space-between;gap:12px;height:30px;margin:0;font-size:var(--d3-fs-apoio);color:var(--d3-escuro-texto)}
.d3m-d-fx-campos > label + label{border-top:1px solid var(--d3-fume-veu-forte)}
.d3m-d-fx-campos > label > span{flex:none}
.d3m-d-fx-campos :is(select,input){appearance:none;flex:0 1 190px;width:190px;min-width:0;height:24px;margin:0;padding:0 4px;box-sizing:border-box;border:0;border-radius:4px;background:none;box-shadow:none;color:var(--d3-escuro-texto);font:600 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);text-align:right;text-align-last:right;color-scheme:dark;cursor:pointer}
.d3m-d-fx-campos input{cursor:text}
.d3m-d-fx-campos :is(select,input):hover{background:var(--d3-fume-veu)}
.d3m-d-fx-campos :is(select,input):focus-visible{outline:2px solid var(--d3-escuro-texto);outline-offset:1px}
.d3m-d-fx-campos option{background:var(--d3-cartao);color:var(--d3-tinta)}
.d3m-d-fx-ja{font:400 var(--d3-fs-apoio)/1.4 var(--vv-texto,Inter,sans-serif)}
.d3m-d-fx-prop .d3m-lar-bts{align-items:center;margin-top:0}
.d3m-d-fx-descartar{appearance:none;height:34px;margin:0 0 0 auto;padding:0 4px;border:0;border-radius:var(--d3-r-botao);background:none;color:var(--d3-escuro-texto);font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);cursor:pointer}
.d3m-d-fx-descartar:hover{text-decoration:underline;text-underline-offset:3px}
.d3m-d-fx-descartar:focus-visible{outline:2px solid var(--d3-escuro-texto);outline-offset:2px}
/* A seguir: os outros lançamentos do grupo, no vidro. */
.d3m-d-fx-seguir{flex:0 0 auto;min-height:0;color:var(--d3-fume-texto)}
.d3m-d-fx-seguir > .d3m-d-fx-rolo{display:flex;flex-direction:column;gap:6px;max-height:86px}
.d3m-d-fx-seguir .d3m-vlin{flex:none;height:40px}
.d3m-d-fx-seguir .d3m-vlin > .d3m-vnome{flex:1 1 auto;max-width:none}
.d3m-d-fx-seguir .d3m-vlin small,.d3m-d-fx-lado .d3m-vlin small{font-size:inherit;color:var(--d3-fume-apagado)}
.d3m-d-fx-seguir .d3m-vlin b{font-weight:600}

/* A coluna de consulta. */
.d3m-d-fx-lado{min-height:0;overflow-y:auto;scrollbar-width:none}
.d3m-d-fx-lado .d3m-cons{flex:none}
.d3m-d-fx-lado .d3m-vlin{flex:none;height:34px}
.d3m-d-fx-lado .d3m-vlin > .d3m-vn{min-width:0;color:var(--d3-fume-texto)}
.d3m-d-fx-como{margin:0;font:400 var(--d3-fs-apoio)/1.5 var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-apagado)}
.d3m-d-fx .d3m-cons.fv2-olha{outline:2px solid var(--d3-fume-texto);outline-offset:6px;border-radius:6px}

/* "Lançar à mão" no lugar do gráfico: o formulário de antes, em folha, com a rolagem por dentro. */
.d3m-d-fx .d3m-d-fx-esq > .fx-form-caixa{flex:1 1 0;min-height:150px;margin:0;padding:14px 16px;box-sizing:border-box;border-radius:16px;overflow-y:auto;scrollbar-width:thin;background:var(--d3-cartao);box-shadow:var(--d3-folha-sombra)}

/* Tela baixa (1366 × 768): os números e o laranja encolhem um degrau. */
@media (max-height:820px){
  .d3m-d-fx .d3m-d-fx-num{height:92px;padding:12px 14px}
  .d3m-d-fx-v{font-size:24px}
  .d3m-d-fx-ach{height:40px}
  .d3m-d-fx-pede{max-height:72%}
  .d3m-d-fx-pede > .d3m-d-cab,.d3m-d-fx-baixo > .d3m-d-cab{height:40px}
  .d3m-d-fx .d3m-d-fx-prop{gap:6px;padding:12px 16px}
  .d3m-d-fx-prop .d3m-lar-num{font-size:32px}
  .d3m-d-fx-prop .d3-acao-frase{font-size:16px}
  .d3m-d-fx-campos > label{height:24px}
  .d3m-d-fx-campos :is(select,input){height:20px}
  .d3m-d-fx-lado .d3m-vlin{height:30px}
  .d3m-d-fx-lado,.d3m-d-fx-lado .d3m-cons{gap:4px}
  .d3m-d-fx-lado{gap:10px}
}
@media (max-width:1320px){
  .d3m-d-fx-grade{grid-template-columns:minmax(0,1fr) 248px}
  .d3m-d-fx-meio{grid-template-columns:minmax(0,1fr) 340px}
}
/* Celular e janela estreita: uma coluna, o laranja logo depois dos números, e a janela rola. */
@media (max-width:1100px){
  #vv-comercial.fv2-casa > .vc-corpo:has(> .d3m-d-fx){overflow:hidden auto;padding:12px}
  #vv-comercial .vc-corpo > .fv2.d3m-d-fx{height:auto}
  .d3m-d-fx-topo{flex-wrap:wrap;gap:8px}
  .d3m-d-fx-topo .d3m-d-sub{white-space:normal}
  .d3m-d-fx-grade,.d3m-d-fx-meio{display:flex;flex-direction:column}
  .d3m-d-fx-main,.d3m-d-fx-grade,.d3m-d-fx-meio,.d3m-d-fx-esq,.d3m-d-fx-dir,.d3m-d-fx-lado,.d3m-d-fx-seguir{flex:none;min-height:auto}
  .d3m-d-fx .d3m-d-fx-prop,.d3m-d-fx-pede{flex:none}
  .d3m-d-fx-rolo,.d3m-d-fx-seguir > .d3m-d-fx-rolo{max-height:none;overflow:visible}
  .d3m-d-fx-dir{order:-1}
  .d3m-d-fx-pede{max-height:none}
  .d3m-d-fx-baixo{flex:none;height:260px}
  .d3m-d-fx .d3m-d-fx-prop,.d3m-d-fx-lado{overflow:visible}
}
@media (max-width:640px){
  .d3m-d-fx-nums{grid-template-columns:minmax(0,1fr)}
  .d3m-d-fx-pede > .d3m-d-cab > small{display:none}
  .d3m-d-fx-ach{height:auto;min-height:52px;flex-wrap:wrap;padding:8px 16px}
  .d3m-d-fx-ach-txt{flex-basis:calc(100% - 40px);white-space:normal}
  .d3m-d-fx-ach-v{min-width:0;margin-left:32px;text-align:left}
  .d3m-d-fx-ach > .d3m-d-fx-btn{margin-left:auto}
  .d3m-d-fx-prop .d3m-lar-num{font-size:40px}
  .d3m-d-fx-campos :is(select,input){flex-basis:160px;width:160px}
}

/* ===== padrao-v2/zm-d-gestao.css ===== */
/* ===================================================================================================================
   GESTÃO · A AGÊNCIA INTEIRA NA PRANCHA V2-M-Gestao (16/11/2026). A janela é vidro fumê; por cima, quatro cartões folha
   (um por área: número grande na cor do que diz, o gráfico na mesma cor e três linhas) e a coluna de consulta direto no
   vidro (o cartão laranja do que pesa agora, a semana em linha e o "Abrir"). Finanças só é montado para os donos: sem
   ele, a Produção ocupa a linha de cima inteira. O HTML vem de vybe-mundo-setor.js (painel setor:agencia e o topo em
   pintarEm); as peças .d3m-d-* são de zm-d-0-pecas.css e as .d3m-* de z-direcao.css.
   =================================================================================================================== */
body.mundo .vv-gestao:has(> .vs-agencia){padding:16px;overflow:hidden;border:0;border-radius:20px;background:var(--d3-fume);box-shadow:inset 0 0 0 1px var(--d3-fume-borda),0 30px 60px -40px rgba(0,0,0,.6);backdrop-filter:none;-webkit-backdrop-filter:none;color:var(--d3-fume-texto)}
.vv-gestao > .vv-g-corpo.vs-agencia{display:flex;flex-direction:column;gap:16px;box-sizing:border-box;width:auto;max-width:none;height:100%;min-height:0;margin:0;padding:0}
.vv-gestao > .vs-agencia > .vs-corpo{flex:1 1 0;display:block;min-height:0;margin:0;padding:0}
/* O período do topo (a mesma barra dos setores) com as peças do vidro. */
.vs-agencia > .d3m-d-topo .vs-periodo{display:inline-flex;align-items:center;gap:8px;margin:0}
.vs-agencia > .d3m-d-topo .g2-vaga:empty{display:none}

.vs-agencia .d3m-d-g{position:relative;display:grid;grid-template-columns:minmax(0,1fr) 316px;gap:16px;height:100%;min-height:0;margin:0;padding:0;color:var(--d3-tinta)}
.vs-agencia .d3m-d-g-cartoes{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));grid-template-rows:repeat(2,minmax(0,1fr));gap:12px;min-width:0;min-height:0}
.vs-agencia .d3m-d-g.sem-fin > .d3m-d-g-cartoes > .d3m-d-g-c:first-child{grid-column:1 / -1}
.vs-agencia .d3m-d-g-meio{flex:1 1 0;display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:0;padding:0 16px 8px}
.vs-agencia .d3m-d-g-n{flex:0 1 auto;display:flex;flex-direction:column;gap:6px;min-width:0}
.vs-agencia .d3m-d-g-n > span{font:400 var(--d3-fs-apoio)/1.3 var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
/* Os gráficos do cartão: área, rosca e barras, na cor do número. */
.vs-agencia .d3m-d-g-graf{flex:0 1 240px;display:block;width:240px;min-width:0;height:120px;max-height:100%;overflow:visible;color:var(--d3-tinta)}
.vs-agencia .d3m-d-g-graf.r{color:var(--d3-perigo)}
.vs-agencia .d3m-d-g-graf.g{color:var(--d3-mod-vybe)}
.vs-agencia .d3m-d-g-graf > .veu{fill:currentColor;stroke:none;opacity:.14}
.vs-agencia .d3m-d-g-graf > .fio{fill:none;stroke:currentColor;stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round;vector-effect:non-scaling-stroke}
.vs-agencia .d3m-d-g-rosca{flex:none;display:block;width:104px;height:104px;max-height:100%;color:var(--d3-meta)}
.vs-agencia .d3m-d-g-rosca.r{color:var(--d3-perigo)}
.vs-agencia .d3m-d-g-rosca.a{color:var(--d3m-d-ambar)}
.vs-agencia .d3m-d-g-rosca.g{color:var(--d3-mod-vybe)}
.vs-agencia .d3m-d-g-rosca > .trilho{fill:none;stroke:var(--d3-veu-forte);stroke-width:10}
.vs-agencia .d3m-d-g-rosca > .fio{fill:none;stroke:currentColor;stroke-width:10;stroke-linecap:round}
.vs-agencia .d3m-d-g-barras{flex:0 1 240px;display:flex;align-items:flex-end;gap:6px;min-width:0;height:120px;max-height:100%}
.vs-agencia .d3m-d-g-barras > i{flex:1 1 0;height:var(--v,18%);border-radius:2px;background:var(--d3-agente)}
.vs-agencia .d3m-d-g-barras.vazio > i{background:var(--d3-veu-forte)}

/* A coluna de consulta, no vidro. */
.vs-agencia .d3m-d-g-lado{min-height:0}
.vs-agencia .d3m-d-g-pesa{flex:1 1 auto;min-height:0}
.vs-agencia .d3m-d-g-semana,.vs-agencia .d3m-d-g-abrir{flex:none}
.vs-agencia .d3m-d-g-sem{appearance:none;display:flex;flex-direction:column;gap:6px;width:100%;margin:0;padding:12px;box-sizing:border-box;border:0;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu);color:var(--d3-fume-texto);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
.vs-agencia .d3m-d-g-sem:hover{background:var(--d3-fume-veu-forte)}
.vs-agencia .d3m-d-g-sem:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}
.vs-agencia .d3m-d-g-sem-graf{display:block;width:100%;height:92px;overflow:visible}
.vs-agencia .d3m-d-g-sem-graf > .meta{fill:none;stroke:var(--d3-escuro-apagado);stroke-width:2;stroke-dasharray:4 5;vector-effect:non-scaling-stroke}
.vs-agencia .d3m-d-g-sem-graf > .fio{fill:none;stroke:var(--d3-fume-texto);stroke-width:2.4;stroke-linecap:round;vector-effect:non-scaling-stroke}
.vs-agencia .d3m-d-g-sem-graf > circle{fill:var(--d3-fume-texto)}
.vs-agencia .d3m-d-g-eixo{display:flex;justify-content:space-between;font-size:var(--d3-fs-mini);color:var(--d3-fume-apagado)}
.vs-agencia .d3m-d-g-eixo > .on{color:var(--d3-fume-texto);font-weight:600}
.vs-agencia .d3m-d-g-sem-vazio{font-size:var(--d3-fs-apoio);color:var(--d3-fume-apagado)}
.vs-agencia .d3m-d-g-minis{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;margin-top:4px}
.vs-agencia .d3m-d-g-minis > span{display:flex;flex-direction:column;gap:2px;min-width:0}
.vs-agencia .d3m-d-g-minis b{font-weight:600;font-variant-numeric:tabular-nums}
.vs-agencia .d3m-d-g-minis small{font-size:var(--d3-fs-mini);color:var(--d3-fume-apagado);white-space:nowrap}
.vs-agencia .d3m-d-g-abrir .d3m-vlin{flex:none}
.vs-agencia .d3m-d-g-abrir .d3m-vlin small{font-size:inherit;color:var(--d3-fume-apagado)}

/* "Números e gráficos" (o que já existia, a um clique): abre por cima dos quatro cartões, com a rolagem por dentro. */
.vs-agencia .d3m-d-g > details.g2-mais{display:none;margin:0}
.vs-agencia .d3m-d-g > details.g2-mais[open]{position:absolute;z-index:5;inset:0 332px 0 0;display:flex;flex-direction:column;padding:0;border:0;border-radius:16px;overflow:hidden;background:var(--d3-cartao);box-shadow:var(--d3-folha-sombra);color:var(--d3-tinta)}
.vs-agencia .d3m-d-g > details.g2-mais > summary{flex:none;display:flex;align-items:center;justify-content:space-between;gap:12px;height:48px;margin:0;padding:0 16px;box-sizing:border-box;border-bottom:1px solid var(--d3-divisa);list-style:none;font:600 14px/1.25 var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);cursor:pointer}
.vs-agencia .d3m-d-g > details.g2-mais > summary::-webkit-details-marker{display:none}
.vs-agencia .d3m-d-g > details.g2-mais > summary > u{font-size:0;text-decoration:none}
.vs-agencia .d3m-d-g > details.g2-mais > summary > u::after{content:"fechar";font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}
.vs-agencia .d3m-d-g > details.g2-mais > summary:focus-visible{outline:2px solid var(--d3-acao);outline-offset:-2px}
.vs-agencia .d3m-d-g > details.g2-mais > .g2-mais-corpo{flex:1 1 0;min-height:0;margin:0;padding:16px;overflow-y:auto;scrollbar-width:thin}

/* Tela baixa (1366 × 768): tudo encolhe um degrau e o gráfico da semana dá lugar aos três números. */
@media (max-height:820px){
  .vs-agencia .d3m-d-g-c > .d3m-d-cab{height:40px}
  .vs-agencia .d3m-d-g-c > .d3m-d-lin{height:34px}
  .vs-agencia .d3m-d-g-c .d3m-d-numero{font-size:36px}
  .vs-agencia .d3m-d-g-graf,.vs-agencia .d3m-d-g-barras{height:84px}
  .vs-agencia .d3m-d-g-rosca{width:80px;height:80px}
  .vs-agencia .d3m-d-g-pesa{padding:12px 16px}
  .vs-agencia .d3m-d-g-pesa .d3m-lar-num{font-size:44px}
  .vs-agencia .d3m-d-g-pesa .d3m-lar-txt > .d3-acao-frase{font-size:17px}
  .vs-agencia .d3m-d-g-pesa .d3m-lar-bts{margin-top:6px}
  .vs-agencia .d3m-d-g-sem-graf,.vs-agencia .d3m-d-g-eixo{display:none}
  .vs-agencia .d3m-d-g-minis{margin-top:0}
  .vs-agencia .d3m-d-g-abrir .d3m-vlin{height:32px}
  .vs-agencia .d3m-d-g-abrir{gap:4px}
}
/* Janela estreita: a coluna de consulta encolhe; no celular vira uma coluna só, o laranja primeiro, e a janela rola. */
@media (max-width:1180px){
  .vs-agencia .d3m-d-g{grid-template-columns:minmax(0,1fr) 264px}
  .vs-agencia .d3m-d-g > details.g2-mais[open]{right:280px}
  .vs-agencia .d3m-d-g-graf,.vs-agencia .d3m-d-g-barras{flex-basis:120px}
}
@media (max-width:900px){
  body.mundo .vv-gestao:has(> .vs-agencia){overflow-y:auto;padding:12px}
  .vv-gestao > .vv-g-corpo.vs-agencia{height:auto}
  .vs-agencia > .d3m-d-topo{flex-wrap:wrap;gap:8px}
  .vs-agencia > .d3m-d-topo > .d3m-d-ferr{flex:1 1 100%;flex-wrap:wrap}
  .vs-agencia .d3m-d-g{display:flex;flex-direction:column;height:auto;gap:12px}
  .vs-agencia .d3m-d-g-cartoes{display:flex;flex-direction:column}
  .vs-agencia .d3m-d-g-c{min-height:236px}
  .vs-agencia .d3m-d-g-lado{display:contents}
  .vs-agencia .d3m-d-g-pesa{order:-1;flex:none;min-height:200px}
  .vs-agencia .d3m-d-g > details.g2-mais[open]{position:static;max-height:70vh}
  .vs-agencia .d3m-d-g-sem-graf,.vs-agencia .d3m-d-g-eixo{display:block}
  .vs-agencia .d3m-d-g-eixo{display:flex}
}

/* ===== padrao-v2/zm-e-casca.css ===== */
/* ===================================================================================================================
   V2 · GRUPO E · A CASCA DAS TELAS (pranchas V2-M-Diario, Performance, IA-Custos, Automacoes, Conta-Equipe, RH-*,
   Equipe-Online, Academy e Toolkit, aprovadas pelo Paulo em 16/11/2026). O esqueleto comum das telas deste grupo:
   a janela de vidro fumê, o título direto no vidro (24, com a seta que troca de tela), a coluna de trabalho em folhas
   claras e a coluna de consulta de 316 px direto no vidro (.d3m-lado, de z-direcao.css). Peças locais (.d3m-e-*):
   quando outra área precisar, sobem para z-direcao.css com o nome .d3m-*.
   =================================================================================================================== */

/* A janela dos quadros deste grupo é vidro fumê. O quadro aberto fica no body (data-quadro, de switchBoard). */
body.mundo.mundo-modulo:is([data-quadro="diario"],[data-quadro="ai-usage"]) #mundo-moldura{border-radius:20px;background:var(--d3-fume);box-shadow:inset 0 0 0 1px var(--d3-fume-borda),0 30px 60px -40px rgba(0,0,0,.6)}

/* A tela: uma coluna da altura da janela. Fora do Irecity (?legado=1) ela mesma faz o fundo escuro. */
.d3m-e-tela{display:flex;flex-direction:column;min-width:0;height:100%;box-sizing:border-box;color:var(--d3-tinta);font:400 var(--d3-fs-texto)/1.4 var(--vv-texto,Inter,sans-serif)}
:where(body:not(.mundo)) .d3m-e-tela{min-height:560px;padding:16px;border-radius:20px;background:var(--d3-fume-painel)}
.d3m-e-tela :is(p,h3,h4){margin:0}

/* Topo no vidro: título com a seta de trocar de tela, a linha de apoio e as ações. À direita ficam os dois botões da janela. */
.d3m-e-topo{flex:none;display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:48px;margin:0 0 16px;padding:0 104px 0 0;color:var(--d3-fume-texto)}
.d3m-e-tit{display:flex;flex-direction:column;gap:3px;min-width:0}
.d3m-e-h{display:block;margin:0;font:600 24px/1.1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.02em;color:var(--d3-fume-texto);white-space:nowrap}
.d3m-e-sub{font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-apagado);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-e-acoes{flex:none;display:flex;align-items:center;gap:8px}
.d3m-e-troca{position:relative;align-self:flex-start}
.d3m-e-troca > summary{display:inline-flex;align-items:center;gap:6px;list-style:none;border-radius:var(--d3-r-botao);cursor:pointer}
.d3m-e-troca > summary::-webkit-details-marker{display:none}
.d3m-e-troca > summary > svg{flex:none;width:16px;height:16px;fill:none;stroke:var(--d3-fume-apagado);stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.d3m-e-troca > summary:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:3px}
.d3m-e-pop{position:absolute;z-index:5;left:0;top:calc(100% + 6px);display:flex;flex-direction:column;gap:2px;min-width:220px;padding:6px;border-radius:12px;background:var(--d3-cartao);box-shadow:0 18px 40px -18px rgba(0,0,0,.55),0 0 0 1px var(--d3-veu)}
.d3m-e-pop > button{appearance:none;display:flex;align-items:center;height:32px;margin:0;padding:0 10px;border:0;border-radius:var(--d3-r-botao);background:none;color:var(--d3-tinta);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);text-align:left;white-space:nowrap;cursor:pointer}
.d3m-e-pop > button:hover{background:var(--d3-veu)}
.d3m-e-pop > button.on{font-weight:600;background:var(--d3-veu)}
.d3m-e-pop > button:focus-visible{outline:2px solid var(--d3-acao);outline-offset:-2px}
.d3m-e-pop > span{padding:6px 10px;color:var(--d3-rotulo);font-size:var(--d3-fs-apoio)}
/* Botão de ícone no vidro (34 px, canto 8). */
.d3m-e-ico{appearance:none;flex:none;display:grid;place-items:center;width:34px;height:34px;margin:0;padding:0;border:0;border-radius:var(--d3-r-botao);background:var(--d3-fume-veu-forte);color:var(--d3-fume-texto);cursor:pointer}
.d3m-e-ico:hover{background:var(--d3-fume-borda)}
.d3m-e-ico > svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.d3m-e-ico:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}

/* Corpo: trabalho à esquerda, consulta de 316 à direita. Só as listas rolam, por dentro. */
.d3m-e-corpo{flex:1 1 0;min-height:0;display:grid;grid-template-columns:minmax(0,1fr) 316px;gap:16px}
.d3m-e-corpo.um{grid-template-columns:minmax(0,1fr)}
.d3m-e-main{display:flex;flex-direction:column;gap:12px;min-width:0;min-height:0}
.d3m-e-corpo > .d3m-lado{min-height:0;overflow-y:auto;scrollbar-width:thin;scrollbar-color:var(--d3-fume-borda) transparent}
.d3m-e-lado-txt{margin:0;font:400 var(--d3-fs-texto)/1.5 var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-apagado)}

/* A folha: cartão claro com cabeça de 44, divisória fina e o corpo. .cresce ocupa o que sobra e rola por dentro. */
.d3m-e-folha{flex:none;display:flex;flex-direction:column;min-width:0;box-sizing:border-box;border-radius:16px;overflow:hidden;background:var(--d3-folha);box-shadow:var(--d3-folha-sombra);color:var(--d3-tinta)}
.d3m-e-folha.cresce{flex:1 1 0;min-height:0}
.d3m-e-cab{flex:none;display:flex;align-items:center;justify-content:space-between;gap:10px;min-height:44px;padding:0 16px;box-sizing:border-box}
.d3m-e-cab > b{min-width:0;font:600 14px/1.25 var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-e-cab > b > span{font-weight:400;color:var(--d3-rotulo)}
.d3m-e-cab-dir{flex:none;display:inline-flex;align-items:center;gap:10px;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);white-space:nowrap;font-variant-numeric:tabular-nums}
.d3m-e-rola{flex:1 1 0;display:flex;flex-direction:column;min-height:0;overflow-y:auto;scrollbar-width:thin;border-top:1px solid var(--d3-divisa)}
.d3m-e-pe{flex:none;display:flex;align-items:center;gap:10px;min-height:52px;padding:0 16px;box-sizing:border-box;border-top:1px solid var(--d3-divisa);font:400 var(--d3-fs-texto)/1.35 var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
.d3m-e-pe > span:first-child{flex:1 1 auto;min-width:0}

/* Alternador dentro da cabeça da folha (26 px, canto 7; a escolhida num véu). */
.d3m-e-seg{display:inline-flex;gap:2px}
.d3m-e-seg > button{appearance:none;display:inline-flex;align-items:center;height:26px;margin:0;padding:0 9px;border:0;border-radius:7px;background:none;color:var(--d3-tinta);font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);white-space:nowrap;cursor:pointer}
.d3m-e-seg > button:hover{background:var(--d3-veu)}
.d3m-e-seg > button[aria-checked="true"],.d3m-e-seg > button[aria-pressed="true"]{background:var(--d3-veu-forte);font-weight:600}
.d3m-e-seg > button:focus-visible{outline:2px solid var(--d3-acao);outline-offset:1px}

/* Faixa de números dentro da folha: número de 28 e o rótulo embaixo, divididos por um fio. */
.d3m-e-nums{flex:none;display:grid;grid-template-columns:repeat(var(--n,4),minmax(0,1fr));border-top:1px solid var(--d3-divisa)}
.d3m-e-nums > span{display:flex;flex-direction:column;gap:4px;min-width:0;padding:16px}
.d3m-e-nums > span + span{border-left:1px solid var(--d3-divisa)}
.d3m-e-nums b{font:600 var(--d3-fs-numero)/1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);color:var(--d3-tinta);font-variant-numeric:tabular-nums}
.d3m-e-nums .r > b{color:var(--d3-perigo)}
.d3m-e-nums .a > b{color:var(--d3-ambar)}
.d3m-e-nums .g > b{color:var(--d3-pronto)}
.d3m-e-nums span > span{font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-e-nums small{font:400 var(--d3-fs-apoio)/1.3 var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}

/* Período no vidro (36 px, canto 10; a escolhida numa pastilha branca). */
.d3m-e-per{flex:none;display:inline-flex;gap:2px;height:36px;padding:3px;box-sizing:border-box;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu)}
.d3m-e-per > button{appearance:none;display:inline-flex;align-items:center;height:30px;margin:0;padding:0 12px;border:0;border-radius:var(--d3-r-botao);background:none;color:var(--d3-fume-texto);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);white-space:nowrap;cursor:pointer}
.d3m-e-per > button:hover{background:var(--d3-fume-veu)}
.d3m-e-per > button:is([aria-pressed="true"],[aria-checked="true"]){background:var(--d3-fume-texto);color:var(--d3-tinta);font-weight:600}
.d3m-e-per > button:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:1px}
/* "Como funciona": o botão de ícone que abre uma nota (a mesma caixa da seta do título, presa à direita). */
.d3m-e-ajuda{align-self:center}
.d3m-e-ajuda > summary.d3m-e-ico{display:grid}
.d3m-e-ajuda > summary.d3m-e-ico > svg{stroke:var(--d3-fume-texto)}
.d3m-e-ajuda-pop{left:auto;right:0;width:300px;gap:6px;padding:12px}
.d3m-e-ajuda-t{font:600 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}
.d3m-e-ajuda-p{margin:0;font:400 var(--d3-fs-apoio)/1.45 var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);white-space:normal}
/* Elo de texto na cabeça ou no pé da folha (tinta, 500) e o botão de fio (contorno) das linhas. */
.d3m-e-elo{appearance:none;flex:none;margin:0;padding:0;border:0;border-radius:4px;background:none;color:var(--d3-tinta);font:500 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);white-space:nowrap;cursor:pointer}
.d3m-e-elo:hover{text-decoration:underline}
.d3m-e-elo:focus-visible{outline:2px solid var(--d3-acao);outline-offset:2px}
.d3v-btn.d3m-e-fio{flex:none;background:none;box-shadow:inset 0 0 0 1px var(--d3-meta);color:var(--d3-tinta);font-weight:500}
.d3v-btn.d3m-e-fio:hover{background:var(--d3-veu)}
.d3v-btn.vidro.d3m-e-fio{box-shadow:inset 0 0 0 1px var(--d3-escuro-apagado);color:var(--d3-fume-texto)}
.d3v-btn.vidro.d3m-e-fio:hover{background:var(--d3-fume-veu)}
/* O selo "só donos" na linha de apoio do título. */
.d3m-e-so-donos{display:inline-flex;align-items:center;gap:4px;color:var(--d3-fume-texto);vertical-align:bottom}
.d3m-e-so-donos > svg{width:12px;height:12px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}

/* Cartões de número (116 de altura): rótulo e selo de 24 em cima; embaixo o número de 28, a nota e, se houver, o anel. */
.d3m-e-kpis{flex:none;display:grid;grid-template-columns:repeat(var(--n,4),minmax(0,1fr));gap:12px}
.d3m-e-kpi{appearance:none;display:flex;flex-direction:column;justify-content:space-between;min-width:0;height:116px;margin:0;padding:14px;box-sizing:border-box;border:0;border-radius:16px;overflow:hidden;background:var(--d3-folha);box-shadow:var(--d3-folha-sombra);color:var(--d3-tinta);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);text-align:left}
button.d3m-e-kpi{cursor:pointer}
button.d3m-e-kpi:hover{box-shadow:var(--d3-folha-sombra),inset 0 0 0 1px var(--d3-meta)}
button.d3m-e-kpi:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}
.d3m-e-kpi-topo{display:flex;align-items:center;justify-content:space-between;gap:8px;font-weight:500}
.d3m-e-kpi-topo > span:first-child{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-e-kpi .d3v-selo[data-k="t"]{background:var(--d3-tinta)}
.d3m-e-kpi .d3v-selo[data-k="a"]{background:var(--d3-ambar)}
.d3m-e-kpi-baixo{display:flex;align-items:flex-end;justify-content:space-between;gap:10px}
.d3m-e-kpi-txt{display:flex;flex-direction:column;gap:4px;min-width:0}
.d3m-e-kpi-v{display:block;font:600 var(--d3-fs-numero)/1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.02em;color:var(--d3-tinta);white-space:nowrap;font-variant-numeric:tabular-nums}
.d3m-e-kpi.r .d3m-e-kpi-v{color:var(--d3-perigo)}
.d3m-e-kpi.a .d3m-e-kpi-v{color:var(--d3-ambar)}
.d3m-e-kpi.g .d3m-e-kpi-v{color:var(--d3-pronto)}
.d3m-e-kpi-v > .d3m-e-kpi-de{font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);letter-spacing:0;color:var(--d3-rotulo)}
.d3m-e-kpi-sub{font:400 var(--d3-fs-apoio)/1.3 var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-e-anel{flex:none;width:40px;height:40px;transform:rotate(-90deg);color:var(--d3-tinta)}
.d3m-e-kpi.r .d3m-e-anel{color:var(--d3-perigo)}
.d3m-e-kpi.a .d3m-e-anel{color:var(--d3-ambar)}
.d3m-e-anel > circle{fill:none;stroke:currentColor;stroke-width:5;stroke-linecap:round}
.d3m-e-anel > circle:first-child{opacity:.16}
.d3m-e-kpi-graf{flex:none;display:block;width:84px;height:36px}
.d3m-e-kpi-graf > svg{display:block;width:100%;height:100%}

/* Telas menores: uma coluna; a consulta desce para depois do trabalho e a janela rola (como no Hoje). */
@media (max-width:900px){
  .d3m-e-tela{height:auto;min-height:100%}
  .d3m-e-topo{flex-wrap:wrap;gap:8px;padding-right:0}
  .d3m-e-sub{white-space:normal}
  .d3m-e-corpo{display:flex;flex-direction:column;flex:none}
  .d3m-e-main{min-height:auto}
  .d3m-e-folha.cresce{flex:none;min-height:200px}
  .d3m-e-rola{flex:none;max-height:60vh}
  .d3m-e-corpo > .d3m-lado{overflow:visible}
  .d3m-e-nums{grid-template-columns:repeat(2,minmax(0,1fr))}
  .d3m-e-nums > span:nth-child(odd){border-left:0}
  .d3m-e-nums > span:nth-child(n+3){border-top:1px solid var(--d3-divisa)}
  .d3m-e-pe{flex-wrap:wrap;padding:10px 16px}
  .d3m-e-acoes{flex:1 1 100%;flex-wrap:wrap;min-width:0}
  .d3m-e-per{max-width:100%;overflow-x:auto;scrollbar-width:none}
  .d3m-e-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}
  .d3m-e-acoes{position:relative}
  .d3m-e-ajuda{position:static}
  .d3m-e-ajuda-pop{left:0;right:0;width:auto}
}

/* ===== padrao-v2/zm-e-diario.css ===== */
/* ===================================================================================================================
   V2 · GRUPO E · DIÁRIO (prancha V2-M-Diario, aprovada pelo Paulo em 16/11/2026). O HTML sai de vybe-relatorios.js
   (diarioPintar): a casca .d3m-e-* (zm-e-casca.css), duas folhas à esquerda ("A foto de agora" e "Registros salvos")
   e, direto no vidro, o cartão laranja do Heitor, "O que mudou", a semana em linha e os atalhos. O cabeçalho antigo do
   index.html (título, alternador com os ids de sempre e o botão do topo) fica guardado: os ids e os handlers continuam.
   =================================================================================================================== */

/* O quadro ocupa a janela inteira, com 16 de respiro, sem a rolagem da página (só a lista de registros rola). No
   computador o quadro prende-se ao body (que no Irecity já é a própria janela, position:fixed) e a tela e a vista das
   peças prendem-se ao quadro: o .container antigo tem padding com !important em três larguras e o cabeçalho antigo
   ocupa 8 px acima, e assim nenhum dos dois entra na conta. Sem rolagem de página, a calha da barra de rolagem sai. */
#painel-diario > .container > .vb-cabecalho{display:none}
body.mundo #painel-diario{background:none}
@media (min-width:901px){
  body.mundo.mundo-modulo[data-quadro="diario"]{scrollbar-gutter:auto}
  body.mundo.mundo-modulo[data-quadro="diario"] #painel-diario{position:absolute;inset:0;max-width:none;height:auto;margin:0}
  body.mundo.mundo-modulo[data-quadro="diario"] :is(#diario-snapshots-list,#diario-detalhe){position:absolute;inset:16px;box-sizing:border-box}
  body.mundo.mundo-modulo[data-quadro="diario"] #diario-detalhe > div:first-child{padding-right:104px}
}
/* O cartão laranja: a frase de apoio é branca (a folha antiga apaga todo small sem classe dentro dos quadros). */
.d3m-laranja .d3m-lar-txt > small.d3m-lar-sub{color:var(--d3-escuro-texto)}

/* O cartão laranja: 200 de altura, como na prancha. */
.d3m-e-diario-lar{flex:none}
.d3m-e-diario-lar.vazio{min-height:200px}
.d3m-e-diario-lar .v2-estado[data-estado="feito"]{gap:6px}

/* Registros: o dia, a linha (hora, quem registrou, as três contagens, o selo do que mudou e a seta) e o que abre no lugar. */
.d3m-e-reg-dia{margin:0;padding:10px 16px 4px;font:400 var(--d3-fs-apoio)/1.3 var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
.d3m-e-reg{border-bottom:1px solid var(--d3-divisa)}
.d3m-e-reg-lin{appearance:none;display:flex;align-items:center;gap:10px;width:100%;min-height:44px;margin:0;padding:0 16px;box-sizing:border-box;border:0;background:none;color:var(--d3-tinta);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);text-align:left;cursor:pointer}
.d3m-e-reg-lin:hover{background:var(--d3-veu)}
.d3m-e-reg-lin:focus-visible{outline:2px solid var(--d3-acao);outline-offset:-2px}
.d3m-e-reg.on > .d3m-e-reg-lin{box-shadow:inset 3px 0 0 var(--d3-tinta)}
.d3m-e-reg-hora{flex:none;min-width:42px;font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);font-variant-numeric:tabular-nums}
.d3m-e-reg-av{flex:none;display:grid;place-items:center;width:24px;height:24px;border-radius:7px;background:var(--d3-veu-forte);color:var(--d3-texto2);font:600 10px var(--vv-texto,Inter,sans-serif)}
.d3m-e-reg-cs{flex:1 1 auto;display:flex;flex-wrap:wrap;gap:2px 14px;min-width:0;color:var(--d3-rotulo)}
.d3m-e-reg-cs > span{white-space:nowrap}
.d3m-e-reg-cs b{font-weight:600;color:var(--d3-tinta);font-variant-numeric:tabular-nums}
.d3m-e-reg-cs > .g > b{color:var(--d3-pronto)}
.d3m-e-reg-cs > .r > b{color:var(--d3-perigo)}
.d3m-e-reg-cs > .a > b{color:var(--d3-ambar)}
.d3m-e-reg-selo{flex:none;display:inline-flex;align-items:center;height:20px;padding:0 8px;border-radius:999px;background:var(--d3-veu);color:var(--d3-tinta);font:500 var(--d3-fs-mini) var(--vv-texto,Inter,sans-serif);white-space:nowrap}
.d3m-e-reg-selo.g{background:var(--d3-pronto-veu);color:var(--d3-pronto)}
.d3m-e-reg-selo.r{background:var(--d3-perigo-veu);color:var(--d3-perigo)}
.d3m-e-reg-seta{flex:none;display:grid;place-items:center;width:16px;height:16px;transition:transform .2s}
.d3m-e-reg-seta > svg{width:14px;height:14px;fill:none;stroke:var(--d3-rotulo);stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.d3m-e-reg[aria-expanded="true"] .d3m-e-reg-seta{transform:rotate(90deg)}
.d3m-e-reg-mais{display:flex;flex-direction:column;gap:6px;padding:0 16px 0 92px;font:400 var(--d3-fs-texto)/1.45 var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
.d3m-e-reg[aria-expanded="true"] .d3m-e-reg-mais{padding-top:2px;padding-bottom:12px}
.d3m-e-reg-grade{display:grid;grid-template-columns:auto minmax(0,1fr);gap:4px 14px}
.d3m-e-reg-grade > b{font-weight:600;color:var(--d3-tinta);white-space:nowrap}
.d3m-e-reg-grade > b.g{color:var(--d3-pronto)}
.d3m-e-reg-grade > b.r{color:var(--d3-perigo)}
.d3m-e-reg-grade > b.a{color:var(--d3-ambar)}
.d3m-e-reg-grade .v2d-cli{font-weight:600;color:var(--d3-tinta)}
.d3m-e-reg-acoes{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-top:4px}
.d3m-e-reg-acoes > span{margin-right:auto;font-size:var(--d3-fs-apoio)}
.d3m-e-reg-pe{margin:0;padding:8px 12px}

/* "O que mudou", no vidro: etapa (ponto na cor do status), barra, quantas e a diferença. */
.d3m-e-ets{display:flex;flex-direction:column;gap:2px;padding:6px 10px;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu)}
.d3m-e-et{display:grid;grid-template-columns:118px minmax(20px,1fr) 30px 34px;align-items:center;gap:8px;min-height:26px;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-texto)}
.d3m-e-et-nome{display:inline-flex;align-items:center;gap:6px;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-e-et-nome > i{flex:none;width:7px;height:7px;border-radius:50%;background:var(--c,var(--d3-fume-apagado))}
.d3m-e-et-nome.g > i{background:var(--d3-pronto-claro)}
.d3m-e-et-nome.a > i{background:var(--d3-ajuste-claro)}
.d3m-e-et-nome.r > i{background:var(--d3-perigo-claro)}
.d3m-e-et > .d3m-vn{min-width:0}
.d3m-e-et-dif{text-align:right;color:var(--d3-fume-apagado);font-variant-numeric:tabular-nums}
.d3m-e-et-dif:is(.g,.a){color:var(--d3-fume-texto);font-weight:600}

/* A semana em linha, no vidro: a linha clara, a meta tracejada e o eixo dos registros. */
.d3m-e-graf{padding:10px;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu)}
.d3m-e-graf .d3-graf polyline{stroke:var(--d3-fume-texto)}
.d3m-e-graf .d3-graf polyline.meta{stroke:var(--d3-fume-apagado)}
.d3m-e-graf .d3-graf circle{fill:var(--d3-fume-texto)}
.d3m-e-eixo{display:flex;justify-content:space-between;gap:4px;margin-top:6px;font:400 var(--d3-fs-mini) var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-apagado)}
.d3m-e-eixo > .ultimo{color:var(--d3-fume-texto);font-weight:600}
.d3m-e-leg{display:inline-flex;align-items:center;gap:5px}
.d3m-e-leg > i{width:10px;height:2px;border-radius:1px;background:var(--d3-fume-texto)}
.d3m-e-leg > i.meta{margin-left:6px;background:none;border-top:2px dashed var(--d3-fume-apagado);height:0}

/* As peças de um registro (a vista que abre com "Ver as peças") numa folha só, que rola por dentro. */
#painel-diario #diario-detalhe .person-chip.active{background:var(--d3-tinta);color:var(--d3-escuro-texto)}
#painel-diario #diario-detalhe{overflow-y:auto;padding:16px;border-radius:16px;background:var(--d3-folha);box-shadow:var(--d3-folha-sombra)}

@media (max-width:900px){
  .d3m-e-reg-lin{flex-wrap:wrap;padding:8px 12px}
  .d3m-e-reg-mais{padding-left:16px}
}

/* ===== padrao-v2/zm-e-estados.css ===== */
/* ===================================================================================================================
   V2 · GRUPO E · ESTADOS (prancha V2-M-Estados, aprovada pelo Paulo em 16/11/2026): vazio, carregando e erro, para
   lista, quadro, grade e ficha. A mesma família de peças em qualquer tela; o HTML sai de d3mEEstado (vybe-core.js).
   Vazio diz o que vai aparecer e dá o primeiro passo. Carregando é o esqueleto da própria tela, parado, com um pulso
   leve de opacidade (de .6 a 1, nunca de zero). Erro diz o que não veio e deixa tentar de novo.
   PEÇA PARA PROMOVER: .d3m-e-estado-* vira .d3m-estado-* em z-direcao.css (hoje há .d3v-estado e .d3v-esq, mais simples).
   =================================================================================================================== */

/* Vazio e erro: selo de 36 com o ícone, o título de 13, uma frase de 12 e, se houver, um botão de 28. */
.d3m-e-estado{flex:1 1 auto;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;min-width:0;min-height:120px;margin:0;padding:10px 16px;box-sizing:border-box;text-align:center;font:400 var(--d3-fs-apoio)/1.45 var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
.d3m-e-estado-ic{flex:none;display:grid;place-items:center;width:36px;height:36px;border-radius:var(--d3-r-caixa);background:var(--d3-veu);color:var(--d3-rotulo)}
.d3m-e-estado-ic > svg{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.d3m-e-estado > b{font:600 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}
.d3m-e-estado > span:not(.d3m-e-estado-ic){max-width:400px}
.d3m-e-estado-erro > .d3m-e-estado-ic{background:var(--d3-perigo-veu);color:var(--d3-perigo)}
/* Na área grande da tela (a lista principal): selo de 44, título de 14 e frase de 13. */
.d3m-e-estado.grande{gap:8px;padding:24px}
.d3m-e-estado.grande > .d3m-e-estado-ic{width:44px;height:44px;border-radius:12px}
.d3m-e-estado.grande > .d3m-e-estado-ic > svg{width:20px;height:20px}
.d3m-e-estado.grande > b{font-size:14px}
.d3m-e-estado.grande > span:not(.d3m-e-estado-ic){font-size:var(--d3-fs-texto);line-height:1.5}
/* Direto no vidro fumê (coluna de consulta): letra clara. */
.d3m-e-estado.vidro{min-height:96px;border-radius:var(--d3-r-caixa);background:var(--d3-fume-veu);color:var(--d3-fume-apagado)}
.d3m-e-estado.vidro > b{color:var(--d3-fume-texto)}
.d3m-e-estado.vidro > .d3m-e-estado-ic{background:var(--d3-fume-veu-forte);color:var(--d3-fume-texto)}
.d3m-e-estado.vidro.d3m-e-estado-erro > .d3m-e-estado-ic{color:var(--d3-perigo-vidro)}
/* O botão do estado: 28 px, canto 8. Cheio no vazio (o primeiro passo); de contorno no erro ("Tentar de novo"). */
.d3m-e-estado-btn{appearance:none;display:inline-flex;align-items:center;justify-content:center;gap:6px;height:28px;margin:4px 0 0;padding:0 10px;box-sizing:border-box;border:0;border-radius:var(--d3-r-botao);background:var(--d3-tinta);color:var(--d3-escuro-texto);font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);text-decoration:none;white-space:nowrap;cursor:pointer}
.d3m-e-estado-btn:hover{background:var(--d3-texto2)}
.d3m-e-estado-btn.sec{background:none;box-shadow:inset 0 0 0 1px var(--d3-meta);color:var(--d3-tinta);font-weight:500}
.d3m-e-estado-btn.sec:hover{background:var(--d3-veu)}
.d3m-e-estado-btn:focus-visible{outline:2px solid var(--d3-acao);outline-offset:2px}
.d3m-e-estado.vidro > .d3m-e-estado-btn{background:var(--d3-fume-texto);color:var(--d3-tinta)}
.d3m-e-estado.vidro > .d3m-e-estado-btn.sec{background:none;box-shadow:inset 0 0 0 1px var(--d3-fume-borda);color:var(--d3-fume-texto)}

/* Carregando: os ossos da tela. O pulso é do bloco inteiro e só de opacidade. */
@keyframes d3mERespira{0%,100%{opacity:.6}50%{opacity:1}}
.d3m-e-estado-carregando{flex:1 1 auto;display:flex;flex-direction:column;min-width:0;box-sizing:border-box;animation:d3mERespira 1.8s ease-in-out infinite}
.d3m-e-osso{flex:none;display:block;height:10px;border-radius:5px;background:var(--d3-veu-forte)}
.d3m-e-estado-carregando[data-forma="lista"] > span{display:flex;align-items:center;gap:10px;height:34px;padding:0 14px;border-bottom:1px solid var(--d3-divisa)}
.d3m-e-estado-carregando[data-forma="lista"] .d3m-e-osso.selo{width:24px;height:24px;border-radius:7px}
.d3m-e-estado-carregando[data-forma="lista"] .d3m-e-osso.nome{width:46%}
.d3m-e-estado-carregando[data-forma="lista"] .d3m-e-osso.fim{width:16%;margin-left:auto}
.d3m-e-estado-carregando[data-forma="quadro"]{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));align-items:stretch;gap:8px;padding:10px}
.d3m-e-estado-carregando[data-forma="quadro"] > span{display:flex;flex-direction:column;gap:6px;padding:6px;border-radius:var(--d3-r-botao);background:var(--d3-veu)}
.d3m-e-estado-carregando[data-forma="quadro"] .d3m-e-osso.rot{width:60%;height:8px}
.d3m-e-estado-carregando[data-forma="quadro"] .d3m-e-osso.cartao{height:34px;border-radius:var(--d3-r-botao)}
.d3m-e-estado-carregando[data-forma="grade"]{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));align-content:start;gap:8px;padding:10px}
.d3m-e-estado-carregando[data-forma="grade"] > .d3m-e-osso{height:56px;border-radius:var(--d3-r-botao)}
.d3m-e-estado-carregando[data-forma="ficha"]{flex-direction:row;gap:12px;padding:12px}
.d3m-e-estado-carregando[data-forma="ficha"] > .d3m-e-osso.foto{width:56px;height:56px;border-radius:14px}
.d3m-e-estado-carregando[data-forma="ficha"] > span{flex:1 1 auto;display:flex;flex-direction:column;gap:8px;min-width:0}
.d3m-e-estado-carregando[data-forma="ficha"] .d3m-e-osso.t{width:60%;height:14px}
.d3m-e-estado-carregando[data-forma="ficha"] .d3m-e-osso.s{width:40%}
.d3m-e-estado-carregando[data-forma="ficha"] .d3m-e-osso.b1{height:46px;border-radius:var(--d3-r-botao)}
.d3m-e-estado-carregando[data-forma="ficha"] .d3m-e-osso.b2{height:26px;border-radius:var(--d3-r-botao)}
/* No vidro, os ossos são claros. */
.d3m-e-estado-carregando.vidro .d3m-e-osso{background:var(--d3-fume-veu-forte)}
.d3m-e-estado-carregando.vidro[data-forma="lista"] > span{border-bottom-color:var(--d3-fume-veu)}
.d3m-e-estado-carregando.vidro[data-forma="quadro"] > span{background:var(--d3-fume-veu)}
@media (prefers-reduced-motion:reduce){.d3m-e-estado-carregando{animation:none}}
@media (max-width:900px){.d3m-e-estado-carregando[data-forma="grade"]{grid-template-columns:repeat(2,minmax(0,1fr))}}

/* ===== padrao-v2/zm-e-ia.css ===== */
/* ===================================================================================================================
   V2 · GRUPO E · IA E CUSTOS (prancha V2-M-IA-Custos, aprovada pelo Paulo em 16/11/2026). O HTML sai de vybe-demandas.js
   (pv2iRender): a casca .d3m-e-* (zm-e-casca.css), três cartões de número, a folha "Teto do mês" (o teto, 80% e 100%),
   a folha "Com quem e em quê" (por dia, com quem e em quê; sem uso, o estado vazio; com "Parâmetros", o formulário) e,
   direto no vidro, o cartão laranja do Alex, o que entra na conta, "De olho" e os atalhos.
   =================================================================================================================== */

/* O quadro ocupa a janela inteira, com 16 de respiro, sem a rolagem da página (a mesma receita do Diário). */
body.mundo #painel-ai-usage{background:none}
@media (min-width:901px){
  body.mundo.mundo-modulo[data-quadro="ai-usage"]{scrollbar-gutter:auto}
  body.mundo.mundo-modulo[data-quadro="ai-usage"] #painel-ai-usage{position:absolute;inset:0;max-width:none;height:auto;margin:0}
  body.mundo.mundo-modulo[data-quadro="ai-usage"] #ai-usage-root > .d3m-e-ia{position:absolute;inset:16px;height:auto;box-sizing:border-box}
}

/* "Teto do mês": a linha do teto (52) e as duas linhas automáticas (44). A primeira coluna tem 100 de largura. */
.d3m-e-ia-lin{flex:none;display:flex;align-items:center;gap:10px;min-height:44px;padding:0 16px;box-sizing:border-box;border-top:1px solid var(--d3-divisa);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}
.d3m-e-ia-lin.principal{min-height:52px}
.d3m-e-ia-c1{flex:none;display:flex;align-items:center;width:90px;min-width:0}
.d3m-e-ia-pct{font-weight:600;font-variant-numeric:tabular-nums}
.d3m-e-ia-pct.r{color:var(--d3-perigo)}
.d3m-e-ia-pct.a{color:var(--d3-ambar)}
.d3m-e-ia-st.a{--st:var(--d3-ambar)}
.d3m-e-ia-st.r{--st:var(--d3-perigo)}
.d3m-e-ia-st.g{--st:var(--d3-pronto)}
.d3m-e-ia-txt{flex:1 1 auto;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-e-ia-txt > b{font-weight:600}
.d3m-e-ia-txt > span{color:var(--d3-rotulo)}
.d3m-e-ia-auto{flex:none;font-size:var(--d3-fs-apoio);color:var(--d3-rotulo)}
.d3m-e-ia-barra{flex:1 1 0;min-width:20px;height:4px;border-radius:2px;background:var(--d3-veu-forte);overflow:hidden}
.d3m-e-ia-lin > .d3m-e-ia-barra{flex:0 0 120px}
.d3m-e-ia-barra > i{display:block;width:var(--v,0%);height:100%;border-radius:2px;background:var(--d3-texto2)}
.d3m-e-ia-barra.r > i{background:var(--d3-perigo)}
.d3m-e-ia-barra.a > i{background:var(--d3-ambar)}
.d3m-e-ia-barra.g > i{background:var(--d3-pronto)}

/* "Com quem e em quê": três colunas dentro da folha (por dia, com quem, em quê). */
.d3m-e-ia-cols{flex:1 0 auto;display:grid;grid-template-columns:repeat(3,minmax(0,1fr))}
.d3m-e-ia-col{display:flex;flex-direction:column;gap:6px;min-width:0;padding:12px 16px}
.d3m-e-ia-col + .d3m-e-ia-col{border-left:1px solid var(--d3-divisa)}
.d3m-e-ia-col-cab{flex:none;display:flex;align-items:center;justify-content:space-between;gap:8px;min-height:26px}
.d3m-e-ia-col-cab > b{font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}
.d3m-e-ia-col-cab > span:not(.d3m-e-seg){font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);white-space:nowrap}
.d3m-e-ia-gx{flex:none;display:flex;align-items:center;gap:8px;min-height:30px;font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}
.d3m-e-ia-gx > .d3v-foto{width:24px;height:24px;border-radius:7px;font-size:10px}
.d3m-e-ia-nome{flex:0 0 84px;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-e-ia-gx > b{flex:none;font-weight:600;font-variant-numeric:tabular-nums;white-space:nowrap}
.d3m-e-ia-graf > svg{display:block;width:100%;height:96px}
.d3m-e-ia-eixo{display:flex;justify-content:space-between;gap:4px;font:400 var(--d3-fs-mini) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
.d3m-e-ia-eixo > b{font-weight:600;color:var(--d3-tinta)}
.d3m-e-ia-nada{margin:0;font:400 var(--d3-fs-apoio)/1.45 var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
.d3m-e-ia-pe > span:first-child{display:flex;align-items:center;gap:6px}
.d3m-e-ia-vazio-bts{display:flex;flex-wrap:wrap;justify-content:center;gap:8px;margin-top:6px}

/* Os parâmetros (teto, dólar e Gemini) no lugar da folha de baixo: três campos lado a lado, Salvar e Voltar. */
.d3m-e-ia-form{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));align-content:start;gap:12px 16px;padding:16px}
.d3m-e-ia-form-p{grid-column:1 / -1;margin:0;font:400 var(--d3-fs-texto)/1.5 var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
.d3m-e-ia-form > .d3m-e-campo{display:flex;flex-direction:column;gap:4px;min-width:0;margin:0}
.d3m-e-ia-form > .d3m-e-campo > label{font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
.d3m-e-ia-form > .d3m-e-campo > :is(input,select){width:100%;height:34px;margin:0;padding:0 10px;box-sizing:border-box;border:0;border-radius:var(--d3-r-botao);background:var(--d3-cartao);box-shadow:inset 0 0 0 1px var(--d3-meta);color:var(--d3-tinta);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif)}
.d3m-e-ia-form > .d3m-e-campo > :is(input,select):focus-visible{outline:2px solid var(--d3-acao);outline-offset:1px}
.d3m-e-ia-form-bts{grid-column:1 / -1;display:flex;gap:8px}
/* A folha antiga pinta .ai-setting-save de laranja e arredonda os campos com !important, pelas variáveis dela: aqui as
   variáveis apontam para os tokens (o botão escuro e o canto 8), sem forçar regra. O botão guarda a classe porque
   saveAiUsageSettings procura por ela. */
.d3m-e-ia-form .ai-setting-save{--vv-acao:var(--d3-tinta);--vv-laranja:var(--d3-tinta)}
.d3m-e-ia-form > .d3m-e-campo > :is(input,select){--ds-r-botao:var(--d3-r-botao);--ds-linha:var(--d3-meta)}

/* O cartão laranja (216 de altura) e o "De olho" no vidro. */
.d3m-e-ia-lar{flex:none;min-height:216px}
.d3m-e-ia-lar::after{content:"";position:absolute;z-index:0;right:18px;top:58px;width:56px;height:56px;border-radius:50%;background:var(--d3-escuro-texto);opacity:.06;pointer-events:none}
.d3m-e-ia-olho{color:var(--d3-fume-apagado);font-size:var(--d3-fs-texto)}
.d3m-e-ia-olho > b{font-weight:600;color:var(--d3-fume-texto)}

/* Janela baixa (notebook de 768): as linhas encolhem para as três faixas caberem. */
@media (min-width:901px) and (max-height:820px){
  .d3m-e-ia .d3m-e-kpi{height:96px;padding:10px 14px}
  .d3m-e-ia .d3m-e-cab{min-height:38px}
  .d3m-e-ia .d3m-e-ia-lin{min-height:36px}
  .d3m-e-ia .d3m-e-ia-lin.principal{min-height:44px}
  .d3m-e-ia-lar{min-height:190px}
}
/* Telas menores: uma coluna, a janela rola. */
@media (max-width:900px){
  .d3m-e-ia .d3m-e-kpis{grid-template-columns:minmax(0,1fr)}
  .d3m-e-ia-lin{flex-wrap:wrap;padding:8px 16px}
  .d3m-e-ia-txt{flex-basis:calc(100% - 110px);white-space:normal}
  .d3m-e-ia-cols,.d3m-e-ia-form{grid-template-columns:minmax(0,1fr)}
  .d3m-e-ia-col + .d3m-e-ia-col{border-left:0;border-top:1px solid var(--d3-divisa)}
  .d3m-e-ia-lar{min-height:0}
  .d3m-e-ia .d3m-e-ia-uso > .d3m-e-rola{max-height:none}
}

/* ===== padrao-v2/zm-e-performance.css ===== */
/* ===================================================================================================================
   V2 · GRUPO E · PERFORMANCE (prancha V2-M-Performance, aprovada pelo Paulo em 16/11/2026). O HTML sai de
   vybe-mundo-performance.js (VybePerformance.html): a casca .d3m-e-* (zm-e-casca.css), quatro cartões de número, a
   folha "Onde a fila está", "Pede ação" e "Entregas por semana" lado a lado e, direto no vidro, o cartão laranja do
   Heitor, as outras leituras da Gestão e as pessoas. A tela abre na camada da Gestão (.vv-gestao), não num quadro.
   =================================================================================================================== */

/* A camada da Gestão com a Performance aberta vira a janela de vidro fumê. A regra antiga do material das janelas
   (vybe-mundo.css) tem o peso de um id por causa do :is(#…): o :is(.vv-gestao,#vv-gestao) daqui só empata esse peso. */
body.mundo :is(.vv-gestao,#vv-gestao):has(> .vv-perf){padding:16px;border:0;border-radius:20px;background:var(--d3-fume);box-shadow:inset 0 0 0 1px var(--d3-fume-borda),0 30px 60px -40px rgba(0,0,0,.6);color:var(--d3-fume-texto)}
body.mundo :is(.vv-gestao,#vv-gestao) > .vv-perf{max-width:none;margin:0;padding:0}
@media (min-width:901px){
  body.mundo :is(.vv-gestao,#vv-gestao):has(> .vv-perf){overflow:hidden}
  body.mundo :is(.vv-gestao,#vv-gestao) > .vv-perf{height:100%}
}
/* Esta janela não tem os botões de tela cheia e fechar: o topo usa a largura toda. */
.d3m-e-perf > .d3m-e-topo{padding-right:0}

/* "Onde a fila está": cabeçalho de colunas (24), uma linha de 44 por etapa e o pé com as atrasadas por cliente. */
.d3m-e-fx-cab,.d3m-e-fx-lin{display:flex;align-items:center;gap:10px;padding:0 16px;box-sizing:border-box}
.d3m-e-fx-cab{flex:none;height:24px;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo);white-space:nowrap}
.d3m-e-fx-lista{flex:none;display:flex;flex-direction:column;min-height:0}
.d3m-e-perf-fila.todas > .d3m-e-fx-lista{max-height:220px;overflow-y:auto;scrollbar-width:thin}
.d3m-e-fx-lin{flex:none;height:44px;border-top:1px solid var(--d3-divisa)}
.d3m-e-fx-st{flex:none;display:flex;align-items:center;width:150px;min-width:0}
.d3m-e-fx-barra,.d3m-e-fx-barra-rot{flex:1 1 0;min-width:0}
.d3m-e-fx-barra{height:4px;border-radius:2px;background:var(--d3-veu-forte);overflow:hidden}
.d3m-e-fx-barra > i{display:block;width:var(--v,0%);height:100%;border-radius:2px;background:var(--d3-texto2)}
.d3m-e-fx-n,.d3m-e-fx-at{appearance:none;flex:none;margin:0;padding:0;border:0;border-radius:4px;background:none;text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}
.d3m-e-fx-n{width:40px;font:600 var(--d3-fs-destaque) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta)}
.d3m-e-fx-at{width:110px;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-perigo)}
.d3m-e-fx-cab > .d3m-e-fx-at,.d3m-e-fx-at.calmo{color:var(--d3-rotulo)}
button:is(.d3m-e-fx-n,.d3m-e-fx-at){cursor:pointer}
button:is(.d3m-e-fx-n,.d3m-e-fx-at):hover{text-decoration:underline}
button:is(.d3m-e-fx-n,.d3m-e-fx-at):focus-visible{outline:2px solid var(--d3-acao);outline-offset:2px}
button.d3m-e-fx-at[aria-pressed="true"]{font-weight:600}
.d3m-e-fx-pe{flex:none;display:flex;align-items:center;gap:16px;height:44px;padding:0 16px;box-sizing:border-box;border-top:1px solid var(--d3-divisa);overflow:hidden;font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);white-space:nowrap}
.d3m-e-fx-pe-rot{flex:none;color:var(--d3-rotulo)}
.d3m-e-fx-cli{flex:0 1 auto;display:inline-flex;align-items:center;gap:6px;min-width:0}
.d3m-e-fx-cli > .d3v-foto{width:20px;height:20px;border-radius:6px;font-size:10px}
.d3m-e-fx-cli > b{flex:0 1 auto;display:block;min-width:56px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-e-perf .d3m-e-fx-pe .d3m-e-fx-cli .cliente-carteira{--carteira-texto:var(--d3-tinta);display:inline;padding:0;border-radius:0;background:none;font:inherit}
.d3m-e-perf .d3m-e-fx-cli .cliente-carteira::before{content:none}
.d3m-e-fx-cli > span{flex:none;color:var(--d3-rotulo)}
.d3m-e-fx-pe > .d3m-e-elo{margin-left:auto}

/* "Pede ação" e "Entregas por semana", lado a lado, ocupando o que sobra; só a lista de dentro rola. */
.d3m-e-par{flex:1 1 0;min-height:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
.d3m-e-par > .d3m-e-folha{min-height:0}
.d3m-e-pd-lin{flex:none;display:flex;align-items:center;gap:10px;min-height:44px;padding:0 16px;box-sizing:border-box;border-bottom:1px solid var(--d3-divisa)}
.d3m-e-pd-lin:last-child{border-bottom:0}
.d3m-e-pd-n{flex:none;width:44px;font:600 var(--d3-fs-destaque) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);white-space:nowrap;font-variant-numeric:tabular-nums}
.d3m-e-pd-n.r{color:var(--d3-perigo)}
.d3m-e-pd-n.a{color:var(--d3-ambar)}
.d3m-e-pd-txt{flex:1 1 auto;min-width:0;font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-e-pd-txt > b{font-weight:600}
.d3m-e-pd-txt > span{color:var(--d3-rotulo)}
.d3m-e-pd-zer{flex:none;display:flex;align-items:center;height:44px;padding:0 16px;box-sizing:border-box;border-top:1px solid var(--d3-divisa);overflow:hidden;white-space:nowrap}
.d3m-e-pd-zer-rot{flex:none;margin-right:14px;font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
.d3m-e-pd-z{flex:none;display:flex;align-items:baseline;gap:5px;padding:0 12px;border-left:1px solid var(--d3-veu-forte)}
.d3m-e-pd-z:first-child,.d3m-e-pd-zer-rot + .d3m-e-pd-z{padding-left:0;border-left:0}
.d3m-e-pd-z > b{font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);font-variant-numeric:tabular-nums}
.d3m-e-pd-z-rot{font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
.d3m-e-pd-z.mais{color:var(--d3-rotulo);font:400 var(--d3-fs-apoio) var(--vv-texto,Inter,sans-serif)}
.d3m-e-pd-z.mais.curta{display:none}

/* Entregas: o gráfico em linha ocupa o que sobra e os três números ficam no pé (a mesma faixa dos zerados). */
.d3m-e-perf .d3m-e-ent-graf{flex:1 1 0;display:flex;flex-direction:column;min-height:0;padding:10px 16px 6px}
.d3m-e-perf .d3m-e-ent-graf > .d3-graf{flex:1 1 0;display:block;width:100%;height:auto;min-height:0;margin:0}
.d3m-e-perf .d3m-e-ent-graf > .d3g-eixo{flex:none;display:flex;justify-content:space-between;gap:4px;margin:4px 0 0;font:400 var(--d3-fs-mini) var(--vv-texto,Inter,sans-serif);color:var(--d3-rotulo)}
.d3m-e-perf .d3m-e-ent-graf > .d3g-eixo > .on{color:var(--d3-tinta);font-weight:600}
.d3m-e-perf-ent > .d3m-e-rola{overflow:hidden}
.d3m-e-mini-v{appearance:none;margin:0;padding:0;border:0;border-radius:4px;background:none;font:600 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);color:var(--d3-tinta);font-variant-numeric:tabular-nums;cursor:pointer}
.d3m-e-mini-v:hover{text-decoration:underline}
.d3m-e-mini-v:focus-visible{outline:2px solid var(--d3-acao);outline-offset:2px}

/* O cartão laranja: 252 de altura, com o segundo círculo de luz da prancha. */
.d3m-e-perf-lar{flex:none;min-height:252px}
.d3m-e-perf-lar::after{content:"";position:absolute;z-index:0;right:18px;top:58px;width:56px;height:56px;border-radius:50%;background:var(--d3-escuro-texto);opacity:.06;pointer-events:none}

/* As tabelas (departamento, formato, pessoa e cliente) numa folha só, que rola por dentro. */
.d3m-e-perf-tabelas .d3v-btn > svg{width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.d3m-e-perf-tabs{display:flex;flex-direction:column;gap:14px;padding:16px;color:var(--d3-tinta)}
.d3m-e-perf .d3m-e-perf-tabs small{color:var(--d3-rotulo)}

/* Janela baixa (notebook de 768): as linhas encolhem para as três faixas caberem sem rolar a tela. */
@media (min-width:901px) and (max-height:820px){
  .d3m-e-perf .d3m-e-kpi{height:96px;padding:10px 14px}
  .d3m-e-perf .d3m-e-cab{min-height:38px}
  .d3m-e-perf .d3m-e-fx-cab{height:20px}
  .d3m-e-perf .d3m-e-fx-lin{height:34px}
  .d3m-e-perf .d3m-e-fx-pe,.d3m-e-perf .d3m-e-pd-zer{height:36px}
  .d3m-e-perf .d3m-e-pd-lin{min-height:40px}
  .d3m-e-perf-lar{min-height:200px}
  .d3m-e-perf .d3m-e-perf-lar .d3m-lar-num{font-size:44px}
  .d3m-e-perf .d3m-lado{gap:10px}
  .d3m-e-perf .d3m-lado .d3m-vlin{height:30px}
}
/* Até 1400 de largura o pé da fila mostra dois clientes (o terceiro fica no "abrir as N") e o dos zerados, dois (o "+N" conta o terceiro). */
@media (min-width:901px) and (max-width:1400px){
  .d3m-e-fx-pe > .d3m-e-fx-cli:nth-of-type(n+4),.d3m-e-pd-zer > .d3m-e-pd-z.terceiro,.d3m-e-pd-z.mais.larga{display:none}
  .d3m-e-pd-z.mais.curta{display:flex}
}
/* Telas menores: uma coluna, a janela rola. */
@media (max-width:900px){
  body.mundo :is(.vv-gestao,#vv-gestao):has(> .vv-perf){padding:12px;border-radius:0 0 16px 16px}
  .d3m-e-par{display:flex;flex-direction:column;flex:none}
  .d3m-e-par > .d3m-e-folha .d3m-e-rola{max-height:none}
  .d3m-e-fx-st{width:112px}
  .d3m-e-fx-at{width:84px}
  .d3m-e-fx-pe,.d3m-e-pd-zer{flex-wrap:wrap;height:auto;gap:6px 12px;padding:10px 16px;white-space:normal}
  .d3m-e-pd-lin{flex-wrap:wrap;padding:8px 16px}
  .d3m-e-pd-txt{flex-basis:calc(100% - 60px);white-space:normal}
  .d3m-e-pd-lin > .d3v-btn{margin-left:54px}
  .d3m-e-perf-lar{min-height:0}
  .d3m-e-perf .d3m-e-ent-graf{flex:none;height:150px;box-sizing:border-box}
  .d3m-e-fx-barra-rot{overflow:hidden;text-overflow:ellipsis}
}

/* ===== padrao-v2/zm-f-casca.css ===== */
/* ===================================================================================================================
   V2 · GRUPO F · O MUNDO VYBE (pranchas V2-M-Centro, Predio, Minha-Sala, Jogos, Loja, Ranking e Conquistas, aprovadas
   pelo Paulo em 16/11/2026). As peças comuns das telas do mundo, por cima da casca do grupo E (.d3m-e-*) e das peças
   dos módulos (.d3m-*): as tiras de número no vidro, o cartão da cena 3D com o que vai por cima dela e as linhas da
   coluna de consulta. A cena (canvas, voxel, jogos) não é tocada: só o que fica por cima ou ao lado.
   Peças locais (.d3m-f-*): quando outra área precisar, sobem para z-direcao.css com o nome .d3m-*.
   =================================================================================================================== */

/* Tiras de número direto no vidro (72 de altura, canto 12): o rótulo em cima; embaixo o número de 18 e o apoio.
   A primeira (.on) é clara: o número que mais importa na tela. */
.d3m-f-tiras{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;min-width:0}
.d3m-f-tira{appearance:none;display:flex;flex-direction:column;justify-content:space-between;min-width:0;height:72px;margin:0;padding:10px 12px;box-sizing:border-box;border:0;border-radius:12px;background:var(--d3-fume-veu);color:var(--d3-fume-texto);font:400 var(--d3-fs-texto)/1.3 var(--vv-texto,Inter,sans-serif);text-align:left}
button.d3m-f-tira{cursor:pointer}
button.d3m-f-tira:hover{background:var(--d3-fume-veu-forte)}
button.d3m-f-tira:disabled{cursor:default}
button.d3m-f-tira:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}
.d3m-f-tira-r{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d3m-f-tira-v{display:flex;align-items:baseline;gap:6px;min-width:0;white-space:nowrap}
.d3m-f-tira-v > b{flex:none;font:600 var(--d3-fs-titulo)/1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);font-variant-numeric:tabular-nums}
.d3m-f-tira-v > span{min-width:0;font-size:var(--d3-fs-apoio);color:var(--d3-fume-apagado);overflow:hidden;text-overflow:ellipsis}
.d3m-f-tira.on,button.d3m-f-tira.on:hover{background:var(--d3-folha);color:var(--d3-tinta)}
.d3m-f-tira.on > .d3m-f-tira-r{font-weight:600}
.d3m-f-tira.on .d3m-f-tira-v > span{color:var(--d3-rotulo-fixo)}
button.d3m-f-tira[aria-pressed="true"]{box-shadow:inset 0 0 0 2px var(--d3-acao)}

/* O cartão da cena: canto 16 e sombra de folha. Vazio por dentro: a cena 3D aparece no retângulo dele. */
.d3m-f-cena{position:relative;min-width:0;min-height:0;box-sizing:border-box;border-radius:16px;box-shadow:var(--d3-folha-sombra)}
/* O que vai por cima da cena: pastilhas escuras de 30 (canto 8) e o botão claro de 34. */
.d3m-f-chips{position:absolute;z-index:1;left:12px;top:12px;right:12px;display:flex;flex-wrap:wrap;gap:6px;pointer-events:none}
.d3m-f-chip{appearance:none;display:inline-flex;align-items:center;gap:6px;height:30px;margin:0;padding:0 12px;box-sizing:border-box;border:0;border-radius:var(--d3-r-botao);background:var(--d3-fume-forte);color:var(--d3-fume-texto);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);white-space:nowrap;pointer-events:auto}
button.d3m-f-chip{cursor:pointer}
button.d3m-f-chip:hover{background:var(--d3-fume-painel)}
button.d3m-f-chip:is([aria-pressed="true"],[aria-checked="true"]){background:var(--d3-fume-texto);color:var(--d3-tinta);font-weight:600}
button.d3m-f-chip:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}
.d3m-f-chip > i{flex:none;width:7px;height:7px;border-radius:50%;background:var(--d3-fume-apagado)}
.d3m-f-chip > i.r{background:var(--d3-perigo-claro)}
.d3m-f-chip > i.a{background:var(--d3-ajuste-claro)}
.d3m-f-chip > i.g{background:var(--d3-pronto-claro)}
.d3m-f-chip > b{font-weight:600}
.d3v-btn.d3m-f-claro{background:var(--d3-fume-texto);color:var(--d3-tinta);box-shadow:0 8px 18px -12px rgba(0,0,0,.7)}
.d3v-btn.d3m-f-claro:hover{background:var(--d3-folha)}
.d3v-btn.d3m-f-claro:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}

/* Coluna de consulta: o cartão laranja de 236, o apoio apagado das linhas e a palavra da ação à direita. */
.d3m-laranja.d3m-f-lar{flex:none;height:236px}
.d3m-laranja.d3m-f-lar::after{content:"";position:absolute;right:18px;top:58px;width:56px;height:56px;border-radius:50%;background:rgba(255,255,255,.06);pointer-events:none}
.d3m-f-lar .d3m-lar-num{white-space:nowrap}
.d3m-f-ap{font-weight:400;color:var(--d3-fume-apagado)}
.d3m-f-vai{flex:none;font-weight:500}
.d3m-vlin.d3m-f-dentro,.d3m-vlin.d3m-f-pes{cursor:default}
.d3m-vlin.d3m-f-dentro:hover,.d3m-vlin.d3m-f-pes:hover{background:var(--d3-fume-veu)}
.d3m-f-lado{min-height:0}
.d3m-f-lado > .d3m-cons{flex:none}
/* Uma lista que cresce na coluna e rola por dentro (lojas por atraso, ranking, vitrine). */
.d3m-f-lado > .d3m-cons.d3m-f-cresce{flex:1 1 0;min-height:0}
.d3m-f-lista{flex:1 1 0;display:flex;flex-direction:column;gap:6px;min-height:0;overflow-y:auto;scrollbar-width:thin;scrollbar-color:var(--d3-fume-borda) transparent}
.d3m-f-lista > .d3m-vlin{flex:none}

/* O menu que abre de um botão de ícone do topo (busca, mais): preso à direita. */
.d3m-e-troca.d3m-f-menu{align-self:center}
.d3m-e-troca.d3m-f-menu > summary.d3m-e-ico{display:grid}
.d3m-e-troca.d3m-f-menu > summary.d3m-e-ico > svg{stroke:var(--d3-fume-texto)}
.d3m-e-troca.d3m-f-menu > .d3m-e-pop{left:auto;right:0}
.d3m-e-pop > button:disabled{color:var(--d3-rotulo);cursor:default}
.d3m-e-pop > button:disabled:hover{background:none}
.d3m-f-campo{appearance:none;width:240px;height:34px;margin:0;padding:0 10px;box-sizing:border-box;border:0;border-radius:var(--d3-r-botao);background:var(--d3-veu);color:var(--d3-tinta);font:400 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif)}
.d3m-f-campo::placeholder{color:var(--d3-rotulo)}
.d3m-f-campo:focus-visible{outline:2px solid var(--d3-acao);outline-offset:1px}

/* Telas baixas (1366 × 768): o cartão laranja e as linhas um degrau menores, para a coluna caber sem rolar. */
@media (min-width:901px) and (max-height:820px){
  .d3m-laranja.d3m-f-lar{height:200px;padding:14px}
  .d3m-f-lar .d3m-lar-num{font-size:44px}
  .d3m-laranja.d3m-f-lar .d3m-lar-txt > .d3-acao-frase{font-size:16px}
  .d3m-f-lar .d3m-lar-bts{margin-top:6px}
  .d3m-f-lado .d3m-vlin{height:34px}
}
@media (max-width:900px){
  .d3m-f-tiras{grid-template-columns:repeat(2,minmax(0,1fr))}
  .d3m-laranja.d3m-f-lar{height:auto;min-height:200px}
  .d3m-f-campo{width:min(240px,70vw)}
}

/* ===== padrao-v2/zm-f-centro.css ===== */
/* ===================================================================================================================
   V2 · GRUPO F · CENTRO (prancha V2-M-Centro, aprovada pelo Paulo em 16/11/2026). A janela de vidro fumê da Vybelândia:
   o título no vidro com Centro/Prédio, a busca de cliente e o "Mais"; as quatro tiras; o cartão com o mapa 3D (o motor
   desenha no retângulo dele) e a coluna de consulta com o cartão laranja, quem está online e as salas. Os oito cartões
   de módulo saíram: já estão no menu. O HTML sai de pintarCentroD3 (vybe-mundo.js).
   SOBRE A CASCA DO GRUPO E (sem editar zm-e-casca.css): o topo não reserva os 104 px dos botões da janela (aqui não há)
   e a tela não tem altura de 100% (ela é presa pelos quatro lados no HUD).
   =================================================================================================================== */

/* A janela fica atrás do canvas (que mora em #mundo, por baixo do HUD): assim o vidro não escurece a cena. */
body.mundo.mundo-centro.d3c-painel #mundo::before{content:"";position:absolute;left:var(--vv-livre-esq,96px);top:var(--vv-m,14px);right:var(--vv-m,14px);bottom:calc(var(--vv-dock-alto,74px) + 12px);border-radius:20px;background:var(--d3-fume);box-shadow:inset 0 0 0 1px var(--d3-fume-borda),0 30px 60px -40px rgba(0,0,0,.6);pointer-events:none}
/* O fundo do cartão da cena, também atrás do canvas (de dia a cena é transparente): um rebaixo escuro no vidro. */
body.mundo.mundo-centro.d3c-painel #mundo::after{content:"";position:absolute;z-index:-1;left:var(--d3c-mx,0px);top:var(--d3c-my,0px);width:var(--d3c-mw,0px);height:var(--d3c-mh,0px);border-radius:16px;background:var(--d3-fume-escuro);pointer-events:none}
body.mundo.mundo-centro.d3c-painel #mundo::before{z-index:-2}
body.mundo.mundo-centro.d3c-painel #mundo > :is(canvas,.mundo-rotulos){border-radius:16px}
body.mundo.mundo-centro.d3c-painel #mundo-hud > #d3-centro.d3m-f-mundo{position:absolute;z-index:3;top:var(--vv-m,14px);left:var(--vv-livre-esq,96px);right:var(--vv-m,14px);bottom:calc(var(--vv-dock-alto,74px) + 12px);display:flex;flex-direction:column;gap:0;height:auto;padding:16px;box-sizing:border-box;pointer-events:none;color:var(--d3-fume-texto)}
#d3-centro.d3m-f-mundo > .d3m-e-topo{padding-right:0}
/* No painel, a barra antiga do mapa e a fala do VYBES dão lugar ao título e ao cartão laranja (voltam no mapa cheio). */
body.mundo.mundo-centro.d3c-painel.d3c-painel.d3c-painel #mundo-hud > :is(.vv-legenda-cidade.v2m-barra,.v2m-fala.d3h-acao){display:none}

/* Corpo: as tiras e o mapa à esquerda; a consulta de 316 à direita. O toque no cartão passa para o 3D. */
#d3-centro.d3m-f-mundo > .d3m-f-corpo{flex:1 1 0;min-height:0;display:grid;grid-template-columns:minmax(0,1fr) 316px;grid-template-rows:72px minmax(0,1fr);gap:12px 16px;pointer-events:none}
#d3-centro.d3m-f-mundo .d3m-f-resto{display:contents}
#d3-centro.d3m-f-mundo .d3m-f-tiras{grid-column:1;grid-row:1;pointer-events:auto}
#d3-centro.d3m-f-mundo .d3m-f-cena{grid-column:1;grid-row:2;min-height:0;border-radius:16px;box-shadow:var(--d3-folha-sombra)}
#d3-centro.d3m-f-mundo .d3m-f-lado{grid-column:2;grid-row:1 / span 2;overflow-y:auto;scrollbar-width:thin;scrollbar-color:var(--d3-fume-borda) transparent;pointer-events:auto}
#d3-centro.d3m-f-mundo .d3m-f-elev[hidden]{display:none}
#d3-centro.d3m-f-mundo .d3m-f-entrar{position:absolute;left:12px;bottom:12px}
#d3-centro.d3m-f-mundo .d3m-f-loja > .d3m-vnome{flex:1 1 0;max-width:none}
#d3-centro.d3m-f-mundo .d3m-f-loja > .d3m-vbarra{flex:0 0 64px}
#d3-centro.d3m-f-mundo .d3m-f-loja > .d3m-vn{min-width:24px}
#d3-centro.d3m-f-mundo .d3m-f-loja .cliente-carteira{color:var(--d3-fume-texto)}

/* Os controles do mapa, dentro do cartão (canto de baixo à direita): pastilha escura com botões de 30. */
body.mundo.mundo-centro.d3c-painel:not(.mundo-andar) #mundo-hud > .vv-controles.vv-ilha{gap:4px;padding:4px;border-radius:var(--d3-r-caixa);background:var(--d3-fume-forte);box-shadow:none}
body.mundo.mundo-centro.d3c-painel:not(.mundo-andar) #mundo-hud > .vv-controles.vv-ilha > .vv-botao{width:30px;min-width:0;height:30px;padding:0;border-radius:7px;background:none;box-shadow:none;color:var(--d3-fume-texto)}
