.vv-tour-raiz .vt-texto{margin:0;max-width:64ch;font:400 var(--d3-fs-destaque)/1.5 var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-apagado)}
.vv-tour-raiz .vt-temas{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-top:24px}
.vv-tour-raiz .vt-tema{appearance:none;position:relative;display:flex;flex-direction:column;gap:12px;min-width:0;margin:0;padding:10px 10px 14px;border:0;border-radius:18px;background:var(--d3-fume-veu);color:var(--d3-fume-texto);text-align:left;cursor:pointer;transition:transform .35s cubic-bezier(.22,1,.36,1),background-color .25s,box-shadow .25s}
.vv-tour-raiz .vt-tema:hover{transform:translateY(-4px);background:var(--d3-fume-veu-forte)}
.vv-tour-raiz .vt-tema[aria-checked="true"]{background:var(--d3-fume-veu-forte);box-shadow:0 0 0 2px var(--d3-acao),0 24px 40px -28px rgba(0,0,0,.6)}
.vv-tour-raiz .vt-tema:focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:3px}
.vv-tour-raiz .vt-tema-pe{display:flex;flex-direction:column;gap:2px;padding:0 6px;min-width:0}
.vv-tour-raiz .vt-tema-pe > b{font:600 var(--d3-fs-destaque)/1.3 var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-texto)}
.vv-tour-raiz .vt-tema-pe > small{font:400 var(--d3-fs-apoio)/1.4 var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-apagado)}
.vv-tour-raiz .vt-tema-ok{display:none;position:absolute;right:18px;top:18px;width:22px;height:22px;border-radius:50%;background:var(--d3-acao);box-shadow:0 6px 14px -6px rgba(0,0,0,.6)}
.vv-tour-raiz .vt-tema-ok::after{content:"";position:absolute;left:8px;top:5px;width:5px;height:9px;border:solid var(--d3-escuro-texto);border-width:0 2px 2px 0;rotate:45deg}
.vv-tour-raiz .vt-tema[aria-checked="true"] > .vt-tema-ok{display:block}
.vv-tour-raiz .vt-pe{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-top:24px}
.vv-tour-raiz .vt-pe-esq{display:flex;flex-direction:column;gap:4px;min-width:0}
.vv-tour-raiz .vt-fala{margin:0;font:500 var(--d3-fs-destaque)/1.4 var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-texto)}
.vv-tour-raiz .vt-nota{font:400 var(--d3-fs-apoio)/1.4 var(--vv-texto,Inter,sans-serif);color:var(--d3-fume-apagado)}
.vv-tour-raiz .vt-pe-dir{flex:none;display:flex;align-items:center;gap:8px}
.vv-tour-raiz :is(.vt-auto,.vt-pular,.vt-principal){appearance:none;display:inline-flex;align-items:center;justify-content:center;height:40px;margin:0;padding:0 16px;border:0;border-radius:var(--d3-r-botao);background:var(--d3-fume-veu);color:var(--d3-fume-texto);font:500 var(--d3-fs-texto) var(--vv-texto,Inter,sans-serif);white-space:nowrap;cursor:pointer;transition:background-color .2s}
.vv-tour-raiz :is(.vt-auto,.vt-pular):hover{background:var(--d3-fume-veu-forte)}
.vv-tour-raiz .vt-auto[aria-checked="true"]{box-shadow:inset 0 0 0 2px var(--d3-acao)}
.vv-tour-raiz .vt-principal{padding:0 20px;background:var(--d3-fume-texto);color:var(--d3-fume-contra);font-weight:600}
.vv-tour-raiz :is(.vt-auto,.vt-pular,.vt-principal):focus-visible{outline:2px solid var(--d3-fume-texto);outline-offset:2px}

/* A prévia: o Hoje em miniatura, com as peças de verdade em escala (cqw = centésimo da largura da prévia). O tema vem do
   atributo da própria prévia, então as três aparecem lado a lado, cada uma no seu tema. */
.d3-previa{position:relative;display:block;width:100%;aspect-ratio:16/10;border-radius:12px;overflow:hidden;background:var(--d3-ambiente);box-shadow:inset 0 0 0 1px var(--d3-fume-borda);container-type:inline-size}
