.d3-previa .vp-topo{grid-column:1;display:flex;align-items:center;justify-content:space-between}
.d3-previa .vp-ola{display:flex;flex-direction:column;gap:.8cqw}
.d3-previa .vp-t1{width:19cqw;height:2.2cqw;border-radius:1cqw;background:var(--d3-fume-texto)}
.d3-previa .vp-t2{width:11cqw;height:1.2cqw;border-radius:.6cqw;background:var(--d3-fume-meta)}
.d3-previa .vp-abas{position:relative;display:flex;gap:.5cqw;padding:.5cqw;border-radius:1.2cqw;background:var(--d3-fume-veu)}
.d3-previa .vp-abas > i{width:5.4cqw;height:2.2cqw;border-radius:.8cqw}
.d3-previa .vp-abas > i.on{background:var(--d3-fume-texto)}
.d3-previa .vp-nums{grid-column:1;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1.3cqw}
.d3-previa .vp-num{position:relative;display:flex;flex-direction:column;gap:1cqw;height:10.4cqw;padding:1.4cqw;border-radius:1.8cqw;background:var(--d3-folha);box-shadow:var(--d3-folha-sombra)}
.d3-previa .vp-rot{width:62%;height:1.1cqw;border-radius:.6cqw;background:var(--d3-rotulo)}
.d3-previa .vp-num > b{font:700 4.2cqw/1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.02em;color:var(--d3-tinta);font-variant-numeric:tabular-nums}
.d3-previa .vp-num.r > b{color:var(--d3-perigo)}
.d3-previa .vp-num.g > b{color:var(--d3-pronto)}
.d3-previa .vp-barras{position:absolute;right:1.4cqw;bottom:1.4cqw;display:flex;align-items:flex-end;gap:.5cqw;height:4cqw}
.d3-previa .vp-barras > i{width:.9cqw;height:45%;border-radius:.45cqw;background:var(--d3-veu-forte);transform-origin:50% 100%}
