.d3-previa .vp-barras > i:nth-child(5){height:82%;background:var(--d3-info)}
.d3-previa .vp-num.r .vp-barras > i:nth-child(5){background:var(--d3-perigo)}
.d3-previa .vp-num.g .vp-barras > i:nth-child(5){background:var(--d3-pronto)}
.d3-previa .vp-meio{grid-column:1;display:grid;grid-template-columns:minmax(0,1.5fr) minmax(0,1fr);gap:1.3cqw;min-height:0}
.d3-previa .vp-folha{display:flex;flex-direction:column;gap:1.2cqw;min-height:0;padding:1.5cqw;border-radius:1.8cqw;background:var(--d3-folha);box-shadow:var(--d3-folha-sombra);overflow:hidden}
.d3-previa .vp-cab{flex:none;width:34%;height:1.5cqw;border-radius:.7cqw;background:var(--d3-tinta)}
.d3-previa .vp-lin{flex:none;display:flex;align-items:center;gap:1.1cqw}
.d3-previa .vp-foto{flex:none;width:2.8cqw;height:2.8cqw;border-radius:.9cqw;background:var(--d3-veu-forte)}
.d3-previa .vp-nome{flex:1 1 auto;height:1.2cqw;border-radius:.6cqw;background:var(--d3-veu-forte)}
.d3-previa .vp-st{flex:none;width:1.5cqw;height:1.5cqw;border-radius:50%;background:var(--d3-info)}
.d3-previa .vp-st.r{background:var(--d3-perigo)}
.d3-previa .vp-st.a{background:var(--d3-ajuste)}
.d3-previa .vp-st.g{background:var(--d3-pronto)}
.d3-previa .vp-laranja{position:relative;display:flex;flex-direction:column;gap:.9cqw;min-height:0;padding:1.6cqw;border-radius:1.8cqw;background:var(--d3-laranja);box-shadow:0 2.4cqw 4cqw -3cqw rgba(194,73,12,.85);overflow:hidden}
.d3-previa .vp-laranja::after{content:"";position:absolute;right:-5cqw;top:-6cqw;width:16cqw;height:16cqw;border-radius:50%;background:radial-gradient(closest-side,rgba(255,224,198,.5),rgba(255,224,198,0))}
.d3-previa .vp-lr{width:56%;height:1.1cqw;border-radius:.6cqw;background:rgba(255,255,255,.78)}
.d3-previa .vp-laranja > b{margin-top:auto;font:700 6.2cqw/1 var(--vv-titulo,"Inter Tight",Inter,sans-serif);letter-spacing:-.03em;color:var(--d3-escuro-texto)}
.d3-previa .vp-lf{width:88%;height:1.3cqw;border-radius:.6cqw;background:rgba(255,255,255,.92)}
.d3-previa .vp-lf.c{width:58%;background:rgba(255,255,255,.62)}
.d3-previa .vp-lbts{display:flex;gap:.8cqw;margin-top:.5cqw}
.d3-previa .vp-lbts > i{width:8cqw;height:2.6cqw;border-radius:.8cqw;background:rgba(255,255,255,.16);box-shadow:inset 0 0 0 1px rgba(255,255,255,.4)}
.d3-previa .vp-lbts > i.k{background:var(--d3-escuro-texto);box-shadow:none}
.d3-previa .vp-lado{grid-column:2;grid-row:1 / -1;display:flex;flex-direction:column;gap:1.2cqw;min-height:0}
.d3-previa .vp-mes{flex:none;height:15cqw;border-radius:1.8cqw;background:var(--d3-fume-escuro);box-shadow:inset 0 0 0 1px var(--d3-fume-borda)}
.d3-previa .vp-tira{flex:none;height:3.6cqw;border-radius:1.2cqw;background:var(--d3-fume-veu)}
.d3-previa .vp-voz{position:absolute;left:33cqw;bottom:2.8cqw;width:44cqw;height:6cqw;border-radius:2.2cqw;background:var(--d3-fume);box-shadow:inset 0 0 0 1px var(--d3-fume-borda);display:flex;align-items:center;justify-content:center;gap:2.2cqw}
.d3-previa .vp-voz > i{width:3cqw;height:3cqw;border-radius:1cqw;background:var(--d3-fume-veu-forte)}
.d3-previa .vp-voz > i.k{width:11cqw;background:var(--d3-fume-texto)}
/* A prévia ganha vida ao passar o mouse, ao chegar pelo teclado e na escolhida: as barras crescem, a fila entra, o número
   sobe, a aba troca e a luz do laranja respira. Nada começa do invisível (o repouso congela a animação no começo). */
@keyframes vpBarra{from{transform:scaleY(.3)}to{transform:scaleY(1)}}
@keyframes vpLinha{from{transform:translateX(-4cqw);opacity:.35}to{transform:none;opacity:1}}
@keyframes vpNumero{from{transform:translateY(1.6cqw);opacity:.35}to{transform:none;opacity:1}}
@keyframes vpAba{0%,30%{transform:translateX(0)}45%,78%{transform:translateX(5.9cqw)}93%,100%{transform:translateX(0)}}
@keyframes vpBrilho{0%,100%{transform:scale(1)}50%{transform:scale(1.3)}}
.vt-tema:is(:hover,:focus-visible,[aria-checked="true"]) .vp-barras > i{animation:vpBarra .7s cubic-bezier(.22,1,.36,1) both}
.vt-tema:is(:hover,:focus-visible,[aria-checked="true"]) .vp-barras > i:nth-child(2){animation-delay:.06s}
.vt-tema:is(:hover,:focus-visible,[aria-checked="true"]) .vp-barras > i:nth-child(3){animation-delay:.12s}
.vt-tema:is(:hover,:focus-visible,[aria-checked="true"]) .vp-barras > i:nth-child(4){animation-delay:.18s}
.vt-tema:is(:hover,:focus-visible,[aria-checked="true"]) .vp-barras > i:nth-child(5){animation-delay:.24s}
.vt-tema:is(:hover,:focus-visible,[aria-checked="true"]) .vp-lin{animation:vpLinha .55s cubic-bezier(.22,1,.36,1) both}
.vt-tema:is(:hover,:focus-visible,[aria-checked="true"]) .vp-lin:nth-child(3){animation-delay:.07s}
.vt-tema:is(:hover,:focus-visible,[aria-checked="true"]) .vp-lin:nth-child(4){animation-delay:.14s}
.vt-tema:is(:hover,:focus-visible,[aria-checked="true"]) .vp-lin:nth-child(5){animation-delay:.21s}
.vt-tema:is(:hover,:focus-visible,[aria-checked="true"]) :is(.vp-num > b,.vp-laranja > b){animation:vpNumero .6s cubic-bezier(.22,1,.36,1) both}
.vt-tema:is(:hover,:focus-visible,[aria-checked="true"]) .vp-abas > i.on{animation:vpAba 3.6s cubic-bezier(.4,0,.2,1) .4s infinite}
.vt-tema:is(:hover,:focus-visible,[aria-checked="true"]) .vp-laranja::after{animation:vpBrilho 3.2s ease-in-out infinite}
@media (prefers-reduced-motion:reduce){.vv-tour-raiz .vt-caixa,.d3-previa *,.d3-previa .vp-laranja::after{animation:none}.vv-tour-raiz .vt-tema{transition:none}}
.vv-tour-raiz.vv-tour-quieto :is(.vt-caixa,.d3-previa *){animation:none}
/* Telas baixas (1366 × 768, 1280 × 720): a janela aperta para caber sem rolar. */
@media (max-height:800px) and (min-width:761px){
  .vv-tour-raiz .vt-caixa{width:min(940px,100%);padding:24px}
  .vv-tour-raiz .vt-temas,.vv-tour-raiz .vt-pe{margin-top:16px}
  .vv-tour-raiz .vt-titulo{font-size:26px}
}
/* Celular (390 px): um cartão por linha, com a prévia à esquerda e o nome ao lado; os botões em duas linhas. */
@media (max-width:760px){
  .vv-tour-raiz .vt-bv{padding:12px;place-items:start center}
  .vv-tour-raiz .vt-caixa{padding:18px;border-radius:20px}
  .vv-tour-raiz .vt-cab{gap:12px}
  .vv-tour-raiz .vt-avatar{width:40px;height:40px}
  .vv-tour-raiz .vt-avatar > i{width:13px;height:13px}
  .vv-tour-raiz .vt-titulo{font-size:22px}
  .vv-tour-raiz .vt-texto{font-size:var(--d3-fs-texto)}
  .vv-tour-raiz .vt-temas{grid-template-columns:minmax(0,1fr);gap:10px;margin-top:16px}
  .vv-tour-raiz .vt-tema{flex-direction:row;align-items:center;gap:12px;padding:8px}
  .vv-tour-raiz .vt-tema:hover{transform:none}
  .vv-tour-raiz .vt-tema > .d3-previa{flex:none;width:136px}
  .vv-tour-raiz .vt-tema-pe{padding:0 28px 0 0}
  .vv-tour-raiz .vt-tema-ok{right:12px;top:12px}
  .vv-tour-raiz .vt-pe{flex-direction:column;align-items:stretch;gap:12px;margin-top:16px}
  .vv-tour-raiz .vt-pe-dir{flex-wrap:wrap}
  .vv-tour-raiz :is(.vt-auto,.vt-pular){flex:1 1 0;padding:0 10px}
  .vv-tour-raiz .vt-principal{flex:1 0 100%;height:44px}
}
